import type { WorldTargetRef } from '../world/WorldTarget';
import type { RadioSignalBand } from './RadioNetworkTypes';

export type RadioSignalDetail =
  | 'FULL'
  | 'REDUCED'
  | 'FRAGMENTED';

export interface RadioSignalPresentation {
  title: string;
  body: string;
  signalBand: RadioSignalBand;
  signalDetail: RadioSignalDetail;
  locationUncertaintyMetres?: number;
}

export const radioSignalBandRank = (
  band: RadioSignalBand,
): number => {
  switch (band) {
    case 'CLEAR':
      return 5;
    case 'GOOD':
      return 4;
    case 'WEAK':
      return 3;
    case 'FRAGMENTED':
      return 2;
    case 'CARRIER_ONLY':
      return 1;
    case 'NO_SIGNAL':
      return 0;
  }
};

const hasWorldPosition = (
  targetRefs: readonly WorldTargetRef[],
): boolean =>
  targetRefs.some(
    (target) => target.kind === 'WORLD_POSITION',
  );

export const presentRadioSignal = (
  title: string,
  body: string,
  targetRefs: readonly WorldTargetRef[],
  signalBand: RadioSignalBand,
): RadioSignalPresentation => {
  if (signalBand === 'CLEAR' || signalBand === 'GOOD') {
    return {
      title,
      body,
      signalBand,
      signalDetail: 'FULL',
    };
  }

  if (signalBand === 'WEAK') {
    return {
      title,
      body:
        `${body} Weak reception; position may be ` +
        'approximate.',
      signalBand,
      signalDetail: 'REDUCED',
      ...(hasWorldPosition(targetRefs)
        ? { locationUncertaintyMetres: 180 }
        : {}),
    };
  }

  const carrierOnly = signalBand === 'CARRIER_ONLY';
  return {
    title,
    body:
      `${body} ${
        carrierOnly
          ? 'Only a carrier and fragments were received.'
          : 'Reception is fragmented.'
      } Critical details are retained; move closer for ` +
      'a clearer position.',
    signalBand,
    signalDetail: 'FRAGMENTED',
    ...(hasWorldPosition(targetRefs)
      ? {
          locationUncertaintyMetres:
            carrierOnly ? 900 : 480,
        }
      : {}),
  };
};
