import type { UtilityComponentCondition } from './UtilityNetworkTypes';
import type { UtilityNetworkSystem } from './UtilityNetworkSystem';

export interface UtilityNetworkInspector {
  snapshot: () => ReturnType<UtilityNetworkSystem['snapshot']>;
  definitions: () => UtilityNetworkSystem['definitions'];
  trace: (subjectId?: string) => ReturnType<UtilityNetworkSystem['trace']>;
  explain: (subjectId: string) => unknown;
  forceComponentCondition: (
    componentId: string,
    condition: UtilityComponentCondition,
  ) => ReturnType<UtilityNetworkSystem['forceComponentCondition']>;
}

declare global {
  interface Window { __ICEWAY_UTILITIES__?: UtilityNetworkInspector; }
}

export const installUtilityNetworkInspector = (
  utilities: UtilityNetworkSystem,
): (() => void) => {
  const inspector: UtilityNetworkInspector = {
    snapshot: () => utilities.snapshot(),
    definitions: () => structuredClone(utilities.definitions),
    trace: (subjectId) => utilities.trace(subjectId),
    explain: (subjectId) => {
      const snapshot = utilities.snapshot();
      return snapshot.components.find((value) => value.componentId === subjectId) ??
        snapshot.connections.find((value) => value.connectionId === subjectId) ??
        snapshot.services.find((value) => value.serviceId === subjectId) ??
        snapshot.networks.find((value) => value.networkId === subjectId) ??
        { error: 'UNKNOWN_UTILITY_SUBJECT', subjectId };
    },
    forceComponentCondition: (componentId, condition) =>
      utilities.forceComponentCondition(componentId, condition),
  };
  window.__ICEWAY_UTILITIES__ = inspector;
  return () => {
    if (window.__ICEWAY_UTILITIES__ === inspector) delete window.__ICEWAY_UTILITIES__;
  };
};
