import { sampleWorldWindField } from '../../environment/WorldWindField';
import { clamp, smoothstep } from '../../utils/math';

export interface FirePoint { readonly x: number; readonly y: number; readonly z: number }
export interface FireWindContext {
  readonly windX: number; readonly windZ: number; readonly windStrength: number;
  readonly windBaseStrength?: number; readonly windGust?: number; readonly windTime?: number;
}
export interface FireAir {
  readonly roofed: boolean; readonly enclosure: number; readonly ventilation: number;
}

/** Same coordinates, clock and analytic field as vegetation. Shelter changes
 * exposure, not the weather itself; no camera/player-relative random gusts. */
export const sampleSurvivalFireWind = (
  context: FireWindContext, position: FirePoint, time: number, air?: FireAir,
) => {
  const field = sampleWorldWindField({
    timeSeconds: context.windTime ?? time, x: position.x, z: position.z,
    directionRadians: Math.atan2(context.windZ, context.windX),
    baseStrength: context.windBaseStrength ?? context.windStrength,
    forecastGust: context.windGust ?? 0.35,
  });
  const exposure = air?.roofed
    ? (1 - clamp(air.enclosure, 0, 1) * 0.96) *
      (0.25 + clamp(air.ventilation, 0, 1) * 0.75)
    : 1;
  return { ...field, strength: field.strength * exposure };
};

export const firePointToLocal = (
  point: FirePoint, origin: FirePoint, yawDegrees: number,
): FirePoint => {
  const yaw = yawDegrees * Math.PI / 180;
  const dx = point.x - origin.x; const dz = point.z - origin.z;
  return { x: dx * Math.cos(yaw) - dz * Math.sin(yaw), y: point.y - origin.y,
    z: dx * Math.sin(yaw) + dz * Math.cos(yaw) };
};

export const firePointToWorld = (
  point: FirePoint, origin: FirePoint, yawDegrees: number,
): FirePoint => {
  const yaw = yawDegrees * Math.PI / 180;
  return { x: origin.x + point.x * Math.cos(yaw) + point.z * Math.sin(yaw),
    y: origin.y + point.y,
    z: origin.z - point.x * Math.sin(yaw) + point.z * Math.cos(yaw) };
};

/** Metadata-sized surface patches, never per-triangle fire simulations. The
 * renderer can change independently of saved ignition and burn coverage. */
export interface SurvivalBurnPatch {
  readonly id: string;
  readonly centre: FirePoint;
  readonly halfWidth: number;
  readonly halfDepth: number;
}
export interface SurvivalBurnProfileInput {
  readonly kind: 'SURFACE' | 'WALL' | 'POST' | 'BEAM' | 'STAIRS' | 'ROOF_FRAME' | 'ROOF';
  readonly halfWidth: number; readonly halfDepth: number; readonly height: number;
  readonly surfaceY?: (z: number) => number;
  readonly assemblyStage?: number;
}

export const createSurvivalBurnProfile = (
  input: SurvivalBurnProfileInput,
): readonly SurvivalBurnPatch[] => {
  const { halfWidth: w, halfDepth: d, height: h, kind } = input;
  if (kind === 'ROOF_FRAME') {
    if ((input.assemblyStage ?? 4) === 1) return [-w + 0.07, w - 0.07].map((x, i) => ({
      id: `tie:${i}`, centre: { x, y: 0.1, z: 0 }, halfWidth: 0.12, halfDepth: d - 0.24,
    }));
    // Two rafter stations. Four tight volumes follow the sloping timbers at
    // each station; no enormous box of flame across the hollow attic.
    return [-w + 0.07, w - 0.07].flatMap((x, station) =>
      [-0.75, -0.25, 0.25, 0.75].filter((fraction) => fraction < 0 || (input.assemblyStage ?? 4) >= 3).map((fraction, index) => ({
        id: `rafter:${station}:${index}`,
        centre: { x, y: input.surfaceY?.(fraction * d) ?? h * (1 - Math.abs(fraction)), z: fraction * d },
        halfWidth: 0.12, halfDepth: Math.max(0.1, d * 0.27),
      })));
  }
  if (kind === 'POST') return [0.2, 0.65].map((fraction, i) => ({
    id: `post:${i}`, centre: { x: 0, y: h * fraction, z: 0 },
    halfWidth: Math.min(w, 0.22), halfDepth: Math.min(d, 0.22),
  }));
  const rows = kind === 'WALL' || kind === 'BEAM' ? 1 : 2;
  return Array.from({ length: rows * 2 }, (_, index) => {
    const x = (index % 2 === 0 ? -0.5 : 0.5) * w;
    const z = rows === 1 ? 0 : (index < 2 ? -0.5 : 0.5) * d;
    const y = kind === 'ROOF' ? input.surfaceY?.(z) ?? h
      : kind === 'STAIRS' ? h * (0.5 - z / Math.max(0.01, d * 2))
      : kind === 'WALL' ? h * 0.28 : h;
    return { id: `surface:${index}`, centre: { x, y, z },
      halfWidth: w * 0.53, halfDepth: d * (rows === 1 ? 1 : 0.53) };
  });
};

/** One continuous presentation volume per physical member, or two for a
 * legacy packet's two separated truss stations. Surface samples still drive
 * spread, but no longer allocate one ray-marched FireMesh per sample. */
export const coherentSurvivalFireVolumes = (profile: readonly SurvivalBurnPatch[], ignition: FirePoint, coverage:number) => {
  const groups = new Map<string, {minX:number;maxX:number;minY:number;maxY:number;minZ:number;maxZ:number;intensity:number}>();
  for(const patch of resolveSurvivalBurnPatches(profile,ignition,coverage)) {
    const key=patch.id.startsWith('rafter:')?`station:${patch.id.split(':')[1]}`:'body';
    const blend=1-patch.growth;
    const x=patch.centre.x+clamp(ignition.x-patch.centre.x,-patch.halfWidth,patch.halfWidth)*blend;
    const z=patch.centre.z+clamp(ignition.z-patch.centre.z,-patch.halfDepth,patch.halfDepth)*blend;
    const w=Math.max(.06,patch.halfWidth*(.15+patch.growth*.85));
    const d=Math.max(.06,patch.halfDepth*(.15+patch.growth*.85));
    const y=patch.centre.y;
    const current=groups.get(key);
    const next={minX:x-w,maxX:x+w,minY:y,maxY:y+.2+patch.growth*1.15,minZ:z-d,maxZ:z+d,intensity:patch.intensity};
    if(current) {
      current.minX=Math.min(current.minX,next.minX);current.maxX=Math.max(current.maxX,next.maxX);
      current.minY=Math.min(current.minY,next.minY);current.maxY=Math.max(current.maxY,next.maxY);
      current.minZ=Math.min(current.minZ,next.minZ);current.maxZ=Math.max(current.maxZ,next.maxZ);
      current.intensity=Math.max(current.intensity,next.intensity);
    } else groups.set(key,next);
  }
  return [...groups].map(([id,b])=>({id,centre:{x:(b.minX+b.maxX)/2,y:b.minY+(b.maxY-b.minY)*.34,z:(b.minZ+b.maxZ)/2},
    width:b.maxX-b.minX,height:b.maxY-b.minY,depth:b.maxZ-b.minZ,intensity:b.intensity}));
};

/** Progress starts at the actual contact side. Local coordinates survive
 * site rotation, save/load, prefab replacement and a moving/falling piece. */
export const resolveSurvivalBurnPatches = (
  profile: readonly SurvivalBurnPatch[], ignition: FirePoint, coverage: number,
): readonly (SurvivalBurnPatch & { readonly intensity: number; readonly growth: number })[] => {
  if (coverage <= 0 || profile.length === 0) return [];
  const distances = profile.map((patch) => Math.hypot(
    patch.centre.x - ignition.x, patch.centre.y - ignition.y, patch.centre.z - ignition.z,
  ));
  const minimum = Math.min(...distances);
  const firstIndex = distances.indexOf(minimum);
  const range = Math.max(0.01, Math.max(...distances) - minimum);
  return profile.flatMap((patch, index) => {
    const arrival = index === firstIndex ? 0 : Math.max(0.12, (distances[index]! - minimum) / range * 0.72);
    const growth = smoothstep(arrival, Math.min(1, arrival + 0.28), coverage);
    return growth <= 0.001 ? [] : [{ ...patch, growth, intensity: 0.15 + growth * 0.85 }];
  });
};
