import { clamp, lerp, smoothstep } from '../utils/math';

/** Shared local/server dimensions for a human forcing through hip-deep snow. */
export interface SnowWadeProfile {
  readonly trailRadius: number;
  readonly sideOffset: number;
  readonly sideRadius: number;
  readonly frontOffset: number;
  readonly frontRadius: number;
  readonly removalScale: number;
}

export const resolveSnowWadeProfile = (strength: number): SnowWadeProfile => {
  const wading = clamp(strength, 0, 1);
  const broad = smoothstep(0.18, 1, wading);
  return {
    // A 34-43 cm trough follows the actual pelvis of the 1.72 m actor. Snow
    // displaced beyond that width belongs to the two soft side lips, not to
    // an oversized invisible character capsule.
    trailRadius: lerp(0.17, 0.215, broad),
    sideOffset: lerp(0.25, 0.39, broad),
    sideRadius: lerp(0.14, 0.22, broad),
    frontOffset: lerp(0.24, 0.42, broad),
    frontRadius: lerp(0.14, 0.22, broad),
    removalScale: lerp(0.12, 0.42, broad),
  };
};
