export type IsolationFeature = typeof ISOLATION_FEATURES[number][0];
export type IsolationState = Record<IsolationFeature, boolean>;
/** A child can be enabled without its parent; that is not a meaningful A/B test. */
export const isolationPrerequisites: Partial<Record<IsolationFeature, IsolationFeature[]>> = {
  treeModels: ['trees'], treeSnow: ['trees', 'snow', 'assetSnow'], treeShadows: ['trees', 'shadows'],
  terrainNear: ['terrain'], terrainFar: ['terrain'], terrainCliffs: ['terrain'],
  terrainShading: ['terrain'], terrainShadowSampling: ['terrain', 'terrainShading', 'shadows'],
  terrainShadowCasting: ['terrain', 'shadows'],
  snowBase: ['snow'], snowDetail: ['snow'], snowMiddle: ['snow'], snowFar: ['snow', 'terrain', 'terrainFar'],
  assetSnow: ['snow'], snowShading: ['snow'], snowShadowSampling: ['snow', 'snowShading', 'shadows'],
  terrainCloudShadows: ['terrain', 'terrainShading', 'cloudShadows'],
  snowCloudShadows: ['snow', 'snowShading', 'cloudShadows'], grade: ['postprocessing'], bloom: ['postprocessing'],
};
export const defaultIsolationState = (): IsolationState => Object.fromEntries(
  ISOLATION_FEATURES.map(([id]) => [id, true]),
) as IsolationState;
export interface IsolationFrameSample {
  intervalMs: number; cpuMs: number; drawCalls: number; triangles: number;
}
export interface IsolationStageResult {
  stage: 'A1' | 'B' | 'A2'; frames: number; fps: number;
  medianFrameMs: number; p95FrameMs: number; meanCpuMs: number;
  meanDrawCalls: number; meanTriangles: number;
}
export interface IsolationResult {
  feature: IsolationFeature; baseline: IsolationState; stages: IsolationStageResult[];
  completed: boolean; reason: string; baselineDriftPercent: number | null;
  note: string;
}
type EventSink = (name: string, data: Record<string, unknown>) => void;
const quantile = (values: number[], p: number): number => {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * p))] ?? 0;
};
const summarize = (stage: IsolationStageResult['stage'], samples: IsolationFrameSample[]): IsolationStageResult => {
  const mean = (key: keyof IsolationFrameSample) => samples.reduce((sum, s) => sum + s[key], 0) / Math.max(1, samples.length);
  return { stage, frames: samples.length, fps: 1000 / Math.max(0.001, mean('intervalMs')),
    medianFrameMs: quantile(samples.map(s => s.intervalMs), 0.5), p95FrameMs: quantile(samples.map(s => s.intervalMs), 0.95),
    meanCpuMs: mean('cpuMs'), meanDrawCalls: mean('drawCalls'), meanTriangles: mean('triangles') };
};

export class PerformanceIsolation {
  private state = defaultIsolationState();
  private listeners = new Set<() => void>();
  public disabledFeatures = '';
  public readonly results: IsolationResult[] = [];
  private run?: {
    feature: IsolationFeature; original: IsolationState; stage: 0 | 1 | 2;
    startedAt: number; settleMs: number; measureMs: number;
    samples: IsolationFrameSample[]; stages: IsolationStageResult[];
  };
  public constructor(private readonly event: EventSink = () => {}) {}
  public enabled(id: IsolationFeature): boolean { return this.state[id]; }
  public blockedBy(id: IsolationFeature): IsolationFeature[] {
    return (isolationPrerequisites[id] ?? []).filter(parent => !this.enabled(parent));
  }
  // Every frame, not a 500 ms timer's arbitrary single-frame sample. Bounded,
  // allocation-free storage; sorting happens only when the visible UI polls.
  private readonly liveTimes = new Float64Array(512);
  private readonly liveIntervals = new Float64Array(512);
  private readonly liveCpu = new Float64Array(512);
  private liveCursor = 0;
  private liveCount = 0;
  public recordLiveFrame(intervalMs: number, cpuMs: number, now: number): void {
    if (!(intervalMs > 0) || !Number.isFinite(intervalMs) || !Number.isFinite(cpuMs)) return;
    const i = this.liveCursor;
    this.liveTimes[i] = now; this.liveIntervals[i] = intervalMs; this.liveCpu[i] = cpuMs;
    this.liveCursor = (i + 1) % this.liveTimes.length;
    this.liveCount = Math.min(this.liveCount + 1, this.liveTimes.length);
  }
  public liveMetrics(now = performance.now()): { fps: number; cpuMs: number; p95FrameMs: number; maxFrameMs: number; samples: number } {
    const intervals: number[] = []; let cpu = 0;
    for (let j = 0; j < this.liveCount; j++) {
      const i = (this.liveCursor - 1 - j + this.liveTimes.length) % this.liveTimes.length;
      if (now - this.liveTimes[i]! > 1000) break;
      intervals.push(this.liveIntervals[i]!); cpu += this.liveCpu[i]!;
    }
    const n = intervals.length;
    return { fps: n ? 1000 * n / intervals.reduce((sum, v) => sum + v, 0) : 0,
      cpuMs: n ? cpu / n : 0, p95FrameMs: quantile(intervals, 0.95),
      maxFrameMs: Math.max(0, ...intervals), samples: n };
  }
  public get active(): boolean { return this.disabledFeatures.length > 0; }
  public get running(): boolean { return !!this.run; }
  public get frozen(): boolean { return this.running || !this.state.simulation; }
  public snapshot(): IsolationState { return { ...this.state }; }
  public status(): string {
    return this.run ? `${['A1', 'B', 'A2'][this.run.stage]} · ${this.run.feature} · maailma pysäytetty` :
      this.active ? 'Eristys aktiivinen · ei tallennu peliin' : 'Normaali toteutus · ei eristyksiä';
  }
  public subscribe(listener: () => void): () => void { this.listeners.add(listener); return () => this.listeners.delete(listener); }
  private changed(name: string, data: Record<string, unknown> = {}): void {
    this.disabledFeatures = ISOLATION_FEATURES.filter(([id]) => !this.state[id]).map(([id]) => id).join(',');
    this.event(name, { ...data, state: this.snapshot(), frozen: this.frozen });
    for (const listener of this.listeners) listener();
  }
  public set(id: IsolationFeature, enabled: boolean): void {
    if (!ISOLATION_FEATURES.some(([key]) => key === id)) throw new Error('Unknown isolation feature');
    if (this.running) throw new Error('Cancel A/B/A before changing switches');
    if (this.state[id] === enabled) return;
    this.state[id] = enabled;
    this.changed('isolation-switch', { feature: id, enabled });
  }
  public reset(): void { this.cancel('reset'); this.state = defaultIsolationState(); this.changed('isolation-reset'); }
  public start(feature: IsolationFeature, now = performance.now(), options: { settleMs?: number; measureMs?: number } = {}): void {
    if (this.running) throw new Error('A/B/A is already running');
    if (!ISOLATION_FEATURES.some(([id, , kind]) => id === feature && kind === 'render')) throw new Error('A/B/A tests render switches only');
    if (!this.enabled(feature)) throw new Error('Enable the selected feature before A/B/A');
    const blocked = this.blockedBy(feature);
    if (blocked.length) throw new Error(`Ota ensin käyttöön: ${blocked.join(', ')}. Muuten A/B ei mittaa valittua osaa.`);
    const duration = (value: number | undefined, fallback: number) => Number.isFinite(value) ? Math.max(500, Math.min(30000, value!)) : fallback;
    this.run = { feature, original: this.snapshot(), stage: 0, startedAt: now,
      settleMs: duration(options.settleMs, 3000), measureMs: duration(options.measureMs, 8000), samples: [], stages: [] };
    this.changed('isolation-aba-start', { feature, settleMs: this.run.settleMs, measureMs: this.run.measureMs,
      note: 'Frozen render comparison. CPU is render-only, not full gameplay CPU. Frame intervals are not GPU times.' });
  }
  /** Call once per completed, visible frame, outside normal simulation. */
  public recordFrame(sample: IsolationFrameSample, now = performance.now()): void {
    const run = this.run;
    if (!run) return;
    const elapsed = now - run.startedAt;
    // Drop the transition frame too: its interval may straddle two configurations.
    if (elapsed - sample.intervalMs >= run.settleMs && sample.intervalMs > 0 && Number.isFinite(sample.intervalMs)) run.samples.push(sample);
    if (elapsed < run.settleMs + run.measureMs) return;
    run.stages.push(summarize((['A1', 'B', 'A2'] as const)[run.stage], run.samples));
    if (run.stage === 2) { this.finish(true, 'complete'); return; }
    run.stage = (run.stage + 1) as 1 | 2; run.startedAt = now; run.samples = [];
    this.state[run.feature] = run.stage !== 1;
    this.changed('isolation-aba-stage', { feature: run.feature, stage: ['A1', 'B', 'A2'][run.stage] });
  }
  public cancel(reason = 'cancelled'): void { if (this.run) this.finish(false, reason); }
  private finish(completed: boolean, reason: string): void {
    const run = this.run!;
    this.state = run.original; this.run = undefined;
    const a1 = run.stages[0]?.medianFrameMs; const a2 = run.stages[2]?.medianFrameMs;
    const result: IsolationResult = { feature: run.feature, baseline: { ...run.original }, stages: run.stages,
      completed, reason, baselineDriftPercent: a1 && a2 ? (a2 / a1 - 1) * 100 : null,
      note: 'Same frozen simulation/camera. Settling excluded. Render CPU only; frame ms != GPU ms. Check A1/A2 drift, inactive features, resolution and GPU diagnostics before drawing conclusions.' };
    this.results.push(result); if (this.results.length > 40) this.results.shift();
    this.changed('isolation-aba-result', { result });
  }
}
