import { ISOLATION_FEATURES, PerformanceIsolation, type IsolationFeature } from './PerformanceIsolation';
import type { RuntimePerformanceInspector } from './RuntimePerformanceTrace';

export interface IsolationInspector {
  show(): void; set(id: IsolationFeature, enabled: boolean): void; reset(): void;
  start(id: IsolationFeature): void; cancel(): void; snapshot(): object;
}
export const installPerformanceIsolationPanel = (
  isolation: PerformanceIsolation, capture: RuntimePerformanceInspector,
  canBenchmark: () => boolean,
  readMetrics: () => { fps: number; cpuMs: number; gpuMs: number; drawCalls: number; bufferWidth: number; bufferHeight: number; p95FrameMs: number; maxFrameMs: number; samples: number },
): { show: () => void; dispose: () => void } => {
  let panel: HTMLElement | undefined;
  let unsubscribe: (() => void) | undefined;
  let metricsTimer: ReturnType<typeof setInterval> | undefined;
  let live: HTMLElement | undefined;
  const startMetrics = () => {
    if (metricsTimer !== undefined) clearInterval(metricsTimer);
    const refresh = () => {
      if (!live) return;
      const m = readMetrics();
      live.textContent = `${m.fps.toFixed(1)} FPS (1 s) · CPU ${m.cpuMs.toFixed(1)} ms\nRuutuaika p95 ${m.p95FrameMs.toFixed(1)} / max ${m.maxFrameMs.toFixed(1)} ms\nGPU ${m.gpuMs >= 0 ? m.gpuMs.toFixed(1) : '—'} ms · ${m.drawCalls} draws · ${m.bufferWidth} × ${m.bufferHeight}${isolation.frozen ? '\nMaailma pysäytetty · CPU: render-only' : ''}`;
    };
    refresh(); metricsTimer = setInterval(refresh, 500);
  };
  const start = (id: IsolationFeature) => {
    if (!canBenchmark()) throw new Error('Aloita peli ja sulje editorit ennen mittausta.');
    if (document.hidden) throw new Error('Pidä pelivälilehti näkyvissä.');
    isolation.start(id);
  };
  const show = () => {
    if (panel) { panel.hidden = false; panel.style.display = 'flex'; startMetrics(); return; }
    panel = document.createElement('aside'); panel.id = 'iceway-performance-isolation';
    panel.setAttribute('aria-label', 'Performance isolation');
    panel.style.cssText = 'position:fixed;left:12px;top:76px;z-index:2147483646;width:min(450px,calc(100vw - 24px));max-height:calc(100dvh - 88px);display:flex;flex-direction:column;overflow:hidden;box-sizing:border-box;background:#172530f5;color:#eef4ee;border:1px solid #89a89e;border-radius:12px;padding:12px;font:13px/1.45 system-ui;box-shadow:0 5px 30px #0008;pointer-events:auto';
    const heading = document.createElement('strong'); heading.textContent = 'Performance isolation · TLW'; panel.append(heading);
    const status = document.createElement('p'); status.setAttribute('role', 'status'); status.style.cssText = 'margin:5px 0;flex-shrink:0'; panel.append(status);
    live = document.createElement('pre'); live.style.cssText = 'white-space:pre-wrap;font:12px/1.5 monospace;margin:6px 0;flex-shrink:0'; live.id = 'isolation-live-metrics'; panel.append(live);
    const buttons = document.createElement('div'); buttons.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;flex-shrink:0'; panel.append(buttons);
    const scroll = document.createElement('div'); scroll.id = 'isolation-scroll-list';
    scroll.style.cssText = 'overflow-y:auto;overscroll-behavior:contain;min-height:0;flex:1 1 auto;padding-right:5px;border-top:1px solid #789c91'; panel.append(scroll);
    const note = document.createElement('p'); note.textContent = 'Render-OFF ei pysäytä simulaatiota. Kaikki ON = normaali peli. Tasaväri ohittaa vain pinnan shadingin; maskit ja geometria säilyvät. Pilvivarjokenttä ei muuta sääsimulaatiota tai pilvien omaa valaisua. Harmaa teksti = pääkytkin estää testin.'; scroll.append(note);
    const button = (text: string, action: () => void, parent: HTMLElement = buttons) => {
      const el = document.createElement('button'); el.type = 'button'; el.textContent = text;
      el.style.cssText = 'font:inherit;background:#304d52;color:#fff;border:1px solid #789c91;border-radius:5px;padding:5px 8px;cursor:pointer';
      el.onclick = () => { try { action(); } catch (error) { status.textContent = String(error); } }; parent.append(el); return el;
    };
    button('Palauta kaikki', () => isolation.reset());
    button('Trace 30 s / tarkka 15 s', () => capture.show());
    button('Lataa trace', () => capture.download());
    button('Sulje', () => { if (panel) { panel.hidden = true; panel.style.display = 'none'; } if (metricsTimer !== undefined) clearInterval(metricsTimer); metricsTimer = undefined; });
    const selector = document.createElement('select'); selector.style.cssText = 'max-width:100%;padding:6px;font:inherit'; selector.setAttribute('aria-label', 'A/B/A feature');
    for (const [id, label, kind] of ISOLATION_FEATURES) if (kind === 'render') {
      const option = document.createElement('option'); option.value = id; option.textContent = label; selector.append(option);
    }
    selector.value = 'terrainShading'; scroll.append(selector);
    const runButton = button('A/B/A · 33 s', () => start(selector.value as IsolationFeature), scroll);
    button('Keskeytä', () => isolation.cancel(), buttons);
    const abaNote = document.createElement('p'); abaNote.textContent = 'A: nykyinen näkymä → B: valittu osa pois → A: palautus. 3 s tasaantuminen + 8 s mittaus / vaihe. Peli ja kamera pysähtyvät. CPU = vain piirtäminen tässä testissä. Esc keskeyttää. FPS ei ole GPU-ms. Valo- ja renderpolkukytkimet voivat kääntää uusia shadereita: odota niiden valmistumista ja toista vertailu.'; scroll.append(abaNote);
    const result = document.createElement('pre'); result.style.cssText = 'white-space:pre-wrap;font:12px/1.5 monospace'; result.id = 'isolation-results'; scroll.append(result);
    const controls: [IsolationFeature, HTMLInputElement][] = [];
    for (const kind of ['render', 'compute'] as const) {
      const title = document.createElement('h3'); title.textContent = kind === 'render' ? 'Piirtäminen' : 'Laskenta · käytä paikallaan'; scroll.append(title);
      for (const [id, text, group] of ISOLATION_FEATURES) {
        if (kind !== group) continue;
        const label = document.createElement('label'); label.style.cssText = 'display:flex;gap:9px;align-items:center;padding:5px;border-top:1px solid #ffffff18;cursor:pointer';
        const input = document.createElement('input'); input.type = 'checkbox'; input.dataset.isolation = id;
        input.onchange = () => isolation.set(id, input.checked); label.append(input, text); scroll.append(label); controls.push([id, input]);
      }
    }
    const refresh = () => {
      status.textContent = isolation.status();
      for (const [id, control] of controls) {
        control.checked = isolation.enabled(id); control.disabled = isolation.running;
        const blocked = isolation.blockedBy(id);
        control.parentElement!.style.opacity = blocked.length ? '0.55' : '1';
        control.parentElement!.title = blocked.length ? `Pääkytkin pois: ${blocked.join(', ')}` : '';
      }
      selector.disabled = isolation.running; runButton.disabled = isolation.running;
      const last = isolation.results.at(-1);
      result.textContent = last ? `${last.feature} · ${last.completed ? 'valmis' : last.reason}\n` +
        last.stages.map(s => `${s.stage} ${s.fps.toFixed(1)} FPS | frame p50 ${s.medianFrameMs.toFixed(1)} / p95 ${s.p95FrameMs.toFixed(1)} ms\n   render CPU ${s.meanCpuMs.toFixed(1)} ms | draws ${s.meanDrawCalls.toFixed(0)}`).join('\n') +
        `\nA1→A2 ero: ${last.baselineDriftPercent?.toFixed(1) ?? '—'} %. Yli 10 %: toista testi.\nTulokset sisältyvät trace-JSONiin.` : '';
    };
    unsubscribe = isolation.subscribe(refresh); refresh();
    // Do not let panel clicks, shortcuts or wheels reach gameplay handlers.
    for (const type of ['pointerdown', 'pointermove', 'pointerup', 'click', 'wheel', 'keydown', 'keyup']) panel.addEventListener(type, event => event.stopPropagation());
    document.body.append(panel);
    startMetrics();
  };
  const hidden = () => { if (document.hidden) isolation.cancel('page-hidden'); };
  const escape = (event: KeyboardEvent) => {
    if (event.code === 'Escape' && isolation.frozen) { event.preventDefault(); event.stopImmediatePropagation(); isolation.cancel('escape'); if (!isolation.enabled('simulation')) isolation.set('simulation', true); }
  };
  const blockFrozenInput = (event: Event) => {
    if (!isolation.frozen) return;
    const target = event.target;
    if (target instanceof Element && target.closest('#iceway-performance-isolation, #iceway-performance-capture-panel, #iceway-isolation-badge')) return;
    event.preventDefault(); event.stopImmediatePropagation();
  };
  const badge = document.createElement('button'); badge.id = 'iceway-isolation-badge'; badge.type = 'button';
  badge.style.cssText = 'position:fixed;left:12px;bottom:12px;max-width:calc(100vw - 24px);z-index:2147483645;background:#543b17;color:#fff;border:1px solid #efc779;border-radius:8px;padding:8px;font:13px system-ui';
  badge.onclick = show;
  const updateBadge = () => { badge.hidden = !isolation.active && !isolation.running; badge.textContent = `DIAGNOSTIIKKA · ${isolation.status()} · avaa`; };
  const removeBadgeListener = isolation.subscribe(updateBadge); updateBadge(); document.body.append(badge);
  const inspector: IsolationInspector = { show, set: (id, on) => isolation.set(id, on), reset: () => isolation.reset(), start,
    cancel: () => isolation.cancel(), snapshot: () => ({ state: isolation.snapshot(), running: isolation.running, results: isolation.results }) };
  const target = window as Window & { __ICEWAY_ISOLATION__?: IsolationInspector }; target.__ICEWAY_ISOLATION__ = inspector;
  document.addEventListener('visibilitychange', hidden); window.addEventListener('keydown', escape, true);
  const blockedEvents = ['keydown', 'keyup', 'pointerdown', 'pointermove', 'pointerup', 'mousedown', 'mousemove', 'mouseup', 'click', 'wheel'];
  for (const type of blockedEvents) window.addEventListener(type, blockFrozenInput, { capture: true, passive: false });
  return { show, dispose: () => { isolation.cancel('dispose'); if (metricsTimer !== undefined) clearInterval(metricsTimer); panel?.remove(); badge.remove(); unsubscribe?.(); removeBadgeListener(); document.removeEventListener('visibilitychange', hidden); window.removeEventListener('keydown', escape, true); for (const type of blockedEvents) window.removeEventListener(type, blockFrozenInput, true); if (target.__ICEWAY_ISOLATION__ === inspector) delete target.__ICEWAY_ISOLATION__; } };
};
