import { generateDeterministicWorld } from './DeterministicWorldGenerator';
import {
  DEFAULT_GENERATED_WORLD_SEED,
  generatedWorldConfig,
} from './GeneratedWorldConfig';
import {
  EMPTY_GENERATED_WORLD_SAMPLE,
  type GeneratedWorldData,
  type GeneratedWorldRuntimeStats,
  type GeneratedWorldSample,
} from './GeneratedWorldTypes';

let generatedWorld: GeneratedWorldData | undefined;
let enabled = true;

const configuredSeed = (): number => {
  if (typeof window === 'undefined') return DEFAULT_GENERATED_WORLD_SEED;
  const value = new URL(window.location.href).searchParams.get('worldSeed');
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.trunc(parsed) : DEFAULT_GENERATED_WORLD_SEED;
};

const worldgenEnabled = (): boolean => {
  if (typeof window === 'undefined') return true;
  const value = new URL(window.location.href).searchParams
    .get('worldgen')
    ?.trim()
    .toLowerCase();
  return value !== 'off' && value !== '0' && value !== 'legacy';
};

export const installGeneratedWorldData = (
  data: GeneratedWorldData | undefined,
): void => {
  generatedWorld = data;
};

export const generatedWorldData = (): GeneratedWorldData | undefined =>
  enabled ? generatedWorld : undefined;

export const isGeneratedWorldEnabled = (): boolean =>
  enabled && generatedWorld !== undefined;

export const setGeneratedWorldEnabled = (next: boolean): void => {
  enabled = next;
};

export const initializeGeneratedWorld = async (): Promise<GeneratedWorldData | undefined> => {
  enabled = worldgenEnabled();
  if (!enabled) {
    generatedWorld = undefined;
    return undefined;
  }
  const config = generatedWorldConfig(configuredSeed());
  if (typeof Worker === 'undefined') {
    generatedWorld = generateDeterministicWorld(config);
    return generatedWorld;
  }
  try {
    generatedWorld = await new Promise<GeneratedWorldData>((resolve, reject) => {
      const worker = new Worker(
        new URL('./GeneratedWorldWorker.ts', import.meta.url),
        { type: 'module', name: 'iceway-world-generator' },
      );
      const timeout = window.setTimeout(() => {
        worker.terminate();
        reject(new Error('World generator Worker timed out.'));
      }, 20_000);
      worker.onmessage = (event: MessageEvent<GeneratedWorldData>) => {
        window.clearTimeout(timeout);
        worker.terminate();
        resolve(event.data);
      };
      worker.onerror = (event) => {
        window.clearTimeout(timeout);
        worker.terminate();
        reject(event.error ?? new Error(event.message));
      };
      worker.postMessage(config);
    });
  } catch (error) {
    console.warn(
      'ICEWAY world generator Worker failed; generating once under the loading cover.',
      error,
    );
    generatedWorld = generateDeterministicWorld(config);
  }
  return generatedWorld;
};

const bilinear = (
  data: ArrayLike<number>,
  width: number,
  x: number,
  z: number,
): number => {
  const x0 = Math.floor(x);
  const z0 = Math.floor(z);
  const x1 = Math.min(width - 1, x0 + 1);
  const height = Math.floor(data.length / width);
  const z1 = Math.min(height - 1, z0 + 1);
  const tx = x - x0;
  const tz = z - z0;
  const near = (data[z0 * width + x0] ?? 0) * (1 - tx) +
    (data[z0 * width + x1] ?? 0) * tx;
  const far = (data[z1 * width + x0] ?? 0) * (1 - tx) +
    (data[z1 * width + x1] ?? 0) * tx;
  return near * (1 - tz) + far * tz;
};

export const sampleGeneratedWorld = (
  x: number,
  z: number,
): GeneratedWorldSample => {
  const data = generatedWorldData();
  if (!data || !Number.isFinite(x) || !Number.isFinite(z)) {
    return EMPTY_GENERATED_WORLD_SAMPLE;
  }
  const { bounds, cellSizeMetres } = data.config;
  if (x < bounds.minX || x > bounds.maxX || z < bounds.minZ || z > bounds.maxZ) {
    return EMPTY_GENERATED_WORLD_SAMPLE;
  }
  const gridX = Math.max(0, Math.min(data.width - 1, (x - bounds.minX) / cellSizeMetres));
  const gridZ = Math.max(0, Math.min(data.height - 1, (z - bounds.minZ) / cellSizeMetres));
  const normalizeMask = (mask: Uint8Array): number =>
    bilinear(mask, data.width, gridX, gridZ) / 255;
  const flowX = bilinear(data.flowDirectionX, data.width, gridX, gridZ);
  const flowZ = bilinear(data.flowDirectionZ, data.width, gridX, gridZ);
  const flowLength = Math.hypot(flowX, flowZ);
  const river = normalizeMask(data.river);
  const lake = normalizeMask(data.lake);
  return {
    inside: true,
    elevation: bilinear(data.elevation, data.width, gridX, gridZ),
    waterSurface: bilinear(data.waterSurface, data.width, gridX, gridZ),
    river,
    lake,
    water: Math.max(river, lake),
    flowAccumulation: bilinear(
      data.flowAccumulation,
      data.width,
      gridX,
      gridZ,
    ),
    flowDirectionX: flowLength > 0.0001 ? flowX / flowLength : 0,
    flowDirectionZ: flowLength > 0.0001 ? flowZ / flowLength : 0,
    moisture: normalizeMask(data.moisture),
    forest: normalizeMask(data.forest),
    rockiness: normalizeMask(data.rockiness),
    fuel: normalizeMask(data.fuel),
  };
};

export const generatedWorldStats = (): GeneratedWorldRuntimeStats => {
  const data = generatedWorldData();
  if (!data) {
    return {
      enabled: false,
      seed: configuredSeed(),
      width: 0,
      height: 0,
      cellSizeMetres: 0,
      generationMilliseconds: 0,
      riverCells: 0,
      lakeCells: 0,
    };
  }
  let riverCells = 0;
  let lakeCells = 0;
  for (let index = 0; index < data.elevation.length; index += 1) {
    if ((data.river[index] ?? 0) >= 32) riverCells += 1;
    if ((data.lake[index] ?? 0) >= 32) lakeCells += 1;
  }
  return {
    enabled: true,
    seed: data.config.seed,
    width: data.width,
    height: data.height,
    cellSizeMetres: data.config.cellSizeMetres,
    generationMilliseconds: data.generationMilliseconds,
    riverCells,
    lakeCells,
  };
};
