import type { SurvivalBuildPieceId } from '../SurvivalBuildingCatalog';

export type SurvivalRoofProfile = 'GABLE' | 'SHED' | 'MANSARD';
export const SURVIVAL_ROOF_ASSEMBLY_STEPS = ['Tie beams', 'First rafters', 'Other rafters', 'Bracing'] as const;
export const survivalRoofMemberStage = (role: string): number =>
  role.includes('tie-beam') ? 1 : role.includes('rafter-north') ? 2 : role.includes('rafter-south') ? 3 : 4;
export const normalizeSurvivalRoofProfile = (value?: string): SurvivalRoofProfile =>
  value === 'SHED' || value === 'MANSARD' ? value : 'GABLE';
export interface RoofProfileKnot { readonly z: number; readonly y: number }

export const survivalRoofProfileHeight = (knots: readonly RoofProfileKnot[], z: number): number => {
  if (z <= knots[0]!.z) return knots[0]!.y;
  for (let i = 1; i < knots.length; i += 1) {
    const left = knots[i - 1]!; const right = knots[i]!;
    if (z <= right.z) return left.y + (right.y - left.y) * (z - left.z) / (right.z - left.z);
  }
  return knots[knots.length - 1]!.y;
};

/**
 * Roof width is structural state, not an artist-authored mesh scale. One bay
 * is the ordinary two-metre Build V3 module and the visible rafter continues a
 * short, constant distance past each wall plate to form an eave.
 */
export const SURVIVAL_BUILD_V3_MIN_ROOF_SPAN_BAYS = 1;
// The first family is unreinforced timber. Six metres is the current safe
// endpoint-only playtest span; wider roofs need a centre support or a future
// reinforced/metal family rather than silently granting a 12 m timber truss.
export const SURVIVAL_BUILD_V3_MAX_ROOF_SPAN_BAYS = 3;
export const SURVIVAL_BUILD_V3_ROOF_EAVE_OVERHANG_METRES = 0.24;
export const SURVIVAL_BUILD_V3_ROOF_WALL_PLATE_Y_METRES = 0.1;

const ROOF_PITCH_BY_DEFINITION = new Map<SurvivalBuildPieceId, 30 | 45>([
  ['TIMBER_ROOF_FRAME_30', 30],
  ['TIMBER_ROOF_PANEL_30', 30],
  ['TIMBER_ROOF_GABLE_30', 30],
  ['TIMBER_ROOF_RIDGE_30', 30],
  ['TIMBER_ROOF_FRAME_45', 45],
  ['TIMBER_ROOF_PANEL_45', 45],
  ['TIMBER_ROOF_GABLE_45', 45],
  ['TIMBER_ROOF_RIDGE_45', 45],
]);

const ADJUSTABLE_ROOF_FRAMES = new Set<SurvivalBuildPieceId>([
  'TIMBER_ROOF_FRAME_30',
  'TIMBER_ROOF_FRAME_45',
]);

export interface SurvivalBuildV3RoofGeometry {
  readonly profile: SurvivalRoofProfile;
  readonly knots: readonly RoofProfileKnot[];
  readonly spanBays: number;
  readonly pitchDegrees: 30 | 45;
  /** Wall-plate to wall-plate width, excluding both eaves. */
  readonly structuralWidthMetres: number;
  readonly structuralHalfSpanMetres: number;
  /** Ridge-to-eave horizontal run, including one constant eave. */
  readonly rafterRunMetres: number;
  readonly rafterLengthMetres: number;
  readonly eaveYMetres: number;
  readonly ridgeYMetres: number;
  readonly rafterCentreYMetres: number;
  readonly rafterCentreOffsetMetres: number;
  readonly footprintHalfDepthMetres: number;
  readonly presentationHeightMetres: number;
}

export const survivalBuildV3RoofPitchDegrees = (
  definitionId: SurvivalBuildPieceId,
): 30 | 45 | undefined => ROOF_PITCH_BY_DEFINITION.get(definitionId);

export const isSurvivalBuildV3AdjustableRoofFrame = (
  definitionId: SurvivalBuildPieceId,
): boolean => ADJUSTABLE_ROOF_FRAMES.has(definitionId);

export const normalizeSurvivalBuildV3RoofSpanBays = (
  spanBays?: number,
): number => Math.max(
  SURVIVAL_BUILD_V3_MIN_ROOF_SPAN_BAYS,
  Math.min(
    SURVIVAL_BUILD_V3_MAX_ROOF_SPAN_BAYS,
    Math.round(spanBays ?? SURVIVAL_BUILD_V3_MIN_ROOF_SPAN_BAYS),
  ),
);

export const survivalBuildV3RoofGeometry = (
  definitionId: SurvivalBuildPieceId,
  spanBays = SURVIVAL_BUILD_V3_MIN_ROOF_SPAN_BAYS,
  moduleMetres = 2,
  requestedProfile: SurvivalRoofProfile = 'GABLE',
): SurvivalBuildV3RoofGeometry | undefined => {
  const pitchDegrees = survivalBuildV3RoofPitchDegrees(definitionId);
  if (!pitchDegrees) return undefined;
  const normalizedSpan = normalizeSurvivalBuildV3RoofSpanBays(spanBays);
  const structuralWidthMetres = normalizedSpan * moduleMetres;
  const structuralHalfSpanMetres = structuralWidthMetres * 0.5;
  const pitchRadians = pitchDegrees * Math.PI / 180;
  const pitchTangent = Math.tan(pitchRadians);
  const rafterRunMetres = structuralHalfSpanMetres +
    SURVIVAL_BUILD_V3_ROOF_EAVE_OVERHANG_METRES;
  const eaveYMetres = SURVIVAL_BUILD_V3_ROOF_WALL_PLATE_Y_METRES -
    SURVIVAL_BUILD_V3_ROOF_EAVE_OVERHANG_METRES * pitchTangent;
  let ridgeYMetres = SURVIVAL_BUILD_V3_ROOF_WALL_PLATE_Y_METRES +
    structuralHalfSpanMetres * pitchTangent;
  const profile = normalizeSurvivalRoofProfile(requestedProfile);
  let knots: RoofProfileKnot[] = [
    { z: -rafterRunMetres, y: eaveYMetres }, { z: 0, y: ridgeYMetres },
    { z: rafterRunMetres, y: eaveYMetres },
  ];
  if (profile === 'SHED') {
    ridgeYMetres = SURVIVAL_BUILD_V3_ROOF_WALL_PLATE_Y_METRES + structuralWidthMetres * pitchTangent;
    knots = [{ z: -rafterRunMetres, y: ridgeYMetres + SURVIVAL_BUILD_V3_ROOF_EAVE_OVERHANG_METRES * pitchTangent },
      { z: 0, y: (ridgeYMetres + SURVIVAL_BUILD_V3_ROOF_WALL_PLATE_Y_METRES) * 0.5 },
      { z: rafterRunMetres, y: eaveYMetres }];
  } else if (profile === 'MANSARD') {
    const kneeZ = structuralHalfSpanMetres * 0.55;
    const kneeY = SURVIVAL_BUILD_V3_ROOF_WALL_PLATE_Y_METRES + structuralHalfSpanMetres * 0.45 * Math.tan(Math.PI / 3);
    ridgeYMetres = kneeY + kneeZ * pitchTangent;
    const endY = SURVIVAL_BUILD_V3_ROOF_WALL_PLATE_Y_METRES - SURVIVAL_BUILD_V3_ROOF_EAVE_OVERHANG_METRES * Math.tan(Math.PI / 3);
    knots = [{ z: -rafterRunMetres, y: endY }, { z: -kneeZ, y: kneeY },
      { z: 0, y: ridgeYMetres }, { z: kneeZ, y: kneeY }, { z: rafterRunMetres, y: endY }];
  }
  return {
    profile, knots,
    spanBays: normalizedSpan,
    pitchDegrees,
    structuralWidthMetres,
    structuralHalfSpanMetres,
    rafterRunMetres,
    rafterLengthMetres: rafterRunMetres / Math.cos(pitchRadians),
    eaveYMetres,
    ridgeYMetres,
    rafterCentreYMetres: (eaveYMetres + ridgeYMetres) * 0.5,
    rafterCentreOffsetMetres: rafterRunMetres * 0.5,
    footprintHalfDepthMetres: rafterRunMetres,
    presentationHeightMetres: Math.max(...knots.map((point) => point.y)) + 0.14,
  };
};
