import { survivalBuildDefinition } from '../SurvivalBuildingCatalog';
import { survivalBuildV3AnchorLocalTransform, survivalBuildV3EdgeEndpoints,
  type SurvivalBuildV3Frame, type SurvivalBuildV3Piece } from './SurvivalBuildV3Model';
import { roofLerp, roofMemberKey, roofPointDistance,
  type ModularRoofKind, type ModularRoofMember, type RoofPoint } from './SurvivalModularRoof';
import { evaluateRoofFrame, RoofFrameSpatialIndex } from './SurvivalRoofFrame';
import { roofMemberPoints } from './SurvivalModularRoof';

interface Bearing { id: string; start: RoofPoint; end: RoofPoint; level: number }
const horizontal = (a: RoofPoint, b: RoofPoint) => Math.hypot(a.x-b.x, a.z-b.z);
const elevated = (p: RoofPoint, amount: number): RoofPoint => ({ ...p, y: p.y + amount });
const project = (p: RoofPoint, a: RoofPoint, b: RoofPoint): number =>
  ((p.x-a.x)*(b.x-a.x)+(p.z-a.z)*(b.z-a.z)) / Math.max(.001, horizontal(a,b)**2);
const bearing = (frame: SurvivalBuildV3Frame, p: SurvivalBuildV3Piece): Bearing | undefined => {
  if ((p.role !== 'WALL' && p.role !== 'BEAM') || p.anchor.kind !== 'EDGE') return undefined;
  const local = survivalBuildV3AnchorLocalTransform(frame, p.anchor, p.role);
  const y = local.y + survivalBuildDefinition(p.definitionId).height + .1;
  const ends = survivalBuildV3EdgeEndpoints(p.anchor.edge).map((n) => ({ x: n.u*frame.moduleMetres, y, z:n.v*frame.moduleMetres }));
  return { id:p.id, start:ends[0]!, end:ends[1]!, level:p.anchor.level+(p.role==='WALL'?1:0) };
};

const pointOnSegment = (p:RoofPoint,a:RoofPoint,b:RoofPoint,tolerance=.035):boolean => {
  const dx=b.x-a.x,dy=b.y-a.y,dz=b.z-a.z;
  const t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy+(p.z-a.z)*dz)/Math.max(.001,dx*dx+dy*dy+dz*dz)));
  return roofPointDistance(p,roofLerp(a,b,t))<=tolerance;
};

/** Exact physical compatibility also lets a shared wall-end socket survive
 * removal of one of its two adjacent walls. No dependency on a camera or on
 * the incidental ID of the wall that happened to be selected first. */
export const roofSupportedAtSocket = (frame:SurvivalBuildV3Frame,m:ModularRoofMember,slot:number,p:SurvivalBuildV3Piece):boolean => {
  const parent=p.roofMember;
  if(parent && parent.level!==m.level) return false;
  if(m.kind==='CROSS_BEAM' || m.kind==='RAFTER'&&slot===1) {
    const wall=bearing(frame,p);if(!wall || wall.level!==m.level) return false;
    if(m.kind==='CROSS_BEAM') return pointOnSegment(slot===0?m.start:m.end,wall.start,wall.end);
    const t=(wall.start.y-m.start.y)/(m.end.y-m.start.y);
    return t>=0 && t<=1 && pointOnSegment(roofLerp(m.start,m.end,t),wall.start,wall.end);
  }
  if(m.kind==='SPINE_BEAM' && parent?.kind==='CROSS_BEAM')
    return pointOnSegment(elevated(slot===0?m.start:m.end,-.2),parent.start,parent.end);
  if(m.kind==='RIDGE_POST' && (parent?.kind==='SPINE_BEAM'||parent?.kind==='CROSS_BEAM'))
    return pointOnSegment(elevated(m.start,-.1),parent.start,parent.end);
  if(m.kind==='RAFTER' && slot===0 && parent?.kind==='RIDGE_POST') return roofPointDistance(m.start,parent.end)<.035;
  if(m.kind==='COVER' && parent?.kind==='RAFTER') {
    const a=slot===0?m.start:m.farStart,b=slot===0?m.end:m.farEnd;
    return Boolean(a&&b&&roofPointDistance(elevated(a,-.1),parent.start)<.035&&roofPointDistance(elevated(b,-.1),parent.end)<.035);
  }
  return false;
};

/** Generate physical sockets in site space, independent of the camera. The
 * caller caches this list by topology/size and ranks it against the mouse ray.
 * A cross beam is ONE wall-to-wall timber; roof length is a sequence of
 * stations rather than a two-dimensional paint of complete gables. */
export const modularRoofCandidates = (frame: SurvivalBuildV3Frame,
  pieces: readonly SurvivalBuildV3Piece[], kind: ModularRoofKind,
  options: { length?: number; postHeight: number; rafterExtra: number; halfGrid: boolean },
): readonly ModularRoofMember[] => {
  const result: ModularRoofMember[] = [];
  const walls = pieces.flatMap((p) => { const b=bearing(frame,p); return b ? [b] : []; });
  const roofs = pieces.filter((p) => p.roofMember);
  if (kind === 'CROSS_BEAM') {
    for (const a of walls) for (const t of options.halfGrid ? [0, .5, 1] : [0,1]) {
      const start = roofLerp(a.start,a.end,t);
      for (const b of walls) {
        if (a.id === b.id || a.level !== b.level) continue;
        const u = project(start,b.start,b.end);
        if (u < -.001 || u > 1.001) continue;
        const end = roofLerp(b.start,b.end,Math.max(0,Math.min(1,u)));
        const length = horizontal(start,end);
        if (length < 1.9 || length > 8.05 || Math.abs(end.y-start.y) > .15) continue;
        const dot = (end.x-start.x)*(a.end.x-a.start.x)+(end.z-start.z)*(a.end.z-a.start.z);
        if (Math.abs(dot) > .02) continue;
        if (options.length !== undefined && Math.abs(length-options.length) > .26) continue;
        result.push({kind,start,end,level:a.level,supports:[a.id,b.id]});
      }
    }
  } else if (kind === 'SPINE_BEAM') {
    const cross = roofs.filter((p) => p.roofMember!.kind === 'CROSS_BEAM');
    for (const a of cross) for (const b of cross) {
      if (a.id >= b.id) continue;
      const m=a.roofMember!, n=b.roofMember!;
      if (m.level !== n.level) continue;
      const width = horizontal(m.start,m.end);
      // The one-metre centre lane is deliberately available in a 2m bay,
      // including a 3m centre line in a six-metre-wide house.
      for(let offset=0;offset<=width+.01;offset+=frame.moduleMetres/2) {
        const start = elevated(roofLerp(m.start,m.end,offset/width),.2);
        const u=project(start,n.start,n.end);
        if(u<-.001 || u>1.001) continue;
        const end=elevated(roofLerp(n.start,n.end,Math.max(0,Math.min(1,u))),.2);
        const length=horizontal(start,end);
        const dot=(end.x-start.x)*(m.end.x-m.start.x)+(end.z-start.z)*(m.end.z-m.start.z);
        if(length<.9 || length>2.05 || Math.abs(dot)>.02 || Math.abs(end.y-start.y)>.05) continue;
        result.push({kind,start,end,level:m.level,supports:[a.id,b.id]});
      }
    }
  } else if (kind === 'RIDGE_POST') {
    for(const p of roofs) {
      const m=p.roofMember!;
      if(m.kind!=='SPINE_BEAM' && m.kind!=='CROSS_BEAM') continue;
      if(m.kind==='CROSS_BEAM' && roofs.some((q)=>q.roofMember?.kind==='SPINE_BEAM')) continue;
      const length=horizontal(m.start,m.end);
      const step=options.halfGrid || m.kind==='CROSS_BEAM' ? frame.moduleMetres/2 : frame.moduleMetres;
      const distances=Array.from({length:Math.floor(length/step)+1},(_,i)=>i*step);
      if(Math.abs(distances[distances.length-1]!-length)>.01) distances.push(length);
      for(const offset of distances) {
        const start=elevated(roofLerp(m.start,m.end,offset/length),.1);
        result.push({kind,start,end:elevated(start,options.postHeight),level:m.level,supports:[p.id]});
      }
    }
  } else if (kind === 'RAFTER') {
    for(const p of roofs) {
      const m=p.roofMember!; if(m.kind!=='RIDGE_POST') continue;
      const parent=roofs.find((q)=>q.id===m.supports[0])?.roofMember; if(!parent) continue;
      const dx=parent.end.x-parent.start.x, dz=parent.end.z-parent.start.z;
      const run=parent.kind==='SPINE_BEAM' ? {x:-dz,z:dx} : {x:dx,z:dz};
      for(const wall of walls) {
        if(wall.level!==m.level) continue;
        const t=project(m.end,wall.start,wall.end);
        if(t<-.001 || t>1.001) continue;
        const foot=roofLerp(wall.start,wall.end,Math.max(0,Math.min(1,t)));
        const width=horizontal(m.end,foot);
        if(width<.45 || width>4.05 || foot.y>=m.end.y-.15) continue;
        if(Math.abs((foot.x-m.end.x)*run.z-(foot.z-m.end.z)*run.x)>.03) continue;
        const extension=.24+options.rafterExtra;
        const end=roofLerp(m.end,foot,1+extension/width);
        result.push({kind,start:m.end,end,level:m.level,supports:[p.id,wall.id]});
      }
    }
  } else {
    const rafters=roofs.filter((p)=>p.roofMember!.kind==='RAFTER');
    for(const a of rafters) for(const b of rafters) {
      if(a.id>=b.id) continue;
      const m=a.roofMember!, n=b.roofMember!;
      if(m.level!==n.level) continue;
      const along={x:m.end.x-m.start.x,z:m.end.z-m.start.z};
      const d={x:n.start.x-m.start.x,z:n.start.z-m.start.z};
      const separation=Math.hypot(d.x,d.z);
      if(separation<.45 || separation>2.05 || Math.abs(d.x*along.x+d.z*along.z)>.05) continue;
      if(Math.abs(m.start.y-n.start.y)>.05 || Math.abs(m.end.y-n.end.y)>.05 ||
        Math.abs((n.end.x-m.end.x)-d.x)>.05 || Math.abs((n.end.z-m.end.z)-d.z)>.05) continue;
      result.push({kind,start:elevated(m.start,.1),end:elevated(m.end,.1),
        farStart:elevated(n.start,.1),farEnd:elevated(n.end,.1),level:m.level,supports:[a.id,b.id]});
    }
  }
  return [...new Map(result.map((m)=>[roofMemberKey(m),m])).values()];
};

/** A replaced wall/beam receives a new piece ID. Reconnect only missing
 * parents at the SAME physical sockets, allowing repairs during the collapse
 * grace period. This runs on commits, not hover or simulation frames. */
export const repairModularRoofSupports = (frame: SurvivalBuildV3Frame,
  pieces: readonly SurvivalBuildV3Piece[]): readonly SurvivalBuildV3Piece[] => {
  const present=new Set(pieces.map((p)=>p.id));
  let changed=false;
  const cache=new Map<string,readonly ModularRoofMember[]>();
  const spatial=pieces.some(p=>p.roofMember?.rules===2)?new RoofFrameSpatialIndex(frame,pieces):undefined;
  const repaired=pieces.map((p)=>{
    const member=p.roofMember;
    if(member?.rules===2) {
      if(member.kind==='COVER'||member.kind==='GABLE') {
        if(!member.coverSupports)return p;
        const supports=member.coverSupports.map((socket,i)=>pieces.find(q=>q.roofMember?.kind===socket.kind&&
          ((roofPointDistance(q.roofMember.start,socket.start)<.035&&roofPointDistance(q.roofMember.end,socket.end)<.035)||
           (roofPointDistance(q.roofMember.start,socket.end)<.035&&roofPointDistance(q.roofMember.end,socket.start)<.035)))?.id??member.supports[i]!);
        if(supports.every((id,i)=>id===member.supports[i]))return p;
        changed=true;return {...p,revision:p.revision+1,roofMember:{...member,supports}};
      }
      const supports=evaluateRoofFrame(frame,member,spatial!.near(roofMemberPoints(member)).filter(q=>q.id!==p.id)).supports;
      if([...supports].sort().join('/')=== [...member.supports].sort().join('/')) return p;
      changed=true;
      return {...p,revision:p.revision+1,roofMember:{...member,supports}};
    }
    if(!member || member.supports.every((id)=>present.has(id))) return p;
    const height=member.kind==='RIDGE_POST'?member.end.y-member.start.y:1.5;
    const key=`${member.kind}:${height}`;
    let candidates=cache.get(key);
    if(!candidates) {candidates=modularRoofCandidates(frame,pieces,member.kind,{postHeight:height,rafterExtra:0,halfGrid:true});cache.set(key,candidates);}
    const match=candidates.find((m)=>roofMemberKey(m)===roofMemberKey(member));
    if(!match) return p;
    changed=true;
    return {...p,revision:p.revision+1,roofMember:{...member,supports:match.supports}};
  });
  return changed?repaired:pieces;
};
