import {
  BoxGeometry,
  BufferGeometry,
  ConeGeometry,
  Float32BufferAttribute,
  Group,
  InstancedMesh,
  Matrix4,
  Mesh,
  MeshBasicMaterial,
  PlaneGeometry,
  Quaternion,
  RingGeometry,
  SphereGeometry,
  Vector3,
  type Scene,
} from 'three';
import { clamp } from '../utils/math';

export type LandGuidanceMarkerKind =
  | 'AVAILABLE'
  | 'TURN_IN'
  | 'OBJECTIVE';

export interface LandQuestGuidanceView {
  readonly actorX: number;
  readonly actorZ: number;
  readonly targetX: number;
  readonly targetZ: number;
  readonly targetRadius?: number;
  readonly markerKind?: LandGuidanceMarkerKind;
  readonly showMarker?: boolean;
}

export interface ShovelTargetView {
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly hasSnow: boolean;
}

const MAX_ROUTE_ARROWS = 28;

/**
 * One inexpensive, reusable world-space guidance layer. Quest selection stays
 * in gameplay data; this presenter only draws the current destination and the
 * exact footprint of a held field tool.
 */
export class LandGuidancePresenter {
  private readonly root = new Group();
  private readonly questRoot = new Group();
  private readonly markerRoot = new Group();
  private readonly shovelRoot = new Group();
  private readonly routeMaterial = new MeshBasicMaterial({
    color: 0x62e9c4,
    transparent: true,
    opacity: 0.8,
    depthWrite: false,
    depthTest: false,
  });
  private readonly targetMaterial = new MeshBasicMaterial({
    color: 0x62e9c4,
    transparent: true,
    opacity: 0.72,
    side: 2,
    depthWrite: false,
    depthTest: false,
  });
  private readonly markerMaterial = new MeshBasicMaterial({
    color: 0xffcf67,
    transparent: true,
    opacity: 0.96,
    depthWrite: false,
    depthTest: false,
  });
  private readonly shovelFillMaterial = new MeshBasicMaterial({
    color: 0x55efa3,
    transparent: true,
    opacity: 0.18,
    side: 2,
    depthWrite: false,
    depthTest: false,
  });
  private readonly shovelEdgeMaterial = new MeshBasicMaterial({
    color: 0x73ffb5,
    transparent: true,
    opacity: 0.92,
    depthWrite: false,
    depthTest: false,
  });
  private readonly route: InstancedMesh;
  private readonly targetRing: Mesh;
  private readonly markerStem: Mesh;
  private readonly markerDot: Mesh;
  private readonly markerPointer: Mesh;
  private readonly shovelFill: Mesh;
  private readonly geometries: BufferGeometry[] = [];
  private readonly matrix = new Matrix4();
  private readonly quaternion = new Quaternion();
  private readonly scale = new Vector3(1, 1, 1);
  private readonly position = new Vector3();
  private visible = false;

  public constructor(
    scene: Scene,
    private readonly sampleSurfaceHeight: (x: number, z: number) => number,
  ) {
    this.root.name = 'Land quest and field-tool guidance';
    this.questRoot.name = 'Active quest world guidance';
    this.shovelRoot.name = 'Snow shovel footprint preview';

    const arrowGeometry = new BufferGeometry();
    arrowGeometry.setAttribute('position', new Float32BufferAttribute([
      -0.23, 0, -0.28,
      0.23, 0, -0.28,
      0, 0, 0.38,
    ], 3));
    arrowGeometry.setIndex([0, 1, 2]);
    arrowGeometry.computeVertexNormals();
    this.geometries.push(arrowGeometry);
    this.route = new InstancedMesh(
      arrowGeometry,
      this.routeMaterial,
      MAX_ROUTE_ARROWS,
    );
    this.route.name = 'Quest direction arrows';
    this.route.count = 0;
    this.route.frustumCulled = false;
    this.route.renderOrder = 42;

    const ringGeometry = new RingGeometry(0.86, 1, 48);
    this.geometries.push(ringGeometry);
    this.targetRing = new Mesh(ringGeometry, this.targetMaterial);
    this.targetRing.name = 'Quest destination area';
    this.targetRing.rotation.x = -Math.PI / 2;
    this.targetRing.renderOrder = 41;

    const markerStemGeometry = new BoxGeometry(0.16, 0.58, 0.14);
    const markerDotGeometry = new SphereGeometry(0.12, 10, 8);
    const markerPointerGeometry = new ConeGeometry(0.16, 0.28, 4);
    this.geometries.push(
      markerStemGeometry,
      markerDotGeometry,
      markerPointerGeometry,
    );
    this.markerStem = new Mesh(markerStemGeometry, this.markerMaterial);
    this.markerStem.position.y = 0.37;
    this.markerDot = new Mesh(markerDotGeometry, this.markerMaterial);
    this.markerDot.position.y = -0.02;
    this.markerPointer = new Mesh(markerPointerGeometry, this.markerMaterial);
    this.markerPointer.rotation.z = Math.PI;
    this.markerPointer.position.y = -0.42;
    this.markerRoot.name = 'NPC quest exclamation marker';
    this.markerRoot.add(this.markerStem, this.markerDot, this.markerPointer);
    this.markerRoot.traverse((object) => { object.renderOrder = 45; });

    const shovelPlaneGeometry = new PlaneGeometry(1.34, 1.34);
    const shovelEdgeHorizontalGeometry = new BoxGeometry(1.42, 0.025, 0.045);
    const shovelEdgeVerticalGeometry = new BoxGeometry(0.045, 0.025, 1.42);
    this.geometries.push(
      shovelPlaneGeometry,
      shovelEdgeHorizontalGeometry,
      shovelEdgeVerticalGeometry,
    );
    this.shovelFill = new Mesh(shovelPlaneGeometry, this.shovelFillMaterial);
    this.shovelFill.rotation.x = -Math.PI / 2;
    this.shovelFill.renderOrder = 44;
    this.shovelRoot.add(this.shovelFill);
    for (const z of [-0.71, 0.71]) {
      const edge = new Mesh(
        shovelEdgeHorizontalGeometry,
        this.shovelEdgeMaterial,
      );
      edge.position.z = z;
      edge.renderOrder = 45;
      this.shovelRoot.add(edge);
    }
    for (const x of [-0.71, 0.71]) {
      const edge = new Mesh(
        shovelEdgeVerticalGeometry,
        this.shovelEdgeMaterial,
      );
      edge.position.x = x;
      edge.renderOrder = 45;
      this.shovelRoot.add(edge);
    }

    this.questRoot.add(this.route, this.targetRing, this.markerRoot);
    this.root.add(this.questRoot, this.shovelRoot);
    this.root.visible = false;
    this.questRoot.visible = false;
    this.shovelRoot.visible = false;
    scene.add(this.root);
  }

  public setVisible(visible: boolean): void {
    this.visible = visible;
    this.root.visible = visible;
  }

  public updateQuest(
    elapsedSeconds: number,
    view?: Readonly<LandQuestGuidanceView>,
  ): void {
    this.questRoot.visible = this.visible && Boolean(view);
    if (!view) return;
    const dx = view.targetX - view.actorX;
    const dz = view.targetZ - view.actorZ;
    const distance = Math.hypot(dx, dz);
    const directionX = distance > 0.001 ? dx / distance : 0;
    const directionZ = distance > 0.001 ? dz / distance : 1;
    const routeLength = Math.min(distance - 1.25, 48);
    const spacing = distance < 10 ? 1.45 : 2.05;
    const count = clamp(
      Math.floor(Math.max(0, routeLength - 1.1) / spacing),
      0,
      MAX_ROUTE_ARROWS,
    );
    const heading = Math.atan2(directionX, directionZ);
    this.quaternion.setFromAxisAngle(new Vector3(0, 1, 0), heading);
    for (let index = 0; index < count; index += 1) {
      const along = Math.min(
        routeLength,
        1.2 + (index + 1) * spacing,
      );
      const x = view.actorX + directionX * along;
      const z = view.actorZ + directionZ * along;
      const bob = Math.sin(elapsedSeconds * 3.3 - index * 0.58) * 0.025;
      this.position.set(x, this.sampleSurfaceHeight(x, z) + 0.09 + bob, z);
      const pulse = 0.88 + Math.sin(elapsedSeconds * 3.3 - index * 0.58) * 0.1;
      this.scale.set(pulse, pulse, pulse);
      this.matrix.compose(this.position, this.quaternion, this.scale);
      this.route.setMatrixAt(index, this.matrix);
    }
    this.route.count = count;
    this.route.instanceMatrix.needsUpdate = true;
    this.routeMaterial.opacity = 0.68 + Math.sin(elapsedSeconds * 2.2) * 0.1;

    const groundY = this.sampleSurfaceHeight(view.targetX, view.targetZ);
    const radius = clamp(view.targetRadius ?? 1.6, 0.65, 8);
    const ringPulse = 1 + Math.sin(elapsedSeconds * 2.7) * 0.08;
    this.targetRing.position.set(view.targetX, groundY + 0.075, view.targetZ);
    this.targetRing.scale.setScalar(radius * ringPulse);
    this.targetMaterial.opacity = 0.5 + Math.sin(elapsedSeconds * 2.7) * 0.15;

    this.markerRoot.visible = view.showMarker ?? false;
    if (this.markerRoot.visible) {
      const color = view.markerKind === 'TURN_IN'
        ? 0x65f0a8
        : view.markerKind === 'OBJECTIVE'
          ? 0x69cfff
          : 0xffcf67;
      this.markerMaterial.color.setHex(color);
      const markerBob = Math.sin(elapsedSeconds * 3.1) * 0.12;
      this.markerRoot.position.set(
        view.targetX,
        groundY + 2.2 + markerBob,
        view.targetZ,
      );
      const markerPulse = 1 + Math.sin(elapsedSeconds * 3.1) * 0.045;
      this.markerRoot.scale.setScalar(markerPulse);
    }
  }

  public updateShovel(
    elapsedSeconds: number,
    view?: Readonly<ShovelTargetView>,
  ): void {
    this.shovelRoot.visible = this.visible && Boolean(view);
    if (!view) return;
    const surfaceY = this.sampleSurfaceHeight(view.x, view.z);
    this.shovelRoot.position.set(view.x, surfaceY + 0.07, view.z);
    this.shovelRoot.rotation.y = view.heading;
    const pulse = 0.92 + Math.sin(elapsedSeconds * 4.2) * 0.08;
    this.shovelFillMaterial.opacity = view.hasSnow
      ? 0.17 + pulse * 0.05
      : 0.08;
    this.shovelEdgeMaterial.opacity = view.hasSnow ? 0.94 : 0.44;
    this.shovelFillMaterial.color.setHex(view.hasSnow ? 0x55efa3 : 0xa4b9b2);
    this.shovelEdgeMaterial.color.setHex(view.hasSnow ? 0x73ffb5 : 0xa4b9b2);
  }

  public dispose(): void {
    this.geometries.forEach((geometry) => geometry.dispose());
    this.routeMaterial.dispose();
    this.targetMaterial.dispose();
    this.markerMaterial.dispose();
    this.shovelFillMaterial.dispose();
    this.shovelEdgeMaterial.dispose();
    this.root.removeFromParent();
  }
}
