import { BufferGeometry, DefaultLoadingManager, Float32BufferAttribute, Group, InstancedBufferAttribute, InstancedMesh, Matrix4, Mesh, MeshStandardMaterial, type Material, type WebGLRenderer } from 'three';
import { constructionInstanceAppearance } from './ConstructionInstanceAppearance';

/** Streamed snow may have no attached meshes yet. Compile its real shared
 * materials on non-rendered representatives, without creating/mutating snow.
 * Three's compile traverses invisible meshes; its renderer does not. */
export function createMaterialWarmupRoot(materials: readonly Material[], instancedMaterials: readonly Material[] = []): { root: Group; dispose: () => void } {
  const root = new Group(); root.name = 'Startup-only streamed material representatives'; root.visible = false;
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new Float32BufferAttribute([0, 0, 0], 3));
  geometry.setAttribute('normal', new Float32BufferAttribute([0, 1, 0], 3));
  geometry.setAttribute('color', new Float32BufferAttribute([1, 1, 1], 3));
  geometry.setAttribute('uv', new Float32BufferAttribute([0, 0], 2));
  geometry.setAttribute('aBuildEmission', new InstancedBufferAttribute(new Float32Array(3), 3));
  for (const material of materials) root.add(new Mesh(geometry, material));
  const instances = instancedMaterials.map(material => {
    const mesh=new InstancedMesh(geometry,material,1);mesh.setMatrixAt(0,new Matrix4());
    mesh.castShadow=true;mesh.receiveShadow=true;root.add(mesh);
    const original=new Mesh(geometry,material);original.castShadow=true;original.receiveShadow=true;root.add(original);
    return mesh;
  });
  const effects = instancedMaterials.filter((m): m is MeshStandardMaterial => m instanceof MeshStandardMaterial).map(source => {
    const material=constructionInstanceAppearance(source), mesh=new InstancedMesh(geometry,material,1);
    mesh.instanceColor=new InstancedBufferAttribute(new Float32Array([1,1,1]),3);
    mesh.setMatrixAt(0,new Matrix4());mesh.castShadow=true;mesh.receiveShadow=true;root.add(mesh);return mesh;
  });
  return { root, dispose() { root.removeFromParent();for(const mesh of instances)mesh.dispose();
    for(const mesh of effects){mesh.dispose();mesh.material.dispose();}geometry.dispose(); } };
}

export const yieldWarmup = (): Promise<void> => new Promise(resolve => setTimeout(resolve, 16));

/** Unlike compileAsync in r175, this does not dereference a material that never
 * received currentProgram. Poll the actual submitted programs, yielding to UI.
 */
export async function waitForShaderPrograms(renderer: WebGLRenderer, timeoutMs = 60000): Promise<void> {
  const started = performance.now();
  while (true) {
    if (renderer.getContext().isContextLost()) throw new Error('WebGL context lost during shader warmup');
    const pending = (renderer.info.programs ?? []).some(program => {
      const ready = (program as unknown as { isReady?: () => boolean }).isReady;
      return ready ? !ready.call(program) : false;
    });
    if (!pending) return;
    if (performance.now() - started > timeoutMs) throw new Error('Shader warmup timed out');
    await yieldWarmup();
  }
}

// deviceMemory is a coarse RAM hint, NOT a VRAM measurement. Unknown desktop
// hardware takes the moderate path; no extra textures/render targets are made.
export const startupLightTiers = (deviceMemory?: number): readonly number[] =>
  deviceMemory !== undefined && deviceMemory <= 4 ? [0, 1, 2, 4, 8] : [0, 1, 2, 4, 8, 16, 24, 32];

/** Install before Game creates loaders. A quiet window also catches deferred
 * GLTF/FBX imports and textures spawned by a model's completion callback.
 */
export function trackStartupAssetLoads(): { wait: () => Promise<boolean>; dispose: () => void } {
  let pending = 0, changedAt = performance.now();
  const manager = DefaultLoadingManager;
  const start = manager.itemStart, end = manager.itemEnd;
  const wrappedStart = (url: string): void => { pending++; changedAt = performance.now(); start.call(manager, url); };
  const wrappedEnd = (url: string): void => { pending = Math.max(0, pending - 1); changedAt = performance.now(); end.call(manager, url); };
  manager.itemStart = wrappedStart; manager.itemEnd = wrappedEnd;
  return {
    async wait() {
      const deadline = performance.now() + 60000;
      while (pending > 0 || performance.now() - changedAt < 1000) {
        if (performance.now() >= deadline) return false;
        await yieldWarmup();
      }
      return true;
    },
    dispose() {
      if (manager.itemStart === wrappedStart) manager.itemStart = start;
      if (manager.itemEnd === wrappedEnd) manager.itemEnd = end;
    },
  };
}
