export interface LocalInfluenceBounds {
  readonly minX: number;
  readonly maxX: number;
  readonly minZ: number;
  readonly maxZ: number;
}

interface LocalWorldInfluenceBase {
  readonly id: string;
  readonly ownerId: string;
  readonly revision: number;
  readonly bounds: LocalInfluenceBounds;
}

export interface ThermalSourceDescriptor extends LocalWorldInfluenceBase {
  readonly kind: 'THERMAL_SOURCE';
  readonly x: number;
  readonly y: number;
  readonly z: number;
  /** Normalized useful output. One is a healthy open campfire. */
  readonly heatOutput: number;
  readonly radiantRadius: number;
  readonly convectiveRadius: number;
  readonly fuelLimited: boolean;
}

export interface ThermalBarrierDescriptor extends LocalWorldInfluenceBase {
  readonly kind: 'THERMAL_BARRIER';
  readonly startX: number;
  readonly startZ: number;
  readonly endX: number;
  readonly endZ: number;
  readonly bottomY: number;
  readonly topY: number;
  readonly insulation: number;
  readonly windPermeability: number;
  readonly precipitationPermeability: number;
  readonly material:
    | 'BRANCH'
    | 'BARK'
    | 'HIDE'
    | 'LOG'
    | 'STONE'
    | 'PLANK'
    | 'METAL';
}

export interface ThreatWardDescriptor extends LocalWorldInfluenceBase {
  readonly kind: 'THREAT_WARD';
  readonly x: number;
  readonly z: number;
  readonly radius: number;
  readonly strength: number;
  readonly charge: number;
}

export type LocalWorldInfluence =
  | ThermalSourceDescriptor
  | ThermalBarrierDescriptor
  | ThreatWardDescriptor;

const finite = (value: number): boolean => Number.isFinite(value);

export const isValidLocalWorldInfluence = (
  influence: Readonly<LocalWorldInfluence>,
): boolean => {
  if (
    !influence.id || !influence.ownerId ||
    !Number.isSafeInteger(influence.revision) || influence.revision < 0 ||
    !finite(influence.bounds.minX) || !finite(influence.bounds.maxX) ||
    !finite(influence.bounds.minZ) || !finite(influence.bounds.maxZ) ||
    influence.bounds.minX > influence.bounds.maxX ||
    influence.bounds.minZ > influence.bounds.maxZ
  ) return false;
  if (influence.kind === 'THERMAL_SOURCE') {
    return finite(influence.x) && finite(influence.y) && finite(influence.z) &&
      finite(influence.heatOutput) && influence.heatOutput >= 0 &&
      finite(influence.radiantRadius) && influence.radiantRadius > 0 &&
      finite(influence.convectiveRadius) && influence.convectiveRadius > 0;
  }
  if (influence.kind === 'THERMAL_BARRIER') {
    return finite(influence.startX) && finite(influence.startZ) &&
      finite(influence.endX) && finite(influence.endZ) &&
      finite(influence.bottomY) && finite(influence.topY) &&
      influence.topY > influence.bottomY &&
      influence.insulation >= 0 && influence.insulation <= 1 &&
      influence.windPermeability >= 0 && influence.windPermeability <= 1 &&
      influence.precipitationPermeability >= 0 &&
      influence.precipitationPermeability <= 1;
  }
  return finite(influence.x) && finite(influence.z) &&
    finite(influence.radius) && influence.radius > 0 &&
    finite(influence.strength) && influence.strength >= 0 &&
    finite(influence.charge) && influence.charge >= 0;
};

/**
 * Small revision-aware authority for local effects. Presentation systems read
 * typed snapshots; they never scan scene objects or infer gameplay from mesh
 * names. Synchronization is deterministic and rejects stale revisions.
 */
export class LocalWorldInfluenceRegistry {
  private readonly byId = new Map<string, Readonly<LocalWorldInfluence>>();
  private registryRevision = 0;
  private barrierRevision = 0;
  private sources: readonly Readonly<ThermalSourceDescriptor>[] = [];
  private barriers: readonly Readonly<ThermalBarrierDescriptor>[] = [];

  public synchronize(
    influences: readonly Readonly<LocalWorldInfluence>[],
  ): boolean {
    const incomingIds = new Set<string>();
    let changed = false;
    let barriersChanged = false;
    for (const influence of influences) {
      if (!isValidLocalWorldInfluence(influence)) continue;
      incomingIds.add(influence.id);
      const previous = this.byId.get(influence.id);
      if (previous && previous.revision > influence.revision) continue;
      if (previous === influence) continue;
      if (
        previous && previous.revision === influence.revision &&
        JSON.stringify(previous) === JSON.stringify(influence)
      ) continue;
      this.byId.set(influence.id, Object.freeze({ ...influence }));
      if (influence.kind === 'THERMAL_BARRIER' || previous?.kind === 'THERMAL_BARRIER') {
        // A paint/fire revision is not necessarily a new wall footprint.
        barriersChanged ||= !previous || JSON.stringify({ ...previous, revision: 0 }) !==
          JSON.stringify({ ...influence, revision: 0 });
      }
      changed = true;
    }
    for (const id of [...this.byId.keys()]) {
      if (incomingIds.has(id)) continue;
      barriersChanged ||= this.byId.get(id)?.kind === 'THERMAL_BARRIER';
      this.byId.delete(id);
      changed = true;
    }
    if (changed) {
      this.registryRevision += 1;
      this.sources = [...this.byId.values()].filter(
        (value): value is ThermalSourceDescriptor => value.kind === 'THERMAL_SOURCE',
      );
      if (barriersChanged) {
        this.barrierRevision += 1;
        this.barriers = [...this.byId.values()].filter(
          (value): value is ThermalBarrierDescriptor => value.kind === 'THERMAL_BARRIER',
        );
      }
    }
    return changed;
  }

  public getRevision(): number {
    return this.registryRevision;
  }

  public thermalSources(): readonly Readonly<ThermalSourceDescriptor>[] {
    return this.sources;
  }

  public thermalBarriers(): readonly Readonly<ThermalBarrierDescriptor>[] {
    return this.barriers;
  }

  public getBarrierRevision(): number {
    return this.barrierRevision;
  }

  public wards(): readonly Readonly<ThreatWardDescriptor>[] {
    return [...this.byId.values()].filter(
      (candidate): candidate is ThreatWardDescriptor =>
        candidate.kind === 'THREAT_WARD',
    );
  }
}
