import type {
  SurvivalBuildFireFuelProfileId,
  SurvivalBuildPieceId,
} from '../SurvivalBuildingCatalog';
import type { SurvivalHearthRecipeId } from '../SurvivalHearthRecipeCatalog';
import type { WildernessInventory } from '../WildernessSurvivalSimulation';
import type { WildernessRuneId } from '../WildernessRuneCatalog';
import type {
  SurvivalBuildV3AnchorAddress,
  SurvivalBuildV3SaveData,
} from './SurvivalBuildV3Model';

export type SurvivalBuildPaintId =
  | 'NATURAL'
  | 'FROST_BLUE'
  | 'MOSS_GREEN'
  | 'EMBER_RED'
  | 'BIRCH_PALE';

/** Canonical persistent state for one authored/runtime construction piece. */
export interface SurvivalPlacedBuildPiece {
  readonly id: string;
  readonly definitionId: SurvivalBuildPieceId;
  readonly prefabId: string;
  x: number;
  y: number;
  z: number;
  yawDegrees: number;
  paintId: SurvivalBuildPaintId;
  mirrored?: boolean;
  grounded: boolean;
  boundRuneId?: WildernessRuneId;
  fire?: {
    fuelProfileId: SurvivalBuildFireFuelProfileId;
    remainingSeconds: number;
    lit: boolean;
    storedHeat?: number;
  };
  combustion?: {
    exposureSeconds: number;
    burningSeconds: number;
    durationSeconds: number;
    charred: number;
    coverage?: number;
    /** Actual contact, in the owning piece's local coordinates. */
    ignitionX?: number;
    ignitionY?: number;
    ignitionZ?: number;
    collapseWarningSeconds?: number;
  };
  station?: {
    work?: {
      recipeId: SurvivalHearthRecipeId;
      remainingSeconds: number;
      durationSeconds: number;
    };
    storage?: Partial<Record<keyof WildernessInventory, number>>;
  };
  surfaceSnowLoad?: number;
  /** Physical V4 roof load, metres; independent of cosmetic snow coverage. */
  roofSnowDepthMetres?: number;
  roofOverloadSeconds?: number;
  /** Absent in old saves means open, preserving the original window aperture. */
  windowClosed?: boolean;
  /** Free-standing furniture remembers the real floor, not the terrain below it. */
  surfaceSupport?: { y: number; pieceIds: readonly string[] };
  readonly structural?: Readonly<{
    authorityPieceId: string;
    siteId: string;
    anchor: SurvivalBuildV3AnchorAddress;
  }>;
  readonly connection?: Readonly<{
    targetPieceId: string;
    targetSocketId: string;
    sourceSocketId: string;
  }>;
  revision: number;
}

export interface SurvivalHeldRecoveredBuildPart {
  readonly roofMember?: import('./SurvivalModularRoof').ModularRoofMember;
  readonly definitionId: SurvivalBuildPieceId;
  readonly paintId: SurvivalBuildPaintId;
  readonly mirrored: boolean;
  readonly fire?: SurvivalPlacedBuildPiece['fire'];
  readonly roof?: Readonly<{ spanBays: number; profile: import('./SurvivalBuildV3Roof').SurvivalRoofProfile; assemblyStage: number }>;
  reusableSeconds?: number;
}

export interface SurvivalRecoveredBuildPart extends SurvivalHeldRecoveredBuildPart {
  readonly id: string;
  x: number;
  y: number;
  z: number;
  yawDegrees: number;
  reusableSeconds: number;
  generic: boolean;
}

export interface SurvivalBurnedBuildDebris {
  readonly roofMember?: import('./SurvivalModularRoof').ModularRoofMember;
  readonly id: string;
  readonly definitionId: SurvivalBuildPieceId;
  readonly prefabId: string;
  readonly roof?: SurvivalHeldRecoveredBuildPart['roof'];
  x: number;
  y: number;
  z: number;
  yawDegrees: number;
  pitchDegrees: number;
  rollDegrees: number;
  heat: number;
  impactMeltDepth: number;
}

export interface SurvivalConstructionSnowHeatSource {
  readonly id: string;
  readonly x: number;
  readonly z: number;
  readonly radius: number;
  readonly heat: number;
  readonly impactMeltDepth: number;
}

export interface SurvivalConstructionSaveData {
  readonly version: 1 | 2;
  readonly pieces: readonly SurvivalPlacedBuildPiece[];
  readonly structure?: SurvivalBuildV3SaveData;
  readonly selectedDefinitionId?: SurvivalBuildPieceId;
  readonly selectedPaintId?: SurvivalBuildPaintId;
  readonly structuralLevel?: number;
  readonly recoveredParts?: readonly SurvivalRecoveredBuildPart[];
  readonly burnedDebris?: readonly SurvivalBurnedBuildDebris[];
  readonly heldRecoveredPart?: SurvivalHeldRecoveredBuildPart;
}

/** Build-state copy helpers live outside the renderer/runtime lifecycle. */
export const cloneBuildStationState = (
  station: Readonly<NonNullable<SurvivalPlacedBuildPiece['station']>> | undefined,
): SurvivalPlacedBuildPiece['station'] => station
  ? {
      work: station.work ? { ...station.work } : undefined,
      storage: station.storage ? { ...station.storage } : undefined,
    }
  : undefined;

export const cloneSurvivalPlacedBuildPiece = (
  piece: Readonly<SurvivalPlacedBuildPiece>,
): SurvivalPlacedBuildPiece => ({
  ...piece,
  fire: piece.fire ? { ...piece.fire } : undefined,
  combustion: piece.combustion ? { ...piece.combustion } : undefined,
  station: cloneBuildStationState(piece.station),
  surfaceSupport: piece.surfaceSupport ? { ...piece.surfaceSupport, pieceIds: [...piece.surfaceSupport.pieceIds] } : undefined,
  connection: piece.connection ? { ...piece.connection } : undefined,
  structural: piece.structural
    ? { ...piece.structural, anchor: structuredClone(piece.structural.anchor) }
    : undefined,
});

export const cloneSurvivalHeldRecoveredBuildPart = (
  source: Readonly<SurvivalHeldRecoveredBuildPart>,
): SurvivalHeldRecoveredBuildPart => ({
  definitionId: source.definitionId,
  paintId: source.paintId,
  mirrored: source.mirrored,
  fire: source.fire ? { ...source.fire } : undefined,
  roof: source.roof ? { ...source.roof } : undefined,
  roofMember: source.roofMember ? structuredClone(source.roofMember) : undefined,
  reusableSeconds: source.reusableSeconds,
});

export const cloneSurvivalRecoveredBuildPart = (
  part: Readonly<SurvivalRecoveredBuildPart>,
): SurvivalRecoveredBuildPart => ({
  ...part,
  roofMember: part.roofMember ? structuredClone(part.roofMember) : undefined,
  fire: part.fire ? { ...part.fire } : undefined,
});

export const cloneSurvivalBurnedBuildDebris = (
  debris: Readonly<SurvivalBurnedBuildDebris>,
): SurvivalBurnedBuildDebris => ({ ...debris, roofMember: debris.roofMember ? structuredClone(debris.roofMember) : undefined });
