  public constructor(
    scene: Scene,
    oceanField: OceanField = new OceanField(),
    options: Readonly<IceGridSystemOptions> = {},
  ) {
    this.oceanField = oceanField;
    this.portIceMode =
      options.portIceMode ?? 'frozen-clearance';
    this.portDefinitions =
      options.ports ?? V1_GAMEPLAY_DEFINITIONS.ports;
    this.buildPortClearanceMasks();
    this.opennessTexture = new DataTexture(
      this.opennessTextureData,
      this.columns,
      this.rows,
      RedFormat,
      UnsignedByteType,
    );
    this.opennessTexture.minFilter = LinearFilter;
    this.opennessTexture.magFilter = LinearFilter;
    this.opennessTexture.wrapS = ClampToEdgeWrapping;
    this.opennessTexture.wrapT = ClampToEdgeWrapping;
    this.opennessTexture.generateMipmaps = false;
    this.opennessTexture.needsUpdate = true;
    this.coverageTexture = new DataTexture(
      this.coverageTextureData,
      this.columns,
      this.rows,
      RGBAFormat,
      UnsignedByteType,
    );
    this.coverageTexture.minFilter = LinearFilter;
    this.coverageTexture.magFilter = LinearFilter;
    this.coverageTexture.wrapS = ClampToEdgeWrapping;
    this.coverageTexture.wrapT = ClampToEdgeWrapping;
    this.coverageTexture.generateMipmaps = false;
    this.coverageTexture.needsUpdate = true;
    this.lifecycleTexture = new DataTexture(
      this.lifecycleTextureData,
      this.columns,
      this.rows,
      RGBAFormat,
      UnsignedByteType,
    );
    this.lifecycleTexture.minFilter = LinearFilter;
    this.lifecycleTexture.magFilter = LinearFilter;
    this.lifecycleTexture.wrapS = ClampToEdgeWrapping;
    this.lifecycleTexture.wrapT = ClampToEdgeWrapping;
    this.lifecycleTexture.generateMipmaps = false;
    this.lifecycleTexture.needsUpdate = true;

    const geometry = new CircleGeometry(
      WORLD.cellSize * 0.5,
      7,
    );
    geometry.rotateX(-Math.PI * 0.5);
    const material = new MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.72,
      metalness: 0.02,
      vertexColors: true,
      transparent: true,
      depthWrite: false,
      alphaTest: 0.025,
    });
    material.onBeforeCompile = (shader) => {
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'attribute float instanceOpacity;',
            'attribute float instanceSnow;',
            'attribute float instanceGloss;',
            'attribute float instanceRoughness;',
            'varying float vInstanceOpacity;',
            'varying float vInstanceSnow;',
            'varying float vInstanceGloss;',
            'varying float vInstanceRoughness;',
          ].join('\n'),
        )
        .replace(
          '#include <begin_vertex>',
          [
            '#include <begin_vertex>',
            'vInstanceOpacity = instanceOpacity;',
            'vInstanceSnow = instanceSnow;',
            'vInstanceGloss = instanceGloss;',
            'vInstanceRoughness = instanceRoughness;',
          ].join('\n'),
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'varying float vInstanceOpacity;',
            'varying float vInstanceSnow;',
            'varying float vInstanceGloss;',
            'varying float vInstanceRoughness;',
          ].join('\n'),
        )
        .replace(
          'vec4 diffuseColor = vec4( diffuse, opacity );',
          [
            'vec4 diffuseColor = vec4(diffuse, opacity * vInstanceOpacity);',
            'diffuseColor.rgb = mix(',
            '  diffuseColor.rgb,',
            '  vec3(0.96, 0.985, 1.0),',
            '  vInstanceSnow * 0.86',
            ');',
            'diffuseColor.rgb = mix(',
            '  diffuseColor.rgb,',
            '  vec3(0.48, 0.78, 0.82),',
            '  0.42',
            ');',
          ].join('\n'),
        )
        .replace(
          '#include <roughnessmap_fragment>',
          [
            '#include <roughnessmap_fragment>',
            'roughnessFactor = mix(',
            '  vInstanceRoughness,',
            '  0.34,',
            '  vInstanceGloss',
            ');',
            'roughnessFactor = mix(',
            '  roughnessFactor,',
            '  0.98,',
            '  vInstanceSnow * 0.72',
            ');',
          ].join('\n'),
        );
    };
    material.customProgramCacheKey = () => 'ice-patch-gloss-v4';
    this.instanceOpacity = new InstancedBufferAttribute(
      new Float32Array(this.count),
      1,
    );
    geometry.setAttribute('instanceOpacity', this.instanceOpacity);
    this.instanceSnow = new InstancedBufferAttribute(
      new Float32Array(this.count),
      1,
    );
    geometry.setAttribute('instanceSnow', this.instanceSnow);
    this.instanceGloss = new InstancedBufferAttribute(
      new Float32Array(this.count),
      1,
    );
    geometry.setAttribute('instanceGloss', this.instanceGloss);
    this.instanceRoughness = new InstancedBufferAttribute(
      new Float32Array(this.count),
      1,
    );
    geometry.setAttribute(
      'instanceRoughness',
      this.instanceRoughness,
    );

    this.mesh = new InstancedMesh(geometry, material, this.count);
    this.mesh.name = 'Ice field';
    this.mesh.instanceMatrix.setUsage(DynamicDrawUsage);
    this.mesh.castShadow = false;
    this.mesh.receiveShadow = true;
    this.mesh.frustumCulled = true;
    scene.add(this.mesh);
    this.detachedFloeRenderer = new DetachedFloeRenderer(
      scene,
      this.columns,
      this.rows,
      this.iceVisualProfile,
    );
    const surfaceChunkRows = Math.ceil(
      this.rows / ICE_DIRTY_CHUNK_SIZE,
    );
    for (
      let chunkRow = 0;
      chunkRow < surfaceChunkRows;
      chunkRow += 1
    ) {
      for (
        let chunkColumn = 0;
        chunkColumn < this.dirtyChunkColumns;
        chunkColumn += 1
      ) {
        this.iceSurfaceChunks.push(
          new IceSurfaceChunkRenderer(
            scene,
            chunkColumn,
            chunkRow,
            this.columns,
            this.rows,
            ICE_DIRTY_CHUNK_SIZE,
            this.iceVisualProfile,
          ),
        );
      }
    }

    this.generateField();
    this.seedOpenWaterAreas();
    this.seedHistoricalChannels();
    if (this.portIceMode === 'legacy-safe-spots') {
      this.seedPortBasinsOpen();
      this.seedFirstClearSafeSpotIce();
    } else {
      this.seedFrozenPortState();
    }
    this.ambientIceFormation.set(
      buildAmbientIceFormationField(
        this.openness,
        this.columns,
        this.rows,
        this.safeSpotAmbientEligibility,
      ),
    );
    this.baselineAmbientIceFormation.set(
      this.ambientIceFormation,
    );
    this.oceanWaterReveal.fill(1);
    this.initializeSnowObstacleField();
    this.baselineThickness.set(this.thickness);
    this.baselineOpenness.set(this.openness);
    this.updateEffectiveThickness(false);
    this.syncVisualThicknessBands();
    this.rebuildFloeTopology();
    this.syncAuthorityFloes(ZERO_SERVER_TICK);
    this.authorityState.establishBaseline();
    this.markAllCellsDirty(IceDirtyFlag.All);
    this.updateDirtyVisuals(0);
  }

