  /** Applies complete sparse chunk snapshots to only their invalidated cell ranges. */
  public applyCanonicalChunks(
    chunks: readonly Readonly<CanonicalIceChunkPresentation>[],
    dirtyRanges: readonly Readonly<CanonicalIceDirtyPresentationRange>[],
    replaceWholeChunks: boolean,
  ): void {
    const ranges = new Map(
      dirtyRanges.map((range) => [`${range.chunkX},${range.chunkZ}`, range] as const),
    );
    const baseline = this.authorityState.baselineArrays();
    for (const chunk of chunks) {
      const range = ranges.get(`${chunk.chunkX},${chunk.chunkZ}`);
      const minimum = replaceWholeChunks
        ? 0
        : clamp(Math.floor(range?.minimumIndex ?? 0), 0, 255);
      const maximum = replaceWholeChunks
        ? 255
        : clamp(Math.floor(range?.maximumIndex ?? 255), minimum, 255);
      const changes = new Map(chunk.changes.map((cell) => [cell.index, cell]));
      const flags = this.presentationFlagsForAuthorityFields(
        replaceWholeChunks ? IceAuthorityField.All : range?.fieldMask ?? IceAuthorityField.All,
        replaceWholeChunks || Boolean(range?.topologyChanged),
      );
      for (let localIndex = minimum; localIndex <= maximum; localIndex += 1) {
        const localColumn = localIndex % ICE_AUTHORITY_CHUNK_SIZE;
        const localRow = Math.floor(localIndex / ICE_AUTHORITY_CHUNK_SIZE);
        const column = chunk.chunkX * ICE_AUTHORITY_CHUNK_SIZE + localColumn;
        const row = chunk.chunkZ * ICE_AUTHORITY_CHUNK_SIZE + localRow;
        if (!this.isInside(column, row)) continue;
        const index = this.index(column, row);
        const change = changes.get(localIndex);
        this.thickness[index] = change
          ? clamp(change.thickness, 0, 255) / 255
          : baseline.thickness[index]!;
        this.openness[index] = change
          ? clamp(change.openness, 0, 255) / 255
          : baseline.openness[index]!;
        this.nextOpenness[index] = this.openness[index]!;
        this.snowCover[index] = change
          ? clamp(change.snow, 0, 255) / 255
          : baseline.snowCover[index]!;
        this.nextSnowCover[index] = this.snowCover[index]!;
        this.channelMemory[index] = change
          ? clamp(change.channelMemory, 0, 255) / 255
          : baseline.channelMemory[index]!;
        this.nextChannelMemory[index] = this.channelMemory[index]!;
        this.channelAge[index] = change
          ? clamp(change.channelAge, 0, 65_535)
          : baseline.channelAge[index]!;
        this.nextChannelAge[index] = this.channelAge[index]!;
        this.cellOwner[index] = change?.owner ?? baseline.cellOwner[index]!;
        this.floeIdByCell[index] = change?.floeId ?? baseline.floeIdByCell[index]!;
        if (this.cellOwner[index] !== IceCellOwner.DetachedFloe) {
          this.clearCellMotion(index);
        }
        this.effectiveThickness[index] = this.calculateEffectiveThicknessAt(index);
        this.visualThicknessBand[index] =
          getVisualThicknessBand(this.effectiveThickness[index]!);
        this.markCellDirty(index, flags, false);
      }
    }
    this.coarseCellIndices = [];
    for (let index = 0; index < this.count; index += 1) {
      if (this.cellOwner[index] === IceCellOwner.CoarseIce) {
        this.coarseCellIndices.push(index);
      }
    }
  }

  /** Applies reliable topology or latest-wins motion from the canonical floe proxy. */
  public applyCanonicalFloes(
    canonical: readonly Readonly<IceAuthorityFloeState>[],
    topologyChanged: boolean,
  ): void {
    if (topologyChanged) {
      this.restoreSavedFloes(canonical.map((floe) => ({
        id: floe.id,
        cells: [...floe.cells],
        centerX: floe.centerX,
        centerZ: floe.centerZ,
        offsetX: floe.offsetX,
        offsetZ: floe.offsetZ,
        velocityX: floe.velocityX,
        velocityZ: floe.velocityZ,
        angle: floe.yaw,
        angularVelocity: floe.angularVelocity,
        pressure: floe.pressure,
        separationCooldown: floe.separationCooldown,
        detachedAgeSeconds: floe.detachedAgeSeconds,
        contactBondSeconds: floe.contactBondSeconds,
        thermalAnchorSeconds: floe.thermalAnchorSeconds,
        seed: floe.seed,
      })), false);
      return;
    }
    const byId = new Map(canonical.map((floe) => [floe.id, floe]));
    for (const floe of this.floes) {
      const next = byId.get(floe.id);
      if (!next) continue;
      floe.centerX = next.centerX;
      floe.centerZ = next.centerZ;
      floe.offsetX = next.offsetX;
      floe.offsetZ = next.offsetZ;
      floe.renderOffsetX = next.offsetX;
      floe.renderOffsetZ = next.offsetZ;
      floe.velocityX = next.velocityX;
      floe.velocityZ = next.velocityZ;
      floe.angle = next.yaw;
      floe.angularVelocity = next.angularVelocity;
      floe.pressure = next.pressure;
      floe.cosine = Math.cos(next.yaw);
      floe.sine = Math.sin(next.yaw);
      for (const index of floe.cells) {
        this.floeOffsetX[index] = next.offsetX;
        this.floeOffsetZ[index] = next.offsetZ;
        this.floeVelocityX[index] = next.velocityX;
        this.floeVelocityZ[index] = next.velocityZ;
        this.floeAngle[index] = next.yaw;
        this.markCellDirty(index, IceDirtyFlag.Movement, false);
      }
    }
  }

  /** Seeded cosmetic confirmation; deliberately does not mutate gameplay fields. */
  public presentCanonicalFracture(
    x: number,
    z: number,
    magnitude: number,
    direction: number,
    seed: number,
  ): void {
    if (![x, z, magnitude, direction, seed].every(Number.isFinite)) return;
    const center = this.worldToGrid(x, z);
    const radius = magnitude > 0.7 ? 2 : 1;
    for (let dz = -radius; dz <= radius; dz += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        const column = center.column + dx;
        const row = center.row + dz;
        if (!this.isInside(column, row)) continue;
        const along = Math.abs(dx * Math.cos(direction) + dz * Math.sin(direction));
        const noise = hash2D(column, row, Math.floor(seed) ^ 0x51f15e) * 0.28;
        const strength = clamp(
          magnitude * (1 - Math.hypot(dx, dz) / (radius + 0.75)) + noise - along * 0.04,
          0,
          1,
        );
        if (strength <= 0.04) continue;
        const index = this.index(column, row);
        const previous = this.remoteFractures.get(index);
        const peak = Math.max(previous?.peak ?? 0, strength);
        this.remoteFractures.set(index, {
          peak,
          expiresAt: this.visualTime + 2.2 + noise,
        });
        this.breakStress[index] = Math.max(this.breakStress[index]!, peak);
        this.markCellDirty(index, IceDirtyFlag.Appearance, false);
      }
    }
  }

  public update(deltaSeconds: number, timeScale: number): void {
    const realDelta = Math.min(deltaSeconds, 0.1);
    const scaledDelta = this.remoteAuthorityMode ? 0 : realDelta * timeScale;
    this.advanceOceanWaterReveals(realDelta);
    this.simulationAccumulator += scaledDelta;
    this.simulationTime += scaledDelta;
    this.visualTime += realDelta;
    this.visualTimer += deltaSeconds;

    if (!this.remoteAuthorityMode && timeScale > 0) {
      this.snowSimulationAccumulator += realDelta;
      while (this.snowSimulationAccumulator >= SNOW_SIMULATION_STEP) {
        this.simulateSnowStep(SNOW_SIMULATION_STEP);
        this.snowSimulationAccumulator -= SNOW_SIMULATION_STEP;
      }
    }

    while (this.simulationAccumulator >= WORLD.fixedSimulationStep) {
      this.simulateStep(WORLD.fixedSimulationStep);
      this.simulationAccumulator -= WORLD.fixedSimulationStep;
    }

    if (this.visualTimer >= 0.06) {
      this.updateRemoteFracturePresentation();
      this.markAnimatedCellsDirty();
      this.visualTimer = 0;
    }
    if (this.dirtyCellIndices.length > 0) {
      this.updateDirtyVisuals(this.visualTime);
    }
  }

  private updateRemoteFracturePresentation(): void {
    for (const [index, fracture] of this.remoteFractures) {
      const remaining = clamp((fracture.expiresAt - this.visualTime) / 2.2, 0, 1);
      const next = fracture.peak * remaining * remaining;
      if (Math.abs(this.breakStress[index]! - next) > 0.02 || remaining === 0) {
        this.breakStress[index] = next;
        this.markCellDirty(index, IceDirtyFlag.Appearance, false);
      }
      if (remaining === 0) this.remoteFractures.delete(index);
    }
  }

