  public forceFloeInteractionTest(
    mode: 'separation' | 'compression',
    center: Readonly<WorldPoint>,
  ): number {
    this.rebuildFloeTopology();
    let affected = 0;
    for (const floe of this.floes) {
      if (floe.cells.length > MAX_DETACHED_FLOE_CELLS) continue;
      let directionX = floe.centerX + floe.offsetX - center.x;
      let directionZ = floe.centerZ + floe.offsetZ - center.z;
      const distance = Math.hypot(directionX, directionZ);
      if (distance > 14) continue;
      if (distance < 0.1) {
        const angle = floe.seed * Math.PI * 2;
        directionX = Math.cos(angle);
        directionZ = Math.sin(angle);
      } else {
        directionX /= distance;
        directionZ /= distance;
      }
      const sign = mode === 'separation' ? 1 : -1;
      const impulse = 0.018 + floe.mobility * 0.035;
      floe.velocityX += directionX * impulse * sign;
      floe.velocityZ += directionZ * impulse * sign;
      if (mode === 'compression') {
        floe.pressure = Math.max(floe.pressure, 0.24);
      }
      affected += 1;
      if (affected >= 18) break;
    }
    if (affected > 0) {
      for (const floe of this.floes) {
        if (Math.hypot(
          floe.centerX + floe.offsetX - center.x,
          floe.centerZ + floe.offsetZ - center.z,
        ) > 14) {
          continue;
        }
        this.markCellsDirty(floe.cells, IceDirtyFlag.Movement);
      }
    }
    return affected;
  }

