import {
  BufferGeometry,
  CanvasTexture,
  Color,
  DoubleSide,
  Float32BufferAttribute,
  Group,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  PlaneGeometry,
  Quaternion,
  RepeatWrapping,
  SRGBColorSpace,
  TextureLoader,
  Vector3,
  type Scene,
  type Texture,
} from 'three';
import type { TerrainHeightSystem } from '../land/TerrainHeightSystem';
import type {
  WorldAssetPlacementSystem,
  WorldAssetRuntimeBatch,
  WorldAssetRuntimeSnowBatch,
} from '../land/WorldAssetPlacementSystem';
import { wildernessCreekCenterX } from '../survival/WildernessBiome';
import {
  addWinterWorldRouteListener,
  listWinterWorldRoutes,
  type WinterWorldRoute,
} from './WinterWorldRoutes';

export { WINTER_WORLD_ROUTES, type WinterWorldRoute } from './WinterWorldRoutes';

interface RoutePlacement {
  readonly prefabId: string;
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly scale?: number;
  readonly snow?: number;
}

const sampleSegment = (
  from: Readonly<{ x: number; z: number }>,
  to: Readonly<{ x: number; z: number }>,
  distance: number,
): Readonly<{ x: number; z: number; heading: number }> => {
  const length = Math.max(0.0001, Math.hypot(to.x - from.x, to.z - from.z));
  const blend = Math.max(0, Math.min(1, distance / length));
  return {
    x: from.x + (to.x - from.x) * blend,
    z: from.z + (to.z - from.z) * blend,
    heading: Math.atan2(to.x - from.x, to.z - from.z),
  };
};

const ROUTE_TEXTURE_URL = 'assets/world/survival/textures/old-winter-path-ground-v1.png';

/**
 * A first authored human-history layer for The Long Winter. It intentionally
 * contains no quest state: old routes, lanterns, walls and ruins make the
 * landscape readable on their own. Every prop resolves through the shared
 * asset bank and can later be replaced by production GLBs without rewriting
 * the deterministic route data.
 */
export class WinterWorldCompositionSystem {
  private readonly root = new Group();
  private readonly routeRoot = new Group();
  private readonly propRoot = new Group();
  private readonly routeMaterial = new MeshStandardMaterial({
    name: 'Old compacted winter route',
    color: new Color(0xffffff),
    roughness: 1,
    metalness: 0,
    polygonOffset: true,
    polygonOffsetFactor: -1,
    polygonOffsetUnits: -2,
  });
  private readonly batches: WorldAssetRuntimeBatch[] = [];
  private readonly snowBatches: WorldAssetRuntimeSnowBatch[] = [];
  private routeTexture?: Texture;
  private readonly signLabelTextures: Texture[] = [];
  private readonly signLabelMaterials: MeshStandardMaterial[] = [];
  private readonly removeRouteListener: () => void;
  private disposed = false;
  private routeVertices = 0;
  private propInstances = 0;

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    private readonly assets: WorldAssetPlacementSystem,
  ) {
    this.root.name = 'Winter world composition · old routes and ruins';
    this.routeRoot.name = 'Editable winter routes';
    this.propRoot.name = 'Winter route landmarks';
    this.root.add(this.routeRoot, this.propRoot);
    scene.add(this.root);
    this.loadRouteTexture();
    this.rebuildRoutePresentation();
    this.removeRouteListener = addWinterWorldRouteListener(() =>
      this.rebuildRoutePresentation());
    this.root.visible = false;
  }

  public setVisible(visible: boolean): void {
    this.root.visible = visible;
  }

  public writePerformanceTrace(target: {
    winterRouteVertices?: number;
    winterRouteProps?: number;
  }): void {
    target.winterRouteVertices = this.routeVertices;
    target.winterRouteProps = this.propInstances;
  }

  public dispose(): void {
    this.disposed = true;
    this.removeRouteListener();
    this.clearRoutePresentation();
    for (const texture of this.signLabelTextures) texture.dispose();
    this.signLabelTextures.length = 0;
    for (const material of this.signLabelMaterials) material.dispose();
    this.signLabelMaterials.length = 0;
    this.routeTexture?.dispose();
    this.routeTexture = undefined;
    this.routeMaterial.dispose();
    this.root.removeFromParent();
  }

  private clearRoutePresentation(): void {
    for (const batch of this.batches) batch.dispose();
    for (const batch of this.snowBatches) batch.dispose();
    this.batches.length = 0;
    this.snowBatches.length = 0;
    this.routeRoot.traverse((object) => {
      if (object instanceof Mesh) object.geometry.dispose();
    });
    this.propRoot.traverse((object) => {
      if (object instanceof Mesh && object.userData.winterSignLabel === true) {
        object.geometry.dispose();
      }
    });
    this.routeRoot.clear();
    this.propRoot.clear();
    for (const texture of this.signLabelTextures) texture.dispose();
    this.signLabelTextures.length = 0;
    for (const material of this.signLabelMaterials) material.dispose();
    this.signLabelMaterials.length = 0;
    this.routeVertices = 0;
    this.propInstances = 0;
  }

  private rebuildRoutePresentation(): void {
    if (this.disposed) return;
    this.clearRoutePresentation();
    const routes = listWinterWorldRoutes();
    for (const route of routes) {
      const mesh = new Mesh(this.createRouteGeometry(route), this.routeMaterial);
      mesh.name = `Old winter route · ${route.id}`;
      mesh.receiveShadow = true;
      mesh.castShadow = false;
      this.routeRoot.add(mesh);
    }
    this.createRouteProps(routes);
  }

  private createRouteGeometry(route: Readonly<WinterWorldRoute>): BufferGeometry {
    const geometry = new BufferGeometry();
    const positions: number[] = [];
    const colors: number[] = [];
    const uvs: number[] = [];
    const indices: number[] = [];
    const samples: Array<{
      x: number;
      z: number;
      heading: number;
      distance: number;
    }> = [];
    let travelled = 0;
    for (let segment = 0; segment < route.points.length - 1; segment += 1) {
      const from = route.points[segment]!;
      const to = route.points[segment + 1]!;
      const length = Math.hypot(to.x - from.x, to.z - from.z);
      const steps = Math.max(1, Math.ceil(length / 1.35));
      for (let step = segment === 0 ? 0 : 1; step <= steps; step += 1) {
        const segmentDistance = length * step / steps;
        samples.push({
          ...sampleSegment(from, to, segmentDistance),
          distance: travelled + segmentDistance,
        });
      }
      travelled += length;
    }
    for (const [index, sample] of samples.entries()) {
      const sideX = Math.cos(sample.heading);
      const sideZ = -Math.sin(sample.heading);
      const wobble = Math.sin(index * 1.713 + route.id.length) * 0.08;
      for (const side of [-1, 1] as const) {
        const x = sample.x + sideX * (route.width * 0.5 + wobble) * side;
        const z = sample.z + sideZ * (route.width * 0.5 + wobble) * side;
        // This is the actual earth route. It stays on terrain beneath the
        // snow and is revealed only where the authoritative snow thins.
        positions.push(x, this.terrain.sampleHeight(x, z) + 0.012, z);
        const tint = 0.965 + Math.sin(index * 0.83 + side) * 0.018;
        colors.push(tint * 0.98, tint * 0.99, tint);
        uvs.push(side < 0 ? 0 : 1, sample.distance / 3.2);
      }
      if (index < samples.length - 1) {
        const base = index * 2;
        indices.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
      }
    }
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('color', new Float32BufferAttribute(colors, 3));
    geometry.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
    this.routeMaterial.vertexColors = true;
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    this.routeVertices += positions.length / 3;
    return geometry;
  }

  private loadRouteTexture(): void {
    const url = new URL(ROUTE_TEXTURE_URL, document.baseURI).href;
    new TextureLoader().load(
      url,
      (texture) => {
        if (this.disposed) {
          texture.dispose();
          return;
        }
        texture.name = 'Old winter path ground albedo';
        texture.colorSpace = SRGBColorSpace;
        texture.wrapS = RepeatWrapping;
        texture.wrapT = RepeatWrapping;
        this.routeTexture = texture;
        this.routeMaterial.map = texture;
        this.routeMaterial.needsUpdate = true;
      },
      undefined,
      () => {
        // The neutral material colour remains a safe playtest fallback.
      },
    );
  }

  private createRouteProps(routes: readonly WinterWorldRoute[]): void {
    const placements: RoutePlacement[] = [
      { prefabId: 'WILDERNESS_RUIN_ARCH_01', x: -859, z: -182, heading: 0.38, snow: 0.42 },
      { prefabId: 'WILDERNESS_WAYSTONE_01', x: -846, z: -200, heading: 0.82, snow: 0.56 },
      {
        prefabId: 'WILDERNESS_TIMBER_FOOTBRIDGE_01',
        x: wildernessCreekCenterX(-199), z: -199, heading: Math.PI * 0.48,
        scale: 1.05, snow: 0.24,
      },
    ];
    // A readable but broken lantern rhythm suggests a former road without
    // turning the wilderness into a modern illuminated street.
    let signPlaced = false;
    for (const route of routes) {
      let travelled = 0;
      let nextMarker = route.id === 'old-raven-road' ? 14 : 22;
      for (let segment = 0; segment < route.points.length - 1; segment += 1) {
        const from = route.points[segment]!;
        const to = route.points[segment + 1]!;
        const length = Math.hypot(to.x - from.x, to.z - from.z);
        while (nextMarker <= travelled + length) {
          const sample = sampleSegment(from, to, nextMarker - travelled);
          const side = Math.floor(nextMarker / 18) % 2 === 0 ? -1 : 1;
          const useCrossroadsSign = !signPlaced && route.id === 'old-raven-road';
          placements.push({
            prefabId: useCrossroadsSign
              ? 'WILDERNESS_THREE_WAY_SIGNPOST_01'
              : 'WILDERNESS_ROUTE_LANTERN_01',
            x: sample.x + Math.cos(sample.heading) * side * (route.width + 0.8),
            z: sample.z - Math.sin(sample.heading) * side * (route.width + 0.8),
            heading: sample.heading + (side < 0 ? Math.PI : 0),
            scale: 0.9 + (Math.sin(nextMarker * 1.7) + 1) * 0.06,
            snow: 0.38,
          });
          if (useCrossroadsSign) signPlaced = true;
          nextMarker += 27 + (Math.floor(nextMarker) % 3) * 4;
        }
        travelled += length;
      }
    }
    for (let index = 0; index < 7; index += 1) {
      placements.push({
        prefabId: 'WILDERNESS_DRY_STONE_WALL_01',
        x: -861.8 + index * 2.25,
        z: -186.4 + Math.sin(index * 0.75) * 0.42,
        heading: Math.PI * 0.51 + Math.sin(index * 0.48) * 0.09,
        scale: 0.86 + (index % 3) * 0.08,
        snow: 0.62,
      });
    }

    const grouped = new Map<string, RoutePlacement[]>();
    for (const placement of placements) {
      const group = grouped.get(placement.prefabId) ?? [];
      group.push(placement);
      grouped.set(placement.prefabId, group);
    }
    const matrix = new Matrix4();
    const position = new Vector3();
    const quaternion = new Quaternion();
    const scale = new Vector3();
    const up = new Vector3(0, 1, 0);
    for (const [prefabId, group] of grouped) {
      const batch = this.assets.createRuntimeBatch(prefabId, group.length);
      if (!batch) continue;
      const snow = this.assets.createRuntimeSnowBatch(prefabId, group.length);
      group.forEach((placement, index) => {
        position.set(
          placement.x,
          this.terrain.sampleHeight(placement.x, placement.z),
          placement.z,
        );
        quaternion.setFromAxisAngle(up, placement.heading);
        scale.setScalar(placement.scale ?? 1);
        matrix.compose(position, quaternion, scale);
        batch.setMatrixAt(index, matrix);
        snow?.setMatrixAt(index, matrix);
        snow?.setAmountAt(index, placement.snow ?? 0.4);
      });
      batch.setCount(group.length);
      batch.commit();
      this.propRoot.add(batch.root);
      this.batches.push(batch);
      if (snow) {
        snow.setCount(group.length);
        snow.commit();
        this.propRoot.add(snow.root);
        this.snowBatches.push(snow);
      }
      this.propInstances += group.length;
    }
    const sign = placements.find((placement) =>
      placement.prefabId === 'WILDERNESS_THREE_WAY_SIGNPOST_01');
    if (sign) this.createThreeWaySignLabels(sign);
  }

  private createThreeWaySignLabels(sign: Readonly<RoutePlacement>): void {
    if (typeof document === 'undefined') return;
    const labels = [
      { name: 'BOREALIS', yaw: 0, y: 1.94 },
      { name: 'EMBER', yaw: Math.PI * 2 / 3, y: 1.6 },
      { name: 'AURORA', yaw: -Math.PI * 2 / 3, y: 1.27 },
    ] as const;
    const root = new Group();
    root.name = 'Three-way village sign lettering';
    root.position.set(
      sign.x,
      this.terrain.sampleHeight(sign.x, sign.z),
      sign.z,
    );
    root.rotation.y = sign.heading;
    root.scale.setScalar(sign.scale ?? 1);
    for (const label of labels) {
      const canvas = document.createElement('canvas');
      canvas.width = 384;
      canvas.height = 80;
      const context = canvas.getContext('2d');
      if (!context) continue;
      context.clearRect(0, 0, canvas.width, canvas.height);
      context.fillStyle = '#2a1d14';
      context.font = '700 42px Georgia, serif';
      context.textAlign = 'center';
      context.textBaseline = 'middle';
      context.fillText(label.name, canvas.width * 0.5, canvas.height * 0.54);
      const texture = new CanvasTexture(canvas);
      texture.name = `Village sign label · ${label.name}`;
      const material = new MeshStandardMaterial({
        name: `Village sign ink · ${label.name}`,
        map: texture,
        transparent: true,
        alphaTest: 0.2,
        roughness: 1,
        metalness: 0,
        side: DoubleSide,
        polygonOffset: true,
        polygonOffsetFactor: -2,
        polygonOffsetUnits: -2,
      });
      const arm = new Group();
      arm.rotation.y = label.yaw;
      const face = new Mesh(new PlaneGeometry(1.16, 0.24), material);
      face.name = `${label.name} lettering`;
      face.userData.winterSignLabel = true;
      face.position.set(0.27, label.y, 0.061);
      face.castShadow = false;
      face.receiveShadow = false;
      arm.add(face);
      root.add(arm);
      this.signLabelTextures.push(texture);
      this.signLabelMaterials.push(material);
    }
    this.propRoot.add(root);
  }
}
