import {
  type CommandSequence,
  type JsonObject,
  type NetworkEntityId,
  type PlayerId,
  type Revision,
  type ServerTick,
  type TransactionId,
  commandSequence,
  isJsonValue,
  isPlainJsonObject,
  networkEntityId,
  playerId,
  revision,
  serverTick,
  transactionId,
} from '../core/NetworkPrimitives';

export interface NormalizedMovementCommand {
  forward: number;
  lateral: number;
  steering: number;
  yaw: number;
  vertical: number;
  /** World-space heading in radians for mouse/stick aiming, when relevant. */
  aimHeading?: number;
}

export interface NormalizedToolCommand {
  primaryAxis: number;
  secondaryAxis: number;
}

export const PLAYER_COMMAND_ACTION = Object.freeze({
  INTERACT: 1 << 0,
  PRIMARY_USE: 1 << 1,
  SECONDARY_USE: 1 << 2,
  TOGGLE_LIGHTS: 1 << 3,
  HORN: 1 << 4,
  TOGGLE_BEACON: 1 << 5,
  RUN_OR_BOOST: 1 << 6,
  RETURN_OR_RESET: 1 << 7,
  TOGGLE_TOOL_MODE: 1 << 8,
});

export const PLAYER_COMMAND_ACTION_MASK = Object.values(
  PLAYER_COMMAND_ACTION,
).reduce((mask, bit) => mask | bit, 0);

export interface PlayerCommandFrame {
  version: 1;
  playerId: PlayerId;
  controlledEntityId?: NetworkEntityId;
  commandSequence: CommandSequence;
  predictedTick: ServerTick;
  movement: NormalizedMovementCommand;
  tool: NormalizedToolCommand;
  actionBits: number;
}

export type ReliableAuthorityChannel =
  | 'CONTEXTUAL_INTERACTION'
  | 'INVENTORY'
  | 'DIALOGUE'
  | 'MAP'
  | 'QUEST'
  | 'TEXT_CHAT'
  | 'CONSTRUCTION'
  | 'RADIO'
  | 'SETTLEMENT'
  | 'SESSION';

export type AuthorityDeliveryClass =
  | 'LATEST_SEQUENCED'
  | 'RELIABLE_ORDERED'
  | 'RELIABLE_IDEMPOTENT';

export const AUTHORITY_CHANNEL_POLICY: Readonly<
  Record<ReliableAuthorityChannel, AuthorityDeliveryClass>
> = Object.freeze({
  CONTEXTUAL_INTERACTION: 'RELIABLE_IDEMPOTENT',
  INVENTORY: 'RELIABLE_IDEMPOTENT',
  DIALOGUE: 'RELIABLE_IDEMPOTENT',
  MAP: 'RELIABLE_IDEMPOTENT',
  QUEST: 'RELIABLE_IDEMPOTENT',
  TEXT_CHAT: 'RELIABLE_ORDERED',
  CONSTRUCTION: 'RELIABLE_IDEMPOTENT',
  RADIO: 'RELIABLE_IDEMPOTENT',
  SETTLEMENT: 'RELIABLE_IDEMPOTENT',
  SESSION: 'RELIABLE_IDEMPOTENT',
});

export interface ReliableAuthorityOperation {
  version: 1;
  requestId: TransactionId;
  playerId: PlayerId;
  issuedAtTick: ServerTick;
  channel: ReliableAuthorityChannel;
  operation: string;
  targetEntityId?: NetworkEntityId;
  observedRevision?: Revision;
  payload: JsonObject;
}

export interface CommandValidationFailure {
  ok: false;
  reason:
    | 'INVALID_VERSION'
    | 'INVALID_ID'
    | 'INVALID_SEQUENCE'
    | 'INVALID_TICK'
    | 'INVALID_AXIS'
    | 'INVALID_ACTION_BITS';
}

export interface CommandValidationSuccess {
  ok: true;
  value: PlayerCommandFrame;
}

export type CommandValidationResult =
  | CommandValidationSuccess
  | CommandValidationFailure;

type NormalizedMovementAxisKey = Exclude<
  keyof NormalizedMovementCommand,
  'aimHeading'
>;

const AXIS_KEYS: readonly NormalizedMovementAxisKey[] = [
  'forward',
  'lateral',
  'steering',
  'yaw',
  'vertical',
];

const isNormalizedAxis = (value: number): boolean =>
  Number.isFinite(value) && value >= -1 && value <= 1;

const cloneCommand = (
  frame: Readonly<PlayerCommandFrame>,
): PlayerCommandFrame => ({
  ...frame,
  movement: { ...frame.movement },
  tool: { ...frame.tool },
});

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const boundedId = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= 160;

export const validatePlayerCommandFrame = (
  input: unknown,
): CommandValidationResult => {
  if (!isRecord(input)) return { ok: false, reason: 'INVALID_VERSION' };
  const candidate = input;
  if (candidate.version !== 1) return { ok: false, reason: 'INVALID_VERSION' };
  if (
    !boundedId(candidate.playerId) ||
    (candidate.controlledEntityId !== undefined &&
      !boundedId(candidate.controlledEntityId))
  ) {
    return { ok: false, reason: 'INVALID_ID' };
  }
  if (
    typeof candidate.commandSequence !== 'number' ||
    !Number.isSafeInteger(candidate.commandSequence) ||
    candidate.commandSequence < 0
  ) {
    return { ok: false, reason: 'INVALID_SEQUENCE' };
  }
  if (
    typeof candidate.predictedTick !== 'number' ||
    !Number.isSafeInteger(candidate.predictedTick) ||
    candidate.predictedTick < 0
  ) {
    return { ok: false, reason: 'INVALID_TICK' };
  }
  if (!isRecord(candidate.movement) || !isRecord(candidate.tool)) {
    return { ok: false, reason: 'INVALID_AXIS' };
  }
  const movement = candidate.movement;
  const tool = candidate.tool;
  if (
    AXIS_KEYS.some(
      (key) => !isNormalizedAxis(movement[key] as number),
    ) ||
    (movement.aimHeading !== undefined &&
      (typeof movement.aimHeading !== 'number' ||
        !Number.isFinite(movement.aimHeading) ||
        movement.aimHeading < -Math.PI ||
        movement.aimHeading > Math.PI)) ||
    !isNormalizedAxis(tool.primaryAxis as number) ||
    !isNormalizedAxis(tool.secondaryAxis as number)
  ) {
    return { ok: false, reason: 'INVALID_AXIS' };
  }
  if (
    typeof candidate.actionBits !== 'number' ||
    !Number.isSafeInteger(candidate.actionBits) ||
    candidate.actionBits < 0 ||
    (candidate.actionBits & ~PLAYER_COMMAND_ACTION_MASK) !== 0
  ) {
    return { ok: false, reason: 'INVALID_ACTION_BITS' };
  }
  return {
    ok: true,
    value: cloneCommand({
      version: 1,
      playerId: playerId(candidate.playerId),
      ...(candidate.controlledEntityId === undefined
        ? {}
        : { controlledEntityId: networkEntityId(candidate.controlledEntityId) }),
      commandSequence: commandSequence(candidate.commandSequence as number),
      predictedTick: serverTick(candidate.predictedTick as number),
      movement: {
        forward: movement.forward as number,
        lateral: movement.lateral as number,
        steering: movement.steering as number,
        yaw: movement.yaw as number,
        vertical: movement.vertical as number,
        ...(movement.aimHeading === undefined
          ? {}
          : { aimHeading: movement.aimHeading as number }),
      },
      tool: {
        primaryAxis: tool.primaryAxis as number,
        secondaryAxis: tool.secondaryAxis as number,
      },
      actionBits: candidate.actionBits as number,
    }),
  };
};

export interface OperationValidationFailure {
  ok: false;
  reason:
    | 'INVALID_VERSION'
    | 'INVALID_ID'
    | 'INVALID_TICK'
    | 'INVALID_CHANNEL'
    | 'INVALID_OPERATION'
    | 'INVALID_PAYLOAD';
}

export interface OperationValidationSuccess {
  ok: true;
  value: ReliableAuthorityOperation;
}

export type OperationValidationResult =
  | OperationValidationSuccess
  | OperationValidationFailure;

export const validateReliableAuthorityOperation = (
  input: unknown,
): OperationValidationResult => {
  if (!isRecord(input)) return { ok: false, reason: 'INVALID_VERSION' };
  const candidate = input;
  if (candidate.version !== 1) return { ok: false, reason: 'INVALID_VERSION' };
  if (
    !boundedId(candidate.requestId) ||
    !boundedId(candidate.playerId) ||
    (candidate.targetEntityId !== undefined &&
      !boundedId(candidate.targetEntityId))
  ) {
    return { ok: false, reason: 'INVALID_ID' };
  }
  if (
    typeof candidate.issuedAtTick !== 'number' ||
    !Number.isSafeInteger(candidate.issuedAtTick) ||
    candidate.issuedAtTick < 0
  ) {
    return { ok: false, reason: 'INVALID_TICK' };
  }
  if (
    candidate.observedRevision !== undefined &&
    (typeof candidate.observedRevision !== 'number' ||
      !Number.isSafeInteger(candidate.observedRevision) ||
      candidate.observedRevision < 0)
  ) {
    return { ok: false, reason: 'INVALID_TICK' };
  }
  if (
    typeof candidate.channel !== 'string' ||
    !Object.prototype.hasOwnProperty.call(
      AUTHORITY_CHANNEL_POLICY,
      candidate.channel,
    )
  ) {
    return { ok: false, reason: 'INVALID_CHANNEL' };
  }
  if (
    typeof candidate.operation !== 'string' ||
    candidate.operation.trim().length === 0 ||
    candidate.operation.length > 96
  ) {
    return { ok: false, reason: 'INVALID_OPERATION' };
  }
  if (
    !isPlainJsonObject(candidate.payload) ||
    !isJsonValue(candidate.payload)
  ) {
    return { ok: false, reason: 'INVALID_PAYLOAD' };
  }
  return {
    ok: true,
    value: {
      version: 1,
      requestId: transactionId(candidate.requestId),
      playerId: playerId(candidate.playerId),
      issuedAtTick: serverTick(candidate.issuedAtTick as number),
      channel: candidate.channel as ReliableAuthorityChannel,
      operation: candidate.operation.trim(),
      ...(candidate.targetEntityId === undefined
        ? {}
        : { targetEntityId: networkEntityId(candidate.targetEntityId) }),
      ...(candidate.observedRevision === undefined
        ? {}
        : { observedRevision: revision(candidate.observedRevision as number) }),
      payload: { ...candidate.payload },
    },
  };
};

export const createNeutralPlayerCommand = (
  targetPlayerId: PlayerId,
  sequence: CommandSequence,
  tick: ServerTick,
  controlledEntityId?: NetworkEntityId,
): PlayerCommandFrame => ({
  version: 1,
  playerId: targetPlayerId,
  ...(controlledEntityId ? { controlledEntityId } : {}),
  commandSequence: sequence,
  predictedTick: tick,
  movement: {
    forward: 0,
    lateral: 0,
    steering: 0,
    yaw: 0,
    vertical: 0,
  },
  tool: { primaryAxis: 0, secondaryAxis: 0 },
  actionBits: 0,
});
