import { DoubleSide, DynamicDrawUsage, InstancedBufferAttribute, InstancedMesh,
  Object3D, PlaneGeometry, ShaderMaterial, type Group } from 'three';
import { clamp } from '../../utils/math';
import type { RoomSmokeCell } from './SurvivalRoomSmoke';

/** Sparse, shared-draw room haze. Cards are clipped in world coordinates to
 * each air cell, below its ceiling, and depth-tested against actual walls.
 * This is not a full-screen overlay and can be seen through an open doorway. */
export class SurvivalRoomSmokePresenter {
  private readonly geometry = new PlaneGeometry(1, 1);
  private readonly bounds = new InstancedBufferAttribute(new Float32Array(1024 * 4), 4);
  private readonly density = new InstancedBufferAttribute(new Float32Array(1024), 1);
  private readonly edges = new InstancedBufferAttribute(new Float32Array(1024 * 4), 4);
  private readonly material = new ShaderMaterial({
    transparent: true, depthWrite: false, side: DoubleSide,
    uniforms: { time: { value: 0 } },
    vertexShader: `
      attribute vec4 smokeBounds;
      attribute float smokeDensity;
      attribute vec4 smokeEdges;
      varying vec3 vWorld;
      varying vec3 vCentre;
      varying vec4 vBounds;
      varying float vDensity;
      varying vec4 vEdges;
      void main() {
        vec4 centre = modelMatrix * instanceMatrix * vec4(0., 0., 0., 1.);
        vec3 right = vec3(viewMatrix[0][0],viewMatrix[1][0],viewMatrix[2][0]);
        vec3 up = vec3(viewMatrix[0][1],viewMatrix[1][1],viewMatrix[2][1]);
        vCentre = centre.xyz; vBounds = smokeBounds; vDensity = smokeDensity;
        vEdges = smokeEdges;
        vWorld = centre.xyz + right * position.x * 2.12 + up * position.y * smokeBounds.w;
        gl_Position = projectionMatrix * viewMatrix * vec4(vWorld, 1.);
      }`,
    fragmentShader: `
      uniform float time;
      varying vec3 vWorld; varying vec3 vCentre;
      varying vec4 vBounds; varying float vDensity;
      varying vec4 vEdges;
      void main() {
        vec2 edge = vec2(.76) - abs(vWorld.xz - vBounds.xy);
        if (min(edge.x, edge.y) < 0. || vWorld.y < vBounds.z || vWorld.y > vBounds.z + vBounds.w) discard;
        vec2 signedOffset = vWorld.xz - vBounds.xy;
        float boundaryX = signedOffset.x < 0. ? vEdges.x : vEdges.y;
        float boundaryZ = signedOffset.y < 0. ? vEdges.z : vEdges.w;
        float soft = mix(1., smoothstep(0., .18, edge.x), boundaryX)
          * mix(1., smoothstep(0., .18, edge.y), boundaryZ);
        float height = (vWorld.y - vBounds.z) / max(.01, vBounds.w);
        soft *= smoothstep(0., .22, height) * smoothstep(1., .86, height);
        float cloud = .8 + .04 * sin(vWorld.x * 2.1 + vWorld.z * 1.7 + time * .19)
          * sin(vWorld.y * 3.1 - time * .12);
        float alpha = (1. - exp(-vDensity * .65)) * soft * cloud;
        if (alpha < .003) discard;
        gl_FragColor = vec4(mix(vec3(.10,.11,.12), vec3(.22,.23,.24), height), alpha);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`,
  });
  readonly mesh: InstancedMesh;
  private readonly transform = new Object3D();
  constructor(root: Group) {
    this.geometry.setAttribute('smokeBounds', this.bounds);
    this.geometry.setAttribute('smokeDensity', this.density);
    this.geometry.setAttribute('smokeEdges', this.edges);
    this.mesh = new InstancedMesh(this.geometry, this.material, 1024);
    this.mesh.name = 'TLW room smoke accumulation'; this.mesh.frustumCulled = false;
    this.mesh.instanceMatrix.setUsage(DynamicDrawUsage); this.mesh.count = 0;
    this.mesh.renderOrder = 23; root.add(this.mesh);
  }
  update(cells: ReadonlyMap<string, RoomSmokeCell>, x: number, z: number, time: number): void {
    this.material.uniforms.time!.value = time;
    let count = 0;
    for (const cell of cells.values()) {
      const concentration = clamp(cell.mass / cell.volume, 0, 2);
      if (concentration < 0.015 || Math.hypot(cell.x - x, cell.z - z) > 45) continue;
      const roomHeight = Math.max(0.1, cell.ceilingY - cell.floorY);
      const layerHeight = Math.min(roomHeight - 0.08, 0.15 + concentration * roomHeight * 1.6);
      const bottom = cell.ceilingY - layerHeight - 0.04;
      let left = 1, right = 1, north = 1, south = 1;
      for (const id of cell.links) {
        const n = cells.get(id);
        if (!n || Math.abs(n.floorY - cell.floorY) >= 0.2) continue;
        if (n.x < cell.x - 0.1) left = 0;
        if (n.x > cell.x + 0.1) right = 0;
        if (n.z < cell.z - 0.1) north = 0;
        if (n.z > cell.z + 0.1) south = 0;
      }
      for (const offset of [-0.23, 0.23]) {
        if (count >= 1024) break;
        this.transform.position.set(cell.x, bottom + layerHeight * 0.5, cell.z + offset);
        this.transform.updateMatrix(); this.mesh.setMatrixAt(count, this.transform.matrix);
        this.bounds.setXYZW(count, cell.x, cell.z, bottom, layerHeight);
        this.edges.setXYZW(count, left, right, north, south);
        this.density.setX(count, concentration); count += 1;
      }
    }
    this.mesh.count = count; this.mesh.visible = count > 0;
    this.mesh.instanceMatrix.needsUpdate = true; this.bounds.needsUpdate = true; this.density.needsUpdate = true;
    this.edges.needsUpdate = true;
  }
  dispose(): void { this.mesh.removeFromParent(); this.geometry.dispose(); this.material.dispose(); }
}
