import { hash2D, lerp } from '../utils/math';
import type {
  IcebergChunkRequest,
  IcebergDefinition,
  IcebergPlacementExclusion,
  IcebergShape,
  IcebergSize,
} from './IcebergTypes';

export type OceanDepthSampler = (x: number, z: number) => number;

interface SizeProfile {
  visualRadiusMin: number;
  visualRadiusMax: number;
  collisionScale: number;
  hiddenKeel: number;
  heightMin: number;
  heightMax: number;
  minimumDepth: number;
  groundingDepth: number;
}

const SIZE_SEQUENCE: readonly IcebergSize[] = [
  'large',
  'growler',
  'small',
  'medium',
  'growler',
  'small',
  'medium',
  'growler',
];

const SHAPES_BY_SIZE: Record<IcebergSize, readonly IcebergShape[]> = {
  growler: ['dome', 'wedge', 'pinnacle'],
  small: ['dome', 'pinnacle', 'wedge'],
  medium: ['dome', 'pinnacle', 'tabular', 'wedge'],
  large: ['tabular', 'dome', 'wedge'],
};

const SIZE_PROFILES: Record<IcebergSize, SizeProfile> = {
  growler: {
    visualRadiusMin: 0.34,
    visualRadiusMax: 0.5,
    collisionScale: 1.12,
    hiddenKeel: 0.12,
    heightMin: 0.48,
    heightMax: 0.78,
    minimumDepth: 0.16,
    groundingDepth: 0.2,
  },
  small: {
    visualRadiusMin: 0.62,
    visualRadiusMax: 0.92,
    collisionScale: 1.15,
    hiddenKeel: 0.16,
    heightMin: 0.85,
    heightMax: 1.42,
    minimumDepth: 0.18,
    groundingDepth: 0.24,
  },
  medium: {
    visualRadiusMin: 1.08,
    visualRadiusMax: 1.52,
    collisionScale: 1.18,
    hiddenKeel: 0.22,
    heightMin: 1.55,
    heightMax: 2.45,
    minimumDepth: 0.2,
    groundingDepth: 0.43,
  },
  large: {
    visualRadiusMin: 1.82,
    visualRadiusMax: 2.62,
    collisionScale: 1.2,
    hiddenKeel: 0.32,
    heightMin: 2.25,
    heightMax: 3.55,
    minimumDepth: 0.24,
    groundingDepth: 0.52,
  },
};

const CANDIDATE_ATTEMPTS = 72;
const PLACEMENT_GAP = 0.48;

const icebergSizeAt = (index: number, seed: number): IcebergSize => {
  const offset = Math.floor(hash2D(seed, 17, 619) * SIZE_SEQUENCE.length);
  return SIZE_SEQUENCE[(index + offset) % SIZE_SEQUENCE.length] ?? 'growler';
};

const shapeAt = (
  size: IcebergSize,
  index: number,
  seed: number,
): IcebergShape => {
  const shapes = SHAPES_BY_SIZE[size];
  const roll = hash2D(index, seed, 947);
  return shapes[Math.floor(roll * shapes.length) % shapes.length] ?? 'dome';
};

const overlapsExclusion = (
  x: number,
  z: number,
  radius: number,
  exclusions: readonly IcebergPlacementExclusion[],
): boolean => exclusions.some((exclusion) =>
  Math.hypot(x - exclusion.x, z - exclusion.z) <
    radius + exclusion.radius
);

const overlapsIceberg = (
  x: number,
  z: number,
  radius: number,
  icebergs: readonly IcebergDefinition[],
): boolean => icebergs.some((iceberg) =>
  Math.hypot(x - iceberg.x, z - iceberg.z) <
    radius + iceberg.collisionRadius + PLACEMENT_GAP
);

export const generateIcebergChunk = (
  request: Readonly<IcebergChunkRequest>,
  sampleDepth: OceanDepthSampler,
  exclusions: readonly IcebergPlacementExclusion[] = [],
): IcebergDefinition[] => {
  const definitions: IcebergDefinition[] = [];
  const chunkSeed =
    request.worldSeed +
    Math.imul(request.chunkX, 73856093) +
    Math.imul(request.chunkZ, 19349663);
  const targetCount = Math.max(0, Math.floor(request.targetCount));

  for (let index = 0; index < targetCount; index += 1) {
    const size = icebergSizeAt(index, chunkSeed);
    const profile = SIZE_PROFILES[size];
    const sizeRoll = hash2D(index, chunkSeed, 101);
    const visualRadius = lerp(
      profile.visualRadiusMin,
      profile.visualRadiusMax,
      sizeRoll,
    );
    const collisionRadius =
      visualRadius * profile.collisionScale + profile.hiddenKeel;
    const margin = collisionRadius + 0.75;
    if (request.width <= margin * 2 || request.height <= margin * 2) continue;

    for (let attempt = 0; attempt < CANDIDATE_ATTEMPTS; attempt += 1) {
      const candidateSeed = index * CANDIDATE_ATTEMPTS + attempt;
      const x =
        request.originX +
        margin +
        hash2D(candidateSeed, chunkSeed, 211) *
          (request.width - margin * 2);
      const z =
        request.originZ +
        margin +
        hash2D(candidateSeed, chunkSeed, 307) *
          (request.height - margin * 2);
      const depth = sampleDepth(x, z);
      if (depth < profile.minimumDepth) continue;
      if (overlapsExclusion(x, z, collisionRadius, exclusions)) continue;
      if (overlapsIceberg(x, z, collisionRadius, definitions)) continue;

      definitions.push({
        id: `${request.chunkX}:${request.chunkZ}:${index}`,
        x,
        z,
        size,
        shape: shapeAt(size, index, chunkSeed),
        visualRadius,
        collisionRadius,
        height: lerp(
          profile.heightMin,
          profile.heightMax,
          hash2D(index, chunkSeed, 401),
        ),
        yaw: hash2D(index, chunkSeed, 503) * Math.PI * 2,
        depth,
        grounded:
          (size === 'medium' || size === 'large') &&
          depth < profile.groundingDepth,
        colorMix: hash2D(index, chunkSeed, 601),
        phase: hash2D(index, chunkSeed, 701) * Math.PI * 2,
      });
      break;
    }
  }

  return definitions;
};
