import type { Camera, Object3D, WebGLRenderer } from 'three';

const rendererCompilationTails = new WeakMap<WebGLRenderer, Promise<void>>();

/**
 * Three's compileAsync mutates per-material currentProgram pointers while it
 * polls KHR_parallel_shader_compile. Overlapping calls on one renderer can
 * therefore observe an undefined program. Serialize these rare prewarm jobs;
 * normal rendering is unaffected.
 */
export const queueRendererCompilation = (
  renderer: WebGLRenderer,
  scene: Object3D,
  camera: Camera,
  setCompilationVisibility?: (visible: boolean) => void,
): Promise<void> => {
  const previous = rendererCompilationTails.get(renderer) ?? Promise.resolve();
  const current = previous.catch(() => undefined).then(async () => {
    setCompilationVisibility?.(true);
    let compilation: ReturnType<WebGLRenderer['compileAsync']>;
    try {
      compilation = renderer.compileAsync(scene, camera);
    } finally {
      setCompilationVisibility?.(false);
    }
    await compilation;
  });
  rendererCompilationTails.set(renderer, current);
  void current.then(
    () => {
      if (rendererCompilationTails.get(renderer) === current) {
        rendererCompilationTails.delete(renderer);
      }
    },
    () => {
      if (rendererCompilationTails.get(renderer) === current) {
        rendererCompilationTails.delete(renderer);
      }
    },
  );
  return current;
};
