import {
  BoxGeometry,
  ConeGeometry,
  CylinderGeometry,
  Group,
  Mesh,
  MeshStandardMaterial,
  SphereGeometry,
  TorusGeometry,
  type BufferGeometry,
  type Scene,
} from 'three';
import { BOREALIS_VERTICAL_SLICE_ASSETS } from '../gameplay/emergence/BorealisVerticalSliceAssetCatalog';
import type { NpcPresentationState } from '../gameplay/emergence/NpcSimulationSystem';
import { prototypeGlobalToLocalPosition } from '../world/PrototypeWorldPositionAdapter';

interface NpcVisual {
  root: Group;
  bodyMaterial: MeshStandardMaterial;
  alert: Mesh;
  authoredX: number;
  authoredZ: number;
  secondsSinceAuthoredUpdate: number;
  transitionSecondsRemaining: number;
  phase: number;
}

interface NpcTemporaryTarget {
  readonly x: number;
  readonly z: number;
  readonly speed: number;
}

export class BorealisNpcPresenter {
  private readonly root = new Group();
  private readonly visuals = new Map<string, NpcVisual>();
  private readonly temporaryTargets = new Map<string, NpcTemporaryTarget>();
  private readonly geometries: BufferGeometry[] = [
    new SphereGeometry(0.22, 10, 8),
    new SphereGeometry(0.16, 10, 8),
    new ConeGeometry(0.075, 0.16, 6),
    new CylinderGeometry(0.055, 0.055, 0.08, 8),
  ];
  private readonly materials: MeshStandardMaterial[] = [];

  public constructor(
    scene: Scene,
    private readonly sampleSurfaceHeight: (x: number, z: number) => number,
  ) {
    this.root.name = 'Borealis systemic NPC presentation';
    this.root.visible = false;
    scene.add(this.root);
  }

  public setVisible(visible: boolean): void {
    this.root.visible = visible;
  }

  /**
   * Presentation-only movement for authored moments such as Marta greeting
   * the player wherever the parachute touched down. Simulation ownership and
   * the NPC's durable home location remain unchanged.
   */
  public setTemporaryTarget(
    npcId: string,
    target?: Readonly<{ x: number; z: number; speed?: number }>,
  ): void {
    if (!target) {
      this.temporaryTargets.delete(npcId);
      return;
    }
    this.temporaryTargets.set(npcId, {
      x: target.x,
      z: target.z,
      speed: Math.max(0.1, target.speed ?? 1.35),
    });
  }

  public getPresentedPosition(
    npcId: string,
  ): Readonly<{ x: number; z: number }> | undefined {
    const position = this.visuals.get(npcId)?.root.position;
    return position ? { x: position.x, z: position.z } : undefined;
  }

  public update(
    states: readonly NpcPresentationState[],
    deltaSeconds: number,
    focus?: Readonly<{ x: number; z: number }>,
  ): void {
    const visibleIds = new Set(
      states
        .map((state) => {
          const local = prototypeGlobalToLocalPosition(state.travel.worldPosition);
          const distanceSquared = focus
            ? (local.x - focus.x) ** 2 + (local.z - focus.z) ** 2
            : 0;
          return { npcId: state.npcId, distanceSquared };
        })
        .filter((candidate) => !focus || candidate.distanceSquared <= 180 ** 2)
        .sort((a, b) => a.distanceSquared - b.distanceSquared || a.npcId.localeCompare(b.npcId))
        .slice(0, 24)
        .map((candidate) => candidate.npcId),
    );
    for (const [npcId, visual] of this.visuals) {
      visual.root.visible = visibleIds.has(npcId);
    }
    for (const state of states) {
      if (!visibleIds.has(state.npcId)) continue;
      let visual = this.visuals.get(state.npcId);
      if (!visual) visual = this.createVisual(state);
      const authored = prototypeGlobalToLocalPosition(state.travel.worldPosition);
      const temporaryTarget = this.temporaryTargets.get(state.npcId);
      const local = temporaryTarget ?? authored;
      visual.secondsSinceAuthoredUpdate += Math.max(0, deltaSeconds);
      if (
        Math.abs(authored.x - visual.authoredX) > 0.0001 ||
        Math.abs(authored.z - visual.authoredZ) > 0.0001
      ) {
        // WorldSimulation advances NPC travel on a deliberately inexpensive
        // fixed tick. Retain that authoritative destination, but spend the
        // observed tick interval travelling toward it instead of displaying
        // each two-second update as an A/B teleport.
        visual.transitionSecondsRemaining = Math.min(
          2,
          Math.max(0.25, visual.secondsSinceAuthoredUpdate),
        );
        visual.secondsSinceAuthoredUpdate = 0;
        visual.authoredX = authored.x;
        visual.authoredZ = authored.z;
      }
      const targetDistance = Math.hypot(
        local.x - visual.root.position.x,
        local.z - visual.root.position.z,
      );
      const beforeX = visual.root.position.x;
      const beforeZ = visual.root.position.z;
      if (temporaryTarget) {
        const step = Math.min(
          targetDistance,
          temporaryTarget.speed * Math.max(0, deltaSeconds),
        );
        const scale = step / Math.max(0.0001, targetDistance);
        visual.root.position.x += (local.x - visual.root.position.x) * scale;
        visual.root.position.z += (local.z - visual.root.position.z) * scale;
      } else {
        const blend = targetDistance > 100
          ? 1
          : Math.min(
              1,
              Math.max(0, deltaSeconds) /
                Math.max(0.0001, visual.transitionSecondsRemaining),
            );
        visual.root.position.x += (local.x - visual.root.position.x) * blend;
        visual.root.position.z += (local.z - visual.root.position.z) * blend;
        visual.transitionSecondsRemaining = Math.max(
          0,
          visual.transitionSecondsRemaining - Math.max(0, deltaSeconds),
        );
      }
      const dx = visual.root.position.x - beforeX;
      const dz = visual.root.position.z - beforeZ;
      const moving = dx * dx + dz * dz > 0.0000001;
      if (moving) {
        const targetYaw = Math.atan2(dx, dz);
        const yawDelta = Math.atan2(
          Math.sin(targetYaw - visual.root.rotation.y),
          Math.cos(targetYaw - visual.root.rotation.y),
        );
        visual.root.rotation.y += yawDelta *
          (1 - Math.exp(-Math.max(0, deltaSeconds) * 12));
      }
      visual.phase += moving ? Math.max(0, deltaSeconds) * 7 : 0;
      const bob = moving ? Math.sin(visual.phase) * 0.018 : 0;
      visual.root.position.y = this.sampleSurfaceHeight(
        visual.root.position.x,
        visual.root.position.z,
      ) + bob;
      visual.alert.visible = state.travel.status === 'STRANDED';
      visual.bodyMaterial.emissiveIntensity = state.travel.status === 'STRANDED' ? 0.12 : 0;
    }
  }

  public dispose(): void {
    this.geometries.forEach((geometry) => geometry.dispose());
    this.materials.forEach((material) => material.dispose());
    this.root.removeFromParent();
  }

  private createVisual(state: NpcPresentationState): NpcVisual {
    const root = new Group();
    root.name = `${state.displayName} systemic NPC`;
    if (state.npcId === 'npc-marta-shopkeeper') {
      root.userData.assetBankId = BOREALIS_VERTICAL_SLICE_ASSETS.marta.id;
    }
    root.scale.setScalar(state.scale * 1.82);
    const bodyMaterial = this.material(state.color, 0.82, state.color);
    const dark = this.material(0x1d292b, 0.9);
    const beak = this.material(0xe5a13d, 0.72);
    const alertMaterial = this.material(0xe65a3b, 0.45, 0xff2c12);
    const body = new Mesh(this.geometries[0]!, bodyMaterial);
    body.scale.set(0.82, 1.22, 0.72);
    body.position.y = 0.28;
    const head = new Mesh(this.geometries[1]!, dark);
    head.position.y = 0.55;
    const bill = new Mesh(this.geometries[2]!, beak);
    bill.rotation.x = Math.PI / 2;
    bill.position.set(0, 0.54, 0.18);
    const alert = new Mesh(this.geometries[3]!, alertMaterial);
    alert.position.y = 0.86;
    alertMaterial.emissiveIntensity = 0.9;
    root.add(body, head, bill, alert);
    if (state.npcId === 'npc-marta-shopkeeper') {
      const scarfMaterial = this.material(0xf0b246, 0.74);
      const capMaterial = this.material(0x385c68, 0.82);
      const scarfGeometry = new TorusGeometry(0.17, 0.035, 6, 12);
      const scarfTailGeometry = new BoxGeometry(0.075, 0.25, 0.035);
      const capGeometry = new ConeGeometry(0.18, 0.2, 10);
      this.geometries.push(scarfGeometry, scarfTailGeometry, capGeometry);
      const scarf = new Mesh(scarfGeometry, scarfMaterial);
      scarf.rotation.x = Math.PI / 2;
      scarf.position.set(0, 0.43, 0);
      const scarfTail = new Mesh(scarfTailGeometry, scarfMaterial);
      scarfTail.position.set(0.12, 0.33, -0.08);
      scarfTail.rotation.z = -0.24;
      const cap = new Mesh(capGeometry, capMaterial);
      cap.position.y = 0.73;
      cap.rotation.z = -0.06;
      root.add(scarf, scarfTail, cap);
    }
    this.root.add(root);
    const local = prototypeGlobalToLocalPosition(state.travel.worldPosition);
    root.position.set(
      local.x,
      this.sampleSurfaceHeight(local.x, local.z),
      local.z,
    );
    const visual = {
      root,
      bodyMaterial,
      alert,
      authoredX: local.x,
      authoredZ: local.z,
      secondsSinceAuthoredUpdate: 0,
      transitionSecondsRemaining: 0,
      phase: 0,
    };
    this.visuals.set(state.npcId, visual);
    return visual;
  }

  private material(color: number, roughness: number, emissive = 0x000000): MeshStandardMaterial {
    const material = new MeshStandardMaterial({ color, roughness, metalness: 0.01, emissive });
    this.materials.push(material);
    return material;
  }
}
