import { Box3, Color, DynamicDrawUsage, Group, InstancedBufferAttribute, InstancedMesh, Matrix4, Mesh, MeshStandardMaterial, Sphere,
  type Object3D, type Quaternion, type Scene, type Vector3 } from 'three';
import type { IsolationRenderScope } from '../performance/ScenePerformanceIsolation';
import { constructionInstanceAppearance } from './ConstructionInstanceAppearance';
import { SIMPLE_ROOF_IDS } from '../survival/build-v3/SurvivalSimpleRoof';

export interface ConstructionInstanceSource {
  root: Object3D; popSeconds: number; assemblySeconds: number; cameraOpacity: number; warningAppearanceAmount: number;
  piece: { id: string; definitionId: string; revision: number; paintId: string; boundRuneId?: unknown;
    combustion?: { burningSeconds?: number; charred?: number; collapseWarningSeconds?: number } };
}
type Source = ConstructionInstanceSource;
interface Slot { source: Mesh; batch: Batch; index: number; matrix: Matrix4; active: boolean; color: Color; emission: Color }
interface Batch { mesh: InstancedMesh; slots: (Slot | undefined)[]; active: number; dirty: boolean; appearanceDirty?: boolean }
interface Record { root: Object3D; revision: number; paint: string; slots: Slot[];
  position: Vector3; scale: Vector3; quaternion: Quaternion }
const owners = new WeakMap<Scene, Set<ConstructionStaticInstances>>();
// Deliberately exclude articulated, emissive, burning and individually clipped
// parts. The exact original object remains available to picking and physics.
const STATIC_IDS = new Set([...SIMPLE_ROOF_IDS,'TIMBER_TABLE','TIMBER_CHAIR','TIMBER_SHELF',
  'LOG_FOUNDATION','TIMBER_FLOOR','LOG_POST','LOG_WALL_STRAIGHT','LOG_WALL_45',
  'SURVIVAL_RECOVERED_BUILD_BUNDLE_01',
  'LOG_BEAM','TIMBER_STAIRS','ROOF_CROSS_BEAM','ROOF_SPINE_BEAM','ROOF_RIDGE_BEAM',
  'ROOF_RIDGE_POST','ROOF_SUPPORT_POST','ROOF_RAFTER','ROOF_BRACE','ROOF_BATTEN']);

/** Presentation-only batching. Every change to source visibility is scoped to
 * an actual render and restored in finally, including shadow/depth passes.
 * Stable piece IDs, authority, collision, raycasts and save state are untouched. */
export class ConstructionStaticInstances {
  public enabled = true;
  public readonly root = new Group();
  private readonly records = new Map<string, Record>();
  private readonly groups = new Map<string, Batch[]>();
  private readonly zero = new Matrix4().makeScale(0,0,0);
  private readonly inverse = new Matrix4();
  private readonly articulatedMatrix = new Matrix4();
  private readonly batches = new Set<Batch>();
  private readonly box = new Box3();
  private readonly color = new Color();
  public stats = { sourceDraws: 0, batchDraws: 0, instances: 0 };

  public constructor(private readonly scene: Scene, owner: Object3D, private readonly sources: () => Iterable<Source>,
    private readonly appearance: 'STATIC' | 'EFFECTS' = 'STATIC') {
    this.root.name = appearance === 'STATIC' ? 'Construction static instance batches' : 'Construction effect instance batches'; owner.add(this.root);
    const list=owners.get(scene)??new Set();list.add(this);owners.set(scene,list);
  }

  private release(record: Record): void {
    for(const slot of record.slots) {
      if(slot.active)slot.batch.active--;
      slot.batch.slots[slot.index]=undefined;
      slot.batch.mesh.userData.survivalStaticInstancePieces[slot.index]=undefined;
      slot.batch.mesh.setMatrixAt(slot.index,this.zero);slot.batch.dirty=true;
    }
  }

  private register(source: Source): Record {
    source.root.updateWorldMatrix(true,true);this.root.updateWorldMatrix(true,false);
    this.inverse.copy(this.root.matrixWorld).invert();
    const record:Record={root:source.root,revision:source.piece.revision,paint:source.piece.paintId,slots:[],
      position:source.root.position.clone(),scale:source.root.scale.clone(),quaternion:source.root.quaternion.clone()};
    if(this.appearance === 'STATIC' && !STATIC_IDS.has(source.piece.definitionId))return record;
    const cell=`${Math.floor(source.root.position.x/16)},${Math.floor(source.root.position.z/16)}`;
    const visit = (object: Object3D): void => {
      if(!(object instanceof Mesh)||object instanceof InstancedMesh||Array.isArray(object.material)||'isSkinnedMesh' in object||object.morphTargetInfluences)return;
      // Hiding a source mesh also hides its non-instanced children. Keep
      // composite parents on the original path; their leaf meshes may batch.
      if(object.children.length > 0)return;
      // Three's instanced front-face handling does not support mirrored instance
      // matrices. Keep those on their exact original per-object render path.
      if(object.matrixWorld.determinant()<0)return;
      const m=object.material;
      if(!(m instanceof MeshStandardMaterial)||m.transparent||m.opacity!==1||!m.userData.survivalBuildOwnedMaterial)return;
      // Source identity includes its authored shader/textures. Colour variants
      // form separate tiny batches, not a new universal material approximation.
      const identity=m.userData.survivalBuildSourceMaterial as string|undefined;
      if(!identity)return;
      const key=[cell,object.geometry.uuid,identity,...(this.appearance === 'STATIC' ? [m.color.getHex(),m.emissive.getHex(),m.emissiveIntensity] : []),
        m.roughness,m.metalness,m.side,object.castShadow,object.receiveShadow,object.layers.mask,object.renderOrder].join(':');
      const group=this.groups.get(key)??[];
      let batch=group.find(b=>b.slots.length<64||b.slots.includes(undefined));
      if(!batch) {
        const material=this.appearance === 'EFFECTS' ? constructionInstanceAppearance(m) : m.clone();
        if(this.appearance === 'STATIC'){material.onBeforeCompile=m.onBeforeCompile;material.customProgramCacheKey=m.customProgramCacheKey;}
        const geometry=this.appearance === 'EFFECTS' ? object.geometry.clone() : object.geometry;
        const mesh=new InstancedMesh(geometry,material,64);
        if(this.appearance === 'EFFECTS'){
          mesh.instanceColor=new InstancedBufferAttribute(new Float32Array(64*3).fill(1),3).setUsage(DynamicDrawUsage);
          geometry.setAttribute('aBuildEmission',new InstancedBufferAttribute(new Float32Array(64*3),3).setUsage(DynamicDrawUsage));
        }
        mesh.raycast=()=>{}; // render proxy only; original per-piece meshes own picking
        mesh.name='Static construction · '+source.piece.definitionId;mesh.visible=false;
        mesh.castShadow=object.castShadow;mesh.receiveShadow=object.receiveShadow;mesh.layers.mask=object.layers.mask;
        mesh.renderOrder=object.renderOrder;mesh.instanceMatrix.setUsage(DynamicDrawUsage);
        mesh.userData.survivalStaticInstancePieces=[];
        batch={mesh,slots:[],active:0,dirty:true};group.push(batch);this.groups.set(key,group);
        this.batches.add(batch);this.root.add(mesh);
      }
      const free=batch.slots.indexOf(undefined),index=free<0?batch.slots.length:free;
      const slot:Slot={source:object,batch,index,matrix:new Matrix4().multiplyMatrices(this.inverse,object.matrixWorld),active:false,
        color:new Color(-1,-1,-1),emission:new Color(-1,-1,-1)};
      batch.slots[index]=slot;batch.mesh.count=batch.slots.length;
      batch.mesh.setMatrixAt(index,this.zero);batch.mesh.userData.survivalStaticInstancePieces[index]=source.piece.id;
      batch.dirty=true;record.slots.push(slot);
    };
    // An open shutter can hide a child that becomes visible later. Capture
    // those render slots too; visibility is checked afresh on each render.
    if(this.appearance === 'EFFECTS') source.root.traverse(visit);
    else source.root.traverseVisible(visit);
    return record;
  }

  public apply(scope: IsolationRenderScope): void {
    this.stats.sourceDraws=0;this.stats.batchDraws=0;this.stats.instances=0;
    if(!this.enabled)return;
    for(let ancestor:Object3D|null=this.root;ancestor;ancestor=ancestor.parent)if(!ancestor.visible)return;
    const seen=new Set<string>();
    for(const source of this.sources()) {
      const p=source.piece;seen.add(p.id);
      const eligible=source.root.visible&&source.popSeconds<=0&&source.assemblySeconds<=0&&source.cameraOpacity>=.995&&
        source.warningAppearanceAmount===0&&!p.boundRuneId&&
        (this.appearance === 'EFFECTS' || (!p.combustion?.burningSeconds&&!p.combustion?.charred&&!p.combustion?.collapseWarningSeconds))&&
        !source.root.userData.survivalBatchExcluded && !source.root.userData.survivalDamageActive;
      let record=this.records.get(p.id);
      if(record&&(record.root!==source.root||record.revision!==p.revision||record.paint!==p.paintId||
        !record.position.equals(source.root.position)||!record.scale.equals(source.root.scale)||!record.quaternion.equals(source.root.quaternion))) {
        this.release(record);this.records.delete(p.id);record=undefined;
      }
      // Capture final assembly transforms and rest materials, never a tiny pop
      // animation or coloured hover state. Dynamic parts use their originals.
      if(!record&&eligible){record=this.register(source);this.records.set(p.id,record);}
      if(!record)continue;
      const articulated = this.appearance === 'EFFECTS' && !STATIC_IDS.has(p.definitionId);
      if(eligible && articulated){
        source.root.updateWorldMatrix(true,true);this.root.updateWorldMatrix(true,false);
        this.inverse.copy(this.root.matrixWorld).invert();
      }
      for(const slot of record.slots){
        let visible = eligible;
        if(visible && this.appearance === 'EFFECTS'){
          for(let child:Object3D|null=slot.source;child && child!==source.root;child=child.parent)
            if(!child.visible){visible=false;break;}
        }
        if(visible && articulated){
          this.articulatedMatrix.multiplyMatrices(this.inverse,slot.source.matrixWorld);
          if(!slot.matrix.equals(this.articulatedMatrix)){
            slot.matrix.copy(this.articulatedMatrix);slot.batch.dirty=true;
            slot.batch.mesh.setMatrixAt(slot.index,slot.matrix);
          }
        }
        if(slot.active!==visible){
          slot.active=visible;slot.batch.active+=visible?1:-1;slot.batch.dirty=true;
          slot.batch.mesh.setMatrixAt(slot.index,visible?slot.matrix:this.zero);
        }
      }
      if(eligible && this.appearance === 'EFFECTS') for(const slot of record.slots){
        const m=slot.source.material as MeshStandardMaterial;
        if(!slot.color.equals(m.color)){
          slot.color.copy(m.color);slot.batch.mesh.setColorAt(slot.index,m.color);slot.batch.appearanceDirty=true;
        }
        this.color.copy(m.emissive).multiplyScalar(m.emissiveIntensity);
        if(!slot.emission.equals(this.color)){
          slot.emission.copy(this.color);
          slot.batch.mesh.geometry.getAttribute('aBuildEmission').setXYZ(slot.index,this.color.r,this.color.g,this.color.b);
          slot.batch.appearanceDirty=true;
        }
      }
    }
    for(const [id,record]of this.records)if(!seen.has(id)){this.release(record);this.records.delete(id);}
    for(const batch of this.batches) {
      if(batch.slots.every(slot=>!slot)) {
        batch.mesh.removeFromParent();batch.mesh.dispose();(batch.mesh.material as MeshStandardMaterial).dispose();
        if(this.appearance === 'EFFECTS')batch.mesh.geometry.dispose();this.batches.delete(batch);
        for(const [key,group]of this.groups)if(group.includes(batch)){
          group.splice(group.indexOf(batch),1);if(!group.length)this.groups.delete(key);break;
        }
        continue;
      }
      if(batch.appearanceDirty){batch.mesh.instanceColor!.needsUpdate=true;batch.mesh.geometry.getAttribute('aBuildEmission').needsUpdate=true;batch.appearanceDirty=false;}
      if(batch.dirty){
        batch.mesh.instanceMatrix.needsUpdate=true;
        batch.mesh.geometry.computeBoundingBox();
        const bounds=batch.mesh.boundingBox??new Box3();bounds.makeEmpty();
        for(const slot of batch.slots)if(slot?.active)
          bounds.union(this.box.copy(batch.mesh.geometry.boundingBox!).applyMatrix4(slot.matrix));
        batch.mesh.boundingBox=bounds;batch.mesh.boundingSphere??=new Sphere();
        bounds.getBoundingSphere(batch.mesh.boundingSphere);batch.dirty=false;
      }
      if(batch.active<2)continue;
      scope.set(batch.mesh,'visible',true);this.stats.batchDraws++;
      for (const slot of batch.slots) if (slot?.active) {
        // Camera optics run in onBeforeRender, inside this scope. Their CPU
        // rays still use the source geometry, not the render-only proxy.
        scope.set(slot.source.userData, 'survivalRenderInstanced', true);
        scope.set(slot.source, 'visible', false);
        this.stats.sourceDraws++;
        this.stats.instances++;
      }
    }
  }

  public dispose(): void {
    owners.get(this.scene)?.delete(this);
    for(const batch of this.batches){batch.mesh.dispose();(batch.mesh.material as MeshStandardMaterial).dispose();if(this.appearance === 'EFFECTS')batch.mesh.geometry.dispose();}
    this.root.removeFromParent();this.batches.clear();this.groups.clear();this.records.clear();
  }
}

export function applyConstructionInstances(scene: Scene, scope: IsolationRenderScope): void {
  for(const owner of owners.get(scene)??[])owner.apply(scope);
}

export function constructionInstanceStats(scene: Scene): { sourceDraws: number; batchDraws: number; instances: number } {
  const total={sourceDraws:0,batchDraws:0,instances:0};
  for(const owner of owners.get(scene)??[]){total.sourceDraws+=owner.stats.sourceDraws;total.batchDraws+=owner.stats.batchDraws;total.instances+=owner.stats.instances;}
  return total;
}
