import { HEART_SANCTUARY, sanctuaryWalkable } from './SanctuaryWorld';

export interface SanctuaryObstacle {
  id: string; x: number; z: number; halfWidth: number; halfDepth: number; yaw: number;
}

/** A short melee segment cannot pass through a built barrier, even if the
 * camera can see over it. Navigation and interaction use the same OBB frame. */
export function sanctuarySegmentBlocked(ax: number, az: number, bx: number, bz: number,
  obstacles: readonly SanctuaryObstacle[]): boolean {
  return obstacles.some(o => {
    const c = Math.cos(o.yaw), s = Math.sin(o.yaw);
    const x = (ax - o.x) * c - (az - o.z) * s;
    const z = (ax - o.x) * s + (az - o.z) * c;
    const dx = (bx - ax) * c - (bz - az) * s;
    const dz = (bx - ax) * s + (bz - az) * c;
    let near = 0, far = 1;
    for (const [p, d, extent] of [[x, dx, o.halfWidth], [z, dz, o.halfDepth]]) {
      if (Math.abs(d!) < .00001) { if (Math.abs(p!) > extent!) return false; continue; }
      const a = (-extent! - p!) / d!, b = (extent! - p!) / d!;
      near = Math.max(near, Math.min(a, b)); far = Math.min(far, Math.max(a, b));
      if (near > far) return false;
    }
    return far > .01 && near < .99;
  });
}

/** Small shared reverse-Dijkstra field. 4,042 cells, rebuilt only on topology
 * change. All husks share it; no per-actor whole-world path search. Walls are
 * expensive traversals, allowing the field to choose a breach when sealed. */
export class SanctuaryNavigation {
  readonly width = 47;
  readonly height = 86;
  readonly distance = new Float32Array(this.width * this.height);
  readonly blockers: (string | undefined)[] = new Array(this.distance.length);
  private readonly allowed = new Uint8Array(this.distance.length);
  private signature = '';
  public rebuilds = 0;

  constructor() {
    for (let i = 0; i < this.allowed.length; i++) {
      const p = this.point(i);
      this.allowed[i] = sanctuaryWalkable(p.x - HEART_SANCTUARY.x, p.z - HEART_SANCTUARY.z, .4) ? 1 : 0;
    }
  }

  point(i: number): { x: number; z: number } {
    return { x: HEART_SANCTUARY.x + i % this.width - 23,
      z: HEART_SANCTUARY.z + Math.floor(i / this.width) - 7 };
  }

  index(x: number, z: number): number {
    const u = Math.round(x - HEART_SANCTUARY.x) + 23;
    const v = Math.round(z - HEART_SANCTUARY.z) + 7;
    return u < 0 || u >= this.width || v < 0 || v >= this.height ? -1 : v * this.width + u;
  }

  rebuild(obstacles: readonly SanctuaryObstacle[]): void {
    const signature = obstacles.map(o => `${o.id}:${o.x}:${o.z}:${o.yaw}:${o.halfWidth}:${o.halfDepth}`).join('|');
    if (this.rebuilds && signature === this.signature) return;
    this.signature = signature;
    this.rebuilds++;
    this.blockers.fill(undefined);
    for (const o of obstacles) {
      const extent = Math.hypot(o.halfWidth, o.halfDepth) + .5;
      const cos = Math.cos(o.yaw), sin = Math.sin(o.yaw);
      for (let v = Math.max(0, Math.floor(o.z - HEART_SANCTUARY.z + 7 - extent));
        v <= Math.min(this.height - 1, Math.ceil(o.z - HEART_SANCTUARY.z + 7 + extent)); v++) {
        for (let u = Math.max(0, Math.floor(o.x - HEART_SANCTUARY.x + 23 - extent));
          u <= Math.min(this.width - 1, Math.ceil(o.x - HEART_SANCTUARY.x + 23 + extent)); u++) {
          const dx = HEART_SANCTUARY.x + u - 23 - o.x;
          const dz = HEART_SANCTUARY.z + v - 7 - o.z;
          if (Math.abs(dx * cos - dz * sin) <= o.halfWidth + .55 &&
            Math.abs(dx * sin + dz * cos) <= o.halfDepth + .55) this.blockers[v * this.width + u] = o.id;
        }
      }
    }
    this.distance.fill(Infinity);
    const heap: { i: number; d: number }[] = [];
    const push = (i: number, d: number) => {
      let cursor = heap.length;
      heap.push({ i, d });
      while (cursor > 0) {
        const parent = (cursor - 1) >> 1;
        if (heap[parent]!.d <= d) break;
        heap[cursor] = heap[parent]!; cursor = parent;
      }
      heap[cursor] = { i, d };
    };
    for (let i = 0; i < this.allowed.length; i++) {
      const p = this.point(i);
      if (this.allowed[i] && Math.hypot(p.x - HEART_SANCTUARY.x, p.z - HEART_SANCTUARY.z) < 3.5) {
        this.distance[i] = 0; push(i, 0);
      }
    }
    while (heap.length) {
      const first = heap[0]!;
      const tail = heap.pop()!;
      if (heap.length) {
        let cursor = 0;
        while (cursor * 2 + 1 < heap.length) {
          let child = cursor * 2 + 1;
          if (child + 1 < heap.length && heap[child + 1]!.d < heap[child]!.d) child++;
          if (heap[child]!.d >= tail.d) break;
          heap[cursor] = heap[child]!; cursor = child;
        }
        heap[cursor] = tail;
      }
      if (first.d > this.distance[first.i]!) continue;
      for (const n of this.neighbours(first.i)) {
        if (!this.allowed[n]) continue;
        const d = first.d + (this.blockers[n] ? 36 : 1);
        if (d < this.distance[n]!) { this.distance[n] = d; push(n, d); }
      }
    }
  }

  private neighbours(i: number): number[] {
    const result: number[] = [];
    if (i % this.width) result.push(i - 1);
    if (i % this.width < this.width - 1) result.push(i + 1);
    if (i >= this.width) result.push(i - this.width);
    if (i < this.width * (this.height - 1)) result.push(i + this.width);
    return result;
  }

  next(x: number, z: number): { x: number; z: number; blocker?: string } | undefined {
    const i = this.index(x, z);
    if (i < 0) return undefined;
    let best = i, cost = this.distance[i]!;
    for (const n of this.neighbours(i)) {
      if (this.distance[n]! < cost) { best = n; cost = this.distance[n]!; }
    }
    if (!Number.isFinite(cost)) return undefined;
    return { ...this.point(best), blocker: this.blockers[best] ?? this.blockers[i] };
  }
}
