/**
 * Stable authored anchors for Borealis gameplay.
 *
 * Coordinates are deliberately provisional while the final four-region map is
 * being drawn. Gameplay, quests and UI should reference an anchor ID instead
 * of copying these coordinates. Moving the town then becomes a data migration
 * rather than a quest rewrite.
 */

export const BOREALIS_WORLD_LAYOUT_VERSION = 6;

export type BorealisWorldAnchorId =
  | 'borealis.arrival.drop-entry'
  | 'borealis.arrival.landing'
  | 'borealis.central-square'
  | 'borealis.harbor.land-access'
  | 'borealis.harbor.legacy-deployment'
  | 'borealis.depot.abandoned'
  | 'borealis.depot.starter-tractor'
  | 'borealis.station'
  | 'borealis.station.entrance'
  | 'borealis.quarry.north-ridge'
  | 'borealis.season.spring-garden'
  | 'borealis.season.summer-meadow'
  | 'borealis.season.autumn-orchard';

export interface BorealisWorldAnchor {
  readonly id: BorealisWorldAnchorId;
  readonly displayName: string;
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly tags: readonly string[];
  /** True until the final user-authored four-season layout is imported. */
  readonly provisional: boolean;
}

const anchor = (
  id: BorealisWorldAnchorId,
  displayName: string,
  x: number,
  z: number,
  heading: number,
  tags: readonly string[],
): BorealisWorldAnchor => Object.freeze({
  id,
  displayName,
  x,
  z,
  heading,
  tags: Object.freeze([...tags]),
  provisional: true,
});

