const ANCHOR_BY_ID: ReadonlyMap<BorealisWorldAnchorId, BorealisWorldAnchor> =
  new Map(
    Object.values(BOREALIS_WORLD_ANCHORS).map((value) => [value.id, value]),
  );

export const borealisWorldAnchor = (
  id: BorealisWorldAnchorId,
): BorealisWorldAnchor => {
  const value = ANCHOR_BY_ID.get(id);
  if (!value) throw new Error(`Unknown Borealis world anchor: ${id}`);
  return value;
};

