import { DAY_LENGTH_SECONDS } from './DayNightSystem';
import { clamp, smoothstep } from '../utils/math';

export type CelestialModel = 'LEGACY_SUN_MOON' | 'AERION_SIRION';

/**
 * The experiment is intentionally one switch away from the shipped
 * sun-and-moon sky. Saves remember the selection, while old saves default to
 * the twin-star story until playtesting says otherwise.
 */
export const DEFAULT_CELESTIAL_MODEL: CelestialModel = 'AERION_SIRION';

export const AERION_DAYS_PER_RESONANCE = 4;
export const SIRION_DAYS_PER_RESONANCE = 7;
export const CELESTIAL_RESONANCE_SECONDS =
  DAY_LENGTH_SECONDS * AERION_DAYS_PER_RESONANCE;
export const SIRION_DAY_LENGTH_SECONDS =
  CELESTIAL_RESONANCE_SECONDS / SIRION_DAYS_PER_RESONANCE;

export interface TwinStarCycleState {
  /** Aerion remains the authored 45-minute day clock. */
  aerionProgress: number;
  /** Sirion completes seven orbits while Aerion completes four. */
  sirionProgress: number;
  resonanceProgress: number;
  aerionDay: number;
  /** Alternating wounded-orbit passage: high/paler or low/ember-rich. */
  aerionPassage: 'HIGH' | 'LOW';
  sirionDay: number;
  aerionAzimuth: number;
  aerionHeight: number;
  sirionAzimuth: number;
  sirionHeight: number;
  aerionAboveHorizon: number;
  sirionAboveHorizon: number;
  angularSeparation: number;
  conjunction: number;
  opposition: number;
  overlap: number;
  storyName: string;
}

const TAU = Math.PI * 2;
const SOUTH_AZIMUTH = Math.PI * 0.5;
const EAST_AZIMUTH = 0;

const fract = (value: number): number => value - Math.floor(value);

const celestialDirection = (
  azimuth: number,
  height: number,
): Readonly<{ x: number; y: number; z: number }> => {
  const horizontal = Math.sqrt(Math.max(0, 1 - height * height));
  return {
    x: Math.cos(azimuth) * horizontal,
    y: height,
    z: Math.sin(azimuth) * horizontal,
  };
};

/**
 * Resolves the 4:7 resonance without shortening the authored 45-minute day.
 * Four low Aerion passages and seven quicker Sirion passages fit inside the
 * same three-hour macro-cycle, so a normal session still sees several useful
 * overlaps while the complete sky calendar remains slow and memorable.
 */
export const resolveTwinStarCycle = (
  dayTimeSeconds: number,
): TwinStarCycleState => {
  const safeTime = Math.max(0, dayTimeSeconds);
  const aerionAbsoluteDay = safeTime / DAY_LENGTH_SECONDS;
  const sirionAbsoluteDay = safeTime / SIRION_DAY_LENGTH_SECONDS;
  const aerionProgress = fract(aerionAbsoluteDay);
  const aerionPassage: 'HIGH' | 'LOW' =
    Math.floor(aerionAbsoluteDay) % 2 === 0 ? 'HIGH' : 'LOW';
  // The offset gives a newly created world a readable twinlight rather than
  // hiding Sirion below the horizon during the initial evening playtest.
  const sirionProgress = fract(sirionAbsoluteDay + 0.14);
  const resonanceProgress = fract(
    safeTime / CELESTIAL_RESONANCE_SECONDS,
  );

  // Aerion's wounded orbit is deliberately wrong: it rises in the south,
  // scrapes a low arc across the horizon and sets in the east. Its highest
  // point is only about thirteen degrees above the horizon.
  const aerionArc = clamp((aerionProgress - 0.08) / 0.74, 0, 1);
  const aerionOnVisibleArc = aerionProgress >= 0.08 && aerionProgress <= 0.82;
  // The hidden return arc crosses the day boundary. Treat the interval before
  // sunrise as 1.0..1.08 instead of clamping it back to zero; otherwise
  // Aerion teleports from a deep night altitude to just under the horizon at
  // midnight and the complete sky grade snaps into dawn on the same frame.
  const aerionHiddenProgress = aerionProgress > 0.82
    ? (aerionProgress - 0.82) / 0.26
    : (aerionProgress + 1 - 0.82) / 0.26;
  const aerionArcAmplitude = aerionPassage === 'HIGH' ? 0.325 : 0.265;
  const aerionHeight = aerionOnVisibleArc
    ? -0.045 + Math.sin(aerionArc * Math.PI) * aerionArcAmplitude
    : -0.045 - Math.sin(
        clamp(aerionHiddenProgress, 0, 1) * Math.PI,
      ) * 0.12;
  const aerionAzimuth = SOUTH_AZIMUTH +
    (EAST_AZIMUTH - SOUTH_AZIMUTH) * aerionArc +
    Math.sin(resonanceProgress * TAU) * 0.035 +
    Math.sin(aerionArc * Math.PI) *
      (aerionPassage === 'HIGH' ? 0.04 : -0.026);

  // Sirion keeps the old, regular celestial plane. The tilted unit circle
  // rises in the east, culminates toward the south and sets in the west.
  const sirionAngle = sirionProgress * TAU;
  const sirionInclination = 0.49;
  const sirionX = Math.cos(sirionAngle);
  const sirionY = Math.sin(sirionAngle) * Math.sin(sirionInclination) - 0.018;
  const sirionZ = Math.sin(sirionAngle) * Math.cos(sirionInclination);
  const sirionHeight = clamp(sirionY, -0.5, 0.82);
  const sirionAzimuth = Math.atan2(sirionZ, sirionX);

  const aerionAboveHorizon = smoothstep(-0.035, 0.045, aerionHeight);
  const sirionAboveHorizon = smoothstep(-0.035, 0.045, sirionHeight);
  const aerionDirection = celestialDirection(aerionAzimuth, aerionHeight);
  const sirionDirection = celestialDirection(sirionAzimuth, sirionHeight);
  const angularSeparation = Math.acos(clamp(
    aerionDirection.x * sirionDirection.x +
      aerionDirection.y * sirionDirection.y +
      aerionDirection.z * sirionDirection.z,
    -1,
    1,
  ));
  const overlap = aerionAboveHorizon * sirionAboveHorizon;
  const conjunction = overlap * (
    1 - smoothstep(0.045, 0.22, angularSeparation)
  );
  const opposition = overlap * smoothstep(
    Math.PI * 0.72,
    Math.PI * 0.94,
    angularSeparation,
  );

  const storyName = conjunction > 0.35
    ? 'Cinder convergence'
    : opposition > 0.35
      ? 'The divided sky'
      : overlap > 0.25
        ? 'Twinlight'
        : aerionAboveHorizon > 0.2
          ? 'Aerion passage'
          : sirionAboveHorizon > 0.2
            ? 'Sirion vigil'
            : 'Starless hush';

  return {
    aerionProgress,
    sirionProgress,
    resonanceProgress,
    aerionDay: Math.floor(aerionAbsoluteDay) % AERION_DAYS_PER_RESONANCE + 1,
    aerionPassage,
    sirionDay: Math.floor(sirionAbsoluteDay) % SIRION_DAYS_PER_RESONANCE + 1,
    aerionAzimuth,
    aerionHeight,
    sirionAzimuth,
    sirionHeight,
    aerionAboveHorizon,
    sirionAboveHorizon,
    angularSeparation,
    conjunction,
    opposition,
    overlap,
    storyName,
  };
};

export const isCelestialModel = (value: unknown): value is CelestialModel =>
  value === 'LEGACY_SUN_MOON' || value === 'AERION_SIRION';
