import {
  cloneConstructionPlacement,
  sanitizeConstructionBlueprint,
  sanitizeConstructionPlacement,
  type ConstructionBlueprint,
  type ConstructionPalette,
  type ConstructionPlacement,
} from '../../construction/ConstructionBlueprint';
import type { GlobalPosition } from '../../world/GlobalPosition';
import { isGlobalPositionInPartition } from '../../world/GlobalPosition';
import { ICEAWAY_TARGET_WORLD_PARTITION } from '../../world/WorldPartitionTypes';
import {
  playerId,
  serverTick,
  transactionId,
  type PlayerId,
  type ServerTick,
  type TransactionId,
} from '../core/NetworkPrimitives';

export const CONSTRUCTION_REPLICATION_FORMAT_VERSION = 1;
export const MAX_CONSTRUCTION_SITES = 128;
export const MAX_CONSTRUCTION_PIECES_PER_SITE = 1_024;
export const MAX_CONSTRUCTION_PIECES_PER_MESSAGE = 64;

export type ConstructionSiteAccessPolicy =
  | { readonly mode: 'SHARED' }
  | { readonly mode: 'OWNER_ONLY'; readonly ownerPlayerId: PlayerId }
  | { readonly mode: 'HOST_ONLY' };

/** Pass 6.2 replaces DEV_UNLIMITED with canonical inventory reservations. */
export type ConstructionResourcePolicy =
  | { readonly mode: 'DEV_UNLIMITED' }
  | {
      readonly mode: 'AUTHORITY_INVENTORY';
      readonly containerId: string;
      readonly contentRevision: number;
    };

export type ConstructionBlueprintMetadata = Omit<
  ConstructionBlueprint,
  'placements'
>;

export interface ReplicatedConstructionSiteManifest {
  readonly siteId: string;
  readonly anchor: GlobalPosition;
  readonly access: ConstructionSiteAccessPolicy;
  readonly resources: ConstructionResourcePolicy;
  readonly blueprint: ConstructionBlueprintMetadata;
  readonly placementCount: number;
}

export interface ReplicatedConstructionSite {
  readonly siteId: string;
  readonly anchor: GlobalPosition;
  readonly access: ConstructionSiteAccessPolicy;
  readonly resources: ConstructionResourcePolicy;
  readonly blueprint: ConstructionBlueprint;
}

export interface ConstructionSitePieceBatch {
  readonly siteId: string;
  readonly placementOffset: number;
  readonly placements: readonly ConstructionPlacement[];
}

export interface ConstructionStateBaselinePartPayload {
  readonly version: 1;
  readonly kind: 'CONSTRUCTION_STATE_BASELINE';
  readonly formatVersion: number;
  readonly worldDatasetHash: string;
  readonly scope: 'FULL' | 'SITE_RESYNC';
  readonly transferId: string;
  readonly partIndex: number;
  readonly partCount: number;
  readonly serverTick: ServerTick;
  readonly revision: number;
  /** Repeated in every part so each envelope is independently inspectable. */
  readonly sites: readonly ReplicatedConstructionSiteManifest[];
  readonly pieceBatches: readonly ConstructionSitePieceBatch[];
}

export interface ConstructionBlueprintDelta {
  readonly requestId: TransactionId;
  readonly actorPlayerId: PlayerId;
  readonly operation:
    | 'PLACE_PIECE'
    | 'MOVE_PIECES'
    | 'REMOVE_PIECE'
    | 'CONFIGURE_PIECE'
    | 'CONFIGURE_BLUEPRINT';
  readonly siteId: string;
  readonly blueprintId: string;
  readonly baseBlueprintRevision: number;
  readonly blueprintRevision: number;
  readonly upsertedPlacements: readonly ConstructionPlacement[];
  readonly removedPlacementIds: readonly string[];
  readonly metadata?: ConstructionBlueprintMetadata;
  /** Updated canonical resource fence when inventory-backed costs changed. */
  readonly resources?: ConstructionResourcePolicy;
}

export interface ConstructionStateDeltaPayload {
  readonly version: 1;
  readonly kind: 'CONSTRUCTION_STATE_DELTA';
  readonly baseRevision: number;
  readonly revision: number;
  readonly serverTick: ServerTick;
  readonly change: ConstructionBlueprintDelta;
}

export interface ConstructionStateResyncRequestPayload {
  readonly version: 1;
  readonly kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST';
  readonly observedRevision: number;
  readonly scope: 'FULL' | 'SITE';
  readonly siteId?: string;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const boundedString = (value: unknown, maximum = 160): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;

const nonNegativeInteger = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

const clonePosition = (position: Readonly<GlobalPosition>): GlobalPosition => ({
  chunk: { ...position.chunk },
  local: { ...position.local },
});

const sanitizeAccess = (
  input: unknown,
): ConstructionSiteAccessPolicy | undefined => {
  if (!isRecord(input)) return undefined;
  if (input.mode === 'SHARED') return { mode: 'SHARED' };
  if (input.mode === 'HOST_ONLY') return { mode: 'HOST_ONLY' };
  if (input.mode === 'OWNER_ONLY' && boundedString(input.ownerPlayerId)) {
    return { mode: 'OWNER_ONLY', ownerPlayerId: playerId(input.ownerPlayerId) };
  }
  return undefined;
};

const sanitizeResources = (
  input: unknown,
): ConstructionResourcePolicy | undefined => {
  if (!isRecord(input)) return undefined;
  if (input.mode === 'DEV_UNLIMITED') return { mode: 'DEV_UNLIMITED' };
  if (
    input.mode === 'AUTHORITY_INVENTORY' &&
    boundedString(input.containerId) &&
    nonNegativeInteger(input.contentRevision)
  ) {
    return {
      mode: 'AUTHORITY_INVENTORY',
      containerId: input.containerId,
      contentRevision: input.contentRevision,
    };
  }
  return undefined;
};

const sanitizeMetadata = (
  input: unknown,
): ConstructionBlueprintMetadata | undefined => {
  if (!isRecord(input)) return undefined;
  const sanitized = sanitizeConstructionBlueprint({ ...input, placements: [] });
  if (!sanitized) return undefined;
  const { placements: _placements, ...metadata } = sanitized;
  return metadata;
};

const sanitizeManifest = (
  input: unknown,
): ReplicatedConstructionSiteManifest | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.siteId) ||
    !isRecord(input.anchor) ||
    !isRecord(input.anchor.chunk) ||
    !isRecord(input.anchor.local) ||
    !nonNegativeInteger(input.placementCount) ||
    input.placementCount > MAX_CONSTRUCTION_PIECES_PER_SITE
  ) return undefined;
  const anchor = input.anchor as unknown as GlobalPosition;
  if (!isGlobalPositionInPartition(ICEAWAY_TARGET_WORLD_PARTITION, anchor)) {
    return undefined;
  }
  const access = sanitizeAccess(input.access);
  const resources = sanitizeResources(input.resources);
  const blueprint = sanitizeMetadata(input.blueprint);
  if (!access || !resources || !blueprint) return undefined;
  return {
    siteId: input.siteId,
    anchor: clonePosition(anchor),
    access,
    resources,
    blueprint,
    placementCount: input.placementCount,
  };
};

const sanitizePieceBatch = (
  input: unknown,
): ConstructionSitePieceBatch | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.siteId) ||
    !nonNegativeInteger(input.placementOffset) ||
    !Array.isArray(input.placements) ||
    input.placements.length > MAX_CONSTRUCTION_PIECES_PER_MESSAGE
  ) return undefined;
  const placements: ConstructionPlacement[] = [];
  const ids = new Set<string>();
  for (const raw of input.placements) {
    const placement = sanitizeConstructionPlacement(raw);
    if (!placement || ids.has(placement.id)) return undefined;
    ids.add(placement.id);
    placements.push(placement);
  }
  return {
    siteId: input.siteId,
    placementOffset: input.placementOffset,
    placements,
  };
};

export const validateConstructionStateBaselinePartPayload = (
  input: unknown,
): ConstructionStateBaselinePartPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'CONSTRUCTION_STATE_BASELINE' ||
    input.formatVersion !== CONSTRUCTION_REPLICATION_FORMAT_VERSION ||
    !boundedString(input.worldDatasetHash, 256) ||
    (input.scope !== 'FULL' && input.scope !== 'SITE_RESYNC') ||
    !boundedString(input.transferId) ||
    !nonNegativeInteger(input.partIndex) ||
    !nonNegativeInteger(input.partCount) ||
    input.partCount < 1 ||
    input.partCount > 4_096 ||
    input.partIndex >= input.partCount ||
    !nonNegativeInteger(input.serverTick) ||
    !nonNegativeInteger(input.revision) ||
    !Array.isArray(input.sites) ||
    input.sites.length > MAX_CONSTRUCTION_SITES ||
    !Array.isArray(input.pieceBatches) ||
    input.pieceBatches.length > MAX_CONSTRUCTION_SITES
  ) return undefined;
  const sites: ReplicatedConstructionSiteManifest[] = [];
  const siteIds = new Set<string>();
  for (const raw of input.sites) {
    const site = sanitizeManifest(raw);
    if (!site || siteIds.has(site.siteId)) return undefined;
    siteIds.add(site.siteId);
    sites.push(site);
  }
  const pieceBatches: ConstructionSitePieceBatch[] = [];
  for (const raw of input.pieceBatches) {
    const batch = sanitizePieceBatch(raw);
    if (!batch || !siteIds.has(batch.siteId)) return undefined;
    pieceBatches.push(batch);
  }
  return {
    version: 1,
    kind: 'CONSTRUCTION_STATE_BASELINE',
    formatVersion: CONSTRUCTION_REPLICATION_FORMAT_VERSION,
    worldDatasetHash: input.worldDatasetHash,
    scope: input.scope,
    transferId: input.transferId,
    partIndex: input.partIndex,
    partCount: input.partCount,
    serverTick: serverTick(input.serverTick),
    revision: input.revision,
    sites,
    pieceBatches,
  };
};

const OPERATIONS = new Set<ConstructionBlueprintDelta['operation']>([
  'PLACE_PIECE',
  'MOVE_PIECES',
  'REMOVE_PIECE',
  'CONFIGURE_PIECE',
  'CONFIGURE_BLUEPRINT',
]);

const sanitizeDelta = (
  input: unknown,
): ConstructionBlueprintDelta | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.requestId) ||
    !boundedString(input.actorPlayerId) ||
    typeof input.operation !== 'string' ||
    !OPERATIONS.has(input.operation as ConstructionBlueprintDelta['operation']) ||
    !boundedString(input.siteId) ||
    !boundedString(input.blueprintId) ||
    !nonNegativeInteger(input.baseBlueprintRevision) ||
    !nonNegativeInteger(input.blueprintRevision) ||
    input.blueprintRevision !== input.baseBlueprintRevision + 1 ||
    !Array.isArray(input.upsertedPlacements) ||
    input.upsertedPlacements.length > MAX_CONSTRUCTION_PIECES_PER_MESSAGE ||
    !Array.isArray(input.removedPlacementIds) ||
    input.removedPlacementIds.length > MAX_CONSTRUCTION_PIECES_PER_MESSAGE
  ) return undefined;
  const upsertedPlacements: ConstructionPlacement[] = [];
  const upsertedIds = new Set<string>();
  for (const raw of input.upsertedPlacements) {
    const placement = sanitizeConstructionPlacement(raw);
    if (!placement || upsertedIds.has(placement.id)) return undefined;
    upsertedIds.add(placement.id);
    upsertedPlacements.push(placement);
  }
  const removedPlacementIds: string[] = [];
  const removedIds = new Set<string>();
  for (const id of input.removedPlacementIds) {
    if (!boundedString(id) || removedIds.has(id) || upsertedIds.has(id)) {
      return undefined;
    }
    removedIds.add(id);
    removedPlacementIds.push(id);
  }
  const metadata = input.metadata === undefined
    ? undefined
    : sanitizeMetadata(input.metadata);
  if (input.metadata !== undefined && !metadata) return undefined;
  const resources = input.resources === undefined
    ? undefined
    : sanitizeResources(input.resources);
  if (input.resources !== undefined && !resources) return undefined;
  return {
    requestId: transactionId(input.requestId),
    actorPlayerId: playerId(input.actorPlayerId),
    operation: input.operation as ConstructionBlueprintDelta['operation'],
    siteId: input.siteId,
    blueprintId: input.blueprintId,
    baseBlueprintRevision: input.baseBlueprintRevision,
    blueprintRevision: input.blueprintRevision,
    upsertedPlacements,
    removedPlacementIds,
    ...(metadata ? { metadata } : {}),
    ...(resources ? { resources } : {}),
  };
};

export const validateConstructionStateDeltaPayload = (
  input: unknown,
): ConstructionStateDeltaPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'CONSTRUCTION_STATE_DELTA' ||
    !nonNegativeInteger(input.baseRevision) ||
    !nonNegativeInteger(input.revision) ||
    input.revision !== input.baseRevision + 1 ||
    !nonNegativeInteger(input.serverTick)
  ) return undefined;
  const change = sanitizeDelta(input.change);
  if (!change) return undefined;
  return {
    version: 1,
    kind: 'CONSTRUCTION_STATE_DELTA',
    baseRevision: input.baseRevision,
    revision: input.revision,
    serverTick: serverTick(input.serverTick),
    change,
  };
};

export const validateConstructionStateResyncRequestPayload = (
  input: unknown,
): ConstructionStateResyncRequestPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'CONSTRUCTION_STATE_RESYNC_REQUEST' ||
    !nonNegativeInteger(input.observedRevision) ||
    (input.scope !== 'FULL' && input.scope !== 'SITE') ||
    (input.siteId !== undefined && !boundedString(input.siteId)) ||
    (input.scope === 'SITE' && !boundedString(input.siteId)) ||
    (input.scope === 'FULL' && input.siteId !== undefined)
  ) return undefined;
  return {
    version: 1,
    kind: 'CONSTRUCTION_STATE_RESYNC_REQUEST',
    observedRevision: input.observedRevision,
    scope: input.scope,
    ...(input.siteId === undefined ? {} : { siteId: input.siteId }),
  };
};

export const cloneReplicatedConstructionSite = (
  site: Readonly<ReplicatedConstructionSite>,
): ReplicatedConstructionSite => ({
  siteId: site.siteId,
  anchor: clonePosition(site.anchor),
  access: site.access.mode === 'OWNER_ONLY'
    ? { ...site.access }
    : { mode: site.access.mode },
  resources: site.resources.mode === 'AUTHORITY_INVENTORY'
    ? { ...site.resources }
    : { mode: 'DEV_UNLIMITED' },
  blueprint: {
    ...site.blueprint,
    palette: { ...site.blueprint.palette },
    placements: site.blueprint.placements.map(cloneConstructionPlacement),
  },
});

export const cloneConstructionMetadata = (
  metadata: Readonly<ConstructionBlueprintMetadata>,
): ConstructionBlueprintMetadata => ({
  ...metadata,
  palette: { ...metadata.palette } as ConstructionPalette,
});
