import { cloneGlobalPosition } from '../../world/GlobalPosition';
import type { EmergentWorldRegistry } from './EmergentWorldRegistry';
import { emergentPolylineLength, sampleEmergentPolyline } from './EmergentPosition';
import type { RoadConditionSystem } from './RoadConditionSystem';
import type {
  MobilityProfileDefinition,
  TravelAgentState,
  TravelStatus,
} from './EmergentWorldTypes';

export interface TravelTransition {
  agentId: string;
  previousStatus: TravelStatus;
  status: TravelStatus;
  occurredAt: number;
  reason: string;
  tripId?: string;
  segmentId?: string;
  locationId?: string;
}

interface TravelSystemSaveData { version: 1; agents: TravelAgentState[]; }

const cloneAgent = (state: Readonly<TravelAgentState>): TravelAgentState => ({
  ...state,
  worldPosition: cloneGlobalPosition(state.worldPosition),
  trip: state.trip ? { ...state.trip, segmentIds: [...state.trip.segmentIds] } : undefined,
});

export class TravelSystem {
  private readonly states = new Map<string, TravelAgentState>();

  public constructor(
    private readonly registry: EmergentWorldRegistry,
    private readonly roads: RoadConditionSystem,
    saved?: unknown,
  ) {
    for (const npc of registry.definitions.npcs) {
      const spawn = registry.getLocation(npc.spawnLocationId)!;
      this.states.set(npc.id, {
        agentId: npc.id,
        status: 'AT_LOCATION',
        worldPosition: cloneGlobalPosition(spawn.worldPosition),
        currentLocationId: spawn.id,
        stateChangedAt: 0,
        tripSequence: 0,
        lastDecision: `SPAWNED_AT_${spawn.id}`,
      });
    }
    this.importState(saved);
  }

  public requestTrip(agentId: string, destinationLocationId: string, simulationTime: number): TravelTransition | undefined {
    const state = this.states.get(agentId);
    const npc = this.registry.getNpc(agentId);
    const profile = npc ? this.registry.getMobilityProfile(npc.mobilityProfileId) : undefined;
    if (!state || !npc || !profile || !this.registry.getLocation(destinationLocationId)) return undefined;
    if (state.currentLocationId === destinationLocationId && state.status === 'AT_LOCATION') return undefined;
    const origin = state.currentLocationId;
    if (!origin) return undefined;
    state.tripSequence += 1;
    const tripId = `land-trip:${agentId}:${state.tripSequence}`;
    const path = this.findPath(origin, destinationLocationId, profile);
    state.destinationLocationId = destinationLocationId;
    state.trip = {
      tripId,
      originLocationId: origin,
      destinationLocationId,
      segmentIds: path,
      segmentIndex: 0,
      segmentProgress: 0,
      departed: false,
      startedAt: simulationTime,
    };
    return this.transition(
      state,
      path.length > 0 ? 'TRAVELLING' : 'WAITING',
      simulationTime,
      path.length > 0 ? `PATH_PLANNED_${path.join('_')}` : 'NO_PASSABLE_PATH',
    );
  }

  public update(deltaSeconds: number, simulationTime: number): readonly TravelTransition[] {
    const transitions: TravelTransition[] = [];
    for (const state of [...this.states.values()].sort((a, b) => a.agentId.localeCompare(b.agentId))) {
      const npc = this.registry.getNpc(state.agentId)!;
      const profile = this.registry.getMobilityProfile(npc.mobilityProfileId)!;
      const trip = state.trip;
      if (!trip || state.status === 'AT_LOCATION') continue;
      if (state.status === 'WAITING' || state.status === 'STRANDED') {
        const segmentId = trip.segmentIds[trip.segmentIndex];
        if (!segmentId && state.currentLocationId) {
          const replanned = this.findPath(state.currentLocationId, trip.destinationLocationId, profile);
          if (replanned.length > 0) {
            trip.segmentIds = replanned;
            trip.segmentIndex = 0;
            trip.segmentProgress = 0;
          }
        }
        const nextSegment = trip.segmentIds[trip.segmentIndex];
        if (nextSegment && this.roads.assess(nextSegment, profile).traversable) {
          transitions.push(this.transition(state, 'TRAVELLING', simulationTime, 'ACCESS_RESTORED'));
        } else if (
          state.status === 'WAITING' &&
          trip.departed &&
          simulationTime - (state.waitingSince ?? simulationTime) >= npc.strandedAfterSeconds
        ) {
          transitions.push(this.transition(state, 'STRANDED', simulationTime, 'WAIT_TIMEOUT_WITHOUT_ROUTE'));
        }
        continue;
      }
      let distance = Math.max(0, deltaSeconds) * profile.speedMetresPerSecond;
      while (distance > 0.0001 && state.status === 'TRAVELLING') {
        const segmentId = trip.segmentIds[trip.segmentIndex];
        if (!segmentId) {
          transitions.push(this.arrive(state, simulationTime));
          break;
        }
        const assessment = this.roads.assess(segmentId, profile);
        if (!assessment.traversable) {
          if (trip.segmentProgress <= 0.0001 && state.currentLocationId) {
            const replanned = this.findPath(state.currentLocationId, trip.destinationLocationId, profile, segmentId);
            if (replanned.length > 0) {
              trip.segmentIds = replanned;
              trip.segmentIndex = 0;
              trip.segmentProgress = 0;
              state.lastDecision = `REPLANNED_${replanned.join('_')}`;
              continue;
            }
          }
          transitions.push(this.transition(state, 'WAITING', simulationTime, assessment.reason));
          break;
        }
        const points = this.orientedRoadPoints(segmentId, state.currentLocationId);
        const length = Math.max(0.001, emergentPolylineLength(points));
        const available = (1 - trip.segmentProgress) * length;
        const move = Math.min(distance * assessment.speedMultiplier, available);
        trip.segmentProgress += move / length;
        trip.departed = trip.departed || move > 0;
        state.currentSegmentId = segmentId;
        state.worldPosition = sampleEmergentPolyline(points, trip.segmentProgress);
        distance -= assessment.speedMultiplier > 0 ? move / assessment.speedMultiplier : distance;
        if (trip.segmentProgress < 0.99999) break;
        const road = this.registry.getRoad(segmentId)!;
        const nextLocation = road.fromLocationId === state.currentLocationId
          ? road.toLocationId
          : road.fromLocationId;
        state.currentLocationId = nextLocation;
        state.worldPosition = cloneGlobalPosition(this.registry.getLocation(nextLocation)!.worldPosition);
        state.currentSegmentId = undefined;
        trip.segmentIndex += 1;
        trip.segmentProgress = 0;
        if (trip.segmentIndex >= trip.segmentIds.length) {
          transitions.push(this.arrive(state, simulationTime));
        }
      }
    }
    return transitions;
  }

  public getState(agentId: string): TravelAgentState | undefined {
    const state = this.states.get(agentId);
    return state ? cloneAgent(state) : undefined;
  }

  public getStates(): readonly TravelAgentState[] {
    return [...this.states.values()].sort((a, b) => a.agentId.localeCompare(b.agentId)).map(cloneAgent);
  }

  public getAgentCount(): number { return this.states.size; }

  public getStatusCount(status: TravelStatus): number {
    let count = 0;
    for (const state of this.states.values()) {
      if (state.status === status) count += 1;
    }
    return count;
  }

  public exportState(): TravelSystemSaveData { return { version: 1, agents: this.getStates().map(cloneAgent) }; }

  private importState(saved: unknown): boolean {
    const candidate = saved as Partial<TravelSystemSaveData> | undefined;
    if (candidate?.version !== 1 || !Array.isArray(candidate.agents)) return false;
    for (const value of candidate.agents) {
      if (!this.registry.getNpc(value?.agentId) || !['AT_LOCATION', 'TRAVELLING', 'WAITING', 'STRANDED'].includes(value.status)) continue;
      this.states.set(value.agentId, cloneAgent(value));
    }
    return true;
  }

  private findPath(
    origin: string,
    destination: string,
    profile: Readonly<MobilityProfileDefinition>,
    excludedSegmentId?: string,
  ): string[] {
    const distance = new Map<string, number>([[origin, 0]]);
    const previous = new Map<string, { locationId: string; segmentId: string }>();
    const open = new Set<string>([origin]);
    while (open.size > 0) {
      const current = [...open].sort((a, b) => (distance.get(a)! - distance.get(b)!) || a.localeCompare(b))[0]!;
      open.delete(current);
      if (current === destination) break;
      for (const road of this.registry.definitions.roadSegments) {
        if (road.id === excludedSegmentId) continue;
        const next = road.fromLocationId === current
          ? road.toLocationId
          : road.toLocationId === current
            ? road.fromLocationId
            : undefined;
        if (!next) continue;
        const assessment = this.roads.assess(road.id, profile);
        if (!assessment.traversable) continue;
        const cost = emergentPolylineLength(this.registry.getRoadPolyline(road.id)) * assessment.costMultiplier;
        const candidate = (distance.get(current) ?? Number.POSITIVE_INFINITY) + cost;
        if (candidate >= (distance.get(next) ?? Number.POSITIVE_INFINITY)) continue;
        distance.set(next, candidate);
        previous.set(next, { locationId: current, segmentId: road.id });
        open.add(next);
      }
    }
    if (!distance.has(destination)) return [];
    const result: string[] = [];
    let cursor = destination;
    while (cursor !== origin) {
      const entry = previous.get(cursor);
      if (!entry) return [];
      result.unshift(entry.segmentId);
      cursor = entry.locationId;
    }
    return result;
  }

  private orientedRoadPoints(segmentId: string, fromLocationId?: string) {
    const road = this.registry.getRoad(segmentId)!;
    const points = [...this.registry.getRoadPolyline(segmentId)];
    return road.fromLocationId === fromLocationId ? points : points.reverse();
  }

  private arrive(state: TravelAgentState, simulationTime: number): TravelTransition {
    const tripId = state.trip?.tripId;
    const locationId = state.destinationLocationId;
    state.trip = undefined;
    state.destinationLocationId = undefined;
    state.currentSegmentId = undefined;
    if (locationId) {
      state.currentLocationId = locationId;
      state.worldPosition = cloneGlobalPosition(this.registry.getLocation(locationId)!.worldPosition);
    }
    return this.transition(state, 'AT_LOCATION', simulationTime, 'DESTINATION_REACHED', tripId, locationId);
  }

  private transition(
    state: TravelAgentState,
    status: TravelStatus,
    simulationTime: number,
    reason: string,
    tripId = state.trip?.tripId,
    locationId = state.currentLocationId,
  ): TravelTransition {
    const previousStatus = state.status;
    state.status = status;
    state.stateChangedAt = simulationTime;
    state.lastDecision = reason;
    state.waitingSince = status === 'WAITING' ? simulationTime : undefined;
    return { agentId: state.agentId, previousStatus, status, occurredAt: simulationTime, reason, tripId, segmentId: state.currentSegmentId, locationId };
  }
}
