import type { SettlementContentRegistry } from './SettlementContentRegistry';
import type {
  SettlementResourceNodeRuntimeState,
  SettlementResourceNodeSaveData,
  SettlementResourceNodeView,
} from './SettlementTypes';
import type { SettlementWarehouse } from './SettlementWarehouse';

interface MutableResourceNodeState {
  nodeId: string;
  harvestedCount: number;
  readyAt?: number;
  depleted: boolean;
  revision: number;
}

export interface SettlementResourceHarvestResult {
  readonly accepted: boolean;
  readonly status: string;
  readonly stateChanged: boolean;
  readonly quantity?: number;
}

const cloneState = (
  state: Readonly<MutableResourceNodeState>,
): SettlementResourceNodeRuntimeState => ({ ...state });

/**
 * Timestamped gathering and regrowth. No resource node runs a frame update;
 * READY transitions are resolved on the fixed world tick and growth visuals
 * are derived from timestamps.
 */
export class SettlementResourceNodeSystem {
  private readonly states = new Map<string, MutableResourceNodeState>();

  public constructor(
    private readonly registry: SettlementContentRegistry,
    private readonly warehouse: SettlementWarehouse,
    saved?: Readonly<SettlementResourceNodeSaveData>,
  ) {
    for (const definition of registry.definitions.resourceNodes) {
      this.states.set(definition.id, {
        nodeId: definition.id,
        harvestedCount: 0,
        depleted: false,
        revision: 0,
      });
    }
    if (saved?.version === 1 && Array.isArray(saved.states)) {
      for (const candidate of saved.states) this.importState(candidate);
    }
  }

  public harvest(
    nodeId: string,
    simulationTime: number,
  ): SettlementResourceHarvestResult {
    const definition = this.registry.getResourceNode(nodeId);
    const state = this.states.get(nodeId);
    if (!definition || !state) {
      return { accepted: false, status: 'RESOURCE_NODE_UNKNOWN', stateChanged: false };
    }
    const now = Math.max(0, simulationTime);
    this.resolveReady(state, now);
    if (state.depleted) {
      return { accepted: false, status: 'RESOURCE_NODE_DEPLETED', stateChanged: false };
    }
    if (state.readyAt !== undefined) {
      return { accepted: false, status: 'RESOURCE_NODE_REGROWING', stateChanged: false };
    }
    if (!this.warehouse.canApply(definition.yields, 1)) {
      return { accepted: false, status: 'WAREHOUSE_FULL', stateChanged: false };
    }
    if (!this.warehouse.apply(definition.yields, 1)) {
      return { accepted: false, status: 'WAREHOUSE_TRANSACTION_FAILED', stateChanged: false };
    }
    state.harvestedCount += 1;
    if (definition.regrowthSeconds === undefined) {
      state.depleted = true;
    } else {
      state.readyAt = now + definition.regrowthSeconds;
    }
    state.revision += 1;
    return {
      accepted: true,
      status: definition.regrowthSeconds === undefined
        ? 'RESOURCE_GATHERED'
        : 'RESOURCE_HARVESTED',
      stateChanged: true,
      quantity: definition.yields.reduce((sum, output) => sum + output.quantity, 0),
    };
  }

  public update(simulationTime: number): boolean {
    let changed = false;
    for (const state of this.states.values()) {
      if (this.resolveReady(state, simulationTime)) changed = true;
    }
    return changed;
  }

  public getView(nodeId: string, simulationTime: number): SettlementResourceNodeView | undefined {
    const definition = this.registry.getResourceNode(nodeId);
    const state = this.states.get(nodeId);
    if (!definition || !state) return undefined;
    const region = this.registry.getSeasonRegion(definition.regionId)!;
    const regrowth = definition.regrowthSeconds;
    const growth = state.depleted
      ? 0
      : state.readyAt === undefined
        ? 1
        : regrowth === undefined
          ? 0
          : Math.max(0, Math.min(1,
              1 - (state.readyAt - simulationTime) / regrowth));
    return {
      ...cloneState(state),
      displayName: definition.displayName,
      kind: definition.kind,
      regionId: definition.regionId,
      season: region.season,
      x: definition.x,
      z: definition.z,
      interactionRadius: definition.interactionRadius,
      yields: definition.yields.map((output) => ({ ...output })),
      status: state.depleted
        ? 'DEPLETED'
        : state.readyAt === undefined
          ? 'READY'
          : 'REGROWING',
      growth,
    };
  }

  public getViews(simulationTime: number): readonly SettlementResourceNodeView[] {
    return this.registry.definitions.resourceNodes.flatMap((definition) => {
      const view = this.getView(definition.id, simulationTime);
      return view ? [view] : [];
    });
  }

  public exportState(): SettlementResourceNodeSaveData {
    return {
      version: 1,
      states: [...this.states.values()]
        .sort((left, right) => left.nodeId.localeCompare(right.nodeId))
        .map(cloneState),
    };
  }

  private resolveReady(
    state: MutableResourceNodeState,
    simulationTime: number,
  ): boolean {
    if (
      state.readyAt === undefined ||
      simulationTime < state.readyAt
    ) return false;
    delete state.readyAt;
    state.revision += 1;
    return true;
  }

  private importState(candidate: Readonly<SettlementResourceNodeRuntimeState>): void {
    const definition = this.registry.getResourceNode(candidate?.nodeId);
    const state = definition ? this.states.get(definition.id) : undefined;
    if (!definition || !state) return;
    state.harvestedCount = Number.isSafeInteger(candidate.harvestedCount) &&
      candidate.harvestedCount >= 0 ? candidate.harvestedCount : 0;
    state.revision = Number.isSafeInteger(candidate.revision) &&
      candidate.revision >= 0 ? candidate.revision : 0;
    if (definition.regrowthSeconds === undefined) {
      state.depleted = candidate.depleted === true;
      delete state.readyAt;
      return;
    }
    state.depleted = false;
    if (Number.isFinite(candidate.readyAt)) {
      state.readyAt = Math.max(0, candidate.readyAt!);
    } else {
      delete state.readyAt;
    }
  }
}
