import {BufferGeometry,Float32BufferAttribute,LineBasicMaterial,LineSegments} from 'three';

/** One small local guide. Geometry changes only when the targeted face does. */
export class SurvivalPlacementGrid extends LineSegments<BufferGeometry,LineBasicMaterial> {
  private signature='';
  constructor(){
    super(new BufferGeometry(),new LineBasicMaterial({color:0x84cfb6,transparent:true,opacity:.28,depthWrite:false}));
    this.name='Optional local placement grid';this.visible=false;this.renderOrder=9960;
  }
  configure(width:number,height:number,step:number):void {
    const signature=`${width}/${height}/${step}`;if(signature===this.signature)return;
    const a:number[]=[];
    for(let x=Math.ceil(-width/2/step)*step;x<=width/2+.0001;x+=step)a.push(x,0,-height/2,x,0,height/2);
    for(let z=Math.ceil(-height/2/step)*step;z<=height/2+.0001;z+=step)a.push(-width/2,0,z,width/2,0,z);
    this.geometry.dispose();this.geometry=new BufferGeometry();
    this.geometry.setAttribute('position',new Float32BufferAttribute(a,3));this.signature=signature;
  }
  dispose():void{this.geometry.dispose();this.material.dispose();this.removeFromParent();}
}
