import { CapsuleGeometry, Group, InstancedMesh, Matrix4, MeshBasicMaterial, Quaternion, Vector3 } from 'three';
import { HUMAN_HITBOX, HUSK_HITBOX, type CombatBody } from './CombatHitboxes';

/** Opt-in diagnostic only: never constructed in normal play. Green = human,
 * red = hostile. These exact capsules drive ray/area/melee collision. */
export class CombatHitboxDebug {
  readonly root = new Group();
  private readonly matrix = new Matrix4();
  private readonly position = new Vector3();
  private readonly rotation = new Quaternion();
  private readonly scale = new Vector3(1,1,1);
  private readonly meshes = [HUMAN_HITBOX, HUSK_HITBOX].map((body, i) => new InstancedMesh(
    new CapsuleGeometry(body.radius, body.height - body.radius * 2, 4, 8),
    new MeshBasicMaterial({ color:i===0 ? 0x62efbb : 0xff536c, wireframe:true, depthTest:false, depthWrite:false, toneMapped:false }),
    i===0 ? 1 : 12,
  ));
  constructor() {
    this.root.name = 'DEV · combat hitboxes';
    for (const mesh of this.meshes) { mesh.count=0; mesh.frustumCulled=false; mesh.renderOrder=9999; this.root.add(mesh); }
  }
  update(player: CombatBody, enemies: readonly CombatBody[]): void {
    for (let group=0; group<2; group++) {
      const bodies = group===0 ? [player] : enemies, mesh=this.meshes[group]!;
      mesh.count=Math.min(bodies.length,group===0 ? 1 : 12);
      for (let i=0;i<mesh.count;i++) {
        const body=bodies[i]!;
        this.position.set(body.x,body.y+body.height/2,body.z);
        this.matrix.compose(this.position,this.rotation,this.scale);
        mesh.setMatrixAt(i,this.matrix);
      }
      mesh.instanceMatrix.needsUpdate=true;
    }
  }
  dispose(): void { for (const mesh of this.meshes) {mesh.dispose();mesh.geometry.dispose();mesh.material.dispose();} this.root.removeFromParent(); }
}
