import {
  type CommandSequence,
  type ControlSlotId,
  type DefinitionId,
  type NetworkEntityId,
  type PlayerId,
  type Revision,
  type ServerTick,
  commandSequence,
  controlSlotId,
  definitionId,
  networkEntityId,
  playerId,
  revision,
  serverTick,
} from '../core/NetworkPrimitives';
import type { SharedEntityKind } from '../../multiplayer/entities/SharedEntityRegistry';
import type { ControlLeaseState } from '../../multiplayer/control/ControlLeaseRegistry';

export interface ReplicatedRootState {
  x: number;
  y: number;
  z: number;
  heading: number;
  pitch: number;
  roll: number;
  velocityX: number;
  velocityY: number;
  velocityZ: number;
}

export interface ReplicatedToolState {
  primaryPosition: number;
  secondaryPosition: number;
  lightsEnabled: boolean;
  beaconEnabled: boolean;
}

export interface ReplicatedCargoState {
  snowMass: number;
  capacity: number;
}

export interface ReplicatedAttachmentState {
  parentEntityId: NetworkEntityId;
  socketId: string;
  revision: Revision;
}

export interface ReplicatedEntitySnapshot {
  entityId: NetworkEntityId;
  definitionId: DefinitionId;
  kind: SharedEntityKind;
  entityRevision: Revision;
  simulationRevision: Revision;
  root: ReplicatedRootState;
  tool: ReplicatedToolState;
  cargo: ReplicatedCargoState;
  attachment?: ReplicatedAttachmentState;
  lastProcessedCommandSequence?: CommandSequence;
}

export interface ReplicatedControlLeaseSnapshot {
  entityId: NetworkEntityId;
  slotId: ControlSlotId;
  state: ControlLeaseState;
  revision: Revision;
  holderPlayerId?: PlayerId;
  holderNpcEntityId?: NetworkEntityId;
}

export interface EntitySnapshotBatchPayload {
  version: 1;
  kind: 'ENTITY_SNAPSHOT_BATCH';
  serverTick: ServerTick;
  snapshotSequence: number;
  entities: readonly ReplicatedEntitySnapshot[];
}

export interface EntityBaselinePayload {
  version: 1;
  kind: 'ENTITY_BASELINE';
  baselineRevision: number;
  serverTick: ServerTick;
  entities: readonly ReplicatedEntitySnapshot[];
  leases: readonly ReplicatedControlLeaseSnapshot[];
}

export interface EntityReliableDeltaPayload {
  version: 1;
  kind: 'ENTITY_DELTA';
  deltaRevision: number;
  serverTick: ServerTick;
  reason: 'LEASE' | 'ATTACHMENT' | 'CARGO' | 'SPAWN' | 'DESPAWN';
  entities: readonly ReplicatedEntitySnapshot[];
  leases: readonly ReplicatedControlLeaseSnapshot[];
  removedEntityIds: readonly NetworkEntityId[];
}

const ENTITY_KINDS = new Set<SharedEntityKind>([
  'PLAYER_CHARACTER',
  'NPC',
  'VEHICLE',
  'VESSEL',
  'TRAILER',
  'PORTABLE_ITEM',
  'CONTAINER',
  'CONSTRUCTION',
  'WORLD_OBJECT',
]);
const LEASE_STATES = new Set<ControlLeaseState>(['FREE', 'HELD', 'RELEASING']);
const DELTA_REASONS = new Set<EntityReliableDeltaPayload['reason']>([
  'LEASE',
  'ATTACHMENT',
  'CARGO',
  'SPAWN',
  'DESPAWN',
]);

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const finite = (value: unknown, limit = 1_000_000): value is number =>
  typeof value === 'number' && Number.isFinite(value) && Math.abs(value) <= limit;
const unit = (value: unknown): value is number => finite(value) && value >= 0 && value <= 1;
const boundedString = (value: unknown, maximum = 160): value is string =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;
const natural = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

const validateRoot = (input: unknown): ReplicatedRootState | undefined => {
  if (!isRecord(input)) return undefined;
  const keys: readonly (keyof ReplicatedRootState)[] = [
    'x', 'y', 'z', 'heading', 'pitch', 'roll',
    'velocityX', 'velocityY', 'velocityZ',
  ];
  if (keys.some((key) => !finite(input[key]))) return undefined;
  if (
    Math.abs(input.heading as number) > Math.PI * 2 ||
    Math.abs(input.pitch as number) > Math.PI ||
    Math.abs(input.roll as number) > Math.PI
  ) return undefined;
  return Object.fromEntries(keys.map((key) => [key, input[key]])) as unknown as ReplicatedRootState;
};

const validateTool = (input: unknown): ReplicatedToolState | undefined => {
  if (
    !isRecord(input) ||
    !unit(input.primaryPosition) ||
    !unit(input.secondaryPosition) ||
    typeof input.lightsEnabled !== 'boolean' ||
    typeof input.beaconEnabled !== 'boolean'
  ) return undefined;
  return {
    primaryPosition: input.primaryPosition,
    secondaryPosition: input.secondaryPosition,
    lightsEnabled: input.lightsEnabled,
    beaconEnabled: input.beaconEnabled,
  };
};

const validateCargo = (input: unknown): ReplicatedCargoState | undefined => {
  if (
    !isRecord(input) ||
    !finite(input.snowMass, 100_000) ||
    !finite(input.capacity, 100_000) ||
    (input.snowMass as number) < 0 ||
    (input.capacity as number) < 0 ||
    (input.snowMass as number) > (input.capacity as number) + 0.001
  ) return undefined;
  return { snowMass: input.snowMass, capacity: input.capacity };
};

export const validateReplicatedEntitySnapshot = (
  input: unknown,
): ReplicatedEntitySnapshot | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.entityId) ||
    !boundedString(input.definitionId) ||
    typeof input.kind !== 'string' ||
    !ENTITY_KINDS.has(input.kind as SharedEntityKind) ||
    !natural(input.entityRevision) ||
    !natural(input.simulationRevision)
  ) return undefined;
  const root = validateRoot(input.root);
  const tool = validateTool(input.tool);
  const cargo = validateCargo(input.cargo);
  if (!root || !tool || !cargo) return undefined;
  let attachment: ReplicatedAttachmentState | undefined;
  if (input.attachment !== undefined) {
    if (
      !isRecord(input.attachment) ||
      !boundedString(input.attachment.parentEntityId) ||
      !boundedString(input.attachment.socketId, 64) ||
      !natural(input.attachment.revision)
    ) return undefined;
    attachment = {
      parentEntityId: networkEntityId(input.attachment.parentEntityId),
      socketId: input.attachment.socketId,
      revision: revision(input.attachment.revision),
    };
  }
  if (
    input.lastProcessedCommandSequence !== undefined &&
    !natural(input.lastProcessedCommandSequence)
  ) return undefined;
  return {
    entityId: networkEntityId(input.entityId),
    definitionId: definitionId(input.definitionId),
    kind: input.kind as SharedEntityKind,
    entityRevision: revision(input.entityRevision),
    simulationRevision: revision(input.simulationRevision),
    root,
    tool,
    cargo,
    ...(attachment ? { attachment } : {}),
    ...(input.lastProcessedCommandSequence === undefined
      ? {}
      : { lastProcessedCommandSequence: commandSequence(input.lastProcessedCommandSequence) }),
  };
};

export const validateReplicatedControlLease = (
  input: unknown,
): ReplicatedControlLeaseSnapshot | undefined => {
  if (
    !isRecord(input) ||
    !boundedString(input.entityId) ||
    !boundedString(input.slotId) ||
    typeof input.state !== 'string' ||
    !LEASE_STATES.has(input.state as ControlLeaseState) ||
    !natural(input.revision) ||
    (input.holderPlayerId !== undefined && !boundedString(input.holderPlayerId)) ||
    (input.holderNpcEntityId !== undefined &&
      !boundedString(input.holderNpcEntityId)) ||
    (input.holderPlayerId !== undefined &&
      input.holderNpcEntityId !== undefined) ||
    (input.state === 'FREE' &&
      (input.holderPlayerId !== undefined ||
        input.holderNpcEntityId !== undefined)) ||
    (input.state !== 'FREE' &&
      input.holderPlayerId === undefined &&
      input.holderNpcEntityId === undefined)
  ) return undefined;
  return {
    entityId: networkEntityId(input.entityId),
    slotId: controlSlotId(input.slotId),
    state: input.state as ControlLeaseState,
    revision: revision(input.revision),
    ...(input.holderPlayerId === undefined
      ? {}
      : { holderPlayerId: playerId(input.holderPlayerId) }),
    ...(input.holderNpcEntityId === undefined
      ? {}
      : { holderNpcEntityId: networkEntityId(input.holderNpcEntityId) }),
  };
};

const validateEntityArray = (
  input: unknown,
  maximum = 256,
): ReplicatedEntitySnapshot[] | undefined => {
  if (!Array.isArray(input) || input.length > maximum) return undefined;
  const output: ReplicatedEntitySnapshot[] = [];
  const ids = new Set<string>();
  for (const candidate of input) {
    const entity = validateReplicatedEntitySnapshot(candidate);
    if (!entity || ids.has(entity.entityId)) return undefined;
    ids.add(entity.entityId);
    output.push(entity);
  }
  return output;
};

const validateLeaseArray = (input: unknown): ReplicatedControlLeaseSnapshot[] | undefined => {
  if (!Array.isArray(input) || input.length > 256) return undefined;
  const output: ReplicatedControlLeaseSnapshot[] = [];
  const keys = new Set<string>();
  for (const candidate of input) {
    const lease = validateReplicatedControlLease(candidate);
    const key = lease ? `${lease.entityId}\u001f${lease.slotId}` : '';
    if (!lease || keys.has(key)) return undefined;
    keys.add(key);
    output.push(lease);
  }
  return output;
};

export const validateEntitySnapshotBatchPayload = (
  input: unknown,
): EntitySnapshotBatchPayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 ||
    input.kind !== 'ENTITY_SNAPSHOT_BATCH' ||
    !natural(input.serverTick) || !natural(input.snapshotSequence)
  ) return undefined;
  const entities = validateEntityArray(input.entities);
  return entities ? {
    version: 1,
    kind: 'ENTITY_SNAPSHOT_BATCH',
    serverTick: serverTick(input.serverTick),
    snapshotSequence: input.snapshotSequence,
    entities,
  } : undefined;
};

export const validateEntityBaselinePayload = (
  input: unknown,
): EntityBaselinePayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ENTITY_BASELINE' ||
    !natural(input.baselineRevision) || input.baselineRevision < 1 ||
    !natural(input.serverTick)
  ) return undefined;
  const entities = validateEntityArray(input.entities);
  const leases = validateLeaseArray(input.leases);
  return entities && leases ? {
    version: 1,
    kind: 'ENTITY_BASELINE',
    baselineRevision: input.baselineRevision,
    serverTick: serverTick(input.serverTick),
    entities,
    leases,
  } : undefined;
};

export const validateEntityReliableDeltaPayload = (
  input: unknown,
): EntityReliableDeltaPayload | undefined => {
  if (
    !isRecord(input) || input.version !== 1 || input.kind !== 'ENTITY_DELTA' ||
    !natural(input.deltaRevision) || input.deltaRevision < 1 ||
    !natural(input.serverTick) || typeof input.reason !== 'string' ||
    !DELTA_REASONS.has(input.reason as EntityReliableDeltaPayload['reason']) ||
    !Array.isArray(input.removedEntityIds) || input.removedEntityIds.length > 256 ||
    !input.removedEntityIds.every((id) => boundedString(id))
  ) return undefined;
  const entities = validateEntityArray(input.entities);
  const leases = validateLeaseArray(input.leases);
  return entities && leases ? {
    version: 1,
    kind: 'ENTITY_DELTA',
    deltaRevision: input.deltaRevision,
    serverTick: serverTick(input.serverTick),
    reason: input.reason as EntityReliableDeltaPayload['reason'],
    entities,
    leases,
    removedEntityIds: input.removedEntityIds.map((id) => networkEntityId(id as string)),
  } : undefined;
};

export const cloneReplicatedEntity = (
  entity: Readonly<ReplicatedEntitySnapshot>,
): ReplicatedEntitySnapshot => ({
  ...entity,
  root: { ...entity.root },
  tool: { ...entity.tool },
  cargo: { ...entity.cargo },
  ...(entity.attachment ? { attachment: { ...entity.attachment } } : {}),
});
