import { clamp } from '../utils/math';
import {
  wildernessAnimalDefinition,
  type WildernessAnimalDietTag,
  type WildernessAnimalSpecies,
} from './WildernessAnimalCatalog';

export type WildernessAnimalBondStage =
  | 'WILD'
  | 'CURIOUS'
  | 'FAMILIAR'
  | 'BONDED'
  | 'COMPANION';

export type WildernessAnimalCareKind = 'FOOD' | 'TREAT' | 'DRINK';

export type WildernessAnimalCareInventoryKey =
  | 'berries'
  | 'roots'
  | 'fish'
  | 'smallGame'
  | 'emberFish'
  | 'roastedRoots'
  | 'roastedGame'
  | 'berryRootMeals'
  | 'cleanWater';

export interface WildernessAnimalRelationshipFields {
  trust?: number;
  confidence?: number;
  suspicion?: number;
  fear?: number;
  startle?: number;
  feedingCount?: number;
  careFoodCount?: number;
  careTreatCount?: number;
  careDrinkCount?: number;
  bondStage?: WildernessAnimalBondStage;
  givenName?: string;
  lastCareAtSeconds?: number;
  lastCalmContactAtSeconds?: number;
  companionIntent?: 'ROAM' | 'FOLLOW' | 'STAY';
}

export interface WildernessAnimalCareInventory {
  berries: number;
  roots: number;
  fish: number;
  smallGame: number;
  emberFish: number;
  roastedRoots: number;
  roastedGame: number;
  berryRootMeals: number;
  cleanWater: number;
}

export interface WildernessAnimalCareOptionView {
  readonly kind: WildernessAnimalCareKind;
  readonly label: string;
  readonly itemLabel: string;
  readonly inventoryKey?: WildernessAnimalCareInventoryKey;
  readonly enabled: boolean;
  readonly reason?: string;
}

export interface WildernessAnimalCareView {
  readonly animalId: string;
  readonly species: WildernessAnimalSpecies;
  readonly speciesName: string;
  readonly displayName: string;
  readonly givenName?: string;
  readonly stage: WildernessAnimalBondStage;
  readonly trust: number;
  readonly confidence: number;
  readonly suspicion: number;
  readonly fear: number;
  readonly startle: number;
  readonly careEvents: number;
  readonly requiredCareEvents: number;
  readonly canName: boolean;
  readonly options: readonly WildernessAnimalCareOptionView[];
  /** Diegetic language shown to the player. Exact relationship values remain
   * simulation/debug data and are never a visible checklist. */
  readonly disposition: string;
  readonly bodyLanguage: string;
  readonly hint: string;
}

export interface WildernessAnimalCareResult {
  readonly accepted: boolean;
  readonly message: string;
  readonly stageChanged?: boolean;
  readonly becameCompanion?: boolean;
  readonly consumed?: WildernessAnimalCareInventoryKey;
}

interface CareItemDefinition {
  readonly key: WildernessAnimalCareInventoryKey;
  readonly label: string;
  readonly kind: WildernessAnimalCareKind;
  readonly tags: readonly WildernessAnimalDietTag[];
  readonly trust: number;
  readonly confidence: number;
  readonly suspicionRelief: number;
  readonly fearRelief: number;
}

const CARE_ITEMS: readonly CareItemDefinition[] = [
  { key: 'berries', label: 'frost berries', kind: 'FOOD', tags: ['BERRY'], trust: 0.1, confidence: 0.055, suspicionRelief: 0.07, fearRelief: 0.035 },
  { key: 'roots', label: 'winter root', kind: 'FOOD', tags: ['ROOT', 'BARK'], trust: 0.105, confidence: 0.06, suspicionRelief: 0.065, fearRelief: 0.035 },
  { key: 'fish', label: 'fresh fish', kind: 'FOOD', tags: ['FISH'], trust: 0.115, confidence: 0.055, suspicionRelief: 0.06, fearRelief: 0.03 },
  { key: 'smallGame', label: 'small-game meat', kind: 'FOOD', tags: ['MEAT'], trust: 0.12, confidence: 0.05, suspicionRelief: 0.055, fearRelief: 0.025 },
  { key: 'berryRootMeals', label: 'berry-glazed root treat', kind: 'TREAT', tags: ['BERRY', 'ROOT'], trust: 0.18, confidence: 0.115, suspicionRelief: 0.12, fearRelief: 0.075 },
  { key: 'roastedRoots', label: 'warm root treat', kind: 'TREAT', tags: ['ROOT', 'BARK'], trust: 0.17, confidence: 0.105, suspicionRelief: 0.11, fearRelief: 0.07 },
  { key: 'emberFish', label: 'ember-fish treat', kind: 'TREAT', tags: ['FISH'], trust: 0.185, confidence: 0.1, suspicionRelief: 0.105, fearRelief: 0.06 },
  { key: 'roastedGame', label: 'roasted meat treat', kind: 'TREAT', tags: ['MEAT'], trust: 0.19, confidence: 0.095, suspicionRelief: 0.1, fearRelief: 0.055 },
  { key: 'cleanWater', label: 'clean meltwater', kind: 'DRINK', tags: ['WATER'], trust: 0.075, confidence: 0.13, suspicionRelief: 0.08, fearRelief: 0.08 },
] as const;

const STAGE_ORDER: readonly WildernessAnimalBondStage[] = [
  'WILD',
  'CURIOUS',
  'FAMILIAR',
  'BONDED',
  'COMPANION',
];

const careEvents = (animal: Readonly<WildernessAnimalRelationshipFields>): number =>
  Math.max(0, Math.floor(
    (animal.careFoodCount ?? animal.feedingCount ?? 0) +
    (animal.careTreatCount ?? 0) +
    (animal.careDrinkCount ?? 0),
  ));

export const normalizeWildernessAnimalRelationship = <
  T extends WildernessAnimalRelationshipFields,
>(animal: T): T => {
  animal.trust = clamp(animal.trust ?? 0, 0, 1);
  animal.confidence = clamp(animal.confidence ?? animal.trust * 0.45, 0, 1);
  animal.suspicion = clamp(animal.suspicion ?? (1 - animal.trust) * 0.72, 0, 1);
  animal.fear = clamp(animal.fear ?? 0.12, 0, 1);
  animal.startle = clamp(animal.startle ?? 0, 0, 1);
  animal.feedingCount = Math.max(0, Math.floor(animal.feedingCount ?? 0));
  animal.careFoodCount = Math.max(
    0,
    Math.floor(animal.careFoodCount ?? animal.feedingCount),
  );
  animal.careTreatCount = Math.max(0, Math.floor(animal.careTreatCount ?? 0));
  animal.careDrinkCount = Math.max(0, Math.floor(animal.careDrinkCount ?? 0));
  animal.lastCareAtSeconds = Number.isFinite(animal.lastCareAtSeconds)
    ? Math.max(-1, animal.lastCareAtSeconds!)
    : -1;
  animal.lastCalmContactAtSeconds = Number.isFinite(animal.lastCalmContactAtSeconds)
    ? Math.max(-1, animal.lastCalmContactAtSeconds!)
    : -1;
  animal.companionIntent ??= 'ROAM';
  animal.bondStage ??= 'WILD';
  if (animal.givenName !== undefined) {
    animal.givenName = sanitizeWildernessAnimalName(animal.givenName) || undefined;
  }
  return animal;
};

export const sanitizeWildernessAnimalName = (input: string): string => input
  .normalize('NFKC')
  .replace(/[<>\n\r\t]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 24);

const stageFor = (
  species: WildernessAnimalSpecies,
  animal: Readonly<WildernessAnimalRelationshipFields>,
): WildernessAnimalBondStage => {
  const definition = wildernessAnimalDefinition(species);
  const trust = animal.trust ?? 0;
  const confidence = animal.confidence ?? 0;
  const suspicion = animal.suspicion ?? 1;
  const fear = animal.fear ?? 1;
  const events = careEvents(animal);
  if (
    events >= definition.minimumCareEventsForCompanion &&
    trust >= definition.trustForCompanion &&
    confidence >= definition.confidenceForCompanion &&
    suspicion <= 0.3 && fear <= 0.25
  ) return 'COMPANION';
  if (
    events >= definition.minimumCareEventsForBond &&
    trust >= definition.trustForBond &&
    confidence >= definition.confidenceForCompanion * 0.72 &&
    suspicion <= 0.48
  ) return 'BONDED';
  if (events >= Math.max(2, Math.floor(definition.minimumCareEventsForBond * 0.55)) && trust >= 0.28) {
    return 'FAMILIAR';
  }
  if (events >= 1 || trust >= 0.12 || confidence >= 0.22) return 'CURIOUS';
  return 'WILD';
};

const stageName = (stage: WildernessAnimalBondStage): string => stage === 'COMPANION'
  ? 'COMPANION'
  : stage;

const bestCareItem = (
  species: WildernessAnimalSpecies,
  kind: WildernessAnimalCareKind,
  inventory: Readonly<WildernessAnimalCareInventory>,
): CareItemDefinition | undefined => {
  const diet = wildernessAnimalDefinition(species).diet;
  return CARE_ITEMS
    .filter((item) => item.kind === kind)
    .filter((item) => item.tags.some((tag) => diet.includes(tag)))
    .filter((item) => inventory[item.key] > 0)
    .sort((left, right) => right.trust - left.trust)[0];
};

const careLabel = (kind: WildernessAnimalCareKind): string => kind === 'FOOD'
  ? 'OFFER FOOD'
  : kind === 'TREAT'
    ? 'OFFER TREAT'
    : 'OFFER WATER';

const unavailableItemLabel = (
  species: WildernessAnimalSpecies,
  kind: WildernessAnimalCareKind,
): string => {
  const diet = wildernessAnimalDefinition(species).diet;
  if (kind === 'DRINK') return 'clean meltwater';
  if (kind === 'TREAT') {
    return diet.includes('FISH') || diet.includes('MEAT')
      ? 'a prepared fish or meat treat'
      : 'a prepared root or berry treat';
  }
  return diet.includes('FISH')
    ? 'fresh fish'
    : diet.includes('MEAT')
      ? 'fresh fish or game'
      : diet.includes('BERRY')
        ? 'berries or roots'
      : 'winter roots';
};

const visibleRelationshipLanguage = (
  definition: ReturnType<typeof wildernessAnimalDefinition>,
  stage: WildernessAnimalBondStage,
  animal: Readonly<WildernessAnimalRelationshipFields>,
): Readonly<{ disposition: string; bodyLanguage: string; hint: string }> => {
  const fear = animal.fear ?? 0;
  const startle = animal.startle ?? 0;
  const suspicion = animal.suspicion ?? 0;
  const confidence = animal.confidence ?? 0;
  if (startle > 0.56 || fear > 0.7) {
    return {
      disposition: 'STARTLED',
      bodyLanguage: 'Its weight is set to flee and every sudden movement draws its eyes.',
      hint: 'Give it room. Chasing it now will only make this meeting harder.',
    };
  }
  if (stage === 'COMPANION') {
    return {
      disposition: 'AT EASE NEAR YOU',
      bodyLanguage: 'It approaches by choice and settles without watching every movement.',
      hint: 'It is still a living creature with its own routes, hunger and moods.',
    };
  }
  if (stage === 'BONDED') {
    return {
      disposition: 'SEEKS YOU OUT',
      bodyLanguage: 'It recognises your scent and no longer turns away at once.',
      hint: 'Patient, varied care matters more than repetition.',
    };
  }
  if (stage === 'FAMILIAR') {
    return {
      disposition: 'RECOGNISES YOU',
      bodyLanguage: 'Its posture softens after the first cautious look.',
      hint: 'Let its behaviour tell you when another approach is welcome.',
    };
  }
  if (stage === 'CURIOUS' || confidence > 0.2) {
    return {
      disposition: 'WATCHING',
      bodyLanguage: suspicion > 0.62
        ? 'It studies your hands, then the ground between you.'
        : 'It lingers instead of leaving, uncertain but curious.',
      hint: 'Something left at a respectful distance may be safer than reaching toward it.',
    };
  }
  return {
    disposition: definition.danger > 0.72 ? 'WARY AND DANGEROUS' : 'WILD',
    bodyLanguage: 'It keeps the wind, distance and an escape route between you.',
    hint: 'Observe first. You do not yet know what it wants—or whether it wants you near.',
  };
};

export class WildernessAnimalCompanionSystem {
  public view(
    animalId: string,
    species: WildernessAnimalSpecies,
    animal: Readonly<WildernessAnimalRelationshipFields>,
    inventory: Readonly<WildernessAnimalCareInventory>,
    distance: number,
    elapsedSeconds: number,
  ): WildernessAnimalCareView {
    normalizeWildernessAnimalRelationship(animal as WildernessAnimalRelationshipFields);
    const definition = wildernessAnimalDefinition(species);
    const stage = animal.bondStage!;
    const calmEnough = (animal.fear ?? 0) <= 0.56 &&
      (animal.startle ?? 0) <= 0.44 &&
      (animal.suspicion ?? 1) <= 0.82;
    const closeEnough = distance <= definition.directCareDistance +
      (stage === 'COMPANION' ? 1.4 : stage === 'BONDED' ? 0.7 : 0);
    const cooldown = Math.max(0, 10 - (
      elapsedSeconds - (animal.lastCareAtSeconds ?? -100)
    ));
    const options = (['FOOD', 'TREAT', 'DRINK'] as const).map((kind) => {
      const item = bestCareItem(species, kind, inventory);
      const enabled = Boolean(item) && closeEnough && calmEnough && cooldown <= 0;
      const reason = !item
        ? `Need ${unavailableItemLabel(species, kind)}.`
        : !closeEnough
          ? `Move calmly within ${definition.directCareDistance.toFixed(1)} m, or leave food and step back.`
          : !calmEnough
            ? `${definition.displayName} is too frightened or suspicious. Give it space.`
            : cooldown > 0
              ? `Let the animal settle for ${Math.ceil(cooldown)}s.`
              : undefined;
      return {
        kind,
        label: careLabel(kind),
        itemLabel: item?.label ?? unavailableItemLabel(species, kind),
        inventoryKey: item?.key,
        enabled,
        reason,
      };
    });
    const displayName = animal.givenName || definition.displayName;
    const language = visibleRelationshipLanguage(definition, stage, animal);
    return {
      animalId,
      species,
      speciesName: definition.displayName,
      displayName,
      givenName: animal.givenName,
      stage,
      trust: animal.trust ?? 0,
      confidence: animal.confidence ?? 0,
      suspicion: animal.suspicion ?? 0,
      fear: animal.fear ?? 0,
      startle: animal.startle ?? 0,
      careEvents: careEvents(animal),
      requiredCareEvents: definition.minimumCareEventsForCompanion,
      canName: stage === 'COMPANION',
      options,
      ...language,
    };
  }

  public applyCare(
    species: WildernessAnimalSpecies,
    animal: WildernessAnimalRelationshipFields,
    inventory: WildernessAnimalCareInventory,
    kind: WildernessAnimalCareKind,
    distance: number,
    elapsedSeconds: number,
  ): WildernessAnimalCareResult {
    const before = this.view('', species, animal, inventory, distance, elapsedSeconds);
    const option = before.options.find((candidate) => candidate.kind === kind)!;
    if (!option.enabled || !option.inventoryKey) {
      return {
        accepted: false,
        message: option.reason ?? 'The animal does not accept that right now.',
      };
    }
    const item = CARE_ITEMS.find((candidate) => candidate.key === option.inventoryKey)!;
    inventory[item.key] = Math.max(0, inventory[item.key] - 1);
    const definition = wildernessAnimalDefinition(species);
    const difficulty = clamp(definition.wildness * 0.72 + definition.danger * 0.28, 0, 1);
    const variety = kind === 'FOOD'
      ? (animal.careFoodCount ?? 0) > 0
      : kind === 'TREAT'
        ? (animal.careTreatCount ?? 0) > 0
        : (animal.careDrinkCount ?? 0) > 0;
    const repetitionScale = variety ? 0.66 : 1;
    const calmScale = 0.72 + (1 - (animal.fear ?? 0)) * 0.28;
    const gainScale = (1 - difficulty * 0.56) * repetitionScale * calmScale;
    animal.trust = clamp((animal.trust ?? 0) + item.trust * gainScale, 0, 1);
    animal.confidence = clamp(
      (animal.confidence ?? 0) + item.confidence * (1 - difficulty * 0.34),
      0,
      1,
    );
    animal.suspicion = clamp(
      (animal.suspicion ?? 0) - item.suspicionRelief * (0.75 + gainScale * 0.5),
      0,
      1,
    );
    animal.fear = clamp((animal.fear ?? 0) - item.fearRelief, 0, 1);
    animal.startle = clamp((animal.startle ?? 0) - item.fearRelief * 1.4, 0, 1);
    animal.feedingCount = (animal.feedingCount ?? 0) + (kind === 'DRINK' ? 0 : 1);
    if (kind === 'FOOD') animal.careFoodCount = (animal.careFoodCount ?? 0) + 1;
    if (kind === 'TREAT') animal.careTreatCount = (animal.careTreatCount ?? 0) + 1;
    if (kind === 'DRINK') animal.careDrinkCount = (animal.careDrinkCount ?? 0) + 1;
    animal.lastCareAtSeconds = elapsedSeconds;
    animal.lastCalmContactAtSeconds = elapsedSeconds;
    const previousStage = before.stage;
    animal.bondStage = this.advanceStage(species, animal);
    if (animal.bondStage === 'COMPANION' && animal.companionIntent === 'ROAM') {
      animal.companionIntent = 'FOLLOW';
    }
    const displayName = animal.givenName || definition.displayName;
    const stageChanged = animal.bondStage !== previousStage;
    return {
      accepted: true,
      consumed: item.key,
      stageChanged,
      becameCompanion: animal.bondStage === 'COMPANION' && previousStage !== 'COMPANION',
      message: stageChanged
        ? animal.bondStage === 'COMPANION'
          ? `${displayName} chooses to stay near you. This is companionship, not ownership.`
          : `${displayName} now regards you as ${stageName(animal.bondStage).toLowerCase()}.`
        : `${displayName} accepts the ${item.label}. Trust grows only a little; the calm meeting matters too.`,
    };
  }

  /**
   * Dropped food is the safest first contact for wary wildlife. It gives less
   * trust than a direct calm interaction but meaningfully lowers suspicion.
   */
  public acceptPlacedFood(
    species: WildernessAnimalSpecies,
    animal: WildernessAnimalRelationshipFields,
    tag: WildernessAnimalDietTag,
    elapsedSeconds: number,
  ): WildernessAnimalCareResult {
    normalizeWildernessAnimalRelationship(animal);
    const definition = wildernessAnimalDefinition(species);
    if (!definition.diet.includes(tag)) {
      return { accepted: false, message: `${definition.displayName} ignores the offering.` };
    }
    if ((animal.lastCareAtSeconds ?? -1) >= 0 &&
      elapsedSeconds - animal.lastCareAtSeconds! < 10) {
      return { accepted: false, message: 'Let this calm encounter settle.' };
    }
    const difficulty = clamp(definition.wildness * 0.72 + definition.danger * 0.28, 0, 1);
    animal.trust = clamp((animal.trust ?? 0) + 0.075 * (1 - difficulty * 0.52), 0, 1);
    animal.confidence = clamp((animal.confidence ?? 0) + 0.045, 0, 1);
    animal.suspicion = clamp((animal.suspicion ?? 0) - 0.085, 0, 1);
    animal.fear = clamp((animal.fear ?? 0) - 0.025, 0, 1);
    animal.feedingCount = (animal.feedingCount ?? 0) + 1;
    animal.careFoodCount = (animal.careFoodCount ?? 0) + 1;
    animal.lastCareAtSeconds = elapsedSeconds;
    const previousStage = animal.bondStage ?? 'WILD';
    animal.bondStage = this.advanceStage(species, animal);
    return {
      accepted: true,
      stageChanged: animal.bondStage !== previousStage,
      becameCompanion: animal.bondStage === 'COMPANION' && previousStage !== 'COMPANION',
      message: `${definition.displayName} accepts food you left at a safe distance.`,
    };
  }

  private advanceStage(
    species: WildernessAnimalSpecies,
    animal: Readonly<WildernessAnimalRelationshipFields>,
  ): WildernessAnimalBondStage {
    const previous = animal.bondStage ?? 'WILD';
    const next = stageFor(species, animal);
    return STAGE_ORDER.indexOf(next) < STAGE_ORDER.indexOf(previous) ? previous : next;
  }

  public updateRelationship(
    species: WildernessAnimalSpecies,
    animal: WildernessAnimalRelationshipFields,
    deltaSeconds: number,
    context: Readonly<{
      elapsedSeconds: number;
      playerDistance: number;
      playerSpeed: number;
      threatened: boolean;
      wounded: boolean;
      nearFire: boolean;
    }>,
  ): void {
    normalizeWildernessAnimalRelationship(animal);
    const definition = wildernessAnimalDefinition(species);
    const close = context.playerDistance < 10;
    const rushed = close && context.playerSpeed > 2.15;
    const dangerousProximity = context.playerDistance < 2.2 + definition.danger * 1.4;
    const shock = context.wounded || context.threatened
      ? 0.38 + definition.wildness * 0.24
      : rushed && dangerousProximity
        ? 0.2 + definition.humanWariness * 0.22
        : 0;
    if (shock > 0) {
      const shockStep = shock * Math.min(1, Math.max(0, deltaSeconds) * 2.4);
      animal.startle = clamp((animal.startle ?? 0) + shockStep, 0, 1);
      animal.fear = clamp((animal.fear ?? 0) + shockStep * 0.62, 0, 1);
      animal.suspicion = clamp((animal.suspicion ?? 0) + shockStep * 0.34, 0, 1);
      animal.confidence = clamp((animal.confidence ?? 0) - shockStep * 0.2, 0, 1);
    } else {
      animal.startle = clamp((animal.startle ?? 0) - deltaSeconds * 0.34, 0, 1);
      animal.fear = clamp(
        (animal.fear ?? 0) - deltaSeconds * (close ? 0.012 : 0.026),
        0,
        1,
      );
      if (close && context.playerSpeed < 0.75 && !context.nearFire) {
        animal.lastCalmContactAtSeconds = context.elapsedSeconds;
        animal.confidence = clamp(
          (animal.confidence ?? 0) + deltaSeconds * 0.0065 * (1 - definition.wildness * 0.48),
          0,
          1,
        );
        animal.suspicion = clamp((animal.suspicion ?? 0) - deltaSeconds * 0.005, 0, 1);
      }
    }
    // A relationship persists across travel. Only prolonged frightening
    // contact erodes it; ordinary off-screen time never becomes an upkeep tax.
    if ((animal.fear ?? 0) > 0.88 && (animal.suspicion ?? 0) > 0.86) {
      animal.trust = clamp((animal.trust ?? 0) - deltaSeconds * 0.0015, 0, 1);
    }
    const resolved = stageFor(species, animal);
    if (STAGE_ORDER.indexOf(resolved) < STAGE_ORDER.indexOf(animal.bondStage ?? 'WILD')) {
      // Bonded/companion status cannot evaporate from a single fright. The
      // emotional meters still change and affect behaviour until safety returns.
      return;
    }
    animal.bondStage = resolved;
  }

  public nameAnimal(
    species: WildernessAnimalSpecies,
    animal: WildernessAnimalRelationshipFields,
    requestedName: string,
  ): WildernessAnimalCareResult {
    normalizeWildernessAnimalRelationship(animal);
    if (animal.bondStage !== 'COMPANION') {
      return { accepted: false, message: 'A name becomes meaningful only after the animal chooses companionship.' };
    }
    const name = sanitizeWildernessAnimalName(requestedName);
    if (name.length < 2) {
      return { accepted: false, message: 'Choose a name with at least two visible characters.' };
    }
    animal.givenName = name;
    return {
      accepted: true,
      message: `${wildernessAnimalDefinition(species).displayName} is now known as ${name}.`,
    };
  }
}
