import { clamp, smoothstep } from '../utils/math';

export const HELICOPTER_ROTOR_SPOOL_UP_PER_SECOND = 0.32;
export const HELICOPTER_ROTOR_SPOOL_DOWN_PER_SECOND = 0.12;
export const HELICOPTER_ROTOR_CONTROL_BEGIN = 0.82;
export const HELICOPTER_ROTOR_TAKEOFF_SPEED = 0.94;
export const HELICOPTER_ROTOR_WASH_BEGIN = 0.34;
export const HELICOPTER_ROTOR_WASH_MAXIMUM_ALTITUDE = 6.5;

export interface HelicopterRotorInput {
  readonly forward: number;
  readonly lateral: number;
  readonly yaw: number;
  readonly vertical: number;
}

export interface HelicopterRotorWashEnvelope {
  readonly strength: number;
  readonly radius: number;
}

export interface HelicopterRotorWashDriftEnvelope {
  readonly innerRadius: number;
  readonly outerRadius: number;
}

export const stepHelicopterRotorSpeed = (
  current: number,
  target: number,
  deltaSeconds: number,
): number => {
  const delta = clamp(deltaSeconds, 0, 0.1);
  const rate = target > current
    ? HELICOPTER_ROTOR_SPOOL_UP_PER_SECOND
    : HELICOPTER_ROTOR_SPOOL_DOWN_PER_SECOND;
  return target > current
    ? Math.min(target, current + rate * delta)
    : Math.max(target, current - rate * delta);
};

/**
 * E/up starts the turbine. Once airborne the rotor stays engaged even with
 * neutral controls. On the ground it winds down only after every flight axis
 * is released, which makes a deliberate landing visibly different from an
 * instantaneous engine toggle.
 */
export const resolveHelicopterRotorTarget = (
  altitude: number,
  rotorSpeed: number,
  input: Readonly<HelicopterRotorInput>,
): 0 | 1 => {
  if (altitude > 0.025 || input.vertical > 0.05) return 1;
  const hasFlightInput = Math.max(
    Math.abs(input.forward),
    Math.abs(input.lateral),
    Math.abs(input.yaw),
    Math.abs(input.vertical),
  ) > 0.05;
  return rotorSpeed > 0.015 && hasFlightInput ? 1 : 0;
};

export const helicopterRotorControlAuthority = (rotorSpeed: number): number =>
  smoothstep(
    HELICOPTER_ROTOR_CONTROL_BEGIN,
    HELICOPTER_ROTOR_TAKEOFF_SPEED,
    clamp(rotorSpeed, 0, 1),
  );

/** A bounded downwash footprint shared by local and authoritative snow. */
export const resolveHelicopterRotorWash = (
  altitude: number,
  rotorSpeed: number,
): HelicopterRotorWashEnvelope => {
  const height = Math.max(0, altitude);
  const spinInfluence = smoothstep(
    HELICOPTER_ROTOR_WASH_BEGIN,
    HELICOPTER_ROTOR_TAKEOFF_SPEED,
    clamp(rotorSpeed, 0, 1),
  );
  const heightInfluence = 1 - smoothstep(
    0.65,
    HELICOPTER_ROTOR_WASH_MAXIMUM_ALTITUDE,
    height,
  );
  return {
    strength: clamp(spinInfluence * heightInfluence, 0, 1),
    // The stream spreads slightly before becoming too weak to move snow.
    radius: 3.55 + Math.min(height, HELICOPTER_ROTOR_WASH_MAXIMUM_ALTITUDE) * 0.2,
  };
};

/**
 * The visible surface response to rotor wash is a broad, low annulus. The
 * airborne plume carries the dramatic motion; concentrating conserved field
 * mass into a few small lobes would create implausible snow needles.
 */
export const resolveHelicopterRotorWashDrift = (
  footprintRadius: number,
  altitude: number,
): HelicopterRotorWashDriftEnvelope => ({
  innerRadius: Math.max(0, footprintRadius - 0.35),
  outerRadius:
    footprintRadius + 2.35 + Math.min(Math.max(0, altitude), 5) * 0.06,
});

/** Gentle mound profile with a non-zero edge so the drift has no hard rim. */
export const helicopterRotorWashDriftWeight = (
  distance: number,
  drift: Readonly<HelicopterRotorWashDriftEnvelope>,
): number => {
  if (distance < drift.innerRadius || distance > drift.outerRadius) return 0;
  const width = Math.max(0.001, drift.outerRadius - drift.innerRadius);
  const progress = clamp((distance - drift.innerRadius) / width, 0, 1);
  const mound = Math.sin(progress * Math.PI);
  return 0.72 + mound * mound * 0.28;
};
