export type PenguinControlMode =
  | 'WASD'
  | 'MOUSE_STEERING'
  | 'WASD_ONLY';

export interface ControlSettings {
  realisticSteering: boolean;
  penguinControlMode: PenguinControlMode;
  /** Restores the authored OTS pitch after an inspect drag and a short hold. */
  otsCameraPitchAutoReturn: boolean;
  otsCameraShoulder: 'LEFT' | 'RIGHT';
}

export const DEFAULT_CONTROL_SETTINGS: Readonly<ControlSettings> =
  Object.freeze({
    realisticSteering: false,
    penguinControlMode: 'WASD',
    // A player-authored view should remain where it was left. The old soft
    // reset is still available as an accessibility/preference toggle.
    otsCameraPitchAutoReturn: false,
    otsCameraShoulder: 'RIGHT',
  });

const STORAGE_KEY = 'iceway-controls-v3';
const LEGACY_STORAGE_KEYS = [
  'iceway-controls-v2',
  'iceway-controls-v1',
] as const;

export class ControlSettingsStore {
  public load(): ControlSettings {
    try {
      const raw =
        window.localStorage.getItem(STORAGE_KEY) ??
        LEGACY_STORAGE_KEYS
          .map((key) => window.localStorage.getItem(key))
          .find((candidate) => candidate !== null);
      if (!raw) return { ...DEFAULT_CONTROL_SETTINGS };
      const parsed = JSON.parse(raw) as Partial<ControlSettings> & {
        mirroredSteering?: unknown;
      };
      return {
        realisticSteering:
          typeof parsed.realisticSteering === 'boolean'
            ? parsed.realisticSteering
            : typeof parsed.mirroredSteering === 'boolean'
              ? parsed.mirroredSteering
              : DEFAULT_CONTROL_SETTINGS.realisticSteering,
        penguinControlMode:
          parsed.penguinControlMode === 'WASD' ||
          parsed.penguinControlMode === 'MOUSE_STEERING' ||
          parsed.penguinControlMode === 'WASD_ONLY'
            ? parsed.penguinControlMode
            : DEFAULT_CONTROL_SETTINGS.penguinControlMode,
        otsCameraPitchAutoReturn:
          typeof parsed.otsCameraPitchAutoReturn === 'boolean'
            ? parsed.otsCameraPitchAutoReturn
            : DEFAULT_CONTROL_SETTINGS.otsCameraPitchAutoReturn,
        otsCameraShoulder: parsed.otsCameraShoulder === 'LEFT' || parsed.otsCameraShoulder === 'RIGHT'
          ? parsed.otsCameraShoulder : DEFAULT_CONTROL_SETTINGS.otsCameraShoulder,
      };
    } catch {
      return { ...DEFAULT_CONTROL_SETTINGS };
    }
  }

  public save(settings: Readonly<ControlSettings>): void {
    try {
      window.localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({
          realisticSteering: settings.realisticSteering,
          penguinControlMode: settings.penguinControlMode,
          otsCameraPitchAutoReturn: settings.otsCameraPitchAutoReturn,
          otsCameraShoulder: settings.otsCameraShoulder,
        }),
      );
    } catch {
      // Control settings are non-critical when storage is unavailable.
    }
  }
}
