import { clamp, smoothstep } from '../utils/math';

export interface WorldWindFieldInput {
  readonly timeSeconds: number;
  readonly x: number;
  readonly z: number;
  readonly directionRadians: number;
  readonly baseStrength: number;
  readonly forecastGust: number;
  readonly snowIntensity?: number;
}

export interface WorldWindFieldSample {
  readonly timeSeconds: number;
  readonly directionX: number;
  readonly directionZ: number;
  readonly strength: number;
  readonly gust: number;
  readonly precipitationMultiplier: number;
  readonly whiteout: number;
}

/**
 * A deterministic, world-space weather front. It is analytic rather than a
 * texture or CPU grid, so every tree, flake and future flag can ask the same
 * question at any coordinate without maintaining per-chunk simulation data.
 * The broad bands travel downwind; the slower cross-wave makes their edge
 * irregular instead of producing a ruler-straight wall of weather.
 */
export const sampleWorldWindField = (
  input: Readonly<WorldWindFieldInput>,
): WorldWindFieldSample => {
  const baseX = Math.cos(input.directionRadians);
  const baseZ = Math.sin(input.directionRadians);
  const crossX = -baseZ;
  const crossZ = baseX;
  const along = input.x * baseX + input.z * baseZ;
  const across = input.x * crossX + input.z * crossZ;
  const edgeWarp = Math.sin(across * 0.017 + input.timeSeconds * 0.027) * 0.72;
  const broadWave = 0.5 + 0.5 * Math.sin(
    along * 0.031 - input.timeSeconds * 0.46 + edgeWarp,
  );
  const detailWave = 0.5 + 0.5 * Math.sin(
    along * 0.071 - input.timeSeconds * 0.83 - across * 0.012 + 1.7,
  );
  const broadFront = smoothstep(0.34, 0.9, broadWave);
  const squall = smoothstep(0.68, 0.98, broadWave * 0.68 + detailWave * 0.32);
  const forecast = clamp(input.forecastGust, 0, 1);
  const gust = clamp(
    0.12 + forecast * 0.34 + broadFront * 0.43 + squall * 0.22,
    0,
    1,
  );
  const turn = (
    Math.sin(along * 0.013 - input.timeSeconds * 0.035 + across * 0.006) * 0.035 +
    Math.sin(input.timeSeconds * 0.009 + across * 0.009) * 0.012
  ) * (0.32 + gust * 0.68);
  const turnedX = baseX * Math.cos(turn) - baseZ * Math.sin(turn);
  const turnedZ = baseX * Math.sin(turn) + baseZ * Math.cos(turn);
  const snowIntensity = clamp(input.snowIntensity ?? 0, 0, 1);
  const precipitationMultiplier = clamp(
    0.08 + broadFront * 0.86 + squall * (0.18 + snowIntensity * 0.5),
    0.06,
    1.7,
  );
  const whiteout = smoothstep(
    0.68,
    1.18,
    snowIntensity * precipitationMultiplier * (0.78 + gust * 0.36),
  );
  return {
    timeSeconds: Math.max(0, input.timeSeconds),
    directionX: turnedX,
    directionZ: turnedZ,
    strength: clamp(input.baseStrength, 0, 2.8) * (0.48 + gust * 0.58),
    gust,
    precipitationMultiplier,
    whiteout,
  };
};

/** GLSL twin of the CPU field for instanced vegetation and attached snow. */
export const WORLD_WIND_FIELD_GLSL = `
vec3 icewaySampleWorldWind(
  vec2 icewayWorldXZ,
  float icewayTime,
  vec2 icewayBaseDirection,
  float icewayForecastGust
) {
  vec2 icewayBase = normalize(icewayBaseDirection);
  vec2 icewayCross = vec2(-icewayBase.y, icewayBase.x);
  float icewayAlong = dot(icewayWorldXZ, icewayBase);
  float icewayAcross = dot(icewayWorldXZ, icewayCross);
  float icewayEdgeWarp = sin(icewayAcross * 0.017 + icewayTime * 0.027) * 0.72;
  float icewayBroadWave = 0.5 + 0.5 * sin(
    icewayAlong * 0.031 - icewayTime * 0.46 + icewayEdgeWarp
  );
  float icewayDetailWave = 0.5 + 0.5 * sin(
    icewayAlong * 0.071 - icewayTime * 0.83 - icewayAcross * 0.012 + 1.7
  );
  float icewayBroadFront = smoothstep(0.34, 0.9, icewayBroadWave);
  float icewaySquall = smoothstep(
    0.68,
    0.98,
    icewayBroadWave * 0.68 + icewayDetailWave * 0.32
  );
  float icewayGust = clamp(
    0.12 + clamp(icewayForecastGust, 0.0, 1.0) * 0.34 +
      icewayBroadFront * 0.43 + icewaySquall * 0.22,
    0.0,
    1.0
  );
  float icewayTurn = (
    sin(icewayAlong * 0.013 - icewayTime * 0.035 + icewayAcross * 0.006) * 0.035 +
    sin(icewayTime * 0.009 + icewayAcross * 0.009) * 0.012
  ) * (0.32 + icewayGust * 0.68);
  float icewayCosTurn = cos(icewayTurn);
  float icewaySinTurn = sin(icewayTurn);
  vec2 icewayLocalDirection = vec2(
    icewayBase.x * icewayCosTurn - icewayBase.y * icewaySinTurn,
    icewayBase.x * icewaySinTurn + icewayBase.y * icewayCosTurn
  );
  return vec3(icewayLocalDirection, icewayGust);
}
`;
