import { Camera, PointLight, Scene, type Light, type Object3D } from 'three';
import { IsolationRenderScope } from '../performance/ScenePerformanceIsolation';

// A small set of precompilable forward-light variants. Never cap active lights:
// the last bucket grows for unusually large authored scenes.
export const LOCAL_LIGHT_TIERS = [0, 1, 2, 4, 8, 16, 24, 32] as const;
export const localLightTier = (count: number): number =>
  LOCAL_LIGHT_TIERS.find(tier => tier >= count) ?? Math.ceil(count / 16) * 16;

/** Render-only filtering. Simulation owns visibility, intensity and lifetime.
 * An extinguished light must leave Three's light list, not merely have zero RGB.
 * Padding reduces shader permutations without limiting genuine light sources.
 */
export class LocalLightRenderPolicy {
  private readonly padding: PointLight[] = [];
  public stats = { activePoints: 0, pointSlots: 0, activeSpots: 0, skipped: 0 };

  public apply(scene: Scene, camera: Camera, scope: IsolationRenderScope, warmTier?: number): void {
    let points = 0, spots = 0, skipped = 0;
    scene.traverseVisible((object: Object3D) => {
      const light = object as Light & { isPointLight?: boolean; isSpotLight?: boolean };
      if ((!light.isPointLight && !light.isSpotLight) || light.userData.localLightPadding) return;
      if (!light.layers.test(camera.layers)) return;
      const hasEnergy = light.intensity > 0 && Math.max(light.color.r, light.color.g, light.color.b) > 0;
      if (warmTier !== undefined || !hasEnergy || light.userData.longWinterExcludedLight === true) {
        scope.set(light, 'visible', false); skipped++;
      } else if (light.isPointLight) points++;
      else spots++;
    });
    const slots = warmTier ?? localLightTier(points);
    while (this.padding.length < slots - points) {
      const light = new PointLight(0xffffff, 0, 1);
      light.name = 'Local light shader tier padding';
      light.userData.localLightPadding = true;
      light.visible = false;
      this.padding.push(light); scene.add(light);
    }
    for (let i = 0; i < slots - points; i++) {
      const light = this.padding[i]!;
      scope.set(light.layers, 'mask', camera.layers.mask);
      scope.set(light, 'visible', true);
    }
    if (warmTier === undefined) this.stats = { activePoints: points, pointSlots: slots, activeSpots: spots, skipped };
  }

  public dispose(): void { for (const light of this.padding) light.removeFromParent(); this.padding.length = 0; }
}
