import type { SettlementContentRegistry } from './SettlementContentRegistry';
import type {
  SettlementAnimalGrowthStage,
  SettlementAnimalHabitatDefinition,
  SettlementAnimalHabitatRuntimeState,
  SettlementAnimalHabitatUpgradeDefinition,
  SettlementAnimalHabitatView,
  SettlementAnimalRuntimeState,
  SettlementAnimalSaveData,
  SettlementAnimalSpeciesDefinition,
  SettlementAnimalView,
  SettlementGoodAmount,
  SettlementMutationResult,
} from './SettlementTypes';
import type { SettlementWarehouse } from './SettlementWarehouse';

interface MutableAnimalState {
  animalId: string;
  habitatId: string;
  speciesId: string;
  bornAt: number;
  nextProductAt: number;
  productReady: boolean;
  collectedProducts: number;
  revision: number;
}

interface MutableHabitatState {
  habitatId: string;
  upgradeLevel: number;
  revision: number;
}

const cloneAnimal = (
  state: Readonly<MutableAnimalState>,
): SettlementAnimalRuntimeState => ({ ...state });

const cloneHabitat = (
  state: Readonly<MutableHabitatState>,
): SettlementAnimalHabitatRuntimeState => ({ ...state });

const mergeAmounts = (
  amounts: readonly Readonly<SettlementGoodAmount>[],
): readonly SettlementGoodAmount[] => {
  const merged = new Map<string, number>();
  for (const amount of amounts) {
    merged.set(amount.goodId, (merged.get(amount.goodId) ?? 0) + amount.quantity);
  }
  return [...merged]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([goodId, quantity]) => ({ goodId, quantity }));
};

/**
 * Cozy livestock state: animals grow and eventually offer products, but never
 * starve, die or create a punishment spiral while the player is away.
 */
export class SettlementAnimalSystem {
  private readonly habitats = new Map<string, MutableHabitatState>();
  private readonly animals = new Map<string, MutableAnimalState>();

  public constructor(
    private readonly registry: SettlementContentRegistry,
    private readonly warehouse: SettlementWarehouse,
    saved?: Readonly<SettlementAnimalSaveData>,
  ) {
    for (const habitat of registry.definitions.animalHabitats ?? []) {
      this.habitats.set(habitat.id, {
        habitatId: habitat.id,
        upgradeLevel: 0,
        revision: 0,
      });
      const species = registry.getAnimalSpecies(habitat.speciesId);
      if (!species) continue;
      for (let index = 0; index < habitat.initialAnimalCount; index += 1) {
        const bornAt = index * -Math.min(30, species.growthStageSeconds[0] * 0.2);
        const adultAt = bornAt + species.growthStageSeconds[1];
        const animalId = `${habitat.id}.animal-${String(index + 1).padStart(2, '0')}`;
        this.animals.set(animalId, {
          animalId,
          habitatId: habitat.id,
          speciesId: species.id,
          bornAt,
          nextProductAt: adultAt + species.product.intervalSeconds,
          productReady: false,
          collectedProducts: 0,
          revision: 0,
        });
      }
    }
    if (saved?.version === 1) {
      for (const candidate of saved.habitats ?? []) this.importHabitat(candidate);
      for (const candidate of saved.animals ?? []) this.importAnimal(candidate);
    }
  }

  public upgradeHabitat(
    habitatId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    const definition = this.registry.getAnimalHabitat(habitatId);
    const state = this.habitats.get(habitatId);
    const next = definition && state
      ? definition.upgrades.find((upgrade) => upgrade.level === state.upgradeLevel + 1)
      : undefined;
    if (!definition || !state) return this.rejected('ANIMAL_HABITAT_INVALID');
    if (!next) return this.rejected('ANIMAL_HABITAT_FULLY_UPGRADED');
    if (!this.warehouse.canApply(next.costs, -1) ||
      !this.warehouse.apply(next.costs, -1)) {
      return this.rejected('ANIMAL_HABITAT_MATERIALS_MISSING');
    }
    state.upgradeLevel = next.level;
    state.revision += 1;
    const species = this.registry.getAnimalSpecies(definition.speciesId);
    if (species) {
      const interval = species.product.intervalSeconds * next.productIntervalMultiplier;
      for (const animal of this.animalsForHabitat(habitatId)) {
        if (animal.productReady) continue;
        const adultAt = animal.bornAt + species.growthStageSeconds[1];
        animal.nextProductAt = Math.min(
          animal.nextProductAt,
          Math.max(Math.max(0, simulationTime), adultAt) + interval,
        );
        animal.revision += 1;
      }
      const existing = this.animalsForHabitat(habitatId);
      for (let index = existing.length; index < next.capacity; index += 1) {
        const bornAt = Math.max(0, simulationTime);
        const animalId = `${habitatId}.animal-${String(index + 1).padStart(2, '0')}`;
        this.animals.set(animalId, {
          animalId,
          habitatId,
          speciesId: species.id,
          bornAt,
          nextProductAt: bornAt + species.growthStageSeconds[1] + interval,
          productReady: false,
          collectedProducts: 0,
          revision: 0,
        });
      }
    }
    return this.accepted('ANIMAL_HABITAT_UPGRADED', next.level);
  }

  /** Same canonical pickup for god mode and the later nearby F interaction. */
  public collectHabitatProducts(
    habitatId: string,
    simulationTime: number,
  ): SettlementMutationResult {
    const habitat = this.registry.getAnimalHabitat(habitatId);
    const habitatState = this.habitats.get(habitatId);
    const species = habitat
      ? this.registry.getAnimalSpecies(habitat.speciesId)
      : undefined;
    if (!habitat || !habitatState || !species) {
      return this.rejected('ANIMAL_HABITAT_INVALID');
    }
    const tuning = this.resolveTuning(habitat, habitatState);
    const ready = this.animalsForHabitat(habitatId).filter((animal) =>
      this.stage(species, animal, simulationTime).stage === 'ADULT' &&
      (animal.productReady || simulationTime >= animal.nextProductAt));
    if (ready.length === 0) return this.rejected('ANIMAL_PRODUCTS_NOT_READY');
    const outputs = mergeAmounts(ready.flatMap(() =>
      species.product.outputs.map((output) => ({
        goodId: output.goodId,
        quantity: output.quantity + tuning.quantityBonus,
      }))));
    if (!this.warehouse.canApply(outputs, 1) || !this.warehouse.apply(outputs, 1)) {
      return this.rejected('WAREHOUSE_FULL');
    }
    const now = Math.max(0, simulationTime);
    for (const animal of ready) {
      animal.productReady = false;
      animal.nextProductAt = now + species.product.intervalSeconds * tuning.intervalMultiplier;
      animal.collectedProducts += 1;
      animal.revision += 1;
    }
    return this.accepted(
      `ANIMAL_${species.product.pickupKind}_COLLECTED`,
      outputs.reduce((sum, output) => sum + output.quantity, 0),
    );
  }

  public update(simulationTime: number): boolean {
    let changed = false;
    for (const animal of this.animals.values()) {
      if (animal.productReady) continue;
      const species = this.registry.getAnimalSpecies(animal.speciesId);
      if (!species || this.stage(species, animal, simulationTime).stage !== 'ADULT') continue;
      if (simulationTime < animal.nextProductAt) continue;
      animal.productReady = true;
      animal.revision += 1;
      changed = true;
    }
    return changed;
  }

  public getHabitatView(
    habitatId: string,
    simulationTime: number,
  ): SettlementAnimalHabitatView | undefined {
    const definition = this.registry.getAnimalHabitat(habitatId);
    const state = this.habitats.get(habitatId);
    const region = definition
      ? this.registry.getSeasonRegion(definition.regionId)
      : undefined;
    const species = definition
      ? this.registry.getAnimalSpecies(definition.speciesId)
      : undefined;
    if (!definition || !state || !region || !species) return undefined;
    const tuning = this.resolveTuning(definition, state);
    const currentUpgrade = definition.upgrades.find((entry) =>
      entry.level === state.upgradeLevel);
    return {
      ...cloneHabitat(state),
      displayName: definition.displayName,
      regionId: definition.regionId,
      season: region.season,
      x: definition.x,
      z: definition.z,
      interactionRadius: definition.interactionRadius,
      capacity: currentUpgrade?.capacity ?? Math.max(1, definition.initialAnimalCount),
      productIntervalMultiplier: tuning.intervalMultiplier,
      productQuantityBonus: tuning.quantityBonus,
      nextUpgrade: definition.upgrades.find((entry) =>
        entry.level === state.upgradeLevel + 1),
      animals: this.animalsForHabitat(habitatId).map((animal) =>
        this.animalView(species, animal, simulationTime, tuning.intervalMultiplier,
          tuning.quantityBonus)),
    };
  }

  public getHabitatViews(simulationTime: number): readonly SettlementAnimalHabitatView[] {
    return (this.registry.definitions.animalHabitats ?? []).flatMap((habitat) => {
      const view = this.getHabitatView(habitat.id, simulationTime);
      return view ? [view] : [];
    });
  }

  public exportState(): SettlementAnimalSaveData {
    return {
      version: 1,
      habitats: [...this.habitats.values()]
        .sort((left, right) => left.habitatId.localeCompare(right.habitatId))
        .map(cloneHabitat),
      animals: [...this.animals.values()]
        .sort((left, right) => left.animalId.localeCompare(right.animalId))
        .map(cloneAnimal),
    };
  }

  private animalView(
    species: Readonly<SettlementAnimalSpeciesDefinition>,
    animal: Readonly<MutableAnimalState>,
    simulationTime: number,
    intervalMultiplier: number,
    quantityBonus: number,
  ): SettlementAnimalView {
    const growth = this.stage(species, animal, simulationTime);
    const productReady = growth.stage === 'ADULT' &&
      (animal.productReady || simulationTime >= animal.nextProductAt);
    const interval = Math.max(0.001,
      species.product.intervalSeconds * intervalMultiplier);
    return {
      ...cloneAnimal(animal),
      displayName: species.displayName,
      kind: species.kind,
      stage: growth.stage,
      growth: growth.growth,
      productReady,
      productGrowth: growth.stage !== 'ADULT'
        ? 0
        : productReady
          ? 1
          : Math.max(0, Math.min(1, 1 - (animal.nextProductAt - simulationTime) / interval)),
      productPickupKind: species.product.pickupKind,
      productOutputs: species.product.outputs.map((output) => ({
        goodId: output.goodId,
        quantity: output.quantity + quantityBonus,
      })),
    };
  }

  private stage(
    species: Readonly<SettlementAnimalSpeciesDefinition>,
    animal: Readonly<MutableAnimalState>,
    simulationTime: number,
  ): Readonly<{ stage: SettlementAnimalGrowthStage; growth: number }> {
    const age = Math.max(0, simulationTime - animal.bornAt);
    const [youngAt, adultAt] = species.growthStageSeconds;
    return {
      stage: age >= adultAt ? 'ADULT' : age >= youngAt ? 'YOUNG' : 'BABY',
      growth: Math.max(0, Math.min(1, age / Math.max(0.001, adultAt))),
    };
  }

  private resolveTuning(
    definition: Readonly<SettlementAnimalHabitatDefinition>,
    state: Readonly<MutableHabitatState>,
  ): Readonly<{ intervalMultiplier: number; quantityBonus: number }> {
    const upgrade = definition.upgrades.find((entry) =>
      entry.level === state.upgradeLevel);
    return {
      intervalMultiplier: upgrade?.productIntervalMultiplier ?? 1,
      quantityBonus: upgrade?.productQuantityBonus ?? 0,
    };
  }

  private animalsForHabitat(habitatId: string): MutableAnimalState[] {
    return [...this.animals.values()]
      .filter((animal) => animal.habitatId === habitatId)
      .sort((left, right) => left.animalId.localeCompare(right.animalId));
  }

  private importHabitat(
    candidate: Readonly<SettlementAnimalHabitatRuntimeState>,
  ): void {
    const definition = this.registry.getAnimalHabitat(candidate?.habitatId);
    const state = definition ? this.habitats.get(definition.id) : undefined;
    if (!definition || !state) return;
    const maximumLevel = definition.upgrades.at(-1)?.level ?? 0;
    state.upgradeLevel = Number.isSafeInteger(candidate.upgradeLevel)
      ? Math.max(0, Math.min(maximumLevel, candidate.upgradeLevel))
      : 0;
    state.revision = Number.isSafeInteger(candidate.revision) && candidate.revision >= 0
      ? candidate.revision
      : 0;
  }

  private importAnimal(candidate: Readonly<SettlementAnimalRuntimeState>): void {
    const habitat = this.registry.getAnimalHabitat(candidate?.habitatId);
    const species = this.registry.getAnimalSpecies(candidate?.speciesId);
    if (!habitat || !species || habitat.speciesId !== species.id ||
      typeof candidate.animalId !== 'string' || candidate.animalId.length > 192 ||
      !Number.isFinite(candidate.bornAt) || !Number.isFinite(candidate.nextProductAt)) return;
    this.animals.set(candidate.animalId, {
      animalId: candidate.animalId,
      habitatId: habitat.id,
      speciesId: species.id,
      bornAt: Math.min(candidate.bornAt, candidate.nextProductAt),
      nextProductAt: Math.max(0, candidate.nextProductAt),
      productReady: candidate.productReady === true,
      collectedProducts: Number.isSafeInteger(candidate.collectedProducts) &&
        candidate.collectedProducts >= 0 ? candidate.collectedProducts : 0,
      revision: Number.isSafeInteger(candidate.revision) && candidate.revision >= 0
        ? candidate.revision
        : 0,
    });
  }

  private accepted(status: string, quantity: number): SettlementMutationResult {
    return { accepted: true, stateChanged: true, status, quantity };
  }

  private rejected(status: string): SettlementMutationResult {
    return { accepted: false, stateChanged: false, status };
  }
}
