import { Ray, Vector3 } from 'three';
import type { SurvivalBuildPieceDefinition } from '../SurvivalBuildingCatalog';

/** One cursor plane, not a list of surfaces. Wheel input never selects a host.
 * Its depth is camera-space Z, so sideways motion is planar, not spherical. */
export class SurvivalFreePlacementCursor {
  private depth?: number;
  private surfaceKey?: string;
  private surfaceOffset = 0;
  private readonly normal = new Vector3();
  private readonly offset = new Vector3();
  readonly point = new Vector3();
  get distance(): number | undefined { return this.depth; }
  reset(): void { this.depth = undefined; this.surfaceKey = undefined; this.surfaceOffset = 0; }
  /** Furniture follows the pointed surface every frame. Wheel is a deliberate
   * offset from that surface, not a depth lock shared with structural pieces. */
  sampleSurface(ray: Readonly<Ray>, seed: Readonly<Vector3>, key: string, forward?: Readonly<Vector3>): Vector3 {
    if (key !== this.surfaceKey) this.surfaceOffset = 0;
    this.surfaceKey = key;
    this.depth = undefined;
    this.sample(ray, seed, forward);
    this.depth = Math.max(.35, Math.min(100, this.depth! + this.surfaceOffset));
    return this.sample(ray, seed, forward);
  }
  sample(ray: Readonly<Ray>, seed: Readonly<Vector3>, forward?: Readonly<Vector3>): Vector3 {
    if (forward) this.normal.copy(forward).normalize();
    else if (this.depth === undefined) this.normal.copy(ray.direction).normalize();
    if (this.depth === undefined) this.depth = Math.max(.35,
      Math.min(100, this.offset.copy(seed).sub(ray.origin).dot(this.normal)));
    const divisor = ray.direction.dot(this.normal);
    // Rays behind the plane cannot turn a ghost inside out.
    return ray.at(this.depth / Math.max(.1, divisor), this.point);
  }
  wheel(deltaY: number, deltaMode = 0): void {
    if (!Number.isFinite(deltaY) || this.depth === undefined) return;
    const pixels = deltaY * (deltaMode === 1 ? 16 : deltaMode === 2 ? 400 : 1);
    const next = Math.max(.35, Math.min(100, this.depth + Math.max(-.65, Math.min(.65, pixels * .0025))));
    this.surfaceOffset += next - this.depth;
    this.depth = next;
  }
}

export type FreeMountKind = 'BELOW' | 'WALL' | 'CEILING';
export function freePlacementMount(definition: SurvivalBuildPieceDefinition): FreeMountKind | undefined {
  if (definition.placementSupport) return definition.placementSupport;
  if (definition.ceilingMounted) return 'CEILING';
  if (definition.sockets.some(s => s.kind === 'WALL_MOUNT' && s.placementRole === 'SOURCE')) return 'WALL';
  // Chimneys and cooking inserts retain their dedicated functional connections.
  if (definition.family === 'UTILITY' && definition.groundPlacement !== 'REQUIRES_SOCKET' &&
    !definition.id.startsWith('CHIMNEY') && definition.id !== 'FIREPLACE_COOKING_INSERT') return 'BELOW';
  return undefined;
}

export function snapLocalCoordinate(value: number, step: number): number {
  return step > 0 ? Math.round(value / step) * step : value;
}

/** Narrow freehand capture; G makes the 3x3 alignment deliberately stronger.
 * Points are inset on the face, never hidden on its opposite side. */
export function nearestWallAlignment(u: number, y: number, halfWidth: number, height: number, grid: boolean):
  { u: number; y: number; column: number; row: number } | undefined {
  let best: {u:number;y:number;column:number;row:number;distance:number} | undefined;
  for (let row=0;row<3;row++) for (let column=0;column<3;column++) {
    const point={u:(column-1)*halfWidth*.72,y:height*(.26+row*.26),column,row};
    const distance=Math.hypot(point.u-u,point.y-y);
    if(distance <= (grid ? .34 : .055) && (!best || distance<best.distance)) best={...point,distance};
  }
  return best;
}
