import {
  clamp,
  smoothstep,
  valueNoise2D,
} from '../utils/math';

export const AMBIENT_ICE_FORMATION_TUNING = Object.freeze({
  minimumOpenOpenness: 0.72,
  fringeRadiusCells: 2.65,
  boundaryNoiseCells: 0.48,
  maximumMaturity: 0.42,
});

export const buildAmbientIceFormationField = (
  openness: ArrayLike<number>,
  columns: number,
  rows: number,
  eligibility?: ArrayLike<number>,
): Float32Array => {
  const count = Math.max(0, columns * rows);
  const result = new Float32Array(count);
  if (
    columns <= 0 ||
    rows <= 0 ||
    openness.length < count ||
    (eligibility !== undefined && eligibility.length < count)
  ) {
    return result;
  }

  const radius = AMBIENT_ICE_FORMATION_TUNING.fringeRadiusCells;
  const searchRange = Math.ceil(radius + 1);
  const minimumOpen =
    AMBIENT_ICE_FORMATION_TUNING.minimumOpenOpenness;

  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const index = row * columns + column;
      if (
        eligibility !== undefined &&
        (eligibility[index] ?? 0) <= 0
      ) {
        continue;
      }
      const localOpenness = clamp(openness[index] ?? 0, 0, 1);
      if (localOpenness < minimumOpen) continue;

      let minimumDistance = Number.POSITIVE_INFINITY;
      for (
        let offsetRow = -searchRange;
        offsetRow <= searchRange;
        offsetRow += 1
      ) {
        const neighborRow = row + offsetRow;
        if (neighborRow < 0 || neighborRow >= rows) continue;
        for (
          let offsetColumn = -searchRange;
          offsetColumn <= searchRange;
          offsetColumn += 1
        ) {
          const neighborColumn = column + offsetColumn;
          if (
            neighborColumn < 0 ||
            neighborColumn >= columns
          ) {
            continue;
          }
          const distance = Math.hypot(offsetColumn, offsetRow);
          if (distance <= 0 || distance > radius + 1) continue;
          const neighborIndex =
            neighborRow * columns + neighborColumn;
          if ((openness[neighborIndex] ?? 0) >= minimumOpen) {
            continue;
          }
          minimumDistance = Math.min(minimumDistance, distance);
        }
      }
      if (!Number.isFinite(minimumDistance)) continue;

      const broadNoise = valueNoise2D(
        column * 0.29,
        row * 0.29,
        1601,
      );
      const detailNoise = valueNoise2D(
        column * 0.71,
        row * 0.71,
        1613,
      );
      const effectiveDistance =
        minimumDistance +
        (broadNoise - 0.5) *
          AMBIENT_ICE_FORMATION_TUNING.boundaryNoiseCells;
      const edgeProximity =
        1 - smoothstep(0.72, radius, effectiveDistance);
      const opennessGate = smoothstep(
        minimumOpen - 0.015,
        minimumOpen + 0.08,
        localOpenness,
      );
      const maturityVariation =
        0.9 + broadNoise * 0.08 + detailNoise * 0.06;
      const maturity = clamp(
        edgeProximity *
          maturityVariation *
          AMBIENT_ICE_FORMATION_TUNING.maximumMaturity *
          opennessGate,
        0,
        AMBIENT_ICE_FORMATION_TUNING.maximumMaturity,
      );
      result[index] = maturity < 0.018 ? 0 : maturity;
    }
  }
  return result;
};
