import { clamp } from '../../utils/math';
import type { FirePoint } from './SurvivalFireBehaviour';
import type { SurvivalIndoorAirSample } from '../SurvivalConstructionSystem';

export interface RoomSmokeSource extends FirePoint {
  readonly id: string;
  /** Uncapped physical production; visual plume limits never enter this. */
  readonly production: number;
}
export interface RoomSmokeCell extends FirePoint {
  readonly id: string;
  readonly floorY: number;
  readonly ceilingY: number;
  readonly radius: number;
  readonly volume: number;
  readonly air: SurvivalIndoorAirSample;
  mass: number;
  links: string[];
  exhaust: number;
  outlet?: FirePoint;
}
export interface RoomSmokeOutlet extends FirePoint { readonly id: string; flow: number }
export interface RoomSmokeSave { readonly version: 1; readonly cells: readonly (FirePoint & { readonly mass: number })[] }

/** Sparse, active-room transport, not a world-sized fluid simulation. A cell
 * keeps smoke after a source goes out. Topology is rebuilt on authored edits,
 * with persistent mass retained at stable addresses and bounded discovery. */
export class SurvivalRoomSmoke {
  readonly cells = new Map<string, RoomSmokeCell>();
  readonly outlets = new Map<string, RoomSmokeOutlet>();
  private restored: (FirePoint & { readonly mass: number })[] = [];
  private queue: RoomSmokeCell[] = [];
  private readonly staleCells = new Set<string>();
  private revision = '';
  private accumulator = 0;
  private emptySeconds = 0;
  private sample!: (point: FirePoint) => SurvivalIndoorAirSample;
  private canCross!: (a: FirePoint, b: FirePoint) => boolean;
  private readonly stepMetres = 1.5;
  public lastStepMs = 0;
  public pendingCells = 0;

  update(delta: number, sources: readonly RoomSmokeSource[], revision: string,
    sample: (point: FirePoint) => SurvivalIndoorAirSample,
    canCross: (a: FirePoint, b: FirePoint) => boolean): void {
    if (delta <= 0) return;
    this.sample = sample; this.canCross = canCross;
    if (this.cells.size === 0 && sources.length === 0 && this.restored.length === 0) {
      this.lastStepMs = 0; this.pendingCells = 0; return;
    }
    this.accumulator += Math.min(delta, 0.25);
    if (this.accumulator < 0.25) return;
    const start = performance.now();
    const dt = this.accumulator; this.accumulator = 0;
    if (this.revision !== revision) {
      this.revision = revision;
      this.queue = [...new Map([...this.queue, ...this.cells.values()]
        .filter((cell) => this.cells.has(cell.id)).map((cell) => [cell.id, cell])).values()];
      this.staleCells.clear();
      for (const cell of this.cells.values()) {
        this.staleCells.add(cell.id); cell.links = []; cell.exhaust = 0; cell.outlet = undefined;
      }
    }
    // Saved smoke is warmed incrementally instead of hundreds of cold air
    // queries in the first frame. Export also preserves the pending cells.
    for (const old of this.restored.splice(0, 12)) {
      const cell = this.cellAt(old); if (cell) cell.mass += old.mass;
    }
    for (const source of sources) {
      const cell = this.cellAt(source);
      if (cell) cell.mass += Math.max(0, source.production) * dt;
    }
    // New buildings discover at most 24 cells per tick, not hundreds of room
    // samples in the placement frame. Stable rooms do no topology work.
    for (let count = 0; count < 24 && this.queue.length; count += 1) {
      const queued = this.queue.shift()!;
      let cell = this.cells.get(queued.id); if (!cell) continue;
      if (this.staleCells.delete(cell.id)) {
        const point = { x: cell.x, y: cell.floorY + 0.55, z: cell.z };
        const air = this.sample(point);
        if (!air.roofed || air.ceilingY === undefined) { this.cells.delete(cell.id); continue; }
        const floorY = air.floorY ?? cell.floorY;
        if (Math.abs(floorY - cell.floorY) > 0.12) {
          const mass = cell.mass; this.cells.delete(cell.id);
          const next = this.cellAt({ ...point, y: floorY + 0.55 }, air);
          if (next) next.mass += mass;
          continue;
        }
        // Keep mass and visibility while bounded topology work catches up.
        // A swinging door must never synchronously re-sample 512 cells.
        cell = { ...cell, air, floorY, ceilingY: air.ceilingY,
          volume: this.stepMetres ** 2 * Math.max(0.6, air.ceilingY - floorY),
          exhaust: !air.indoors ? 0.04 : 0.00015 };
        this.cells.set(cell.id, cell);
      }
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const point = { x: cell.x + dx! * this.stepMetres,
          y: cell.floorY + 0.55, z: cell.z + dz! * this.stepMetres };
        if (!this.canCross({ x: cell.x, y: point.y, z: cell.z }, point)) continue;
        const air = this.sample(point);
        if (!air.roofed) {
          cell.exhaust += 0.5;
          cell.outlet ??= { x: point.x, y: cell.ceilingY + 0.15, z: point.z };
          continue;
        }
        const next = this.cellAt(point, air);
        if (next && next.id !== cell.id) {
          if (!cell.links.includes(next.id)) cell.links.push(next.id);
          if (!next.links.includes(cell.id)) next.links.push(cell.id);
        }
      }
      const vent = cell.air.vent;
      if (vent?.kind === 'STAIR' && Math.hypot(vent.x - cell.x, vent.z - cell.z) < 1.5) {
        const next = this.cellAt({ x: vent.x, y: vent.y + 0.35, z: vent.z });
        if (next && next.id !== cell.id && !cell.links.includes(next.id)) {
          cell.links.push(next.id); next.links.push(cell.id);
        } else if (!next) { cell.exhaust += 0.45; cell.outlet = vent; }
      } else if (vent && vent.kind !== 'STAIR' &&
        Math.hypot(vent.x - cell.x, vent.z - cell.z) < 1.6) {
        cell.exhaust += cell.air.ventilation * 0.45;
        cell.outlet = vent;
      }
    }
    this.pendingCells = this.queue.length + this.restored.length;
    this.outlets.clear();
    const changes = new Map<string, number>();
    for (const cell of this.cells.values()) {
      const concentration = cell.mass / cell.volume;
      for (const id of cell.links) {
        if (id <= cell.id) continue;
        const other = this.cells.get(id); if (!other) continue;
        const deltaDensity = concentration - other.mass / other.volume;
        // Conservative exchange and gentle upward bias through stair portals.
        const rise = Math.sign(other.floorY - cell.floorY) * Math.min(concentration, other.mass / other.volume) * 0.15;
        const raw = (deltaDensity + rise) * dt * 1.8;
        const flow = clamp(raw, -other.mass * 0.08, cell.mass * 0.08);
        changes.set(cell.id, (changes.get(cell.id) ?? 0) - flow);
        changes.set(other.id, (changes.get(other.id) ?? 0) + flow);
      }
      const lost = cell.mass * (1 - Math.exp(-cell.exhaust * dt));
      changes.set(cell.id, (changes.get(cell.id) ?? 0) - lost);
      if (lost > 0.00001 && cell.outlet) {
        const point = cell.outlet;
        const id = `outlet:${Math.round(point.x)}:${Math.round(point.y)}:${Math.round(point.z)}`;
        const outlet = this.outlets.get(id) ?? { id, ...point, flow: 0 };
        outlet.flow += lost / dt; this.outlets.set(id, outlet);
      }
    }
    for (const cell of this.cells.values()) cell.mass = Math.max(0, cell.mass + (changes.get(cell.id) ?? 0));
    this.emptySeconds = sources.length === 0 && [...this.cells.values()].every((c) => c.mass < 0.0001)
      ? this.emptySeconds + dt : 0;
    if (this.emptySeconds > 2 && !this.restored.length) { this.cells.clear(); this.queue = []; this.outlets.clear(); }
    this.lastStepMs = performance.now() - start;
  }

  exportState(): RoomSmokeSave {
    return { version: 1, cells: [...this.cells.values()].filter((c) => c.mass > 0.00001)
      .map((c) => ({ x: c.x, y: c.floorY + 0.55, z: c.z, mass: c.mass })).concat(this.restored) };
  }

  restore(saved?: RoomSmokeSave): void {
    this.cells.clear(); this.outlets.clear(); this.queue = []; this.staleCells.clear(); this.revision = '';
    this.accumulator = 0; this.emptySeconds = 0;
    this.restored = saved?.version === 1 ? saved.cells.slice(0, 512).filter((c) =>
      [c.x, c.y, c.z, c.mass].every(Number.isFinite) && c.mass > 0).map((c) => ({ ...c })) : [];
  }

  private cellAt(point: FirePoint, given?: SurvivalIndoorAirSample): RoomSmokeCell | undefined {
    const air = given ?? this.sample(point);
    if (!air.roofed || air.ceilingY === undefined) return undefined;
    const floorY = air.floorY ?? point.y - 0.55;
    const x = Math.floor(point.x / this.stepMetres) * this.stepMetres + this.stepMetres * 0.5;
    const z = Math.floor(point.z / this.stepMetres) * this.stepMetres + this.stepMetres * 0.5;
    const id = `${Math.floor(point.x / this.stepMetres)}:${Math.round(floorY * 4)}:${Math.floor(point.z / this.stepMetres)}`;
    const existing = this.cells.get(id); if (existing) return existing;
    if (this.cells.size >= 512) return undefined;
    // A cell intersecting a wall uses an inset centre instead of placing its
    // entire smoke layer in the adjoining room.
    const centre = this.canCross(point, { x, y: point.y, z }) ? { x, z } : { x: point.x, z: point.z };
    const cell: RoomSmokeCell = { id, ...centre, y: floorY + 0.55,
      floorY, ceilingY: air.ceilingY, radius: this.stepMetres * 0.5,
      volume: this.stepMetres ** 2 * Math.max(0.6, air.ceilingY - floorY), air,
      mass: 0, links: [], exhaust: !air.indoors ? 0.04 : 0.00015 };
    this.cells.set(id, cell); this.queue.push(cell); return cell;
  }

  exposureAt(point: FirePoint): number {
    let result = 0;
    for (const cell of this.cells.values()) {
      if (Math.abs(point.x - cell.x) > cell.radius || Math.abs(point.z - cell.z) > cell.radius ||
        point.y < cell.floorY || point.y > cell.ceilingY) continue;
      const density = clamp(cell.mass / cell.volume, 0, 2);
      const height = cell.ceilingY - cell.floorY;
      const bottom = cell.ceilingY - Math.min(height, 0.15 + density * height * 1.6);
      result = Math.max(result, density * clamp((point.y - bottom) / 0.3, 0, 1));
    }
    return clamp(result, 0, 1);
  }
}
