import { Float32BufferAttribute, type BufferGeometry } from 'three';
import { clamp, smoothstep } from '../utils/math';
import { queueAttributeUpdate } from '../rendering/AttributeUpdates';

/** The same diagonal as the canonical, MID and macro index buffers (b--c). */
export function winterTriangleHeight(a: number, b: number, c: number, d: number, x: number, z: number): number {
  return x + z <= 1
    ? a + (b - a) * x + (c - a) * z
    : d + (c - d) * (1 - x) + (b - d) * (1 - z);
}

/** Coverage is physical snow, never inferred from a ground-coloured albedo. */
export const winterSnowCoverage = (depth: number): number => smoothstep(0.018, 0.15, Math.max(0, depth));

/** Reuses coarse vertices already present in the canonical grid. No new mass queries. */
export function updateWinterCoarseTargets(geometry: BufferGeometry, segments: number, coarseStride: number,
  dirty?: Readonly<{minColumn:number;maxColumn:number;minRow:number;maxRow:number}>): void {
  const positions = geometry.getAttribute('position');
  let target = geometry.getAttribute('aWinterCoarseHeight');
  if (!target) {
    target = new Float32BufferAttribute(new Float32Array(positions.count), 1);
    geometry.setAttribute('aWinterCoarseHeight', target);
    dirty = undefined;
  }
  const samples = segments + 1;
  // Only a changed coarse-grid corner can change the receiving 2 m surface.
  // Include both adjacent cells at exact coarse boundaries; unpublished GPU
  // ranges remain queued until Three actually uploads them.
  const bounds=(min:number,max:number):[number,number]|undefined=>{
    const first=Math.ceil(min/coarseStride)*coarseStride,last=Math.floor(max/coarseStride)*coarseStride;
    return first>last?undefined:[Math.max(0,first-coarseStride),Math.min(segments,last+coarseStride)];
  };
  const rows=dirty?bounds(dirty.minRow,dirty.maxRow):[0,segments];
  const columns=dirty?bounds(dirty.minColumn,dirty.maxColumn):[0,segments];
  if(!rows||!columns)return;
  for (let row = rows[0]!; row <= rows[1]!; row++) {
    const near = Math.min(segments - coarseStride, Math.floor(row / coarseStride) * coarseStride);
    const z = clamp((row - near) / coarseStride, 0, 1);
    for (let column = columns[0]!; column <= columns[1]!; column++) {
      const left = Math.min(segments - coarseStride, Math.floor(column / coarseStride) * coarseStride);
      const x = clamp((column - left) / coarseStride, 0, 1);
      const a = near * samples + left, b = a + coarseStride;
      const c = a + coarseStride * samples, d = c + coarseStride;
      target.setX(row * samples + column, winterTriangleHeight(
        positions.getY(a), positions.getY(b), positions.getY(c), positions.getY(d), x, z,
      ));
    }
    queueAttributeUpdate(target as Float32BufferAttribute,row*samples+columns[0]!,columns[1]!-columns[0]!+1);
  }
  target.needsUpdate = true;
}
