import { Box3, Mesh, Raycaster, Vector3, type Object3D } from 'three';

/** CPU disc coverage for camera optics only. The depth-tested sky and shadow
 * maps still own pixel silhouettes and world illumination respectively. */
export class SurvivalBuildingOptics {
  private readonly ray = new Raycaster();
  private readonly forward = new Vector3();
  private readonly right = new Vector3();
  private readonly up = new Vector3();
  private readonly direction = new Vector3();
  private readonly point = new Vector3();

  sample(
    origin: Readonly<{ x: number; y: number; z: number }>,
    direction: Readonly<{ x: number; y: number; z: number }>,
    radius: number,
    candidates: readonly { root: Object3D; worldBounds: Box3 }[],
  ): number {
    if (!candidates.length) return 1;
    this.forward.set(direction.x, direction.y, direction.z).normalize();
    this.right.set(0, Math.abs(this.forward.y) < .98 ? 1 : 0, Math.abs(this.forward.y) < .98 ? 0 : 1)
      .cross(this.forward).normalize();
    this.up.crossVectors(this.forward, this.right);
    this.ray.near = .025;
    this.ray.far = 96;
    this.ray.ray.origin.set(origin.x, origin.y, origin.z);
    for (const candidate of candidates) candidate.root.updateWorldMatrix(true, true);
    let clear = 0;
    for (let i = 0; i < 13; i++) {
      const angle = (i - 1) * Math.PI / 6;
      const r = i === 0 ? 0 : Math.tan(radius) * .78;
      this.direction.copy(this.forward).addScaledVector(this.right, Math.cos(angle) * r)
        .addScaledVector(this.up, Math.sin(angle) * r).normalize();
      this.ray.ray.direction.copy(this.direction);
      const blocked = candidates.some(candidate => {
        const hit = this.ray.ray.intersectBox(candidate.worldBounds, this.point);
        if (!hit || hit.distanceTo(this.ray.ray.origin) > this.ray.far) return false;
        return this.ray.intersectObject(candidate.root, true).some(intersection => {
          if (!(intersection.object instanceof Mesh) || !intersection.object.castShadow) return false;
          // Hidden replacement geometry/destroyed boards do not seal real
          // openings. Source objects remain available outside the render scope.
          for (let object: Object3D | null = intersection.object; object && object !== candidate.root; object = object.parent) {
            if (object.userData.survivalDamageHidden) return false;
            if (!object.visible && !object.userData.survivalRenderInstanced) return false;
          }
          return true;
        });
      });
      if (!blocked) clear++;
    }
    return clear / 13;
  }
}
