import type { Camera, Vector3 } from 'three';

export type ArcticRenderQuality = 'low' | 'medium' | 'high';

export interface ArcticWaterQualitySettings {
  quality: ArcticRenderQuality;
  microNormalLayers: 1 | 2;
  maxPixelRatio: number;
  enableDepthFoam: boolean;
  enablePlanarReflection: boolean;
  harborReflectionCount: number;
}

export interface IceSurfaceMaterialChannels {
  thickness: number;
  openness: number;
  snow: number;
  wetness: number;
  stress: number;
  edge: number;
}

export const DEFAULT_ARCTIC_WATER_QUALITY: Readonly<ArcticWaterQualitySettings> = {
  quality: 'medium',
  microNormalLayers: 1,
  maxPixelRatio: 1.5,
  enableDepthFoam: false,
  enablePlanarReflection: false,
  harborReflectionCount: 3,
};

export const ARCTIC_WATER_TUNING = {
  fresnelF0: 0.026,
  fresnelStrength: 0.42,
  microNormalStrength: 0.19,
  sunGlintIntensity: 1.08,
  moonGlintIntensity: 0.92,
  iceEdgeFoamIntensity: 0.32,
  harborHopeIntensity: 0.34,
} as const;

export const ICE_SURFACE_TUNING = {
  dryRoughness: 0.86,
  bareRoughness: 0.58,
  wetRoughness: 0.24,
  edgeFresnel: 0.12,
} as const;

export const clampIceSurfaceChannels = (
  channels: Readonly<IceSurfaceMaterialChannels>,
  target: IceSurfaceMaterialChannels,
): IceSurfaceMaterialChannels => {
  target.thickness = clampUnit(channels.thickness);
  target.openness = clampUnit(channels.openness);
  target.snow = clampUnit(channels.snow);
  target.wetness = clampUnit(channels.wetness);
  target.stress = clampUnit(channels.stress);
  target.edge = clampUnit(channels.edge);
  return target;
};

export const updateViewToCameraDirection = (
  camera: Camera,
  target: Vector3,
): Vector3 => camera.getWorldDirection(target).multiplyScalar(-1);

const clampUnit = (value: number): number =>
  Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
