import { clamp, damp } from '../utils/math';

/** Match a normal wheel notch while preserving fine trackpad deltas. */
export function characterCameraWheelDelta(deltaY: number, deltaMode: number, precision: boolean): number {
  if (!Number.isFinite(deltaY) || deltaY === 0) return 0;
  const pixels = deltaY * (deltaMode === 1 ? 40 : deltaMode === 2 ? 360 : 1);
  return -clamp(pixels / 120, -3, 3) * (precision ? 0.24 : 0.12);
}

/** Exact critically damped dolly. Retargeting changes acceleration, never
 * velocity instantaneously, so successive wheel notches join one motion. */
export class CharacterCameraZoom {
  public target: number;
  public velocity = 0;

  public constructor(public value: number, private readonly minimum: number, private readonly maximum: number) {
    this.target = this.value = clamp(value, minimum, maximum);
  }

  public adjust(delta: number): void {
    if (!Number.isFinite(delta)) return;
    this.target = clamp(this.target * Math.exp(-delta * 0.92), this.minimum, this.maximum);
  }

  public update(seconds: number): number {
    const dt = Number.isFinite(seconds) ? clamp(seconds, 0, 0.1) : 0;
    if (dt === 0) return this.value;
    const frequency = 16;
    const offset = this.value - this.target;
    const c = this.velocity + frequency * offset;
    const decay = Math.exp(-frequency * dt);
    const next = this.target + (offset + c * dt) * decay;
    this.velocity = (this.velocity - frequency * c * dt) * decay;
    this.value = clamp(next, this.minimum, this.maximum);
    if (offset * (next - this.target) < 0 ||
      (Math.abs(this.value - this.target) < 0.000001 && Math.abs(this.velocity) < 0.00001)) {
      this.value = this.target;
      this.velocity = 0;
    } else if (this.value !== next) {
      this.velocity = 0;
    }
    return this.value;
  }
}

/** Only obstruction recovery is damped. A changing unobstructed zoom length
 * must not be mistaken for a spring arm recovering from a wall. */
export function advanceCameraClearance(previous: number, fullDistance: number, safeDistance: number, seconds: number): number {
  const allowed = clamp(safeDistance / Math.max(0.0001, fullDistance), 0, 1);
  return !Number.isFinite(previous) || allowed < previous
    ? allowed
    : damp(previous, allowed, 9, clamp(seconds, 0, 0.1));
}
