import {
  isFiniteGlobalPosition,
  type GlobalPosition,
} from '../../world/GlobalPosition';
import type {
  EmergentWorldDefinitionSet,
  MobilityProfileDefinition,
  NpcDefinition,
  RoadSegmentDefinition,
  WorldLocationDefinition,
  WorldServiceDefinition,
  StoryQuestDefinition,
} from './EmergentWorldTypes';

export interface EmergentWorldDefinitionIssue {
  path: string;
  message: string;
}

export class EmergentWorldDefinitionError extends Error {
  public constructor(
    public readonly issues: readonly EmergentWorldDefinitionIssue[],
  ) {
    super(`Invalid emergent world definitions:\n${issues.map((issue) => `- ${issue.path}: ${issue.message}`).join('\n')}`);
    this.name = 'EmergentWorldDefinitionError';
  }
}

const ids = <T extends { id: string }>(
  values: readonly T[],
  path: string,
  issues: EmergentWorldDefinitionIssue[],
): Set<string> => {
  const result = new Set<string>();
  values.forEach((value, index) => {
    if (!value.id.trim()) {
      issues.push({ path: `${path}[${index}].id`, message: 'ID must not be empty' });
    } else if (result.has(value.id)) {
      issues.push({ path: `${path}[${index}].id`, message: `Duplicate ID "${value.id}"` });
    }
    result.add(value.id);
  });
  return result;
};

const deepFreeze = <T>(value: T): T => {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const nested of Object.values(value as Record<string, unknown>)) {
    deepFreeze(nested);
  }
  return Object.freeze(value);
};

export const validateEmergentWorldDefinitions = (
  definitions: Readonly<EmergentWorldDefinitionSet>,
): readonly EmergentWorldDefinitionIssue[] => {
  const issues: EmergentWorldDefinitionIssue[] = [];
  const locationIds = ids(definitions.locations, 'locations', issues);
  const mobilityIds = ids(definitions.mobilityProfiles, 'mobilityProfiles', issues);
  ids(definitions.roadSegments, 'roadSegments', issues);
  const npcIds = ids(definitions.npcs, 'npcs', issues);
  const serviceIds = ids(definitions.services, 'services', issues);
  const roadIds = new Set(definitions.roadSegments.map((road) => road.id));
  ids(definitions.storyQuests, 'storyQuests', issues);
  definitions.locations.forEach((value, index) => {
    if (!isFiniteGlobalPosition(value.worldPosition)) {
      issues.push({ path: `locations[${index}].worldPosition`, message: 'Position must be finite' });
    }
  });
  definitions.mobilityProfiles.forEach((value, index) => {
    if (!(value.speedMetresPerSecond > 0)) {
      issues.push({ path: `mobilityProfiles[${index}].speedMetresPerSecond`, message: 'Speed must be positive' });
    }
    if (!(value.maximumSnowDepth >= 0)) {
      issues.push({ path: `mobilityProfiles[${index}].maximumSnowDepth`, message: 'Snow depth must be non-negative' });
    }
    if (!(value.deepSnowSpeedMultiplier > 0 && value.deepSnowSpeedMultiplier <= 1)) {
      issues.push({ path: `mobilityProfiles[${index}].deepSnowSpeedMultiplier`, message: 'Multiplier must be within (0, 1]' });
    }
  });
  definitions.roadSegments.forEach((value, index) => {
    if (!locationIds.has(value.fromLocationId) || !locationIds.has(value.toLocationId)) {
      issues.push({ path: `roadSegments[${index}]`, message: 'Road endpoints must reference locations' });
    }
    if (value.fromLocationId === value.toLocationId) {
      issues.push({ path: `roadSegments[${index}]`, message: 'Road endpoints must differ' });
    }
    if (!(value.sampleHalfWidth > 0 && value.sampleSpacing > 0)) {
      issues.push({ path: `roadSegments[${index}]`, message: 'Sampling dimensions must be positive' });
    }
    if (value.mobilityClasses.length === 0) {
      issues.push({ path: `roadSegments[${index}].mobilityClasses`, message: 'At least one mobility class is required' });
    }
    (value.waypoints ?? []).forEach((waypoint, waypointIndex) => {
      if (!isFiniteGlobalPosition(waypoint)) {
        issues.push({ path: `roadSegments[${index}].waypoints[${waypointIndex}]`, message: 'Position must be finite' });
      }
    });
    const threshold = value.condition;
    if (
      threshold.reopenAverageDepth > threshold.degradedAverageDepth ||
      threshold.degradedAverageDepth > threshold.blockedAverageDepth ||
      threshold.blockedAverageDepth > threshold.blockedMaximumDepth ||
      threshold.stableSeconds < 0
    ) {
      issues.push({ path: `roadSegments[${index}].condition`, message: 'Road thresholds must be ordered and stable time non-negative' });
    }
  });
  definitions.npcs.forEach((value, index) => {
    if (!locationIds.has(value.spawnLocationId)) {
      issues.push({ path: `npcs[${index}].spawnLocationId`, message: `Missing location "${value.spawnLocationId}"` });
    }
    if (!mobilityIds.has(value.mobilityProfileId)) {
      issues.push({ path: `npcs[${index}].mobilityProfileId`, message: `Missing mobility profile "${value.mobilityProfileId}"` });
    }
    if (!(value.strandedAfterSeconds >= 0)) {
      issues.push({ path: `npcs[${index}].strandedAfterSeconds`, message: 'Stranding delay must be non-negative' });
    }
    const goalIds = new Set<string>();
    value.goals.forEach((goal, goalIndex) => {
      if (goalIds.has(goal.id)) {
        issues.push({ path: `npcs[${index}].goals[${goalIndex}].id`, message: `Duplicate goal "${goal.id}"` });
      }
      goalIds.add(goal.id);
      if (!locationIds.has(goal.targetLocationId)) {
        issues.push({ path: `npcs[${index}].goals[${goalIndex}].targetLocationId`, message: `Missing location "${goal.targetLocationId}"` });
      }
      if (!Number.isFinite(goal.priority) || (goal.startAfterSeconds !== undefined && goal.startAfterSeconds < 0)) {
        issues.push({ path: `npcs[${index}].goals[${goalIndex}]`, message: 'Goal priority must be finite and start delay non-negative' });
      }
      goal.availabilityConditions?.forEach((condition, conditionIndex) => {
        if (
          !condition.factId.trim() ||
          !['EQUALS', 'LESS_THAN_OR_EQUAL', 'GREATER_THAN_OR_EQUAL']
            .includes(condition.operator) ||
          ((condition.operator === 'LESS_THAN_OR_EQUAL' ||
            condition.operator === 'GREATER_THAN_OR_EQUAL') &&
            typeof condition.value !== 'number')
        ) {
          issues.push({
            path: `npcs[${index}].goals[${goalIndex}].availabilityConditions[${conditionIndex}]`,
            message: 'Invalid NPC goal world-fact condition',
          });
        }
      });
    });
  });
  definitions.services.forEach((value, index) => {
    if (!locationIds.has(value.locationId)) {
      issues.push({ path: `services[${index}].locationId`, message: `Missing location "${value.locationId}"` });
    }
    if (value.ownerNpcId && !npcIds.has(value.ownerNpcId)) {
      issues.push({ path: `services[${index}].ownerNpcId`, message: `Missing NPC "${value.ownerNpcId}"` });
    }
    if (value.openWhenStaffed && !value.ownerNpcId) {
      issues.push({ path: `services[${index}].ownerNpcId`, message: 'A staffed service requires an owner NPC' });
    }
  });
  definitions.storyQuests.forEach((quest, questIndex) => {
    if (
      quest.hudPriority !== undefined &&
      !Number.isFinite(quest.hudPriority)
    ) {
      issues.push({
        path: `storyQuests[${questIndex}].hudPriority`,
        message: 'HUD priority must be finite',
      });
    }
    if (quest.hudTitle !== undefined && !quest.hudTitle.trim()) {
      issues.push({
        path: `storyQuests[${questIndex}].hudTitle`,
        message: 'HUD title must not be empty',
      });
    }
    if (
      quest.requestPresentation &&
      !npcIds.has(quest.requestPresentation.sourceNpcId)
    ) {
      issues.push({
        path: `storyQuests[${questIndex}].requestPresentation.sourceNpcId`,
        message: `Missing NPC "${quest.requestPresentation.sourceNpcId}"`,
      });
    }
    if (
      quest.requestPresentation &&
      !locationIds.has(quest.requestPresentation.locationId)
    ) {
      issues.push({
        path: `storyQuests[${questIndex}].requestPresentation.locationId`,
        message: `Missing location "${quest.requestPresentation.locationId}"`,
      });
    }
    (quest.startConditions ?? []).forEach((condition, conditionIndex) => {
      const path = `storyQuests[${questIndex}].startConditions[${conditionIndex}]`;
      if (condition.type !== 'WORLD_FACT') {
        issues.push({ path, message: 'Conditional quest activation currently accepts WORLD_FACT conditions only' });
      } else if (!condition.factId.trim()) {
        issues.push({ path, message: 'World fact ID must not be empty' });
      } else if (
        condition.operator !== 'EQUALS' &&
        typeof condition.value !== 'number'
      ) {
        issues.push({ path, message: 'Ordered world-fact comparisons require a numeric value' });
      }
    });
    const stageIds = ids(quest.stages, `storyQuests[${questIndex}].stages`, issues);
    if (!stageIds.has(quest.initialStageId)) {
      issues.push({ path: `storyQuests[${questIndex}].initialStageId`, message: `Missing stage "${quest.initialStageId}"` });
    }
    const visitedStages = new Set<string>();
    let cursor: string | undefined = quest.initialStageId;
    while (cursor && stageIds.has(cursor)) {
      if (visitedStages.has(cursor)) {
        issues.push({ path: `storyQuests[${questIndex}].stages`, message: `Stage cycle reaches "${cursor}"` });
        break;
      }
      visitedStages.add(cursor);
      cursor = quest.stages.find((stage) => stage.id === cursor)?.nextStageId;
    }
    quest.stages.forEach((stage, stageIndex) => {
      if (stage.hudGuidance !== undefined && !stage.hudGuidance.trim()) {
        issues.push({
          path: `storyQuests[${questIndex}].stages[${stageIndex}].hudGuidance`,
          message: 'HUD guidance must not be empty',
        });
      }
      if (
        stage.hudTargetLocationId !== undefined &&
        !locationIds.has(stage.hudTargetLocationId)
      ) {
        issues.push({
          path: `storyQuests[${questIndex}].stages[${stageIndex}].hudTargetLocationId`,
          message: `Missing location "${stage.hudTargetLocationId}"`,
        });
      }
      if (stage.nextStageId && !stageIds.has(stage.nextStageId)) {
        issues.push({ path: `storyQuests[${questIndex}].stages[${stageIndex}].nextStageId`, message: `Missing stage "${stage.nextStageId}"` });
      }
      stage.completionConditions.forEach((condition, conditionIndex) => {
        const path = `storyQuests[${questIndex}].stages[${stageIndex}].completionConditions[${conditionIndex}]`;
        if (
          (condition.type === 'ROAD_STATUS' || condition.type === 'ROAD_TRAVERSABLE') &&
          !roadIds.has(condition.segmentId)
        ) {
          issues.push({ path, message: `Missing road "${condition.segmentId}"` });
        } else if (
          condition.type === 'ROAD_TRAVERSABLE' &&
          !mobilityIds.has(condition.mobilityProfileId)
        ) {
          issues.push({ path, message: `Missing mobility profile "${condition.mobilityProfileId}"` });
        } else if (
          (condition.type === 'NPC_AT_LOCATION' || condition.type === 'NPC_TRAVEL_STATUS') &&
          !npcIds.has(condition.npcId)
        ) {
          issues.push({ path, message: `Missing NPC "${condition.npcId}"` });
        } else if (condition.type === 'NPC_AT_LOCATION' && !locationIds.has(condition.locationId)) {
          issues.push({ path, message: `Missing location "${condition.locationId}"` });
        } else if (condition.type === 'SERVICE_AVAILABILITY' && !serviceIds.has(condition.serviceId)) {
          issues.push({ path, message: `Missing service "${condition.serviceId}"` });
        } else if (condition.type === 'INCIDENT_STATUS' && !npcIds.has(condition.subjectId)) {
          issues.push({ path, message: `Missing incident subject NPC "${condition.subjectId}"` });
        } else if (condition.type === 'WORLD_FACT' && !condition.factId.trim()) {
          issues.push({ path, message: 'World fact ID must not be empty' });
        } else if (
          condition.type === 'WORLD_FACT' &&
          condition.operator !== 'EQUALS' &&
          typeof condition.value !== 'number'
        ) {
          issues.push({ path, message: 'Ordered world-fact comparisons require a numeric value' });
        }
      });
      const validateActions = (
        actions: typeof stage.onEnterActions,
        phase: 'onEnterActions' | 'onCompleteActions',
      ): void => (actions ?? []).forEach((action, actionIndex) => {
        const path = `storyQuests[${questIndex}].stages[${stageIndex}].${phase}[${actionIndex}]`;
        if (action.type === 'SET_NPC_GOAL') {
          const npc = definitions.npcs.find((value) => value.id === action.npcId);
          if (!npc) issues.push({ path, message: `Missing NPC "${action.npcId}"` });
          else if (action.goalId && !npc.goals.some((goal) => goal.id === action.goalId)) {
            issues.push({ path, message: `Missing goal "${action.goalId}" for NPC "${action.npcId}"` });
          }
        } else if (action.type === 'CREATE_INCIDENT') {
          if (!npcIds.has(action.subjectId)) {
            issues.push({ path, message: `Missing incident subject NPC "${action.subjectId}"` });
          }
          if (!locationIds.has(action.locationId)) {
            issues.push({ path, message: `Missing incident location "${action.locationId}"` });
          }
        }
      });
      validateActions(stage.onEnterActions, 'onEnterActions');
      validateActions(stage.onCompleteActions, 'onCompleteActions');
    });
  });
  if (!Number.isInteger(definitions.director.maximumReportedIncidents) || definitions.director.maximumReportedIncidents < 1) {
    issues.push({ path: 'director.maximumReportedIncidents', message: 'Director budget must be a positive integer' });
  }
  if (!(definitions.director.minimumReportIntervalSeconds >= 0)) {
    issues.push({ path: 'director.minimumReportIntervalSeconds', message: 'Director cooldown must be non-negative' });
  }
  return issues;
};

export class EmergentWorldRegistry {
  public readonly definitions: EmergentWorldDefinitionSet;
  private readonly locations = new Map<string, WorldLocationDefinition>();
  private readonly mobilityProfiles = new Map<string, MobilityProfileDefinition>();
  private readonly roads = new Map<string, RoadSegmentDefinition>();
  private readonly npcs = new Map<string, NpcDefinition>();
  private readonly services = new Map<string, WorldServiceDefinition>();
  private readonly storyQuests = new Map<string, StoryQuestDefinition>();

  public constructor(source: Readonly<EmergentWorldDefinitionSet>) {
    const issues = validateEmergentWorldDefinitions(source);
    if (issues.length > 0) throw new EmergentWorldDefinitionError(issues);
    this.definitions = deepFreeze(structuredClone(source));
    this.index(this.definitions.locations, this.locations);
    this.index(this.definitions.mobilityProfiles, this.mobilityProfiles);
    this.index(this.definitions.roadSegments, this.roads);
    this.index(this.definitions.npcs, this.npcs);
    this.index(this.definitions.services, this.services);
    this.index(this.definitions.storyQuests, this.storyQuests);
  }

  public getLocation(id: string): WorldLocationDefinition | undefined { return this.locations.get(id); }
  public getMobilityProfile(id: string): MobilityProfileDefinition | undefined { return this.mobilityProfiles.get(id); }
  public getRoad(id: string): RoadSegmentDefinition | undefined { return this.roads.get(id); }
  public getNpc(id: string): NpcDefinition | undefined { return this.npcs.get(id); }
  public getService(id: string): WorldServiceDefinition | undefined { return this.services.get(id); }
  public getStoryQuest(id: string): StoryQuestDefinition | undefined { return this.storyQuests.get(id); }

  public getRoadPolyline(id: string): readonly GlobalPosition[] {
    const road = this.roads.get(id);
    if (!road) return [];
    const from = this.locations.get(road.fromLocationId);
    const to = this.locations.get(road.toLocationId);
    return from && to ? [from.worldPosition, ...(road.waypoints ?? []), to.worldPosition] : [];
  }

  private index<T extends { id: string }>(values: readonly T[], target: Map<string, T>): void {
    values.forEach((value) => target.set(value.id, value));
  }
}
