import { PORTS } from '../data/config';
import {
  clamp,
  distancePointToSegment,
  smoothstep,
  valueNoise2D,
} from '../utils/math';
import { WORLD } from '../world/WorldConfig';
import {
  NEEDLE_ISLAND,
  PORT_ACCESS_DISTANCE,
  PORT_ISLAND_SHAPE,
} from '../world/WorldLandmarks';
import {
  borealisCoastX,
} from '../land/BorealisLand';
import {
  sampleBorealisCoastRaster,
} from '../land/BorealisCoastRaster';

export interface OceanBathymetrySample {
  depth: number;
  shoreDistance: number;
  waveExposure: number;
  authoredOverride: number;
}

export interface OceanBathymetryPoint {
  readonly x: number;
  readonly z: number;
}

interface OceanBathymetryIsland extends OceanBathymetryPoint {
  readonly radius: number;
}

interface OceanBathymetryChannel {
  readonly points: readonly OceanBathymetryPoint[];
  readonly halfWidth: number;
  readonly softness: number;
}

export const OCEAN_BATHYMETRY_WIDTH = 192;
export const OCEAN_BATHYMETRY_HEIGHT = 144;
export const OCEAN_BATHYMETRY_WORLD_WIDTH =
  WORLD.gridColumns * WORLD.cellSize + WORLD.seaPadding * 2;
export const OCEAN_BATHYMETRY_WORLD_HEIGHT =
  WORLD.gridRows * WORLD.cellSize + WORLD.seaPadding * 2;

export const OCEAN_BATHYMETRY_TUNING = Object.freeze({
  shoreDistanceRange: 12,
  coastalDepthRange: 9.2,
  minimumCoastalDepth: 0.035,
  coastalDepthGain: 0.72,
  harborDepth: 0.58,
  channelDepth: 0.76,
  harborExposureReduction: 0.76,
});

export const oceanPortAccessPoint = (
  portIndex: number,
): OceanBathymetryPoint => {
  const port = PORTS[portIndex] ?? PORTS[0]!;
  const length = Math.max(
    0.001,
    Math.hypot(port.position.x, port.position.z),
  );
  return {
    x:
      port.position.x -
      port.position.x / length * PORT_ACCESS_DISTANCE,
    z:
      port.position.z -
      port.position.z / length * PORT_ACCESS_DISTANCE,
  };
};

const PORT_ISLANDS: readonly OceanBathymetryIsland[] = PORTS.map(
  (port) => ({
    x: port.position.x,
    z: port.position.z,
    radius:
      port.iceAccess.shoreline.kind === 'circle'
        ? port.iceAccess.shoreline.radius
        : PORT_ISLAND_SHAPE.baseRadius,
  }),
);

export const OCEAN_BATHYMETRY_ISLANDS: readonly OceanBathymetryIsland[] =
  Object.freeze([
    ...PORT_ISLANDS,
    {
      x: NEEDLE_ISLAND.x,
      z: NEEDLE_ISLAND.z,
      radius: NEEDLE_ISLAND.baseRadius,
    },
  ]);

const BOREALIS_ACCESS = oceanPortAccessPoint(0);
const AURORA_ACCESS = oceanPortAccessPoint(1);
const EMBER_ACCESS = oceanPortAccessPoint(2);

export const OCEAN_BATHYMETRY_CHANNELS: readonly OceanBathymetryChannel[] =
  Object.freeze([
    {
      points: Object.freeze([
        BOREALIS_ACCESS,
        { x: -6.4, z: 9.2 },
        { x: 6.8, z: 10.1 },
        EMBER_ACCESS,
      ]),
      halfWidth: 1.85,
      softness: 1.45,
    },
    {
      points: Object.freeze([
        EMBER_ACCESS,
        { x: 18.4, z: 1.2 },
        AURORA_ACCESS,
      ]),
      halfWidth: 1.7,
      softness: 1.35,
    },
  ]);

const createSample = (): OceanBathymetrySample => ({
  depth: 0.5,
  shoreDistance: 1,
  waveExposure: 1,
  authoredOverride: 0,
});

const portBasinMask = (x: number, z: number): number => {
  let mask = 0;
  for (let index = 0; index < PORTS.length; index += 1) {
    const access = oceanPortAccessPoint(index);
    const distance = Math.hypot(x - access.x, z - access.z);
    mask = Math.max(mask, 1 - smoothstep(2.45, 4.5, distance));
  }
  return mask;
};

const channelMask = (x: number, z: number): number => {
  let mask = 0;
  for (const channel of OCEAN_BATHYMETRY_CHANNELS) {
    for (let index = 1; index < channel.points.length; index += 1) {
      const start = channel.points[index - 1]!;
      const end = channel.points[index]!;
      const distance = distancePointToSegment(
        x,
        z,
        start.x,
        start.z,
        end.x,
        end.z,
      );
      mask = Math.max(
        mask,
        1 -
          smoothstep(
            channel.halfWidth,
            channel.halfWidth + channel.softness,
            distance,
          ),
      );
    }
  }
  return mask;
};

const sampleAnalyticBathymetry = (
  x: number,
  z: number,
  target: OceanBathymetrySample,
): OceanBathymetrySample => {
  let coastDistance = Number.POSITIVE_INFINITY;
  for (const island of OCEAN_BATHYMETRY_ISLANDS) {
    coastDistance = Math.min(
      coastDistance,
      Math.hypot(x - island.x, z - island.z) - island.radius,
    );
  }
  coastDistance = Math.min(
    coastDistance,
    x - borealisCoastX(z),
  );

  const broadNoise =
    valueNoise2D(x * 0.047 + 11.3, z * 0.047 - 7.1, 431) - 0.5;
  const detailNoise =
    valueNoise2D(x * 0.112 - 3.8, z * 0.112 + 9.6, 947) - 0.5;
  const openWaterDepth = clamp(
    0.68 + broadNoise * 0.2 + detailNoise * 0.07,
    0.42,
    0.9,
  );
  const coastalDepth =
    OCEAN_BATHYMETRY_TUNING.minimumCoastalDepth +
    smoothstep(
      0,
      OCEAN_BATHYMETRY_TUNING.coastalDepthRange,
      Math.max(0, coastDistance),
    ) *
      OCEAN_BATHYMETRY_TUNING.coastalDepthGain;
  const basin = portBasinMask(x, z);
  const channel = channelMask(x, z);
  const authoredOverride = Math.max(basin * 0.86, channel);
  let depth = Math.min(openWaterDepth, coastalDepth);
  const borealisRaster = sampleBorealisCoastRaster(x, z);
  if (borealisRaster?.terrain === 'WATER') {
    depth = Math.min(depth, borealisRaster.bathymetry);
  }
  depth = Math.max(
    depth,
    OCEAN_BATHYMETRY_TUNING.harborDepth * basin,
  );
  depth = Math.max(
    depth,
    OCEAN_BATHYMETRY_TUNING.channelDepth * channel,
  );

  const shoreDistance = smoothstep(
    0,
    OCEAN_BATHYMETRY_TUNING.shoreDistanceRange,
    Math.max(0, coastDistance),
  );
  const exposureNoise =
    valueNoise2D(x * 0.038 - 4.2, z * 0.038 + 2.7, 1291) - 0.5;
  const coastalExposure = 0.18 + shoreDistance * 0.82;
  let waveExposure = clamp(
    coastalExposure * (0.88 + exposureNoise * 0.24),
    0.08,
    1,
  );
  waveExposure *=
    1 -
    basin * OCEAN_BATHYMETRY_TUNING.harborExposureReduction;

  target.depth = clamp(depth, 0, 1);
  target.shoreDistance = shoreDistance;
  target.waveExposure = clamp(waveExposure, 0, 1);
  target.authoredOverride = clamp(authoredOverride, 0, 1);
  return target;
};

export const oceanBathymetryWorldToUv = (
  x: number,
  z: number,
): { u: number; v: number } => ({
  u: x / OCEAN_BATHYMETRY_WORLD_WIDTH + 0.5,
  v: z / OCEAN_BATHYMETRY_WORLD_HEIGHT + 0.5,
});

const channelValue = (
  data: Uint8Array,
  width: number,
  x: number,
  y: number,
  channel: number,
): number => data[(y * width + x) * 4 + channel]! / 255;

export class OceanBathymetryField {
  public readonly width: number;
  public readonly height: number;
  public readonly worldWidth = OCEAN_BATHYMETRY_WORLD_WIDTH;
  public readonly worldHeight = OCEAN_BATHYMETRY_WORLD_HEIGHT;
  public readonly data: Uint8Array;

  public constructor(
    width = OCEAN_BATHYMETRY_WIDTH,
    height = OCEAN_BATHYMETRY_HEIGHT,
  ) {
    this.width = Math.max(2, Math.floor(width));
    this.height = Math.max(2, Math.floor(height));
    this.data = new Uint8Array(this.width * this.height * 4);
    const sample = createSample();

    for (let y = 0; y < this.height; y += 1) {
      const v = (y + 0.5) / this.height;
      const worldZ = (v - 0.5) * this.worldHeight;
      for (let x = 0; x < this.width; x += 1) {
        const u = (x + 0.5) / this.width;
        const worldX = (u - 0.5) * this.worldWidth;
        sampleAnalyticBathymetry(worldX, worldZ, sample);
        const offset = (y * this.width + x) * 4;
        this.data[offset] = Math.round(sample.depth * 255);
        this.data[offset + 1] = Math.round(
          sample.shoreDistance * 255,
        );
        this.data[offset + 2] = Math.round(
          sample.waveExposure * 255,
        );
        this.data[offset + 3] = Math.round(
          sample.authoredOverride * 255,
        );
      }
    }
  }

  public sampleWorld(
    x: number,
    z: number,
    target: OceanBathymetrySample = createSample(),
  ): OceanBathymetrySample {
    const uv = oceanBathymetryWorldToUv(x, z);
    const pixelX = clamp(uv.u, 0, 1) * this.width - 0.5;
    const pixelY = clamp(uv.v, 0, 1) * this.height - 0.5;
    const baseX = Math.floor(pixelX);
    const baseY = Math.floor(pixelY);
    const x0 = clamp(baseX, 0, this.width - 1);
    const y0 = clamp(baseY, 0, this.height - 1);
    const x1 = clamp(baseX + 1, 0, this.width - 1);
    const y1 = clamp(baseY + 1, 0, this.height - 1);
    const tx = pixelX - baseX;
    const ty = pixelY - baseY;
    const sampleChannel = (channel: number): number => {
      const lower =
        channelValue(this.data, this.width, x0, y0, channel) *
          (1 - tx) +
        channelValue(this.data, this.width, x1, y0, channel) * tx;
      const upper =
        channelValue(this.data, this.width, x0, y1, channel) *
          (1 - tx) +
        channelValue(this.data, this.width, x1, y1, channel) * tx;
      return lower * (1 - ty) + upper * ty;
    };

    target.depth = sampleChannel(0);
    target.shoreDistance = sampleChannel(1);
    target.waveExposure = sampleChannel(2);
    target.authoredOverride = sampleChannel(3);
    return target;
  }
}
