import { DataTexture, NearestFilter, RedFormat, UnsignedByteType, Vector2 } from 'three';

/** Tiny presentation-only map: retain the far fallback until a MID tile is complete. */
export class WinterSurfaceReadiness {
  readonly size = 11;
  readonly origin = new Vector2();
  readonly texture = new DataTexture(new Uint8Array(this.size * this.size), this.size, this.size, RedFormat, UnsignedByteType);
  constructor() {
    this.texture.minFilter = this.texture.magFilter = NearestFilter;
    this.texture.generateMipmaps = false;
    this.texture.needsUpdate = true;
  }
  update(centerX: number, centerZ: number, tiles: Iterable<{ tileX: number; tileZ: number; ready: boolean }>): void {
    const x = centerX - 5, z = centerZ - 5;
    const data = this.texture.image.data as Uint8Array;
    const next = new Uint8Array(data.length);
    for (const tile of tiles) {
      const column = tile.tileX - x, row = tile.tileZ - z;
      if (tile.ready && column >= 0 && column < this.size && row >= 0 && row < this.size) next[row * this.size + column] = 255;
    }
    if (this.origin.x !== x || this.origin.y !== z || next.some((n, i) => n !== data[i])) {
      this.origin.set(x, z); data.set(next); this.texture.needsUpdate = true;
    }
  }
  dispose(): void { this.texture.dispose(); }
}
