const isPredatorOf = (
  predator: WildernessAnimalSpecies,
  prey: WildernessAnimalSpecies,
): boolean => {
  if (predator === 'WOLF') {
    return prey === 'DEER' || prey === 'RABBIT' || prey === 'MOOSE';
  }
  if (predator === 'FOX') return prey === 'RABBIT';
  if (predator === 'BEAR' || predator === 'POLAR_BEAR') {
    return prey === 'DEER' || prey === 'MOOSE' || prey === 'RABBIT';
  }
  return false;
};

/**
 * Animals always notice a close predator, but scent extends awareness only
 * downwind. A careful predator approaching from downwind can therefore remain
 * hidden until it makes noise or enters the visual radius.
 */
export const wildernessPredatorDetection = (
  prey: Readonly<Pick<WildernessAnimalState, 'species' | 'x' | 'z'>>,
  predator: Readonly<Pick<WildernessAnimalState, 'species' | 'x' | 'z' | 'speed'>>,
  windX: number,
  windZ: number,
  windStrength: number,
): Readonly<{ detected: boolean; strength: number; reason: 'NONE' | 'SIGHT' | 'SOUND' | 'SCENT' }> => {
  if (!isPredatorOf(predator.species, prey.species)) {
    return { detected: false, strength: 0, reason: 'NONE' };
  }
  const dx = prey.x - predator.x;
  const dz = prey.z - predator.z;
  const distance = Math.hypot(dx, dz);
  const sightRadius = prey.species === 'RABBIT' ? 8.5 : 11.5;
  if (distance <= sightRadius) {
    return { detected: true, strength: 1 - distance / (sightRadius * 1.35), reason: 'SIGHT' };
  }
  const soundRadius = 7.5 + clamp(predator.speed, 0, 4) * 3.4;
  if (distance <= soundRadius && predator.speed > 0.55) {
    return { detected: true, strength: 0.72, reason: 'SOUND' };
  }
  const windLength = Math.hypot(windX, windZ);
  if (windLength < 0.05 || windStrength < 0.08 || distance > 34) {
    return { detected: false, strength: 0, reason: 'NONE' };
  }
  const scentAlignment = (dx / Math.max(0.001, distance)) * (windX / windLength) +
    (dz / Math.max(0.001, distance)) * (windZ / windLength);
  const scentRadius = 15 + clamp(windStrength, 0, 1) * 19;
  if (scentAlignment > 0.2 && distance <= scentRadius) {
    return {
      detected: true,
      strength: clamp(scentAlignment * (1 - distance / (scentRadius * 1.25)), 0.18, 0.82),
      reason: 'SCENT',
    };
  }
  return { detected: false, strength: 0, reason: 'NONE' };
};

