const animalBehaviorProfile = (
  species: WildernessAnimalSpecies,
): WildernessAnimalBehaviorProfile =>
  ANIMAL_BEHAVIOR_PROFILES[species] ?? GENERIC_ANIMAL_BEHAVIOR_PROFILE;

const STATIONARY_AMBIENT_BEHAVIORS = new Set<WildernessAnimalState['behavior']>([
  'OBSERVE',
  'SNIFF',
  'DIG_FORAGE',
  'REST',
  'PERCH',
  'NEST',
]);

const animalIdentitySeed = (animal: Readonly<WildernessAnimalState>): number => {
  const ordinal = Number(animal.id.match(/\d+$/)?.[0] ?? 0);
  return ordinal * 131 + animal.species.length * 29 + animal.id.charCodeAt(5);
};

/**
 * Chooses a lasting, individual intention instead of generating a moving
 * target every simulation tick. Route points are stable per animal, so deer
 * reuse familiar corridors and a wolf pack does not perform one synchronised
 * orbit around its leader.
 */
const chooseAmbientAnimalIntention = (
  animal: WildernessAnimalState,
  anchorX = animal.homeX ?? animal.x,
  anchorZ = animal.homeZ ?? animal.z,
): number => {
  const profile = animalBehaviorProfile(animal.species);
  const identity = animalIdentitySeed(animal);
  const intentionIndex = (animal.intentionIndex ?? 0) + 1;
  animal.intentionIndex = intentionIndex;
  const intentionRoll = hash2D(identity, intentionIndex, 15401);
  let cumulativeWeight = 0;
  const selected = profile.intentions.find((intention) => {
    cumulativeWeight += intention.weight;
    return intentionRoll <= cumulativeWeight;
  }) ?? profile.intentions[profile.intentions.length - 1]!;
  const durationRoll = hash2D(identity, intentionIndex, 15413);
  animal.behavior = selected.behavior;
  animal.targetSeconds = selected.minSeconds +
    (selected.maxSeconds - selected.minSeconds) * durationRoll;

  if (selected.behavior === 'PERCH' || selected.behavior === 'NEST') {
    animal.targetX = animal.nestX ?? anchorX;
    animal.targetZ = animal.nestZ ?? anchorZ;
    return profile.walkSpeed * 0.82;
  }
  if (
    selected.behavior === 'OBSERVE' &&
    isWildernessBirdSpecies(animal.species)
  ) {
    animal.observeAnchorX = animal.x;
    animal.observeAnchorZ = animal.z;
    animal.observeOrbitAngle = hash2D(identity, intentionIndex, 15419) *
      Math.PI * 2;
    const radius = animal.species === 'EAGLE'
      ? 18
      : animal.species === 'TIT'
        ? 3.6
        : 8.5;
    animal.targetX = animal.x + Math.cos(animal.observeOrbitAngle) * radius;
    animal.targetZ = animal.z + Math.sin(animal.observeOrbitAngle) * radius;
    return profile.walkSpeed * 0.78;
  }
  if (
    selected.behavior === 'FORAGE' &&
    isWildernessBirdSpecies(animal.species)
  ) {
    const forageAngle = hash2D(identity, intentionIndex, 15423) * Math.PI * 2;
    const forageRadius = animal.species === 'TIT'
      ? 2.5 + durationRoll * 3.5
      : 4 + durationRoll * 7;
    animal.targetX = animal.x + Math.cos(forageAngle) * forageRadius;
    animal.targetZ = animal.z + Math.sin(forageAngle) * forageRadius;
    return profile.walkSpeed * 0.68;
  }
  if (
    selected.behavior !== 'PATROL' &&
    selected.behavior !== 'FLOCK' &&
    selected.behavior !== 'SOAR'
  ) {
    animal.targetX = animal.x;
    animal.targetZ = animal.z;
    return 0;
  }

  const routeIndex = (animal.routeIndex ?? Math.floor(
    hash2D(identity, 17, 15427) * profile.routePoints,
  )) % profile.routePoints;
  animal.routeIndex = (routeIndex + 1) % profile.routePoints;
  const baseAngle = hash2D(identity, 19, 15439) * Math.PI * 2;
  const routeAngle = baseAngle + routeIndex / profile.routePoints * Math.PI * 2;
  const radiusMix = hash2D(identity, routeIndex, 15451);
  const routeRadius = profile.routeRadiusMin +
    (profile.routeRadiusMax - profile.routeRadiusMin) * radiusMix;
  animal.targetX = clamp(
    anchorX + Math.cos(routeAngle) * routeRadius,
    WILDERNESS_SURVIVAL_REGION.centerX - 68,
    WILDERNESS_SURVIVAL_REGION.centerX + 68,
  );
  animal.targetZ = clamp(
    anchorZ + Math.sin(routeAngle) * routeRadius,
    WILDERNESS_SURVIVAL_REGION.centerZ - 68,
    WILDERNESS_SURVIVAL_REGION.centerZ + 68,
  );
  if (animal.species === 'POLAR_BEAR') {
    animal.targetX = clamp(
      animal.targetX,
      WILDERNESS_SURVIVAL_REGION.creekX - 13,
      WILDERNESS_SURVIVAL_REGION.creekX + 13,
    );
  }
  return profile.walkSpeed;
};

const ambientAnimalSpeed = (animal: Readonly<WildernessAnimalState>): number =>
  STATIONARY_AMBIENT_BEHAVIORS.has(animal.behavior)
    ? 0
    : animalBehaviorProfile(animal.species).walkSpeed;

export const resolveBirdMaximumTurnRate = (
  species: WildernessAnimalSpecies,
  airspeed: number,
  urgent = false,
): number => {
  const referenceSpeed = animalBehaviorProfile(species).walkSpeed;
  const referenceRadius = species === 'TIT'
    ? 1.15
    : species === 'CROW'
      ? 3.2
      : species === 'RAVEN'
        ? 4.2
        : 9.5;
  // At a comparable bank angle, turn radius grows approximately with speed
  // squared. This stops a fast raven/eagle from pivoting in place while a
  // slow tit can still make the tight arcs expected of a small bird.
  const speed = Math.max(0.45, airspeed);
  const radius = referenceRadius * Math.max(
    0.58,
    (speed / Math.max(0.45, referenceSpeed)) ** 2,
  );
  return clamp(
    speed / radius * (urgent ? 1.45 : 1),
    0.12,
    species === 'TIT' ? 1.45 : urgent ? 0.82 : 0.58,
  );
};

const updateBirdFlightState = (
  animal: WildernessAnimalState,
  context: Readonly<WildernessStepContext>,
  delta: number,
  destinationRemaining: number,
): void => {
  if (!isWildernessBirdSpecies(animal.species)) return;
  const surface = context.sampleSurfaceHeight?.(animal.x, animal.z) ?? 0;
  const identity = animalIdentitySeed(animal);
  const frequency = animal.species === 'TIT'
    ? 5.8
    : animal.species === 'CROW'
      ? 2.65
      : animal.species === 'RAVEN'
        ? 2.15
        : 1.72;
  animal.wingPhase = ((animal.wingPhase ?? 0) + delta * frequency) % 1;
  const downstroke = animal.wingPhase < 0.43;
  const groundForage = animal.behavior === 'FORAGE' &&
    destinationRemaining < 0.86;
  const perch = (animal.behavior === 'PERCH' || animal.behavior === 'NEST') &&
    destinationRemaining < 0.82;
  const landing = groundForage || perch;
  const cruiseHeight = animal.behavior === 'OBSERVE'
    ? animal.species === 'EAGLE'
      ? 17
      : animal.species === 'TIT'
        ? 4.4
        : 10.5
    : animal.species === 'EAGLE'
      ? 8.5
      : animal.species === 'TIT'
        ? 2.6
        : animal.behavior === 'FLEE'
          ? 6.2
          : 4.4;
  const targetY = surface + (groundForage
    ? 0.16
    : perch
      ? animal.species === 'TIT' ? 1.55 : 2.05
      : cruiseHeight);
  animal.flightY ??= surface + cruiseHeight;
  animal.flightVerticalSpeed ??= 0;

  const windLength = Math.max(0.001, Math.hypot(context.windX, context.windZ));
  const headwind = clamp(-(
    Math.sin(animal.heading) * context.windX / windLength +
    Math.cos(animal.heading) * context.windZ / windLength
  ), 0, 1);
  const ridgeLift = smoothstep(0.82, 1.5, context.windStrength) *
    smoothstep(0.42, 0.92, headwind);
  const slowGlideCycle = (
    (context.windTime ?? 0) * (0.105 + hash2D(identity, 31, 16519) * 0.028) +
    hash2D(identity, 37, 16529) * 7
  ) % 1;
  const canSoar = animal.species !== 'TIT';
  const needsClimb = targetY - animal.flightY > 0.34;
  animal.flightGliding = !landing && canSoar && !needsClimb &&
    (animal.behavior === 'OBSERVE' || animal.behavior === 'SOAR') &&
    (ridgeLift > 0.34 || slowGlideCycle > (
      animal.species === 'CROW' ? 0.7 : 0.48
    ));

  let targetVerticalSpeed = clamp(
    (targetY - animal.flightY) * (landing ? 0.62 : 0.48),
    landing ? -0.72 : -0.34,
    1.05,
  );
  if (animal.flightGliding) {
    // A supported glide is level. In still air it loses height very slowly;
    // it never uses a decorative sine bob.
    targetVerticalSpeed = ridgeLift > 0.34
      ? Math.max(targetVerticalSpeed, 0)
      : Math.min(targetVerticalSpeed, -0.055);
  } else if (targetVerticalSpeed > 0 && !downstroke) {
    // Visible climb belongs to the power-producing downstroke. Between
    // strokes the trajectory is level or has only a tiny natural sink.
    targetVerticalSpeed = animal.species === 'TIT' ? -0.035 : -0.018;
  }
  animal.flightVerticalSpeed = damp(
    animal.flightVerticalSpeed,
    targetVerticalSpeed,
    landing ? 3.2 : downstroke ? 5.2 : 2.4,
    delta,
  );
  animal.flightY += animal.flightVerticalSpeed * delta;
  if (landing && Math.abs(animal.flightY - targetY) < 0.08) {
    animal.flightY = targetY;
    animal.flightVerticalSpeed = 0;
    animal.flightLanded = true;
    animal.flightGliding = false;
  } else {
    animal.flightLanded = false;
  }
};

