import type { LandSnowSystem } from '../land/LandSnowSystem';
import { LAND_SNOW_SPACING } from '../land/LandSnowData';

export interface PendingSnowMelt {
  x: number; z: number; radius: number; depth: number; retained: number;
  sheltered?: boolean;
  /** Absolute canonical grid row, not a pointer into a streamed tile. */
  nextRow?: number;
}

/** Background heat is a durable work queue, not a second snow field. Small
 * row slices always read live V3 depth. Checkpoints include unfinished work,
 * so saving does not have to drain the entire heat burst on the main thread. */
export class BudgetedSnowMelt {
  private jobs: PendingSnowMelt[] = [];
  private epoch?: number;
  public stats = { pending: 0, rows: 0, milliseconds: 0, mass: 0, samples: 0 };

  public enqueue(request: PendingSnowMelt): void {
    if (!Number.isFinite(request.depth) || request.depth <= 0 || !Number.isFinite(request.radius) || request.radius <= 0) return;
    // Accumulate energy only into an untouched request with the exact same
    // footprint. Never restart a partially processed source or lose its tail.
    const waiting = this.jobs.find(j => j.nextRow === undefined && j.x === request.x && j.z === request.z &&
      j.radius === request.radius && j.retained === request.retained && j.sheltered === request.sheltered);
    if (waiting) waiting.depth += request.depth;
    else this.jobs.push({ ...request });
    this.stats.pending = this.jobs.length;
  }

  public advance(snow: LandSnowSystem, acceptsSheltered: (x: number, z: number) => boolean,
    budgetMs = 1, maximumRows = 48): void {
    const start = performance.now(); let rows = 0, mass = 0, samples = 0;
    if (this.epoch !== undefined && this.epoch !== snow.contentEpoch) this.jobs = [];
    this.epoch = snow.contentEpoch;
    let skipped = 0;
    while (this.jobs.length && rows < maximumRows && (rows === 0 || performance.now() - start < budgetMs)) {
      const job = this.jobs[0]!;
      // As before, do not generate off-screen terrain to apply heat. Pending
      // rows survive streaming and resume when their source is active again.
      if (!snow.isTileActiveAt(job.x, job.z)) {
        this.jobs.push(this.jobs.shift()!);
        if (++skipped >= this.jobs.length) break;
        continue;
      }
      skipped = 0;
      const radius = Math.max(LAND_SNOW_SPACING * 1.25, job.radius);
      const row = job.nextRow ?? Math.floor((job.z - radius) / LAND_SNOW_SPACING);
      const z = row * LAND_SNOW_SPACING;
      const result = snow.meltSnowRadial(job.x, job.z, radius, job.depth, job.retained, 'BACKGROUND',
        job.sheltered ? acceptsSheltered : undefined, { minZ: z, maxZ: z });
      mass += result.snowMass; samples += result.changedSamples; rows++;
      job.nextRow = row + 1;
      if (job.nextRow > Math.ceil((job.z + radius) / LAND_SNOW_SPACING)) this.jobs.shift();
    }
    this.stats = { pending: this.jobs.length, rows, milliseconds: performance.now() - start, mass, samples };
  }

  public exportState(): PendingSnowMelt[] { return this.jobs.map(j => ({ ...j })); }
  public restore(saved?: readonly PendingSnowMelt[]): void {
    this.epoch = undefined;
    this.jobs = (saved ?? []).filter(j => [j.x,j.z,j.radius,j.depth,j.retained].every(Number.isFinite) &&
      j.radius > 0 && j.radius <= 64 && j.depth > 0 && (j.nextRow === undefined || Number.isSafeInteger(j.nextRow)))
      .map(j => ({ ...j }));
    this.stats.pending = this.jobs.length;
  }
}
