import type { SettlementContentRegistry } from './SettlementContentRegistry';
import type {
  SettlementBuildingRuntimeState,
  SettlementBuildingSaveData,
  SettlementBuildingStaffingState,
  SettlementBuildingView,
  SettlementGoodAmount,
} from './SettlementTypes';

export type SettlementStaffResolver = (
  npcId: string,
  locationId?: string,
) => SettlementBuildingStaffingState;

interface MutableBuildingState {
  buildingId: string;
  structuralLevel: number;
  targetLevel?: number;
  contributions: Array<{ goodId: string; quantity: number }>;
  workStartedAt?: number;
  workCompletesAt?: number;
  revision: number;
}

const cloneRuntime = (
  state: Readonly<MutableBuildingState>,
): SettlementBuildingRuntimeState => ({
  ...state,
  contributions: state.contributions.map((entry) => ({ ...entry })),
});

/** Structural restoration state, independent from presentation and quests. */
export class SettlementBuildingSystem {
  private readonly states = new Map<string, MutableBuildingState>();

  public constructor(
    private readonly registry: SettlementContentRegistry,
    private readonly resolveStaff: SettlementStaffResolver,
    saved?: Readonly<SettlementBuildingSaveData>,
  ) {
    for (const definition of registry.definitions.buildings) {
      this.states.set(definition.id, {
        buildingId: definition.id,
        structuralLevel: definition.initialStructuralLevel,
        contributions: [],
        revision: 0,
      });
    }
    if (saved?.version === 1 && Array.isArray(saved.states)) {
      for (const candidate of saved.states) this.importRuntime(candidate);
    }
  }

  public getStructuralLevel(buildingId: string): number {
    return this.states.get(buildingId)?.structuralLevel ?? 0;
  }

  public getStaffing(buildingId: string): SettlementBuildingStaffingState {
    const definition = this.registry.getBuilding(buildingId);
    if (!definition?.assignedNpcId) return 'NONE';
    return this.resolveStaff(definition.assignedNpcId, definition.locationId);
  }

  public remainingCosts(buildingId: string): readonly SettlementGoodAmount[] {
    const definition = this.registry.getBuilding(buildingId);
    const state = this.states.get(buildingId);
    if (!definition || !state || state.targetLevel !== undefined) return [];
    const stage = definition.stages.find(
      (candidate) => candidate.level === state.structuralLevel + 1,
    );
    if (!stage) return [];
    return stage.costs.flatMap((cost) => {
      const contributed = state.contributions.find(
        (entry) => entry.goodId === cost.goodId,
      )?.quantity ?? 0;
      const quantity = Math.max(0, cost.quantity - contributed);
      return quantity > 0 ? [{ goodId: cost.goodId, quantity }] : [];
    });
  }

  public contributionCapacity(buildingId: string, goodId: string): number {
    return this.remainingCosts(buildingId)
      .find((amount) => amount.goodId === goodId)?.quantity ?? 0;
  }

  public contribute(buildingId: string, goodId: string, quantity: number): boolean {
    const state = this.states.get(buildingId);
    const capacity = this.contributionCapacity(buildingId, goodId);
    if (!state || !Number.isSafeInteger(quantity) || quantity <= 0 || quantity > capacity) {
      return false;
    }
    const existing = state.contributions.find((entry) => entry.goodId === goodId);
    if (existing) existing.quantity += quantity;
    else state.contributions.push({ goodId, quantity });
    state.contributions.sort((left, right) => left.goodId.localeCompare(right.goodId));
    state.revision += 1;
    return true;
  }

  public startWork(buildingId: string, simulationTime: number): boolean {
    const definition = this.registry.getBuilding(buildingId);
    const state = this.states.get(buildingId);
    if (!definition || !state || state.targetLevel !== undefined) return false;
    const stage = definition.stages.find(
      (candidate) => candidate.level === state.structuralLevel + 1,
    );
    if (!stage || this.remainingCosts(buildingId).length > 0) return false;
    state.targetLevel = stage.level;
    state.workStartedAt = Math.max(0, simulationTime);
    state.workCompletesAt = state.workStartedAt + stage.workDurationSeconds;
    state.revision += 1;
    return true;
  }

  public update(simulationTime: number): readonly string[] {
    const completed: string[] = [];
    for (const state of this.states.values()) {
      if (
        state.targetLevel === undefined ||
        state.workCompletesAt === undefined ||
        simulationTime < state.workCompletesAt
      ) continue;
      state.structuralLevel = state.targetLevel;
      delete state.targetLevel;
      delete state.workStartedAt;
      delete state.workCompletesAt;
      state.contributions = [];
      state.revision += 1;
      completed.push(state.buildingId);
    }
    return completed.sort();
  }

  public getView(buildingId: string): SettlementBuildingView | undefined {
    const definition = this.registry.getBuilding(buildingId);
    const state = this.states.get(buildingId);
    if (!definition || !state) return undefined;
    const nextStage = definition.stages.find(
      (candidate) => candidate.level === state.structuralLevel + 1,
    );
    const remainingCosts = this.remainingCosts(buildingId);
    const workState = !nextStage
      ? 'COMPLETE' as const
      : state.targetLevel !== undefined
        ? 'UNDER_REPAIR' as const
        : remainingCosts.length === 0
          ? 'READY' as const
          : 'MATERIALS_INCOMPLETE' as const;
    return {
      ...cloneRuntime(state),
      displayName: definition.displayName,
      worldObjectId: definition.worldObjectId,
      nextStage,
      remainingCosts,
      workState,
      staffing: this.getStaffing(buildingId),
      assignedNpcId: definition.assignedNpcId,
      serviceId: definition.serviceId,
    };
  }

  public getViews(): readonly SettlementBuildingView[] {
    return this.registry.definitions.buildings.flatMap((definition) => {
      const view = this.getView(definition.id);
      return view ? [view] : [];
    });
  }

  public exportState(): SettlementBuildingSaveData {
    return {
      version: 1,
      states: [...this.states.values()]
        .sort((left, right) => left.buildingId.localeCompare(right.buildingId))
        .map(cloneRuntime),
    };
  }

  private importRuntime(candidate: Readonly<SettlementBuildingRuntimeState>): void {
    const definition = this.registry.getBuilding(candidate?.buildingId);
    if (!definition || !Number.isSafeInteger(candidate.structuralLevel)) return;
    const maximumLevel = this.registry.maximumBuildingLevel(definition.id);
    if (
      candidate.structuralLevel < definition.initialStructuralLevel ||
      candidate.structuralLevel > maximumLevel
    ) return;
    const state = this.states.get(definition.id)!;
    state.structuralLevel = candidate.structuralLevel;
    state.revision = Number.isSafeInteger(candidate.revision) && candidate.revision >= 0
      ? candidate.revision
      : 0;
    const stage = definition.stages.find(
      (value) => value.level === candidate.structuralLevel + 1,
    );
    state.contributions = stage
      ? stage.costs.flatMap((cost) => {
          const quantity = candidate.contributions?.find(
            (entry) => entry.goodId === cost.goodId,
          )?.quantity;
          return Number.isSafeInteger(quantity) && quantity! > 0
            ? [{ goodId: cost.goodId, quantity: Math.min(cost.quantity, quantity!) }]
            : [];
        })
      : [];
    if (
      stage && candidate.targetLevel === stage.level &&
      Number.isFinite(candidate.workStartedAt) &&
      Number.isFinite(candidate.workCompletesAt) &&
      candidate.workCompletesAt! >= candidate.workStartedAt!
    ) {
      state.targetLevel = stage.level;
      state.workStartedAt = Math.max(0, candidate.workStartedAt!);
      state.workCompletesAt = Math.max(state.workStartedAt, candidate.workCompletesAt!);
    }
  }
}
