import { serverTick, type ServerTick } from '../core/NetworkPrimitives';

export interface SessionEndingPayload {
  readonly version: 1;
  readonly kind: 'SESSION_ENDING';
  readonly reason: string;
  readonly recoverable: boolean;
  readonly checkpointSaved: boolean;
  readonly serverTick: ServerTick;
}

export const validateSessionEndingPayload = (
  input: unknown,
): SessionEndingPayload | undefined => {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return undefined;
  const value = input as Record<string, unknown>;
  if (
    value.version !== 1 ||
    value.kind !== 'SESSION_ENDING' ||
    typeof value.reason !== 'string' ||
    value.reason.length < 1 ||
    value.reason.length > 160 ||
    typeof value.recoverable !== 'boolean' ||
    typeof value.checkpointSaved !== 'boolean' ||
    typeof value.serverTick !== 'number' ||
    !Number.isSafeInteger(value.serverTick) ||
    value.serverTick < 0
  ) return undefined;
  return {
    version: 1,
    kind: 'SESSION_ENDING',
    reason: value.reason,
    recoverable: value.recoverable,
    checkpointSaved: value.checkpointSaved,
    serverTick: serverTick(value.serverTick),
  };
};
