import { REVISION, type WebGLRenderer, type Camera } from 'three';
import type { Pass } from 'three/examples/jsm/postprocessing/Pass.js';
import { DetailedPerformanceCapture } from './DetailedPerformanceCapture';
import { GpuQueryQueue } from './GpuQueryQueue';

interface DrawStats { key: string; invocations: number; calls: number; triangles: number; lines: number; points: number; cpuMs: number }

/** Instrument public pass and renderer boundaries; never change materials, visibility or render order. */
export class RenderDiagnostics {
  private readonly queries: GpuQueryQueue;
  private restorations: (() => void)[] = [];
  private passRestorations: (() => void)[] = [];
  private patchedPasses = new Set<Pass>();
  private readonly removeStateListener: () => void;
  private readonly removeContextListeners: () => void;
  private scopePath: string[] = [];
  private gpuFrame = false;
  private drawFrame = false;
  private segmentActive = false;
  private frameId = 0;
  private queryAttempts = 0;
  private submittedSegments = 0;
  private skippedSegments = 0;
  private draws = new Map<string, DrawStats>();
  private catalog: Record<string, unknown> = {};
  private catalogSize = 0;
  private catalogDropped = 0;
  private drawRowsRecorded = 0;
  private targetTransitions: Record<string, unknown>[] = [];
  private drawIndex = 0;
  private previousDrawCount = 1;
  private selectedDraws = new Set<number>();
  private shadowDepth = 0;
  private shadowLights: Record<string, unknown>[] = [];
  private shaderIds = new WeakMap<object, number>();
  private shaderSequence = 0;

  public constructor(private readonly renderer: WebGLRenderer, public readonly capture: DetailedPerformanceCapture) {
    const gl = renderer.getContext() as WebGL2RenderingContext;
    this.queries = new GpuQueryQueue(gl, segment => capture.addGpu(segment));
    Object.assign(capture.metadata, {
      rendererScope: 'WorldScene WebGL renderer and its nested/offscreen render calls. Separate editor/inspection WebGL contexts are not instrumented by this attachment.',
      legacyGpuSampler: 'Paused during detailed capture and pending-query drain; use detailed.gpuSegments and complete-frame scope summaries.',
      threeRevision: REVISION, gpuTimerSupported: this.queries.supported,
      glVersion: gl.getParameter(gl.VERSION), glRenderer: gl.getParameter(gl.RENDERER), glVendor: gl.getParameter(gl.VENDOR),
      contextAttributes: gl.getContextAttributes(), extensions: gl.getSupportedExtensions(),
    });
    const debugRenderer = gl.getExtension('WEBGL_debug_renderer_info');
    capture.metadata.reportedGpu = debugRenderer ? {
      vendor: gl.getParameter(debugRenderer.UNMASKED_VENDOR_WEBGL), renderer: gl.getParameter(debugRenderer.UNMASKED_RENDERER_WEBGL),
    } : { available: false };
    this.removeStateListener = capture.onStateChange(active => {
      if (active) {
        this.capture.metadata.gpuTiming = this.capture.options.gpuTiming;
        this.capture.metadata.gpuTimingCaveat = 'Frame timing uses one asynchronous query around the complete renderer. Experimental segmented timing can perturb command buffers (especially ANGLE/Metal); do not interpret inclusive/nested scopes as additive pass costs.';
        this.queries.cancel(this.frameId);
        this.catalog = {}; this.catalogSize = 0; this.catalogDropped = 0;
        this.drawRowsRecorded = 0;
        this.capture.metadata.renderCatalog = this.catalog;
        this.install();
      } else this.uninstall();
    });
    const lost = () => {
      capture.event('webgl-context-lost'); this.queries.cancel(this.frameId, 'context-lost');
    };
    const restored = () => { this.queries.restore(); capture.event('webgl-context-restored'); capture.metadata.gpuTimerSupported = this.queries.supported; };
    renderer.domElement.addEventListener('webglcontextlost', lost);
    renderer.domElement.addEventListener('webglcontextrestored', restored);
    this.removeContextListeners = () => {
      renderer.domElement.removeEventListener('webglcontextlost', lost);
      renderer.domElement.removeEventListener('webglcontextrestored', restored);
    };
    if (capture.active) { capture.metadata.renderCatalog = this.catalog; this.install(); }
  }
  public get ownsGpuTimer(): boolean { return this.capture.active || this.queries.pendingCount > 0; }
  public beginFrame(frameId: number): void {
    this.frameId = frameId;
    const pollStart = performance.now();
    this.queries.poll(frameId);
    this.capture.span('diagnostics.gpu-poll', pollStart);
    this.capture.metadata.gpuQueriesPending = this.queries.pendingCount;
    this.gpuFrame = this.capture.isGpuFrame(); this.drawFrame = this.capture.isDrawFrame();
    this.draws.clear(); this.drawIndex = 0; this.queryAttempts = 0;
    this.shadowLights = [];
    this.targetTransitions = [];
    this.submittedSegments = 0; this.skippedSegments = 0; this.selectedDraws.clear();
    // Eight distributed object invocations per sampled deep frame. Explicitly partial coverage.
    if (this.drawFrame && this.gpuFrame && this.capture.options.gpuTiming === 'segmented') {
      for (let i = 0; i < 8; i++) this.selectedDraws.add((frameId * 97 + Math.floor(i * this.previousDrawCount / 8)) % this.previousDrawCount);
    }
  }
  public measure<T>(name: string, work: () => T): T {
    if (!this.capture.active) return work();
    const startedAt = performance.now();
    const before = this.counters();
    const counterFrame = this.renderer.info.render.frame;
    const mayResetCounters = this.renderer.info.autoReset;
    const segmented = this.capture.options.gpuTiming === 'segmented';
    if (segmented) this.closeSegment();
    this.scopePath.push(name);
    if (segmented || this.scopePath.length === 1) this.openSegment();
    try { return work(); }
    finally {
      if (segmented || this.scopePath.length === 1) this.closeSegment();
      this.scopePath.pop();
      if (segmented) this.openSegment();
      const end = performance.now();
      this.capture.span(`render.${name}`, startedAt, end);
      const after = this.counters();
      if (mayResetCounters && counterFrame !== this.renderer.info.render.frame) {
        this.capture.count(`render.${name}.counterCoverageUnknown`);
      } else for (const key of ['calls', 'triangles', 'lines', 'points'] as const) {
        if (after[key] >= before[key]) this.capture.count(`render.${name}.${key}`, after[key] - before[key]);
        else this.capture.count(`render.${name}.counterCoverageUnknown`);
      }
    }
  }
  public instrumentPasses(passes: readonly Pass[], labels?: readonly string[]): void {
    if (!this.capture.active) return;
    passes.forEach((pass, index) => {
      if (this.patchedPasses.has(pass)) return;
      this.patchedPasses.add(pass);
      const original = pass.render;
      const profiler = this;
      // The owner supplies stable labels; constructor names are minified in Pages builds.
      const name = labels?.[index] ?? `pass-${index}-${pass.constructor.name}`;
      const wrapped: Pass['render'] = function (this: Pass, ...args) { return profiler.measure(name, () => original.apply(this, args)); };
      pass.render = wrapped;
      this.passRestorations.push(() => { if (pass.render === wrapped) pass.render = original; });
    });
  }
  public finishFrame(camera: Camera): void {
    if (!this.capture.active || !this.capture.currentFrame) return;
    this.previousDrawCount = Math.max(1, this.drawIndex || this.previousDrawCount);
    this.capture.currentFrame.render = {
      gpuCoverage: { requested: this.gpuFrame, supported: this.queries.supported,
        submittedSegments: this.submittedSegments, skippedSegments: this.skippedSegments },
      drawCoverage: { sampled: this.drawFrame, capturedGroups: this.draws.size, invocations: this.drawIndex,
        objectGpuSampling: this.capture.options.gpuTiming === 'segmented'
          ? 'Experimental: at most 8 distributed invocations on sampled deep frames; not a complete per-object GPU ranking.'
          : 'Disabled: one GPU query around the complete renderer. Per-object rows measure CPU/calls only.' },
      draws: this.drawFrame ? [...this.draws.values()] : [],
      shadowLights: this.shadowLights,
      targetTransitions: this.targetTransitions,
      camera: { type: camera.type, matrixWorld: [...camera.matrixWorld.elements], projection: [...camera.projectionMatrix.elements], layers: camera.layers.mask },
      viewport: { width: this.renderer.domElement.width, height: this.renderer.domElement.height, pixelRatio: this.renderer.getPixelRatio() },
    };
    this.capture.metadata.gpuQueriesPending = this.queries.pendingCount;
    this.capture.metadata.renderCatalogDropped = this.catalogDropped;
    this.capture.metadata.drawRowsRecorded = this.drawRowsRecorded;
    this.capture.metadata.drawRowBudget = 65536;
  }
  public dispose(): void {
    this.queries.cancel(this.frameId); this.uninstall(); this.removeStateListener(); this.removeContextListeners();
  }
  private openSegment(): void {
    if (!this.gpuFrame || !this.scopePath.length || !this.capture.active) return;
    if (this.queryAttempts++ >= 128) { this.skippedSegments++; return; }
    this.segmentActive = this.queries.begin(this.capture.captureId, this.frameId, this.scopePath);
    if (this.segmentActive) this.submittedSegments++; else this.skippedSegments++;
  }
  private closeSegment(): void {
    if (this.segmentActive) this.queries.end();
    this.segmentActive = false;
  }
  private counters(): { calls: number; triangles: number; lines: number; points: number } {
    const info = this.renderer.info.render;
    return { calls: info.calls, triangles: info.triangles, lines: info.lines, points: info.points };
  }
  private install(): void {
    this.uninstall();
    const shadow = this.renderer.shadowMap;
    const originalShadow = shadow.render;
    const profiler = this;
    const originalSetTarget = this.renderer.setRenderTarget;
    const wrappedSetTarget: typeof originalSetTarget = function (this: WebGLRenderer, ...args) {
      const result = originalSetTarget.apply(this, args);
      const target = args[0];
      if (profiler.targetTransitions.length < 64) profiler.targetTransitions.push({
        atMs: performance.now(), scopePath: [...profiler.scopePath],
        target: target ? (Array.isArray(target.texture) ? target.texture.map(t => t.uuid).join(',') : target.texture.uuid) : 'screen', width: target?.width ?? this.domElement.width,
        height: target?.height ?? this.domElement.height, samples: target?.samples ?? null,
        depthBuffer: target?.depthBuffer ?? null, stencilBuffer: target?.stencilBuffer ?? null,
        face: args[1] ?? 0, mip: args[2] ?? 0,
      });
      else profiler.capture.count('diagnostics.droppedTargetTransitions');
      return result;
    };
    this.renderer.setRenderTarget = wrappedSetTarget;
    this.restorations.push(() => { if (this.renderer.setRenderTarget === wrappedSetTarget) this.renderer.setRenderTarget = originalSetTarget; });
    // Covers extra offscreen scene renders too, including renders outside the main composer.
    const originalRender = this.renderer.render;
    const wrappedRender: typeof originalRender = function (this: WebGLRenderer, scene, camera) {
      return profiler.measure(`renderer-call:${scene.name || scene.type}#${scene.id}`, () => originalRender.call(this, scene, camera));
    };
    this.renderer.render = wrappedRender;
    this.restorations.push(() => { if (this.renderer.render === wrappedRender) this.renderer.render = originalRender; });
    const wrappedShadow: typeof originalShadow = function (this: typeof shadow, ...args) {
      return profiler.measure('shadow-maps', () => {
        for (const light of args[0] ?? []) {
          if (profiler.shadowLights.length >= 64) break;
          profiler.shadowLights.push({ id: light.id, name: light.name, type: light.type, intensity: light.intensity,
            castShadow: light.castShadow, shadowCameraId: light.shadow?.camera.id,
            mapSize: light.shadow?.mapSize.toArray(), autoUpdate: light.shadow?.autoUpdate, needsUpdate: light.shadow?.needsUpdate });
        }
        profiler.shadowDepth++;
        try { return originalShadow.apply(this, args); } finally { profiler.shadowDepth--; }
      });
    };
    shadow.render = wrappedShadow;
    this.restorations.push(() => { if (shadow.render === wrappedShadow) shadow.render = originalShadow; });
    if (this.capture.options.mode !== 'deep') return;
    const originalDraw = this.renderer.renderBufferDirect;
    const wrappedDraw: typeof originalDraw = function (this: WebGLRenderer, ...args) {
      if (!profiler.drawFrame || !profiler.capture.active) return originalDraw.apply(this, args);
      const [, , geometry, material, object, group] = args;
      const key = `${profiler.shadowDepth ? 'shadow' : 'view'}:${object.id}:${geometry.id}:${material.id}:${group?.start ?? 0}`;
      profiler.describeDraw(key, geometry, material, object);
      const before = profiler.counters(); const startedAt = performance.now();
      const selected = profiler.selectedDraws.has(profiler.drawIndex++);
      try {
        if (selected) return profiler.measure(`draw:${key}`, () => originalDraw.apply(this, args));
        return originalDraw.apply(this, args);
      } finally {
        const cpuMs = performance.now() - startedAt; const after = profiler.counters();
        const entry = profiler.catalog[key] as Record<string, unknown> | undefined;
        if (entry) entry.lastProgramId = (profiler.renderer.properties.get(material) as { currentProgram?: { id?: number } }).currentProgram?.id ?? null;
        let row = profiler.draws.get(key);
        if (!row && profiler.draws.size < 4096 && profiler.drawRowsRecorded < 65536) {
          row = { key, invocations: 0, calls: 0, triangles: 0, lines: 0, points: 0, cpuMs: 0 }; profiler.draws.set(key, row);
          profiler.drawRowsRecorded++;
        }
        if (row) {
          row.invocations++; row.cpuMs += cpuMs;
          for (const field of ['calls', 'triangles', 'lines', 'points'] as const) row[field] += after[field] - before[field];
        } else profiler.capture.count('diagnostics.droppedDrawGroups');
      }
    };
    this.renderer.renderBufferDirect = wrappedDraw;
    this.restorations.push(() => { if (this.renderer.renderBufferDirect === wrappedDraw) this.renderer.renderBufferDirect = originalDraw; });
    this.installGlHooks();
  }
  private describeDraw(key: string, geometry: any, material: any, object: any): void {
    if (this.catalog[key]) return;
    if (this.catalogSize >= 8192) { this.catalogDropped++; return; }
    const ancestry: string[] = [];
    for (let current = object, depth = 0; current && depth < 8; current = current.parent, depth++) ancestry.push(current.name || `${current.type}#${current.id}`);
    const textures: Record<string, unknown> = {};
    for (const name of ['map', 'normalMap', 'roughnessMap', 'alphaMap', 'envMap', 'displacementMap']) {
      const texture = material[name];
      if (texture?.isTexture) textures[name] = { uuid: texture.uuid, width: texture.image?.width ?? null, height: texture.image?.height ?? null };
    }
    this.catalog[key] = {
      objectId: object.id, objectUuid: object.uuid, objectName: object.name, objectType: object.type,
      ancestry, castShadow: object.castShadow, receiveShadow: object.receiveShadow,
      frustumCulled: object.frustumCulled, layers: object.layers?.mask,
      instanceCount: object.isInstancedMesh ? object.count : 1,
      geometryId: geometry.id, vertices: geometry.attributes.position?.count ?? 0,
      indices: geometry.index?.count ?? 0, groups: geometry.groups.length,
      materialId: material.id, materialUuid: material.uuid, materialName: material.name, materialType: material.type,
      transparent: material.transparent, opacity: material.opacity, alphaTest: material.alphaTest,
      side: material.side, depthWrite: material.depthWrite, blending: material.blending,
      vertexShaderCharacters: material.vertexShader?.length ?? 0, fragmentShaderCharacters: material.fragmentShader?.length ?? 0,
      textures, catalogedFrameId: this.frameId,
    };
    this.catalogSize++;
  }
  private installGlHooks(): void {
    const gl = this.renderer.getContext() as unknown as Record<string, any>;
    const methods = ['bufferData', 'bufferSubData', 'texImage2D', 'texSubImage2D', 'texImage3D', 'texSubImage3D',
      'compressedTexImage2D', 'compressedTexSubImage2D', 'generateMipmap', 'compileShader', 'linkProgram',
      'getProgramParameter', 'getShaderParameter', 'readPixels'];
    const profiler = this;
    const installed: string[] = [];
    for (const name of methods) {
      const original = gl[name]; if (typeof original !== 'function') continue;
      const hadOwn = Object.hasOwn(gl, name);
      function wrapped(this: unknown, ...args: unknown[]): unknown {
        if (!profiler.capture.active) return original.apply(this, args);
        const start = performance.now();
        try { return original.apply(this, args); }
        finally {
          const end = performance.now();
          profiler.capture.count(`gl.${name}.calls`);
          profiler.capture.count(`gl.${name}.cpuMs`, end - start);
          if (name === 'bufferData' || name === 'bufferSubData') {
            const index = name === 'bufferData' ? 1 : 2;
            const source = args[index];
            let bytes = typeof source === 'number' ? source : source instanceof ArrayBuffer ? source.byteLength : 0;
            if (ArrayBuffer.isView(source)) {
              const elementBytes = (source as unknown as { BYTES_PER_ELEMENT?: number }).BYTES_PER_ELEMENT ?? 1;
              const offsetIndex = 3;
              const offset = Number(args[offsetIndex] ?? 0);
              const length = Number(args[offsetIndex + 1] ?? 0);
              bytes = length > 0 ? length * elementBytes : Math.max(0, source.byteLength - offset * elementBytes);
            }
            profiler.capture.count(`gl.${name}.specifiedBytes`, bytes);
          }
          if (end - start >= 2 || name === 'compileShader' || name === 'linkProgram') {
            profiler.capture.span(`gl.${name}`, start, end);
            const resource = args[0]; let id: number | null = null;
            if (resource && typeof resource === 'object') {
              if (!profiler.shaderIds.has(resource)) profiler.shaderIds.set(resource, ++profiler.shaderSequence);
              id = profiler.shaderIds.get(resource)!;
            }
            profiler.capture.event(`gl.${name}`, { resourceId: id, result: 'Wall-clock invocation; asynchronous compiler/driver work may finish later.' }, start, end - start);
          }
        }
      }
      try {
        gl[name] = wrapped;
        if (gl[name] !== wrapped) continue;
        installed.push(name);
        this.restorations.push(() => { if (gl[name] === wrapped) { if (hadOwn) gl[name] = original; else delete gl[name]; } });
      } catch { /* Some environments expose non-writable native methods. */ }
    }
    this.capture.metadata.glInstrumentation = { installed, unavailable: methods.filter(name => !installed.includes(name)),
      bytes: 'Buffer specifiedBytes measures API-specified source/allocation bytes, not VRAM usage. Texture transfers are counted, not guessed in bytes.' };
  }
  private uninstall(): void {
    for (const restore of this.passRestorations.reverse()) restore();
    for (const restore of this.restorations.reverse()) restore();
    this.passRestorations = []; this.restorations = []; this.patchedPasses.clear();
  }
}
