import { clamp, damp, lerp, smoothstep } from '../utils/math';

export type DayPhase =
  | 'early-morning'
  | 'arctic-day'
  | 'evening'
  | 'twilight'
  | 'night';
export type DayMode = 'auto' | DayPhase;
export type DayTimeScale = 1 | 8 | 32 | 128;

export const POLAR_DAYS_PER_MONTH = 8;
export const POLAR_MONTHS_PER_YEAR = 12;
export const POLAR_DAYS_PER_YEAR =
  POLAR_DAYS_PER_MONTH * POLAR_MONTHS_PER_YEAR;

export interface PolarCalendarState {
  /** One-based authored year. */
  year: number;
  /** One-based month in the compact polar calendar. */
  month: number;
  /** One-based day inside the current eight-day lunar month. */
  dayOfMonth: number;
  /** Continuous 0..1 position through the solar year. */
  yearProgress: number;
  /** -1 = darkest solar season, +1 = brightest solar season. */
  solarSeason: number;
}

interface DayProfile {
  daylight: number;
  warmth: number;
  twilight: number;
  night: number;
  sunHeight: number;
  starVisibility: number;
  artificialLight: number;
}

export interface DayNightState extends DayProfile {
  mode: DayMode;
  phase: DayPhase;
  frozen: boolean;
  timeScale: DayTimeScale;
  cycleProgress: number;
  dayTime: number;
  sunAzimuth: number;
  updates: number;
}

export interface DayNightSystemSaveData {
  version: 1;
  state: DayNightState;
  accumulator: number;
}

interface DayKeyframe {
  progress: number;
  phase: DayPhase;
  profile: Readonly<DayProfile>;
}

const DAY_STEP = 0.25;
export const DAY_LENGTH_SECONDS = 2700;
const TAU = Math.PI * 2;
const DAY_MODES: readonly DayMode[] = [
  'auto',
  'early-morning',
  'arctic-day',
  'evening',
  'twilight',
  'night',
];
// x128 compresses the 45-minute authored day into roughly 21 seconds. It is
// intentionally a playtest-only-feeling inspection speed: simulation and
// character movement remain at x1 while the complete sky story can be
// reviewed without repeatedly stepping through fixed preview phases.
const DAY_TIME_SCALES: readonly DayTimeScale[] = [1, 8, 32, 128];
const PHASE_PROGRESS: Readonly<Record<DayPhase, number>> = {
  'early-morning': 0.14,
  'arctic-day': 0.4,
  evening: 0.72,
  twilight: 0.82,
  night: 0.94,
};

const NIGHT: Readonly<DayProfile> = Object.freeze({
  daylight: 0.16,
  warmth: 0,
  twilight: 0.18,
  night: 1,
  sunHeight: -0.2,
  starVisibility: 1,
  artificialLight: 1,
});
const MORNING: Readonly<DayProfile> = Object.freeze({
  daylight: 0.58,
  warmth: 0.2,
  twilight: 0.48,
  night: 0.24,
  sunHeight: 0.16,
  starVisibility: 0.12,
  artificialLight: 0.52,
});
const DAY: Readonly<DayProfile> = Object.freeze({
  daylight: 1,
  warmth: 0.04,
  twilight: 0,
  night: 0,
  sunHeight: 0.78,
  starVisibility: 0,
  artificialLight: 0.08,
});
const EVENING: Readonly<DayProfile> = Object.freeze({
  daylight: 0.68,
  warmth: 1,
  twilight: 0.42,
  night: 0.2,
  sunHeight: 0.12,
  starVisibility: 0.08,
  artificialLight: 0.5,
});
const TWILIGHT: Readonly<DayProfile> = Object.freeze({
  daylight: 0.34,
  warmth: 0.24,
  twilight: 1,
  night: 0.7,
  sunHeight: -0.07,
  starVisibility: 0.58,
  artificialLight: 0.9,
});

const KEYFRAMES: readonly DayKeyframe[] = [
  { progress: 0, phase: 'night', profile: NIGHT },
  { progress: 0.14, phase: 'early-morning', profile: MORNING },
  { progress: 0.28, phase: 'arctic-day', profile: DAY },
  { progress: 0.62, phase: 'arctic-day', profile: DAY },
  { progress: 0.72, phase: 'evening', profile: EVENING },
  { progress: 0.82, phase: 'twilight', profile: TWILIGHT },
  { progress: 0.9, phase: 'night', profile: NIGHT },
  { progress: 1, phase: 'night', profile: NIGHT },
];

/**
 * A compact deterministic calendar keeps the astronomical story independent
 * from real-world waiting. One eight-day month equals one lunar cycle and a
 * 96-day year produces a slow, inspectable arctic solar variation.
 */
export const resolvePolarCalendar = (
  dayTimeSeconds: number,
): PolarCalendarState => {
  const absoluteDay = Math.max(0, dayTimeSeconds) / DAY_LENGTH_SECONDS;
  const wholeDay = Math.floor(absoluteDay);
  const dayInYear = wholeDay % POLAR_DAYS_PER_YEAR;
  const yearProgress = (
    dayInYear + (absoluteDay - wholeDay)
  ) / POLAR_DAYS_PER_YEAR;
  return {
    year: Math.floor(wholeDay / POLAR_DAYS_PER_YEAR) + 1,
    month: Math.floor(dayInYear / POLAR_DAYS_PER_MONTH) + 1,
    dayOfMonth: dayInYear % POLAR_DAYS_PER_MONTH + 1,
    yearProgress,
    // Day zero starts at the equinox-like midpoint. The brightest and darkest
    // arcs arrive a quarter and three quarters of a year later.
    solarSeason: Math.sin(yearProgress * TAU),
  };
};

const cycleValue = <T>(values: readonly T[], current: T): T => {
  const index = values.indexOf(current);
  return values[(index + 1) % values.length] ?? values[0]!;
};

const sampleProfile = (
  progress: number,
  dayTimeSeconds = progress * DAY_LENGTH_SECONDS,
): { phase: DayPhase; profile: DayProfile } => {
  const wrapped = progress - Math.floor(progress);
  let start = KEYFRAMES[0]!;
  let end = KEYFRAMES[KEYFRAMES.length - 1]!;
  for (let index = 1; index < KEYFRAMES.length; index += 1) {
    const candidate = KEYFRAMES[index]!;
    if (wrapped <= candidate.progress) {
      start = KEYFRAMES[index - 1] ?? start;
      end = candidate;
      break;
    }
  }
  const raw =
    (wrapped - start.progress) /
    Math.max(0.0001, end.progress - start.progress);
  const blend = smoothstep(0, 1, raw);
  const calendar = resolvePolarCalendar(dayTimeSeconds);
  const annualSolarOffset = calendar.solarSeason * 0.105;
  const annualLightOffset = calendar.solarSeason * 0.055;
  const profile: DayProfile = {
    daylight: clamp(
      lerp(start.profile.daylight, end.profile.daylight, blend) +
        annualLightOffset,
      0.15,
      1,
    ),
    warmth: lerp(start.profile.warmth, end.profile.warmth, blend),
    twilight: clamp(
      lerp(start.profile.twilight, end.profile.twilight, blend) -
        annualLightOffset * 0.35,
      0,
      1,
    ),
    night: clamp(
      lerp(start.profile.night, end.profile.night, blend) -
        annualLightOffset * 0.7,
      0,
      1,
    ),
    sunHeight: clamp(
      lerp(start.profile.sunHeight, end.profile.sunHeight, blend) +
        annualSolarOffset,
      -0.32,
      0.92,
    ),
    starVisibility: clamp(
      lerp(start.profile.starVisibility, end.profile.starVisibility, blend) -
        annualLightOffset * 0.65,
      0,
      1,
    ),
    artificialLight: clamp(
      lerp(start.profile.artificialLight, end.profile.artificialLight, blend) -
        annualLightOffset * 0.45,
      0,
      1,
    ),
  };
  return {
    phase: blend < 0.5 ? start.phase : end.phase,
    profile,
  };
};

export class DayNightSystem {
  private readonly state: DayNightState;
  private accumulator = 0;

  public constructor() {
    const cycleProgress = 0.64;
    const dayTime = cycleProgress * DAY_LENGTH_SECONDS;
    const initial = sampleProfile(cycleProgress, dayTime);
    this.state = {
      mode: 'auto',
      phase: initial.phase,
      frozen: false,
      timeScale: 1,
      cycleProgress,
      dayTime,
      sunAzimuth: cycleProgress * TAU - Math.PI * 0.65,
      updates: 0,
      ...initial.profile,
    };
  }

  public update(deltaSeconds: number, masterTimeScale = 1): void {
    if (this.state.frozen) return;
    const realStep = clamp(deltaSeconds, 0, 0.1);
    const step = realStep * this.state.timeScale * clamp(
      masterTimeScale,
      1,
      64,
    );
    this.accumulator += realStep;
    if (this.state.mode === 'auto') {
      this.state.dayTime += step;
      this.state.cycleProgress =
        (this.state.dayTime / DAY_LENGTH_SECONDS) % 1;
    }
    const targetProgress =
      this.state.mode === 'auto'
        ? this.state.cycleProgress
        : PHASE_PROGRESS[this.state.mode];
    const target = sampleProfile(targetProgress, this.state.dayTime);
    const response = this.state.mode === 'auto' ? 1.8 : 2.4;
    this.state.phase = target.phase;
    this.state.daylight = damp(
      this.state.daylight,
      target.profile.daylight,
      response,
      step,
    );
    this.state.warmth = damp(
      this.state.warmth,
      target.profile.warmth,
      response,
      step,
    );
    this.state.twilight = damp(
      this.state.twilight,
      target.profile.twilight,
      response,
      step,
    );
    this.state.night = damp(
      this.state.night,
      target.profile.night,
      response,
      step,
    );
    this.state.sunHeight = damp(
      this.state.sunHeight,
      target.profile.sunHeight,
      response,
      step,
    );
    this.state.starVisibility = damp(
      this.state.starVisibility,
      target.profile.starVisibility,
      response,
      step,
    );
    this.state.artificialLight = damp(
      this.state.artificialLight,
      target.profile.artificialLight,
      response,
      step,
    );
    const targetAzimuth = targetProgress * TAU - Math.PI * 0.65;
    let azimuthDelta = targetAzimuth - this.state.sunAzimuth;
    while (azimuthDelta > Math.PI) azimuthDelta -= TAU;
    while (azimuthDelta < -Math.PI) azimuthDelta += TAU;
    this.state.sunAzimuth +=
      azimuthDelta * (1 - Math.exp(-response * step));
    while (this.accumulator >= DAY_STEP) {
      this.state.updates += 1;
      this.accumulator -= DAY_STEP;
    }
  }

  public applyAuthorityWorldTime(worldTimeSeconds: number): void {
    if (!Number.isFinite(worldTimeSeconds) || worldTimeSeconds < 0) return;
    this.state.mode = 'auto';
    this.state.dayTime = worldTimeSeconds;
    this.state.cycleProgress = (worldTimeSeconds / DAY_LENGTH_SECONDS) % 1;
    const target = sampleProfile(
      this.state.cycleProgress,
      this.state.dayTime,
    );
    this.state.phase = target.phase;
    this.state.sunAzimuth = this.state.cycleProgress * TAU - Math.PI * 0.65;
    Object.assign(this.state, target.profile);
    this.accumulator = 0;
  }

  public getState(): Readonly<DayNightState> {
    return this.state;
  }

  public exportState(): DayNightSystemSaveData {
    return {
      version: 1,
      state: { ...this.state },
      accumulator: this.accumulator,
    };
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<DayNightSystemSaveData>;
    const state = candidate.state as Partial<DayNightState> | undefined;
    if (
      candidate.version !== 1 ||
      !state ||
      !DAY_MODES.includes(state.mode as DayMode) ||
      !Object.hasOwn(PHASE_PROGRESS, state.phase ?? '') ||
      !DAY_TIME_SCALES.includes(state.timeScale as DayTimeScale)
    ) {
      return false;
    }
    const numericState = [
      state.cycleProgress,
      state.dayTime,
      state.sunAzimuth,
      state.updates,
      state.daylight,
      state.warmth,
      state.twilight,
      state.night,
      state.sunHeight,
      state.starVisibility,
      state.artificialLight,
      candidate.accumulator,
    ];
    if (!numericState.every((value) => Number.isFinite(value))) {
      return false;
    }

    Object.assign(this.state, {
      mode: state.mode,
      phase: state.phase,
      frozen: state.frozen === true,
      timeScale: state.timeScale,
      cycleProgress: clamp(state.cycleProgress ?? 0, 0, 1),
      // Keep the absolute day count: the 18 authored sky stories key from it.
      // Reconstructing from cycleProgress used to reset every loaded world to
      // day zero even though all other daylight values survived the save.
      dayTime: Math.max(0, state.dayTime ?? 0),
      sunAzimuth: state.sunAzimuth ?? 0,
      updates: Math.max(0, Math.floor(state.updates ?? 0)),
      daylight: clamp(state.daylight ?? 1, 0.15, 1),
      warmth: clamp(state.warmth ?? 0, 0, 1),
      twilight: clamp(state.twilight ?? 0, 0, 1),
      night: clamp(state.night ?? 0, 0, 1),
      sunHeight: clamp(state.sunHeight ?? 0.78, -0.24, 0.92),
      starVisibility: clamp(state.starVisibility ?? 0, 0, 1),
      artificialLight: clamp(
        state.artificialLight ?? 0.08,
        0,
        1,
      ),
    });
    this.accumulator = clamp(
      candidate.accumulator ?? 0,
      0,
      DAY_STEP,
    );
    return true;
  }

  public cycleMode(): DayMode {
    const currentDayIndex = Math.floor(
      Math.max(0, this.state.dayTime) / DAY_LENGTH_SECONDS,
    );
    this.state.mode = cycleValue(DAY_MODES, this.state.mode);
    if (this.state.mode !== 'auto') {
      this.state.phase = this.state.mode;
      this.state.cycleProgress = PHASE_PROGRESS[this.state.mode];
      this.state.dayTime =
        currentDayIndex * DAY_LENGTH_SECONDS +
        this.state.cycleProgress * DAY_LENGTH_SECONDS;
    }
    return this.state.mode;
  }

  public toggleFrozen(): boolean {
    this.state.frozen = !this.state.frozen;
    return this.state.frozen;
  }

  public cycleTimeScale(): DayTimeScale {
    this.state.timeScale = cycleValue(
      DAY_TIME_SCALES,
      this.state.timeScale,
    );
    return this.state.timeScale;
  }

  public setTimeScale(timeScale: DayTimeScale): void {
    this.state.timeScale = timeScale;
  }
}
