interface LandSnowTile {
  tileX: number;
  tileZ: number;
  depth: Float32Array;
  compaction: Float32Array;
  initialDepth: Float32Array;
  cellularTint: Float32Array;
  edgeSnowDepth: Float32Array;
  surfaceX: Float32Array;
  geometry: BufferGeometry;
  mesh: Mesh<BufferGeometry, MeshStandardMaterial>;
  modified: boolean;
  dirty: boolean;
  dirtyMinColumn: number;
  dirtyMaxColumn: number;
  dirtyMinRow: number;
  dirtyMaxRow: number;
  /** Per-row spans keep two distant tracks from uploading the full tile box. */
  dirtyMinColumnByRow: Int16Array;
  dirtyMaxColumnByRow: Int16Array;
  dirtyPriority: LandSnowMutationPriority;
  /**
   * Interaction bounds are tracked independently from weather/heat debt.
   * Without this, one boot touching a tile with a pending full-tile snowfall
   * promoted the entire 16 m weather rectangle to an urgent V5/V6 refresh.
   */
  interactionDirtyBounds?: {
    minColumn: number;
    maxColumn: number;
    minRow: number;
    maxRow: number;
  };
  hasBackgroundDirty: boolean;
  /** Tiny uniform weather changes remain canonical without uploading at 4 Hz. */
  weatherVisualDebt: number;
  /** Real elapsed weather time owed to this round-robin tile. */
  weatherElapsedDebt: number;
}

interface MutableSample {
  tile: LandSnowTile;
  index: number;
  x: number;
  z: number;
}

type LandSnowTileBuildStage = 'INITIAL' | 'ATTRIBUTES' | 'INDICES';

