import type { GpuSegment } from './DetailedPerformanceCapture';

interface TimerExtension { TIME_ELAPSED_EXT: number; GPU_DISJOINT_EXT: number }
interface PendingQuery { query: WebGLQuery; segment: Omit<GpuSegment, 'resolvedAtMs' | 'resolvedFrameId' | 'gpuMs' | 'status'> }

/** One active elapsed query, bounded asynchronous results, no finish/readback/spin waits. */
export class GpuQueryQueue {
  private extension: TimerExtension | null;
  private pending: PendingQuery[] = [];
  private active?: PendingQuery;
  private sequence = 0;
  public skipped = 0;
  public invalid = 0;
  public constructor(
    private readonly gl: WebGL2RenderingContext,
    private readonly publish: (segment: GpuSegment) => void,
    private readonly maximumPending = 256,
    private readonly timeoutMs = 5000,
  ) { this.extension = gl.getExtension('EXT_disjoint_timer_query_webgl2') as TimerExtension | null; }
  public get supported(): boolean { return this.extension !== null; }
  public get pendingCount(): number { return this.pending.length + (this.active ? 1 : 0); }
  public begin(captureId: number, frameId: number, scopePath: readonly string[], now = performance.now()): boolean {
    const ext = this.extension;
    if (!ext || this.gl.isContextLost() || this.active || this.pendingCount >= this.maximumPending ||
        this.gl.getQuery(ext.TIME_ELAPSED_EXT, this.gl.CURRENT_QUERY)) { this.skipped++; return false; }
    const query = this.gl.createQuery();
    if (!query) { this.skipped++; return false; }
    this.gl.beginQuery(ext.TIME_ELAPSED_EXT, query);
    this.active = { query, segment: { captureId, queryId: ++this.sequence, frameId, scopePath: [...scopePath], submittedAtMs: now } };
    return true;
  }
  public end(): void {
    if (!this.active || !this.extension) return;
    if (!this.gl.isContextLost()) this.gl.endQuery(this.extension.TIME_ELAPSED_EXT);
    this.pending.push(this.active); this.active = undefined;
  }
  public poll(frameId: number, now = performance.now()): void {
    if (!this.extension || this.active || !this.pending.length) return;
    const lost = this.gl.isContextLost();
    // Read disjoint before result availability; invalidate the entire outstanding batch.
    const disjoint = !lost && Boolean(this.gl.getParameter(this.extension.GPU_DISJOINT_EXT));
    const remaining: PendingQuery[] = [];
    for (const item of this.pending) {
      let status: GpuSegment['status'] | undefined;
      let gpuMs: number | null = null;
      if (lost) status = 'context-lost';
      else if (disjoint) status = 'disjoint';
      else if (now - item.segment.submittedAtMs > this.timeoutMs) status = 'timeout';
      else if (this.gl.getQueryParameter(item.query, this.gl.QUERY_RESULT_AVAILABLE)) {
        const ns = Number(this.gl.getQueryParameter(item.query, this.gl.QUERY_RESULT));
        status = Number.isFinite(ns) && ns >= 0 ? 'valid' : 'invalid-result';
        if (status === 'valid') gpuMs = ns / 1e6;
      }
      if (!status) { remaining.push(item); continue; }
      this.resolve(item, status, gpuMs, frameId, now);
    }
    this.pending = remaining;
  }
  public cancel(frameId: number, status: 'cancelled' | 'context-lost' = 'cancelled', now = performance.now()): void {
    this.end();
    for (const item of this.pending) this.resolve(item, status, null, frameId, now);
    this.pending = [];
  }
  public restore(): void {
    this.extension = this.gl.getExtension('EXT_disjoint_timer_query_webgl2') as TimerExtension | null;
  }
  private resolve(item: PendingQuery, status: GpuSegment['status'], gpuMs: number | null, frameId: number, now: number): void {
    if (status !== 'valid') this.invalid++;
    if (!this.gl.isContextLost()) this.gl.deleteQuery(item.query);
    this.publish({ ...item.segment, resolvedAtMs: now, resolvedFrameId: frameId, gpuMs, status });
  }
}
