import { clamp, hash2D } from '../utils/math';
import {
  WILDERNESS_ANIMAL_CATALOG,
  type WildernessAnimalSpecies,
} from './WildernessAnimalCatalog';

export const WILDERNESS_ANIMAL_WORLD_SIZE_METRES = 8_000;
export const WILDERNESS_ANIMAL_WORLD_CELL_METRES = 500;
export const WILDERNESS_ANIMAL_WORLD_CELL_AXIS =
  WILDERNESS_ANIMAL_WORLD_SIZE_METRES / WILDERNESS_ANIMAL_WORLD_CELL_METRES;

// Keep the original slow ecological pace as an explicit balance choice.
// It must not accidentally depend on the number of cells serviced per slice.
export const WILDERNESS_ECOLOGY_PACE = 1 / 32;
const ANIMAL_DEFINITIONS = new Map(WILDERNESS_ANIMAL_CATALOG.map((entry) => [entry.id, entry]));

export type WildernessAnimalWorldBiome =
  | 'TAIGA'
  | 'TUNDRA'
  | 'VALLEY'
  | 'WETLAND'
  | 'COAST'
  | 'ALPINE';

export interface WildernessAnimalPopulationCohort {
  readonly species: WildernessAnimalSpecies;
  population: number;
  carryingCapacity: number;
  hungerPressure: number;
  disturbance: number;
}

export interface WildernessAnimalWorldCellState {
  readonly key: string;
  readonly cellX: number;
  readonly cellZ: number;
  readonly biome: WildernessAnimalWorldBiome;
  readonly shelter: number;
  readonly water: number;
  readonly forage: number;
  readonly cohorts: WildernessAnimalPopulationCohort[];
  lastSimulatedSeconds: number;
}

export interface WildernessAnimalWorldSaveData {
  readonly version: 1;
  readonly elapsedSeconds: number;
  readonly updateCursor: number;
  readonly cells: readonly Readonly<{
    key: string;
    lastSimulatedSeconds: number;
    cohorts: readonly Readonly<Pick<
      WildernessAnimalPopulationCohort,
      'species' | 'population' | 'hungerPressure' | 'disturbance'
    >>[];
  }>[];
}

export interface WildernessAnimalWorldStats {
  readonly worldSizeMetres: number;
  readonly cellMetres: number;
  readonly cells: number;
  readonly populatedCells: number;
  readonly cohorts: number;
  readonly estimatedAnimals: number;
  readonly lastUpdatedCells: number;
  readonly lastUpdateMs: number;
}

const biomeFor = (
  cellX: number,
  cellZ: number,
): WildernessAnimalWorldBiome => {
  const temperature = hash2D(cellX, cellZ, 8803);
  const moisture = hash2D(cellX, cellZ, 8819);
  const relief = hash2D(cellX, cellZ, 8831);
  if (relief > 0.82) return 'ALPINE';
  if (moisture > 0.82) return temperature < 0.34 ? 'COAST' : 'WETLAND';
  if (temperature < 0.3) return 'TUNDRA';
  if (relief < 0.24) return 'VALLEY';
  return 'TAIGA';
};

const domainSuitability = (
  domain: (typeof WILDERNESS_ANIMAL_CATALOG)[number]['domain'],
  biome: WildernessAnimalWorldBiome,
  water: number,
): number => {
  if (domain === 'AQUATIC') return biome === 'COAST' ? 1 : water > 0.84 ? 0.35 : 0;
  if (domain === 'SHORE') return water > 0.58 ? 1 : 0.16;
  if (domain === 'AERIAL') return biome === 'ALPINE' ? 0.78 : 1;
  if (biome === 'COAST') return 0.38;
  if (biome === 'ALPINE') return 0.3;
  return 1;
};

const cellKey = (cellX: number, cellZ: number): string => `${cellX}:${cellZ}`;

const createCell = (
  cellX: number,
  cellZ: number,
): WildernessAnimalWorldCellState => {
  const biome = biomeFor(cellX, cellZ);
  const shelter = hash2D(cellX, cellZ, 8849);
  const water = hash2D(cellX, cellZ, 8861);
  const forage = hash2D(cellX, cellZ, 8867);
  const cohorts = WILDERNESS_ANIMAL_CATALOG.flatMap((definition, speciesIndex) => {
    const suitability = domainSuitability(definition.domain, biome, water);
    const habitatRoll = hash2D(cellX * 31 + speciesIndex, cellZ * 37, 8887);
    const foodFit = definition.diet.includes('FISH')
      ? water * 0.76 + forage * 0.24
      : definition.diet.includes('BERRY') || definition.diet.includes('ROOT')
        ? forage
        : shelter * 0.65 + forage * 0.35;
    const coverFit = definition.domain === 'AERIAL'
      ? 0.62 + shelter * 0.38
      : shelter;
    const habitat = suitability * (0.25 + foodFit * 0.48 + coverFit * 0.27);
    // Sparse populations are intentional. The 8 km world can know about
    // thousands of animals without allocating or ticking individual actors.
    if (habitat < 0.16 || habitatRoll > 0.2 + habitat * 0.66) return [];
    const carryingCapacity = Math.max(
      definition.backgroundDensity < 1 ? definition.backgroundDensity : 1,
      definition.backgroundDensity * habitat * (0.62 + habitatRoll * 0.76),
    );
    const population = definition.backgroundDensity < 1
      ? habitatRoll < carryingCapacity ? 1 : 0
      : Math.max(1, Math.round(carryingCapacity * (0.62 + habitatRoll * 0.32)));
    if (population <= 0) return [];
    return [{
      species: definition.id,
      population,
      carryingCapacity,
      hungerPressure: clamp(0.12 + (1 - forage) * 0.32, 0, 1),
      disturbance: 0,
    }];
  });
  return {
    key: cellKey(cellX, cellZ),
    cellX,
    cellZ,
    biome,
    shelter,
    water,
    forage,
    cohorts,
    lastSimulatedSeconds: 0,
  };
};

const createWorldCells = (): WildernessAnimalWorldCellState[] => {
  const half = WILDERNESS_ANIMAL_WORLD_CELL_AXIS / 2;
  const cells: WildernessAnimalWorldCellState[] = [];
  for (let z = -half; z < half; z += 1) {
    for (let x = -half; x < half; x += 1) cells.push(createCell(x, z));
  }
  return cells;
};

/**
 * Coarse, deterministic ecology for the complete future 8×8 km map.
 *
 * Only a narrow rotating slice is advanced per cadence. Detailed animals near
 * a player remain owned by WildernessSurvivalSimulation; everything else is
 * represented by population cohorts whose cost does not grow with distance or
 * camera visibility.
 */
export class WildernessAnimalWorldModel {
  public readonly cells = createWorldCells();
  private readonly byKey = new Map(this.cells.map((cell) => [cell.key, cell]));
  private elapsedSeconds = 0;
  private updateAccumulator = 0;
  private updateCursor = 0;
  private lastUpdatedCells = 0;
  private lastUpdateMs = 0;

  public constructor(saved?: Readonly<WildernessAnimalWorldSaveData>) {
    if (saved) this.importState(saved);
  }

  public update(
    deltaSeconds: number,
    context: Readonly<{
      playerX: number;
      playerZ: number;
      weatherSeverity: number;
      humanDisturbance?: number;
    }>,
  ): void {
    const delta = clamp(deltaSeconds, 0, 0.5);
    this.elapsedSeconds += delta;
    this.updateAccumulator += delta;
    if (this.updateAccumulator < 2) {
      this.lastUpdatedCells = 0;
      this.lastUpdateMs = 0;
      return;
    }
    const started = typeof performance !== 'undefined' ? performance.now() : 0;
    this.updateAccumulator = 0;
    const cellsPerSlice = 8;
    for (let offset = 0; offset < cellsPerSlice; offset += 1) {
      const cell = this.cells[(this.updateCursor + offset) % this.cells.length]!;
      const elapsed = Math.max(0, this.elapsedSeconds - cell.lastSimulatedSeconds);
      // Bound catch-up without throwing away time when a legacy save contains
      // a long-unvisited cell. Remaining debt is serviced on subsequent turns.
      const caughtUpSeconds = Math.min(elapsed, 120);
      const simulatedSeconds = caughtUpSeconds * WILDERNESS_ECOLOGY_PACE;
      const centreX = (cell.cellX + 0.5) * WILDERNESS_ANIMAL_WORLD_CELL_METRES;
      const centreZ = (cell.cellZ + 0.5) * WILDERNESS_ANIMAL_WORLD_CELL_METRES;
      const playerDistance = Math.hypot(
        centreX - context.playerX,
        centreZ - context.playerZ,
      );
      const localDisturbance = playerDistance < WILDERNESS_ANIMAL_WORLD_CELL_METRES
        ? clamp(context.humanDisturbance ?? 0.12, 0, 1)
        : 0;
      for (const cohort of cell.cohorts) {
        const definition = ANIMAL_DEFINITIONS.get(cohort.species)!;
        cohort.disturbance = clamp(
          cohort.disturbance + localDisturbance * simulatedSeconds * 0.018 -
            simulatedSeconds * 0.0025,
          0,
          1,
        );
        cohort.hungerPressure = clamp(
          cohort.hungerPressure +
            context.weatherSeverity * simulatedSeconds * 0.0014 -
            cell.forage * simulatedSeconds * 0.001,
          0,
          1,
        );
        // Background births/deaths are deliberately glacial. This system is
        // world continuity, not a management game demanding constant upkeep.
        const recovery = Math.max(0, cohort.carryingCapacity - cohort.population) *
          (0.00004 + definition.sociality * 0.000025) * simulatedSeconds;
        const pressure = Math.max(0, cohort.hungerPressure - 0.82) *
          (0.00008 + definition.danger * 0.00003) * simulatedSeconds;
        cohort.population = clamp(
          cohort.population + recovery - pressure,
          0,
          Math.max(1, cohort.carryingCapacity * 1.08),
        );
      }
      cell.lastSimulatedSeconds += caughtUpSeconds;
    }
    this.updateCursor = (this.updateCursor + cellsPerSlice) % this.cells.length;
    this.lastUpdatedCells = cellsPerSlice;
    this.lastUpdateMs = started > 0 ? performance.now() - started : 0;
  }

  public cellAt(worldX: number, worldZ: number): Readonly<WildernessAnimalWorldCellState> | undefined {
    const half = WILDERNESS_ANIMAL_WORLD_CELL_AXIS / 2;
    const cellX = Math.floor(worldX / WILDERNESS_ANIMAL_WORLD_CELL_METRES);
    const cellZ = Math.floor(worldZ / WILDERNESS_ANIMAL_WORLD_CELL_METRES);
    if (cellX < -half || cellX >= half || cellZ < -half || cellZ >= half) return undefined;
    return this.byKey.get(cellKey(cellX, cellZ));
  }

  public estimatedPopulation(species?: WildernessAnimalSpecies): number {
    return this.cells.reduce((total, cell) => total + cell.cohorts.reduce(
      (cellTotal, cohort) => cellTotal + (
        !species || cohort.species === species ? cohort.population : 0
      ),
      0,
    ), 0);
  }

  public stats(): WildernessAnimalWorldStats {
    const cohorts = this.cells.reduce((total, cell) => total + cell.cohorts.length, 0);
    return {
      worldSizeMetres: WILDERNESS_ANIMAL_WORLD_SIZE_METRES,
      cellMetres: WILDERNESS_ANIMAL_WORLD_CELL_METRES,
      cells: this.cells.length,
      populatedCells: this.cells.filter((cell) => cell.cohorts.length > 0).length,
      cohorts,
      estimatedAnimals: Math.round(this.estimatedPopulation()),
      lastUpdatedCells: this.lastUpdatedCells,
      lastUpdateMs: this.lastUpdateMs,
    };
  }

  public exportState(): WildernessAnimalWorldSaveData {
    return {
      version: 1,
      elapsedSeconds: this.elapsedSeconds,
      updateCursor: this.updateCursor,
      cells: this.cells.map((cell) => ({
        key: cell.key,
        lastSimulatedSeconds: cell.lastSimulatedSeconds,
        cohorts: cell.cohorts.map((cohort) => ({
          species: cohort.species,
          population: cohort.population,
          hungerPressure: cohort.hungerPressure,
          disturbance: cohort.disturbance,
        })),
      })),
    };
  }

  private importState(saved: Readonly<WildernessAnimalWorldSaveData>): void {
    if (saved.version !== 1) return;
    this.elapsedSeconds = Math.max(0, saved.elapsedSeconds);
    this.updateCursor = Math.floor(clamp(saved.updateCursor, 0, this.cells.length - 1));
    for (const savedCell of saved.cells) {
      const cell = this.byKey.get(savedCell.key);
      if (!cell) continue;
      cell.lastSimulatedSeconds = Math.max(0, savedCell.lastSimulatedSeconds);
      const cohorts = new Map(cell.cohorts.map((cohort) => [cohort.species, cohort]));
      for (const savedCohort of savedCell.cohorts) {
        const cohort = cohorts.get(savedCohort.species);
        if (!cohort) continue;
        cohort.population = clamp(
          savedCohort.population,
          0,
          Math.max(1, cohort.carryingCapacity * 1.08),
        );
        cohort.hungerPressure = clamp(savedCohort.hungerPressure, 0, 1);
        cohort.disturbance = clamp(savedCohort.disturbance, 0, 1);
      }
    }
  }
}
