import { clamp, smoothstep } from '../utils/math';

export const ICE_REFREEZE_VISUAL_TUNING = Object.freeze({
  crystalStart: 0.03,
  crystalEnd: 0.18,
  slushStart: 0.14,
  slushEnd: 0.38,
  plateStart: 0.32,
  plateEnd: 0.62,
  sheetStart: 0.58,
  sheetEnd: 0.84,
  maximumBlend: 0.74,
});

export interface IceRefreezeVisualBands {
  crystals: number;
  slush: number;
  plates: number;
  sheet: number;
}

export const calculateIceRefreezeVisualBands = (
  openness: number,
): IceRefreezeVisualBands => {
  const closure = 1 - clamp(openness, 0, 1);
  return {
    crystals: smoothstep(
      ICE_REFREEZE_VISUAL_TUNING.crystalStart,
      ICE_REFREEZE_VISUAL_TUNING.crystalEnd,
      closure,
    ),
    slush: smoothstep(
      ICE_REFREEZE_VISUAL_TUNING.slushStart,
      ICE_REFREEZE_VISUAL_TUNING.slushEnd,
      closure,
    ),
    plates: smoothstep(
      ICE_REFREEZE_VISUAL_TUNING.plateStart,
      ICE_REFREEZE_VISUAL_TUNING.plateEnd,
      closure,
    ),
    sheet: smoothstep(
      ICE_REFREEZE_VISUAL_TUNING.sheetStart,
      ICE_REFREEZE_VISUAL_TUNING.sheetEnd,
      closure,
    ),
  };
};

const glslFloat = (value: number): string => value.toFixed(4);

export const createIceRefreezeVisualGLSL = (): string => {
  const tuning = ICE_REFREEZE_VISUAL_TUNING;
  return `
    vec4 resolveIceRefreezeVisual(
      vec2 worldPoint,
      float openness,
      vec4 lifecycle,
      float iceCoverage,
      float ambientFormation,
      float insideIceField
    ) {
      float closure = clamp(1.0 - openness, 0.0, 1.0);
      float memoryMask = smoothstep(0.015, 0.08, lifecycle.b);
      float grace = clamp(
        lifecycle.r / max(0.015, closure),
        0.0,
        1.0
      );
      float localClosureMask = smoothstep(
        0.012,
        0.065,
        closure
      );
      float dynamicRefreezeActive = memoryMask *
        smoothstep(0.04, 0.42, grace) *
        localClosureMask *
        (1.0 - iceCoverage) *
        insideIceField;
      float ambientMaturity =
        clamp(ambientFormation, 0.0, 1.0) *
        (1.0 - iceCoverage) *
        insideIceField;
      float ambientActive =
        smoothstep(0.018, 0.12, ambientMaturity) * 0.88;
      float refreezeActive = max(
        dynamicRefreezeActive,
        ambientActive
      );
      if (refreezeActive < 0.001) {
        return vec4(0.0);
      }
      float formationProgress = max(
        closure * step(0.001, dynamicRefreezeActive),
        ambientMaturity
      );

      float crystalProgress = smoothstep(
        ${glslFloat(tuning.crystalStart)},
        ${glslFloat(tuning.crystalEnd)},
        formationProgress
      );
      float slushProgress = smoothstep(
        ${glslFloat(tuning.slushStart)},
        ${glslFloat(tuning.slushEnd)},
        formationProgress
      );
      float plateProgress = smoothstep(
        ${glslFloat(tuning.plateStart)},
        ${glslFloat(tuning.plateEnd)},
        formationProgress
      );
      float sheetProgress = smoothstep(
        ${glslFloat(tuning.sheetStart)},
        ${glslFloat(tuning.sheetEnd)},
        formationProgress
      );

      vec2 patternUv =
        vec2(
          worldPoint.x * 0.066 + worldPoint.y * 0.017,
          -worldPoint.x * 0.014 + worldPoint.y * 0.071
        ) +
        vec2(0.37, 0.61);
      vec4 pattern = texture2D(uOceanVoronoiMap, patternUv);
      float crystalField =
        pattern.b * 0.68 +
        pattern.a * 0.32;
      float platePopulation =
        smoothstep(
          0.76 - plateProgress * 0.5,
          0.84 - plateProgress * 0.42,
          pattern.r
        );
      float crystalMask =
        smoothstep(
          0.8 - crystalProgress * 0.28,
          0.89 - crystalProgress * 0.22,
          crystalField
        ) *
        smoothstep(0.025, 0.19, pattern.a);
      float slushMask =
        smoothstep(
          0.73 - slushProgress * 0.43,
          0.83 - slushProgress * 0.36,
          crystalField
        ) *
        smoothstep(0.018, 0.15, pattern.a);
      float plateInterior =
        platePopulation *
        smoothstep(0.018, 0.14, pattern.g);
      float plateSeam =
        platePopulation *
        (1.0 - smoothstep(0.018, 0.12, pattern.g)) *
        plateProgress *
        (1.0 - sheetProgress * 0.72);

      float patchCoverage = max(
        crystalMask * (1.0 - slushProgress * 0.58),
        max(
          slushMask * slushProgress,
          plateInterior * plateProgress
        )
      );
      patchCoverage = mix(
        patchCoverage,
        1.0,
        sheetProgress * 0.86
      );

      vec3 crystalColor = vec3(0.68, 0.94, 0.95);
      vec3 slushColor = vec3(0.43, 0.82, 0.86);
      vec3 plateColor = vec3(0.56, 0.84, 0.89);
      vec3 sheetColor = vec3(0.7, 0.88, 0.91);
      vec3 freezeColor = mix(
        crystalColor,
        slushColor,
        slushProgress
      );
      freezeColor = mix(
        freezeColor,
        plateColor,
        plateProgress
      );
      freezeColor = mix(
        freezeColor,
        sheetColor,
        sheetProgress
      );
      freezeColor = mix(
        freezeColor,
        vec3(0.2, 0.55, 0.65),
        plateSeam * 0.58
      );

      float blend = refreezeActive *
        (
          patchCoverage *
            mix(0.38, 0.7, plateProgress) +
          sheetProgress * 0.16
        );
      return vec4(
        freezeColor,
        clamp(blend, 0.0, ${glslFloat(tuning.maximumBlend)})
      );
    }
  `;
};
