import type {
  RuntimeMetricSummary,
  RuntimePerformanceSnapshot,
  RuntimePerformanceTrace,
  RuntimeTraceContext,
} from './RuntimePerformanceTrace';

export type PerformanceScenarioId =
  | 'arrival-town'
  | 'snow-plow-four-minutes'
  | 'cave-mining'
  | 'warm-cultivation'
  | 'seasonal-density';

export type PerformanceTargetProfile = 'DESKTOP_60' | 'TABLET_30';

export interface PerformanceScenarioDefinition {
  readonly id: PerformanceScenarioId;
  readonly displayName: string;
  readonly recommendedSeconds: number;
  readonly instructions: readonly string[];
}

export interface PerformanceBudgetFinding {
  readonly metric: string;
  readonly value: number;
  readonly limit: number;
  readonly passed: boolean;
  readonly note: string;
}

export interface PerformanceScenarioReport {
  readonly version: 1;
  readonly scenario: PerformanceScenarioDefinition;
  readonly profile: PerformanceTargetProfile;
  readonly startedAtMs: number;
  readonly completedAtMs: number;
  readonly elapsedSeconds: number;
  readonly passed: boolean;
  readonly findings: readonly PerformanceBudgetFinding[];
  readonly trace: RuntimePerformanceSnapshot;
}

