const metricValue = (
  metrics: Readonly<Record<string, RuntimeMetricSummary>>,
  name: string,
  field: keyof RuntimeMetricSummary,
): number => metrics[name]?.[field] ?? 0;

export const evaluatePerformanceScenarioSnapshot = (
  snapshot: Readonly<RuntimePerformanceSnapshot>,
  profile: PerformanceTargetProfile,
): readonly PerformanceBudgetFinding[] => {
  const frameLimit = profile === 'DESKTOP_60' ? 16.7 : 33.4;
  const cpuLimit = profile === 'DESKTOP_60' ? 14 : 28;
  const findings: PerformanceBudgetFinding[] = [];
  const add = (metric: string, value: number, limit: number, note: string): void => {
    findings.push(Object.freeze({
      metric,
      value,
      limit,
      passed: value <= limit,
      note,
    }));
  };
  add(
    'frame.interval.p95',
    metricValue(snapshot.metrics, 'frame.interval', 'p95Ms'),
    frameLimit,
    'Representative frame pacing after scenario warm-up.',
  );
  add(
    'frame.cpu.p95',
    metricValue(snapshot.metrics, 'frame.cpu', 'p95Ms'),
    cpuLimit,
    'Main-thread work must leave presentation headroom.',
  );
  add(
    'worst-frame',
    snapshot.worstFrameMs,
    100,
    'No post-warm-up interaction should create a visible long hitch.',
  );
  add(
    'frame.render.p99',
    metricValue(snapshot.metrics, 'frame.scene-render', 'p99Ms'),
    profile === 'DESKTOP_60' ? 10 : 22,
    'Scene rendering budget includes current lighting and snow detail.',
  );
  return Object.freeze(findings);
};

interface ActiveScenario {
  readonly definition: PerformanceScenarioDefinition;
  readonly profile: PerformanceTargetProfile;
  readonly startedAtMs: number;
}

export interface PerformanceScenarioLabInspector {
  list(): readonly PerformanceScenarioDefinition[];
  start(id: PerformanceScenarioId, profile?: PerformanceTargetProfile): void;
  checkpoint(name: string): void;
  finish(): PerformanceScenarioReport | undefined;
  current(): Readonly<ActiveScenario> | undefined;
  download(): void;
  dispose(): void;
}

export const installPerformanceScenarioLab = (
  trace: RuntimePerformanceTrace,
  context: () => Readonly<RuntimeTraceContext>,
): PerformanceScenarioLabInspector => {
  let active: ActiveScenario | undefined;
  let lastReport: PerformanceScenarioReport | undefined;
  const inspector: PerformanceScenarioLabInspector = {
    list: () => PERFORMANCE_SCENARIOS,
    start: (id, profile = 'DESKTOP_60') => {
      const definition = PERFORMANCE_SCENARIOS.find((item) => item.id === id);
      if (!definition) throw new Error(`Unknown performance scenario: ${id}`);
      trace.clear();
      active = Object.freeze({
        definition,
        profile,
        startedAtMs: performance.now(),
      });
      trace.event('performance-scenario-start', context(), {
        scenarioId: id,
        profile,
        recommendedSeconds: definition.recommendedSeconds,
      });
    },
    checkpoint: (name) => {
      if (!active) return;
      trace.event('performance-scenario-checkpoint', context(), {
        scenarioId: active.definition.id,
        checkpoint: name.trim().slice(0, 80) || 'unnamed',
      });
    },
    finish: () => {
      if (!active) return undefined;
      const completedAtMs = performance.now();
      trace.event('performance-scenario-finish', context(), {
        scenarioId: active.definition.id,
      });
      const snapshot = trace.snapshot(completedAtMs);
      const findings = evaluatePerformanceScenarioSnapshot(snapshot, active.profile);
      lastReport = Object.freeze({
        version: 1,
        scenario: active.definition,
        profile: active.profile,
        startedAtMs: active.startedAtMs,
        completedAtMs,
        elapsedSeconds: Math.max(0, (completedAtMs - active.startedAtMs) / 1_000),
        passed: findings.every((finding) => finding.passed),
        findings,
        trace: snapshot,
      });
      active = undefined;
      return lastReport;
    },
    current: () => active,
    download: () => {
      const report = lastReport ?? inspector.finish();
      if (!report) return;
      const blob = new Blob([JSON.stringify(report, null, 2)], {
        type: 'application/json',
      });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `iceway-performance-scenario-${report.scenario.id}-${new Date()
        .toISOString().replace(/[:.]/g, '-')}.json`;
      document.body.append(link);
      link.click();
      link.remove();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 0);
    },
    dispose: () => {
      const target = window as Window & {
        __ICEWAY_PERF_LAB__?: PerformanceScenarioLabInspector;
      };
      if (target.__ICEWAY_PERF_LAB__ === inspector) {
        delete target.__ICEWAY_PERF_LAB__;
      }
      active = undefined;
    },
  };
  (window as Window & {
    __ICEWAY_PERF_LAB__?: PerformanceScenarioLabInspector;
  }).__ICEWAY_PERF_LAB__ = inspector;
  return inspector;
};
