import { Ray, Triangle, Vector3 } from 'three';
import type { RoofPoint } from './SurvivalModularRoof';

/** Convex saved panel polygons are shared by presentation, picking and air.
 * Unlike a height query, these functions also handle vertical gable panels. */
export function roofPanelNormal(points: readonly RoofPoint[]): Vector3 {
  const [a, b, c] = points;
  if (!a || !b || !c) return new Vector3(0, 1, 0);
  return new Vector3(b.x-a.x, b.y-a.y, b.z-a.z).cross(new Vector3(c.x-a.x,c.y-a.y,c.z-a.z)).normalize();
}

export function distanceToRoofPanel(points: readonly RoofPoint[], point: RoofPoint): number {
  const p = new Vector3(point.x,point.y,point.z), closest = new Vector3();
  const triangle = new Triangle(), a = points[0];
  if (!a) return Infinity;
  triangle.a.set(a.x,a.y,a.z);
  let distance = Infinity;
  for (let i=1;i<points.length-1;i++) {
    const b=points[i]!,c=points[i+1]!;
    triangle.b.set(b.x,b.y,b.z); triangle.c.set(c.x,c.y,c.z);
    triangle.closestPointToPoint(p,closest);
    distance=Math.min(distance,p.distanceTo(closest));
  }
  return distance;
}

export function rayRoofPanel(points: readonly RoofPoint[], origin: RoofPoint, direction: RoofPoint): number {
  const ray=new Ray(new Vector3(origin.x,origin.y,origin.z),new Vector3(direction.x,direction.y,direction.z).normalize());
  const a=points[0]; if (!a) return Infinity;
  const av=new Vector3(a.x,a.y,a.z), b=new Vector3(),c=new Vector3(), hit=new Vector3();
  let distance=Infinity;
  for(let i=1;i<points.length-1;i++) {
    const bp=points[i]!,cp=points[i+1]!;b.set(bp.x,bp.y,bp.z);c.set(cp.x,cp.y,cp.z);
    if(ray.intersectTriangle(av,b,c,false,hit))distance=Math.min(distance,hit.distanceTo(ray.origin));
  }
  return distance;
}
