import {
  BufferGeometry,
  Color,
  DoubleSide,
  Float32BufferAttribute,
  Mesh,
  MeshBasicMaterial,
  MeshStandardMaterial,
  Scene,
} from 'three';
import { WORLD } from '../world/WorldConfig';
import {
  DEFAULT_ICE_VISUAL_PROFILE_ID,
  getIceVisualStyle,
  type IceMaterialDebugMode,
  type IceVisualProfileId,
} from '../ice/IceThicknessProfile';
import {
  IceCellOwner,
  IceDirtyFlag,
} from '../ice/IceOwnership';
import {
  ICE_SURFACE_TUNING,
  type IceSurfaceMaterialChannels,
} from './ArcticRendering';
import {
  clamp,
  hash2D,
  lerp,
  smoothstep,
} from '../utils/math';
import {
  castsIceEdgeShadow,
  ICE_SHADOW_CULL_HYSTERESIS,
  isInsideIceShadowRange,
  type IceShadowQualitySettings,
} from './IceShadowRendering';

export interface IceSurfaceChunkCell
  extends IceSurfaceMaterialChannels {
  owner: IceCellOwner;
}

export interface IceSurfaceChunkStats {
  chunks: number;
  rebuilds: number;
  snowUpdates: number;
  cells: number;
  triangles: number;
}

export interface IceSurfaceAppearance {
  weatherContrast: number;
  warmth: number;
  wetnessEmphasis: number;
  snowLightResponse: number;
}

type IceSurfaceSampler = (
  column: number,
  row: number,
  target: IceSurfaceChunkCell,
) => IceSurfaceChunkCell;

interface SurfaceVertex {
  x: number;
  y: number;
  z: number;
}

enum SurfaceEdge {
  Left = 0,
  Right = 1,
  Top = 2,
  Bottom = 3,
}

const POLYGON_EDGE_AFTER_CORNER = [
  SurfaceEdge.Left,
  SurfaceEdge.Bottom,
  SurfaceEdge.Right,
  SurfaceEdge.Top,
] as const;

const SURFACE_REBUILD_FLAGS = IceDirtyFlag.Geometry;
const SOLID_OPENNESS = 0.72;

export const getOrganicIceBoundaryOffset = (
  column: number,
  row: number,
  edgeIndex: number,
  outwardX: number,
  outwardZ: number,
): Readonly<{ x: number; z: number }> => {
  const edgeSeed = column * 4 + edgeIndex;
  const normalOffset =
    (hash2D(edgeSeed, row, 977) - 0.42) *
    WORLD.cellSize *
    0.3;
  const tangentNoise =
    hash2D(edgeSeed, row, 983) - 0.5;
  const tangentOffset =
    Math.sign(tangentNoise || 1) *
    (
      0.045 +
      Math.abs(tangentNoise) * 0.16
    ) *
    WORLD.cellSize;
  return {
    x:
      outwardX * normalOffset -
      outwardZ * tangentOffset,
    z:
      outwardZ * normalOffset +
      outwardX * tangentOffset,
  };
};

export const getOrganicIceCornerOffset = (
  column: number,
  row: number,
  columns: number,
  rows: number,
): Readonly<{ x: number; z: number }> => {
  const boundary =
    column === 0 ||
    column === columns ||
    row === 0 ||
    row === rows;
  const jitter = boundary ? 0 : WORLD.cellSize * 0.4;
  return {
    x: (hash2D(column, row, 881) - 0.5) * jitter,
    z: (hash2D(column, row, 883) - 0.5) * jitter,
  };
};

export class IceSurfaceChunkRenderer {
  public readonly chunkIndex: number;

  private readonly bodyMesh: Mesh<
    BufferGeometry,
    MeshStandardMaterial
  >;
  private readonly opticalMesh: Mesh<
    BufferGeometry,
    MeshStandardMaterial
  >;
  private readonly shadowMesh: Mesh<
    BufferGeometry,
    MeshBasicMaterial
  >;
  private readonly chunkColumn: number;
  private readonly chunkRow: number;
  private readonly chunkSize: number;
  private readonly columns: number;
  private readonly rows: number;
  private readonly width: number;
  private readonly height: number;
  private readonly shadowCenterX: number;
  private readonly shadowCenterZ: number;
  private readonly shadowBoundingRadius: number;
  private readonly sample: IceSurfaceChunkCell = {
    owner: IceCellOwner.OpenWater,
    thickness: 0,
    openness: 1,
    snow: 0,
    wetness: 0,
    stress: 0,
    edge: 0,
  };
  private readonly neighbor: IceSurfaceChunkCell = {
    owner: IceCellOwner.OpenWater,
    thickness: 0,
    openness: 1,
    snow: 0,
    wetness: 0,
    stress: 0,
    edge: 0,
  };
  private readonly weatherContrastUniform = { value: 1 };
  private readonly warmthUniform = { value: 0 };
  private readonly wetnessEmphasisUniform = { value: 1 };
  private readonly snowLightResponseUniform = { value: 1 };
  private readonly materialDebugModeUniform = { value: 0 };
  private readonly surfaceColorValue = new Color();
  private readonly sideColorValue = new Color();
  private visualProfile: IceVisualProfileId;
  private rebuilds = 0;
  private snowUpdates = 0;
  private renderedCells = 0;
  private triangles = 0;

  public constructor(
    scene: Scene,
    chunkColumn: number,
    chunkRow: number,
    columns: number,
    rows: number,
    chunkSize: number,
    visualProfile: IceVisualProfileId =
      DEFAULT_ICE_VISUAL_PROFILE_ID,
  ) {
    this.chunkColumn = chunkColumn;
    this.chunkRow = chunkRow;
    this.columns = columns;
    this.rows = rows;
    this.chunkSize = chunkSize;
    this.visualProfile = visualProfile;
    this.width = columns * WORLD.cellSize;
    this.height = rows * WORLD.cellSize;
    const startColumn = chunkColumn * chunkSize;
    const startRow = chunkRow * chunkSize;
    const endColumn = Math.min(columns, startColumn + chunkSize);
    const endRow = Math.min(rows, startRow + chunkSize);
    const chunkWidth = (endColumn - startColumn) * WORLD.cellSize;
    const chunkHeight = (endRow - startRow) * WORLD.cellSize;
    this.shadowCenterX =
      (startColumn + endColumn) * 0.5 * WORLD.cellSize -
      this.width * 0.5;
    this.shadowCenterZ =
      (startRow + endRow) * 0.5 * WORLD.cellSize -
      this.height * 0.5;
    this.shadowBoundingRadius =
      Math.hypot(chunkWidth, chunkHeight) * 0.5;
    this.chunkIndex =
      chunkRow * Math.ceil(columns / chunkSize) + chunkColumn;

    const bodyMaterial = new MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.7,
      metalness: 0,
      vertexColors: true,
      transparent: false,
      depthWrite: true,
    });
    const opticalMaterial = new MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.7,
      metalness: 0,
      vertexColors: true,
      transparent: true,
      depthWrite: false,
      alphaTest: 0.012,
    });
    bodyMaterial.colorWrite = false;
    const configureMaterial = (
      material: MeshStandardMaterial,
      layer: 0 | 1,
    ): void => {
      material.onBeforeCompile = (shader) => {
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'attribute vec4 iceSurfaceData;',
            'attribute float iceSurfaceOpacity;',
            'attribute float iceSurfaceStress;',
            'attribute vec3 iceSurfaceWeights;',
            'attribute float iceSurfaceRoughness;',
            'varying vec4 vIceSurfaceData;',
            'varying float vIceSurfaceOpacity;',
            'varying float vIceSurfaceStress;',
            'varying vec3 vIceSurfaceWeights;',
            'varying float vIceSurfaceRoughness;',
            'varying vec2 vIceSurfacePoint;',
          ].join('\n'),
        )
        .replace(
          '#include <begin_vertex>',
          [
            '#include <begin_vertex>',
            'vIceSurfaceData = iceSurfaceData;',
            'vIceSurfaceOpacity = iceSurfaceOpacity;',
            'vIceSurfaceStress = iceSurfaceStress;',
            'vIceSurfaceWeights = iceSurfaceWeights;',
            'vIceSurfaceRoughness = iceSurfaceRoughness;',
            'vIceSurfacePoint = position.xz;',
          ].join('\n'),
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          [
            '#include <common>',
            'uniform float uIceWeatherContrast;',
            'uniform float uIceWarmth;',
            'uniform float uIceWetnessEmphasis;',
            'uniform float uIceSnowLightResponse;',
            'uniform float uIceMaterialDebugMode;',
            'uniform float uIceLayer;',
            'varying vec4 vIceSurfaceData;',
            'varying float vIceSurfaceOpacity;',
            'varying float vIceSurfaceStress;',
            'varying vec3 vIceSurfaceWeights;',
            'varying float vIceSurfaceRoughness;',
            'varying vec2 vIceSurfacePoint;',
            'float iceHash21(vec2 point) {',
            '  point = fract(point * vec2(123.34, 456.21));',
            '  point += dot(point, point + 45.32);',
            '  return fract(point.x * point.y);',
            '}',
            'float iceNoise21(vec2 point) {',
            '  vec2 cell = floor(point);',
            '  vec2 local = fract(point);',
            '  local = local * local * (3.0 - 2.0 * local);',
            '  return mix(',
            '    mix(iceHash21(cell), iceHash21(cell + vec2(1.0, 0.0)), local.x),',
            '    mix(iceHash21(cell + vec2(0.0, 1.0)), iceHash21(cell + vec2(1.0, 1.0)), local.x),',
            '    local.y',
            '  );',
            '}',
          ].join('\n'),
        )
        .replace(
          'vec4 diffuseColor = vec4( diffuse, opacity );',
          [
            'float surfaceVariation =',
            '  iceNoise21(vIceSurfacePoint * 0.24) * 0.68 +',
            '  iceNoise21(vIceSurfacePoint * 0.73 + 11.4) * 0.32;',
            'float crackRibbonA = abs(sin(',
            '  vIceSurfacePoint.x * 2.1 +',
            '  sin(vIceSurfacePoint.y * 1.26) * 2.75',
            '));',
            'float crackRibbonB = abs(sin(',
            '  vIceSurfacePoint.y * 2.55 +',
            '  sin(vIceSurfacePoint.x * 1.08 + 1.7) * 3.05',
            '));',
            'float crack = max(',
            '  smoothstep(0.986, 0.998, crackRibbonA),',
            '  smoothstep(0.99, 0.999, crackRibbonB) *',
            '    smoothstep(0.42, 0.74, surfaceVariation)',
            ') * vIceSurfaceStress *',
            '  (1.0 - smoothstep(0.82, 0.98, vIceSurfaceData.w));',
            'vec3 surfaceColor = diffuse;',
            'if (uIceMaterialDebugMode < 0.5) {',
            '  surfaceColor *= 0.965 + surfaceVariation * 0.055;',
            '  float weatherLuma = dot(',
            '    surfaceColor,',
            '    vec3(0.2126, 0.7152, 0.0722)',
            '  );',
            '  surfaceColor = mix(',
            '    vec3(weatherLuma),',
            '    surfaceColor,',
            '    uIceWeatherContrast',
            '  );',
            '  surfaceColor = mix(',
            '    surfaceColor,',
            '    vec3(0.76, 0.88, 0.92),',
            '    max(0.0, -uIceWarmth) * 0.16',
            '  );',
            '  surfaceColor = mix(',
            '    surfaceColor,',
            '    vec3(1.0, 0.91, 0.78),',
            '    max(0.0, uIceWarmth) * 0.13',
            '  );',
            '  surfaceColor = mix(',
            '    surfaceColor,',
            '    vec3(0.45, 0.72, 0.77),',
            '    vIceSurfaceData.z * 0.18 * uIceWetnessEmphasis',
            '  );',
            '  surfaceColor = mix(',
            '    surfaceColor,',
            '    vec3(0.96, 0.985, 1.0),',
            '    vIceSurfaceData.y * 0.82 * uIceSnowLightResponse',
            '  );',
            '  surfaceColor = mix(',
            '    surfaceColor,',
            '    vec3(0.16, 0.37, 0.43),',
            '    crack * 0.42',
            '  );',
            '} else if (uIceMaterialDebugMode < 1.5) {',
            '  surfaceColor = vec3(clamp(vIceSurfaceData.x, 0.0, 1.0));',
            '} else {',
            '  surfaceColor = vec3(',
            '    vIceSurfaceWeights.z,',
            '    vIceSurfaceWeights.y,',
            '    vIceSurfaceWeights.x',
            '  );',
            '}',
            'vec4 diffuseColor = vec4(',
            '  surfaceColor,',
            '  opacity * vIceSurfaceOpacity',
            ');',
            'if (uIceMaterialDebugMode > 0.5) {',
            '  if (uIceLayer > 0.5) discard;',
            '  diffuseColor.a = 1.0;',
            '} else if (uIceLayer < 0.5) {',
            '  float bodyCoverage = vIceSurfaceWeights.z;',
            '  if (bodyCoverage < 0.985) discard;',
            '  diffuseColor.a = 1.0;',
            '} else {',
            '  diffuseColor.a *= 1.0;',
            '}',
          ].join('\n'),
        )
        .replace(
          '#include <roughnessmap_fragment>',
          [
            '#include <roughnessmap_fragment>',
            'roughnessFactor =',
            '  uIceMaterialDebugMode < 0.5',
            '    ? vIceSurfaceRoughness',
            '    : 0.92;',
            'if (uIceMaterialDebugMode < 0.5) {',
            `  roughnessFactor = mix(roughnessFactor, ${ICE_SURFACE_TUNING.wetRoughness.toFixed(3)}, vIceSurfaceData.z);`,
            `  roughnessFactor = mix(roughnessFactor, ${ICE_SURFACE_TUNING.dryRoughness.toFixed(3)}, vIceSurfaceData.y * 0.88);`,
            `  roughnessFactor = mix(roughnessFactor, ${ICE_SURFACE_TUNING.wetRoughness.toFixed(3)}, crack * 0.7);`,
            '}',
          ].join('\n'),
        );
      shader.uniforms.uIceWeatherContrast =
        this.weatherContrastUniform;
      shader.uniforms.uIceWarmth = this.warmthUniform;
      shader.uniforms.uIceWetnessEmphasis =
        this.wetnessEmphasisUniform;
      shader.uniforms.uIceSnowLightResponse =
        this.snowLightResponseUniform;
      shader.uniforms.uIceMaterialDebugMode =
        this.materialDebugModeUniform;
      shader.uniforms.uIceLayer = { value: layer };
      };
      material.customProgramCacheKey = () =>
        `ice-surface-chunk-v4-${layer}`;
    };
    configureMaterial(bodyMaterial, 0);
    configureMaterial(opticalMaterial, 1);

    const geometry = new BufferGeometry();
    this.bodyMesh = new Mesh(geometry, bodyMaterial);
    this.bodyMesh.name =
      `Ice Surface V2 chunk ${chunkColumn},${chunkRow}`;
    this.bodyMesh.receiveShadow = true;
    this.bodyMesh.castShadow = false;
    this.bodyMesh.frustumCulled = true;
    this.bodyMesh.renderOrder = 10;
    this.opticalMesh = new Mesh(geometry, opticalMaterial);
    this.opticalMesh.name =
      `Ice Surface V2 optical ${chunkColumn},${chunkRow}`;
    this.opticalMesh.receiveShadow = true;
    this.opticalMesh.castShadow = false;
    this.opticalMesh.frustumCulled = true;
    this.opticalMesh.renderOrder = 11;
    const shadowMaterial = new MeshBasicMaterial({
      color: 0x000000,
      colorWrite: false,
      depthWrite: false,
      depthTest: false,
      side: DoubleSide,
      toneMapped: false,
    });
    this.shadowMesh = new Mesh(
      new BufferGeometry(),
      shadowMaterial,
    );
    this.shadowMesh.name =
      `Ice Surface V2 edge shadow ${chunkColumn},${chunkRow}`;
    this.shadowMesh.castShadow = true;
    this.shadowMesh.receiveShadow = false;
    this.shadowMesh.frustumCulled = true;
    this.shadowMesh.visible = false;
    scene.add(this.bodyMesh, this.opticalMesh, this.shadowMesh);
  }

  public containsCell(column: number, row: number): boolean {
    return (
      column >= this.chunkColumn * this.chunkSize &&
      column < (this.chunkColumn + 1) * this.chunkSize &&
      row >= this.chunkRow * this.chunkSize &&
      row < (this.chunkRow + 1) * this.chunkSize
    );
  }

  public replacesCell(column: number, row: number): boolean {
    return this.containsCell(column, row);
  }

  public needsRebuild(dirtyFlags: number): boolean {
    return (dirtyFlags & SURFACE_REBUILD_FLAGS) !== 0;
  }

  public rebuild(sampleCell: IceSurfaceSampler): void {
    const positions: number[] = [];
    const normals: number[] = [];
    const colors: number[] = [];
    const surfaceData: number[] = [];
    const opacity: number[] = [];
    const stress: number[] = [];
    const weights: number[] = [];
    const roughness: number[] = [];
    const snowCoordinates: number[] = [];
    const indices: number[] = [];
    const shadowPositions: number[] = [];
    const shadowIndices: number[] = [];
    const topVertexByCorner = new Map<number, number>();
    this.renderedCells = 0;

    const startColumn = this.chunkColumn * this.chunkSize;
    const startRow = this.chunkRow * this.chunkSize;
    const endColumn = Math.min(
      this.columns,
      startColumn + this.chunkSize,
    );
    const endRow = Math.min(this.rows, startRow + this.chunkSize);

    for (let row = startRow; row < endRow; row += 1) {
      for (
        let column = startColumn;
        column < endColumn;
        column += 1
      ) {
        const cell = sampleCell(column, row, this.sample);
        if (
          cell.owner !== IceCellOwner.StaticPack ||
          cell.openness >= SOLID_OPENNESS
        ) {
          continue;
        }

        const cornerIndices = [
          this.getTopVertex(
            column,
            row,
            sampleCell,
            topVertexByCorner,
            positions,
            normals,
            colors,
            surfaceData,
            opacity,
            stress,
            weights,
            roughness,
            snowCoordinates,
          ),
          this.getTopVertex(
            column,
            row + 1,
            sampleCell,
            topVertexByCorner,
            positions,
            normals,
            colors,
            surfaceData,
            opacity,
            stress,
            weights,
            roughness,
            snowCoordinates,
          ),
          this.getTopVertex(
            column + 1,
            row + 1,
            sampleCell,
            topVertexByCorner,
            positions,
            normals,
            colors,
            surfaceData,
            opacity,
            stress,
            weights,
            roughness,
            snowCoordinates,
          ),
          this.getTopVertex(
            column + 1,
            row,
            sampleCell,
            topVertexByCorner,
            positions,
            normals,
            colors,
            surfaceData,
            opacity,
            stress,
            weights,
            roughness,
            snowCoordinates,
          ),
        ] as const;
        const boundaryEdges = this.boundaryEdges(
          column,
          row,
          sampleCell,
        );
        const boundaryMidpointIndices = [
          boundaryEdges[SurfaceEdge.Left]
            ? this.pushTopMidpoint(
                cornerIndices[0],
                cornerIndices[1],
                -1,
                0,
                column,
                row,
                0,
                positions,
                normals,
                colors,
                surfaceData,
                opacity,
                stress,
                weights,
                roughness,
                snowCoordinates,
              )
            : undefined,
          boundaryEdges[SurfaceEdge.Right]
            ? this.pushTopMidpoint(
                cornerIndices[2],
                cornerIndices[3],
                1,
                0,
                column,
                row,
                1,
                positions,
                normals,
                colors,
                surfaceData,
                opacity,
                stress,
                weights,
                roughness,
                snowCoordinates,
              )
            : undefined,
          boundaryEdges[SurfaceEdge.Top]
            ? this.pushTopMidpoint(
                cornerIndices[3],
                cornerIndices[0],
                0,
                -1,
                column,
                row,
                2,
                positions,
                normals,
                colors,
                surfaceData,
                opacity,
                stress,
                weights,
                roughness,
                snowCoordinates,
              )
            : undefined,
          boundaryEdges[SurfaceEdge.Bottom]
            ? this.pushTopMidpoint(
                cornerIndices[1],
                cornerIndices[2],
                0,
                1,
                column,
                row,
                3,
                positions,
                normals,
                colors,
                surfaceData,
                opacity,
                stress,
                weights,
                roughness,
                snowCoordinates,
              )
            : undefined,
        ] as const;
        if (boundaryEdges.some(Boolean)) {
          const polygon: number[] = [];
          for (let edgeIndex = 0; edgeIndex < 4; edgeIndex += 1) {
            polygon.push(cornerIndices[edgeIndex]!);
            const midpoint =
              boundaryMidpointIndices[
                POLYGON_EDGE_AFTER_CORNER[edgeIndex]!
              ];
            if (midpoint !== undefined) polygon.push(midpoint);
          }
          const center = this.pushTopCenter(
            cornerIndices,
            positions,
            normals,
            colors,
            surfaceData,
            opacity,
            stress,
            weights,
            roughness,
            snowCoordinates,
          );
          for (let index = 0; index < polygon.length; index += 1) {
            indices.push(
              center,
              polygon[index]!,
              polygon[(index + 1) % polygon.length]!,
            );
          }
        } else {
          indices.push(
            cornerIndices[0],
            cornerIndices[1],
            cornerIndices[2],
            cornerIndices[0],
            cornerIndices[2],
            cornerIndices[3],
          );
        }
        const corners = cornerIndices.map((index) => ({
          x: positions[index * 3] ?? 0,
          y: positions[index * 3 + 1] ?? 0,
          z: positions[index * 3 + 2] ?? 0,
        })) as unknown as readonly [
          SurfaceVertex,
          SurfaceVertex,
          SurfaceVertex,
          SurfaceVertex,
        ];
        const boundaryMidpoints =
          boundaryMidpointIndices.map((index) =>
            index === undefined
              ? undefined
              : this.vertexAt(index, positions),
          );

        this.pushBoundarySides(
          column,
          row,
          corners,
          cell,
          boundaryMidpoints,
          sampleCell,
          positions,
          normals,
          colors,
          surfaceData,
          opacity,
          stress,
          weights,
          roughness,
          snowCoordinates,
          indices,
          shadowPositions,
          shadowIndices,
        );
        this.renderedCells += 1;
      }
    }

    const geometry = new BufferGeometry();
    geometry.setAttribute(
      'position',
      new Float32BufferAttribute(positions, 3),
    );
    geometry.setAttribute(
      'normal',
      new Float32BufferAttribute(normals, 3),
    );
    geometry.setAttribute(
      'color',
      new Float32BufferAttribute(colors, 3),
    );
    geometry.setAttribute(
      'iceSurfaceData',
      new Float32BufferAttribute(surfaceData, 4),
    );
    geometry.setAttribute(
      'iceSurfaceOpacity',
      new Float32BufferAttribute(opacity, 1),
    );
    geometry.setAttribute(
      'iceSurfaceStress',
      new Float32BufferAttribute(stress, 1),
    );
    geometry.setAttribute(
      'iceSurfaceWeights',
      new Float32BufferAttribute(weights, 3),
    );
    geometry.setAttribute(
      'iceSurfaceRoughness',
      new Float32BufferAttribute(roughness, 1),
    );
    geometry.setAttribute(
      'iceSurfaceSnowCoordinate',
      new Float32BufferAttribute(snowCoordinates, 3),
    );
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();

    const previous = this.bodyMesh.geometry;
    const previousShadow = this.shadowMesh.geometry;
    this.bodyMesh.geometry = geometry;
    this.opticalMesh.geometry = geometry;
    const shadowGeometry = new BufferGeometry();
    shadowGeometry.setAttribute(
      'position',
      new Float32BufferAttribute(shadowPositions, 3),
    );
    shadowGeometry.setIndex(shadowIndices);
    shadowGeometry.computeBoundingSphere();
    this.shadowMesh.geometry = shadowGeometry;
    previous.dispose();
    previousShadow.dispose();
    this.triangles = indices.length / 3;
    this.rebuilds += 1;
  }

  public getStats(): IceSurfaceChunkStats {
    return {
      chunks: 1,
      rebuilds: this.rebuilds,
      snowUpdates: this.snowUpdates,
      cells: this.renderedCells,
      triangles: this.triangles,
    };
  }

  public updateSnow(sampleCell: IceSurfaceSampler): number {
    const surfaceData = this.bodyMesh.geometry.getAttribute(
      'iceSurfaceData',
    ) as Float32BufferAttribute | undefined;
    const snowCoordinates = this.bodyMesh.geometry.getAttribute(
      'iceSurfaceSnowCoordinate',
    ) as Float32BufferAttribute | undefined;
    if (!surfaceData || !snowCoordinates) return 0;

    let changed = 0;
    for (let index = 0; index < surfaceData.count; index += 1) {
      const snow =
        this.sampleSnowAtGridCoordinate(
          snowCoordinates.getX(index),
          snowCoordinates.getY(index),
          sampleCell,
        ) * snowCoordinates.getZ(index);
      if (Math.abs(surfaceData.getY(index) - snow) < 0.0001) {
        continue;
      }
      surfaceData.setY(index, snow);
      changed += 1;
    }
    if (changed > 0) {
      surfaceData.needsUpdate = true;
      this.snowUpdates += 1;
    }
    return changed;
  }

  public setAppearance(
    appearance: Partial<Readonly<IceSurfaceAppearance>>,
  ): void {
    if (appearance.weatherContrast !== undefined) {
      this.weatherContrastUniform.value = clamp(
        appearance.weatherContrast,
        0.65,
        1.2,
      );
    }
    if (appearance.warmth !== undefined) {
      this.warmthUniform.value = clamp(
        appearance.warmth,
        -1,
        1,
      );
    }
    if (appearance.wetnessEmphasis !== undefined) {
      this.wetnessEmphasisUniform.value = clamp(
        appearance.wetnessEmphasis,
        0.5,
        1.5,
      );
    }
    if (appearance.snowLightResponse !== undefined) {
      this.snowLightResponseUniform.value = clamp(
        appearance.snowLightResponse,
        0.5,
        1.35,
      );
    }
  }

  public getAppearance(): IceSurfaceAppearance {
    return {
      weatherContrast: this.weatherContrastUniform.value,
      warmth: this.warmthUniform.value,
      wetnessEmphasis: this.wetnessEmphasisUniform.value,
      snowLightResponse: this.snowLightResponseUniform.value,
    };
  }

  public setMaterialDebugMode(
    mode: IceMaterialDebugMode,
  ): void {
    this.materialDebugModeUniform.value =
      mode === 'thickness' ? 1 : mode === 'weights' ? 2 : 0;
    this.bodyMesh.material.colorWrite = mode !== 'normal';
  }

  public setVisualProfile(profile: IceVisualProfileId): void {
    this.visualProfile = profile;
  }

  public setVisible(visible: boolean): void {
    this.bodyMesh.visible = visible;
    this.opticalMesh.visible = visible;
    if (!visible) this.shadowMesh.visible = false;
  }

  public setShadowState(
    presentationVisible: boolean,
    focusX: number,
    focusZ: number,
    settings: Readonly<IceShadowQualitySettings>,
  ): void {
    this.shadowMesh.visible =
      presentationVisible &&
      settings.enabled &&
      this.shadowMesh.geometry.getAttribute('position').count > 0 &&
      isInsideIceShadowRange(
        this.shadowCenterX,
        this.shadowCenterZ,
        this.shadowBoundingRadius,
        focusX,
        focusZ,
        settings.casterRadius +
          (
            this.shadowMesh.visible
              ? ICE_SHADOW_CULL_HYSTERESIS
              : 0
          ),
      );
  }

  public dispose(): void {
    this.bodyMesh.removeFromParent();
    this.opticalMesh.removeFromParent();
    this.shadowMesh.removeFromParent();
    this.bodyMesh.geometry.dispose();
    this.shadowMesh.geometry.dispose();
    this.bodyMesh.material.dispose();
    this.opticalMesh.material.dispose();
    this.shadowMesh.material.dispose();
  }

  private corner(
    column: number,
    row: number,
    y: number,
  ): SurfaceVertex {
    const offset = getOrganicIceCornerOffset(
      column,
      row,
      this.columns,
      this.rows,
    );
    return {
      x:
        column * WORLD.cellSize -
        this.width * 0.5 +
        offset.x,
      y,
      z:
        row * WORLD.cellSize -
        this.height * 0.5 +
        offset.z,
    };
  }

  private pushBoundarySides(
    column: number,
    row: number,
    corners: readonly [
      SurfaceVertex,
      SurfaceVertex,
      SurfaceVertex,
      SurfaceVertex,
    ],
    cell: Readonly<IceSurfaceChunkCell>,
    boundaryMidpoints: readonly (
      | SurfaceVertex
      | undefined
    )[],
    sampleCell: IceSurfaceSampler,
    positions: number[],
    normals: number[],
    colors: number[],
    surfaceData: number[],
    opacity: number[],
    stress: number[],
    weights: number[],
    roughness: number[],
    snowCoordinates: number[],
    indices: number[],
    shadowPositions: number[],
    shadowIndices: number[],
  ): void {
    const style = getIceVisualStyle(
      cell.thickness,
      hash2D(column, row, 1901) * 2 - 1,
      this.visualProfile,
    );
    this.sideColorValue.setHex(style.sideColor);
    const edges = [
      {
        column: column - 1,
        row,
        a: corners[1],
        b: corners[0],
        normal: { x: -1, y: 0, z: 0 },
      },
      {
        column: column + 1,
        row,
        a: corners[3],
        b: corners[2],
        normal: { x: 1, y: 0, z: 0 },
      },
      {
        column,
        row: row - 1,
        a: corners[0],
        b: corners[3],
        normal: { x: 0, y: 0, z: -1 },
      },
      {
        column,
        row: row + 1,
        a: corners[2],
        b: corners[1],
        normal: { x: 0, y: 0, z: 1 },
      },
    ] as const;

    for (let edgeIndex = 0; edgeIndex < edges.length; edgeIndex += 1) {
      const edge = edges[edgeIndex]!;
      const outside =
        edge.column < 0 ||
        edge.column >= this.columns ||
        edge.row < 0 ||
        edge.row >= this.rows;
      const neighbor = outside
        ? this.neighbor
        : sampleCell(edge.column, edge.row, this.neighbor);
      if (
        !outside &&
        neighbor.owner === IceCellOwner.StaticPack &&
        neighbor.openness < SOLID_OPENNESS
      ) {
        continue;
      }
      const bottomY = Math.max(
        0.018,
        Math.min(edge.a.y, edge.b.y) -
          0.055 -
          style.heightScale * 0.1,
      );
      const topPoints = boundaryMidpoints[edgeIndex]
        ? [edge.a, boundaryMidpoints[edgeIndex]!, edge.b]
        : [edge.a, edge.b];
      for (
        let segment = 0;
        segment < topPoints.length - 1;
        segment += 1
      ) {
        const topA = topPoints[segment]!;
        const topB = topPoints[segment + 1]!;
        const bottomA = { ...topA, y: bottomY };
        const bottomB = { ...topB, y: bottomY };
        this.pushQuad(
          topA,
          topB,
          bottomB,
          bottomA,
          edge.normal,
          this.sideColorValue,
          [
            cell.thickness,
            cell.snow * 0.15,
            Math.max(cell.wetness, 0.7),
            1,
          ],
          Math.max(
            0.12,
            style.opacity * 0.76,
          ) *
            this.worldBoundaryWeightAtCell(column, row),
          cell.stress,
          [
            style.weights.thin,
            style.weights.medium,
            style.weights.thick,
          ],
          Math.min(0.96, style.roughness + 0.07),
          [column + 0.5, row + 0.5, 0.15],
          positions,
          normals,
          colors,
          surfaceData,
          opacity,
          stress,
          weights,
          roughness,
          snowCoordinates,
          indices,
        );
        if (castsIceEdgeShadow(cell.thickness)) {
          this.pushShadowQuad(
            topA,
            topB,
            bottomB,
            bottomA,
            shadowPositions,
            shadowIndices,
          );
        }
      }
    }
  }

  private pushShadowQuad(
    a: Readonly<SurfaceVertex>,
    b: Readonly<SurfaceVertex>,
    c: Readonly<SurfaceVertex>,
    d: Readonly<SurfaceVertex>,
    positions: number[],
    indices: number[],
  ): void {
    const start = positions.length / 3;
    for (const vertex of [a, b, c, d]) {
      positions.push(vertex.x, vertex.y, vertex.z);
    }
    indices.push(
      start,
      start + 1,
      start + 2,
      start,
      start + 2,
      start + 3,
    );
  }

  private boundaryEdges(
    column: number,
    row: number,
    sampleCell: IceSurfaceSampler,
  ): readonly [boolean, boolean, boolean, boolean] {
    return [
      !this.isStaticSurfaceCell(column - 1, row, sampleCell),
      !this.isStaticSurfaceCell(column + 1, row, sampleCell),
      !this.isStaticSurfaceCell(column, row - 1, sampleCell),
      !this.isStaticSurfaceCell(column, row + 1, sampleCell),
    ];
  }

  private sampleSnowAtGridCoordinate(
    column: number,
    row: number,
    sampleCell: IceSurfaceSampler,
  ): number {
    const left = Math.floor(column);
    const top = Math.floor(row);
    const amountX = column - left;
    const amountY = row - top;
    const topLeft = this.sampleSnowAtCorner(
      left,
      top,
      sampleCell,
    );
    const topRight = this.sampleSnowAtCorner(
      left + 1,
      top,
      sampleCell,
    );
    const bottomLeft = this.sampleSnowAtCorner(
      left,
      top + 1,
      sampleCell,
    );
    const bottomRight = this.sampleSnowAtCorner(
      left + 1,
      top + 1,
      sampleCell,
    );
    return lerp(
      lerp(topLeft, topRight, amountX),
      lerp(bottomLeft, bottomRight, amountX),
      amountY,
    );
  }

  private sampleSnowAtCorner(
    cornerColumn: number,
    cornerRow: number,
    sampleCell: IceSurfaceSampler,
  ): number {
    let total = 0;
    let samples = 0;
    const adjacent = [
      [cornerColumn - 1, cornerRow - 1],
      [cornerColumn, cornerRow - 1],
      [cornerColumn - 1, cornerRow],
      [cornerColumn, cornerRow],
    ] as const;
    for (const [column, row] of adjacent) {
      if (
        column < 0 ||
        column >= this.columns ||
        row < 0 ||
        row >= this.rows
      ) {
        continue;
      }
      const cell = sampleCell(column, row, this.neighbor);
      if (
        cell.owner !== IceCellOwner.StaticPack ||
        cell.openness >= SOLID_OPENNESS
      ) {
        continue;
      }
      total += cell.snow;
      samples += 1;
    }
    return samples > 0 ? total / samples : 0;
  }

  private isStaticSurfaceCell(
    column: number,
    row: number,
    sampleCell: IceSurfaceSampler,
  ): boolean {
    if (
      column < 0 ||
      column >= this.columns ||
      row < 0 ||
      row >= this.rows
    ) {
      return false;
    }
    const cell = sampleCell(column, row, this.neighbor);
    return (
      cell.owner === IceCellOwner.StaticPack &&
      cell.openness < SOLID_OPENNESS
    );
  }

  private pushTopMidpoint(
    a: number,
    b: number,
    outwardX: number,
    outwardZ: number,
    column: number,
    row: number,
    edgeIndex: number,
    positions: number[],
    normals: number[],
    colors: number[],
    surfaceData: number[],
    opacity: number[],
    stress: number[],
    weights: number[],
    roughness: number[],
    snowCoordinates: number[],
  ): number {
    const offset = getOrganicIceBoundaryOffset(
      column,
      row,
      edgeIndex,
      outwardX,
      outwardZ,
    );
    return this.pushInterpolatedTopVertex(
      [a, b],
      offset.x,
      offset.z,
      positions,
      normals,
      colors,
      surfaceData,
      opacity,
      stress,
      weights,
      roughness,
      snowCoordinates,
    );
  }

  private pushTopCenter(
    corners: readonly number[],
    positions: number[],
    normals: number[],
    colors: number[],
    surfaceData: number[],
    opacity: number[],
    stress: number[],
    weights: number[],
    roughness: number[],
    snowCoordinates: number[],
  ): number {
    return this.pushInterpolatedTopVertex(
      corners,
      0,
      0,
      positions,
      normals,
      colors,
      surfaceData,
      opacity,
      stress,
      weights,
      roughness,
      snowCoordinates,
    );
  }

  private pushInterpolatedTopVertex(
    sources: readonly number[],
    offsetX: number,
    offsetZ: number,
    positions: number[],
    normals: number[],
    colors: number[],
    surfaceData: number[],
    opacity: number[],
    stress: number[],
    weights: number[],
    roughness: number[],
    snowCoordinates: number[],
  ): number {
    const inverse = 1 / Math.max(1, sources.length);
    const index = positions.length / 3;
    for (let component = 0; component < 3; component += 1) {
      let total = 0;
      for (const source of sources) {
        total += positions[source * 3 + component] ?? 0;
      }
      positions.push(
        total * inverse +
          (component === 0
            ? offsetX
            : component === 2
              ? offsetZ
              : 0),
      );
    }
    normals.push(0, 1, 0);
    for (let component = 0; component < 3; component += 1) {
      let total = 0;
      for (const source of sources) {
        total += colors[source * 3 + component] ?? 0;
      }
      colors.push(total * inverse);
    }
    for (let component = 0; component < 4; component += 1) {
      let total = 0;
      for (const source of sources) {
        total += surfaceData[source * 4 + component] ?? 0;
      }
      surfaceData.push(total * inverse);
    }
    opacity.push(
      sources.reduce(
        (total, source) => total + (opacity[source] ?? 0),
        0,
      ) * inverse,
    );
    stress.push(
      sources.reduce(
        (total, source) => total + (stress[source] ?? 0),
        0,
      ) * inverse,
    );
    for (let component = 0; component < 3; component += 1) {
      let total = 0;
      for (const source of sources) {
        total += weights[source * 3 + component] ?? 0;
      }
      weights.push(total * inverse);
    }
    roughness.push(
      sources.reduce(
        (total, source) =>
          total + (roughness[source] ?? 0),
        0,
      ) * inverse,
    );
    for (let component = 0; component < 3; component += 1) {
      let total = 0;
      for (const source of sources) {
        total +=
          snowCoordinates[source * 3 + component] ?? 0;
      }
      snowCoordinates.push(total * inverse);
    }
    return index;
  }

  private vertexAt(
    index: number,
    positions: readonly number[],
  ): SurfaceVertex {
    return {
      x: positions[index * 3] ?? 0,
      y: positions[index * 3 + 1] ?? 0,
      z: positions[index * 3 + 2] ?? 0,
    };
  }

  private getTopVertex(
    cornerColumn: number,
    cornerRow: number,
    sampleCell: IceSurfaceSampler,
    cache: Map<number, number>,
    positions: number[],
    normals: number[],
    colors: number[],
    surfaceData: number[],
    opacity: number[],
    stress: number[],
    weights: number[],
    roughness: number[],
    snowCoordinates: number[],
  ): number {
    const cacheKey =
      cornerRow * (this.columns + 1) + cornerColumn;
    const cached = cache.get(cacheKey);
    if (cached !== undefined) return cached;

    let samples = 0;
    let thickness = 0;
    let openness = 0;
    let snow = 0;
    let wetness = 0;
    let crackStress = 0;
    let edge = 0;
    const adjacent = [
      [cornerColumn - 1, cornerRow - 1],
      [cornerColumn, cornerRow - 1],
      [cornerColumn - 1, cornerRow],
      [cornerColumn, cornerRow],
    ] as const;
    for (const [column, row] of adjacent) {
      if (
        column < 0 ||
        column >= this.columns ||
        row < 0 ||
        row >= this.rows
      ) {
        edge = 1;
        continue;
      }
      const cell = sampleCell(column, row, this.neighbor);
      if (
        cell.owner !== IceCellOwner.StaticPack ||
        cell.openness >= SOLID_OPENNESS
      ) {
        edge = Math.max(
          edge,
          smoothstep(0.38, 0.8, cell.openness),
        );
        continue;
      }
      samples += 1;
      thickness += cell.thickness;
      openness += cell.openness;
      snow += cell.snow;
      wetness += cell.wetness;
      crackStress += cell.stress;
    }
    const inverse = 1 / Math.max(1, samples);
    thickness *= inverse;
    openness *= inverse;
    snow *= inverse;
    wetness *= inverse;
    crackStress *= inverse;
    edge = Math.max(edge, 1 - samples * 0.25);
    const coverage = samples * 0.25;

    const blend = this.worldBoundaryWeightAtCorner(
      cornerColumn,
      cornerRow,
    );
    const style = getIceVisualStyle(
      thickness,
      hash2D(cornerColumn, cornerRow, 1901) * 2 - 1,
      this.visualProfile,
    );
    const y = 0.075 + style.heightScale * 0.095;
    const point = this.corner(cornerColumn, cornerRow, y);
    this.surfaceColorValue.setHex(style.color);
    const alpha =
      style.opacity *
      lerp(0.7, 1, 1 - openness) *
      smoothstep(0.04, 0.94, coverage) *
      blend;
    const index = positions.length / 3;
    positions.push(point.x, point.y, point.z);
    normals.push(0, 1, 0);
    colors.push(
      this.surfaceColorValue.r,
      this.surfaceColorValue.g,
      this.surfaceColorValue.b,
    );
    surfaceData.push(
      thickness,
      snow,
      Math.max(wetness, edge * (0.28 + openness * 0.32)),
      edge,
    );
    opacity.push(alpha);
    stress.push(crackStress);
    weights.push(
      style.weights.thin,
      style.weights.medium,
      style.weights.thick,
    );
    roughness.push(style.roughness);
    snowCoordinates.push(cornerColumn, cornerRow, 1);
    cache.set(cacheKey, index);
    return index;
  }

  private worldBoundaryWeightAtCorner(
    column: number,
    row: number,
  ): number {
    const edgeDistance = Math.min(
      column,
      this.columns - column,
      row,
      this.rows - row,
    );
    return smoothstep(0, 0.9, edgeDistance);
  }

  private worldBoundaryWeightAtCell(
    column: number,
    row: number,
  ): number {
    const edgeDistance = Math.min(
      column + 0.5,
      this.columns - column - 0.5,
      row + 0.5,
      this.rows - row - 0.5,
    );
    return smoothstep(0, 1.1, edgeDistance);
  }

  private pushQuad(
    a: Readonly<SurfaceVertex>,
    b: Readonly<SurfaceVertex>,
    c: Readonly<SurfaceVertex>,
    d: Readonly<SurfaceVertex>,
    normal: Readonly<SurfaceVertex>,
    color: Readonly<Color>,
    data: readonly [number, number, number, number],
    alpha: number,
    crackStress: number,
    materialWeights: readonly [number, number, number],
    vertexRoughness: number,
    snowCoordinate: readonly [number, number, number],
    positions: number[],
    normals: number[],
    colors: number[],
    surfaceData: number[],
    opacity: number[],
    stress: number[],
    weights: number[],
    roughness: number[],
    snowCoordinates: number[],
    indices: number[],
  ): void {
    const startIndex = positions.length / 3;
    const vertices = [a, b, c, d] as const;
    for (const vertex of vertices) {
      positions.push(vertex.x, vertex.y, vertex.z);
      normals.push(normal.x, normal.y, normal.z);
      colors.push(color.r, color.g, color.b);
      surfaceData.push(data[0], data[1], data[2], data[3]);
      opacity.push(alpha);
      stress.push(crackStress);
      weights.push(
        materialWeights[0],
        materialWeights[1],
        materialWeights[2],
      );
      roughness.push(vertexRoughness);
      snowCoordinates.push(
        snowCoordinate[0],
        snowCoordinate[1],
        snowCoordinate[2],
      );
    }
    indices.push(
      startIndex,
      startIndex + 1,
      startIndex + 2,
      startIndex,
      startIndex + 2,
      startIndex + 3,
    );
  }
}
