import { Vector3, type Ray } from 'three';
import { survivalBuildDefinition, type SurvivalBuildPieceDefinition } from '../SurvivalBuildingCatalog';
import type { SurvivalBuildPlacementAim, SurvivalBuildPlacementResolution } from '../SurvivalBuildPlacementV2';
import type { SurvivalPlacedBuildPiece } from './SurvivalConstructionState';
import { findSurvivalFurnitureSurface, type SurvivalFurnitureSurface } from './SurvivalFurnitureSupport';
import { freePlacementMount, nearestWallAlignment, snapLocalCoordinate } from './SurvivalFreePlacement';

const rotate=(x:number,z:number,yaw:number):[number,number]=>{
  const a=yaw*Math.PI/180;return [x*Math.cos(a)+z*Math.sin(a),-x*Math.sin(a)+z*Math.cos(a)];
};

export type FreeFurnitureResolution=SurvivalBuildPlacementResolution & {
  surfaceSupport?: SurvivalFurnitureSurface; supportError?: string;
};

export function resolveFreeFurniturePlacement(options:{
  definition:SurvivalBuildPieceDefinition; aim:SurvivalBuildPlacementAim;
  pieces:readonly SurvivalPlacedBuildPiece[]; yaw:number; grid:boolean;
  terrain:(x:number,z:number)=>number; ray?:Readonly<Ray>;
  surfaceSolidAt?:(piece:SurvivalPlacedBuildPiece,u:number,v:number)=>boolean;
}):FreeFurnitureResolution {
  const {definition:d,aim,pieces,grid,terrain}=options,mount=freePlacementMount(d);
  let result:FreeFurnitureResolution={x:aim.x,y:aim.y,z:aim.z,yawDegrees:options.yaw,intent:'GROUND_GRID',socketHints:[]};
  if(mount==='BELOW') {
    if(grid){
      const host=pieces.find(p=>p.id===aim.hit?.pieceId);
      const origin=host??{x:0,z:0,yawDegrees:0};
      const [u,v]=rotate(aim.x-origin.x,aim.z-origin.z,-origin.yawDegrees);
      const [x,z]=rotate(snapLocalCoordinate(u,.25),snapLocalCoordinate(v,.25),origin.yawDegrees);
      result={...result,x:origin.x+x,z:origin.z+z};
    }
    const pointedSurface = aim.hit && aim.hit.normalY > .5 &&
      Math.hypot(aim.hit.x-aim.x,aim.hit.y-aim.y,aim.hit.z-aim.z) < .03;
    const heightTolerance = pointedSurface ? .025 : .12;
    const surface=findSurvivalFurnitureSurface(pieces,d,result,aim.y-heightTolerance,aim.y+heightTolerance,options.surfaceSolidAt);
    if(surface) return {...result,y:surface.y,surfaceSupport:surface,targetPieceId:surface.pieceIds[0],intent:'STACK'};
    const heights=[-1,0,1].flatMap(u=>[-1,0,1].map(v=>{
      const [x,z]=rotate(u*d.halfWidth,v*d.halfDepth,result.yawDegrees);
      return terrain(result.x+x,result.z+z);
    }));
    const top=Math.max(...heights),bottom=Math.min(...heights);
    if (pointedSurface && !surface) return {...result,supportError:'The whole footprint needs support on the pointed surface.'};
    if(Number.isFinite(top)&&Math.abs(top-result.y)<=.12&&top-bottom<=.18)return {...result,y:top};
    return {...result,supportError:'Needs a surface immediately below · wheel moves depth · Alt + wheel zooms'};
  }
  if(mount==='CEILING') {
    const hit=aim.hit,host=pieces.find(p=>p.id===hit?.pieceId);
    // The free cursor is the suspension point. Do not jump back to a ray hit
    // several metres behind the cursor when a player adjusts depth.
    if(!host||!hit||hit.normalY>-.5||Math.hypot(hit.x-aim.x,hit.y-aim.y,hit.z-aim.z)>.22)
      return {...result,y:aim.y-d.height,supportError:'Move the hanger against the underside of a supporting surface.'};
    return {...result,y:hit.y-d.height,yawDegrees:options.yaw,targetPieceId:host.id,intent:'ATTACH',
      connection:{targetPieceId:host.id,targetSocketId:`ceiling-free:${aim.x.toFixed(3)},${aim.z.toFixed(3)}`,sourceSocketId:'hanger'}};
  }
  if(mount==='WALL') {
    const source=d.sockets.find(s=>s.kind==='WALL_MOUNT'&&s.placementRole==='SOURCE');
    let best:FreeFurnitureResolution|undefined,bestDistance=.24;
    for(const host of pieces){
      if (aim.hit && host.id !== aim.hit.pieceId) continue;
      const hd=survivalBuildDefinition(host.definitionId);
      if(!['WALL','FRAME'].includes(hd.family)||hd.height<.3)continue;
      const [u,v]=rotate(aim.x-host.x,aim.z-host.z,-host.yawDegrees);
      const y=aim.y-host.y;
      const camera=options.ray?.origin??new Vector3(aim.x-aim.forwardX,aim.y,aim.z-aim.forwardZ);
      const [,cameraV]=rotate(camera.x-host.x,camera.z-host.z,-host.yawDegrees);
      const side=cameraV>=0?1:-1,face=side*hd.halfDepth;
      const distance=Math.abs(v-face);
      if(distance>bestDistance||Math.abs(u)>hd.halfWidth-d.halfWidth+.025||y<0||y+d.height>hd.height+.025)continue;
      // A torch cannot mount to the empty opening in a door or window.
      if(['DOOR_FRAME','STONE_ARCH'].includes(host.definitionId)&&Math.abs(u)<.64&&y<1.8)continue;
      if(host.definitionId==='LOG_WALL_WINDOW'&&Math.abs(u)<.58&&y+d.height>.65&&y<1.7)continue;
      const aligned=nearestWallAlignment(u,y,hd.halfWidth,hd.height,grid);
      const targetU=aligned?.u??(grid?snapLocalCoordinate(u,.25):u);
      const targetY=aligned?.y??(grid?snapLocalCoordinate(y,.25):y);
      if(Math.abs(targetU)+d.halfWidth>hd.halfWidth+.025||targetY+d.height>hd.height+.025)continue;
      const yaw=host.yawDegrees+(side<0?180:0);
      const [wx,wz]=rotate(targetU,face,host.yawDegrees);
      const [sx,sz]=rotate(source?.position.x??0,source?.position.z??-.1,yaw);
      const key=`face:${side}:${targetU.toFixed(3)},${targetY.toFixed(3)}`;
      best={...result,x:host.x+wx-sx,y:host.y+targetY-(source?.position.y??0),z:host.z+wz-sz,
        yawDegrees:yaw,targetPieceId:host.id,intent:'ATTACH',snapKey:`${host.id}:${key}`,
        connection:{targetPieceId:host.id,targetSocketId:key,sourceSocketId:source?.id??'wall-back'},
        socketHints:[0,1,2].flatMap(row=>[0,1,2].map(column=>{
          const [x,z]=rotate((column-1)*hd.halfWidth*.72,face+side*.015,host.yawDegrees);
          return {key:`${host.id}:align-${column}-${row}`,pieceId:host.id,socketId:`align-${column}-${row}`,
            x:host.x+x,y:host.y+hd.height*(.26+row*.26),z:host.z+z,
            selected:aligned?.row===row&&aligned.column===column};
        }))};
      bestDistance=distance;
    }
    return best??{...result,supportError:'Move the back of this fixture against a wall · wheel moves depth'};
  }
  return result;
}
