import {
  Group,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  type Material,
  type Scene,
} from 'three';
import type { TerrainHeightSystem } from '../../land/TerrainHeightSystem';
import type { WorldAssetPlacementSystem } from '../../land/WorldAssetPlacementSystem';
import {
  THE_LONG_WINTER_FIRE_ROOT_ENABLED,
  THE_LONG_WINTER_MECHANOS_ENABLED,
  THE_LONG_WINTER_STONE_LAB_ENABLED,
} from '../../core/RuntimeBuildFlags';
import type {
  WildernessActionResult,
  WildernessSurvivalSimulation,
} from '../WildernessSurvivalSimulation';
import {
  ANCIENT_ECHOES_LANDMARKS,
  AncientEchoesModel,
  type AncientEchoesInteraction,
  type AncientEchoesSaveData,
  type AncientEchoesView,
} from './AncientEchoesModel';

export interface AncientEchoesInteractionCandidate {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly aimRadius: number;
  readonly reach: number;
}

interface AncientVisual {
  readonly root: Group;
  readonly glowParts: Mesh[];
  readonly ownedMaterials: Material[];
}

const ANCIENT_PREFABS = Object.freeze({
  root: 'TLW_FIRE_ROOT_01',
  collapse: 'TLW_ANCIENT_COLLAPSE_01',
  laboratory: 'TLW_ANCIENT_LABORATORY_01',
  bench: 'TLW_ANCIENT_LAB_BENCH_01',
  planter: 'TLW_ANCIENT_ROOT_PLANTER_01',
  weapon: 'TLW_ANCIENT_WEAPON_01',
  mechanos: 'TLW_ANCIENT_MECHANOS_01',
} as const);

/**
 * Thin scene/input adapter around AncientEchoesModel. The feature does not
 * own character movement, weather, survival authority or the base inventory;
 * disabling it removes one root, one save key and one interaction dispatch.
 */
export class AncientEchoesSystem {
  public readonly model: AncientEchoesModel;
  private readonly root = new Group();
  private readonly visuals = new Map<string, AncientVisual>();
  private active = false;
  private revealSeconds = 0;
  private visualTime = 0;

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    private readonly simulation: WildernessSurvivalSimulation,
    private readonly assetBank?: WorldAssetPlacementSystem,
    saved?: Readonly<AncientEchoesSaveData>,
  ) {
    this.model = new AncientEchoesModel(simulation.inventory, saved);
    this.root.name = 'The Long Winter · detachable Ancient Echoes feature island';
    scene.add(this.root);
    this.createInitialVisuals();
    this.synchronizePresentation(true);
    this.root.visible = false;
  }

  public setActive(active: boolean): void {
    this.active = active;
    this.root.visible = active;
  }

  public view(): AncientEchoesView {
    return this.model.view();
  }

  public exportState(): AncientEchoesSaveData {
    return this.model.exportState();
  }

  public canWalkAt(x: number, z: number, radius: number): boolean {
    if (!this.active || !THE_LONG_WINTER_STONE_LAB_ENABLED) return true;
    const lab = ANCIENT_ECHOES_LANDMARKS.laboratory;
    if (!this.model.laboratoryOpen) {
      const collapse = ANCIENT_ECHOES_LANDMARKS.collapse;
      return Math.hypot(x - collapse.x, z - collapse.z) > 1.18 + radius;
    }
    const local = this.labLocal(x, z);
    const nearSideWall = Math.abs(Math.abs(local.x) - 4.72) <= 0.34 + radius &&
      Math.abs(local.z) <= 4.05 + radius;
    const nearBackWall = Math.abs(local.z + 3.78) <= 0.34 + radius &&
      Math.abs(local.x) <= 5.05 + radius;
    const atFront = Math.abs(local.z - 3.78) <= 0.34 + radius;
    const frontPier = atFront && Math.abs(local.x) >= 2.72 - radius &&
      Math.abs(local.x) <= 5.05 + radius;
    return !(nearSideWall || nearBackWall || frontPier);
  }

  public sampleWalkSurfaceHeight(x: number, z: number, base: number): number {
    if (!this.active || !this.model.laboratoryOpen) return base;
    const local = this.labLocal(x, z);
    if (Math.abs(local.x) > 4.38 || Math.abs(local.z) > 3.45) return base;
    const lab = ANCIENT_ECHOES_LANDMARKS.laboratory;
    return Math.max(base, this.terrain.sampleHeight(lab.x, lab.z) + 0.37);
  }

  public update(
    deltaSeconds: number,
    context: Readonly<{
      playerX: number;
      playerZ: number;
      playerHeading: number;
      playerSpeed: number;
    }>,
  ): void {
    if (!this.active) return;
    const wasEchoActive = this.model.isEchoActive();
    this.model.update(deltaSeconds);
    this.visualTime += Math.max(0, deltaSeconds);
    this.revealSeconds = Math.max(0, this.revealSeconds - deltaSeconds);
    const mechanos = this.visuals.get(ANCIENT_ECHOES_LANDMARKS.mechanos.id)?.root;
    if (mechanos) {
      if (this.model.mechanosPiloted) {
        mechanos.position.x = context.playerX;
        mechanos.position.y = this.terrain.sampleHeight(
          context.playerX,
          context.playerZ,
        );
        mechanos.position.z = context.playerZ;
        mechanos.rotation.y = context.playerHeading;
        const stride = this.visualTime * Math.min(8, 2.2 + context.playerSpeed * 2.6);
        mechanos.traverse((part) => {
          if (!part.name.includes('ancient-mechanos-leg-')) return;
          const side = part.name.endsWith('--1') ? -1 : 1;
          part.rotation.x = Math.sin(stride) * 0.16 * side;
        });
      } else {
        this.anchorLaboratoryObject(
          mechanos,
          ANCIENT_ECHOES_LANDMARKS.mechanos.x,
          ANCIENT_ECHOES_LANDMARKS.mechanos.z,
          ANCIENT_ECHOES_LANDMARKS.mechanos.heading,
        );
      }
    }
    if (wasEchoActive !== this.model.isEchoActive() || this.revealSeconds > 0) {
      this.synchronizePresentation(false);
    } else {
      this.updateGlow();
    }
  }

  public interactionCandidates(): readonly AncientEchoesInteractionCandidate[] {
    if (!this.active) return [];
    const candidates: AncientEchoesInteractionCandidate[] = [];
    if (
      THE_LONG_WINTER_FIRE_ROOT_ENABLED &&
      this.model.stage !== 'DORMANT'
    ) {
      for (const root of this.model.fireRoots) {
        if (root.stock <= 0) continue;
        candidates.push(this.candidate(root.id, root.x, root.z, 0.72, 2.25, 0.42));
      }
    }
    if (THE_LONG_WINTER_STONE_LAB_ENABLED) {
      const collapse = ANCIENT_ECHOES_LANDMARKS.collapse;
      if (!this.model.laboratoryOpen) {
        candidates.push(this.candidate(collapse.id, collapse.x, collapse.z, 1.45, 3.2, 0.9));
      }
      if (this.model.laboratoryOpen) {
        const bench = ANCIENT_ECHOES_LANDMARKS.bench;
        const planter = ANCIENT_ECHOES_LANDMARKS.planter;
        candidates.push(this.candidate(bench.id, bench.x, bench.z, 1, 2.8, 0.78));
        candidates.push(this.candidate(planter.id, planter.x, planter.z, 0.9, 2.6, 0.5));
        if (!this.model.weaponRecovered) {
          const weapon = ANCIENT_ECHOES_LANDMARKS.weapon;
          candidates.push(this.candidate(weapon.id, weapon.x, weapon.z, 0.7, 2.4, 0.95));
        }
      }
    }
    if (THE_LONG_WINTER_MECHANOS_ENABLED && this.model.laboratoryOpen) {
      const mechanos = ANCIENT_ECHOES_LANDMARKS.mechanos;
      candidates.push(this.candidate(mechanos.id, mechanos.x, mechanos.z, 1.25, 3.35, 1.9));
    }
    return candidates;
  }

  public resolveInteraction(
    playerX: number,
    playerZ: number,
    focusedTargetId?: string,
  ): AncientEchoesInteraction | undefined {
    if (!this.active) return undefined;
    const hasLivingFire = this.simulation.firePits.some((fire) =>
      fire.stage === 'LIT' && (fire.heatLevel ?? 0) > 0.08 &&
      Math.hypot(fire.x - playerX, fire.z - playerZ) <= 7.5);
    return this.model.resolveInteraction(playerX, playerZ, {
      focusedTargetId,
      hasLivingFire,
      flintToolCondition: this.simulation.toolCondition.flintTool,
    });
  }

  public perform(interaction: Readonly<AncientEchoesInteraction>): WildernessActionResult {
    const before = this.model.view();
    const result = this.model.perform(interaction, {
      consumeFlintUse: () => {
        this.simulation.toolCondition.flintTool = Math.max(
          0,
          this.simulation.toolCondition.flintTool - 1,
        );
      },
    });
    if (result.accepted) {
      this.revealSeconds = 0.65;
      this.synchronizePresentation(false);
      if (before.stage !== this.model.stage) {
        this.simulation.recordProgress('GATHER');
      }
    }
    return result;
  }

  public useFireRootExtract(): WildernessActionResult {
    const result = this.model.useExtract();
    if (result.accepted) {
      this.revealSeconds = 1.1;
      this.synchronizePresentation(false);
    }
    return result;
  }

  public grantPlaytestSupplies(): WildernessActionResult {
    this.simulation.inventory.fireRoot += 2;
    this.simulation.inventory.fireRootExtract += 1;
    return {
      accepted: true,
      message: 'PLAYTEST: 2 Fire-roots and 1 prepared extract added to the backpack.',
      tone: 'achievement',
    };
  }

  public dispose(): void {
    for (const visual of this.visuals.values()) {
      for (const material of visual.ownedMaterials) material.dispose();
    }
    this.visuals.clear();
    this.root.removeFromParent();
  }

  private createInitialVisuals(): void {
    if (THE_LONG_WINTER_FIRE_ROOT_ENABLED) {
      for (const root of this.model.fireRoots) this.createRootVisual(root.id, root.x, root.z);
    }
    if (THE_LONG_WINTER_STONE_LAB_ENABLED) {
      const lab = ANCIENT_ECHOES_LANDMARKS.laboratory;
      this.createVisual(lab.id, ANCIENT_PREFABS.laboratory, lab.x, lab.z, lab.heading);
      const collapse = ANCIENT_ECHOES_LANDMARKS.collapse;
      this.createVisual(collapse.id, ANCIENT_PREFABS.collapse, collapse.x, collapse.z, lab.heading);
      const bench = ANCIENT_ECHOES_LANDMARKS.bench;
      this.createVisual(bench.id, ANCIENT_PREFABS.bench, bench.x, bench.z, lab.heading);
      const planter = ANCIENT_ECHOES_LANDMARKS.planter;
      this.createVisual(planter.id, ANCIENT_PREFABS.planter, planter.x, planter.z, lab.heading);
      const weapon = ANCIENT_ECHOES_LANDMARKS.weapon;
      this.createVisual(weapon.id, ANCIENT_PREFABS.weapon, weapon.x, weapon.z, lab.heading);
    }
    if (THE_LONG_WINTER_MECHANOS_ENABLED) {
      const mechanos = ANCIENT_ECHOES_LANDMARKS.mechanos;
      this.createVisual(mechanos.id, ANCIENT_PREFABS.mechanos, mechanos.x, mechanos.z, mechanos.heading);
    }
  }

  private createRootVisual(id: string, x: number, z: number): void {
    if (this.visuals.has(id)) return;
    const visual = this.createVisual(id, ANCIENT_PREFABS.root, x, z, 0);
    visual?.root.scale.setScalar(0.82 + (id.length % 5) * 0.035);
  }

  private createVisual(
    id: string,
    prefabId: (typeof ANCIENT_PREFABS)[keyof typeof ANCIENT_PREFABS],
    x: number,
    z: number,
    heading: number,
  ): AncientVisual | undefined {
    const instance = this.assetBank?.createRuntimeInstance(prefabId);
    if (!instance) return undefined;
    instance.name = `${id} · asset-bank runtime`;
    const ownedMaterials: Material[] = [];
    const glowParts: Mesh[] = [];
    instance.traverse((object) => {
      if (!(object instanceof Mesh)) return;
      const cloned = Array.isArray(object.material)
        ? object.material.map((entry) => entry.clone())
        : object.material.clone();
      object.material = cloned;
      if (Array.isArray(cloned)) ownedMaterials.push(...cloned);
      else ownedMaterials.push(cloned);
      if (object.name.includes('ancient-echo')) glowParts.push(object);
    });
    this.anchor(instance, x, z, heading);
    this.root.add(instance);
    const visual = { root: instance, glowParts, ownedMaterials };
    this.visuals.set(id, visual);
    return visual;
  }

  private anchor(object: Object3D, x: number, z: number, heading = 0): void {
    object.position.set(x, this.terrain.sampleHeight(x, z), z);
    object.rotation.y = heading;
  }

  private synchronizePresentation(force: boolean): void {
    for (const root of this.model.fireRoots) {
      if (!this.visuals.has(root.id)) this.createRootVisual(root.id, root.x, root.z);
      const visual = this.visuals.get(root.id);
      if (!visual) continue;
      // Harvest removes rhizomes, never the living crown. A depleted plant
      // reads as a small sleeping crown and visibly grows back in place.
      visual.root.visible = true;
      const baseScale = 0.82 + (root.id.length % 5) * 0.035;
      const stockScale = root.stock <= 0 ? 0.56 : root.stock === 1 ? 0.78 : 1;
      visual.root.scale.set(
        baseScale * stockScale,
        baseScale * (0.58 + stockScale * 0.42),
        baseScale * stockScale,
      );
      this.anchor(visual.root, root.x, root.z);
    }
    const laboratory = this.visuals.get(ANCIENT_ECHOES_LANDMARKS.laboratory.id)?.root;
    const collapse = this.visuals.get(ANCIENT_ECHOES_LANDMARKS.collapse.id)?.root;
    const bench = this.visuals.get(ANCIENT_ECHOES_LANDMARKS.bench.id)?.root;
    const planter = this.visuals.get(ANCIENT_ECHOES_LANDMARKS.planter.id)?.root;
    const weapon = this.visuals.get(ANCIENT_ECHOES_LANDMARKS.weapon.id)?.root;
    const mechanos = this.visuals.get(ANCIENT_ECHOES_LANDMARKS.mechanos.id)?.root;
    if (laboratory) laboratory.visible = this.model.laboratoryOpen;
    if (collapse) {
      collapse.visible = !this.model.laboratoryOpen;
      collapse.traverse((object) => {
        if (!object.name.startsWith('ancient-rubble-')) return;
        const index = Number(object.name.slice('ancient-rubble-'.length));
        object.visible = Number.isFinite(index) &&
          index / 7 >= this.model.collapseProgress - 0.01;
      });
    }
    if (bench) bench.visible = this.model.laboratoryOpen;
    if (planter) planter.visible = this.model.laboratoryOpen;
    if (weapon) weapon.visible = this.model.laboratoryOpen && !this.model.weaponRecovered;
    if (mechanos) mechanos.visible = this.model.laboratoryOpen;
    const labHeading = ANCIENT_ECHOES_LANDMARKS.laboratory.heading;
    if (bench) this.anchorLaboratoryObject(
      bench,
      ANCIENT_ECHOES_LANDMARKS.bench.x,
      ANCIENT_ECHOES_LANDMARKS.bench.z,
      labHeading,
    );
    if (planter) this.anchorLaboratoryObject(
      planter,
      ANCIENT_ECHOES_LANDMARKS.planter.x,
      ANCIENT_ECHOES_LANDMARKS.planter.z,
      labHeading,
    );
    if (weapon) this.anchorLaboratoryObject(
      weapon,
      ANCIENT_ECHOES_LANDMARKS.weapon.x,
      ANCIENT_ECHOES_LANDMARKS.weapon.z,
      labHeading,
    );
    if (mechanos && !this.model.mechanosPiloted) this.anchorLaboratoryObject(
      mechanos,
      ANCIENT_ECHOES_LANDMARKS.mechanos.x,
      ANCIENT_ECHOES_LANDMARKS.mechanos.z,
      ANCIENT_ECHOES_LANDMARKS.mechanos.heading,
    );
    this.updateGlow(force);
  }

  private updateGlow(force = false): void {
    const echo = this.model.view().echoStrength;
    const pulse = 0.82 + Math.sin(this.visualTime * 2.1) * 0.18;
    for (const visual of this.visuals.values()) {
      for (const mesh of visual.glowParts) {
        const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
        for (const material of materials) {
          if (!(material instanceof MeshStandardMaterial)) continue;
          const visibleStrength = Math.max(0, echo * pulse);
          material.emissive.set(0xff7c35);
          material.emissiveIntensity = visibleStrength * 4.2;
          material.transparent = true;
          material.opacity = visibleStrength;
          material.depthWrite = material.opacity > 0.65;
          if (force) material.needsUpdate = true;
        }
      }
    }
  }

  private candidate(
    id: string,
    x: number,
    z: number,
    aimRadius: number,
    reach: number,
    height: number,
  ): AncientEchoesInteractionCandidate {
    return {
      id,
      x,
      y: this.terrain.sampleHeight(x, z) + height,
      z,
      aimRadius,
      reach,
    };
  }

  private anchorLaboratoryObject(
    object: Object3D,
    x: number,
    z: number,
    heading = 0,
  ): void {
    const lab = ANCIENT_ECHOES_LANDMARKS.laboratory;
    object.position.set(
      x,
      this.terrain.sampleHeight(lab.x, lab.z) + 0.37,
      z,
    );
    object.rotation.y = heading;
  }

  private labLocal(x: number, z: number): Readonly<{ x: number; z: number }> {
    const lab = ANCIENT_ECHOES_LANDMARKS.laboratory;
    const dx = x - lab.x;
    const dz = z - lab.z;
    const cosine = Math.cos(lab.heading);
    const sine = Math.sin(lab.heading);
    return {
      x: dx * cosine - dz * sine,
      z: dx * sine + dz * cosine,
    };
  }
}
