import {
  type ServerTick,
  type SessionEpoch,
  serverTick,
  sessionEpoch,
} from '../core/NetworkPrimitives';

export type AuthorityRehydrationDomain =
  | 'ENTITY'
  | 'SNOW'
  | 'ICE_CHUNKS'
  | 'ICE_FLOES'
  | 'WORLD'
  | 'CONSTRUCTION'
  | 'INVENTORY'
  | 'INFRASTRUCTURE';

export interface AuthorityStateHashFence {
  readonly players: string;
  readonly entities: string;
  readonly leases: string;
  readonly ingress: string;
  readonly combined: string;
}

export interface AuthorityRehydrationCompletePayload {
  readonly version: 1;
  readonly kind: 'AUTHORITY_REHYDRATION_COMPLETE';
  readonly previousSessionEpoch: SessionEpoch;
  readonly sessionEpoch: SessionEpoch;
  readonly serverTick: ServerTick;
  readonly domains: readonly AuthorityRehydrationDomain[];
  readonly stateHashes: AuthorityStateHashFence;
}

const DOMAINS = new Set<AuthorityRehydrationDomain>([
  'ENTITY',
  'SNOW',
  'ICE_CHUNKS',
  'ICE_FLOES',
  'WORLD',
  'CONSTRUCTION',
  'INVENTORY',
  'INFRASTRUCTURE',
]);
const HASH_KEYS = [
  'players',
  'entities',
  'leases',
  'ingress',
  'combined',
] as const;

const record = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const safeInteger = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
const hash = (value: unknown): value is string =>
  typeof value === 'string' && value.length > 0 && value.length <= 256;
const stateHashes = (value: unknown): value is Record<typeof HASH_KEYS[number], string> =>
  record(value) && HASH_KEYS.every((key) => hash(value[key]));

export const createAuthorityRehydrationComplete = (input: Readonly<{
  previousSessionEpoch: SessionEpoch;
  sessionEpoch: SessionEpoch;
  serverTick: ServerTick;
  domains: readonly AuthorityRehydrationDomain[];
  stateHashes: AuthorityStateHashFence;
}>): AuthorityRehydrationCompletePayload => ({
  version: 1,
  kind: 'AUTHORITY_REHYDRATION_COMPLETE',
  previousSessionEpoch: input.previousSessionEpoch,
  sessionEpoch: input.sessionEpoch,
  serverTick: input.serverTick,
  domains: [...new Set(input.domains)].sort(),
  stateHashes: { ...input.stateHashes },
});

export const validateAuthorityRehydrationCompletePayload = (
  input: unknown,
): AuthorityRehydrationCompletePayload | undefined => {
  if (
    !record(input) ||
    input.version !== 1 ||
    input.kind !== 'AUTHORITY_REHYDRATION_COMPLETE' ||
    !safeInteger(input.previousSessionEpoch) ||
    !safeInteger(input.sessionEpoch) ||
    input.sessionEpoch < input.previousSessionEpoch ||
    !safeInteger(input.serverTick) ||
    !Array.isArray(input.domains) ||
    input.domains.length > DOMAINS.size ||
    !input.domains.every((domain) => DOMAINS.has(domain as AuthorityRehydrationDomain)) ||
    new Set(input.domains).size !== input.domains.length ||
    !stateHashes(input.stateHashes)
  ) return undefined;
  return {
    version: 1,
    kind: 'AUTHORITY_REHYDRATION_COMPLETE',
    previousSessionEpoch: sessionEpoch(input.previousSessionEpoch),
    sessionEpoch: sessionEpoch(input.sessionEpoch),
    serverTick: serverTick(input.serverTick),
    domains: [...input.domains] as AuthorityRehydrationDomain[],
    stateHashes: {
      players: input.stateHashes.players as string,
      entities: input.stateHashes.entities as string,
      leases: input.stateHashes.leases as string,
      ingress: input.stateHashes.ingress as string,
      combined: input.stateHashes.combined as string,
    },
  };
};
