import {
  BoxGeometry,
  ConeGeometry,
  CylinderGeometry,
  Group,
  Mesh,
  MeshBasicMaterial,
  MeshStandardMaterial,
  PlaneGeometry,
  Scene,
  SphereGeometry,
  Vector3,
  type BufferGeometry,
  type Material,
  type Object3D,
} from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import type { MerchantShipPresentationState } from '../gameplay/simulation/MerchantShippingSystem';
import {
  OCEAN_SEA_LEVEL,
  type OceanField,
  type OceanSurfaceSample,
} from '../ocean/OceanField';
import { clamp, damp } from '../utils/math';

export interface MerchantVesselPresenterStats {
  visible: boolean;
  triangles: number;
  updateMs: number;
}

interface FadingMaterial {
  material: Material & {
    opacity: number;
    transparent: boolean;
  };
  baseOpacity: number;
}

const countTriangles = (geometry: BufferGeometry): number => {
  if (geometry.index) return geometry.index.count / 3;
  return (geometry.getAttribute('position')?.count ?? 0) / 3;
};

export class MerchantVesselPresenter {
  private readonly root = new Group();
  private readonly vessel = new Group();
  private readonly fadingMaterials: FadingMaterial[] = [];
  private readonly targetPosition = new Vector3();
  private readonly predictedPosition = new Vector3();
  private readonly visualPosition = new Vector3();
  private readonly surface: OceanSurfaceSample = {
    height: OCEAN_SEA_LEVEL,
    normalX: 0,
    normalY: 1,
    normalZ: 0,
  };
  private readonly oceanField: OceanField;
  private wakeMaterial?: MeshBasicMaterial;
  private snapshot?: MerchantShipPresentationState;
  private targetHeading = 0;
  private visualHeading = 0;
  private targetVisible = false;
  private previousTargetVisible = false;
  private fade = 0;
  private initialized = false;
  private snapshotAgeSeconds = 0;
  private triangles = 0;
  private lastUpdateMs = 0;
  private presentationEnabled = true;

  public constructor(scene: Scene, oceanField: OceanField) {
    this.oceanField = oceanField;
    this.root.name = 'Merchant vessel presentation';
    this.vessel.name = 'M/V Lumi';
    this.root.visible = false;
    this.createVessel();
    this.root.add(this.vessel);
    scene.add(this.root);
  }

  public setState(
    snapshot: Readonly<MerchantShipPresentationState>,
  ): void {
    const previousSnapshot = this.snapshot;
    const authoritativeStateChanged =
      !previousSnapshot ||
      Math.abs(
        previousSnapshot.worldPosition.x -
          snapshot.worldPosition.x,
      ) > 0.0001 ||
      Math.abs(
        previousSnapshot.worldPosition.z -
          snapshot.worldPosition.z,
      ) > 0.0001 ||
      Math.abs(previousSnapshot.heading - snapshot.heading) >
        0.0001 ||
      previousSnapshot.routeProgress !== snapshot.routeProgress ||
      previousSnapshot.speed !== snapshot.speed ||
      previousSnapshot.status !== snapshot.status ||
      previousSnapshot.routeId !== snapshot.routeId ||
      previousSnapshot.visible !== snapshot.visible ||
      previousSnapshot.simulationMode !== snapshot.simulationMode ||
      previousSnapshot.nearTransitionSequence !==
        snapshot.nearTransitionSequence;
    this.snapshot = {
      ...snapshot,
      worldPosition: { ...snapshot.worldPosition },
      cargo: snapshot.cargo ? { ...snapshot.cargo } : undefined,
    };
    const vesselScale =
      snapshot.shipDefinitionId === 'coastal-courier'
        ? 0.74
        : 1;
    this.vessel.scale.setScalar(vesselScale);
    this.vessel.name =
      snapshot.shipId === 'mv-kajo'
        ? 'M/V Kajo'
        : 'M/V Lumi';
    this.targetPosition.set(
      snapshot.worldPosition.x,
      snapshot.worldPosition.y,
      snapshot.worldPosition.z,
    );
    this.targetHeading = snapshot.heading;
    this.targetVisible = snapshot.visible;
    if (authoritativeStateChanged) {
      this.snapshotAgeSeconds = 0;
    }

    if (!this.initialized || (!this.previousTargetVisible && snapshot.visible)) {
      this.visualPosition.copy(this.targetPosition);
      this.visualHeading = this.targetHeading;
      this.initialized = true;
    }
    this.previousTargetVisible = snapshot.visible;
  }

  public update(
    deltaSeconds: number,
    worldTime: number,
    simulationRunning = true,
  ): void {
    const startedAt = performance.now();
    if (!this.presentationEnabled) {
      this.root.visible = false;
      this.lastUpdateMs = performance.now() - startedAt;
      return;
    }
    const delta = clamp(deltaSeconds, 0, 0.1);
    if (simulationRunning) {
      this.snapshotAgeSeconds = Math.min(
        2.5,
        this.snapshotAgeSeconds + delta,
      );
    }
    this.fade = damp(
      this.fade,
      this.targetVisible ? 1 : 0,
      this.targetVisible ? 4.5 : 3.2,
      delta,
    );
    this.root.visible = this.fade > 0.004;
    if (!this.root.visible || !this.initialized) {
      this.lastUpdateMs = performance.now() - startedAt;
      return;
    }

    const headingDelta = Math.atan2(
      Math.sin(this.targetHeading - this.visualHeading),
      Math.cos(this.targetHeading - this.visualHeading),
    );
    this.visualHeading +=
      headingDelta * (1 - Math.exp(-4.2 * delta));

    const predictionSpeed = this.targetVisible
      ? Math.max(0, this.snapshot?.speed ?? 0)
      : 0;
    this.predictedPosition.copy(this.targetPosition);
    this.predictedPosition.x +=
      Math.sin(this.targetHeading) *
      predictionSpeed *
      this.snapshotAgeSeconds;
    this.predictedPosition.z +=
      Math.cos(this.targetHeading) *
      predictionSpeed *
      this.snapshotAgeSeconds;
    if (simulationRunning && predictionSpeed > 0) {
      this.visualPosition.x +=
        Math.sin(this.visualHeading) * predictionSpeed * delta;
      this.visualPosition.z +=
        Math.cos(this.visualHeading) * predictionSpeed * delta;
    }
    this.visualPosition.lerp(
      this.predictedPosition,
      1 - Math.exp(-(predictionSpeed > 0 ? 3.2 : 4.8) * delta),
    );

    this.oceanField.sampleSurface(
      this.visualPosition.x,
      this.visualPosition.z,
      worldTime,
      0.82,
      this.surface,
    );
    this.root.position.set(
      this.visualPosition.x,
      this.surface.height + 0.13,
      this.visualPosition.z,
    );
    this.root.rotation.set(
      this.surface.normalZ * 0.16,
      this.visualHeading,
      -this.surface.normalX * 0.16,
    );

    for (const entry of this.fadingMaterials) {
      entry.material.opacity = entry.baseOpacity * this.fade;
    }
    if (this.wakeMaterial) {
      const speedRatio = clamp(
        (this.snapshot?.speed ?? 0) / 0.42,
        0,
        1,
      );
      this.wakeMaterial.opacity =
        0.14 * speedRatio * this.fade;
    }
    this.lastUpdateMs = performance.now() - startedAt;
  }

  public setPresentationEnabled(enabled: boolean): void {
    this.presentationEnabled = enabled;
    if (!enabled) this.root.visible = false;
  }

  public getStats(): MerchantVesselPresenterStats {
    return {
      visible: this.root.visible,
      triangles: this.triangles,
      updateMs: this.lastUpdateMs,
    };
  }

  public dispose(): void {
    this.root.removeFromParent();
    this.disposeObject(this.root);
    this.fadingMaterials.length = 0;
  }

  private createVessel(): void {
    const hull = this.standardMaterial(0x3d8294, 0.58, 0.1);
    const lowerHull = this.standardMaterial(0x275766, 0.64, 0.08);
    const deck = this.standardMaterial(0xf3e5c8, 0.76, 0.02);
    const cabin = this.standardMaterial(0xfff7df, 0.72, 0.02);
    const dark = this.standardMaterial(0x2c4650, 0.48, 0.16);
    const cargoOrange = this.standardMaterial(0xf18b55, 0.7, 0.04);
    const cargoYellow = this.standardMaterial(0xf4c85f, 0.72, 0.03);
    const light = this.standardMaterial(
      0xffe9a6,
      0.36,
      0.02,
      1,
      0xffb84d,
      1.8,
    );

    this.addMesh(
      new RoundedBoxGeometry(0.94, 0.34, 1.72, 2, 0.12),
      hull,
      0,
      0.2,
      -0.04,
    );
    const bow = this.addMesh(
      new ConeGeometry(0.48, 0.76, 4),
      hull,
      0,
      0.2,
      1.13,
    );
    bow.rotation.x = Math.PI / 2;
    bow.rotation.y = Math.PI / 4;
    this.addMesh(
      new BoxGeometry(0.78, 0.14, 1.58),
      lowerHull,
      0,
      0.02,
      -0.05,
    );
    this.addMesh(
      new BoxGeometry(0.78, 0.09, 1.5),
      deck,
      0,
      0.42,
      -0.08,
    );
    this.addMesh(
      new RoundedBoxGeometry(0.68, 0.5, 0.58, 2, 0.06),
      cabin,
      0,
      0.71,
      -0.48,
    );
    this.addMesh(
      new BoxGeometry(0.52, 0.16, 0.025),
      dark,
      0,
      0.76,
      -0.177,
    );
    this.addMesh(
      new BoxGeometry(0.31, 0.27, 0.52),
      cargoOrange,
      -0.19,
      0.59,
      0.28,
    );
    this.addMesh(
      new BoxGeometry(0.31, 0.27, 0.52),
      cargoYellow,
      0.19,
      0.59,
      0.28,
    );
    this.addMesh(
      new CylinderGeometry(0.025, 0.035, 0.53, 8),
      dark,
      0,
      1.16,
      -0.5,
    );
    this.addMesh(
      new SphereGeometry(0.055, 8, 6),
      light,
      0,
      1.45,
      -0.5,
    );

    const wakeMaterial = new MeshBasicMaterial({
      color: 0xe7fbff,
      transparent: true,
      opacity: 0,
      depthWrite: false,
    });
    this.wakeMaterial = wakeMaterial;
    const wake = new Mesh(
      new PlaneGeometry(0.72, 1.4),
      wakeMaterial,
    );
    wake.name = 'M/V Lumi bounded wake';
    wake.rotation.x = -Math.PI / 2;
    wake.position.set(0, -0.16, -1.42);
    this.vessel.add(wake);
    this.triangles += countTriangles(wake.geometry);
  }

  private standardMaterial(
    color: number,
    roughness: number,
    metalness: number,
    baseOpacity = 1,
    emissive = 0x000000,
    emissiveIntensity = 0,
  ): MeshStandardMaterial {
    const material = new MeshStandardMaterial({
      color,
      roughness,
      metalness,
      transparent: true,
      opacity: 0,
      emissive,
      emissiveIntensity,
    });
    this.fadingMaterials.push({ material, baseOpacity });
    return material;
  }

  private addMesh(
    geometry: BufferGeometry,
    material: Material,
    x: number,
    y: number,
    z: number,
  ): Mesh {
    const mesh = new Mesh(geometry, material);
    mesh.position.set(x, y, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.vessel.add(mesh);
    this.triangles += countTriangles(geometry);
    return mesh;
  }

  private disposeObject(object: Object3D): void {
    for (const child of [...object.children]) {
      this.disposeObject(child);
    }
    if (!(object instanceof Mesh)) return;
    object.geometry.dispose();
    const materials = Array.isArray(object.material)
      ? object.material
      : [object.material];
    for (const material of materials) material.dispose();
  }
}
