import { ShaderChunk, type Material } from 'three';
import type { PerformanceIsolation } from './PerformanceIsolation';
import type { IsolationRenderScope } from './ScenePerformanceIsolation';

type Domain = 'terrain' | 'snow';
const createUniforms = () => ({
  uIsolationSurfaceShading: { value: 1 },
  uIsolationShadowSampling: { value: 1 },
  uIsolationCloudShadow: { value: 1 },
});
// Scoped render-only values, shared by all LODs. No changes to weather,
// displacement, saved masks, ownership, wind or gameplay light intensities.
const uniforms = { terrain: createUniforms(), snow: createUniforms() };

export function installSurfacePerformanceIsolation(material: Material, domain: Domain): void {
  const compile = material.onBeforeCompile;
  const key = material.customProgramCacheKey.bind(material);
  material.onBeforeCompile = (shader, renderer) => {
    compile.call(material, shader, renderer);
    Object.assign(shader.uniforms, uniforms[domain]);
    // Skip the actual field evaluation, not just its final darkness multiplier.
    const cloud = (source: string): string => source.replace(
      /(float icewayWorldCloudShadow\s*\([^)]*\)\s*\{)/,
      'uniform float uIsolationCloudShadow;\n$1\nif (uIsolationCloudShadow < 0.5) return 0.0;',
    );
    shader.vertexShader = cloud(shader.vertexShader);
    shader.fragmentShader = cloud(shader.fragmentShader)
      .replace('#include <common>', '#include <common>\nuniform float uIsolationSurfaceShading;\nuniform float uIsolationShadowSampling;')
      .replace('#include <shadowmap_pars_fragment>', ShaderChunk.shadowmap_pars_fragment.replace(
        /(float get(?:Point)?Shadow\s*\([^)]*\)\s*\{)/g,
        '$1\nif (uIsolationShadowSampling < 0.5) return 1.0;',
      ))
      // Retain the original vertex shader, visibility/discard masks, alpha,
      // depth and texture colour. Only bypass the expensive normal/BRDF/crystal
      // fragment work. This is NOT a geometry replacement or a quality preset.
      .replace('#include <normal_fragment_begin>', `
if (uIsolationSurfaceShading < 0.5) {
  gl_FragColor = vec4(diffuseColor.rgb, diffuseColor.a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
  return;
}
#include <normal_fragment_begin>`);
  };
  material.customProgramCacheKey = () => `${key()}|surface-isolation-v1-${domain}`;
  material.needsUpdate = true;
}

export function applySurfacePerformanceIsolation(isolation: PerformanceIsolation, scope: IsolationRenderScope): void {
  for (const domain of ['terrain', 'snow'] as const) {
    const u = uniforms[domain];
    scope.set(u.uIsolationSurfaceShading, 'value', Number(isolation.enabled(`${domain}Shading`)));
    scope.set(u.uIsolationShadowSampling, 'value', Number(isolation.enabled(`${domain}ShadowSampling`)));
    scope.set(u.uIsolationCloudShadow, 'value', Number(isolation.enabled('cloudShadows') && isolation.enabled(`${domain}CloudShadows`)));
  }
}
