/**
 * Canonical animal vocabulary for The Long Winter.
 *
 * A species does not need an authored model before it can participate in the
 * world ecology. `assetStatus` is deliberately presentation metadata; diets,
 * population ranges and bonding rules remain usable by the coarse 8 km world
 * simulation and by tests long before an asset is promoted into the scene.
 */
export const WILDERNESS_ANIMAL_SPECIES_IDS = [
  'RABBIT',
  'ARCTIC_HARE',
  'DEER',
  'REINDEER',
  'MOOSE',
  'MUSK_OX',
  'BISON',
  'WILD_BOAR',
  'FOX',
  'ARCTIC_FOX',
  'LYNX',
  'WOLVERINE',
  'WOLF',
  'BEAR',
  'POLAR_BEAR',
  'STOAT',
  'OTTER',
  'BEAVER',
  'RAVEN',
  'CROW',
  'EAGLE',
  'SNOWY_OWL',
  'TIT',
  'PTARMIGAN',
  'SWAN',
  'SEAL',
  'WALRUS',
] as const;

export type WildernessAnimalSpecies =
  (typeof WILDERNESS_ANIMAL_SPECIES_IDS)[number];

export type WildernessAnimalDietTag =
  | 'BERRY'
  | 'ROOT'
  | 'FISH'
  | 'MEAT'
  | 'BARK'
  | 'SEED'
  | 'WATER';

export type WildernessAnimalTemperament =
  | 'GENTLE'
  | 'CAUTIOUS'
  | 'INDEPENDENT'
  | 'TERRITORIAL'
  | 'DANGEROUS';

export type WildernessAnimalDomain =
  | 'GROUND'
  | 'AERIAL'
  | 'SHORE'
  | 'AQUATIC';

export interface WildernessAnimalSpeciesDefinition {
  readonly id: WildernessAnimalSpecies;
  readonly displayName: string;
  readonly domain: WildernessAnimalDomain;
  readonly temperament: WildernessAnimalTemperament;
  readonly diet: readonly WildernessAnimalDietTag[];
  /** 0 is naturally trusting; 1 requires a long, careful relationship. */
  readonly wildness: number;
  /** Physical danger is separate from suspicion: a shy moose is still risky. */
  readonly danger: number;
  readonly sociality: number;
  readonly humanWariness: number;
  readonly settlementTolerance: number;
  readonly directCareDistance: number;
  readonly offeringNoticeRadius: number;
  readonly minimumCareEventsForBond: number;
  readonly minimumCareEventsForCompanion: number;
  readonly trustForBond: number;
  readonly trustForCompanion: number;
  readonly confidenceForCompanion: number;
  readonly presentationRadius: number;
  /** Nominal animals in a suitable 500 m population cell. */
  readonly backgroundDensity: number;
  readonly assetStatus: 'AUTHORED' | 'PLACEHOLDER' | 'DATA_ONLY';
  readonly notes: string;
}

type SpeciesSeed = Omit<
  WildernessAnimalSpeciesDefinition,
  | 'directCareDistance'
  | 'offeringNoticeRadius'
  | 'minimumCareEventsForBond'
  | 'minimumCareEventsForCompanion'
  | 'trustForBond'
  | 'trustForCompanion'
  | 'confidenceForCompanion'
  | 'presentationRadius'
> & Partial<Pick<
  WildernessAnimalSpeciesDefinition,
  | 'directCareDistance'
  | 'offeringNoticeRadius'
  | 'minimumCareEventsForBond'
  | 'minimumCareEventsForCompanion'
  | 'trustForBond'
  | 'trustForCompanion'
  | 'confidenceForCompanion'
  | 'presentationRadius'
>>;

const species = (seed: SpeciesSeed): WildernessAnimalSpeciesDefinition => {
  const difficulty = Math.max(0, Math.min(1, seed.wildness * 0.72 + seed.danger * 0.28));
  return Object.freeze({
    ...seed,
    directCareDistance: seed.directCareDistance ?? (1.9 + seed.sociality * 1.25),
    offeringNoticeRadius: seed.offeringNoticeRadius ?? (10 + seed.sociality * 5),
    minimumCareEventsForBond: seed.minimumCareEventsForBond ?? Math.round(3 + difficulty * 6),
    minimumCareEventsForCompanion: seed.minimumCareEventsForCompanion ?? Math.round(6 + difficulty * 13),
    trustForBond: seed.trustForBond ?? (0.42 + difficulty * 0.18),
    trustForCompanion: seed.trustForCompanion ?? (0.72 + difficulty * 0.19),
    confidenceForCompanion: seed.confidenceForCompanion ?? (0.5 + difficulty * 0.22),
    presentationRadius: seed.presentationRadius ?? (
      seed.domain === 'AERIAL' ? 300 : seed.danger > 0.7 ? 210 : 150
    ),
  });
};

