const DEFINITIONS = new Map(
  WILDERNESS_ANIMAL_CATALOG.map((definition) => [definition.id, definition]),
);

export const wildernessAnimalDefinition = (
  id: WildernessAnimalSpecies,
): WildernessAnimalSpeciesDefinition => DEFINITIONS.get(id)!;

export const wildernessAnimalDisplayName = (
  id: WildernessAnimalSpecies,
): string => wildernessAnimalDefinition(id).displayName;

export const isWildernessAnimalSpecies = (
  value: unknown,
): value is WildernessAnimalSpecies => typeof value === 'string' &&
  DEFINITIONS.has(value as WildernessAnimalSpecies);

export const isWildernessBirdSpecies = (
  speciesId: WildernessAnimalSpecies,
): boolean => wildernessAnimalDefinition(speciesId).domain === 'AERIAL';
