import { clamp } from '../utils/math';

export type SnowObstacleOwner =
  | 'TOWN'
  | 'PARK'
  | 'WORLD_ASSET'
  | 'TERRAIN'
  | 'GAMEPLAY';

export interface SnowObstacleDescriptor {
  readonly id: string;
  readonly owner: SnowObstacleOwner;
  readonly x: number;
  readonly z: number;
  readonly width: number;
  readonly depth: number;
  readonly height: number;
  readonly yawRadians?: number;
  /** 0 is a solid wall, 1 lets all wind-driven snow through. */
  readonly porosity?: number;
  /** Warm obstacles receive no persistent ground bank. */
  readonly warmth?: number;
  readonly snowCatch?: number;
}

export interface SnowObstacleDriftResult {
  readonly processed: number;
  readonly shaped: number;
  readonly movedSnow: number;
}

const SERVICE_INTERVAL_SECONDS = 0.2;
// Snow relocation settles a real 25 cm mass field. Two obstacles per service
// tick keep authored wind banks converging in the background without letting
// eight independent ridge operations monopolize one animation frame.
const SERVICE_BUDGET = 2;
const SPATIAL_CELL_METRES = 32;

const validDescriptor = (
  descriptor: Readonly<SnowObstacleDescriptor>,
): boolean =>
  descriptor.id.length > 0 &&
  [
    descriptor.x,
    descriptor.z,
    descriptor.width,
    descriptor.depth,
    descriptor.height,
  ].every(Number.isFinite) &&
  descriptor.width > 0 &&
  descriptor.depth > 0 &&
  descriptor.height > 0;

/**
 * One low-frequency drift contract for built-in and authored obstacles.
 *
 * The operation converges toward a stable leeward depth advantage. It never
 * creates snow: callers provide the canonical mass relocation function.
 */
export class SnowObstacleRegistry {
  private readonly descriptors = new Map<string, SnowObstacleDescriptor>();
  private orderedIds: readonly string[] = [];
  private cursor = 0;
  private accumulator = 0;
  private simulatedTime = 0;
  private readonly spatialIds = new Map<string, string[]>();
  private focusKey = '';
  private focusCandidates: readonly string[] = [];
  private activeDriftIds = new Set<string>();
  private readonly lastSimulatedTime = new Map<string, number>();

  public replaceOwner(
    owner: SnowObstacleOwner,
    descriptors: readonly Readonly<SnowObstacleDescriptor>[],
  ): void {
    for (const [id, descriptor] of this.descriptors) {
      if (descriptor.owner === owner) this.descriptors.delete(id);
    }
    for (const descriptor of descriptors) {
      if (descriptor.owner !== owner || !validDescriptor(descriptor)) continue;
      this.descriptors.set(descriptor.id, {
        ...descriptor,
        width: clamp(descriptor.width, 0.08, 80),
        depth: clamp(descriptor.depth, 0.08, 80),
        height: clamp(descriptor.height, 0.08, 80),
        yawRadians: descriptor.yawRadians ?? 0,
        porosity: clamp(descriptor.porosity ?? 0, 0, 1),
        warmth: clamp(descriptor.warmth ?? 0, 0, 1),
        snowCatch: clamp(descriptor.snowCatch ?? 1, 0, 2),
      });
    }
    this.rebuildOrder();
  }

  public upsert(descriptor: Readonly<SnowObstacleDescriptor>): boolean {
    if (!validDescriptor(descriptor)) return false;
    this.descriptors.set(descriptor.id, {
      ...descriptor,
      yawRadians: descriptor.yawRadians ?? 0,
      porosity: clamp(descriptor.porosity ?? 0, 0, 1),
      warmth: clamp(descriptor.warmth ?? 0, 0, 1),
      snowCatch: clamp(descriptor.snowCatch ?? 1, 0, 2),
    });
    this.rebuildOrder();
    return true;
  }

  public remove(id: string): boolean {
    const removed = this.descriptors.delete(id);
    if (removed) this.rebuildOrder();
    return removed;
  }

  public count(): number {
    return this.descriptors.size;
  }

  public list(): readonly Readonly<SnowObstacleDescriptor>[] {
    return this.orderedIds.flatMap((id) => {
      const descriptor = this.descriptors.get(id);
      return descriptor ? [{ ...descriptor }] : [];
    });
  }

  /**
   * Resolves a camera boom against the same low-cost authored obstacle
   * proxies that already shape windblown snow. This avoids raycasting the
   * complete rendered scene (and every instanced tree) on every frame.
   */
  public resolveCameraDistance(
    anchor: Readonly<{ x: number; y: number; z: number }>,
    desired: Readonly<{ x: number; y: number; z: number }>,
    sampleGroundHeight: (x: number, z: number) => number,
    paddingMetres = 0.16,
    includeObstacle: (
      obstacle: Readonly<SnowObstacleDescriptor>,
    ) => boolean = () => true,
  ): number {
    const deltaX = desired.x - anchor.x;
    const deltaY = desired.y - anchor.y;
    const deltaZ = desired.z - anchor.z;
    const fullDistance = Math.hypot(deltaX, deltaY, deltaZ);
    if (fullDistance <= 0.0001) return 0;
    let bestRatio = 1;
    const padding = clamp(paddingMetres, 0.04, 0.5);
    for (const obstacle of this.descriptors.values()) {
      if (!includeObstacle(obstacle)) continue;
      const yaw = obstacle.yawRadians ?? 0;
      const cosine = Math.cos(yaw);
      const sine = Math.sin(yaw);
      const originX = (anchor.x - obstacle.x) * cosine -
        (anchor.z - obstacle.z) * sine;
      const originZ = (anchor.x - obstacle.x) * sine +
        (anchor.z - obstacle.z) * cosine;
      const directionX = deltaX * cosine - deltaZ * sine;
      const directionZ = deltaX * sine + deltaZ * cosine;
      const ground = sampleGroundHeight(obstacle.x, obstacle.z);
      const minimum = {
        x: -obstacle.width * 0.5 - padding,
        y: ground - padding,
        z: -obstacle.depth * 0.5 - padding,
      };
      const maximum = {
        x: obstacle.width * 0.5 + padding,
        y: ground + obstacle.height + padding,
        z: obstacle.depth * 0.5 + padding,
      };
      let near = 0;
      let far = bestRatio;
      let missed = false;
      const axes = [
        [originX, directionX, minimum.x, maximum.x],
        [anchor.y, deltaY, minimum.y, maximum.y],
        [originZ, directionZ, minimum.z, maximum.z],
      ] as const;
      for (const [origin, direction, lower, upper] of axes) {
        if (Math.abs(direction) <= 0.000001) {
          if (origin < lower || origin > upper) missed = true;
          continue;
        }
        const inverse = 1 / direction;
        const first = (lower - origin) * inverse;
        const second = (upper - origin) * inverse;
        near = Math.max(near, Math.min(first, second));
        far = Math.min(far, Math.max(first, second));
        if (near > far) missed = true;
      }
      if (missed || far < 0 || near > bestRatio) continue;
      // When the actor is already inside a hollow structure proxy, the exit
      // plane represents its wall. Otherwise the entry plane is the blocker.
      const anchorInside = axes.every(([origin, , lower, upper]) =>
        origin >= lower && origin <= upper
      );
      const hitRatio = anchorInside ? far : Math.max(0, near);
      if (hitRatio <= 0.01) continue;
      bestRatio = Math.min(
        bestRatio,
        Math.max(0.26 / fullDistance, hitRatio - padding / fullDistance),
      );
    }
    return fullDistance * clamp(bestRatio, 0, 1);
  }

  public service(
    deltaSeconds: number,
    wind: Readonly<{ x: number; z: number; strength: number }>,
    sampleDepth: (x: number, z: number) => number,
    relocateSnow: (
      sourceX: number,
      sourceZ: number,
      destinationX: number,
      destinationZ: number,
      radius: number,
      maximumMass: number,
      maximumDepth: number,
      ridgeLength: number,
      ridgePoints: number,
    ) => number,
    focus?: Readonly<{ x: number; z: number; radius: number }>,
  ): SnowObstacleDriftResult {
    const delta = clamp(deltaSeconds, 0, 0.25);
    this.accumulator += delta;
    this.simulatedTime += delta;
    if (this.orderedIds.length === 0) {
      this.accumulator = 0;
      this.activeDriftIds.clear();
      return { processed: 0, shaped: 0, movedSnow: 0 };
    }
    if (this.accumulator < SERVICE_INTERVAL_SECONDS) return { processed: 0, shaped: 0, movedSnow: 0 };
    const elapsed = this.accumulator;
    this.accumulator = 0;
    const windLength = Math.hypot(wind.x, wind.z);
    const strength = clamp(wind.strength, 0, 2.8);
    if (windLength < 0.0001 || strength < 0.08) {
      this.activeDriftIds.clear();
      return { processed: 0, shaped: 0, movedSnow: 0 };
    }
    const windX = wind.x / windLength;
    const windZ = wind.z / windLength;
    const eligible = this.candidatesNear(focus).filter((id) => {
      const obstacle = this.descriptors.get(id)!;
      return (obstacle.warmth ?? 0) < 0.72 && (!focus ||
        (obstacle.x - focus.x) ** 2 + (obstacle.z - focus.z) ** 2 <= focus.radius ** 2);
    });
    for (const id of eligible) {
      if (!this.activeDriftIds.has(id)) this.lastSimulatedTime.set(id, this.simulatedTime - elapsed);
    }
    this.activeDriftIds = new Set(eligible);
    let processed = 0;
    let shaped = 0;
    let movedSnow = 0;
    for (
      let serviced = 0;
      serviced < Math.min(SERVICE_BUDGET, eligible.length);
      serviced += 1
    ) {
      const id = eligible[this.cursor % eligible.length]!;
      this.cursor = (this.cursor + 1) % eligible.length;
      const obstacle = this.descriptors.get(id)!;
      const debt = Math.max(0, this.simulatedTime - this.lastSimulatedTime.get(id)!);
      const obstacleDelta = Math.min(debt, 1);
      this.lastSimulatedTime.set(id, this.simulatedTime - debt + obstacleDelta);
      processed += 1;
      const yaw = obstacle.yawRadians ?? 0;
      const localWindX = windX * Math.cos(yaw) - windZ * Math.sin(yaw);
      const localWindZ = windX * Math.sin(yaw) + windZ * Math.cos(yaw);
      const projectedSpan =
        Math.abs(localWindX) * obstacle.width +
        Math.abs(localWindZ) * obstacle.depth;
      const crosswindSpan = Math.abs(localWindZ) * obstacle.width +
        Math.abs(localWindX) * obstacle.depth;
      const footprint = clamp(
        Math.max(0.15, projectedSpan, crosswindSpan),
        0.15,
        18,
      );
      const porosity = clamp(obstacle.porosity ?? 0, 0, 1);
      const catchStrength = clamp(obstacle.snowCatch ?? 1, 0, 2);
      const slenderObstacle = footprint < 0.7;
      const targetLeeAdvantage = clamp(
        (0.035 + obstacle.height * 0.027 + footprint * 0.012) *
          strength * (1 - porosity * 0.82) * catchStrength,
        0.025,
        slenderObstacle ? 0.24 : 0.72,
      );
      // A sub-grid pole cannot form a stable radial mound on a 25 cm field.
      // Give every obstacle a multi-sample footprint and trail it downwind,
      // yielding one broad low ridge rather than repeatedly feeding one peak.
      const radius = clamp(
        footprint * (slenderObstacle ? 1.6 : 0.3),
        slenderObstacle ? 0.52 : 0.68,
        1.75,
      );
      const offset = projectedSpan * 0.5 + radius * 0.42;
      const sourceX = obstacle.x - windX * offset;
      const sourceZ = obstacle.z - windZ * offset;
      const destinationX = obstacle.x + windX * offset;
      const destinationZ = obstacle.z + windZ * offset;
      const sourceDepth = sampleDepth(sourceX, sourceZ);
      const destinationDepth = sampleDepth(destinationX, destinationZ);
      const deficit = targetLeeAdvantage - (destinationDepth - sourceDepth);
      if (deficit <= 0.016 || sourceDepth <= 0.075) {
        this.lastSimulatedTime.set(id, this.simulatedTime);
        continue;
      }
      const request = Math.min(
        slenderObstacle ? 0.28 : 1.8,
        deficit * Math.PI * radius * radius * 0.5 *
          (obstacleDelta / SERVICE_INTERVAL_SECONDS),
      );
      const ridgePoints = slenderObstacle ? 3 : 4;
      const ridgeLength = clamp(
        footprint * 0.18 + obstacle.height * 0.075,
        0.45,
        2.2,
      );
      const bankCap = Math.max(sourceDepth, destinationDepth) +
        targetLeeAdvantage * 1.06;
      const moved = clamp(
        relocateSnow(
          sourceX,
          sourceZ,
          destinationX,
          destinationZ,
          radius,
          request,
          bankCap,
          ridgeLength,
          ridgePoints,
        ),
        0,
        request,
      );
      if (moved <= 0.00001) continue;
      shaped += 1;
      movedSnow += moved;
    }
    return { processed, shaped, movedSnow };
  }

  private rebuildOrder(): void {
    this.orderedIds = [...this.descriptors.keys()].sort();
    this.focusKey = '';
    this.spatialIds.clear();
    for (const id of this.orderedIds) {
      const obstacle = this.descriptors.get(id)!;
      const key = `${Math.floor(obstacle.x / SPATIAL_CELL_METRES)},${Math.floor(obstacle.z / SPATIAL_CELL_METRES)}`;
      const ids = this.spatialIds.get(key);
      if (ids) ids.push(id);
      else this.spatialIds.set(key, [id]);
    }
    for (const id of this.lastSimulatedTime.keys()) {
      if (!this.descriptors.has(id)) this.lastSimulatedTime.delete(id);
    }
    this.cursor = this.orderedIds.length > 0
      ? this.cursor % this.orderedIds.length
      : 0;
  }

  private candidatesNear(focus?: Readonly<{ x: number; z: number; radius: number }>): readonly string[] {
    if (!focus) return this.orderedIds;
    const minX = Math.floor((focus.x - focus.radius) / SPATIAL_CELL_METRES);
    const maxX = Math.floor((focus.x + focus.radius) / SPATIAL_CELL_METRES);
    const minZ = Math.floor((focus.z - focus.radius) / SPATIAL_CELL_METRES);
    const maxZ = Math.floor((focus.z + focus.radius) / SPATIAL_CELL_METRES);
    const key = `${minX},${maxX},${minZ},${maxZ}`;
    if (key !== this.focusKey) {
      const ids: string[] = [];
      for (let z = minZ; z <= maxZ; z += 1) {
        for (let x = minX; x <= maxX; x += 1) ids.push(...this.spatialIds.get(`${x},${z}`) ?? []);
      }
      this.focusCandidates = ids;
      this.focusKey = key;
    }
    return this.focusCandidates;
  }
}
