import type { AtmosphereGroundingQuality } from '../rendering/SphericalWorldOverlay';

export const LONG_WINTER_BASE_PIXEL_RATIO = 1.25;
export const LONG_WINTER_SNOW_PIXEL_RATIO = 1.1;
export const LONG_WINTER_SNOW_PARTICLE_MULTIPLIER = 0.65;
export const LONG_WINTER_SNOW_RESOLUTION_ENTER = 0.55;
export const LONG_WINTER_SNOW_RESOLUTION_EXIT = 0.25;

export const resolveLongWinterDenseSnow = (
  currentlyDense: boolean,
  snowfallIntensity: number,
): boolean => currentlyDense
  ? snowfallIntensity > LONG_WINTER_SNOW_RESOLUTION_EXIT
  : snowfallIntensity >= LONG_WINTER_SNOW_RESOLUTION_ENTER;

export const resolveLongWinterPixelRatio = (
  platformMaximum: number,
  active: boolean,
  denseSnow: boolean,
): number => Math.min(
  platformMaximum,
  active
    ? denseSnow
      ? LONG_WINTER_SNOW_PIXEL_RATIO
      : LONG_WINTER_BASE_PIXEL_RATIO
    : platformMaximum,
);

/**
 * HIGH and ULTRA enable the bloom chain. The Long Winter keeps its atmosphere
 * grade, but caps that presentation at MEDIUM so snow overdraw is not followed
 * by a multi-target bloom pass.
 */
export const resolveLongWinterAtmosphereQuality = (
  requested: AtmosphereGroundingQuality,
  active: boolean,
): AtmosphereGroundingQuality => active && (
  requested === 'HIGH' || requested === 'ULTRA'
)
  ? 'MEDIUM'
  : requested;
