import { clamp } from '../../utils/math';

export type AncientEchoesStage =
  | 'DORMANT'
  | 'LAB_FOUND'
  | 'FIRE_ROOT_FOUND'
  | 'EXTRACT_BREWED'
  | 'ECHO_SEEN'
  | 'SEAL_OPEN'
  | 'LAB_AWAKENED'
  | 'MECHANOS_ATTUNED';

export type AncientEchoesInteractionKind =
  | 'DISCOVER_LAB'
  | 'EXCAVATE_COLLAPSE'
  | 'HARVEST_FIRE_ROOT'
  | 'BREW_FIRE_ROOT_EXTRACT'
  | 'DRINK_FIRE_ROOT_EXTRACT'
  | 'OPEN_ECHO_SEAL'
  | 'RECOVER_ANCIENT_WEAPON'
  | 'ATTUNE_MECHANOS'
  | 'ENTER_MECHANOS'
  | 'LEAVE_MECHANOS'
  | 'TRANSPLANT_FIRE_ROOT';

export interface AncientEchoesInventory {
  fireRoot: number;
  fireRootExtract: number;
  ancientMetal: number;
  ancientWeapon: number;
}

export interface AncientFireRootPatchState {
  readonly id: string;
  readonly x: number;
  readonly z: number;
  stock: number;
  regrowSeconds: number;
  transplanted: boolean;
}

export interface AncientEchoesSaveData {
  readonly version: 1;
  readonly stage: AncientEchoesStage;
  readonly collapseProgress: number;
  readonly echoSecondsRemaining: number;
  readonly echoExposure: number;
  readonly laboratoryOpen: boolean;
  readonly laboratoryAwake: boolean;
  readonly weaponRecovered: boolean;
  readonly mechanosAttunement: number;
  readonly mechanosAttuned: boolean;
  readonly mechanosPiloted: boolean;
  readonly fireRoots: readonly Readonly<AncientFireRootPatchState>[];
}

export interface AncientEchoesInteraction {
  readonly kind: AncientEchoesInteractionKind;
  readonly targetId: string;
  readonly label: string;
  readonly enabled: boolean;
  readonly x: number;
  readonly z: number;
  readonly requiresTool?: 'HANDS' | 'FLINT_TOOL';
}

export interface AncientEchoesActionResult {
  readonly accepted: boolean;
  readonly message: string;
  readonly tone?: 'achievement';
}

export interface AncientEchoesView {
  readonly enabled: boolean;
  readonly stage: AncientEchoesStage;
  readonly stageName: string;
  readonly objective: string;
  readonly progress: number;
  readonly echoActive: boolean;
  readonly echoSecondsRemaining: number;
  readonly echoStrength: number;
  readonly mechanosAttuned: boolean;
  readonly mechanosPiloted: boolean;
  readonly collapseProgress: number;
  readonly laboratoryOpen: boolean;
  readonly laboratoryAwake: boolean;
}

