export const ANCIENT_FIRE_ROOT_PATCHES: readonly Readonly<
  Pick<AncientFireRootPatchState, 'id' | 'x' | 'z'>
>[] = [
  { id: 'fire-root-west-1', x: -867.4, z: -245.8 },
  { id: 'fire-root-west-2', x: -870.1, z: -243.9 },
  { id: 'fire-root-west-3', x: -872.2, z: -247.1 },
  { id: 'fire-root-west-4', x: -869.5, z: -249.4 },
] as const;

const FIRE_ROOT_REGROW_SECONDS = 8 * 60;
export const FIRE_ROOT_EXTRACT_SECONDS = 180;

const stageOrder: readonly AncientEchoesStage[] = [
  'DORMANT',
  'LAB_FOUND',
  'FIRE_ROOT_FOUND',
  'EXTRACT_BREWED',
  'ECHO_SEEN',
  'SEAL_OPEN',
  'LAB_AWAKENED',
  'MECHANOS_ATTUNED',
];

const stageAtLeast = (
  current: AncientEchoesStage,
  target: AncientEchoesStage,
): boolean => stageOrder.indexOf(current) >= stageOrder.indexOf(target);

const stageName = (stage: AncientEchoesStage): string => ({
  DORMANT: 'A silence under stone',
  LAB_FOUND: 'The buried laboratory',
  FIRE_ROOT_FOUND: 'A root that remembers fire',
  EXTRACT_BREWED: 'The first extraction',
  ECHO_SEEN: 'The world beneath the world',
  SEAL_OPEN: 'A door without hinges',
  LAB_AWAKENED: 'The old instruments breathe',
  MECHANOS_ATTUNED: 'A thought inside metal',
})[stage];

const createRoots = (): AncientFireRootPatchState[] =>
  ANCIENT_FIRE_ROOT_PATCHES.map((patch) => ({
    ...patch,
    stock: 2,
    regrowSeconds: 0,
    transplanted: false,
  }));

const normalizeInventory = (inventory: AncientEchoesInventory): void => {
  inventory.fireRoot = Math.max(0, Math.floor(inventory.fireRoot || 0));
  inventory.fireRootExtract = Math.max(
    0,
    Math.floor(inventory.fireRootExtract || 0),
  );
  inventory.ancientMetal = Math.max(
    0,
    Math.floor(inventory.ancientMetal || 0),
  );
  inventory.ancientWeapon = Math.max(
    0,
    Math.floor(inventory.ancientWeapon || 0),
  );
};

/**
 * Pure authority for the entire feature island. Rendering and input adapters
 * may disappear without invalidating the base wilderness save.
 */
export class AncientEchoesModel {
  public stage: AncientEchoesStage = 'DORMANT';
  public collapseProgress = 0;
  public echoSecondsRemaining = 0;
  public echoExposure = 0;
  public laboratoryOpen = false;
  public laboratoryAwake = false;
  public weaponRecovered = false;
  public mechanosAttunement = 0;
  public mechanosAttuned = false;
  public mechanosPiloted = false;
  public readonly fireRoots = createRoots();

  public constructor(
    private readonly inventory: AncientEchoesInventory,
    saved?: Readonly<AncientEchoesSaveData>,
  ) {
    normalizeInventory(inventory);
    if (saved) this.importState(saved);
  }

  public isEchoActive(): boolean {
    return this.echoSecondsRemaining > 0.001;
  }

  public update(deltaSeconds: number): void {
    // The authority normally receives frame-sized deltas, but accepting a
    // larger bounded step keeps timers coherent after a suspended tab and in
    // deterministic save/test catch-up. Presentation smoothing remains in the
    // adapter and is never advanced by this value.
    const delta = clamp(deltaSeconds, 0, 600);
    if (delta <= 0) return;
    this.echoSecondsRemaining = Math.max(
      0,
      this.echoSecondsRemaining - delta,
    );
    const targetExposure = this.isEchoActive() ? 1 : 0;
    this.echoExposure += (targetExposure - this.echoExposure) *
      (1 - Math.exp(-delta * (targetExposure > 0 ? 2.5 : 1.25)));
    if (!this.isEchoActive()) this.mechanosPiloted = false;
    for (const root of this.fireRoots) {
      if (root.stock > 0 || root.regrowSeconds <= 0) continue;
      root.regrowSeconds = Math.max(0, root.regrowSeconds - delta);
      if (root.regrowSeconds <= 0) root.stock = root.transplanted ? 3 : 2;
    }
  }

  public resolveInteraction(
    playerX: number,
    playerZ: number,
    context: Readonly<{
      focusedTargetId?: string;
      hasLivingFire: boolean;
      flintToolCondition: number;
    }>,
  ): AncientEchoesInteraction | undefined {
    const focus = context.focusedTargetId;
    const within = (id: string, x: number, z: number, radius: number): boolean =>
      Math.hypot(playerX - x, playerZ - z) <= radius && (!focus || focus === id);

    if (this.mechanosPiloted) {
      return {
        kind: 'LEAVE_MECHANOS',
        targetId: ANCIENT_ECHOES_LANDMARKS.mechanos.id,
        label: 'RELEASE YOUR THOUGHT FROM MECHANOS',
        enabled: true,
        x: playerX,
        z: playerZ,
        requiresTool: 'HANDS',
      };
    }

    if (stageAtLeast(this.stage, 'LAB_FOUND')) {
      for (const root of this.fireRoots) {
        if (!within(root.id, root.x, root.z, 2.25)) continue;
        return {
          kind: 'HARVEST_FIRE_ROOT',
          targetId: root.id,
          label: root.stock > 0
            ? 'LIFT ONE FIRE-ROOT RHIZOME · LEAVE THE CROWN ALIVE'
            : `THE ROOT SLEEPS · ${Math.ceil(root.regrowSeconds)}s`,
          enabled: root.stock > 0,
          x: root.x,
          z: root.z,
          requiresTool: 'HANDS',
        };
      }
    }

    const collapse = ANCIENT_ECHOES_LANDMARKS.collapse;
    if (within(collapse.id, collapse.x, collapse.z, 3.1)) {
      if (this.stage === 'DORMANT') {
        return {
          kind: 'DISCOVER_LAB', targetId: collapse.id,
          label: 'READ THE MARKS BENEATH THE COLLAPSED ARCH', enabled: true,
          x: collapse.x, z: collapse.z, requiresTool: 'HANDS',
        };
      }
      if (this.collapseProgress < 1) {
        return {
          kind: 'EXCAVATE_COLLAPSE', targetId: collapse.id,
          label: context.flintToolCondition > 0
            ? `PRY LOOSE THE COLLAPSE · ${Math.round(this.collapseProgress * 100)}%`
            : 'THE FLINT EDGE NEEDS REPAIR',
          enabled: context.flintToolCondition > 0,
          x: collapse.x, z: collapse.z, requiresTool: 'FLINT_TOOL',
        };
      }
      if (!this.laboratoryOpen) {
        return {
          kind: 'OPEN_ECHO_SEAL', targetId: collapse.id,
          label: this.isEchoActive()
            ? 'PLACE YOUR HAND IN THE GLOWING SEAM'
            : 'THE STONE HAS NO SEAM IN THIS WORLD',
          enabled: this.isEchoActive(), x: collapse.x, z: collapse.z,
          requiresTool: 'HANDS',
        };
      }
    }

    const bench = ANCIENT_ECHOES_LANDMARKS.bench;
    if (
      this.laboratoryOpen &&
      within(bench.id, bench.x, bench.z, 2.7)
    ) {
      const enabled = this.inventory.fireRoot >= 2;
      return {
        kind: 'BREW_FIRE_ROOT_EXTRACT', targetId: bench.id,
        label: enabled
          ? 'DISTIL FIRE-ROOT IN THE STONE RETORT · 2 ROOTS'
          : 'THE RETORT NEEDS 2 FIRE-ROOT RHIZOMES',
        enabled, x: bench.x, z: bench.z, requiresTool: 'HANDS',
      };
    }

    const weapon = ANCIENT_ECHOES_LANDMARKS.weapon;
    if (
      this.laboratoryOpen && !this.weaponRecovered &&
      within(weapon.id, weapon.x, weapon.z, 2.3)
    ) {
      return {
        kind: 'RECOVER_ANCIENT_WEAPON', targetId: weapon.id,
        label: this.isEchoActive()
          ? 'LIFT THE ECHO-BLADE FROM ITS STONE CRADLE'
          : 'THE EMPTY CRADLE HUMS BEYOND SIGHT',
        enabled: this.isEchoActive(), x: weapon.x, z: weapon.z,
        requiresTool: 'HANDS',
      };
    }

    const planter = ANCIENT_ECHOES_LANDMARKS.planter;
    if (
      this.laboratoryOpen &&
      within(planter.id, planter.x, planter.z, 2.5)
    ) {
      const hasTransplant = this.fireRoots.some((root) => root.transplanted);
      const enabled = !hasTransplant && this.inventory.fireRoot >= 1;
      return {
        kind: 'TRANSPLANT_FIRE_ROOT', targetId: planter.id,
        label: hasTransplant
          ? 'THE TRANSPLANTED FIRE-ROOT HOLDS TO THE WARM STONE'
          : enabled
            ? 'TRANSPLANT ONE FIRE-ROOT INTO THE WARM BED'
            : 'BRING A LIVING FIRE-ROOT RHIZOME',
        enabled, x: planter.x, z: planter.z, requiresTool: 'HANDS',
      };
    }

    const mechanos = ANCIENT_ECHOES_LANDMARKS.mechanos;
    if (
      this.laboratoryOpen &&
      within(mechanos.id, mechanos.x, mechanos.z, 3.2)
    ) {
      if (!this.mechanosAttuned) {
        return {
          kind: 'ATTUNE_MECHANOS', targetId: mechanos.id,
          label: this.isEchoActive()
            ? `HOLD ONE THOUGHT STEADY · ${Math.round(this.mechanosAttunement * 100)}%`
            : 'MEKANOS IS ONLY SILHOUETTE · DRINK THE EXTRACT',
          enabled: this.isEchoActive(), x: mechanos.x, z: mechanos.z,
          requiresTool: 'HANDS',
        };
      }
      return {
        kind: 'ENTER_MECHANOS', targetId: mechanos.id,
        label: this.isEchoActive()
          ? 'CENTRE YOUR THOUGHT INSIDE MEKANOS'
          : 'THE THOUGHT-BRIDGE IS SILENT',
        enabled: this.isEchoActive(), x: mechanos.x, z: mechanos.z,
        requiresTool: 'HANDS',
      };
    }

    if (
      this.inventory.fireRoot >= 2 &&
      context.hasLivingFire &&
      this.collapseProgress >= 1 &&
      !this.laboratoryOpen
    ) {
      return {
        kind: 'BREW_FIRE_ROOT_EXTRACT', targetId: 'ancient-field-retort',
        label: 'STEEP 2 FIRE-ROOTS BESIDE THE LIVING FIRE', enabled: true,
        x: playerX, z: playerZ, requiresTool: 'HANDS',
      };
    }
    return undefined;
  }

  public useExtract(): AncientEchoesActionResult {
    if (this.inventory.fireRootExtract <= 0) {
      return { accepted: false, message: 'No fire-root extract remains.' };
    }
    if (this.isEchoActive()) {
      return {
        accepted: false,
        message: 'The first dose is still carrying your sight. Wait before taking another.',
      };
    }
    this.inventory.fireRootExtract -= 1;
    this.echoSecondsRemaining = FIRE_ROOT_EXTRACT_SECONDS;
    this.echoExposure = Math.max(this.echoExposure, 0.08);
    this.advanceTo('ECHO_SEEN');
    return {
      accepted: true,
      message: 'Warmth crosses the tongue. The world drains to sepia—and old metal begins to burn with light.',
      tone: 'achievement',
    };
  }

  public perform(
    interaction: Readonly<AncientEchoesInteraction>,
    context: Readonly<{ consumeFlintUse: () => void }>,
  ): AncientEchoesActionResult {
    if (!interaction.enabled) {
      return { accepted: false, message: interaction.label };
    }
    switch (interaction.kind) {
      case 'DISCOVER_LAB':
        this.advanceTo('LAB_FOUND');
        return {
          accepted: true,
          message: 'The arch is not a ruin. A fitted stone door lies beneath the collapse, marked with a root and an open eye.',
          tone: 'achievement',
        };
      case 'EXCAVATE_COLLAPSE':
        context.consumeFlintUse();
        this.collapseProgress = clamp(this.collapseProgress + 0.2, 0, 1);
        return {
          accepted: true,
          message: this.collapseProgress >= 1
            ? 'The last slab rolls free. Under it waits seamless black stone.'
            : 'Stone and frozen soil give way without turning the work into a cave simulation.',
          ...(this.collapseProgress >= 1 ? { tone: 'achievement' as const } : {}),
        };
      case 'HARVEST_FIRE_ROOT': {
        const root = this.fireRoots.find((entry) =>
          entry.id === interaction.targetId);
        if (!root || root.stock <= 0) break;
        root.stock -= 1;
        if (root.stock <= 0) root.regrowSeconds = FIRE_ROOT_REGROW_SECONDS;
        this.inventory.fireRoot += 1;
        this.advanceTo('FIRE_ROOT_FOUND');
        return {
          accepted: true,
          message: 'One ember-red rhizome comes free. The crown remains rooted beneath the snow.',
          tone: 'achievement',
        };
      }
      case 'BREW_FIRE_ROOT_EXTRACT':
        if (this.inventory.fireRoot < 2) break;
        this.inventory.fireRoot -= 2;
        this.inventory.fireRootExtract += 1;
        this.advanceTo('EXTRACT_BREWED');
        return {
          accepted: true,
          message: 'The bitter root becomes one dose of amber extract. Open the backpack and drink it when you are ready.',
          tone: 'achievement',
        };
      case 'DRINK_FIRE_ROOT_EXTRACT':
        return this.useExtract();
      case 'OPEN_ECHO_SEAL':
        if (!this.isEchoActive()) break;
        this.laboratoryOpen = true;
        this.inventory.ancientMetal += 1;
        this.advanceTo('SEAL_OPEN');
        return {
          accepted: true,
          message: 'The glowing seam unfolds into a doorway. A loose shard of primal metal answers your pulse.',
          tone: 'achievement',
        };
      case 'RECOVER_ANCIENT_WEAPON':
        if (!this.isEchoActive() || this.weaponRecovered) break;
        this.weaponRecovered = true;
        this.inventory.ancientWeapon += 1;
        this.inventory.ancientMetal += 1;
        this.laboratoryAwake = true;
        this.advanceTo('LAB_AWAKENED');
        return {
          accepted: true,
          message: 'The Echo-blade has almost no weight here. In the ordinary world, it is only cold air in your hand.',
          tone: 'achievement',
        };
      case 'ATTUNE_MECHANOS':
        if (!this.isEchoActive()) break;
        this.mechanosAttunement = clamp(
          this.mechanosAttunement + 0.34,
          0,
          1,
        );
        if (this.mechanosAttunement >= 1) {
          this.mechanosAttuned = true;
          this.laboratoryAwake = true;
          this.advanceTo('MECHANOS_ATTUNED');
          return {
            accepted: true,
            message: 'Mekanos answers without lever or saddle. It has learned the shape of one deliberate thought.',
            tone: 'achievement',
          };
        }
        return {
          accepted: true,
          message: 'The metal moves a fraction after your thought—not after your hand.',
        };
      case 'ENTER_MECHANOS':
        if (!this.mechanosAttuned || !this.isEchoActive()) break;
        this.mechanosPiloted = true;
        return {
          accepted: true,
          message: 'WASD no longer feels like movement. It feels like intention—and Mekanos obeys.',
          tone: 'achievement',
        };
      case 'LEAVE_MECHANOS':
        this.mechanosPiloted = false;
        return {
          accepted: true,
          message: 'You release the thought. Ancient limbs settle into the snow.',
        };
      case 'TRANSPLANT_FIRE_ROOT': {
        if (this.inventory.fireRoot < 1) break;
        const source = this.fireRoots.find((root) => !root.transplanted);
        if (!source) break;
        this.inventory.fireRoot -= 1;
        this.fireRoots.push({
          id: 'fire-root-laboratory-bed',
          x: ANCIENT_ECHOES_LANDMARKS.planter.x,
          z: ANCIENT_ECHOES_LANDMARKS.planter.z,
          stock: 0,
          regrowSeconds: 150,
          transplanted: true,
        });
        return {
          accepted: true,
          message: 'The rhizome accepts the old warm bed. Its first cultivated crown will grow here without becoming a factory timer.',
          tone: 'achievement',
        };
      }
    }
    return { accepted: false, message: 'The old mechanism does not answer.' };
  }

  public view(): AncientEchoesView {
    const objective = this.objective();
    return {
      enabled: true,
      stage: this.stage,
      stageName: stageName(this.stage),
      objective: objective.detail,
      progress: objective.progress,
      echoActive: this.isEchoActive(),
      echoSecondsRemaining: this.echoSecondsRemaining,
      echoStrength: clamp(this.echoExposure, 0, 1),
      mechanosAttuned: this.mechanosAttuned,
      mechanosPiloted: this.mechanosPiloted,
      collapseProgress: this.collapseProgress,
      laboratoryOpen: this.laboratoryOpen,
      laboratoryAwake: this.laboratoryAwake,
    };
  }

  public exportState(): AncientEchoesSaveData {
    return {
      version: 1,
      stage: this.stage,
      collapseProgress: this.collapseProgress,
      echoSecondsRemaining: this.echoSecondsRemaining,
      echoExposure: this.echoExposure,
      laboratoryOpen: this.laboratoryOpen,
      laboratoryAwake: this.laboratoryAwake,
      weaponRecovered: this.weaponRecovered,
      mechanosAttunement: this.mechanosAttunement,
      mechanosAttuned: this.mechanosAttuned,
      mechanosPiloted: this.mechanosPiloted,
      fireRoots: this.fireRoots.map((root) => ({ ...root })),
    };
  }

  public importState(saved: Readonly<AncientEchoesSaveData>): void {
    if (saved.version !== 1) return;
    this.stage = stageOrder.includes(saved.stage) ? saved.stage : 'DORMANT';
    this.collapseProgress = clamp(saved.collapseProgress, 0, 1);
    this.echoSecondsRemaining = clamp(
      saved.echoSecondsRemaining,
      0,
      FIRE_ROOT_EXTRACT_SECONDS,
    );
    this.echoExposure = clamp(saved.echoExposure, 0, 1);
    this.laboratoryOpen = Boolean(saved.laboratoryOpen);
    this.laboratoryAwake = Boolean(saved.laboratoryAwake);
    this.weaponRecovered = Boolean(saved.weaponRecovered);
    this.mechanosAttunement = clamp(saved.mechanosAttunement, 0, 1);
    this.mechanosAttuned = Boolean(saved.mechanosAttuned);
    this.mechanosPiloted = Boolean(saved.mechanosPiloted) &&
      this.echoSecondsRemaining > 0;
    const roots = new Map(saved.fireRoots.map((root) => [root.id, root]));
    for (const root of this.fireRoots) {
      const restored = roots.get(root.id);
      if (!restored) continue;
      root.stock = clamp(Math.floor(restored.stock), 0, 3);
      root.regrowSeconds = clamp(
        restored.regrowSeconds,
        0,
        FIRE_ROOT_REGROW_SECONDS,
      );
      root.transplanted = Boolean(restored.transplanted);
    }
    const cultivated = saved.fireRoots.find((root) =>
      root.id === 'fire-root-laboratory-bed');
    if (cultivated && !this.fireRoots.some((root) => root.id === cultivated.id)) {
      this.fireRoots.push({
        id: cultivated.id,
        x: ANCIENT_ECHOES_LANDMARKS.planter.x,
        z: ANCIENT_ECHOES_LANDMARKS.planter.z,
        stock: clamp(Math.floor(cultivated.stock), 0, 3),
        regrowSeconds: clamp(cultivated.regrowSeconds, 0, FIRE_ROOT_REGROW_SECONDS),
        transplanted: true,
      });
    }
  }

  private advanceTo(stage: AncientEchoesStage): void {
    if (!stageAtLeast(this.stage, stage)) this.stage = stage;
  }

  private objective(): Readonly<{ detail: string; progress: number }> {
    switch (this.stage) {
      case 'DORMANT':
        return {
          detail: 'The broken stone road ends at an arch northwest of camp. Something under it has not weathered.',
          progress: 0,
        };
      case 'LAB_FOUND':
        return this.collapseProgress < 1
          ? {
              detail: 'Use the flint edge to loosen the five readable layers of the collapse.',
              progress: 0.08 + this.collapseProgress * 0.24,
            }
          : {
              detail: 'A root-and-eye mark points west, toward the frozen pond and warmer soil.',
              progress: 0.33,
            };
      case 'FIRE_ROOT_FOUND':
        return {
          detail: this.inventory.fireRoot >= 2
            ? 'Steep two Fire-root rhizomes beside a living fire.'
            : 'Harvest one more rhizome without killing its crown.',
          progress: 0.4 + Math.min(2, this.inventory.fireRoot) * 0.07,
        };
      case 'EXTRACT_BREWED':
        return {
          detail: 'Open the backpack and drink the amber extract when you are ready to spend its brief sight.',
          progress: 0.56,
        };
      case 'ECHO_SEEN':
        return {
          detail: this.laboratoryOpen
            ? 'Enter the opened stone laboratory before the echo fades.'
            : 'Return to the seamless door. Its hidden metal seam now burns through the fog.',
          progress: this.laboratoryOpen ? 0.72 : 0.64,
        };
      case 'SEAL_OPEN':
        return {
          detail: 'Inside, find the stone retort, the empty cradle and the kneeling Mekanos.',
          progress: 0.76,
        };
      case 'LAB_AWAKENED':
        return {
          detail: 'While Echo Sight lasts, hold one thought steady before Mekanos three times.',
          progress: 0.82 + this.mechanosAttunement * 0.14,
        };
      case 'MECHANOS_ATTUNED':
        return {
          detail: this.mechanosPiloted
            ? 'Direct Mekanos with movement intention. F releases the thought before the extract fades.'
            : 'Mekanos remembers you. Drink extract, approach it and centre your thought to walk.',
          progress: 1,
        };
    }
  }
}
