/** Bounded, opt-in diagnostics. All timestamps use performance.timeOrigin. */
export class TraceRing<T> {
  private readonly items: T[] = [];
  private cursor = 0;
  public dropped = 0;
  public constructor(public readonly capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error('Invalid trace capacity');
  }
  public push(value: T): void {
    if (this.items.length < this.capacity) this.items.push(value);
    else { this.items[this.cursor] = value; this.cursor = (this.cursor + 1) % this.capacity; this.dropped++; }
  }
  public values(): T[] { return [...this.items.slice(this.cursor), ...this.items.slice(0, this.cursor)]; }
}

export interface DetailedCaptureOptions {
  mode?: 'standard' | 'deep';
  durationSeconds?: number;
  maxFrames?: number;
  gpuEveryNFrames?: number;
  /** One query around the renderer by default. Segmented timing may perturb ANGLE/Metal. */
  gpuTiming?: 'frame' | 'segmented';
  drawEveryNFrames?: number;
  label?: string;
}
export interface CpuSpan { name: string; startMs: number; durationMs: number }
export interface DetailedFrame {
  frameId: number;
  startMs: number;
  intervalSincePreviousStartMs: number;
  simulationDeltaMs: number;
  cpuMs: number | null;
  callbackMs: number | null;
  tailAfterContextMs: number | null;
  spans: CpuSpan[];
  counters: Record<string, number>;
  context: Record<string, unknown>;
  render?: Record<string, unknown>;
}
export interface CaptureEvent {
  name: string; startMs: number; durationMs: number; frameId: number | null; data: Record<string, unknown>;
}
export interface GpuSegment {
  captureId: number; queryId: number; frameId: number; scopePath: string[];
  submittedAtMs: number; resolvedAtMs: number; resolvedFrameId: number;
  gpuMs: number | null; status: 'valid' | 'disjoint' | 'invalid-result' | 'timeout' | 'context-lost' | 'cancelled';
}

const bounded = (value: number | undefined, fallback: number, min: number, max: number): number =>
  value === undefined || !Number.isFinite(value) ? fallback : Math.max(min, Math.min(max, Math.floor(value)));
const safeUrl = (value: unknown): string => {
  try { const u = new URL(String(value), location.href); return `${u.origin}${u.pathname}`; }
  catch { return ''; }
};

export class DetailedPerformanceCapture {
  public active = false;
  public captureId = 0;
  public options: Required<DetailedCaptureOptions> = {
    mode: 'standard', durationSeconds: 30, maxFrames: 3600, gpuEveryNFrames: 10, gpuTiming: 'frame', drawEveryNFrames: 30, label: '',
  };
  public readonly metadata: Record<string, unknown> = {};
  public currentFrame?: DetailedFrame;
  private frames = new TraceRing<DetailedFrame>(3600);
  private events = new TraceRing<CaptureEvent>(2000);
  private gpu = new TraceRing<GpuSegment>(12000);
  private observers: PerformanceObserver[] = [];
  private cleanups: (() => void)[] = [];
  private listeners = new Set<(active: boolean) => void>();
  private startedAtMs = 0;
  private stoppedAtMs: number | null = null;
  private finalizedAtMs = 0;
  private droppedSpans = 0;
  private frameCount = 0;
  private stopTimer?: ReturnType<typeof setTimeout>;
  private changes: Record<string, unknown> = {};

  public onStateChange(listener: (active: boolean) => void): () => void {
    this.listeners.add(listener); return () => this.listeners.delete(listener);
  }
  public start(options: DetailedCaptureOptions = {}, now = performance.now()): void {
    this.stop(now);
    this.captureId++;
    const mode = options.mode === 'deep' ? 'deep' : 'standard';
    this.options = {
      mode, durationSeconds: bounded(options.durationSeconds, 30, 1, 120),
      maxFrames: bounded(options.maxFrames, 3600, 60, 7200),
      gpuEveryNFrames: bounded(options.gpuEveryNFrames, mode === 'deep' ? 5 : 10, 1, 120),
      gpuTiming: options.gpuTiming === 'segmented' ? 'segmented' : 'frame',
      drawEveryNFrames: bounded(options.drawEveryNFrames, 30, 1, 600),
      label: String(options.label ?? '').slice(0, 200),
    };
    this.frames = new TraceRing(this.options.maxFrames);
    this.events = new TraceRing(2000); this.gpu = new TraceRing(12000);
    this.currentFrame = undefined; this.frameCount = 0; this.droppedSpans = 0; this.changes = {};
    this.startedAtMs = now; this.stoppedAtMs = null; this.active = true;
    this.metadata.timeOrigin = performance.timeOrigin;
    this.metadata.startedAtIso = new Date(performance.timeOrigin + now).toISOString();
    if (typeof navigator !== 'undefined') {
      this.metadata.browser = navigator.userAgent;
      this.metadata.hardwareConcurrency = navigator.hardwareConcurrency;
      this.metadata.deviceMemoryGiB = (navigator as Navigator & { deviceMemory?: number }).deviceMemory ?? null;
    }
    this.installBrowserObservers();
    for (const listener of this.listeners) listener(true);
    this.event('capture-start', { ...this.options }, now);
    this.stopTimer = setTimeout(() => this.stop(), this.options.durationSeconds * 1000);
    (this.stopTimer as unknown as { unref?: () => void }).unref?.();
  }
  public stop(now = performance.now()): void {
    if (!this.active) return;
    if (this.stopTimer !== undefined) clearTimeout(this.stopTimer);
    this.stopTimer = undefined;
    for (const observer of this.observers) {
      this.recordBrowserEntries(observer.takeRecords()); observer.disconnect();
    }
    this.observers = [];
    for (const cleanup of this.cleanups) cleanup();
    this.cleanups = [];
    this.event('capture-stop', {}, now);
    this.active = false; this.stoppedAtMs = now;
    for (const listener of this.listeners) listener(false);
  }
  public dispose(): void { this.stop(); this.listeners.clear(); }
  public clear(now = performance.now()): void {
    this.stop(now); this.captureId++;
    this.frames = new TraceRing(this.options.maxFrames); this.events = new TraceRing(2000); this.gpu = new TraceRing(12000);
    this.currentFrame = undefined; this.frameCount = 0; this.droppedSpans = 0;
    this.startedAtMs = now; this.stoppedAtMs = now; this.changes = {};
    this.metadata.renderCatalog = {}; this.metadata.gpuQueriesPending = 0;
  }
  public beginFrame(frameId: number, intervalMs: number, startMs: number): void {
    if (!this.active) return;
    this.frameCount++;
    this.currentFrame = {
      frameId, startMs, intervalSincePreviousStartMs: intervalMs,
      simulationDeltaMs: Math.min(intervalMs, 100), cpuMs: null, callbackMs: null,
      tailAfterContextMs: null, spans: [], counters: {}, context: {},
    };
    this.frames.push(this.currentFrame);
  }
  public span(name: string, startMs: number, endMs = performance.now()): void {
    if (!this.active || !this.currentFrame) return;
    if (this.currentFrame.spans.length >= 256) { this.droppedSpans++; return; }
    this.currentFrame.spans.push({ name, startMs, durationMs: Math.max(0, endMs - startMs) });
  }
  public measure<T>(name: string, work: () => T): T {
    if (!this.active) return work();
    const start = performance.now();
    try { return work(); } finally { this.span(name, start); }
  }
  /** Returns a restoration function; never replaces a wrapper installed later by another owner. */
  public instrument(target: object, method: string, name: string): () => void {
    const owner = target as Record<string, any>;
    const original = owner[method];
    if (typeof original !== 'function') return () => {};
    const hadOwn = Object.hasOwn(owner, method);
    const capture = this;
    function wrapped(this: unknown, ...args: unknown[]): unknown {
      if (!capture.active) return original.apply(this, args);
      const start = performance.now();
      try { return original.apply(this, args); } finally { capture.span(name, start); }
    }
    owner[method] = wrapped;
    return () => { if (owner[method] === wrapped) { if (hadOwn) owner[method] = original; else delete owner[method]; } };
  }
  public count(name: string, value = 1): void {
    if (!this.active || !this.currentFrame || !Number.isFinite(value)) return;
    const counters = this.currentFrame.counters;
    counters[name] = (counters[name] ?? 0) + value;
  }
  public finishFrame(context: object, cpuEndMs: number): void {
    const frame = this.currentFrame;
    if (!this.active || !frame) return;
    frame.cpuMs = Math.max(0, cpuEndMs - frame.startMs);
    frame.context = { ...context };
    const keys = ['renderBufferWidth', 'renderBufferHeight', 'renderPixelRatio', 'sunShadowActive',
      'moonShadowActive', 'celestialShadowOwner', 'celestialStory', 'snowV5Quality', 'weatherKind',
      'weatherPhase', 'pageVisibility', 'shaderPrograms', 'renderGeometries', 'renderTextures',
      'localLightActivePoints', 'localLightPointSlots', 'localLightActiveSpots', 'localLightSkipped',
      'survivalBuiltPieces', 'atmospherePhysicalReady', 'volumetricCloudRenderer'];
    const changed: Record<string, unknown> = {};
    for (const key of keys) {
      const value = frame.context[key];
      if (value !== this.changes[key]) { changed[key] = { before: this.changes[key] ?? null, after: value ?? null }; this.changes[key] = value; }
    }
    if (Object.keys(changed).length) this.event('context-change', changed, cpuEndMs);
    this.finalizedAtMs = performance.now();
  }
  public finishCallback(now = performance.now()): void {
    const frame = this.currentFrame;
    if (!this.active || !frame) return;
    frame.callbackMs = Math.max(0, now - frame.startMs);
    frame.tailAfterContextMs = Math.max(0, now - this.finalizedAtMs);
    if (now - this.startedAtMs >= this.options.durationSeconds * 1000) this.stop(now);
  }
  public event(name: string, data: Record<string, unknown> = {}, startMs = performance.now(), durationMs = 0, frameId: number | null = this.currentFrame?.frameId ?? null): void {
    if (this.active) this.events.push({ name, startMs, durationMs, frameId, data });
  }
  public addGpu(segment: GpuSegment): void {
    if (segment.captureId === this.captureId) this.gpu.push(segment);
  }
  public isGpuFrame(): boolean { return this.active && (this.frameCount - 1) % this.options.gpuEveryNFrames === 0; }
  public isDrawFrame(): boolean { return this.active && this.options.mode === 'deep' && (this.frameCount - 1) % this.options.drawEveryNFrames === 0; }
  public snapshot(): Record<string, unknown> {
    const frames = this.frames.values(); const segments = this.gpu.values();
    const byFrame = new Map<number, GpuSegment[]>();
    for (const segment of segments) {
      const list = byFrame.get(segment.frameId) ?? []; list.push(segment); byFrame.set(segment.frameId, list);
    }
    const gpuScopes = new Map<string, number[]>();
    const cpuScopes = new Map<string, number[]>();
    for (const frame of frames) {
      const sums = new Map<string, number>();
      for (const span of frame.spans) sums.set(span.name, (sums.get(span.name) ?? 0) + span.durationMs);
      for (const [name, sum] of sums) { const values = cpuScopes.get(name) ?? []; values.push(sum); cpuScopes.set(name, values); }
    }
    const frameGpuStatus: Record<number, unknown> = {};
    for (const frame of frames) {
      const coverage = frame.render?.gpuCoverage as { requested: boolean; supported: boolean; submittedSegments: number; skippedSegments: number } | undefined;
      if (!coverage?.requested) continue;
      const samples = byFrame.get(frame.frameId) ?? [];
      const complete = coverage.supported && coverage.skippedSegments === 0 && coverage.submittedSegments > 0 &&
        samples.length === coverage.submittedSegments && samples.every(s => s.status === 'valid');
      frameGpuStatus[frame.frameId] = { complete, submitted: coverage.submittedSegments, resolved: samples.length,
        invalid: samples.filter(s => s.status !== 'valid').length, skipped: coverage.skippedSegments };
      if (!complete) continue;
      const sums = new Map<string, number>();
      for (const sample of samples) for (let i = 1; i <= sample.scopePath.length; i++) {
        const name = sample.scopePath.slice(0, i).join('/'); sums.set(name, (sums.get(name) ?? 0) + sample.gpuMs!);
      }
      for (const [name, sum] of sums) { const list = gpuScopes.get(name) ?? []; list.push(sum); gpuScopes.set(name, list); }
    }
    return structuredClone({
      version: 1, captureId: this.captureId, active: this.active, options: { ...this.options },
      startedAtMs: this.startedAtMs, stoppedAtMs: this.stoppedAtMs, metadata: { ...this.metadata },
      frameCount: this.frameCount,
      dropped: { frames: this.frames.dropped, events: this.events.dropped, gpuSegments: this.gpu.dropped, cpuSpans: this.droppedSpans },
      semantics: {
        cpu: 'Wall-clock spans may overlap. callbackMs includes trace finalization and shader-prewarm dispatch, but not browser paint after the callback.',
        gpu: 'Non-overlapping TIME_ELAPSED segments. scopePath identifies ancestors. Sum valid segments of one complete frame for inclusive scope totals; never add parent totals to child totals.',
        gpuCoverage: 'Inspect each frame render.gpuCoverage, pending count, query status, and dropped counters. Missing GPU values are unknown, never zero.',
        draw: 'Deep-mode sampled frames only. Actual renderer.info counter deltas per renderBufferDirect call; sprite and custom draw paths may remain unclassified.',
        browser: 'Observer records are asynchronous. Associate by timestamp overlap, not the observer callback frame. Unsupported entry types are explicitly listed.',
        overhead: 'Instrumentation changes CPU/GPU workload. Compare standard, deep and disabled captures; deep draw timings are diagnostic samples, not baseline frame times.',
      },
      summary: {
        window: 'Retained capture frames only, including normal frames; not lifetime statistics.',
        cpuMs: summarize(frames.flatMap(f => f.cpuMs === null ? [] : [f.cpuMs])),
        cpuScopes: Object.fromEntries([...cpuScopes].map(([name, values]) => [name, summarize(values)])),
        cpuScopeSemantics: 'Inclusive per-frame sums for frames where that scope was observed; absent or dropped scopes are not silently treated as zero. Counts may differ across scopes.',
        callbackMs: summarize(frames.flatMap(f => f.callbackMs === null ? [] : [f.callbackMs])),
        intervalMs: summarize(frames.map(f => f.intervalSincePreviousStartMs)),
        gpuScopes: Object.fromEntries([...gpuScopes].map(([name, values]) => [name, summarize(values)])),
        gpuScopeSemantics: 'Inclusive totals from complete sampled frames only. Do not sum parents and children or compare scopes sampled on different frame subsets as an additive breakdown.',
      },
      frameGpuStatus, frames, gpuSegments: segments, events: this.events.values(),
    });
  }
  public chromeTrace(): object {
    const traceEvents: object[] = [];
    for (const frame of this.frames.values()) {
      for (const span of frame.spans) traceEvents.push({ name: span.name, cat: 'cpu', ph: 'X', pid: 1, tid: 1, ts: span.startMs * 1000, dur: span.durationMs * 1000, args: { frameId: frame.frameId } });
      traceEvents.push({ name: 'frame', ph: 'i', s: 't', pid: 1, tid: 1, ts: frame.startMs * 1000, args: { frameId: frame.frameId, cpuMs: frame.cpuMs, callbackMs: frame.callbackMs, counters: frame.counters } });
    }
    for (const event of this.events.values()) traceEvents.push({ name: event.name, cat: 'observation', ph: event.durationMs ? 'X' : 'i', s: 't', pid: 1, tid: 2, ts: event.startMs * 1000, dur: event.durationMs * 1000, args: event.data });
    // WebGL elapsed queries do not expose GPU timestamps synchronized with the CPU clock.
    for (const g of this.gpu.values()) traceEvents.push({ name: g.scopePath.join('/'), cat: 'gpu-result', ph: 'i', s: 't', pid: 2, tid: 1, ts: g.resolvedAtMs * 1000, args: g });
    return { traceEvents, displayTimeUnit: 'ms', metadata: { ...this.metadata, gpuTimeline: 'Result arrival markers, not fabricated GPU execution timestamps.' } };
  }
  private installBrowserObservers(): void {
    const supported = typeof PerformanceObserver !== 'undefined' ? PerformanceObserver.supportedEntryTypes ?? [] : [];
    const desired = ['longtask', 'long-animation-frame', 'resource'];
    const installed: string[] = [];
    for (const type of desired) {
      if (!supported.includes(type)) continue;
      try {
        const observer = new PerformanceObserver(list => this.recordBrowserEntries(list.getEntries()));
        observer.observe({ type, buffered: false }); this.observers.push(observer); installed.push(type);
      } catch { /* Explicitly reported as unavailable below. */ }
    }
    this.metadata.observers = { installed, unavailable: desired.filter(t => !installed.includes(t)) };
    if (typeof document !== 'undefined') {
      const visibility = () => this.event('visibility-change', { state: document.visibilityState }, performance.now(), 0, null);
      document.addEventListener('visibilitychange', visibility);
      this.cleanups.push(() => document.removeEventListener('visibilitychange', visibility));
    }
  }
  private recordBrowserEntries(entries: readonly PerformanceEntry[]): void {
    for (const entry of entries) {
      if (entry.startTime + entry.duration < this.startedAtMs) continue;
      const e = entry as PerformanceEntry & Record<string, any>;
      const data: Record<string, unknown> = { entryType: e.entryType };
      if (e.entryType === 'resource') {
        Object.assign(data, { url: safeUrl(e.name), initiatorType: e.initiatorType, transferSize: e.transferSize,
          encodedBodySize: e.encodedBodySize, decodedBodySize: e.decodedBodySize,
          responseStart: e.responseStart, responseEnd: e.responseEnd });
      } else {
        for (const key of ['blockingDuration', 'renderStart', 'styleAndLayoutStart', 'firstUIEventTimestamp']) if (typeof e[key] === 'number') data[key] = e[key];
        if (Array.isArray(e.scripts)) data.scripts = e.scripts.slice(0, 32).map((s: Record<string, any>) => ({
          startTime: s.startTime, duration: s.duration, executionStart: s.executionStart,
          forcedStyleAndLayoutDuration: s.forcedStyleAndLayoutDuration,
          invokerType: s.invokerType, sourceURL: safeUrl(s.sourceURL),
          sourceFunctionName: s.sourceFunctionName, sourceCharPosition: s.sourceCharPosition,
        }));
      }
      this.event(`browser.${e.entryType}`, data, e.startTime, e.duration, null);
    }
  }
}

const summarize = (values: number[]): Record<string, number | null> => {
  values.sort((a, b) => a - b);
  const percentile = (p: number) => values.length ? values[Math.max(0, Math.ceil(values.length * p) - 1)]! : null;
  return { count: values.length, meanMs: values.length ? values.reduce((a, b) => a + b, 0) / values.length : null,
    p50Ms: percentile(.5), p95Ms: percentile(.95), p99Ms: percentile(.99), maximumMs: values.at(-1) ?? null };
};
