import { BufferGeometry, Float32BufferAttribute } from 'three';
import type { SurvivalBuildPieceDefinition } from '../SurvivalBuildingCatalog';
import type { WorldAssetRecipe } from '../../land/WorldAssetCatalog';

/** Shared footprint contract: local x + z <= 0 is the occupied half bay. */
export const isTriangleBuildFloor=(id:string):boolean=>id==='TIMBER_FLOOR_TRIANGLE'||id==='STONE_FLOOR_TRIANGLE'||id==='TIMBER_FLOOR_EQUILATERAL';
export const triangleBuildFloorVertices=(id:string):readonly (readonly [number,number])[]=>
  id==='TIMBER_FLOOR_EQUILATERAL'?[[-1,-Math.sqrt(3)/3],[1,-Math.sqrt(3)/3],[0,2*Math.sqrt(3)/3]]:[[-1,-1],[1,-1],[-1,1]];
export const triangleBuildFloorContains=(x:number,z:number,padding=0,id='TIMBER_FLOOR_TRIANGLE'):boolean=>
  id==='TIMBER_FLOOR_EQUILATERAL'
    ? z>=-Math.sqrt(3)/3-padding && Math.sqrt(3)*Math.abs(x)+z<=2*Math.sqrt(3)/3+padding*2
    : Math.abs(x)<=1+padding&&Math.abs(z)<=1+padding&&x+z<=padding*Math.SQRT2;

