export interface DrivingPerformanceSummaryData {
  readonly fps: number;
  readonly frameMs: number;
  readonly cpuFrameMs: number;
  readonly gpuRenderMs: number;
  readonly frameWaitMs: number;
}

export const formatDrivingPerformanceSummary = (
  data: Readonly<DrivingPerformanceSummaryData>,
): string =>
  `FPS ${data.fps.toFixed(0)}  ` +
  `FRAME ${data.frameMs.toFixed(1)} ms  ` +
  `CPU ${data.cpuFrameMs.toFixed(1)} ms  ` +
  `GPU ${data.gpuRenderMs >= 0 ? `${data.gpuRenderMs.toFixed(1)} ms` : 'N/A'}  ` +
  `WAIT ${data.frameWaitMs.toFixed(1)} ms`;

