  public updateTelemetry(state: Readonly<VesselState>): void {
    this.telemetryTitle.textContent = 'M/S TERN';
    this.engineLabel.textContent = 'ENGINE LOAD';
    this.throttleLabel.textContent = 'THROTTLE';
    this.resistanceLabel.textContent = 'ICE RESISTANCE';
    this.surfaceLabel.textContent = 'UNDER THE BOW';
    this.fuelLabel.textContent = 'FUEL';
    const throttlePercent = Math.round(Math.abs(state.throttle) * 100);
    this.throttleValue.textContent = `${throttlePercent}%`;
    this.directionValue.textContent =
      state.throttle > 0.03 ? 'AHEAD' : state.throttle < -0.03 ? 'REVERSE' : 'NEUTRAL';
    this.throttleFill.style.transform = `scaleX(${Math.abs(state.throttle)})`;
    this.throttleFill.classList.toggle('is-reverse', state.throttle < -0.03);
    this.speedValue.textContent = `${(state.speed * 6.3).toFixed(1)} kn`;
    this.engineValue.textContent = `${Math.round(state.engineLoad * 100)}%`;
    this.engineFill.style.transform = `scaleX(${state.engineLoad})`;
    this.resistanceValue.textContent = `${Math.round(state.currentResistance * 100)}%`;
    this.iceValue.textContent = ICE_LABELS[state.currentIceClass];
    this.iceValue.dataset.ice = state.currentIceClass;
    this.fuelValue.textContent = `${Math.round(state.fuel)}%`;
    this.updateWorldPosition(state.worldPosition.x, state.worldPosition.z);
    this.root.classList.toggle('is-boosting', state.boostActive);
    this.root.classList.toggle('is-stuck', state.stuckFactor > 0.66);
  }

  public updateBulldozerTelemetry(
    state: Readonly<BulldozerState>,
  ): void {
    const maximumSpeed = state.speed >= 0 ? 2.9 : 1.55;
    const groundSpeedRatio = Math.min(
      1,
      Math.abs(state.speed) / maximumSpeed,
    );
    this.telemetryTitle.textContent = 'BOREALIS DOZER';
    this.engineLabel.textContent = 'ENGINE LOAD';
    this.throttleLabel.textContent = 'GROUND SPEED';
    this.resistanceLabel.textContent = state.tractionSlip > 0.18
      ? 'PLOW LOAD / TRACK SLIP'
      : 'PLOW LOAD';
    this.surfaceLabel.textContent = 'SNOW UNDER THE TRACKS';
    this.fuelLabel.textContent = 'BLADE HEIGHT';
    this.throttleValue.textContent =
      `${Math.round(groundSpeedRatio * 100)}%`;
    this.directionValue.textContent =
      state.speed > 0.03
        ? 'FORWARD'
        : state.speed < -0.03
          ? 'REVERSE'
          : 'STOPPED';
    this.throttleFill.style.transform = `scaleX(${groundSpeedRatio})`;
    this.throttleFill.classList.toggle('is-reverse', state.speed < -0.03);
    this.speedValue.textContent =
      `${Math.abs(state.speed * 3.6).toFixed(1)} km/h`;
    this.engineValue.textContent = `${Math.round(state.engineLoad * 100)}%`;
    this.engineFill.style.transform = `scaleX(${state.engineLoad})`;
    this.resistanceValue.textContent = state.tractionSlip > 0.18
      ? `${Math.round(state.bladeLoad * 100)}% · ` +
        `${Math.round(state.tractionSlip * 100)}%`
      : `${Math.round(state.bladeLoad * 100)}%`;
    this.iceValue.textContent = `${state.snowDepth.toFixed(2)} m`;
    this.iceValue.dataset.ice = 'snow';
    this.fuelValue.textContent =
      `${Math.round(state.bladePosition * 100)}%`;
    this.updateWorldPosition(state.x, state.z);
    this.root.classList.remove('is-boosting');
    this.root.classList.toggle('is-stuck', state.tractionSlip > 0.78);
  }

  public updateLandMachineTelemetry(
    state: Readonly<LandMachineState>,
  ): void {
    const capacity = state.type === 'SNOW_TRUCK'
      ? 22
      : state.type === 'HELICOPTER'
        ? 12
        : state.type === 'WHEEL_LOADER'
          ? 2.4
        : 0;
    this.telemetryTitle.textContent = state.type === 'HEAVY_DOZER'
      ? 'HEAVY DOZER'
      : state.type === 'WHEEL_LOADER'
        ? 'WHEEL LOADER'
      : state.type === 'SNOW_TRUCK'
        ? 'SNOW HAUL TRUCK'
        : 'CARGO HELICOPTER';
    this.engineLabel.textContent = state.type === 'HELICOPTER'
      ? 'ROTOR SPEED'
      : 'ENGINE LOAD';
    this.throttleLabel.textContent = state.type === 'HELICOPTER'
      ? 'AIR SPEED'
      : 'GROUND SPEED';
    this.resistanceLabel.textContent = capacity > 0 ? 'CARGO' : 'PLOW LOAD';
    this.surfaceLabel.textContent = state.type === 'HELICOPTER' ? 'ALTITUDE' : 'SNOW ROUTE';
    this.fuelLabel.textContent = state.type === 'HEAVY_DOZER' ? 'BLADE HEIGHT' : 'LOAD';
    const speedRatio = Math.max(
      0,
      Math.min(1, Math.abs(state.speed) / (state.type === 'HELICOPTER' ? 7.4 : 5.2)),
    );
    this.throttleValue.textContent = `${Math.round(speedRatio * 100)}%`;
    this.directionValue.textContent = state.type === 'HELICOPTER'
      ? state.rotorSpeed < 0.02
        ? 'ROTOR STOPPED'
        : state.rotorSpeed < 0.94
          ? 'ROTOR SPOOLING'
          : state.altitude > 0.05
            ? 'AIRBORNE'
            : 'ROTOR READY'
      : Math.abs(state.speed) > 0.03 ? 'MOVING' : 'STOPPED';
    this.throttleFill.style.transform = `scaleX(${speedRatio})`;
    this.throttleFill.classList.remove('is-reverse');
    this.speedValue.textContent = `${Math.abs(state.speed * 3.6).toFixed(1)} km/h`;
    const loadRatio = capacity > 0
      ? Math.max(0, Math.min(1, state.cargoMass / capacity))
      : state.bladePosition;
    const engineRatio = state.type === 'HELICOPTER'
      ? state.rotorSpeed
      : speedRatio;
    this.engineValue.textContent = `${Math.round(engineRatio * 100)}%`;
    this.engineFill.style.transform = `scaleX(${engineRatio})`;
    this.resistanceValue.textContent = `${Math.round(loadRatio * 100)}%`;
    this.iceValue.textContent = state.type === 'HELICOPTER'
      ? `${state.altitude.toFixed(1)} m`
      : 'LAND';
    this.iceValue.dataset.ice = 'snow';
    this.fuelValue.textContent = capacity > 0
      ? `${state.cargoMass.toFixed(1)} m³`
      : `${Math.round(state.bladePosition * 100)}%`;
    this.updateWorldPosition(
      state.x,
      state.z,
      state.type === 'HELICOPTER' ? state.altitude : undefined,
    );
  }

  public updatePenguinTelemetry(
    state: Readonly<PenguinState>,
    cleanRatio: number,
    selectedToolName?: string,
  ): void {
    const speedRatio = Math.min(1, Math.abs(state.speed) / 2.18);
    this.telemetryTitle.textContent = 'BOREALIS CARETAKER';
    this.engineLabel.textContent = 'TOOL ACTIVITY';
    this.throttleLabel.textContent = 'WADDLE SPEED';
    this.resistanceLabel.textContent = selectedToolName?.toUpperCase() ?? 'FIELD TOOL';
    this.surfaceLabel.textContent = 'SNOW UNDERFOOT';
    this.fuelLabel.textContent = 'PARK DETAILS';
    this.throttleValue.textContent = `${Math.round(speedRatio * 100)}%`;
    this.directionValue.textContent =
      state.speed > 0.03
        ? 'FORWARD'
        : state.speed < -0.03
          ? 'BACKWARD'
          : 'STANDING';
    this.throttleFill.style.transform = `scaleX(${speedRatio})`;
    this.throttleFill.classList.toggle('is-reverse', state.speed < -0.03);
    this.speedValue.textContent = `${Math.abs(state.speed * 3.6).toFixed(1)} km/h`;
    this.engineValue.textContent = state.blowerActive ? '100%' : '0%';
    this.engineFill.style.transform = `scaleX(${state.blowerActive ? 1 : 0})`;
    this.resistanceValue.textContent = state.blowerActive ? 'ACTIVE' : 'READY';
    this.iceValue.textContent = `${state.snowDepth.toFixed(2)} m`;
    this.iceValue.dataset.ice = 'snow';
    this.fuelValue.textContent = `${Math.round(cleanRatio * 100)}%`;
    this.updateWorldPosition(state.x, state.z);
    this.root.classList.remove('is-boosting', 'is-stuck');
  }

