  public setProgressionState(state: {
    label: string;
    text: string;
    complete: boolean;
    progress?: readonly string[];
  }): void {
    const progressionKey = [
      state.label,
      state.text,
      ...(state.progress ?? []),
    ].join('|');
    if (this.progressionKey && progressionKey !== this.progressionKey) {
      this.objective.classList.remove('is-updated');
      void this.objective.offsetWidth;
      this.objective.classList.add('is-updated');
      window.clearTimeout(this.objectivePulseTimer);
      this.objectivePulseTimer = window.setTimeout(() => {
        this.objective.classList.remove('is-updated');
      }, 1_600);
    }
    this.progressionKey = progressionKey;
    this.objective.classList.toggle(
      'is-complete',
      state.complete,
    );
    this.objectiveLabel.textContent = state.label;
    this.objectiveText.textContent = state.text;
    this.objectiveProgress.replaceChildren(
      ...(state.progress ?? []).map((text) => {
        const item = document.createElement('span');
        item.textContent = text;
        return item;
      }),
    );
    this.objectiveProgress.classList.toggle(
      'is-hidden',
      !state.progress?.length,
    );
  }

