  public updateEnvironment(
    weather: Readonly<WeatherState>,
    day: Readonly<DayNightState>,
  ): void {
    const wilderness = this.root.classList.contains('is-wilderness-survival');
    const weatherKey = wilderness
      ? `${weather.target}:${weather.weatherStoryId}`
      : weather.target;
    if (this.weatherValue.dataset.weather !== weatherKey) {
      this.weatherValue.textContent = wilderness
        ? weather.weatherStoryName.toUpperCase()
        : weather.target.replace('-', ' ').toUpperCase();
      this.weatherValue.dataset.weather = weatherKey;
    }
    if (this.lightValue.dataset.light !== day.phase) {
      this.lightValue.textContent = day.phase
        .replace('-', ' ')
        .toUpperCase();
      this.lightValue.dataset.light = day.phase;
    }
  }

