  private updateToggleActionState(
    action: string,
    active: boolean,
    label: string,
  ): void {
    this.root
      .querySelectorAll<HTMLButtonElement>(
        `[data-drive-action="${action}"]`,
      )
      .forEach((button) => {
        button.classList.toggle('is-active', active);
        button.setAttribute('aria-pressed', String(active));
        const state = button.querySelector<HTMLElement>('b');
        if (state) state.textContent = label;
      });
  }

  public setMusicPlayerState(state: Readonly<{
    context: MusicContext;
    tracks: readonly MusicTrack[];
    trackId: string;
    selectionId: string;
    trackTitle: string;
    paused: boolean;
    repeat: boolean;
  }>): void {
    const catalogSignature = state.tracks
      .map((track) => track.id)
      .join('|');
    if (this.musicTrackSelect.dataset.catalog !== catalogSignature) {
      this.musicTrackSelect.replaceChildren(
        new Option('Automatic playlist', AUTOMATIC_MUSIC_TRACK_ID),
        ...state.tracks.map((track) => new Option(track.title, track.id)),
      );
      this.musicTrackSelect.dataset.catalog = catalogSignature;
    }
    this.musicTrackSelect.value = [...this.musicTrackSelect.options].some(
      (option) => option.value === state.selectionId,
    )
      ? state.selectionId
      : AUTOMATIC_MUSIC_TRACK_ID;
    this.musicTrackSelect.setAttribute(
      'aria-label',
      state.context === 'THE_LONG_WINTER'
        ? 'The Long Winter music track'
        : 'Ice-A-Way music track',
    );
    this.updateMusicPlayerControls(state);
  }

