  public updateTabletWorld(view: Readonly<FieldTabletWorldView>): void {
    this.tabletMap = view.map;
    const visibleQuests = view.quests.filter(
      (quest) => quest.status !== 'CANCELLED',
    );
    const activeQuestCount = visibleQuests.filter(
      (quest) => quest.status === 'ACTIVE' || quest.status === 'OFFERED',
    ).length;
    this.updateTabletCount(this.tabletQuestCount, activeQuestCount);
    this.tabletQuestList.replaceChildren(
      ...(visibleQuests.length > 0
        ? visibleQuests.map((quest) => {
            const card = document.createElement('article');
            card.className = 'drive-tablet-card drive-tablet-quest-card';
            card.dataset.status = quest.status;
            const eyebrow = document.createElement('small');
            eyebrow.textContent = `${quest.sourceLabel} · ${quest.status}`;
            const title = document.createElement('strong');
            title.textContent = quest.title;
            const description = document.createElement('p');
            description.textContent = quest.description;
            card.append(eyebrow, title, description);
            if (quest.objective) {
              const objective = document.createElement('div');
              objective.className = 'drive-tablet-card-objective';
              objective.textContent = quest.objective;
              card.append(objective);
            }
            if (quest.rewardLabel) {
              const reward = document.createElement('b');
              reward.className = 'drive-tablet-card-reward';
              reward.textContent = quest.rewardLabel;
              card.append(reward);
            }
            return card;
          })
        : [this.createTabletEmptyState('NO KNOWN TASKS')]),
    );

    const activeRequests = view.requests.filter(
      (request) => request.status !== 'EXPIRED',
    );
    const newRequestCount = activeRequests.filter(
      (request) => request.status === 'NEW',
    ).length;
    this.updateTabletCount(this.tabletRequestCount, newRequestCount);
    this.tabletButton.classList.toggle('has-unread', newRequestCount > 0);
    this.tabletRequestList.replaceChildren(
      ...(activeRequests.length > 0
        ? activeRequests.map((request) => {
            const card = document.createElement('article');
            card.className = 'drive-tablet-card drive-tablet-request-card';
            card.dataset.status = request.status;
            card.dataset.kind = request.kind;
            const header = document.createElement('header');
            const source = document.createElement('small');
            source.textContent = `${request.kind.replace('_', ' ')} · ${request.sourceLabel}`;
            const status = document.createElement('b');
            status.textContent = request.status;
            header.append(source, status);
            const title = document.createElement('strong');
            title.textContent = request.title;
            const body = document.createElement('p');
            body.textContent = request.body;
            card.append(header, title, body);
            const metaParts = [
              request.signalBand?.replaceAll('_', ' '),
              request.locationLabel,
              request.locationUncertaintyMetres !== undefined
                ? `±${Math.round(request.locationUncertaintyMetres)} m`
                : undefined,
              request.receivedAt !== undefined
                ? this.formatRadioTime(request.receivedAt)
                : undefined,
            ].filter((part): part is string => !!part);
            if (metaParts.length > 0) {
              const meta = document.createElement('small');
              meta.className = 'drive-tablet-card-meta';
              meta.textContent = metaParts.join(' · ');
              card.append(meta);
            }
            if (request.signalDetail) {
              const detail = document.createElement('small');
              detail.className = 'drive-tablet-card-detail';
              detail.textContent = request.signalDetail;
              card.append(detail);
            }
            if (request.status === 'NEW' && request.radioMessageId) {
              const acknowledge = document.createElement('button');
              acknowledge.dataset.radioMessageId = request.radioMessageId;
              acknowledge.textContent = 'ACKNOWLEDGE CALL';
              card.append(acknowledge);
            }
            return card;
          })
        : [this.createTabletEmptyState('NO RECEIVED REQUESTS')]),
    );
    this.renderTabletMap(view.map);
    const utilityServices = view.utilityServices ?? [];
    this.tabletUtilitySummary.replaceChildren(
      ...(utilityServices.length > 0
        ? utilityServices.map((service) => {
        const card = document.createElement('article');
        card.className = 'drive-tablet-card drive-tablet-utility-card';
        card.dataset.utilityState = service.state;
        const title = document.createElement('strong');
        title.textContent = service.name;
        const state = document.createElement('small');
        state.textContent = service.state;
        const detail = document.createElement('p');
        detail.textContent = service.detail;
        card.append(title, state, detail);
        return card;
          })
        : [this.createTabletEmptyState('NO UTILITY DIAGNOSTICS')]),
    );
  }

