  public setDebugSettings(
    state: Readonly<DrivingDebugSettingsState>,
  ): void {
    const setValue = (
      key: string,
      value: string,
      active?: boolean,
    ): void => {
      const buttons = this.root.querySelectorAll<HTMLButtonElement>(
        `[data-debug-state="${key}"]`,
      );
      buttons.forEach((button) => {
        const output = button.querySelector<HTMLElement>('b');
        if (output) output.textContent = value;
        if (active === undefined) return;
        button.classList.toggle('is-active', active);
        button.setAttribute('aria-pressed', String(active));
      });
    };
    const toggle = (key: string, active: boolean): void =>
      setValue(key, active ? 'ON' : 'OFF', active);
    const setRange = (key: string, value: number): void => {
      const input =
        this.debugSettingsPanel.querySelector<HTMLInputElement>(
          `[data-ice-tuning="${key}"]`,
        );
      const output =
        this.debugSettingsPanel.querySelector<HTMLOutputElement>(
          `[data-ice-tuning-output="${key}"]`,
        );
      if (input) input.value = value.toFixed(2);
      if (output) output.textContent = `${value.toFixed(2)}x`;
    };

    toggle('metrics', state.metricsVisible);
    setValue(
      'spherical-world',
      state.sphericalWorldVisible
        ? state.sphericalWorldContext.toUpperCase()
        : 'OFF',
      state.sphericalWorldVisible,
    );
    toggle('sea-preview', state.seaPreview);
    toggle('cloud-patches', state.cloudPatches);
    toggle('depth-color', state.depthColor);
    toggle('voronoi', state.voronoi);
    toggle('surface-waves', state.surfaceWaves);
    toggle('micro-ripples', state.microRipples);
    toggle('wave-highlights', state.waveHighlights);
    toggle('current-ribbons', state.currentRibbons);
    toggle('edge-foam', state.edgeFoam);
    toggle('wind-shimmer', state.windShimmer);
    toggle('sky-reflection', state.skyReflection);
    toggle('celestial-glint', state.celestialGlint);
    setValue('ocean-profile', state.oceanProfile.toUpperCase());
    setValue('snow-presentation', state.snowPresentation.toUpperCase());
    setValue('traversal-mode', state.traversalMode.toUpperCase());
    setValue(
      'ocean-v3-view',
      state.oceanV3DebugView.toUpperCase(),
    );
    setValue('ice-profile', state.iceProfile.toUpperCase());
    setValue(
      'ice-shadow-quality',
      state.iceShadowQuality.toUpperCase(),
      state.iceShadowQuality !== 'off',
    );
    toggle(
      'port-clearance',
      state.portClearanceVisible,
    );
    setValue('ocean-mode', state.oceanMode.toUpperCase());
    toggle('ocean-freeze', !state.oceanFrozen);
    setValue('ocean-time', `x${state.oceanTimeScale}`);
    setValue('weather-mode', state.weatherMode.toUpperCase());
    toggle(
      'sky-weather-overlay',
      state.skyWeatherOverlayVisible,
    );
    toggle('wind-streaks', state.windStreaksVisible);
    setValue(
      'cloud-renderer',
      state.cloudRenderer === 'MESH_LIBRARY_V2' ? 'MESH V2' : 'PUFFS V1',
      state.cloudRenderer === 'MESH_LIBRARY_V2',
    );
    toggle('weather-freeze', !state.weatherFrozen);
    setValue('weather-time', `x${state.weatherTimeScale}`);
    setValue('day-mode', state.dayMode.toUpperCase());
    setValue(
      'celestial-model',
      state.celestialModel === 'AERION_SIRION' ? 'AERION + SIRION' : 'SUN + MOON',
      state.celestialModel === 'AERION_SIRION',
    );
    setValue('celestial-cycle', state.celestialCycle);
    setValue('polar-calendar', state.polarCalendar);
    toggle('day-freeze', !state.dayFrozen);
    setValue('day-time', `x${state.dayTimeScale}`);
    setValue('environment-master-time', `x${state.environmentMasterTimeScale}`);
    setValue('ice-time', `x${state.iceTimeScale}`);
    toggle('ice-drift', !state.iceDriftFrozen);
    toggle('refreeze', !state.refreezeFrozen);
    setRange('drift-strength', state.driftStrength);
    setRange('refreeze-speed', state.refreezeSpeed);
    setValue('ice-view', state.iceView.toUpperCase());
    toggle('ambient', state.ambientEnabled);
    setValue('ambient-budget', String(state.ambientBudget));
  }

