  private requireElement<T extends Element = HTMLElement>(selector: string): T {
    const element = this.root.querySelector<T>(selector);
    if (!element) throw new Error(`ICE-A-WAY driving UI element not found: ${selector}`);
    return element;
  }

  private updateWorldPosition(x: number, z: number, altitude?: number): void {
    this.positionValue.textContent = altitude === undefined
      ? `X ${x.toFixed(1)} · Z ${z.toFixed(1)}`
      : `X ${x.toFixed(1)} · Z ${z.toFixed(1)} · Y ${altitude.toFixed(1)}`;
  }

  private installLegacyTabletPages(): void {
    const pages: readonly [FieldTabletPage, HTMLElement][] = [
      ['settings', this.audioSettingsPanel],
      ['log', this.achievementPanel],
      ['radio', this.radioPanel],
      ['dev', this.debugSettingsPanel],
    ];
    for (const [page, panel] of pages) {
      panel.classList.add('drive-tablet-page');
      panel.dataset.tabletPagePanel = page;
      panel.classList.add('is-hidden');
      this.tabletPages.append(panel);
    }
  }

  private setSettingsCategory(category: string): void {
    const buttons = this.audioSettingsPanel.querySelectorAll<HTMLButtonElement>(
      '[data-settings-page]',
    );
    const panels = this.audioSettingsPanel.querySelectorAll<HTMLElement>(
      '[data-settings-panel]',
    );
    for (const button of buttons) {
      button.setAttribute(
        'aria-selected',
        String(button.dataset.settingsPage === category),
      );
    }
    for (const panel of panels) {
      panel.classList.toggle(
        'is-hidden',
        panel.dataset.settingsPanel !== category,
      );
    }
  }

  /** Turns the long developer list into stable, scannable native groups. */
  private organizeDebugSettingsPanel(): void {
    const headerTitle = this.debugSettingsPanel.querySelector<HTMLElement>(
      ':scope > header strong',
    );
    const headerDetail = this.debugSettingsPanel.querySelector<HTMLElement>(
      ':scope > header small',
    );
    if (headerTitle) headerTitle.textContent = 'DEV TOOLBOX';
    if (headerDetail) headerDetail.textContent = 'ADVANCED · SESSION ONLY';
    const sections = [
      ...this.debugSettingsPanel.querySelectorAll<HTMLElement>(
        ':scope > section',
      ),
    ];
    const priority = new Map<string, number>([
      ['SNOW & STONE V4', 0],
      ['PERFORMANCE TRACE', 1],
      ['ENVIRONMENT', 2],
      ['VIEW', 3],
      ['OCEAN LAYERS', 4],
      ['ICE SIMULATION', 5],
      ['AMBIENT EVENTS', 6],
    ]);
    const groups = sections.map((section) => {
      const heading = section.querySelector<HTMLElement>('h2');
      const title = heading?.textContent?.trim() ?? 'DEV TOOLS';
      heading?.remove();
      const details = document.createElement('details');
      details.className = 'drive-debug-group';
      details.dataset.debugGroup = title.toLowerCase().replace(/\W+/g, '-');
      details.open = title === 'SNOW & STONE V4';
      const summary = document.createElement('summary');
      const count = section.querySelectorAll('button, input').length;
      summary.innerHTML = `<span>${title}</span><small>${count} CONTROLS</small>`;
      details.append(summary, section);
      return { details, title };
    }).sort((left, right) =>
      (priority.get(left.title) ?? 99) - (priority.get(right.title) ?? 99)
    );
    this.debugSettingsPanel.append(...groups.map((group) => group.details));
  }

  public isTabletOpen(): boolean {
    return this.tabletIsOpen;
  }

  public toggleTablet(page: FieldTabletPage = this.activeTabletPage): void {
    if (this.tabletIsOpen) this.closeTablet();
    else this.openTabletPage(page);
  }

  /** Keyboard/controller shortcuts open their page, then close on repeat. */
  public toggleTabletShortcut(page: FieldTabletPage): void {
    if (this.tabletIsOpen && this.activeTabletPage === page) {
      this.closeTablet();
      return;
    }
    this.openTabletPage(page);
  }

  public closeTablet(): void {
    if (!this.tabletIsOpen) return;
    this.tabletIsOpen = false;
    this.tablet.classList.add('is-hidden');
    this.tablet.setAttribute('aria-hidden', 'true');
    this.root.classList.remove('is-tablet-open');
    this.tabletButton.classList.remove('is-active');
    this.tabletButton.setAttribute('aria-expanded', 'false');
    this.inventoryButton.classList.remove('is-active');
    this.inventoryButton.setAttribute('aria-expanded', 'false');
    for (const button of [
      this.audioSettingsButton,
      this.achievementButton,
      this.radioButton,
      this.debugSettingsButton,
    ]) {
      button.classList.remove('is-active');
      button.setAttribute('aria-expanded', 'false');
    }
    this.actions.onTabletOpenChanged(false);
    this.lastTabletFocus?.focus({ preventScroll: true });
    this.lastTabletFocus = undefined;
  }

  private openTabletPage(page: FieldTabletPage): void {
    const labels: Readonly<Record<FieldTabletPage, readonly [string, string]>> = {
      home: ['GOOD TO SEE YOU', 'FIELD TABLET'],
      inventory: ['FIELD KIT', 'TOOLS + CARRIED PARTS'],
      village: ['VILLAGE REVIVAL', 'WAREHOUSE + PROJECTS'],
      map: [this.tabletMap?.title ?? 'BOREALIS LOCAL CHART', 'MAP'],
      quests: ['QUEST LOG', 'WORK + STORIES'],
      requests: ['REQUESTS + SOS', 'RECEIVED CALLS'],
      radio: ['SHIP RADIO', 'RECEIVER'],
      log: ["CAPTAIN'S LOG", 'CAREER'],
      settings: ['SETTINGS', 'CONTROLS · VISUAL · AUDIO'],
      system: ['SYSTEM', 'TOOLS + SERVICES'],
      dev: ['DEBUG SETTINGS', 'RUNTIME ONLY'],
    };
    this.activeTabletPage = page;
    this.tablet.classList.toggle('is-tlw-menu',this.root.classList.contains('is-wilderness-survival')&&(page==='settings'||page==='dev'));
    this.tablet.setAttribute('aria-label',this.root.classList.contains('is-wilderness-survival')?'The Long Winter menu':'Borealis field tablet');
    this.inventoryButton.classList.toggle('is-active', page === 'inventory');
    this.inventoryButton.setAttribute(
      'aria-expanded',
      String(this.tabletIsOpen && page === 'inventory'),
    );
    this.tabletTitle.textContent = labels[page][0];
    this.tabletSubtitle.textContent = labels[page][1];
    this.tabletPages
      .querySelectorAll<HTMLElement>('[data-tablet-page-panel]')
      .forEach((panel) => {
        panel.classList.toggle(
          'is-hidden',
          panel.dataset.tabletPagePanel !== page,
        );
      });
    this.tabletNavigation.forEach((button) => {
      const selected = button.dataset.tabletPage === page;
      button.classList.toggle('is-active', selected);
      button.setAttribute('aria-current', selected ? 'page' : 'false');
    });
    const pageButtonState: readonly [HTMLButtonElement, FieldTabletPage][] = [
      [this.audioSettingsButton, 'settings'],
      [this.achievementButton, 'log'],
      [this.radioButton, 'radio'],
      [this.debugSettingsButton, 'dev'],
    ];
    pageButtonState.forEach(([button, buttonPage]) => {
      const active = buttonPage === page;
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-expanded', String(active));
    });
    if (!this.tabletIsOpen) {
      this.lastTabletFocus = document.activeElement instanceof HTMLElement
        ? document.activeElement
        : undefined;
      this.tabletIsOpen = true;
      this.tablet.classList.remove('is-hidden');
      this.tablet.setAttribute('aria-hidden', 'false');
      this.root.classList.add('is-tablet-open');
      this.tabletButton.classList.add('is-active');
      this.tabletButton.setAttribute('aria-expanded', 'true');
      this.inventoryButton.setAttribute(
        'aria-expanded',
        String(page === 'inventory'),
      );
      this.actions.onTabletOpenChanged(true);
      window.requestAnimationFrame(() => {
        this.tablet
          .querySelector<HTMLButtonElement>(
            '.drive-tablet-page-header [data-drive-action="close-tablet"]',
          )
          ?.focus({ preventScroll: true });
      });
    }
  }

