  private formatRadioTime(seconds: number): string {
    const totalMinutes = Math.max(
      0,
      Math.floor(seconds / 60),
    );
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    return `T+${String(hours).padStart(2, '0')}:${String(
      minutes,
    ).padStart(2, '0')}`;
  }

  private updateMusicPlayerControls(state: Readonly<{
    trackTitle: string;
    paused: boolean;
    repeat: boolean;
  }>): void {
    this.musicTrackTitle.textContent = state.trackTitle;
    this.musicPlaybackButton.textContent = state.paused
      ? 'PLAY'
      : 'PAUSE';
    this.musicPlaybackButton.setAttribute(
      'aria-label',
      state.paused ? 'Play music' : 'Pause music',
    );
    this.musicPlaybackButton.setAttribute(
      'aria-pressed',
      String(state.paused),
    );
    this.musicRepeatButton.classList.toggle(
      'is-active',
      state.repeat,
    );
    this.musicRepeatButton.setAttribute(
      'aria-pressed',
      String(state.repeat),
    );
  }

  private updateVolumeControl(
    input: HTMLInputElement,
    output: HTMLOutputElement,
    volume: number,
  ): void {
    const normalized = Math.max(0, Math.min(1, volume));
    input.value = normalized.toFixed(2);
    input.style.setProperty(
      '--range-progress',
      `${Math.round(normalized * 100)}%`,
    );
    output.value = `${Math.round(normalized * 100)}%`;
  }
