import { NearestFilter, ShaderMaterial, Vector2, WebGLRenderTarget, type WebGLRenderer } from 'three';
import { FullScreenQuad, Pass } from 'three/examples/jsm/postprocessing/Pass.js';

export interface CelestialDepthMaskSource {
  /** NDC centre and radius on the vertical NDC axis, not world metres. */
  sample(): { sun: Vector2; moon: Vector2; sunRadius: number; moonRadius: number; aspect: number; key: number };
  publish(sun: number, moon: number, key: number): void;
}

/** Optional A/B path. Reuses the actual beauty depth (including animated
 * trees and alpha-tested foliage); never renders the scene a second time.
 * One bounded asynchronous readback, never synchronous readPixels. This
 * measures the disc area, not a branch-resolved screen-space shaft filter. */
export class CelestialDepthMaskPass extends Pass {
  private readonly target = new WebGLRenderTarget(32,32,{minFilter:NearestFilter,magFilter:NearestFilter,depthBuffer:false});
  private readonly material = new ShaderMaterial({
    uniforms: { tDepth:{value:null}, sun:{value:new Vector2()},moon:{value:new Vector2()},
      radii:{value:new Vector2()}, aspect:{value:1} },
    vertexShader:'varying vec2 maskUv; void main(){maskUv=uv;gl_Position=vec4(position.xy,0.,1.);}',
    fragmentShader:`uniform sampler2D tDepth; uniform vec2 sun,moon,radii; uniform float aspect; varying vec2 maskUv;
      float visibility(vec2 centre,float radius,vec2 p){
        vec2 uv=(centre+p*radius/vec2(aspect,1.))*0.5+0.5;
        if(radius<=0.||any(lessThan(uv,vec2(0.)))||any(greaterThan(uv,vec2(1.))))return 0.;
        return step(0.9999998,texture2D(tDepth,uv).r);
      }
      void main(){vec2 p=maskUv*2.-1.; float circle=step(dot(p,p),1.);
        gl_FragColor=vec4(visibility(sun,radii.x,p),visibility(moon,radii.y,p),1.,1.)*circle;}`,
    depthTest:false,depthWrite:false,toneMapped:false,
  });
  private readonly quad = new FullScreenQuad(this.material);
  private pending=false;
  private disposed=false;
  public completedSamples=0;
  public failedSamples=0;
  public lastLatencyMs=0;
  public constructor(private readonly source: CelestialDepthMaskSource) { super(); this.needsSwap=false; }
  public override render(renderer: WebGLRenderer, _write: WebGLRenderTarget, read: WebGLRenderTarget): void {
    if (!read.depthTexture || this.pending || this.disposed) return;
    const state=this.source.sample();
    const u=this.material.uniforms;
    u.tDepth!.value=read.depthTexture;u.sun!.value.copy(state.sun);u.moon!.value.copy(state.moon);
    u.radii!.value.set(state.sunRadius,state.moonRadius);u.aspect!.value=state.aspect;
    const previous=renderer.getRenderTarget();renderer.setRenderTarget(this.target);this.quad.render(renderer);renderer.setRenderTarget(previous);
    this.pending=true; const start=performance.now();
    void renderer.readRenderTargetPixelsAsync(this.target,0,0,32,32,new Uint8Array(32*32*4)).then(data=>{
      if(this.disposed)return;
      let sun=0,moon=0,count=0;
      for(let i=0;i<data.length;i+=4)if(data[i+2]!>0){sun+=data[i]!;moon+=data[i+1]!;count++;}
      this.lastLatencyMs=performance.now()-start;this.completedSamples++;
      if(count>0&&this.lastLatencyMs<120)this.source.publish(sun/(count*255),moon/(count*255),state.key);
    }).catch(()=>{this.failedSamples++;}).finally(()=>{this.pending=false;});
  }
  public override dispose(): void { this.disposed=true;this.quad.dispose();this.material.dispose();this.target.dispose(); }
}
