import {Color,Matrix4,Vector2,Vector3,ShaderMaterial,WebGLRenderTarget,Scene,Mesh,PlaneGeometry,OrthographicCamera,
  type Camera,type DirectionalLight,type WebGLRenderer} from 'three';
import {Pass,FullScreenQuad} from 'three/examples/jsm/postprocessing/Pass.js';

export interface IndoorLightShaftState {
  light:DirectionalLight; centre:Vector3; floor:number; ceiling:number;
}
const vertexShader=`varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}`;
const marchShader=`
  #include <packing>
  varying vec2 vUv;
  uniform sampler2D sceneDepth,shadowDepth;
  uniform mat4 inverseProjection,cameraWorld,shadowMatrix;
  uniform vec3 centre,lightColor;
  uniform float floorY,ceilingY,strength;
  vec3 worldAt(vec2 uv,float d){vec4 p=inverseProjection*vec4(uv*2.-1.,d*2.-1.,1.);return (cameraWorld*vec4(p.xyz/p.w,1.)).xyz;}
  void main(){
    float d=texture2D(sceneDepth,vUv).x;
    vec3 a=worldAt(vUv,0.),b=worldAt(vUv,d),delta=b-a;
    float depth=length(delta),lengthToTrace=min(depth,24.);
    vec3 direction=delta/max(depth,.001),sum=vec3(0.);
    // Static spatial dithering removes visible marching bands without a
    // time-varying shimmer. The coarse result is depth-aware blurred below.
    float jitter=fract(sin(dot(floor(gl_FragCoord.xy),vec2(12.9898,78.233)))*43758.5453);
    for(int i=0;i<16;i++){
      vec3 p=a+direction*((float(i)+jitter)/16.*lengthToTrace);
      float inside=step(floorY,p.y)*step(p.y,ceilingY)*
        (1.-smoothstep(6.,8.,length(p.xz-centre.xz)));
      vec4 projected=shadowMatrix*vec4(p,1.);vec3 q=projected.xyz/projected.w;
      float valid=step(0.,q.x)*step(q.x,1.)*step(0.,q.y)*step(q.y,1.)*step(0.,q.z)*step(q.z,1.);
      float visible=step(q.z-.00008,unpackRGBAToDepth(texture2D(shadowDepth,q.xy)));
      sum+=lightColor*inside*valid*visible*lengthToTrace/16.*strength;
    }
    gl_FragColor=vec4(sum,min(depth/80.,1.));
  }`;
const compositeShader=`
  varying vec2 vUv;uniform sampler2D tDiffuse,shafts,sceneDepth;
  uniform vec2 texel;uniform mat4 inverseProjection;
  float viewDistance(float d){vec4 p=inverseProjection*vec4(vUv*2.-1.,d*2.-1.,1.);return length(p.xyz/p.w);}
  void main(){
    vec4 base=texture2D(tDiffuse,vUv);float depth=min(viewDistance(texture2D(sceneDepth,vUv).x)/80.,1.);
    vec3 sum=vec3(0.);float weight=0.;
    // Depth-aware upsampling prevents shafts bleeding across a foreground wall.
    for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++){
      vec4 s=texture2D(shafts,vUv+vec2(float(x),float(y))*texel);
      float w=exp(-abs(s.a-depth)*600.)/(1.+float(x*x+y*y));sum+=s.rgb*w;weight+=w;
    }
    gl_FragColor=vec4(base.rgb+sum/max(weight,.001),base.a);
  }`;

/** Experimental WebGL path: one quarter-resolution march + one depth-aware
 * composite. Reuses the scene depth and the existing directional shadow map;
 * no extra scene/shadow rendering and no global sunlight modification. */
export class IndoorLightShaftPass extends Pass {
  readonly target=new WebGLRenderTarget(1,1,{depthBuffer:false});
  readonly march=new ShaderMaterial({name:'TLW indoor shafts · 16 samples',depthTest:false,depthWrite:false,toneMapped:false,
    vertexShader,fragmentShader:marchShader,uniforms:{sceneDepth:{value:null},shadowDepth:{value:null},
      inverseProjection:{value:new Matrix4()},cameraWorld:{value:new Matrix4()},shadowMatrix:{value:new Matrix4()},
      centre:{value:new Vector3()},lightColor:{value:new Color()},floorY:{value:0},ceilingY:{value:3},strength:{value:.045}}});
  readonly composite=new ShaderMaterial({name:'TLW indoor shafts · bilateral composite',depthTest:false,depthWrite:false,toneMapped:false,
    vertexShader,fragmentShader:compositeShader,uniforms:{tDiffuse:{value:null},shafts:{value:this.target.texture},sceneDepth:{value:null},
      texel:{value:new Vector2()},inverseProjection:{value:new Matrix4()}}});
  private readonly quad=new FullScreenQuad(this.march);
  private state?:IndoorLightShaftState;
  private camera?:Camera;
  constructor(){super();this.enabled=false;this.target.texture.name='TLW indoor shafts quarter resolution';}
  prewarm(renderer:WebGLRenderer):void {
    const scene=new Scene(),geometry=new PlaneGeometry(2,2),camera=new OrthographicCamera(-1,1,1,-1,0,1);
    scene.add(new Mesh(geometry,this.march),new Mesh(geometry,this.composite));
    renderer.compile(scene,camera);geometry.dispose();
  }
  prepare(camera:Camera,state:IndoorLightShaftState|undefined,enabled:boolean):void {
    this.state=state;this.camera=camera;
    this.enabled=enabled&&!!state?.light.castShadow&&!!state.light.shadow.map&&state.light.intensity>.05;
  }
  setSize(width:number,height:number):void {
    this.target.setSize(Math.max(1,Math.ceil(width/4)),Math.max(1,Math.ceil(height/4)));
    this.composite.uniforms.texel!.value.set(1/this.target.width,1/this.target.height);
  }
  render(renderer:WebGLRenderer,write:WebGLRenderTarget,read:WebGLRenderTarget):void {
    const state=this.state,camera=this.camera;if(!state||!camera||!read.depthTexture)return;
    const u=this.march.uniforms,light=state.light;
    u.sceneDepth!.value=read.depthTexture;u.shadowDepth!.value=light.shadow.map!.texture;
    u.inverseProjection!.value.copy(camera.projectionMatrixInverse);u.cameraWorld!.value.copy(camera.matrixWorld);
    u.shadowMatrix!.value.copy(light.shadow.matrix);u.centre!.value.copy(state.centre);
    u.lightColor!.value.copy(light.color).multiplyScalar(Math.min(2,light.intensity));
    u.floorY!.value=state.floor;u.ceilingY!.value=state.ceiling;
    this.quad.material=this.march;renderer.setRenderTarget(this.target);this.quad.render(renderer);
    this.composite.uniforms.tDiffuse!.value=read.texture;this.composite.uniforms.sceneDepth!.value=read.depthTexture;
    this.composite.uniforms.inverseProjection!.value.copy(camera.projectionMatrixInverse);
    this.quad.material=this.composite;renderer.setRenderTarget(this.renderToScreen?null:write);this.quad.render(renderer);
  }
  dispose():void{this.target.dispose();this.march.dispose();this.composite.dispose();this.quad.dispose();}
}
