import { SurvivalBuildV3Authority, survivalBuildV3Definition,
  type SurvivalBuildV3Environment, type SurvivalBuildV3PlacementEvaluation,
  type SurvivalBuildV3PlacementRequest } from './SurvivalBuildV3Authority';
import { survivalBuildV3AnchorWorldTransform, survivalBuildV3AnchorKey,
  type SurvivalBuildV3AnchorAddress, type SurvivalBuildV3Piece } from './SurvivalBuildV3Model';

export interface SurvivalBuildStrokeRow {
  readonly anchor: SurvivalBuildV3AnchorAddress;
  readonly evaluation: SurvivalBuildV3PlacementEvaluation;
  readonly piece?: SurvivalBuildV3Piece;
  readonly blockedReason?: string;
}

/** A bounded, sequential *preview transaction*. Both the ghost and commit
 * consume these rows. Nothing is added to the live authority while dragging. */
export interface SurvivalBuildStrokePlan {
  readonly sourceToken: object;
  readonly staged: SurvivalBuildV3Authority;
  readonly rows: readonly SurvivalBuildStrokeRow[];
}

export function prepareSurvivalBuildStroke(options: {
  authority: SurvivalBuildV3Authority;
  request: SurvivalBuildV3PlacementRequest;
  start: SurvivalBuildV3AnchorAddress;
  anchors: readonly SurvivalBuildV3AnchorAddress[];
  createSite?: { x: number; y: number; z: number; yawDegrees: number };
  environment?: SurvivalBuildV3Environment;
  block?: (evaluation: SurvivalBuildV3PlacementEvaluation) => string | undefined;
}): SurvivalBuildStrokePlan {
  const sourceToken = options.authority.topologyToken();
  const staged = new SurvivalBuildV3Authority(options.authority.snapshot(), options.environment);
  const siteId = options.createSite ? staged.createSite(options.createSite).id : options.request.siteId;
  const frame = staged.frameForSite(siteId);
  const definition = survivalBuildV3Definition(options.request.definitionId);
  if (!frame || !definition) return { sourceToken, staged, rows: [] };
  const origin = survivalBuildV3AnchorWorldTransform(frame, options.start, definition.role);
  const distance = (anchor: SurvivalBuildV3AnchorAddress): number => {
    const p = survivalBuildV3AnchorWorldTransform(frame, anchor, definition.role);
    return Math.abs(p.x - origin.x) + Math.abs(p.z - origin.z);
  };
  // Outwards from the held anchor even when painting west/north. Sequential
  // support must not depend on whether a sorted grid happens to start far away.
  const anchors = [...new Map(options.anchors.map(a => [survivalBuildV3AnchorKey(a), a])).values()]
    .slice(0, 144).sort((a, b) => distance(a) - distance(b));
  const rows = anchors.map((anchor): SurvivalBuildStrokeRow => {
    const request = { ...options.request, siteId, anchor };
    const evaluation = staged.evaluate(request);
    const blockedReason = options.block?.(evaluation);
    if (blockedReason || evaluation.status === 'BLOCKED') {
      return { anchor, evaluation, blockedReason };
    }
    const result = staged.place(request);
    return result.ok
      ? { anchor, evaluation: result.evaluation, piece: result.piece }
      : { anchor, evaluation: result.evaluation };
  });
  return { sourceToken, staged, rows };
}
