import { survivalBuildDefinition, type SurvivalBuildPieceId } from '../SurvivalBuildingCatalog';

export interface BuildDamageState { readonly version:1; readonly health:readonly number[]; readonly events:readonly string[] }
export interface BuildDamageCell { readonly id:number; readonly x:number; readonly y:number; readonly z:number;
  readonly width:number; readonly height:number; readonly depth:number }
export interface BuildDamageProfile { readonly prefabId:string; readonly cells:readonly BuildDamageCell[];
  readonly columns:number; readonly rows:number; readonly floor:boolean; readonly resistance:number }
const supported=new Set<SurvivalBuildPieceId>(['LOG_WALL_STRAIGHT','TIMBER_PALISADE','TIMBER_FLOOR','STONE_WALL','STONE_FLOOR']);
const profiles=new Map<SurvivalBuildPieceId,BuildDamageProfile>();

/** Authored, stable regions; no runtime cutting or dependence on artist mesh
 * vertex order. Replacement prefabs can supply richer matching region meshes. */
export function buildDamageProfile(id:SurvivalBuildPieceId):BuildDamageProfile|undefined {
  if(!supported.has(id))return undefined;
  const cached=profiles.get(id);if(cached)return cached;
  const d=survivalBuildDefinition(id),floor=id.includes('FLOOR'),stone=id.startsWith('STONE');
  const columns=floor?4:stone?4:5,rows=floor?4:stone?3:4;
  const width=d.halfWidth*2/columns,height=floor?d.height:d.height/rows,depth=floor?d.halfDepth*2/rows:d.halfDepth*2;
  const cells=Array.from({length:columns*rows},(_,i)=>({id:i,
    x:-d.halfWidth+(i%columns+.5)*width,y:floor?d.height/2:(Math.floor(i/columns)+.5)*height,
    z:floor?-d.halfDepth+(Math.floor(i/columns)+.5)*depth:0,width,height,depth}));
  const profile={prefabId:d.prefabId,cells,columns,rows,floor,resistance:stone?2.6:1};profiles.set(id,profile);return profile;
}
export function normaliseBuildDamage(profile:BuildDamageProfile,state:BuildDamageState|undefined):BuildDamageState {
  return {version:1,health:profile.cells.map((_,i)=>state?.version===1&&Number.isFinite(state.health?.[i])
    ? Math.max(0,Math.min(255,Math.round(state.health[i]!))):255),
    events:(Array.isArray(state?.events)?state.events:[]).filter(id=>typeof id==='string'&&id.length<=200).slice(-32)};
}
export function damageCellAt(profile:BuildDamageProfile,p:{x:number;y:number;z:number}):BuildDamageCell|undefined {
  return profile.cells.find(c=>Math.abs(p.x-c.x)<=c.width/2+.005&&Math.abs(p.y-c.y)<=c.height/2+.005&&Math.abs(p.z-c.z)<=c.depth/2+.005);
}
export function applyBuildDamage(profile:BuildDamageProfile,previous:BuildDamageState|undefined,
  point:{x:number;y:number;z:number},power:number,eventId:string):{state:BuildDamageState;broken:readonly number[];changed:boolean} {
  const state=normaliseBuildDamage(profile,previous),cell=damageCellAt(profile,point);
  if(!cell||!Number.isFinite(power)||power<=0||!eventId||state.events.includes(eventId)||state.health[cell.id]===0)
    return {state,broken:[],changed:false};
  const health=[...state.health],before=health[cell.id]!;
  health[cell.id]=Math.max(0,before-Math.max(1,Math.round(power/profile.resistance)));
  return {state:{version:1,health,events:[...state.events,eventId].slice(-32)},
    broken:health[cell.id]===0?[cell.id]:[],changed:true};
}
export function repairBuildDamage(profile:BuildDamageProfile,previous:BuildDamageState):BuildDamageState|undefined {
  const state=normaliseBuildDamage(profile,previous),health=[...state.health];
  const worst=Math.min(...health);if(worst===255)return undefined;
  health[health.indexOf(worst)]=255;
  return health.every(h=>h===255)?undefined:{...state,health};
}
export function buildDamageHasBearing(profile:BuildDamageProfile,state:BuildDamageState|undefined):boolean {
  if(!state)return true;
  if(profile.floor)return state.health.filter(h=>h>0).length>=profile.cells.length*.3;
  // A top plate needs at least one continuous surviving vertical timber/masonry
  // column. Disconnected floating cladding cannot carry a storey.
  return Array.from({length:profile.columns},(_,x)=>x).some(x=>
    Array.from({length:profile.rows},(_,y)=>state.health[y*profile.columns+x]??255).every(h=>h>0));
}
export function buildDamageSolidAt(profile:BuildDamageProfile,state:BuildDamageState|undefined,p:{x:number;y:number;z:number},
  radius=0,actorHeight=0):boolean {
  return profile.cells.some(c=>(state?.health[c.id]??255)>0 &&
    Math.abs(p.x-c.x)<c.width/2+radius && Math.abs(p.z-c.z)<c.depth/2+radius &&
    p.y+actorHeight>c.y-c.height/2+.005 && p.y<c.y+c.height/2-.005);
}
