import {
  survivalBuildV3AnchorKey,
  type SurvivalBuildV3AnchorAddress,
  type SurvivalBuildV3Frame,
  type SurvivalBuildV3Joint,
  type SurvivalBuildV3Piece,
  type SurvivalBuildV3Role,
  type SurvivalBuildV3SaveData,
  type SurvivalBuildV3Site,
} from './SurvivalBuildV3Model';
import { RoofFrameSpatialIndex } from './SurvivalRoofFrame';
import { roofMemberPoints, type ModularRoofMember } from './SurvivalModularRoof';

/**
 * Read-only topology index for Build V3.
 *
 * The save remains the canonical, serialisable state. This index is rebuilt
 * only after topology mutations and lets support/placement queries avoid
 * repeatedly scanning — or cloning — the complete save graph.
 */
export class SurvivalBuildV3StateIndex {
  private readonly sitesById = new Map<string, SurvivalBuildV3Site>();
  private readonly sitePositionsById = new Map<string, number>();
  private readonly framesById = new Map<string, SurvivalBuildV3Frame>();
  private readonly piecesById = new Map<string, SurvivalBuildV3Piece>();
  private readonly piecesBySiteRole = new Map<string, SurvivalBuildV3Piece[]>();
  private readonly piecesBySiteRoleAnchor = new Map<string, SurvivalBuildV3Piece[]>();
  private readonly jointsById = new Map<string, SurvivalBuildV3Joint>();
  private readonly jointPositionsById = new Map<string, number>();
  private readonly jointsByPieceId = new Map<string, SurvivalBuildV3Joint[]>();
  private readonly piecesByOccupancy = new Map<string, SurvivalBuildV3Piece[]>();
  private readonly roofDependentsById = new Map<string, string[]>();
  private readonly roofSpatialBySite = new Map<string, RoofFrameSpatialIndex>();

  public constructor(
    save: Readonly<SurvivalBuildV3SaveData>,
    occupancyKeyForPiece: (piece: Readonly<SurvivalBuildV3Piece>) => string,
  ) {
    save.sites.forEach((site, index) => {
      this.sitesById.set(site.id, site);
      this.sitePositionsById.set(site.id, index);
    });
    for (const frame of save.frames) this.framesById.set(frame.id, frame);
    for (const piece of save.pieces) {
      this.piecesById.set(piece.id, piece);
      for (const support of piece.roofMember?.supports ?? []) append(this.roofDependentsById, support, piece.id);
      append(this.piecesBySiteRole, siteRoleKey(piece.siteId, piece.role), piece);
      append(
        this.piecesBySiteRoleAnchor,
        siteRoleAnchorKey(piece.siteId, piece.role, piece.anchor),
        piece,
      );
      append(this.piecesByOccupancy, occupancyKeyForPiece(piece), piece);
    }
    save.joints.forEach((joint, index) => {
      this.jointsById.set(joint.id, joint);
      this.jointPositionsById.set(joint.id, index);
      for (const member of joint.members) {
        append(this.jointsByPieceId, member.pieceId, joint);
      }
    });
  }

  public get pieceCount(): number {
    return this.piecesById.size;
  }

  public roofDependents(pieceId: string): readonly string[] {
    return this.roofDependentsById.get(pieceId) ?? [];
  }

  public get jointCount(): number {
    return this.jointsById.size;
  }

  public site(siteId: string): SurvivalBuildV3Site | undefined {
    return this.sitesById.get(siteId);
  }

  public sitePosition(siteId: string): number | undefined {
    return this.sitePositionsById.get(siteId);
  }

  public frame(frameId: string): SurvivalBuildV3Frame | undefined {
    return this.framesById.get(frameId);
  }

  public piece(pieceId: string): SurvivalBuildV3Piece | undefined {
    return this.piecesById.get(pieceId);
  }

  public piecesForRole(siteId: string, role: SurvivalBuildV3Role): readonly SurvivalBuildV3Piece[] {
    return this.piecesBySiteRole.get(siteRoleKey(siteId, role)) ?? [];
  }

  public piecesForSite(siteId: string): readonly SurvivalBuildV3Piece[] {
    return (this.site(siteId)?.pieceIds ?? []).flatMap(id=>this.piece(id)?[this.piece(id)!]:[]);
  }

  public roofCandidates(siteId:string,frame:SurvivalBuildV3Frame,member:ModularRoofMember):readonly SurvivalBuildV3Piece[]{
    let index=this.roofSpatialBySite.get(siteId);
    if(!index){index=new RoofFrameSpatialIndex(frame,this.piecesForSite(siteId));this.roofSpatialBySite.set(siteId,index);}
    return index.near(roofMemberPoints(member));
  }

  public piecesAt(
    siteId: string,
    role: SurvivalBuildV3Role,
    anchor: Readonly<SurvivalBuildV3AnchorAddress>,
  ): readonly SurvivalBuildV3Piece[] {
    return this.piecesBySiteRoleAnchor.get(siteRoleAnchorKey(siteId, role, anchor)) ?? [];
  }

  public joint(jointId: string): SurvivalBuildV3Joint | undefined {
    return this.jointsById.get(jointId);
  }

  public jointPosition(jointId: string): number | undefined {
    return this.jointPositionsById.get(jointId);
  }

  public jointsForPiece(pieceId: string): readonly SurvivalBuildV3Joint[] {
    return this.jointsByPieceId.get(pieceId) ?? [];
  }

  public piecesOccupying(occupancyKey: string): readonly SurvivalBuildV3Piece[] {
    return this.piecesByOccupancy.get(occupancyKey) ?? [];
  }

  /** Placement-only fast path. Removal/restore still rebuild the full index. */
  public replaceSite(site: SurvivalBuildV3Site): void {
    this.sitesById.set(site.id, site);
  }

  public addPiece(
    piece: SurvivalBuildV3Piece,
    occupancyKey: string,
  ): void {
    this.roofSpatialBySite.delete(piece.siteId);
    this.piecesById.set(piece.id, piece);
    for (const support of piece.roofMember?.supports ?? []) append(this.roofDependentsById, support, piece.id);
    append(this.piecesBySiteRole, siteRoleKey(piece.siteId, piece.role), piece);
    append(
      this.piecesBySiteRoleAnchor,
      siteRoleAnchorKey(piece.siteId, piece.role, piece.anchor),
      piece,
    );
    append(this.piecesByOccupancy, occupancyKey, piece);
  }

  public upsertJoint(joint: SurvivalBuildV3Joint, position: number): void {
    const previous = this.jointsById.get(joint.id);
    if (previous) {
      for (const member of previous.members) {
        const memberships = this.jointsByPieceId.get(member.pieceId);
        if (!memberships) continue;
        const filtered = memberships.filter((candidate) => candidate.id !== joint.id);
        if (filtered.length > 0) this.jointsByPieceId.set(member.pieceId, filtered);
        else this.jointsByPieceId.delete(member.pieceId);
      }
    }
    this.jointsById.set(joint.id, joint);
    this.jointPositionsById.set(joint.id, position);
    for (const member of joint.members) {
      append(this.jointsByPieceId, member.pieceId, joint);
    }
  }
}

const append = <T>(map: Map<string, T[]>, key: string, value: T): void => {
  const values = map.get(key);
  if (values) values.push(value);
  else map.set(key, [value]);
};

const siteRoleKey = (siteId: string, role: SurvivalBuildV3Role): string =>
  `${siteId}:${role}`;

const siteRoleAnchorKey = (
  siteId: string,
  role: SurvivalBuildV3Role,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
): string => `${siteRoleKey(siteId, role)}:${survivalBuildV3AnchorKey(anchor)}`;
