import { clamp } from '../utils/math';

export interface VirtualStickValue {
  readonly right: number;
  readonly forward: number;
}

export const resolveVirtualStickValue = (
  offsetX: number,
  offsetY: number,
  radius: number,
  deadZone = 0.08,
): VirtualStickValue => {
  if (![offsetX, offsetY, radius, deadZone].every(Number.isFinite) || radius <= 0) {
    return { right: 0, forward: 0 };
  }
  const x = offsetX / radius;
  const y = offsetY / radius;
  const length = Math.hypot(x, y);
  if (length <= deadZone) return { right: 0, forward: 0 };
  const scale = Math.min(1, length) / length;
  const right = clamp(x * scale, -1, 1);
  const forward = clamp(-y * scale, -1, 1);
  return {
    right: Object.is(right, -0) ? 0 : right,
    forward: Object.is(forward, -0) ? 0 : forward,
  };
};

export class VirtualStickInput {
  private pointerId?: number;
  private value: VirtualStickValue = { right: 0, forward: 0 };
  private readonly thumb: HTMLElement;

  public constructor(
    private readonly element: HTMLElement,
    private readonly onChange: (value: Readonly<VirtualStickValue>) => void,
  ) {
    const thumb = element.querySelector<HTMLElement>('[data-stick-thumb]');
    if (!thumb) throw new Error('Virtual stick thumb is missing.');
    this.thumb = thumb;
    element.addEventListener('pointerdown', this.onPointerDown);
    element.addEventListener('pointermove', this.onPointerMove);
    element.addEventListener('pointerup', this.onPointerEnd);
    element.addEventListener('pointercancel', this.onPointerEnd);
    element.addEventListener('keydown', this.onKeyDown);
    element.addEventListener('keyup', this.onKeyUp);
  }

  public reset(): void {
    this.pointerId = undefined;
    this.apply({ right: 0, forward: 0 });
  }

  public dispose(): void {
    this.reset();
    this.element.removeEventListener('pointerdown', this.onPointerDown);
    this.element.removeEventListener('pointermove', this.onPointerMove);
    this.element.removeEventListener('pointerup', this.onPointerEnd);
    this.element.removeEventListener('pointercancel', this.onPointerEnd);
    this.element.removeEventListener('keydown', this.onKeyDown);
    this.element.removeEventListener('keyup', this.onKeyUp);
  }

  private onPointerDown = (event: PointerEvent): void => {
    if (this.pointerId !== undefined) return;
    event.preventDefault();
    this.pointerId = event.pointerId;
    this.element.setPointerCapture?.(event.pointerId);
    this.updatePointer(event);
  };

  private onPointerMove = (event: PointerEvent): void => {
    if (event.pointerId !== this.pointerId) return;
    event.preventDefault();
    this.updatePointer(event);
  };

  private onPointerEnd = (event: PointerEvent): void => {
    if (event.pointerId !== this.pointerId) return;
    this.reset();
  };

  private updatePointer(event: PointerEvent): void {
    const bounds = this.element.getBoundingClientRect();
    const radius = Math.max(1, Math.min(bounds.width, bounds.height) * 0.36);
    this.apply(resolveVirtualStickValue(
      event.clientX - (bounds.left + bounds.width / 2),
      event.clientY - (bounds.top + bounds.height / 2),
      radius,
    ));
  }

  private onKeyDown = (event: KeyboardEvent): void => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.code)) return;
    event.preventDefault();
    this.apply({
      right: event.code === 'ArrowLeft' ? -1 : event.code === 'ArrowRight' ? 1 : 0,
      forward: event.code === 'ArrowDown' ? -1 : event.code === 'ArrowUp' ? 1 : 0,
    });
  };

  private onKeyUp = (event: KeyboardEvent): void => {
    if (event.code.startsWith('Arrow')) this.reset();
  };

  private apply(value: Readonly<VirtualStickValue>): void {
    this.value = { ...value };
    this.thumb.style.transform =
      `translate(${(value.right * 34).toFixed(1)}px, ${(-value.forward * 34).toFixed(1)}px)`;
    this.element.setAttribute('aria-valuetext',
      `right ${value.right.toFixed(2)}, forward ${value.forward.toFixed(2)}`);
    this.onChange(this.value);
  }
}
