  public getRadioTowerRepairViews(
    portId?: string,
  ): readonly RadioTowerRepairView[] {
    const networkState = this.radio.getNetworkState();
    const towerStates = new Map(
      networkState.towerStates.map((state) => [
        state.towerId,
        state.state,
      ]),
    );
    return this.radioTowerRepairs
      .getDefinitions()
      .filter(
        (definition) =>
          !portId || definition.servicePortId === portId,
      )
      .flatMap((definition) => {
        const tower = this.radioNetwork.getTower(
          definition.towerId,
        );
        if (!tower) return [];
        const mission = this.missions.getState(
          definition.missionId,
        );
        return [
          this.radioTowerRepairs.createView(
            definition,
            mission?.status,
            this.outcomes.getState(definition.outcomeId),
            towerStates.get(definition.towerId) ??
              tower.initialState,
            tower.worldPosition,
          ),
        ];
      });
  }

  public repairRadioTower(
    repairId: string,
    portId: string,
  ): WorldRadioTowerRepairResult {
    const definition =
      this.radioTowerRepairs.getDefinition(repairId);
    const mission = definition
      ? this.missions.getState(definition.missionId)
      : undefined;
    const outcome = definition
      ? this.outcomes.getState(definition.outcomeId)
      : undefined;
    const check = this.radioTowerRepairs.checkRepair(
      repairId,
      portId,
      mission?.status,
      outcome?.state,
    );
    if (!check.accepted || !check.definition) {
      return {
        success: false,
        repairId,
        reason: check.reason,
      };
    }

    const repair = check.definition;
    const sourceEventId =
      `radio-tower:${repair.towerId}:` +
      `component:${repair.componentId}:installed`;
    const outcomeResult = this.outcomes.transition(
      repair.outcomeId,
      'ONLINE',
      this.simulationTime,
      sourceEventId,
    );
    if (!outcomeResult.changed) {
      return {
        success: false,
        repairId,
        reason: 'ALREADY_REPAIRED',
      };
    }

    this.radio.setTowerState(repair.towerId, 'ONLINE');
    this.radio.discoverFrequency(
      repair.frequencyId,
      this.simulationTime,
      'TOWER_REPAIR',
    );
    const frequency = this.radioNetwork.getFrequency(
      repair.frequencyId,
    );
    if (frequency) {
      this.radio.setDialFrequencyMhz(
        frequency.frequencyMhz,
      );
    }
    const componentEvent: WorldContributionEvent = {
      type: 'SPECIAL_COMPONENT_DELIVERED',
      eventId: sourceEventId,
      occurredAt: this.simulationTime,
      source: 'PLAYER',
      portId: repair.servicePortId,
      componentId: repair.componentId,
      targetRefs: [
        worldTarget.port(repair.servicePortId),
        worldTarget.object(
          `radio-tower:${repair.towerId}`,
        ),
      ],
    };
    const missionResult = this.missions.update(
      this.simulationTime,
      this.missionWorldSnapshot(),
      [componentEvent],
      [componentEvent],
    );
    const missionCompletionEvents: WorldContributionEvent[] =
      missionResult.contributionEvents.map((event) => ({
        ...event,
        targetRefs:
          event.type === 'MISSION_COMPLETED'
            ? this.missionTargetRefs(event.missionId)
            : event.targetRefs,
      }));
    const domainEvents: WorldDomainEvent[] = [
      componentEvent,
      ...(outcomeResult.event
        ? [outcomeResult.event]
        : []),
      ...missionCompletionEvents,
    ];
    const contributionEvents = domainEvents.filter(
      isWorldContributionEvent,
    );
    this.radio.process(domainEvents, this.simulationTime);
    const rewardResult = this.rewards.process(
      contributionEvents,
    );
    for (const reward of rewardResult.rewards) {
      if (reward.unlockedUpgradeId) {
        this.upgrades.unlockAvailability(
          reward.unlockedUpgradeId,
        );
      }
    }
    this.upgrades.refreshAvailability({
      discoveredPortIds: this.discoveredPortIds,
      discoveredPoiIds: this.discoveredPoiIds,
      activeGoodsFlows: this.activeGoodsFlows(),
      portStates: this.ports.getStates(),
    });
    return {
      success: true,
      repairId,
      displayName: repair.displayName,
      componentDisplayName:
        repair.componentDisplayName,
      frequencyMhz: frequency?.frequencyMhz,
      contributionEvents,
      domainEvents,
      completedMissionIds:
        missionResult.completedMissionIds,
    };
  }

