  public restoreLighthouse(
    restorationId: string,
    portId: string,
  ): WorldLighthouseRestorationResult {
    const definition =
      this.lighthouseRestorations.getDefinition(
        restorationId,
      );
    const mission = definition
      ? this.missions.getState(definition.missionId)
      : undefined;
    const outcome = definition
      ? this.outcomes.getState(definition.outcomeId)
      : undefined;
    const check =
      this.lighthouseRestorations.checkRestoration(
        restorationId,
        portId,
        mission?.status,
        outcome?.state,
      );
    if (!check.accepted || !check.definition) {
      return {
        success: false,
        restorationId,
        reason: check.reason,
      };
    }

    const restoration = check.definition;
    const sourceEventId =
      `lighthouse:${restoration.poiId}:` +
      `component:${restoration.componentId}:installed`;
    const outcomeResult = this.outcomes.transition(
      restoration.outcomeId,
      'LIT',
      this.simulationTime,
      sourceEventId,
    );
    if (!outcomeResult.changed) {
      return {
        success: false,
        restorationId,
        reason: 'ALREADY_RESTORED',
      };
    }
    const componentEvent: WorldContributionEvent = {
      type: 'SPECIAL_COMPONENT_DELIVERED',
      eventId: sourceEventId,
      occurredAt: this.simulationTime,
      source: 'PLAYER',
      portId: restoration.servicePortId,
      componentId: restoration.componentId,
      targetRefs: [
        worldTarget.port(restoration.servicePortId),
        worldTarget.poi(restoration.poiId),
      ],
    };
    const missionResult = this.missions.update(
      this.simulationTime,
      this.missionWorldSnapshot(),
      [componentEvent],
      [componentEvent],
    );
    const missionCompletionEvents: WorldContributionEvent[] =
      missionResult.contributionEvents.map((event) => ({
        ...event,
        targetRefs:
          event.type === 'MISSION_COMPLETED'
            ? this.missionTargetRefs(event.missionId)
            : event.targetRefs,
      }));
    const domainEvents: WorldDomainEvent[] = [
      componentEvent,
      ...(outcomeResult.event ? [outcomeResult.event] : []),
      ...missionCompletionEvents,
    ];
    const contributionEvents = domainEvents.filter(
      isWorldContributionEvent,
    );
    this.radio.process(domainEvents, this.simulationTime);
    const rewardResult = this.rewards.process(
      contributionEvents,
    );
    for (const reward of rewardResult.rewards) {
      if (reward.unlockedUpgradeId) {
        this.upgrades.unlockAvailability(
          reward.unlockedUpgradeId,
        );
      }
    }
    return {
      success: true,
      restorationId,
      displayName: restoration.displayName,
      componentDisplayName:
        restoration.componentDisplayName,
      revealedChartId: restoration.revealId,
      contributionEvents,
      domainEvents,
      completedMissionIds:
        missionResult.completedMissionIds,
    };
  }

