  public purchaseUpgradeAtPort(
    upgradeId: string,
    portId: string,
  ): WorldUpgradePurchaseResult {
    const definition = this.registry.getUpgrade(upgradeId);
    const port = this.ports.getState(portId);
    if (
      !definition ||
      !port ||
      (
        definition.requiredPortId &&
        definition.requiredPortId !== portId
      ) ||
      (
        definition.requiredService &&
        !port.unlockedServices.includes(
          definition.requiredService,
        )
      )
    ) {
      return {
        success: false,
        cost: definition?.price ?? 0,
        moneyRemaining: this.rewards.getMoney(),
        reason: definition ? 'INVALID_DOCK' : 'UNKNOWN_UPGRADE',
      };
    }
    const result = this.upgrades.purchase(
      upgradeId,
      this.rewards.getMoney(),
    );
    if (result.success) {
      this.rewards.spendMoney(result.cost);
      this.synchronizeRadioReceiverUpgrades();
      this.refreshMissionOffers();
    }
    return {
      ...result,
      moneyRemaining: this.rewards.getMoney(),
    };
  }

  public refitModulesAtPort(
    moduleIds: readonly string[],
    portId: string,
    shipId: string,
  ): RefitResult {
    const ship = this.registry.getShip(shipId);
    if (!ship) {
      return { success: false, reason: 'INVALID_DOCK' };
    }
    const result = this.upgrades.refit(
      moduleIds,
      this.ports.getState(portId),
      ship,
    );
    if (result.success) {
      this.synchronizeRadioReceiverUpgrades();
    }
    return result;
  }

