import { clamp } from '../../utils/math';
import type { WorldContributionEvent } from '../events/WorldContributionEvent';

export interface ContributionReward {
  eventId: string;
  type: WorldContributionEvent['type'];
  money: number;
  portId?: string;
  portProgress: number;
  unlockedUpgradeId?: string;
}

export interface ContributionRewardSaveData {
  version: 1;
  money: number;
  rewardedEventIds: string[];
  unlockedUpgradeIds: string[];
  portProgress: Record<string, number>;
}

export interface ContributionRewardResult {
  rewards: ContributionReward[];
  moneyAwarded: number;
}

const rewardFor = (
  event: Readonly<WorldContributionEvent>,
): ContributionReward => {
  switch (event.type) {
    case 'ROUTE_OPENED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: 110,
        portProgress: 0.08,
      };
    case 'ROUTE_SERVICED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: Math.round(
          25 + clamp(event.improvement, 0, 1) * 120,
        ),
        portProgress: clamp(event.improvement * 0.08, 0, 0.08),
      };
    case 'SHIP_RESCUED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: 180,
        portProgress: 0.06,
      };
    case 'SHIP_ESCORTED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: 145,
        portProgress: 0.05,
      };
    case 'POI_DISCOVERED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: 95,
        portProgress: 0.03,
      };
    case 'UPGRADE_PART_RECOVERED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: 80,
        portProgress: 0.03,
      };
    case 'SPECIAL_COMPONENT_DELIVERED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: 165,
        portId: event.portId,
        portProgress: 0.08,
      };
    case 'PORT_ACCESS_IMPROVED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: Math.round(
          20 + clamp(event.improvement, 0, 1) * 100,
        ),
        portId: event.portId,
        portProgress: clamp(event.improvement * 0.1, 0, 0.1),
      };
    case 'PORT_CLEARED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: 0,
        portId: event.portId,
        portProgress: 0.12,
      };
    case 'MISSION_COMPLETED':
      return {
        eventId: event.eventId,
        type: event.type,
        money: Math.max(0, Math.round(event.rewardMoney)),
        portProgress: 0.06,
        unlockedUpgradeId: event.rewardUpgradeId,
      };
  }
};

export class ContributionRewardSystem {
  private money: number;
  private readonly rewardedEventIds = new Set<string>();
  private readonly unlockedUpgradeIds = new Set<string>();
  private readonly portProgress = new Map<string, number>();

  public constructor(
    initialMoney = 0,
    saved?: Readonly<ContributionRewardSaveData>,
  ) {
    this.money = Math.max(0, initialMoney);
    if (saved) this.importState(saved);
  }

  public process(
    events: readonly WorldContributionEvent[],
  ): ContributionRewardResult {
    const rewards: ContributionReward[] = [];
    let moneyAwarded = 0;
    for (const event of events) {
      if (
        !event.eventId ||
        this.rewardedEventIds.has(event.eventId)
      ) {
        continue;
      }
      this.rewardedEventIds.add(event.eventId);
      const reward = rewardFor(event);
      this.money += reward.money;
      moneyAwarded += reward.money;
      if (reward.unlockedUpgradeId) {
        this.unlockedUpgradeIds.add(
          reward.unlockedUpgradeId,
        );
      }
      if (reward.portId && reward.portProgress > 0) {
        this.portProgress.set(
          reward.portId,
          clamp(
            (this.portProgress.get(reward.portId) ?? 0) +
              reward.portProgress,
            0,
            1,
          ),
        );
      }
      rewards.push(reward);
    }
    return { rewards, moneyAwarded };
  }

  public getMoney(): number {
    return this.money;
  }

  /** Explicit economy ingress used by rewards and gated playtest tools. */
  public grantMoney(amount: number): number {
    const granted = Math.max(
      0,
      Number.isFinite(amount) ? Math.floor(amount) : 0,
    );
    this.money += granted;
    return granted;
  }

  public spendMoney(amount: number): boolean {
    const cost = Math.max(
      0,
      Number.isFinite(amount) ? amount : 0,
    );
    if (cost > this.money) return false;
    this.money -= cost;
    return true;
  }

  public hasUnlockedUpgrade(upgradeId: string): boolean {
    return this.unlockedUpgradeIds.has(upgradeId);
  }

  public getPortProgress(portId: string): number {
    return this.portProgress.get(portId) ?? 0;
  }

  public exportState(): ContributionRewardSaveData {
    return {
      version: 1,
      money: this.money,
      rewardedEventIds: [...this.rewardedEventIds],
      unlockedUpgradeIds: [...this.unlockedUpgradeIds],
      portProgress: Object.fromEntries(this.portProgress),
    };
  }

  public importState(
    saved: Readonly<ContributionRewardSaveData>,
  ): boolean {
    if (
      saved.version !== 1 ||
      !Array.isArray(saved.rewardedEventIds) ||
      !Array.isArray(saved.unlockedUpgradeIds)
    ) {
      return false;
    }
    this.money = Math.max(
      0,
      Number.isFinite(saved.money) ? saved.money : 0,
    );
    this.rewardedEventIds.clear();
    for (const id of saved.rewardedEventIds) {
      if (typeof id === 'string' && id) {
        this.rewardedEventIds.add(id);
      }
    }
    this.unlockedUpgradeIds.clear();
    for (const id of saved.unlockedUpgradeIds) {
      if (typeof id === 'string' && id) {
        this.unlockedUpgradeIds.add(id);
      }
    }
    this.portProgress.clear();
    for (const [portId, progress] of Object.entries(
      saved.portProgress ?? {},
    )) {
      if (Number.isFinite(progress)) {
        this.portProgress.set(
          portId,
          clamp(progress, 0, 1),
        );
      }
    }
    return true;
  }
}
