import './styles.css';
import './construction/construction.css';
import './land/world-editor.css';
import './authoring/content-authoring.css';
import './land/land-expedition.css';
import './multiplayer/multiplayer-ui.css';
import './world/generation/world-generation-lab.css';
import { Game } from './core/Game';
import { SaveSystem } from './game/SaveSystem';
import { initializeBorealisLandRaster } from './land/BorealisLand';
import { initializeGeneratedWorld } from './world/generation/GeneratedWorldRuntime';
import { trackStartupAssetLoads, yieldWarmup } from './rendering/ShaderWarmup';

const root = document.querySelector<HTMLElement>('#app');
if (!root) throw new Error('ICEWAY could not find the #app root element.');
const loading = document.querySelector<HTMLElement>('#startup-loading')!;
const progress = (message: string): void => { loading.querySelector('[role="status"]')!.textContent = message; };
root.inert = true;
// Registered before game input handlers. Loading must not activate tools or
// let held keys accumulate movement while no simulation frames are running.
const blockInput = (event: Event): void => {
  if (event instanceof KeyboardEvent && (event.metaKey || event.ctrlKey || event.key === 'F5')) return;
  event.stopImmediatePropagation();
};
const inputEvents = ['keydown', 'keyup', 'pointerdown', 'pointerup', 'wheel'] as const;
for (const type of inputEvents) window.addEventListener(type, blockInput, { capture: true });
const assets = trackStartupAssetLoads();

try {
  await Promise.all([
    initializeBorealisLandRaster(),
    initializeGeneratedWorld(),
  ]);
} catch (error) {
  console.warn(
    'ICE-A-WAY authored/generated world data could not be loaded. Using deterministic fallbacks.',
    error,
  );
}

const game = new Game(root, await new SaveSystem().loadAsync());

window.addEventListener('beforeunload', () => game.dispose(), { once: true });
try {
  progress('Loading the world, models & textures');
  const loaded = await assets.wait();
  game.startupWarmup.assetsComplete = loaded;
  if (!loaded) console.warn('Some startup assets are still loading. Their authored fallbacks remain available.');
  await game.prepareStartupShaders(progress);
  // Keep the cover for the first live presentation updates too: animation,
  // snow ownership and instanced presenters create their first view here.
  await game.startRendering();
  await yieldWarmup();
} catch (error) {
  console.warn('Initial presentation preparation incomplete.', error);
} finally {
  assets.dispose();
  root.inert = false;
  for (const type of inputEvents) window.removeEventListener(type, blockInput, { capture: true });
  loading.remove();
}
