import type {
  PortState,
} from '../definitions/GameplayTypes';
import type { WorldDomainEvent } from '../events/WorldDomainEvent';
import type { MerchantShipRuntimeState } from '../simulation/MerchantShippingSystem';
import { worldTarget } from '../world/WorldTarget';

export interface RadioWeatherObservation {
  kind:
    | 'clear'
    | 'overcast'
    | 'light-snow'
    | 'fog'
    | 'strong-wind'
    | 'snowstorm';
  windMultiplier: number;
  fogDensity: number;
  snowIntensity: number;
  refreezeMultiplier: number;
}

export interface RadioProgrammingSaveData {
  version: 1;
  sequence: number;
  lastWeatherSignature?: string;
  lastWeatherAt: number;
  lastLocalNoticeAt: number;
  shipStatusSignatures: {
    shipId: string;
    signature: string;
  }[];
  mysteryBroadcastEmitted?: boolean;
}

const WEATHER_INTERVAL_SECONDS = 180;
const LOCAL_NOTICE_INTERVAL_SECONDS = 240;

const finiteTime = (value: unknown): number =>
  Number.isFinite(value) ? Math.max(0, Number(value)) : 0;

export class RadioProgrammingSystem {
  private sequence = 0;
  private lastWeatherSignature?: string;
  private lastWeatherAt = -WEATHER_INTERVAL_SECONDS;
  private lastLocalNoticeAt = -LOCAL_NOTICE_INTERVAL_SECONDS;
  private readonly shipStatusSignatures = new Map<
    string,
    string
  >();
  private mysteryBroadcastEmitted = false;

  public constructor(
    saved?: Readonly<RadioProgrammingSaveData>,
  ) {
    if (saved?.version !== 1) return;
    this.sequence = Math.floor(
      finiteTime(saved.sequence),
    );
    this.lastWeatherSignature =
      typeof saved.lastWeatherSignature === 'string'
        ? saved.lastWeatherSignature
        : undefined;
    this.lastWeatherAt = finiteTime(saved.lastWeatherAt);
    this.lastLocalNoticeAt = finiteTime(
      saved.lastLocalNoticeAt,
    );
    this.mysteryBroadcastEmitted =
      saved.mysteryBroadcastEmitted === true;
    for (const entry of saved.shipStatusSignatures ?? []) {
      if (
        typeof entry?.shipId === 'string' &&
        entry.shipId.trim() &&
        typeof entry.signature === 'string' &&
        entry.signature.trim()
      ) {
        this.shipStatusSignatures.set(
          entry.shipId,
          entry.signature,
        );
      }
    }
  }

  public update(
    simulationTime: number,
    weather: Readonly<RadioWeatherObservation> | undefined,
    ports: readonly Readonly<PortState>[],
    ships: readonly Readonly<MerchantShipRuntimeState>[],
    outcomes: readonly Readonly<{
      outcomeId: string;
      state: string;
    }>[] = [],
  ): readonly WorldDomainEvent[] {
    const time = Math.max(0, simulationTime);
    const events: WorldDomainEvent[] = [];
    const weatherEvent = this.weatherEvent(time, weather);
    if (weatherEvent) events.push(weatherEvent);
    const localEvent = this.localNoticeEvent(time, ports);
    if (localEvent) events.push(localEvent);
    events.push(...this.openBandEvents(time, ships));
    const mysteryEvent = this.mysteryEvent(time, outcomes);
    if (mysteryEvent) events.push(mysteryEvent);
    return events;
  }

  public exportState(): RadioProgrammingSaveData {
    return {
      version: 1,
      sequence: this.sequence,
      lastWeatherSignature: this.lastWeatherSignature,
      lastWeatherAt: Math.max(0, this.lastWeatherAt),
      lastLocalNoticeAt: Math.max(0, this.lastLocalNoticeAt),
      shipStatusSignatures: [
        ...this.shipStatusSignatures,
      ].map(([shipId, signature]) => ({
        shipId,
        signature,
      })),
      mysteryBroadcastEmitted:
        this.mysteryBroadcastEmitted,
    };
  }

  private weatherEvent(
    time: number,
    weather: Readonly<RadioWeatherObservation> | undefined,
  ): WorldDomainEvent | undefined {
    if (!weather) return undefined;
    const signature = [
      weather.kind,
      Math.round(weather.windMultiplier * 4),
      Math.round(weather.fogDensity * 200),
      Math.round(weather.snowIntensity * 4),
      Math.round(weather.refreezeMultiplier * 4),
    ].join(':');
    const changed = signature !== this.lastWeatherSignature;
    if (
      !changed &&
      time - this.lastWeatherAt <
        WEATHER_INTERVAL_SECONDS
    ) {
      return undefined;
    }
    this.lastWeatherSignature = signature;
    this.lastWeatherAt = time;
    this.sequence += 1;
    return {
      type: 'WEATHER_REPORT_UPDATED',
      eventId: `radio-program:weather:${this.sequence}`,
      occurredAt: time,
      source: 'WORLD_SIMULATION',
      regionId: 'prototype-archipelago',
      weatherKind: weather.kind,
      windMultiplier: weather.windMultiplier,
      fogDensity: weather.fogDensity,
      snowIntensity: weather.snowIntensity,
      refreezeMultiplier: weather.refreezeMultiplier,
    };
  }

  private localNoticeEvent(
    time: number,
    ports: readonly Readonly<PortState>[],
  ): WorldDomainEvent | undefined {
    if (
      time - this.lastLocalNoticeAt <
        LOCAL_NOTICE_INTERVAL_SECONDS
    ) {
      return undefined;
    }
    const ember = ports.find(
      (port) => port.portId === 'ember',
    );
    if (!ember) return undefined;
    this.lastLocalNoticeAt = time;
    this.sequence += 1;
    const noticeCode =
      ember.supplySatisfaction < 0.42
        ? 'SUPPLY_LOW'
        : ember.traffic > 0.58
          ? 'PORT_BUSY'
          : ember.developmentProgress > 0.55
            ? 'PORT_GROWING'
            : 'OPERATIONS_NORMAL';
    return {
      type: 'LOCAL_PORT_NOTICE',
      eventId: `radio-program:local:${this.sequence}`,
      occurredAt: time,
      source: 'WORLD_SIMULATION',
      portId: ember.portId,
      noticeCode,
      supplySatisfaction: ember.supplySatisfaction,
      traffic: ember.traffic,
      developmentProgress: ember.developmentProgress,
      targetRefs: [worldTarget.port(ember.portId)],
    };
  }

  private openBandEvents(
    time: number,
    ships: readonly Readonly<MerchantShipRuntimeState>[],
  ): readonly WorldDomainEvent[] {
    const events: WorldDomainEvent[] = [];
    for (const ship of ships) {
      const routeId =
        ship.routePlan[ship.routeIndex] ??
        ship.routePlan[ship.routePlan.length - 1];
      const signature = [
        ship.status,
        routeId ?? 'none',
        ship.destinationPortId,
        ship.tripId ?? 'none',
      ].join(':');
      const previous =
        this.shipStatusSignatures.get(ship.shipId);
      this.shipStatusSignatures.set(
        ship.shipId,
        signature,
      );
      if (
        previous === undefined ||
        previous === signature ||
        !routeId ||
        !ship.activated ||
        ![
          'TRAVELLING_FAR',
          'WAITING_FOR_CHANNEL',
          'STUCK_ASSISTANCE',
          'ARRIVING',
        ].includes(ship.status)
      ) {
        continue;
      }
      this.sequence += 1;
      events.push({
        type: 'OPEN_BAND_TRAFFIC',
        eventId:
          `radio-program:open:${ship.shipId}:` +
          `${this.sequence}`,
        occurredAt: time,
        source: 'WORLD_SIMULATION',
        shipId: ship.shipId,
        routeId,
        destinationPortId: ship.destinationPortId,
        navigationStatus: ship.status as
          | 'TRAVELLING_FAR'
          | 'WAITING_FOR_CHANNEL'
          | 'STUCK_ASSISTANCE'
          | 'ARRIVING',
        targetRefs: [
          worldTarget.ship(
            ship.shipId,
            ship.shipDefinitionId,
          ),
          worldTarget.route(routeId),
        ],
      });
    }
    return events;
  }

  private mysteryEvent(
    time: number,
    outcomes: readonly Readonly<{
      outcomeId: string;
      state: string;
    }>[],
  ): WorldDomainEvent | undefined {
    if (
      this.mysteryBroadcastEmitted ||
      !outcomes.some(
        (outcome) =>
          outcome.outcomeId ===
            'ember-lighthouse-state' &&
          outcome.state === 'LIT',
      )
    ) {
      return undefined;
    }
    this.mysteryBroadcastEmitted = true;
    this.sequence += 1;
    return {
      type: 'MYSTERY_BROADCAST_AVAILABLE',
      eventId:
        `radio-program:mystery:north-star:${this.sequence}`,
      occurredAt: time,
      source: 'WORLD_SIMULATION',
      broadcastId: 'north-star-first-light',
      clueCode: 'CURRENT_UNDER_ICE',
      musicTrackId: 'dream-of-ice',
      targetRefs: [
        worldTarget.object(
          'transmitter:north-star-hidden-primary',
        ),
      ],
    };
  }
}
