export interface WorldAssetMaterialRecipe {
  readonly id: string;
  readonly color: number;
  readonly roughness: number;
  readonly metalness?: number;
  readonly emissive?: number;
  readonly emissiveIntensity?: number;
}

export interface WorldAssetPartRecipe {
  readonly geometry: WorldAssetGeometryKind;
  readonly material: string;
  /** Optional animation/presentation socket retained by runtime instances. */
  readonly role?: string;
  readonly position: readonly [number, number, number];
  readonly scale: readonly [number, number, number];
  readonly rotationDegrees?: readonly [number, number, number];
}

export interface WorldAssetDefaultCollisionRecipe {
  readonly kind: 'NONE' | 'BOX' | 'CYLINDER';
  readonly width: number;
  readonly height: number;
  readonly depth: number;
  readonly offsetX?: number;
  readonly offsetY?: number;
  readonly offsetZ?: number;
}

export interface WorldAssetConnectorRecipe {
  readonly kind: 'FENCE' | 'RAIL' | 'HEAT_PIPE' | 'WIRE_NODE';
  readonly spanMetres?: number;
  readonly attachmentHeight?: number;
  readonly maximumDistance?: number;
  readonly networkId?: string;
  readonly endpoints?: readonly Readonly<{
    x: number;
    z: number;
    outwardX: number;
    outwardZ: number;
  }>[];
}

export interface WorldAssetSnowMeltRecipe {
  readonly kind: 'LINE' | 'RADIAL';
  readonly radiusMetres: number;
  readonly strength: number;
  readonly halfLengthMetres?: number;
}

export interface WorldAssetPointLightRecipe {
  readonly color: number;
  readonly intensity: number;
  readonly distance: number;
  readonly decay?: number;
  readonly position: readonly [number, number, number];
}

export interface WorldAssetRecipe {
  readonly id: string;
  readonly displayName: string;
  readonly icon: string;
  readonly category: WorldAssetCategory;
  readonly suggestedModelUrl: string;
  readonly defaultCollision: WorldAssetDefaultCollisionRecipe;
  readonly connector?: WorldAssetConnectorRecipe;
  readonly snowMelt?: WorldAssetSnowMeltRecipe;
  /** Optional pooled, shadowless work light for authored utility props. */
  readonly pointLight?: WorldAssetPointLightRecipe;
  readonly parts: readonly WorldAssetPartRecipe[];
}

const LONG_WINTER_NATURE_CATEGORIES: ReadonlySet<WorldAssetCategory> = new Set([
  'CONIFERS',
  'DECIDUOUS',
  'ROCKS_SMALL',
  'ROCKS_LARGE',
  'UNDERSTORY',
]);

/**
 * The Long Winter editor deliberately exposes only timeless natural,
 * survival and fantasy-world props. Ice-A-Way railway, district heating,
 * electrical, harbor, roadwork and modern street-furniture recipes remain in
 * the shared stable-id bank for the Borealis editor, but cannot leak into a
 * Long Winter map by accident.
 */
export const isLongWinterWorldEditorAsset = (
  prefab: Pick<WorldAssetRecipe, 'id' | 'category'>,
): boolean => {
  if (LONG_WINTER_NATURE_CATEGORIES.has(prefab.category)) return true;
  if (prefab.id.startsWith('SURVIVAL_ANIMAL_')) return false;
  if (
    prefab.id.startsWith('SURVIVAL_') ||
    prefab.id.startsWith('TLW_') ||
    prefab.id.startsWith('WILDERNESS_')
  ) return true;
  return prefab.id === 'FENCE_WOOD_2M' ||
    prefab.id === 'FENCE_GATE_2M' ||
    prefab.id === 'IMPORT_CRATE_WOOD_01' ||
    prefab.id === 'IMPORT_SIGNBOARD_FANTASY_01';
};

const part = (
  geometry: WorldAssetGeometryKind,
  material: string,
  position: readonly [number, number, number],
  scale: readonly [number, number, number],
  rotationDegrees?: readonly [number, number, number],
  role?: string,
): WorldAssetPartRecipe => ({
  geometry,
  material,
  position,
  scale,
  ...(rotationDegrees ? { rotationDegrees } : {}),
  ...(role ? { role } : {}),
});

