const survivalBuildWallRecipe = (
  id: string,
  displayName: string,
  bendDegrees: 0 | 15 | 30 | 45,
): WorldAssetRecipe => {
  // Directly follows Yarrgone's readable city-module language: one wall is a
  // single load-bearing edge made from five vertical boards. The 45° variant
  // spans a full bay diagonal instead of pretending that a short curved prop
  // can connect two canonical grid nodes.
  const span = bendDegrees === 45 ? 2 * Math.SQRT2 : 2;
  const plankCount = bendDegrees === 15 || bendDegrees === 30 ? 7 : 5;
  const plankWidth = span / plankCount;
  const pieces = Array.from({ length: plankCount }, (_, index) => [
    part(
      'BOX',
      index === 0 || index === plankCount - 1 ? 'TRUNK_DARK' : index % 2 ? 'WOOD' : 'WOOD_PALE',
      [-span * 0.5 + plankWidth * (index + 0.5), 1.04, 0],
      [plankWidth - 0.018, 1.92 - (index % 2) * 0.045, 0.24],
    ),
  ]).flat();
  // Build V3 storeys are 2.15 m high while the readable vertical boards stop
  // at 2.0 m. Every complete wall owns its upper plate so stacked walls and
  // floors meet without a daylight slit; the separately placeable LOG_BEAM
  // remains a genuine load-bearing span rather than mandatory trim.
  pieces.push(part(
    'BOX',
    'TRUNK_DARK',
    [0, 2.075, 0],
    [span + 0.04, 0.15, 0.3],
  ));
  // Recessed continuous backing closes decorative plank gaps. Keep openings
  // in their own door/window recipes; this is not a universal wall collider.
  pieces.push(part('BOX','TRUNK_DARK',[0,1,0],[span,2,.12]));
  return {
    id,
    displayName,
    icon: bendDegrees === 0 ? '▥' : '⌒',
    category: 'SURVIVAL_STRUCTURES',
    suggestedModelUrl:
      `assets/world/survival/models/${id.toLowerCase().replaceAll('_', '-')}.glb`,
    defaultCollision: {
      kind: 'BOX', width: span, height: 2.15,
      depth: bendDegrees === 15 || bendDegrees === 30 ? 0.68 : 0.3, offsetY: 1.075,
    },
    parts: pieces,
  };
};

