import {
  AdditiveBlending,
  BufferAttribute,
  CanvasTexture,
  Color,
  InstancedBufferAttribute,
  InstancedBufferGeometry,
  LinearFilter,
  Mesh,
  NormalBlending,
  Scene,
  ShaderMaterial,
  SRGBColorSpace,
  Vector2,
  type Camera,
} from 'three';
import { clamp, hash2D, smoothstep } from '../utils/math';
import type { AtmosphereGroundingQuality } from '../rendering/SphericalWorldOverlay';

export type SnowSurfaceHeightSampler = (x: number, z: number) => number;

const MAX_POWDER_INSTANCES = 2_800;
const MAX_CRYSTAL_INSTANCES = 1_100;
const FIELD_RADIUS = 108;
const FIELD_CELL = 4.5;
// Rebuild the CPU-authored ground heights only after the player has crossed a
// wider anchor cell. The shader animates every flake between those crossings;
// sampling ~2k terrain points every 4.5 metres caused avoidable traversal
// spikes on the high and ultra presets.
const FIELD_ANCHOR_CELL = 36;

const QUALITY_COUNTS: Readonly<Record<
  AtmosphereGroundingQuality,
  Readonly<{ powder: number; crystals: number }>
>> = Object.freeze({
  LOW: { powder: 0, crystals: 0 },
  MEDIUM: { powder: 1_050, crystals: 320 },
  HIGH: { powder: 1_850, crystals: 680 },
  ULTRA: { powder: MAX_POWDER_INSTANCES, crystals: MAX_CRYSTAL_INSTANCES },
});

const fract = (value: number): number => value - Math.floor(value);

const createPowderTexture = (): CanvasTexture => {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 64;
  const context = canvas.getContext('2d');
  if (context) {
    context.clearRect(0, 0, 128, 64);
    const lobes = [
      [42, 37, 28, 15, 0.58],
      [66, 29, 37, 20, 0.72],
      [91, 37, 27, 14, 0.52],
      [65, 42, 49, 13, 0.38],
    ] as const;
    for (const [x, y, rx, ry, opacity] of lobes) {
      const gradient = context.createRadialGradient(x, y, 1, x, y, rx);
      gradient.addColorStop(0, `rgba(247,253,255,${opacity})`);
      gradient.addColorStop(0.4, `rgba(231,247,252,${opacity * 0.58})`);
      gradient.addColorStop(1, 'rgba(214,239,246,0)');
      context.save();
      context.translate(x, y);
      context.scale(1, ry / rx);
      context.translate(-x, -y);
      context.fillStyle = gradient;
      context.fillRect(x - rx, y - rx, rx * 2, rx * 2);
      context.restore();
    }
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

const createCrystalTexture = (): CanvasTexture => {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const context = canvas.getContext('2d');
  if (context) {
    const glow = context.createRadialGradient(32, 32, 0, 32, 32, 30);
    glow.addColorStop(0, 'rgba(255,255,255,1)');
    glow.addColorStop(0.08, 'rgba(241,253,255,0.98)');
    glow.addColorStop(0.24, 'rgba(198,237,255,0.34)');
    glow.addColorStop(1, 'rgba(180,225,255,0)');
    context.fillStyle = glow;
    context.fillRect(0, 0, 64, 64);
    context.translate(32, 32);
    context.strokeStyle = 'rgba(255,255,255,0.88)';
    context.lineWidth = 1.2;
    for (let index = 0; index < 4; index += 1) {
      context.rotate(Math.PI / 4);
      context.beginPath();
      context.moveTo(-18, 0);
      context.lineTo(18, 0);
      context.stroke();
    }
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.needsUpdate = true;
  return texture;
};

const createGeometry = (capacity: number): InstancedBufferGeometry => {
  const geometry = new InstancedBufferGeometry();
  geometry.setAttribute('position', new BufferAttribute(new Float32Array([
    -0.5, -0.5, 0,
    0.5, -0.5, 0,
    0.5, 0.5, 0,
    -0.5, 0.5, 0,
  ]), 3));
  geometry.setAttribute('uv', new BufferAttribute(new Float32Array([
    0, 0, 1, 0, 1, 1, 0, 1,
  ]), 2));
  geometry.setIndex([0, 1, 2, 0, 2, 3]);
  geometry.setAttribute(
    'aBase',
    new InstancedBufferAttribute(new Float32Array(capacity * 3), 3),
  );
  geometry.setAttribute(
    'aSeed',
    new InstancedBufferAttribute(new Float32Array(capacity * 3), 3),
  );
  geometry.instanceCount = 0;
  return geometry;
};

const VERTEX_SHADER = `
  uniform float uTime;
  uniform float uAdvection;
  uniform vec2 uWindDirection;
  uniform float uWindStrength;
  uniform float uIntensity;
  uniform float uCrystal;
  attribute vec3 aBase;
  attribute vec3 aSeed;
  varying vec2 vUv;
  varying float vAlpha;

  void main() {
    vec2 direction = normalize(uWindDirection + vec2(0.00001, 0.0));
    vec2 crossWind = vec2(-direction.y, direction.x);
    // Advection is integrated on the CPU. Multiplying absolute time by a
    // changing gust speed moved every existing sheet to a different phase in
    // one frame, which read as teleporting or briefly running backwards.
    float phase = fract(uAdvection * mix(0.055, 0.13, aSeed.y) + aSeed.x);
    float life = smoothstep(0.0, 0.12, phase) *
      (1.0 - smoothstep(0.72, 1.0, phase));
    float travel = mix(5.0, 19.0, aSeed.z) * phase;
    float meander = sin(uTime * 0.19 + aSeed.y * 19.0) *
      mix(0.18, 1.1, aSeed.z);
    vec3 centre = aBase;
    centre.xz += direction * travel + crossWind * meander;
    centre.y += mix(0.02, 0.34, aSeed.y) * sin(phase * 3.14159265) +
      uCrystal * (0.25 + aSeed.z * 2.35);

    float travellingFront = smoothstep(-0.46, 0.72, sin(
      dot(aBase.xz, direction) * 0.038 - uAdvection * 0.31 + aSeed.z * 5.0
    ));
    vec3 cameraRight = vec3(viewMatrix[0][0], viewMatrix[1][0], viewMatrix[2][0]);
    vec3 cameraUp = vec3(viewMatrix[0][1], viewMatrix[1][1], viewMatrix[2][1]);
    float powderWidth = mix(0.55, 2.85, aSeed.y) * (0.72 + uWindStrength * 0.2);
    float powderHeight = mix(0.08, 0.34, aSeed.z);
    float crystalSize = mix(0.018, 0.052, aSeed.y);
    float width = mix(powderWidth, crystalSize, uCrystal);
    float height = mix(powderHeight, crystalSize, uCrystal);
    vec3 worldPosition = centre + cameraRight * position.x * width +
      cameraUp * position.y * height;
    gl_Position = projectionMatrix * viewMatrix * vec4(worldPosition, 1.0);
    vUv = uv;
    float crystalTwinkle = mix(1.0, 0.28 + 0.72 * pow(abs(sin(
      uTime * mix(1.7, 4.2, aSeed.z) + aSeed.x * 17.0
    )), 8.0), uCrystal);
    vAlpha = life * travellingFront * uIntensity *
      mix(0.34, 0.88, aSeed.x) * crystalTwinkle;
  }
`;

const FRAGMENT_SHADER = `
  uniform sampler2D uMap;
  uniform vec3 uTint;
  uniform float uCrystal;
  varying vec2 vUv;
  varying float vAlpha;
  void main() {
    vec4 sampleColor = texture2D(uMap, vUv);
    float alpha = sampleColor.a * vAlpha;
    if (alpha < 0.006) discard;
    gl_FragColor = vec4(sampleColor.rgb * uTint, alpha);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }
`;

/** Two inexpensive world-space layers: surface powder and rare airborne ice. */
export class GpuSpindriftField {
  private readonly powderGeometry = createGeometry(MAX_POWDER_INSTANCES);
  private readonly crystalGeometry = createGeometry(MAX_CRYSTAL_INSTANCES);
  private readonly powderTexture = createPowderTexture();
  private readonly crystalTexture = createCrystalTexture();
  private readonly powderMaterial: ShaderMaterial;
  private readonly crystalMaterial: ShaderMaterial;
  private readonly powderMesh: Mesh<InstancedBufferGeometry, ShaderMaterial>;
  private readonly crystalMesh: Mesh<InstancedBufferGeometry, ShaderMaterial>;
  private readonly windDirection = new Vector2(1, 0);
  private readonly targetWindDirection = new Vector2(1, 0);
  private quality: AtmosphereGroundingQuality = 'LOW';
  private sampler?: SnowSurfaceHeightSampler;
  private anchorCellX = Number.POSITIVE_INFINITY;
  private anchorCellZ = Number.POSITIVE_INFINITY;
  private anchorRegionX = Number.POSITIVE_INFINITY;
  private anchorRegionZ = Number.POSITIVE_INFINITY;
  private elapsed = 0;
  private advection = 0;
  private transportWindStrength = 0;
  private hasWindDirection = false;
  private intensity = 0;
  private localVisible = true;
  private daylight = 1;
  private night = 0;
  private populatedPowder = 0;
  private populatedCrystals = 0;

  public constructor(private readonly scene: Scene) {
    this.powderMaterial = this.createMaterial(this.powderTexture, false);
    this.crystalMaterial = this.createMaterial(this.crystalTexture, true);
    this.powderMesh = new Mesh(this.powderGeometry, this.powderMaterial);
    this.powderMesh.name = 'World-space windblown powder sheets';
    this.powderMesh.frustumCulled = false;
    this.powderMesh.renderOrder = 7;
    this.crystalMesh = new Mesh(this.crystalGeometry, this.crystalMaterial);
    this.crystalMesh.name = 'World-space airborne snow crystals';
    this.crystalMesh.frustumCulled = false;
    this.crystalMesh.renderOrder = 8;
    this.scene.add(this.powderMesh, this.crystalMesh);
  }

  public setQuality(quality: AtmosphereGroundingQuality): void {
    if (quality === this.quality) return;
    this.quality = quality;
    this.invalidateAnchor();
  }

  public setSurfaceHeightSampler(sampler: SnowSurfaceHeightSampler): void {
    this.sampler = sampler;
    this.invalidateAnchor();
  }

  public setLocalVisible(visible: boolean): void {
    this.localVisible = visible;
  }

  public setLighting(daylight: number, night: number): void {
    this.daylight = clamp(daylight, 0, 1);
    this.night = clamp(night, 0, 1);
  }

  public update(
    deltaSeconds: number,
    _camera: Camera,
    focus: Readonly<{ x: number; y?: number; z: number }>,
    windX: number,
    windZ: number,
    windStrength: number,
    visibleWindIntensity: number,
  ): void {
    const delta = clamp(deltaSeconds, 0, 0.1);
    this.elapsed += delta;
    const windLength = Math.max(0.0001, Math.hypot(windX, windZ));
    const targetX = windX / windLength;
    const targetZ = windZ / windLength;
    this.targetWindDirection.set(targetX, targetZ);
    if (!this.hasWindDirection) {
      this.windDirection.copy(this.targetWindDirection);
      this.transportWindStrength = clamp(windStrength, 0, 2.4);
      this.hasWindDirection = true;
    } else {
      // A landscape-scale air mass turns patiently. Gusts may alter density
      // and turbulence, but they cannot rotate every already-airborne crystal
      // instantaneously or reverse an entire powder front.
      const currentAngle = Math.atan2(
        this.windDirection.y,
        this.windDirection.x,
      );
      const targetAngle = Math.atan2(targetZ, targetX);
      const angleDelta = Math.atan2(
        Math.sin(targetAngle - currentAngle),
        Math.cos(targetAngle - currentAngle),
      );
      const desiredTurn = angleDelta * (1 - Math.exp(-delta / 28));
      const maximumTurn = delta * 0.055;
      const angle = currentAngle + clamp(
        desiredTurn,
        -maximumTurn,
        maximumTurn,
      );
      this.windDirection.set(Math.cos(angle), Math.sin(angle));
      this.transportWindStrength += (
        clamp(windStrength, 0, 2.4) - this.transportWindStrength
      ) * (1 - Math.exp(-delta / 8));
    }
    this.advection += delta * (0.6 + this.transportWindStrength * 0.45);
    const targetIntensity = this.localVisible
      ? smoothstep(0.12, 0.84, visibleWindIntensity) *
        smoothstep(0.72, 1.42, windStrength)
      : 0;
    this.intensity += (targetIntensity - this.intensity) *
      (1 - Math.exp(-delta / (targetIntensity > this.intensity ? 1.2 : 3.8)));
    const counts = QUALITY_COUNTS[this.quality];
    if (counts.powder === 0 && counts.crystals === 0) {
      this.powderGeometry.instanceCount = 0;
      this.crystalGeometry.instanceCount = 0;
      this.powderMesh.visible = false;
      this.crystalMesh.visible = false;
      return;
    }
    const regionX = Math.floor(focus.x / FIELD_ANCHOR_CELL);
    const regionZ = Math.floor(focus.z / FIELD_ANCHOR_CELL);
    if (regionX !== this.anchorRegionX || regionZ !== this.anchorRegionZ) {
      this.anchorRegionX = regionX;
      this.anchorRegionZ = regionZ;
      this.anchorCellX = Math.floor(focus.x / FIELD_CELL);
      this.anchorCellZ = Math.floor(focus.z / FIELD_CELL);
      this.rebuildField(focus.y ?? 0);
    }
    this.powderGeometry.instanceCount = Math.min(
      counts.powder,
      this.populatedPowder,
    );
    this.crystalGeometry.instanceCount = Math.min(
      counts.crystals,
      this.populatedCrystals,
    );
    const visible = this.intensity > 0.002 && counts.powder > 0;
    this.powderMesh.visible = visible;
    this.crystalMesh.visible = visible && counts.crystals > 0;
    const light = clamp(this.daylight + this.night * 0.62, 0.22, 1);
    for (const material of [this.powderMaterial, this.crystalMaterial]) {
      material.uniforms.uTime!.value = this.elapsed;
      material.uniforms.uAdvection!.value = this.advection;
      material.uniforms.uWindDirection!.value.copy(this.windDirection);
      material.uniforms.uWindStrength!.value = this.transportWindStrength;
      material.uniforms.uIntensity!.value = this.intensity * light;
    }
  }

  public getActiveCounts(): Readonly<{ powder: number; crystals: number }> {
    return this.powderMesh.visible
      ? {
          powder: this.powderGeometry.instanceCount,
          crystals: this.crystalMesh.visible
            ? this.crystalGeometry.instanceCount
            : 0,
        }
      : { powder: 0, crystals: 0 };
  }

  public dispose(): void {
    this.scene.remove(this.powderMesh, this.crystalMesh);
    this.powderGeometry.dispose();
    this.crystalGeometry.dispose();
    this.powderMaterial.dispose();
    this.crystalMaterial.dispose();
    this.powderTexture.dispose();
    this.crystalTexture.dispose();
  }

  private createMaterial(texture: CanvasTexture, crystal: boolean): ShaderMaterial {
    return new ShaderMaterial({
      uniforms: {
        uMap: { value: texture },
        uTime: { value: 0 },
        uAdvection: { value: 0 },
        uWindDirection: { value: new Vector2(1, 0) },
        uWindStrength: { value: 0 },
        uIntensity: { value: 0 },
        uCrystal: { value: crystal ? 1 : 0 },
        uTint: { value: new Color(crystal ? 0xc7edff : 0xe8f7ff) },
      },
      vertexShader: VERTEX_SHADER,
      fragmentShader: FRAGMENT_SHADER,
      transparent: true,
      depthTest: true,
      depthWrite: false,
      blending: crystal ? AdditiveBlending : NormalBlending,
      toneMapped: true,
    });
  }

  private invalidateAnchor(): void {
    this.anchorCellX = Number.POSITIVE_INFINITY;
    this.anchorCellZ = Number.POSITIVE_INFINITY;
    this.anchorRegionX = Number.POSITIVE_INFINITY;
    this.anchorRegionZ = Number.POSITIVE_INFINITY;
  }

  private rebuildField(fallbackHeight: number): void {
    const powderBase = this.powderGeometry.getAttribute('aBase') as InstancedBufferAttribute;
    const powderSeed = this.powderGeometry.getAttribute('aSeed') as InstancedBufferAttribute;
    const crystalBase = this.crystalGeometry.getAttribute('aBase') as InstancedBufferAttribute;
    const crystalSeed = this.crystalGeometry.getAttribute('aSeed') as InstancedBufferAttribute;
    const powderArray = powderBase.array as Float32Array;
    const powderSeeds = powderSeed.array as Float32Array;
    const crystalArray = crystalBase.array as Float32Array;
    const crystalSeeds = crystalSeed.array as Float32Array;
    let powderIndex = 0;
    let crystalIndex = 0;
    const radiusCells = Math.ceil(FIELD_RADIUS / FIELD_CELL);
    for (let dz = -radiusCells; dz <= radiusCells; dz += 1) {
      for (let dx = -radiusCells; dx <= radiusCells; dx += 1) {
        const worldCellX = this.anchorCellX + dx;
        const worldCellZ = this.anchorCellZ + dz;
        const centreX = (worldCellX + 0.5) * FIELD_CELL;
        const centreZ = (worldCellZ + 0.5) * FIELD_CELL;
        if (Math.hypot(dx, dz) * FIELD_CELL > FIELD_RADIUS) continue;
        const ground = this.sampler?.(centreX, centreZ) ?? fallbackHeight;
        for (let candidate = 0; candidate < 2; candidate += 1) {
          if (powderIndex >= MAX_POWDER_INSTANCES) break;
          const seed = hash2D(worldCellX * 2 + candidate, worldCellZ, 39_117);
          if (candidate === 1 && seed < 0.38) continue;
          const x = centreX + (hash2D(worldCellX, worldCellZ, 81 + candidate) - 0.5) * FIELD_CELL;
          const z = centreZ + (hash2D(worldCellX, worldCellZ, 173 + candidate) - 0.5) * FIELD_CELL;
          const offset = powderIndex * 3;
          powderArray[offset] = x;
          powderArray[offset + 1] = ground + 0.045;
          powderArray[offset + 2] = z;
          powderSeeds[offset] = seed;
          powderSeeds[offset + 1] = fract(seed * 17.13 + 0.31);
          powderSeeds[offset + 2] = fract(seed * 31.77 + 0.67);
          powderIndex += 1;
        }
        if (crystalIndex < MAX_CRYSTAL_INSTANCES) {
          const seed = hash2D(worldCellX, worldCellZ, 77_031);
          if (seed > 0.7) continue;
          const offset = crystalIndex * 3;
          crystalArray[offset] = centreX;
          crystalArray[offset + 1] = ground + 0.08;
          crystalArray[offset + 2] = centreZ;
          crystalSeeds[offset] = seed;
          crystalSeeds[offset + 1] = fract(seed * 23.91 + 0.17);
          crystalSeeds[offset + 2] = fract(seed * 47.03 + 0.43);
          crystalIndex += 1;
        }
      }
    }
    // Fill unused slots deterministically outside the visible circle. Quality
    // never requests more than the populated counts, but complete attributes
    // keep WebGL validation straightforward across device drivers.
    this.populatedPowder = powderIndex;
    this.populatedCrystals = crystalIndex;
    this.powderGeometry.instanceCount = Math.min(
      QUALITY_COUNTS[this.quality].powder,
      powderIndex,
    );
    this.crystalGeometry.instanceCount = Math.min(
      QUALITY_COUNTS[this.quality].crystals,
      crystalIndex,
    );
    powderBase.needsUpdate = true;
    powderSeed.needsUpdate = true;
    crystalBase.needsUpdate = true;
    crystalSeed.needsUpdate = true;
  }
}
