import { MeshStandardMaterial } from 'three';

/** Per-instance linear albedo/emission; all other authored material properties
 * stay intact. Cooling embers and fire warnings never require a new shader. */
export function constructionInstanceAppearance(source: MeshStandardMaterial): MeshStandardMaterial {
  const material = source.clone();
  material.color.setRGB(1, 1, 1);
  material.emissive.setRGB(1, 1, 1); material.emissiveIntensity = 1;
  const compile = source.onBeforeCompile, key = source.customProgramCacheKey.bind(source);
  material.onBeforeCompile = function(shader, renderer) {
    compile.call(this, shader, renderer);
    shader.vertexShader = shader.vertexShader.replace('#include <common>',
      '#include <common>\nattribute vec3 aBuildEmission;\nvarying vec3 vBuildEmission;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvBuildEmission = aBuildEmission;');
    shader.fragmentShader = shader.fragmentShader.replace('#include <common>',
      '#include <common>\nvarying vec3 vBuildEmission;')
      .replace('vec3 totalEmissiveRadiance = emissive;', 'vec3 totalEmissiveRadiance = vBuildEmission;');
  };
  material.customProgramCacheKey = () => `${key()}|construction-instance-emission-v1`;
  return material;
}
