import { clamp, smoothstep } from '../utils/math';
import type {
  LocalWorldInfluenceRegistry,
  ThermalBarrierDescriptor,
} from './LocalWorldInfluenceRegistry';

export interface WildernessThermalFieldUpdate {
  readonly focusX: number;
  readonly focusZ: number;
  readonly ambientTemperatureCelsius: number;
  readonly windX: number;
  readonly windZ: number;
  readonly windStrength: number;
}

export interface WildernessThermalSample {
  readonly temperatureDeltaCelsius: number;
  readonly exposure: number;
  readonly drying: number;
}

export interface WildernessThermalFieldStats {
  readonly cells: number;
  readonly sources: number;
  readonly barriers: number;
  readonly updates: number;
  readonly topologyRevision: number;
  readonly lastUpdateMs: number;
  readonly maximumUpdateMs: number;
}

const CELL_SIZE = 0.75;
const CELLS_PER_SIDE = 64;
const FIELD_SIZE = CELL_SIZE * CELLS_PER_SIDE;
const UPDATE_INTERVAL_SECONDS = 0.5;

const pointSegmentDistance = (
  x: number,
  z: number,
  barrier: Readonly<ThermalBarrierDescriptor>,
): number => {
  const dx = barrier.endX - barrier.startX;
  const dz = barrier.endZ - barrier.startZ;
  const lengthSquared = dx * dx + dz * dz;
  if (lengthSquared <= 0.0001) {
    return Math.hypot(x - barrier.startX, z - barrier.startZ);
  }
  const progress = clamp(
    ((x - barrier.startX) * dx + (z - barrier.startZ) * dz) /
      lengthSquared,
    0,
    1,
  );
  return Math.hypot(
    x - (barrier.startX + dx * progress),
    z - (barrier.startZ + dz * progress),
  );
};

/** 2.5D, ground-relative and camera-independent local thermal field. */
export class WildernessThermalFieldSystem {
  private readonly heat = new Float32Array(CELLS_PER_SIDE * CELLS_PER_SIDE);
  private readonly scratch = new Float32Array(CELLS_PER_SIDE * CELLS_PER_SIDE);
  private readonly exposure = new Float32Array(CELLS_PER_SIDE * CELLS_PER_SIDE)
    .fill(1);
  private originX = Number.NaN;
  private originZ = Number.NaN;
  private accumulator = 0;
  private topologyRevision = -1;
  private topologyWindX = Number.NaN;
  private topologyWindZ = Number.NaN;
  private topologyWindStrength = Number.NaN;
  private updates = 0;
  private lastUpdateMs = 0;
  private maximumUpdateMs = 0;

  public constructor(
    private readonly registry: LocalWorldInfluenceRegistry,
  ) {}

  public update(
    deltaSeconds: number,
    input: Readonly<WildernessThermalFieldUpdate>,
  ): void {
    const sources = this.registry.thermalSources();
    const barriers = this.registry.thermalBarriers();
    if (sources.length === 0 && barriers.length === 0) {
      // Direct solar snow melt is handled by WildernessSurvivalSystem and is
      // intentionally independent of this camp/shelter-scale thermal field.
      // With no local source or protection there is no field to simulate.
      if (this.topologyRevision !== -2) {
        this.heat.fill(0);
        this.exposure.fill(1);
        this.topologyRevision = -2;
      }
      this.accumulator = 0;
      this.lastUpdateMs = 0;
      return;
    }
    this.ensureFocus(input.focusX, input.focusZ);
    this.accumulator += clamp(deltaSeconds, 0, 0.1);
    if (this.accumulator < UPDATE_INTERVAL_SECONDS) return;
    const startedAt = performance.now();
    const elapsed = Math.min(1, this.accumulator);
    this.accumulator = 0;
    if (
      this.topologyRevision !== this.registry.getBarrierRevision() ||
      Math.abs(input.windX - this.topologyWindX) > 0.08 ||
      Math.abs(input.windZ - this.topologyWindZ) > 0.08 ||
      Math.abs(input.windStrength - this.topologyWindStrength) > 0.12
    ) {
      this.rebuildExposure(
        input.windX,
        input.windZ,
        input.windStrength,
        barriers,
      );
      this.topologyRevision = this.registry.getBarrierRevision();
      this.topologyWindX = input.windX;
      this.topologyWindZ = input.windZ;
      this.topologyWindStrength = input.windStrength;
    }
    const windLength = Math.max(0.001, Math.hypot(input.windX, input.windZ));
    const windX = input.windX / windLength;
    const windZ = input.windZ / windLength;
    for (let index = 0; index < this.heat.length; index += 1) {
      const escape = 0.075 + (this.exposure[index] ?? 1) * 0.16;
      this.heat[index] = Math.max(0, (this.heat[index] ?? 0) *
        Math.exp(-escape * elapsed));
    }
    for (const source of sources) {
      if (source.heatOutput <= 0.0001) continue;
      const radius = Math.max(source.radiantRadius, source.convectiveRadius);
      const minColumn = clamp(
        Math.floor((source.x - radius - this.originX) / CELL_SIZE),
        0,
        CELLS_PER_SIDE - 1,
      );
      const maxColumn = clamp(
        Math.ceil((source.x + radius - this.originX) / CELL_SIZE),
        0,
        CELLS_PER_SIDE - 1,
      );
      const minRow = clamp(
        Math.floor((source.z - radius - this.originZ) / CELL_SIZE),
        0,
        CELLS_PER_SIDE - 1,
      );
      const maxRow = clamp(
        Math.ceil((source.z + radius - this.originZ) / CELL_SIZE),
        0,
        CELLS_PER_SIDE - 1,
      );
      for (let row = minRow; row <= maxRow; row += 1) {
        const z = this.originZ + (row + 0.5) * CELL_SIZE;
        for (let column = minColumn; column <= maxColumn; column += 1) {
          const x = this.originX + (column + 0.5) * CELL_SIZE;
          const dx = x - source.x;
          const dz = z - source.z;
          const downwind = Math.max(0, dx * windX + dz * windZ);
          const convectiveDistance = Math.hypot(
            dx - windX * downwind * 0.24,
            dz - windZ * downwind * 0.24,
          );
          const radiant = 1 - smoothstep(
            source.radiantRadius * 0.18,
            source.radiantRadius,
            Math.hypot(dx, dz),
          );
          const convective = 1 - smoothstep(
            source.convectiveRadius * 0.2,
            source.convectiveRadius,
            convectiveDistance,
          );
          const targetDelta = source.heatOutput *
            (radiant * 12 + convective * (4 + input.windStrength * 1.6));
          const index = row * CELLS_PER_SIDE + column;
          this.heat[index] = Math.max(
            this.heat[index] ?? 0,
            targetDelta * (0.72 + (1 - (this.exposure[index] ?? 1)) * 0.28),
          );
        }
      }
    }
    for (let iteration = 0; iteration < 2; iteration += 1) {
      for (let row = 0; row < CELLS_PER_SIDE; row += 1) {
        for (let column = 0; column < CELLS_PER_SIDE; column += 1) {
          const index = row * CELLS_PER_SIDE + column;
          const center = this.heat[index] ?? 0;
          const west = this.heat[index - (column > 0 ? 1 : 0)] ?? center;
          const east = this.heat[index + (column + 1 < CELLS_PER_SIDE ? 1 : 0)] ?? center;
          const north = this.heat[index - (row > 0 ? CELLS_PER_SIDE : 0)] ?? center;
          const south = this.heat[index + (row + 1 < CELLS_PER_SIDE ? CELLS_PER_SIDE : 0)] ?? center;
          const average = (west + east + north + south) * 0.25;
          this.scratch[index] = center + (average - center) * 0.11;
        }
      }
      this.heat.set(this.scratch);
    }
    this.updates += 1;
    this.lastUpdateMs = performance.now() - startedAt;
    this.maximumUpdateMs = Math.max(this.maximumUpdateMs, this.lastUpdateMs);
  }

  public sample(x: number, z: number): WildernessThermalSample {
    if (!Number.isFinite(this.originX) || !Number.isFinite(this.originZ)) {
      return { temperatureDeltaCelsius: 0, exposure: 1, drying: 0 };
    }
    const column = Math.floor((x - this.originX) / CELL_SIZE);
    const row = Math.floor((z - this.originZ) / CELL_SIZE);
    if (
      column < 0 || column >= CELLS_PER_SIDE ||
      row < 0 || row >= CELLS_PER_SIDE
    ) return { temperatureDeltaCelsius: 0, exposure: 1, drying: 0 };
    const index = row * CELLS_PER_SIDE + column;
    const temperatureDeltaCelsius = this.heat[index] ?? 0;
    return {
      temperatureDeltaCelsius,
      exposure: this.exposure[index] ?? 1,
      drying: clamp(temperatureDeltaCelsius / 14, 0, 1),
    };
  }

  public getStats(): WildernessThermalFieldStats {
    return {
      cells: this.heat.length,
      sources: this.registry.thermalSources().length,
      barriers: this.registry.thermalBarriers().length,
      updates: this.updates,
      topologyRevision: this.topologyRevision,
      lastUpdateMs: this.lastUpdateMs,
      maximumUpdateMs: this.maximumUpdateMs,
    };
  }

  private ensureFocus(x: number, z: number): void {
    const targetOriginX = Math.floor((x - FIELD_SIZE * 0.5) / 12) * 12;
    const targetOriginZ = Math.floor((z - FIELD_SIZE * 0.5) / 12) * 12;
    if (targetOriginX === this.originX && targetOriginZ === this.originZ) return;
    const previous = this.heat.slice();
    const previousOriginX = this.originX;
    const previousOriginZ = this.originZ;
    this.originX = targetOriginX;
    this.originZ = targetOriginZ;
    this.heat.fill(0);
    if (Number.isFinite(previousOriginX) && Number.isFinite(previousOriginZ)) {
      for (let row = 0; row < CELLS_PER_SIDE; row += 1) {
        const worldZ = this.originZ + (row + 0.5) * CELL_SIZE;
        const oldRow = Math.floor((worldZ - previousOriginZ) / CELL_SIZE);
        if (oldRow < 0 || oldRow >= CELLS_PER_SIDE) continue;
        for (let column = 0; column < CELLS_PER_SIDE; column += 1) {
          const worldX = this.originX + (column + 0.5) * CELL_SIZE;
          const oldColumn = Math.floor((worldX - previousOriginX) / CELL_SIZE);
          if (oldColumn < 0 || oldColumn >= CELLS_PER_SIDE) continue;
          this.heat[row * CELLS_PER_SIDE + column] =
            previous[oldRow * CELLS_PER_SIDE + oldColumn] ?? 0;
        }
      }
    }
    this.topologyRevision = -1;
  }

  private rebuildExposure(
    windX: number,
    windZ: number,
    strength: number,
    barriers: readonly Readonly<ThermalBarrierDescriptor>[],
  ): void {
    this.exposure.fill(1);
    const windLength = Math.max(0.001, Math.hypot(windX, windZ));
    const directionX = windX / windLength;
    const directionZ = windZ / windLength;
    for (let row = 0; row < CELLS_PER_SIDE; row += 1) {
      const z = this.originZ + (row + 0.5) * CELL_SIZE;
      for (let column = 0; column < CELLS_PER_SIDE; column += 1) {
        const x = this.originX + (column + 0.5) * CELL_SIZE;
        let shelter = 0;
        for (const barrier of barriers) {
          const midpointX = (barrier.startX + barrier.endX) * 0.5;
          const midpointZ = (barrier.startZ + barrier.endZ) * 0.5;
          const downwind =
            (x - midpointX) * directionX + (z - midpointZ) * directionZ;
          if (downwind < -0.3 || downwind > 5.5) continue;
          const distance = pointSegmentDistance(
            x - directionX * Math.max(0, downwind),
            z - directionZ * Math.max(0, downwind),
            barrier,
          );
          const coverage =
            (1 - smoothstep(0.35, 1.5, distance)) *
            (1 - smoothstep(2.8, 5.5, Math.max(0, downwind))) *
            (1 - barrier.windPermeability) * barrier.insulation;
          shelter = Math.max(shelter, coverage);
        }
        this.exposure[row * CELLS_PER_SIDE + column] = clamp(
          1 - shelter * clamp(0.55 + strength * 0.18, 0.55, 0.9),
          0.18,
          1,
        );
      }
    }
  }
}
