import type { ClockSyncEstimate } from '../../netcode/core/AuthorityClock';
import type {
  MultiplayerSessionClientDiagnostics,
  MultiplayerSessionClientState,
} from './MultiplayerSessionClient';

export type MultiplayerConnectionQuality =
  | 'OFFLINE'
  | 'MEASURING'
  | 'GOOD'
  | 'FAIR'
  | 'POOR';

export interface MultiplayerPlatformViewModel {
  readonly title: string;
  readonly detail: string;
  readonly phaseLabel: string;
  readonly quality: MultiplayerConnectionQuality;
  readonly qualityDetail: string;
  readonly tone: 'NEUTRAL' | 'GOOD' | 'WARNING' | 'DANGER';
  readonly busy: boolean;
  readonly expanded: boolean;
  readonly canRetry: boolean;
  readonly canInvite: boolean;
  readonly canLeave: boolean;
  readonly assertive: boolean;
  readonly updateUrl?: string;
  readonly supportUrl?: string;
}

const quality = (
  state: Readonly<MultiplayerSessionClientState>,
  diagnostics: Readonly<MultiplayerSessionClientDiagnostics>,
  clock: Readonly<ClockSyncEstimate>,
): Pick<MultiplayerPlatformViewModel, 'quality' | 'qualityDetail'> => {
  if (state.phase !== 'JOINED') {
    return { quality: 'OFFLINE', qualityDetail: 'No live authority link' };
  }
  if (clock.samples < 2) {
    return { quality: 'MEASURING', qualityDetail: 'Measuring connection' };
  }
  const queued = diagnostics.transport?.queuedBytes ?? 0;
  const label = `${Math.round(clock.roundTripMs)} ms · ${Math.round(clock.jitterMs)} ms jitter`;
  if (clock.roundTripMs <= 90 && clock.jitterMs <= 24 && queued < 64 * 1024) {
    return { quality: 'GOOD', qualityDetail: label };
  }
  if (clock.roundTripMs <= 190 && clock.jitterMs <= 60 && queued < 256 * 1024) {
    return { quality: 'FAIR', qualityDetail: label };
  }
  return { quality: 'POOR', qualityDetail: label };
};

export const createMultiplayerPlatformViewModel = (
  state: Readonly<MultiplayerSessionClientState>,
  diagnostics: Readonly<MultiplayerSessionClientDiagnostics>,
  clock: Readonly<ClockSyncEstimate>,
  nowMs: number,
): MultiplayerPlatformViewModel => {
  const link = quality(state, diagnostics, clock);
  const ending = state.sessionEnding;
  if (ending) {
    return {
      title: 'Session authority is closing',
      detail: ending.recoverable
        ? 'Progress was checkpointed. You can reconnect when the room returns.'
        : 'The room could not confirm a recovery checkpoint. Leave and contact the host.',
      phaseLabel: 'AUTHORITY EXIT',
      ...link,
      tone: ending.recoverable ? 'WARNING' : 'DANGER',
      busy: false,
      expanded: true,
      canRetry: ending.recoverable,
      canInvite: false,
      canLeave: true,
      assertive: true,
    };
  }
  const base = {
    ...link,
    canLeave: true,
    updateUrl: state.rejectionNotice?.updateUrl,
    supportUrl: state.rejectionNotice?.supportUrl,
  };
  switch (state.phase) {
    case 'IDLE':
    case 'CONNECTING':
      return { ...base, title: 'Connecting to room', detail: 'Opening a secure authority connection.', phaseLabel: 'CONNECTING', tone: 'NEUTRAL', busy: true, expanded: true, canRetry: false, canInvite: false, assertive: false };
    case 'HANDSHAKING':
      return { ...base, title: 'Checking game versions', detail: 'Negotiating protocol, world data and capabilities.', phaseLabel: 'HANDSHAKE', tone: 'NEUTRAL', busy: true, expanded: true, canRetry: false, canInvite: false, assertive: false };
    case 'REHYDRATING':
      return { ...base, title: 'Synchronizing the world', detail: 'Controls are paused until every authority baseline reaches the same epoch.', phaseLabel: 'SYNCING', tone: 'NEUTRAL', busy: true, expanded: true, canRetry: false, canInvite: false, assertive: false };
    case 'JOINED':
      return { ...base, title: 'Multiplayer connected', detail: `Authority epoch ${state.sessionEpoch ?? 1} · ${link.qualityDetail}`, phaseLabel: link.quality, tone: link.quality === 'POOR' ? 'WARNING' : 'GOOD', busy: false, expanded: false, canRetry: false, canInvite: true, assertive: false };
    case 'SUSPENDED':
      return { ...base, title: 'Session suspended', detail: 'The browser is backgrounded or offline. Movement was neutralized safely.', phaseLabel: 'SUSPENDED', tone: 'WARNING', busy: false, expanded: true, canRetry: true, canInvite: false, assertive: true };
    case 'RECONNECT_WAIT': {
      const remaining = state.reconnectAtMs === undefined
        ? 0
        : Math.max(0, Math.ceil((state.reconnectAtMs - nowMs) / 1_000));
      return { ...base, title: 'Connection interrupted', detail: `Movement is stopped. Reconnecting${remaining > 0 ? ` in ${remaining} s` : ' now'}…`, phaseLabel: 'RECONNECTING', tone: 'WARNING', busy: true, expanded: true, canRetry: true, canInvite: false, assertive: true };
    }
    case 'REJECTED':
      return { ...base, title: 'Could not join this room', detail: state.rejectionNotice?.message ?? state.rejectionReason ?? 'The authority rejected this client.', phaseLabel: state.rejectionNotice?.action === 'UPDATE_CLIENT' ? 'UPDATE REQUIRED' : 'JOIN REJECTED', tone: 'DANGER', busy: false, expanded: true, canRetry: state.rejectionNotice?.retryable ?? true, canInvite: false, assertive: true };
    case 'CLOSED':
      return { ...base, title: 'Multiplayer closed', detail: state.lastDisconnectReason ?? 'The multiplayer client has stopped.', phaseLabel: 'CLOSED', tone: 'NEUTRAL', busy: false, expanded: true, canRetry: false, canInvite: false, assertive: false };
  }
};
