import type {SurvivalBuildPieceDefinition} from '../SurvivalBuildingCatalog';
import type {WorldAssetRecipe,WorldAssetPartRecipe} from '../../land/WorldAssetCatalog';

export const FREE_FURNITURE_CATALOG:readonly SurvivalBuildPieceDefinition[]=[
  {id:'TIMBER_TABLE',name:'Timber table',icon:'╤',halfWidth:.75,halfDepth:.45,height:.8,placementSurfaceY:.8},
  {id:'TIMBER_CHAIR',name:'Timber chair',icon:'♧',halfWidth:.25,halfDepth:.25,height:.95,placementSurfaceY:.48},
  {id:'TIMBER_SHELF',name:'Shelf board · 1 m',icon:'▬',halfWidth:.5,halfDepth:.25,height:.045,placementSurfaceY:.045},
].map(d=>({...d,description:'Freehand furniture · mouse position, wheel depth, G local grid. Needs a real supporting surface.',
  prefabId:`SURVIVAL_BUILD_${d.id}_01`,family:'UTILITY',curvatureDegrees:0,placementSupport:'BELOW',
  blocksMovement:d.id!=='TIMBER_SHELF',weatherCover:false,sockets:[],
  cost:[{inventory:'logs',amount:1,label:'timber'}],
} as SurvivalBuildPieceDefinition));

const box=(position:[number,number,number],scale:[number,number,number]):WorldAssetPartRecipe=>({
  geometry:'BOX',material:'WOOD',position,scale,
});
export const FREE_FURNITURE_ASSETS:readonly WorldAssetRecipe[]=FREE_FURNITURE_CATALOG.map(d=>{
  const chair=d.id==='TIMBER_CHAIR',shelf=d.id==='TIMBER_SHELF',top=d.placementSurfaceY!;
  const parts:WorldAssetPartRecipe[]=[];
  const count=shelf?2:chair?3:5;
  for(let i=0;i<count;i++)parts.push(box([0,top-.0225,-d.halfDepth+(i+.5)*d.halfDepth*2/count],
    [d.halfWidth*2,.045,d.halfDepth*2/count-.008]));
  if(!shelf){
    for(const x of [-1,1])for(const z of [-1,1])parts.push(box([x*(d.halfWidth-.07),top/2-.025,z*(d.halfDepth-.07)],[.085,top-.045,.085]));
    if(chair){
      for(const x of [-.18,.18])parts.push(box([x,.72,.19],[.06,.46,.065]));
      for(const y of [.69,.85])parts.push(box([0,y,.19],[.45,.12,.06]));
    }
  }
  return {id:d.prefabId,displayName:d.name,icon:d.icon,category:'SURVIVAL_STRUCTURES',
    suggestedModelUrl:`assets/world/survival/models/${d.id.toLowerCase().replaceAll('_','-')}-01.glb`,
    defaultCollision:{kind:'BOX',width:d.halfWidth*2,height:d.height,depth:d.halfDepth*2,offsetY:d.height/2},parts};
});
