import type { SurvivalBuildPieceId } from '../SurvivalBuildingCatalog';
import type { SurvivalBuildV3TerrainFit } from './SurvivalBuildV3TerrainFit';

export const SURVIVAL_BUILD_V3_SAVE_VERSION = 3 as const;
export const SURVIVAL_BUILD_V3_MODULE_METRES = 2 as const;
export const SURVIVAL_BUILD_V3_YAW_STEP_DEGREES = 15 as const;

export type SurvivalBuildV3SiteKind =
  | 'SURFACE'
  | 'DUGOUT'
  | 'CAVE'
  | 'RUIN_ADDITION';

export type SurvivalBuildV3Role =
  | 'FOUNDATION'
  | 'FLOOR'
  | 'WALL'
  | 'POST'
  | 'BEAM'
  | 'ROOF'
  | 'UTILITY';

export type SurvivalBuildV3ConnectionRole =
  | 'SUPPORTED_BY'
  | 'SUPPORTS'
  | 'CONTINUES'
  | 'SEALS'
  | 'MOUNTS';

export type SurvivalBuildV3EdgeDirection =
  | 'NORTH'
  | 'EAST'
  | 'SOUTH'
  | 'WEST';

/**
 * Canonical edge coordinates use lattice nodes, not cell ownership. A north
 * edge of one bay and the south edge of its neighbour therefore become the
 * same address automatically.
 */
export type SurvivalBuildV3CanonicalEdge =
  | {
      readonly kind: 'CARDINAL';
      /** U runs between (u,v) and (u+1,v); V between (u,v) and (u,v+1). */
      readonly axis: 'U' | 'V';
      readonly u: number;
      readonly v: number;
    }
  | {
      readonly kind: 'DIAGONAL';
      readonly u: number;
      readonly v: number;
      readonly diagonal: 'NORTH_WEST_TO_SOUTH_EAST' | 'SOUTH_WEST_TO_NORTH_EAST';
    };

export type SurvivalBuildV3AnchorAddress =
  | {
      readonly kind: 'NODE';
      readonly level: number;
      readonly u: number;
      readonly v: number;
    }
  | {
      readonly kind: 'EDGE';
      readonly level: number;
      readonly edge: SurvivalBuildV3CanonicalEdge;
    }
  | {
      readonly kind: 'BAY';
      readonly level: number;
      readonly u: number;
      readonly v: number;
      readonly shape: 'SQUARE' | 'WEDGE' | 'SECTOR';
    }
  | {
      readonly kind: 'SURFACE';
      readonly hostPieceId: string;
      readonly mountId: string;
    };

export interface SurvivalBuildV3Frame {
  readonly id: string;
  readonly origin: Readonly<{ x: number; y: number; z: number }>;
  readonly yawDegrees: number;
  readonly moduleMetres: number;
  readonly foundationTopMetres: number;
  readonly floorThicknessMetres: number;
  readonly storeyHeightMetres: number;
}

export interface SurvivalBuildV3Site {
  readonly id: string;
  readonly frameId: string;
  readonly kind: SurvivalBuildV3SiteKind;
  readonly excavationSiteId?: string;
  readonly pieceIds: readonly string[];
  readonly topologyRevision: number;
}

export interface SurvivalBuildV3Connection {
  readonly jointId: string;
  readonly portId: string;
  readonly role: SurvivalBuildV3ConnectionRole;
}

export interface SurvivalBuildV3Piece {
  readonly id: string;
  readonly siteId: string;
  readonly definitionId: SurvivalBuildPieceId;
  readonly role: SurvivalBuildV3Role;
  readonly anchor: SurvivalBuildV3AnchorAddress;
  /** Versioned socket/free placement; absent on all legacy grid pieces. */
  readonly freePose?: import('./SurvivalBuildV4Placement').SurvivalBuildV4Pose;
  readonly damage?: import('./SurvivalBuildDamage').BuildDamageState;
  readonly mirrored?: boolean;
  readonly paintId?: string;
  /** Presentation rotation inside a BAY. Structural ownership stays canonical. */
  readonly yawOffsetDegrees?: number;
  /** Whole two-metre bays crossed by a roof frame/cover. Omitted legacy pieces
   * are exactly one bay wide. The anchor remains the first eave-side bay. */
  readonly spanBays?: number;
  readonly roofProfile?: import('./SurvivalBuildV3Roof').SurvivalRoofProfile;
  /** Undefined means a complete legacy frame. New guided frames start at 1. */
  readonly roofAssemblyStage?: number;
  readonly roofMember?: import('./SurvivalModularRoof').ModularRoofMember;
  readonly terrainFit?: SurvivalBuildV3TerrainFit;
  readonly buildState: 'PLANNED' | 'SITE_PREPARATION' | 'FRAME_PLACED' | 'FASTENED' | 'FINISHED' | 'DAMAGED';
  readonly connections: readonly SurvivalBuildV3Connection[];
  readonly revision: number;
}

export interface SurvivalBuildV3JointMember {
  readonly pieceId: string;
  readonly portId: string;
  readonly role: SurvivalBuildV3ConnectionRole;
}

export interface SurvivalBuildV3Joint {
  readonly id: string;
  readonly siteId: string;
  readonly address: SurvivalBuildV3AnchorAddress;
  readonly capacityClass: 'BRANCH' | 'EDGE' | 'BAY' | 'SURFACE';
  readonly members: readonly SurvivalBuildV3JointMember[];
}

export interface SurvivalBuildV3SaveData {
  readonly version: typeof SURVIVAL_BUILD_V3_SAVE_VERSION;
  readonly sites: readonly SurvivalBuildV3Site[];
  readonly frames: readonly SurvivalBuildV3Frame[];
  readonly pieces: readonly SurvivalBuildV3Piece[];
  readonly joints: readonly SurvivalBuildV3Joint[];
  readonly nextSiteSerial: number;
  readonly nextFrameSerial: number;
  readonly nextPieceSerial: number;
}

export interface SurvivalBuildV3WorldTransform {
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly yawDegrees: number;
}

const assertInteger = (value: number, label: string): number => {
  if (!Number.isInteger(value)) throw new Error(`${label} must be an integer.`);
  return Object.is(value, -0) ? 0 : value;
};

export const normalizeSurvivalBuildV3Yaw = (yawDegrees: number): number => {
  const normalized = ((yawDegrees + 180) % 360 + 360) % 360 - 180;
  return Object.is(normalized, -0) ? 0 : normalized;
};

export const snapSurvivalBuildV3FrameYaw = (yawDegrees: number): number =>
  normalizeSurvivalBuildV3Yaw(
    Math.round(yawDegrees / SURVIVAL_BUILD_V3_YAW_STEP_DEGREES) *
      SURVIVAL_BUILD_V3_YAW_STEP_DEGREES,
  );

export const createSurvivalBuildV3Frame = (options: Readonly<{
  id: string;
  x: number;
  y: number;
  z: number;
  yawDegrees: number;
  moduleMetres?: number;
}>): SurvivalBuildV3Frame => ({
  id: options.id,
  origin: { x: options.x, y: options.y, z: options.z },
  yawDegrees: snapSurvivalBuildV3FrameYaw(options.yawDegrees),
  moduleMetres: options.moduleMetres ?? SURVIVAL_BUILD_V3_MODULE_METRES,
  foundationTopMetres: 0.34,
  floorThicknessMetres: 0.14,
  storeyHeightMetres: 2.15,
});

export const survivalBuildV3LocalToWorld = (
  frame: Readonly<SurvivalBuildV3Frame>,
  local: Readonly<{ x: number; y: number; z: number }>,
): Readonly<{ x: number; y: number; z: number }> => {
  const yaw = frame.yawDegrees * Math.PI / 180;
  return {
    x: frame.origin.x + local.x * Math.cos(yaw) + local.z * Math.sin(yaw),
    y: frame.origin.y + local.y,
    z: frame.origin.z - local.x * Math.sin(yaw) + local.z * Math.cos(yaw),
  };
};

export const survivalBuildV3WorldToLocal = (
  frame: Readonly<SurvivalBuildV3Frame>,
  world: Readonly<{ x: number; y: number; z: number }>,
): Readonly<{ x: number; y: number; z: number }> => {
  const yaw = frame.yawDegrees * Math.PI / 180;
  const deltaX = world.x - frame.origin.x;
  const deltaZ = world.z - frame.origin.z;
  return {
    x: deltaX * Math.cos(yaw) - deltaZ * Math.sin(yaw),
    y: world.y - frame.origin.y,
    z: deltaX * Math.sin(yaw) + deltaZ * Math.cos(yaw),
  };
};

export const canonicalSurvivalBuildV3Edge = (
  u: number,
  v: number,
  direction: SurvivalBuildV3EdgeDirection,
): SurvivalBuildV3CanonicalEdge => {
  const safeU = assertInteger(u, 'u');
  const safeV = assertInteger(v, 'v');
  if (direction === 'NORTH') {
    return { kind: 'CARDINAL', axis: 'U', u: safeU, v: safeV };
  }
  if (direction === 'SOUTH') {
    return { kind: 'CARDINAL', axis: 'U', u: safeU, v: safeV + 1 };
  }
  if (direction === 'WEST') {
    return { kind: 'CARDINAL', axis: 'V', u: safeU, v: safeV };
  }
  return { kind: 'CARDINAL', axis: 'V', u: safeU + 1, v: safeV };
};

export const survivalBuildV3AnchorKey = (
  address: Readonly<SurvivalBuildV3AnchorAddress>,
): string => {
  if (address.kind === 'NODE') {
    return `node:${address.level}:${address.u}:${address.v}`;
  }
  if (address.kind === 'BAY') {
    return `bay:${address.level}:${address.u}:${address.v}:${address.shape}`;
  }
  if (address.kind === 'SURFACE') {
    return `surface:${address.hostPieceId}:${address.mountId}`;
  }
  const edge = address.edge;
  return edge.kind === 'CARDINAL'
    ? `edge:${address.level}:${edge.axis}:${edge.u}:${edge.v}`
    : `edge:${address.level}:diagonal:${edge.u}:${edge.v}:${edge.diagonal}`;
};

export const survivalBuildV3EdgeEndpoints = (
  edge: Readonly<SurvivalBuildV3CanonicalEdge>,
): readonly [Readonly<{ u: number; v: number }>, Readonly<{ u: number; v: number }>] => {
  if (edge.kind === 'DIAGONAL') {
    return edge.diagonal === 'NORTH_WEST_TO_SOUTH_EAST'
      ? [{ u: edge.u, v: edge.v }, { u: edge.u + 1, v: edge.v + 1 }]
      : [{ u: edge.u, v: edge.v + 1 }, { u: edge.u + 1, v: edge.v }];
  }
  return edge.axis === 'U'
    ? [{ u: edge.u, v: edge.v }, { u: edge.u + 1, v: edge.v }]
    : [{ u: edge.u, v: edge.v }, { u: edge.u, v: edge.v + 1 }];
};

export const survivalBuildV3BayEdges = (
  u: number,
  v: number,
  level: number,
): readonly SurvivalBuildV3AnchorAddress[] => [
  { kind: 'EDGE', level, edge: canonicalSurvivalBuildV3Edge(u, v, 'NORTH') },
  { kind: 'EDGE', level, edge: canonicalSurvivalBuildV3Edge(u, v, 'EAST') },
  { kind: 'EDGE', level, edge: canonicalSurvivalBuildV3Edge(u, v, 'SOUTH') },
  { kind: 'EDGE', level, edge: canonicalSurvivalBuildV3Edge(u, v, 'WEST') },
];

export const survivalBuildV3BaysTouchingEdge = (
  edge: Readonly<SurvivalBuildV3CanonicalEdge>,
): readonly Readonly<{ u: number; v: number }>[] => {
  if (edge.kind === 'DIAGONAL') return [{ u: edge.u, v: edge.v }];
  return edge.axis === 'U'
    ? [{ u: edge.u, v: edge.v - 1 }, { u: edge.u, v: edge.v }]
    : [{ u: edge.u - 1, v: edge.v }, { u: edge.u, v: edge.v }];
};

export const survivalBuildV3BaysTouchingNode = (
  u: number,
  v: number,
): readonly Readonly<{ u: number; v: number }>[] => [
  { u: u - 1, v: v - 1 },
  { u, v: v - 1 },
  { u: u - 1, v },
  { u, v },
];

export const survivalBuildV3StructuralLevelY = (
  frame: Readonly<SurvivalBuildV3Frame>,
  level: number,
): number => frame.foundationTopMetres + level * frame.storeyHeightMetres;

export const survivalBuildV3AnchorLocalTransform = (
  frame: Readonly<SurvivalBuildV3Frame>,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
  role: SurvivalBuildV3Role,
): SurvivalBuildV3WorldTransform => {
  if (anchor.kind === 'SURFACE') {
    throw new Error('A surface mount needs its host piece transform.');
  }
  const module = frame.moduleMetres;
  let x = 0;
  let z = 0;
  let yawDegrees = 0;
  if (anchor.kind === 'NODE') {
    x = anchor.u * module;
    z = anchor.v * module;
  } else if (anchor.kind === 'BAY') {
    x = (anchor.u + 0.5) * module;
    z = (anchor.v + 0.5) * module;
  } else if (anchor.edge.kind === 'DIAGONAL') {
    x = (anchor.edge.u + 0.5) * module;
    z = (anchor.edge.v + 0.5) * module;
    yawDegrees = anchor.edge.diagonal === 'NORTH_WEST_TO_SOUTH_EAST' ? -45 : 45;
  } else if (anchor.edge.axis === 'U') {
    x = (anchor.edge.u + 0.5) * module;
    z = anchor.edge.v * module;
  } else {
    x = anchor.edge.u * module;
    z = (anchor.edge.v + 0.5) * module;
    yawDegrees = -90;
  }

  const level = anchor.kind === 'NODE' || anchor.kind === 'EDGE' || anchor.kind === 'BAY'
    ? anchor.level
    : 0;
  const y = role === 'FOUNDATION'
    ? level * frame.storeyHeightMetres
    : survivalBuildV3StructuralLevelY(frame, level);
  return { x, y, z, yawDegrees };
};

export const survivalBuildV3AnchorWorldTransform = (
  frame: Readonly<SurvivalBuildV3Frame>,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
  role: SurvivalBuildV3Role,
): SurvivalBuildV3WorldTransform => {
  const local = survivalBuildV3AnchorLocalTransform(frame, anchor, role);
  const world = survivalBuildV3LocalToWorld(frame, local);
  return {
    ...world,
    yawDegrees: normalizeSurvivalBuildV3Yaw(frame.yawDegrees + local.yawDegrees),
  };
};

export const emptySurvivalBuildV3Save = (): SurvivalBuildV3SaveData => ({
  version: SURVIVAL_BUILD_V3_SAVE_VERSION,
  sites: [],
  frames: [],
  pieces: [],
  joints: [],
  nextSiteSerial: 1,
  nextFrameSerial: 1,
  nextPieceSerial: 1,
});
