/** Authored, movable first-loop landmark. Coordinates are shared by terrain,
 * navigation and presentation; a blank editor map never applies this profile. */
export const HEART_SANCTUARY = Object.freeze({
  x: -908, z: -304, groundY: 11.5,
  gateZ: 32, entranceWidth: 16, radius: 92,
  approach: { x: -908, z: -246 },
  templePrefab: 'TLW_HEART_TEMPLE_01',
  heartPrefab: 'TLW_PLANET_HEART_01',
  shellPrefab: 'TLW_SHADOW_HUSK_01',
});

const smooth = (a: number, b: number, v: number): number => {
  const t = Math.max(0, Math.min(1, (v - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/** Six bounded analytical landforms, not a second mesh above the snow. */
export function sanctuaryTerrainHeight(base: number, x: number, z: number): number {
  const u = x - HEART_SANCTUARY.x, v = z - HEART_SANCTUARY.z;
  if (Math.abs(u) > 58 || v < -45 || v > 63) return base;
  const blend = (1 - smooth(38, 58, Math.abs(u))) *
    smooth(-45, -26, v) * (1 - smooth(43, 63, v));
  const mound = (cx: number, cz: number, rx: number, rz: number, h: number) => {
    const d = Math.hypot((u - cx) / rx, (v - cz) / rz);
    return h * (1 - smooth(.28, 1, d));
  };
  const gateCliffs = mound(-21, 31, 13, 19, 27) + mound(21, 29, 13, 20, 32);
  const enclosure = mound(-26, 1, 17, 35, 22) + mound(26, 0, 17, 35, 25) +
    mound(0, -23, 34, 17, 29);
  const floor = HEART_SANCTUARY.groundY + smooth(8, 66, v) * 1.8;
  return base + (floor + Math.max(gateCliffs, enclosure) - base) * blend;
}

/** Interior walkable contour also keeps AI away from steep cliff faces. */
export function sanctuaryWalkable(u: number, v: number, radius = .3): boolean {
  if (v < -7 || v > 78) return false;
  const halfWidth = v < 17 ? 15 : v < 43 ? 8 : 23;
  if (Math.abs(u) > halfWidth - radius) return false;
  // Temple columns and plinth are physical, with a wide open central aisle.
  if (Math.hypot(u, v) < 1.35 + radius) return false;
  for (const cx of [-6, 6]) for (const cz of [-4, 3, 10]) {
    if (Math.hypot(u - cx, v - cz) < .68 + radius) return false;
  }
  return true;
}

export const inSanctuary = (x: number, z: number, radius: number = HEART_SANCTUARY.radius): boolean =>
  Math.hypot(x - HEART_SANCTUARY.x, z - HEART_SANCTUARY.z) < radius;

/** Reserve only the temple aisle and fighting approach in generated ecology.
 * Never deletes authored assets or renumbers saved scenery-tree identities. */
export const sanctuarySceneryExcluded = (x: number, z: number): boolean => {
  const u = x - HEART_SANCTUARY.x, v = z - HEART_SANCTUARY.z;
  return v > -13 && v < 76 && Math.abs(u) < (v < 19 ? 18 : v < 45 ? 11 : 10);
};
