export interface PlayerVesselModelTuning {
  visualScale: number;
  sourceForwardDegrees: number;
  yawCorrectionDegrees: number;
  centerOffsetX: number;
  centerOffsetZ: number;
  visualBowOffset: number;
}

export const PLAYER_VESSEL_MODEL_TUNING: Readonly<PlayerVesselModelTuning> = {
  visualScale: 1.15 * 1.2,
  sourceForwardDegrees: -26,
  yawCorrectionDegrees: 26,
  centerOffsetX: 0,
  centerOffsetZ: 0,
  visualBowOffset: 1.515,
};

export const getPlayerVesselForwardErrorDegrees = (
  tuning: Readonly<PlayerVesselModelTuning> =
    PLAYER_VESSEL_MODEL_TUNING,
): number =>
  tuning.sourceForwardDegrees + tuning.yawCorrectionDegrees;

