import { Box3, Mesh, type Object3D, type Vector3 } from 'three';

/** Real roof prefabs falling independently. Authority owns support/collision;
 * this short-lived presentation needs neither rigid bodies nor new flames. */
export class SurvivalRoofCollapsePresentation {
  private readonly falling:Array<{root:Object3D;from:Vector3;ground:number;elapsed:number;duration:number;phase:number;pitch:number;roll:number}>=[];
  public get count():number{return this.falling.length;}
  public add(root:Object3D,ground:number,seed:number):boolean {
    if(this.falling.length>=48)return false;
    root.visible=true;
    this.falling.push({root,from:root.position.clone(),ground,elapsed:0,
      duration:Math.max(.6,Math.min(2.5,Math.sqrt(Math.max(.1,root.position.y-ground)/4.9))),
      phase:seed,pitch:root.rotation.x,roll:root.rotation.z});
    return true;
  }
  public update(delta:number,dispose:(root:Object3D)=>void):void {
    for(let i=this.falling.length-1;i>=0;i--) {
      const f=this.falling[i]!;f.elapsed+=Math.max(0,Math.min(.1,delta));
      const t=Math.min(1,f.elapsed/f.duration);
      f.root.position.copy(f.from);f.root.position.y+=(f.ground-f.from.y)*t*t;
      f.root.position.x+=Math.sin(f.phase)*.3*t;f.root.position.z+=Math.cos(f.phase)*.3*t;
      f.root.rotation.x=f.pitch+Math.sin(f.phase*1.7)*.55*t;
      f.root.rotation.z=f.roll+Math.cos(f.phase*1.3)*.55*t;
      if(t>=1) {
        const box=new Box3().setFromObject(f.root);
        f.root.position.y+=Math.max(0,f.ground-box.min.y);
      }
      const fade=Math.max(0,1-(f.elapsed-f.duration)/.65);
      if(t>=1)f.root.traverse(object=>{
        if(!(object instanceof Mesh))return;
        for(const material of Array.isArray(object.material)?object.material:[object.material]){
          material.transparent=true;material.opacity=fade;
        }
      });
      if(fade===0){dispose(f.root);f.root.removeFromParent();this.falling.splice(i,1);}
    }
  }
  public clear(dispose:(root:Object3D)=>void):void {
    for(const f of this.falling){dispose(f.root);f.root.removeFromParent();}
    this.falling.length=0;
  }
}
