import type { BufferAttribute } from 'three';

/** Preserve unpublished patches, with bounded bookkeeping for culled meshes. */
export function queueAttributeUpdate(attribute: BufferAttribute, start: number, count: number): void {
  if (count <= 0) return;
  if (attribute.updateRanges.length < 64) {
    attribute.addUpdateRange(start, count);
    return;
  }
  let first = start, end = start + count;
  for (const range of attribute.updateRanges) {
    first = Math.min(first, range.start);
    end = Math.max(end, range.start + range.count);
  }
  attribute.clearUpdateRanges();
  attribute.addUpdateRange(first, end - first);
}
