export interface SurvivalBurnedDebrisLifecycleFrame {
  readonly heat: number;
  readonly fallSeconds: number;
  readonly position: Readonly<{ x: number; y: number; z: number }>;
  readonly rotationDegrees: Readonly<{ x: number; y: number; z: number }>;
}

export interface SurvivalRuntimePieceEntranceFrame {
  readonly remainingSeconds: number;
  readonly scale: number;
  readonly verticalOffset: number;
}

const clampDelta = (deltaSeconds: number): number =>
  Math.max(0, Math.min(0.1, deltaSeconds));

const lerp = (from: number, to: number, amount: number): number =>
  from + (to - from) * amount;

export const survivalRuntimePieceEntrancePose = (
  remainingSeconds: number,
  durationSeconds = 0.34,
): Omit<SurvivalRuntimePieceEntranceFrame, 'remainingSeconds'> => {
  const duration = Math.max(0.001, durationSeconds);
  const remaining = Math.max(0, Math.min(duration, remainingSeconds));
  const progress = 1 - remaining / duration;
  const scale = progress < 0.58
    ? 0.76 + progress / 0.58 * 0.34
    : 1.1 - (progress - 0.58) / 0.42 * 0.1;
  return {
    scale,
    verticalOffset: Math.sin(Math.PI * progress) * (1 - progress) * 0.13,
  };
};

/** Pure lifecycle for an authored piece's short placement entrance. */
export const stepSurvivalRuntimePieceEntrance = (options: Readonly<{
  deltaSeconds: number;
  remainingSeconds: number;
  durationSeconds?: number;
}>): SurvivalRuntimePieceEntranceFrame => {
  const remainingSeconds = Math.max(
    0,
    options.remainingSeconds - Math.max(0, options.deltaSeconds),
  );
  return {
    remainingSeconds,
    ...survivalRuntimePieceEntrancePose(
      remainingSeconds,
      options.durationSeconds,
    ),
  };
};

/** Deterministic state transition for one charred structural mesh. Rendering,
 * terrain sampling and snow mutation stay outside this lifecycle function. */
export const stepSurvivalBurnedDebrisLifecycle = (options: Readonly<{
  deltaSeconds: number;
  heat: number;
  fallSeconds: number;
  fallDuration: number;
  fallFromX: number;
  fallFromY: number;
  fallFromZ: number;
  fallFromYawDegrees: number;
  x: number;
  groundY: number;
  z: number;
  yawDegrees: number;
  pitchDegrees: number;
  rollDegrees: number;
}>): SurvivalBurnedDebrisLifecycleFrame => {
  const delta = clampDelta(options.deltaSeconds);
  const heat = Math.max(0, options.heat - delta / 105);
  const fallSeconds = Math.max(0, options.fallSeconds - delta);
  if (options.fallSeconds > 0) {
    const progress = 1 - fallSeconds / Math.max(0.001, options.fallDuration);
    const gravity = progress * progress;
    return {
      heat,
      fallSeconds,
      position: {
        x: lerp(options.fallFromX, options.x, progress),
        y: lerp(options.fallFromY, options.groundY, gravity) +
          Math.sin(progress * Math.PI) * 0.08,
        z: lerp(options.fallFromZ, options.z, progress),
      },
      rotationDegrees: {
        x: options.pitchDegrees * gravity,
        y: lerp(options.fallFromYawDegrees, options.yawDegrees, progress),
        z: options.rollDegrees * gravity,
      },
    };
  }
  return {
    heat,
    fallSeconds: 0,
    position: { x: options.x, y: options.groundY, z: options.z },
    rotationDegrees: {
      x: options.pitchDegrees,
      y: options.yawDegrees,
      z: options.rollDegrees,
    },
  };
};
