import {
  ICE_AUTHORITY_BASELINE_ID,
  ICE_AUTHORITY_CHUNK_SIZE,
  ICE_AUTHORITY_FORMAT_VERSION,
  IceAuthorityField,
  type IceAuthorityFloeState,
  type IceFloeMovementSnapshot,
} from '../../ice/IceAuthorityState';
import { IceCellOwner } from '../../ice/IceOwnership';
import { revision, type Revision } from '../../netcode/core/NetworkPrimitives';
import {
  iceChunkChecksum,
  unpackIceCellRuns,
  unpackIceDeltaRuns,
  type IceBaselinePartPayload,
  type IceDeltaPayload,
  type IceFloeBaselinePayload,
  type IceFloeLifecyclePayload,
  type IceFloeMovementPayload,
  type IceFractureVisualEvent,
  type IceFractureVisualPayload,
  type ReplicatedIceCell,
} from '../../netcode/protocol/IceReplication';

export interface ClientIceChunkSnapshot {
  readonly chunkX: number;
  readonly chunkZ: number;
  readonly revision: Revision;
  readonly topologyRevision: Revision;
  readonly checksum: string;
  readonly changes: readonly ReplicatedIceCell[];
}

export interface ClientIceDirtyRange {
  readonly chunkX: number;
  readonly chunkZ: number;
  readonly minimumIndex: number;
  readonly maximumIndex: number;
  readonly fieldMask: IceAuthorityField;
  readonly topologyChanged: boolean;
}

export interface IceChunkResyncRequest {
  readonly chunkX: number;
  readonly chunkZ: number;
  readonly observedRevision: Revision;
  readonly observedTopologyRevision: Revision;
}

export interface IceReplicationClientDiagnostics {
  readonly completedBaselines: number;
  readonly acceptedBaselineParts: number;
  readonly acceptedDeltas: number;
  readonly staleDeltas: number;
  readonly revisionMismatches: number;
  readonly topologyMismatches: number;
  readonly checksumMismatches: number;
  readonly resyncRequests: number;
  readonly chunks: number;
  readonly floes: number;
  readonly acceptedLifecycleEvents: number;
  readonly staleMovementSnapshots: number;
  readonly fractureEvents: number;
}

export interface IceReplicationClientOptions {
  readonly expectedWorldDatasetHash: string;
  readonly expectedBaselineId?: string;
  readonly baselineCell: (
    chunkX: number,
    chunkZ: number,
    localIndex: number,
  ) => Readonly<ReplicatedIceCell>;
}

interface MutableClientChunk {
  chunkX: number;
  chunkZ: number;
  revision: Revision;
  topologyRevision: Revision;
  checksum: string;
  changes: Map<number, ReplicatedIceCell>;
}

type MutableReplicatedIceCell = {
  -readonly [TKey in keyof ReplicatedIceCell]: ReplicatedIceCell[TKey];
};

interface StagedBaseline {
  transferId: string;
  scope: IceBaselinePartPayload['scope'];
  baselineId: string;
  worldDatasetHash: string;
  columns: number;
  rows: number;
  cellSize: number;
  partCount: number;
  serverTick: IceBaselinePartPayload['serverTick'];
  parts: Map<number, IceBaselinePartPayload>;
}

const chunkKey = (chunkX: number, chunkZ: number): string => `${chunkX},${chunkZ}`;

const cloneCell = (
  cell: Readonly<ReplicatedIceCell>,
): MutableReplicatedIceCell => ({
  ...cell,
});

const sameCell = (
  left: Readonly<ReplicatedIceCell>,
  right: Readonly<ReplicatedIceCell>,
): boolean => left.thickness === right.thickness &&
  left.openness === right.openness &&
  left.snow === right.snow &&
  left.channelMemory === right.channelMemory &&
  left.channelAge === right.channelAge &&
  left.owner === right.owner &&
  left.floeId === right.floeId;

/** Sparse canonical client proxy. It never simulates authoritative ice. */
export class IceReplicationClient {
  private readonly chunks = new Map<string, MutableClientChunk>();
  private readonly floes = new Map<number, IceAuthorityFloeState>();
  private readonly resync = new Map<string, IceChunkResyncRequest>();
  private readonly lifecycleEventIds = new Set<string>();
  private readonly fractureEventIds = new Set<string>();
  private transfer?: StagedBaseline;
  private columns?: number;
  private rows?: number;
  private cellSize?: number;
  private lastDeltaSequence = 0;
  private lastFloeBaselineSequence = 0;
  private lastLifecycleSequence = 0;
  private lastMovementSequence = 0;
  private readonly stats = {
    completedBaselines: 0,
    acceptedBaselineParts: 0,
    acceptedDeltas: 0,
    staleDeltas: 0,
    revisionMismatches: 0,
    topologyMismatches: 0,
    checksumMismatches: 0,
    resyncRequests: 0,
    acceptedLifecycleEvents: 0,
    staleMovementSnapshots: 0,
    fractureEvents: 0,
  };

  public constructor(private readonly options: Readonly<IceReplicationClientOptions>) {}

  public applyBaselinePart(
    payload: Readonly<IceBaselinePartPayload>,
  ): {
    accepted: boolean;
    completed: boolean;
    updatedChunks: readonly ClientIceChunkSnapshot[];
    dirtyRanges: readonly ClientIceDirtyRange[];
  } {
    if (
      payload.baselineId !==
        (this.options.expectedBaselineId ?? ICE_AUTHORITY_BASELINE_ID) ||
      payload.formatVersion !== ICE_AUTHORITY_FORMAT_VERSION ||
      payload.worldDatasetHash !== this.options.expectedWorldDatasetHash
    ) return { accepted: false, completed: false, updatedChunks: [], dirtyRanges: [] };
    if (!this.transfer || this.transfer.transferId !== payload.transferId) {
      this.transfer = {
        transferId: payload.transferId,
        scope: payload.scope,
        baselineId: payload.baselineId,
        worldDatasetHash: payload.worldDatasetHash,
        columns: payload.columns,
        rows: payload.rows,
        cellSize: payload.cellSize,
        partCount: payload.partCount,
        serverTick: payload.serverTick,
        parts: new Map(),
      };
    }
    if (
      this.transfer.scope !== payload.scope ||
      this.transfer.partCount !== payload.partCount ||
      this.transfer.serverTick !== payload.serverTick ||
      this.transfer.columns !== payload.columns ||
      this.transfer.rows !== payload.rows ||
      this.transfer.cellSize !== payload.cellSize ||
      this.transfer.parts.has(payload.partIndex)
    ) return { accepted: false, completed: false, updatedChunks: [], dirtyRanges: [] };
    this.transfer.parts.set(payload.partIndex, payload as IceBaselinePartPayload);
    this.stats.acceptedBaselineParts += 1;
    if (this.transfer.parts.size !== this.transfer.partCount) {
      return { accepted: true, completed: false, updatedChunks: [], dirtyRanges: [] };
    }
    const staged = new Map<string, MutableClientChunk>();
    for (let partIndex = 0; partIndex < this.transfer.partCount; partIndex += 1) {
      const part = this.transfer.parts.get(partIndex);
      if (!part) return { accepted: false, completed: false, updatedChunks: [], dirtyRanges: [] };
      for (const chunk of part.chunks) {
        const key = chunkKey(chunk.chunkX, chunk.chunkZ);
        const changes = unpackIceCellRuns(chunk.runs);
        if (staged.has(key) || iceChunkChecksum(
          chunk.chunkX,
          chunk.chunkZ,
          chunk.revision,
          chunk.topologyRevision,
          changes,
        ) !== chunk.checksum) {
          this.stats.checksumMismatches += 1;
          this.transfer = undefined;
          return { accepted: false, completed: false, updatedChunks: [], dirtyRanges: [] };
        }
        staged.set(key, {
          chunkX: chunk.chunkX,
          chunkZ: chunk.chunkZ,
          revision: chunk.revision,
          topologyRevision: chunk.topologyRevision,
          checksum: chunk.checksum,
          changes: new Map(changes.map((cell) => [cell.index, cloneCell(cell)])),
        });
      }
    }
    const scope = this.transfer.scope;
    if (scope === 'FULL') {
      this.chunks.clear();
      this.lastDeltaSequence = 0;
      this.resync.clear();
      this.columns = this.transfer.columns;
      this.rows = this.transfer.rows;
      this.cellSize = this.transfer.cellSize;
    } else if (
      (this.columns !== undefined && this.columns !== this.transfer.columns) ||
      (this.rows !== undefined && this.rows !== this.transfer.rows) ||
      (this.cellSize !== undefined && this.cellSize !== this.transfer.cellSize)
    ) {
      this.transfer = undefined;
      return { accepted: false, completed: false, updatedChunks: [], dirtyRanges: [] };
    }
    for (const [key, chunk] of staged) {
      this.chunks.set(key, chunk);
      this.resync.delete(key);
    }
    const updatedChunks = [...staged.values()].map((chunk) => this.cloneChunk(chunk));
    const dirtyRanges = updatedChunks.map((chunk): ClientIceDirtyRange => ({
      chunkX: chunk.chunkX,
      chunkZ: chunk.chunkZ,
      minimumIndex: 0,
      maximumIndex: ICE_AUTHORITY_CHUNK_SIZE ** 2 - 1,
      fieldMask: IceAuthorityField.All,
      topologyChanged: true,
    }));
    this.transfer = undefined;
    this.stats.completedBaselines += 1;
    return { accepted: true, completed: true, updatedChunks, dirtyRanges };
  }

  public applyDelta(payload: Readonly<IceDeltaPayload>): {
    accepted: boolean;
    updatedChunks: readonly ClientIceChunkSnapshot[];
    dirtyRanges: readonly ClientIceDirtyRange[];
  } {
    if (payload.deltaSequence <= this.lastDeltaSequence) {
      this.stats.staleDeltas += 1;
      return { accepted: false, updatedChunks: [], dirtyRanges: [] };
    }
    this.lastDeltaSequence = payload.deltaSequence;
    const updated: ClientIceChunkSnapshot[] = [];
    const dirty: ClientIceDirtyRange[] = [];
    for (const delta of payload.chunks) {
      const key = chunkKey(delta.chunkX, delta.chunkZ);
      const existing = this.chunks.get(key);
      const observedRevision = existing?.revision ?? revision(0);
      const observedTopology = existing?.topologyRevision ?? revision(0);
      if (observedRevision !== delta.baseRevision) {
        this.stats.revisionMismatches += 1;
        this.queueResync(delta.chunkX, delta.chunkZ, observedRevision, observedTopology);
        continue;
      }
      if (observedTopology !== delta.baseTopologyRevision) {
        this.stats.topologyMismatches += 1;
        this.queueResync(delta.chunkX, delta.chunkZ, observedRevision, observedTopology);
        continue;
      }
      const changes = new Map(existing?.changes ?? []);
      const cellDeltas = unpackIceDeltaRuns(delta.runs);
      let minimumIndex = 255;
      let maximumIndex = 0;
      let fieldMask = IceAuthorityField.None;
      for (const change of cellDeltas) {
        const baseline = cloneCell(
          this.options.baselineCell(delta.chunkX, delta.chunkZ, change.index),
        );
        const current = cloneCell(changes.get(change.index) ?? baseline);
        if (change.fieldMask & IceAuthorityField.Thickness) current.thickness = change.thickness!;
        if (change.fieldMask & IceAuthorityField.Openness) current.openness = change.openness!;
        if (change.fieldMask & IceAuthorityField.Snow) current.snow = change.snow!;
        if (change.fieldMask & IceAuthorityField.ChannelMemory) {
          current.channelMemory = change.channelMemory!;
        }
        if (change.fieldMask & IceAuthorityField.ChannelAge) {
          current.channelAge = change.channelAge!;
        }
        if (change.fieldMask & IceAuthorityField.Owner) current.owner = change.owner!;
        if (change.fieldMask & IceAuthorityField.FloeMembership) current.floeId = change.floeId!;
        if (sameCell(current, baseline)) changes.delete(change.index);
        else changes.set(change.index, current);
        minimumIndex = Math.min(minimumIndex, change.index);
        maximumIndex = Math.max(maximumIndex, change.index);
        fieldMask |= change.fieldMask;
      }
      const full = [...changes.values()].sort((a, b) => a.index - b.index);
      const checksum = iceChunkChecksum(
        delta.chunkX,
        delta.chunkZ,
        delta.revision,
        delta.topologyRevision,
        full,
      );
      if (checksum !== delta.checksum) {
        this.stats.checksumMismatches += 1;
        this.queueResync(delta.chunkX, delta.chunkZ, observedRevision, observedTopology);
        continue;
      }
      const next: MutableClientChunk = {
        chunkX: delta.chunkX,
        chunkZ: delta.chunkZ,
        revision: delta.revision,
        topologyRevision: delta.topologyRevision,
        checksum,
        changes,
      };
      this.chunks.set(key, next);
      this.resync.delete(key);
      updated.push(this.cloneChunk(next));
      const topologyChanged = delta.topologyRevision !== delta.baseTopologyRevision;
      dirty.push({
        chunkX: delta.chunkX,
        chunkZ: delta.chunkZ,
        minimumIndex: cellDeltas.length ? minimumIndex : 0,
        maximumIndex: cellDeltas.length ? maximumIndex : 0,
        fieldMask,
        topologyChanged,
      });
    }
    this.stats.acceptedDeltas += 1;
    return { accepted: true, updatedChunks: updated, dirtyRanges: dirty };
  }

  public applyFloeBaseline(payload: Readonly<IceFloeBaselinePayload>): boolean {
    if (payload.baselineSequence <= this.lastFloeBaselineSequence) return false;
    this.lastFloeBaselineSequence = payload.baselineSequence;
    this.floes.clear();
    for (const floe of payload.floes) this.floes.set(floe.id, this.cloneFloe(floe));
    this.lifecycleEventIds.clear();
    this.lastLifecycleSequence = 0;
    this.lastMovementSequence = 0;
    return true;
  }

  public applyFloeLifecycle(payload: Readonly<IceFloeLifecyclePayload>): boolean {
    if (payload.lifecycleSequence <= this.lastLifecycleSequence) return false;
    this.lastLifecycleSequence = payload.lifecycleSequence;
    for (const event of payload.events) {
      if (this.lifecycleEventIds.has(event.eventId)) continue;
      this.lifecycleEventIds.add(event.eventId);
      if (event.kind === 'REMOVE' || event.kind === 'REATTACH') {
        this.floes.delete(event.floeId);
      } else if (event.floe) {
        this.floes.set(event.floeId, this.cloneFloe(event.floe));
      }
      this.stats.acceptedLifecycleEvents += 1;
    }
    this.trimIdSet(this.lifecycleEventIds, 8_192);
    return true;
  }

  public applyFloeMovement(payload: Readonly<IceFloeMovementPayload>): boolean {
    if (payload.snapshotSequence <= this.lastMovementSequence) {
      this.stats.staleMovementSnapshots += payload.floes.length;
      return false;
    }
    this.lastMovementSequence = payload.snapshotSequence;
    for (const movement of payload.floes) {
      const floe = this.floes.get(movement.floeId);
      if (!floe || movement.movementRevision <= floe.movementRevision) {
        this.stats.staleMovementSnapshots += 1;
        continue;
      }
      this.floes.set(movement.floeId, {
        ...floe,
        ...this.movementFields(movement),
      });
    }
    return true;
  }

  public acceptFractureVisuals(
    payload: Readonly<IceFractureVisualPayload>,
  ): readonly IceFractureVisualEvent[] {
    const accepted: IceFractureVisualEvent[] = [];
    for (const event of payload.events) {
      if (this.fractureEventIds.has(event.eventId)) continue;
      this.fractureEventIds.add(event.eventId);
      accepted.push({
        ...event,
        worldPosition: {
          chunk: { ...event.worldPosition.chunk },
          local: { ...event.worldPosition.local },
        },
      });
    }
    this.stats.fractureEvents += accepted.length;
    this.trimIdSet(this.fractureEventIds, 4_096);
    return accepted;
  }

  public listChunks(): readonly ClientIceChunkSnapshot[] {
    return [...this.chunks.values()]
      .sort((a, b) => a.chunkZ - b.chunkZ || a.chunkX - b.chunkX)
      .map((chunk) => this.cloneChunk(chunk));
  }

  public listFloes(): readonly IceAuthorityFloeState[] {
    return [...this.floes.values()]
      .sort((a, b) => a.id - b.id)
      .map((floe) => this.cloneFloe(floe));
  }

  public drainResyncRequests(): readonly IceChunkResyncRequest[] {
    const result = [...this.resync.values()];
    this.resync.clear();
    return result;
  }

  public worldDimensions(): Readonly<{
    columns?: number;
    rows?: number;
    cellSize?: number;
  }> {
    return { columns: this.columns, rows: this.rows, cellSize: this.cellSize };
  }

  public diagnostics(): IceReplicationClientDiagnostics {
    return {
      ...this.stats,
      chunks: this.chunks.size,
      floes: this.floes.size,
    };
  }

  public reset(): void {
    this.chunks.clear();
    this.floes.clear();
    this.resync.clear();
    this.lifecycleEventIds.clear();
    this.fractureEventIds.clear();
    this.transfer = undefined;
    this.columns = undefined;
    this.rows = undefined;
    this.cellSize = undefined;
    this.lastDeltaSequence = 0;
    this.lastFloeBaselineSequence = 0;
    this.lastLifecycleSequence = 0;
    this.lastMovementSequence = 0;
  }

  private queueResync(
    chunkX: number,
    chunkZ: number,
    observedRevision: Revision,
    observedTopologyRevision: Revision,
  ): void {
    const key = chunkKey(chunkX, chunkZ);
    if (this.resync.has(key)) return;
    this.resync.set(key, {
      chunkX,
      chunkZ,
      observedRevision,
      observedTopologyRevision,
    });
    this.stats.resyncRequests += 1;
  }

  private cloneChunk(chunk: Readonly<MutableClientChunk>): ClientIceChunkSnapshot {
    return {
      chunkX: chunk.chunkX,
      chunkZ: chunk.chunkZ,
      revision: chunk.revision,
      topologyRevision: chunk.topologyRevision,
      checksum: chunk.checksum,
      changes: [...chunk.changes.values()]
        .sort((a, b) => a.index - b.index)
        .map(cloneCell),
    };
  }

  private cloneFloe(floe: Readonly<IceAuthorityFloeState>): IceAuthorityFloeState {
    return { ...floe, cells: [...floe.cells] };
  }

  private movementFields(movement: Readonly<IceFloeMovementSnapshot>): Pick<
    IceAuthorityFloeState,
    | 'centerX' | 'centerZ' | 'offsetX' | 'offsetZ' | 'velocityX'
    | 'velocityZ' | 'yaw' | 'angularVelocity' | 'pressure' | 'movementRevision'
  > {
    return {
      centerX: movement.centerX,
      centerZ: movement.centerZ,
      offsetX: movement.offsetX,
      offsetZ: movement.offsetZ,
      velocityX: movement.velocityX,
      velocityZ: movement.velocityZ,
      yaw: movement.yaw,
      angularVelocity: movement.angularVelocity,
      pressure: movement.pressure,
      movementRevision: movement.movementRevision,
    };
  }

  private trimIdSet(set: Set<string>, maximum: number): void {
    if (set.size <= maximum) return;
    const remove = set.size - maximum;
    let index = 0;
    for (const id of set) {
      set.delete(id);
      index += 1;
      if (index >= remove) break;
    }
  }
}

export const openWaterIceBaselineCell = (
  _chunkX: number,
  _chunkZ: number,
  localIndex: number,
): ReplicatedIceCell => ({
  index: localIndex,
  thickness: 0,
  openness: 255,
  snow: 0,
  channelMemory: 0,
  channelAge: 0,
  owner: IceCellOwner.OpenWater,
  floeId: -1,
});
