import { clamp } from '../utils/math';

export interface TerrainSoftControl {
  readonly gridX: number;
  readonly gridZ: number;
  readonly deltaMetres: number;
}

/** Sparse cubic B-spline coefficients, not square corner heights. Positive
 * weights keep the surface bounded; shared derivatives remove the flat spots
 * that per-cell smoothstep interpolation produces at every grid line. */
export class TerrainSoftField {
  private readonly controls = new Map<string, number>();
  // Count controls whose cubic support touches each 32 m bucket. Unedited
  // world samples stay O(1), without filling the spline cache with zeros.
  private readonly occupiedBuckets = new Map<string, number>();
  private readonly patches = new Map<string, Float64Array>();

  public constructor(private readonly spacing: number) {}

  public get size(): number { return this.controls.size; }

  public get(x: number, z: number): number {
    return this.controls.get(`${x},${z}`) ?? 0;
  }

  public set(x: number, z: number, height: number): boolean {
    const value = Math.abs(height) < 1e-8 ? 0 : clamp(height, -64, 64);
    const previous = this.get(x, z);
    if (previous === value) return false;
    if ((previous === 0) !== (value === 0)) {
      const delta = value === 0 ? -1 : 1;
      for (let bz = Math.floor((z - 2) / 16); bz <= Math.floor((z + 1) / 16); bz++) {
        for (let bx = Math.floor((x - 2) / 16); bx <= Math.floor((x + 1) / 16); bx++) {
          const key = `${bx},${bz}`;
          const count = (this.occupiedBuckets.get(key) ?? 0) + delta;
          if (count === 0) this.occupiedBuckets.delete(key);
          else this.occupiedBuckets.set(key, count);
        }
      }
    }
    if (value === 0) this.controls.delete(`${x},${z}`);
    else this.controls.set(`${x},${z}`, value);
    // One coefficient affects only four patches in each direction.
    for (let dz = -2; dz <= 1; dz++) {
      for (let dx = -2; dx <= 1; dx++) this.patches.delete(`${x + dx},${z + dz}`);
    }
    return true;
  }

  public sample(worldX: number, worldZ: number): number {
    if (this.controls.size === 0) return 0;
    const sx = worldX / this.spacing, sz = worldZ / this.spacing;
    const x = Math.floor(sx), z = Math.floor(sz), tx = sx - x, tz = sz - z;
    if (!this.occupiedBuckets.has(`${Math.floor(x / 16)},${Math.floor(z / 16)}`)) return 0;
    const key = `${x},${z}`;
    let patch = this.patches.get(key);
    if (!patch) {
      patch = new Float64Array(16);
      for (let row = 0; row < 4; row++) {
        const a = this.get(x - 1, z + row - 1), b = this.get(x, z + row - 1);
        const c = this.get(x + 1, z + row - 1), d = this.get(x + 2, z + row - 1);
        patch.set([(-a + 3 * b - 3 * c + d) / 6,
          (a - 2 * b + c) / 2, (c - a) / 2, (a + 4 * b + c) / 6], row * 4);
      }
      // Bound runtime cache independently of world size and painted area.
      if (this.patches.size >= 2048) this.patches.delete(this.patches.keys().next().value!);
      this.patches.set(key, patch);
    }
    const a = ((patch[0]! * tx + patch[1]!) * tx + patch[2]!) * tx + patch[3]!;
    const b = ((patch[4]! * tx + patch[5]!) * tx + patch[6]!) * tx + patch[7]!;
    const c = ((patch[8]! * tx + patch[9]!) * tx + patch[10]!) * tx + patch[11]!;
    const d = ((patch[12]! * tx + patch[13]!) * tx + patch[14]!) * tx + patch[15]!;
    return (((-a + 3 * b - 3 * c + d) / 6 * tz + (a - 2 * b + c) / 2) * tz +
      (c - a) / 2) * tz + (a + 4 * b + c) / 6;
  }

  public importState(input: unknown): void {
    this.controls.clear();
    this.occupiedBuckets.clear();
    this.patches.clear();
    if (!Array.isArray(input)) return;
    for (const control of input) {
      if (!control || !Number.isSafeInteger(control.gridX) || !Number.isSafeInteger(control.gridZ) ||
          Math.abs(control.gridX) > 1_000_000 || Math.abs(control.gridZ) > 1_000_000 ||
          !Number.isFinite(control.deltaMetres)) continue;
      this.set(control.gridX, control.gridZ, control.deltaMetres);
    }
  }

  public exportState(): readonly TerrainSoftControl[] {
    return [...this.controls].map(([key, deltaMetres]) => {
      const [x, z] = key.split(',');
      return { gridX: Number(x), gridZ: Number(z), deltaMetres };
    }).sort((a, b) => a.gridZ - b.gridZ || a.gridX - b.gridX);
  }
}
