/** Canonical settlement state projected into map hints; no map-owned state. */
export const createSettlementMapMarkers = (
  settlement: Readonly<SettlementSnapshot>,
): readonly FieldTabletMapMarkerView[] => [
  ...settlement.resourceNodes.map((node) => ({
    id: `resource:${node.nodeId}`,
    kind: 'RESOURCE' as const,
    label: `${node.displayName} · ${node.status.toLowerCase()}`,
    x: node.x,
    z: node.z,
    tone: node.status === 'READY'
      ? 'ACTIVE' as const
      : node.status === 'DEPLETED'
        ? 'COMPLETE' as const
        : 'DEFAULT' as const,
    showLabel: false,
  })),
  ...settlement.cropPlots
    .filter((plot) => plot.status !== 'LOCKED')
    .map((plot) => ({
      id: `crop:${plot.plotId}`,
      kind: 'CROP' as const,
      label: `${plot.displayName} · ${plot.status.toLowerCase()}`,
      x: plot.x,
      z: plot.z,
      tone: plot.status === 'READY' ? 'ACTIVE' as const : 'DEFAULT' as const,
      showLabel: false,
    })),
  ...(settlement.cultivation ?? []).map((patch) => ({
    id: `cultivation:${patch.patchId}`,
    kind: 'CROP' as const,
    label: `${patch.displayName} · ${patch.cells.filter((cell) =>
      cell.status === 'READY').length}/9 ready`,
    x: patch.x,
    z: patch.z,
    tone: patch.cells.some((cell) => cell.status === 'READY')
      ? 'ACTIVE' as const
      : 'DEFAULT' as const,
    showLabel: false,
  })),
  ...(settlement.animalHabitats ?? []).map((habitat) => ({
    id: `animals:${habitat.habitatId}`,
    kind: 'PLACE' as const,
    label: `${habitat.displayName} · ${habitat.animals.filter((animal) =>
      animal.productReady).length} pickups ready`,
    x: habitat.x,
    z: habitat.z,
    tone: habitat.animals.some((animal) => animal.productReady)
      ? 'ACTIVE' as const
      : 'DEFAULT' as const,
    showLabel: false,
  })),
];

