export interface FieldTabletQuestProjectionInput {
  readonly missions: readonly Readonly<{
    state: MissionRuntimeState;
    definition?: MissionDefinition;
  }>[];
  readonly storyQuests: readonly Readonly<{
    state: StoryQuestRuntimeState;
    definition?: StoryQuestDefinition;
  }>[];
}

const QUEST_STATUS_ORDER: Readonly<Record<FieldTabletQuestStatus, number>> = {
  ACTIVE: 0,
  OFFERED: 1,
  COMPLETED: 2,
  EXPIRED: 3,
  CANCELLED: 4,
};

const displayIdentifier = (value: string): string =>
  value
    .replaceAll('-', ' ')
    .replaceAll('_', ' ')
    .replace(/\b\w/g, (letter) => letter.toUpperCase());

export const createFieldTabletQuestViews = (
  input: Readonly<FieldTabletQuestProjectionInput>,
): readonly FieldTabletQuestView[] => {
  const missions: FieldTabletQuestView[] = input.missions.flatMap(
    ({ state, definition }) => {
      if (state.status === 'LOCKED') return [];
      const kind: FieldTabletQuestKind = definition?.source === 'SIMULATION'
        ? 'WORLD_REQUEST'
        : 'MAIN_STORY';
      return [{
        id: `mission:${state.missionId}`,
        kind,
        status: state.status,
        title: definition?.displayName ?? displayIdentifier(state.missionId),
        description: definition?.description ?? 'Details will arrive when this task is updated.',
        sourceLabel: kind === 'WORLD_REQUEST' ? 'WORLD REQUEST' : 'ICEWAY STORY',
        ...(definition?.rewardMoney
          ? { rewardLabel: `${definition.rewardMoney} CR` }
          : {}),
      }];
    },
  );
  const stories: FieldTabletQuestView[] = input.storyQuests.flatMap(
    ({ state, definition }) => {
      if (state.status === 'LOCKED') return [];
      const stage = state.currentStageId
        ? definition?.stages.find((candidate) => candidate.id === state.currentStageId)
        : undefined;
      const status: FieldTabletQuestStatus = state.status === 'ACTIVE'
        ? 'ACTIVE'
        : state.status === 'COMPLETED'
          ? 'COMPLETED'
          : 'CANCELLED';
      return [{
        id: `story:${state.questId}`,
        kind: 'SIDE_STORY',
        status,
        title: definition?.displayName ?? displayIdentifier(state.questId),
        description: definition?.description ?? 'A local Borealis story.',
        ...(stage ? {
          objective: stage.hudGuidance
            ? `${stage.displayName} · ${stage.hudGuidance}`
            : stage.displayName,
        } : {}),
        sourceLabel: 'BOREALIS STORY',
      }];
    },
  );
  return [...missions, ...stories].sort(
    (left, right) =>
      QUEST_STATUS_ORDER[left.status] - QUEST_STATUS_ORDER[right.status] ||
      left.title.localeCompare(right.title),
  );
};

const incidentTargetId = (message: Readonly<RadioMessage>): string | undefined =>
  message.targetRefs.find((target) => target.kind === 'INCIDENT')?.incidentId;

const npcTargetId = (message: Readonly<RadioMessage>): string | undefined =>
  message.targetRefs.find((target) => target.kind === 'NPC')?.npcId;

const radioKnowsIncidentResolved = (message: Readonly<RadioMessage>): boolean =>
  message.sourceEventId.includes(':resolved:') ||
  message.sourceEventId.endsWith(':resolved');

export const createFieldTabletRequestViews = (input: Readonly<{
  radioMessages: readonly RadioMessage[];
  incidents: readonly FieldTabletIncidentSource[];
  npcRequests?: readonly FieldTabletNpcRequestSource[];
}>): readonly FieldTabletRequestView[] => {
  const incidentById = new Map(
    input.incidents.map((incident) => [incident.incidentId, incident] as const),
  );
  const incidentMessages = new Map<string, RadioMessage[]>();
  for (const message of input.radioMessages) {
    const incidentId = incidentTargetId(message);
    if (!incidentId) continue;
    const messages = incidentMessages.get(incidentId) ?? [];
    messages.push(message);
    incidentMessages.set(incidentId, messages);
  }
  const distress: FieldTabletRequestView[] = [];
  for (const [incidentId, messages] of incidentMessages) {
    const received = [...messages].sort(
      (left, right) => right.receivedAt - left.receivedAt || right.priority - left.priority,
    );
    const firstDistress = [...received]
      .reverse()
      .find((message) => message.category === 'DISTRESS');
    if (!firstDistress) continue;
    const incident = incidentById.get(incidentId);
    const resolvedMessage = received.find(radioKnowsIncidentResolved);
    const resolved = resolvedMessage !== undefined;
    const npcId = npcTargetId(firstDistress) ?? incident?.subjectId;
    distress.push({
      id: `request:${incidentId}`,
      kind: 'SOS',
      status: resolved
        ? 'RESOLVED'
        : firstDistress.acknowledgedAt === undefined
          ? 'NEW'
          : 'ACTIVE',
      title: resolved ? resolvedMessage.title : firstDistress.title,
      body: resolved ? resolvedMessage.body : firstDistress.body,
      sourceLabel: incident?.subjectName ?? (npcId ? displayIdentifier(npcId) : 'UNKNOWN CALLER'),
      urgent: !resolved,
      receivedAt: (resolvedMessage ?? firstDistress).receivedAt,
      radioMessageId: (resolvedMessage ?? firstDistress).id,
      ...((resolvedMessage ?? firstDistress).presentedSignalBand
        ? { signalBand: (resolvedMessage ?? firstDistress).presentedSignalBand }
        : {}),
      ...((resolvedMessage ?? firstDistress).signalDetail
        ? { signalDetail: (resolvedMessage ?? firstDistress).signalDetail }
        : {}),
      ...(firstDistress.locationUncertaintyMetres !== undefined
        ? { locationUncertaintyMetres: firstDistress.locationUncertaintyMetres }
        : {}),
      ...(incident ? { worldPosition: incident.worldPosition } : {}),
      locationLabel: incident ? 'BOREALIS FIELD POSITION' : 'POSITION NOT RECOVERED',
    });
  }
  const radioTasks: FieldTabletRequestView[] = input.radioMessages
    .filter((message) => message.category === 'TASK_OFFER' && !incidentTargetId(message))
    .map((message) => ({
      id: `request:${message.id}`,
      kind: 'RADIO_TASK' as const,
      status: message.acknowledgedAt === undefined ? 'NEW' as const : 'ACTIVE' as const,
      title: message.title,
      body: message.body,
      sourceLabel: displayIdentifier(message.stationId ?? 'radio request'),
      urgent: message.urgent,
      receivedAt: message.receivedAt,
      radioMessageId: message.id,
      ...(message.presentedSignalBand ? { signalBand: message.presentedSignalBand } : {}),
      ...(message.signalDetail ? { signalDetail: message.signalDetail } : {}),
      ...(message.locationUncertaintyMetres !== undefined
        ? { locationUncertaintyMetres: message.locationUncertaintyMetres }
        : {}),
    }));
  const npcRequests: FieldTabletRequestView[] = (input.npcRequests ?? []).map(
    (request) => ({
      id: `request:${request.id}`,
      kind: 'NPC_REQUEST',
      status: request.status === 'OFFERED'
        ? 'NEW'
        : request.status,
      title: request.title,
      body: request.body,
      sourceLabel: request.npcName,
      urgent: request.urgent ?? false,
      ...(request.receivedAt !== undefined ? { receivedAt: request.receivedAt } : {}),
      ...(request.radioMessageId ? { radioMessageId: request.radioMessageId } : {}),
      ...(request.signalBand ? { signalBand: request.signalBand } : {}),
      ...(request.signalDetail ? { signalDetail: request.signalDetail } : {}),
      ...(request.locationUncertaintyMetres !== undefined
        ? { locationUncertaintyMetres: request.locationUncertaintyMetres }
        : {}),
      ...(request.worldPosition ? { worldPosition: request.worldPosition } : {}),
      ...(request.locationLabel ? { locationLabel: request.locationLabel } : {}),
    }),
  );
  const statusOrder = { NEW: 0, ACTIVE: 1, RESOLVED: 2, EXPIRED: 3 } as const;
  return [...distress, ...radioTasks, ...npcRequests].sort(
    (left, right) =>
      statusOrder[left.status] - statusOrder[right.status] ||
      Number(right.urgent) - Number(left.urgent) ||
      (right.receivedAt ?? 0) - (left.receivedAt ?? 0) ||
      left.id.localeCompare(right.id),
  );
};
