import { BOREALIS_DIALOGUE_DEFINITIONS } from '../gameplay/dialogue/DialogueDefinitions';
import { BOREALIS_EMERGENT_WORLD_DEFINITIONS } from '../gameplay/emergence/BorealisEmergentDefinitions';
import {
  WORLD_ASSET_MATERIALS,
  WORLD_ASSET_RECIPES,
  type WorldAssetCategory,
} from '../land/WorldAssetCatalog';
import type { AssetBudgetClass } from '../performance/AssetPerformanceBudget';
import type {
  AssetAuthoringRecord,
  AuthoringScenarioDefinition,
  IcewayContentAuthoringDocument,
  SurfaceMaterialAuthoringDefinition,
} from './ContentAuthoringTypes';

const hex = (color: number): string =>
  `#${Math.max(0, Math.min(0xffffff, color)).toString(16).padStart(6, '0')}`;

const budgetClassForCategory = (category: WorldAssetCategory): AssetBudgetClass => {
  if (category === 'CONIFERS' || category === 'DECIDUOUS') return 'TREE';
  if (category === 'INFRASTRUCTURE' || category === 'RAILWAY' || category === 'HEATING') {
    return 'STREET_PROP';
  }
  return 'SMALL_PROP';
};

const materials = (): SurfaceMaterialAuthoringDefinition[] =>
  WORLD_ASSET_MATERIALS.map((material) => ({
    id: material.id,
    displayName: material.id.toLowerCase().replaceAll('_', ' '),
    baseColor: hex(material.color),
    roughness: material.roughness,
    metalness: material.metalness ?? 0,
    snowAffinity: material.emissiveIntensity && material.emissiveIntensity > 0.5
      ? 0.2
      : 1,
    thermalOutput: material.emissiveIntensity
      ? Math.min(1, material.emissiveIntensity * 0.2)
      : 0,
    windResponse: material.id.startsWith('FOLIAGE_') ? 1 : 0,
    tags: material.id.startsWith('FOLIAGE_') ? ['VEGETATION', 'WIND'] : [],
  }));

const assets = (): AssetAuthoringRecord[] => WORLD_ASSET_RECIPES.map((asset) => ({
  id: asset.id,
  displayName: asset.displayName,
  category: asset.category,
  suggestedModelUrl: asset.suggestedModelUrl,
  budgetClass: budgetClassForCategory(asset.category),
  tags: [
    ...(asset.connector ? ['CONNECTOR'] : []),
    ...(asset.snowMelt ? ['SNOW_MELT'] : []),
    ...(asset.pointLight ? ['LIGHT'] : []),
    ...(asset.id.startsWith('IMPORT_') ? ['IMPORT_CANDIDATE'] : []),
  ],
}));

