export type GeneratedWorldLayer =
  | 'FINAL'
  | 'HEIGHT'
  | 'WATER'
  | 'MOISTURE'
  | 'FOREST'
  | 'ROCKINESS'
  | 'FUEL';

export interface GeneratedWorldBounds {
  readonly minX: number;
  readonly maxX: number;
  readonly minZ: number;
  readonly maxZ: number;
}

export interface GeneratedWorldConfig {
  readonly version: 1;
  readonly seed: number;
  readonly bounds: GeneratedWorldBounds;
  readonly cellSizeMetres: number;
  readonly seaLevelMetres: number;
  readonly thermalErosionPasses: number;
  readonly hydraulicErosionPasses: number;
  readonly riverAccumulationThreshold: number;
}

/**
 * Immutable macro-world layers. They are intentionally engine agnostic: the
 * renderer, snow, ice, editor and gameplay all sample the same compact data
 * instead of allowing the generator to create its own parallel world.
 */
export interface GeneratedWorldData {
  readonly version: 1;
  readonly config: GeneratedWorldConfig;
  readonly width: number;
  readonly height: number;
  readonly elevation: Float32Array;
  readonly waterSurface: Float32Array;
  readonly flowAccumulation: Float32Array;
  readonly flowDirectionX: Int8Array;
  readonly flowDirectionZ: Int8Array;
  /** Normalized 0..255 masks. */
  readonly river: Uint8Array;
  readonly lake: Uint8Array;
  readonly moisture: Uint8Array;
  readonly forest: Uint8Array;
  readonly rockiness: Uint8Array;
  readonly fuel: Uint8Array;
  readonly generationMilliseconds: number;
}

export interface GeneratedWorldSample {
  readonly inside: boolean;
  readonly elevation: number;
  readonly waterSurface: number;
  readonly river: number;
  readonly lake: number;
  readonly water: number;
  readonly flowAccumulation: number;
  readonly flowDirectionX: number;
  readonly flowDirectionZ: number;
  readonly moisture: number;
  readonly forest: number;
  readonly rockiness: number;
  readonly fuel: number;
}

export interface GeneratedWorldRuntimeStats {
  readonly enabled: boolean;
  readonly seed: number;
  readonly width: number;
  readonly height: number;
  readonly cellSizeMetres: number;
  readonly generationMilliseconds: number;
  readonly riverCells: number;
  readonly lakeCells: number;
}

export const EMPTY_GENERATED_WORLD_SAMPLE: GeneratedWorldSample = Object.freeze({
  inside: false,
  elevation: 0,
  waterSurface: 0,
  river: 0,
  lake: 0,
  water: 0,
  flowAccumulation: 0,
  flowDirectionX: 0,
  flowDirectionZ: 0,
  moisture: 0,
  forest: 0,
  rockiness: 0,
  fuel: 0,
});
