const anchorLevelMatches = (
  left: Readonly<SurvivalBuildV3AnchorAddress>,
  right: Readonly<SurvivalBuildV3AnchorAddress>,
): boolean => left.kind === right.kind && addressLevel(left) === addressLevel(right);

const distanceToAnchorInFrame = (
  frame: Readonly<SurvivalBuildV3Frame>,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
  x: number,
  z: number,
): number => {
  if (anchor.kind === 'NODE') {
    return Math.hypot(x - anchor.u * frame.moduleMetres, z - anchor.v * frame.moduleMetres);
  }
  if (anchor.kind === 'BAY') {
    const minimumX = anchor.u * frame.moduleMetres;
    const maximumX = minimumX + frame.moduleMetres;
    const minimumZ = anchor.v * frame.moduleMetres;
    const maximumZ = minimumZ + frame.moduleMetres;
    return Math.hypot(
      Math.max(minimumX - x, 0, x - maximumX),
      Math.max(minimumZ - z, 0, z - maximumZ),
    );
  }
  if (anchor.kind === 'EDGE') {
    const [start, end] = survivalBuildV3EdgeEndpoints(anchor.edge);
    const startX = start.u * frame.moduleMetres;
    const startZ = start.v * frame.moduleMetres;
    const deltaX = (end.u - start.u) * frame.moduleMetres;
    const deltaZ = (end.v - start.v) * frame.moduleMetres;
    const lengthSquared = Math.max(0.0001, deltaX * deltaX + deltaZ * deltaZ);
    const t = Math.max(0, Math.min(1,
      ((x - startX) * deltaX + (z - startZ) * deltaZ) / lengthSquared,
    ));
    return Math.hypot(x - (startX + deltaX * t), z - (startZ + deltaZ * t));
  }
  return Number.POSITIVE_INFINITY;
};

