const roofOrientation = (yawOffsetDegrees = 0): number =>
  ((Math.round(yawOffsetDegrees / 90) % 2) + 2) % 2;

const normalizedRoofSpanBays = (spanBays?: number): number =>
  normalizeSurvivalBuildV3RoofSpanBays(spanBays);

const SPANNED_ROOF_DEFINITIONS = new Set<SurvivalBuildPieceId>([
  ...ROOF_FRAME_DEFINITIONS,
  ...ROOF_PANEL_FRAME.keys(),
  ...ROOF_GABLE_FRAME.keys(),
  ...ROOF_RIDGE_PANEL.keys(),
]);

const roofSpanBayKeys = (
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  yawOffsetDegrees = 0,
  spanBays = 1,
): readonly string[] => {
  const span = normalizedRoofSpanBays(spanBays);
  const orientation = roofOrientation(yawOffsetDegrees);
  return Array.from({ length: span }, (_, offset) =>
    `${anchor.level}:${anchor.u + (orientation === 1 ? offset : 0)}:` +
    `${anchor.v + (orientation === 0 ? offset : 0)}`);
};

const roofSpanContainsBay = (
  piece: Readonly<SurvivalBuildV3Piece>,
  bay: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
): boolean => piece.anchor.kind === 'BAY' &&
  roofSpanBayKeys(piece.anchor, piece.yawOffsetDegrees, piece.spanBays)
    .includes(`${bay.level}:${bay.u}:${bay.v}`);

export const survivalBuildV3Definition = (
  definitionId: SurvivalBuildPieceId,
): SurvivalBuildV3Definition | undefined => DEFINITIONS[definitionId];

const addressLevel = (address: Readonly<SurvivalBuildV3AnchorAddress>): number | undefined =>
  address.kind === 'SURFACE' ? undefined : address.level;

const occupancyKey = (
  siteId: string,
  lane: string,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
): string => `${siteId}:${lane}:${survivalBuildV3AnchorKey(anchor)}`;

const pieceOccupancyLane = (
  definition: Readonly<SurvivalBuildV3Definition> | undefined,
  definitionId: SurvivalBuildPieceId,
  mirrored = false,
): string => definition?.occupancyLane === 'roof-gable-end'
  ? `${definition.occupancyLane}:${mirrored ? 'terminal' : 'leading'}:${definitionId}`
  : definition?.occupancyLane ?? definitionId.toLowerCase();

const pieceOccupancyKey = (piece: Readonly<SurvivalBuildV3Piece>): string => {
  if (piece.freePose) return `${piece.siteId}:free:${piece.definitionId}:${[piece.freePose.x,piece.freePose.y,piece.freePose.z,piece.freePose.yawDegrees].map(v=>Math.round(v*1000)).join('/')}`;
  if (piece.roofMember) return `${piece.siteId}:modular-roof:${roofMemberKey(piece.roofMember)}`;
  const definition = survivalBuildV3Definition(piece.definitionId);
  return occupancyKey(
    piece.siteId,
    pieceOccupancyLane(definition, piece.definitionId, piece.mirrored),
    piece.anchor,
  );
};

interface SurvivalBuildV3QueryContext {
  readonly supportProof?: { visiting: Set<string>; supported: Set<string> };
  readonly environment?: Readonly<SurvivalBuildV3Environment>;
  readonly roofStableCache?: Map<string, boolean>;
  readonly index?: SurvivalBuildV3StateIndex;
  readonly omittedPieceIds?: ReadonlySet<string>;
  readonly roofVisited?: ReadonlySet<string>;
}

const pieceIsVisibleToQuery = (
  piece: Readonly<SurvivalBuildV3Piece>,
  query: Readonly<SurvivalBuildV3QueryContext>,
): boolean => !query.omittedPieceIds?.has(piece.id);

/** A joint is an address, not proof of grounding. Follow the existing local
 * bearings to real support and reject self-supporting floor/wall loops.
 * Only successful proofs are memoized: a path blocked by a current ancestor
 * may become valid through a different bearing later in this query. */
const providerIsSupported = (save: Readonly<SurvivalBuildV3SaveData>, id: string,
  query: Readonly<SurvivalBuildV3QueryContext>): boolean => {
  if (query.omittedPieceIds?.has(id)) return false;
  const proof = query.supportProof ?? { visiting: new Set<string>(), supported: new Set<string>() };
  if (proof.visiting.has(id)) return false;
  if (proof.supported.has(id)) return true;
  const piece = query.index?.piece(id) ?? save.pieces.find(p => p.id === id);
  if (!piece) return false;
  const damageProfile = buildDamageProfile(piece.definitionId);
  if(damageProfile && !buildDamageHasBearing(damageProfile,piece.damage))return false;
  proof.visiting.add(id);
  const status = evaluateSurvivalBuildV3Placement(save, piece, query.environment, {
    ...query, supportProof: proof, omittedPieceIds: new Set([...(query.omittedPieceIds ?? []), id]),
  }).status;
  proof.visiting.delete(id);
  if (status === 'SUPPORTED') proof.supported.add(id);
  return status === 'SUPPORTED';
};

const jointId = (
  siteId: string,
  address: Readonly<SurvivalBuildV3AnchorAddress>,
): string => `${siteId}:joint:${survivalBuildV3AnchorKey(address)}`;

const capacityClass = (
  address: Readonly<SurvivalBuildV3AnchorAddress>,
): SurvivalBuildV3Joint['capacityClass'] => {
  if (address.kind === 'NODE') return 'BRANCH';
  if (address.kind === 'EDGE') return 'EDGE';
  if (address.kind === 'BAY') return 'BAY';
  return 'SURFACE';
};

interface ConnectionDescriptor {
  readonly portId: string;
  readonly role: SurvivalBuildV3ConnectionRole;
  readonly address: SurvivalBuildV3AnchorAddress;
}

const edgeNodeAddresses = (
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'EDGE' }>,
): readonly [SurvivalBuildV3AnchorAddress, SurvivalBuildV3AnchorAddress] => {
  const [first, second] = survivalBuildV3EdgeEndpoints(anchor.edge);
  return [
    { kind: 'NODE', level: anchor.level, u: first.u, v: first.v },
    { kind: 'NODE', level: anchor.level, u: second.u, v: second.v },
  ];
};

const connectionDescriptors = (
  role: SurvivalBuildV3Role,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
  definitionId?: SurvivalBuildPieceId,
  yawOffsetDegrees = 0,
  spanBays = 1,
): readonly ConnectionDescriptor[] => {
  if (anchor.kind === 'SURFACE') {
    return [{ portId: 'mount', role: 'MOUNTS', address: anchor }];
  }
  if (role === 'FOUNDATION' && anchor.kind === 'EDGE') {
    const [start, end] = edgeNodeAddresses(anchor);
    if (definitionId === 'TIMBER_PALISADE') return [
      { portId: 'span', role: 'CONTINUES', address: anchor },
      { portId: 'start', role: 'CONTINUES', address: start },
      { portId: 'end', role: 'CONTINUES', address: end },
    ];
    return [
      { portId: 'span', role: 'SUPPORTS', address: anchor },
      { portId: 'start', role: 'SUPPORTS', address: start },
      { portId: 'end', role: 'SUPPORTS', address: end },
    ];
  }
  if (role === 'FLOOR' && anchor.kind === 'BAY') {
    return [
      { portId: 'bay', role: 'SUPPORTED_BY', address: anchor },
      ...survivalBuildV3BayEdges(anchor.u, anchor.v, anchor.level).flatMap(
        (address, index): ConnectionDescriptor[] => [
          { portId: `supported-edge-${index}`, role: 'SUPPORTED_BY', address },
          { portId: `support-edge-${index}`, role: 'SUPPORTS', address },
        ],
      ),
    ];
  }
  if (role === 'WALL' && anchor.kind === 'EDGE') {
    const [baseStart, baseEnd] = edgeNodeAddresses(anchor);
    const topEdge: SurvivalBuildV3AnchorAddress = {
      kind: 'EDGE',
      level: anchor.level + 1,
      edge: anchor.edge,
    };
    const [topStart, topEnd] = edgeNodeAddresses(topEdge);
    return [
      { portId: 'base-edge', role: 'SUPPORTED_BY', address: anchor },
      { portId: 'base-start', role: 'CONTINUES', address: baseStart },
      { portId: 'base-end', role: 'CONTINUES', address: baseEnd },
      { portId: 'top-edge', role: 'SUPPORTS', address: topEdge },
      { portId: 'top-start', role: 'SUPPORTS', address: topStart },
      { portId: 'top-end', role: 'SUPPORTS', address: topEnd },
    ];
  }
  if (role === 'POST' && anchor.kind === 'NODE') {
    return [
      { portId: 'base', role: 'SUPPORTED_BY', address: anchor },
      {
        portId: 'top',
        role: 'SUPPORTS',
        address: { ...anchor, level: anchor.level + 1 },
      },
    ];
  }
  if (role === 'BEAM' && anchor.kind === 'EDGE') {
    if (definitionId === 'TIMBER_ROOF_RIDGE') {
      return [{ portId: 'roof-edge', role: 'SUPPORTED_BY', address: anchor }];
    }
    const [start, end] = edgeNodeAddresses(anchor);
    return [
      { portId: 'span', role: 'SUPPORTS', address: anchor },
      { portId: 'start', role: 'SUPPORTED_BY', address: start },
      { portId: 'end', role: 'SUPPORTED_BY', address: end },
    ];
  }
  if (role === 'ROOF' && anchor.kind === 'BAY') {
    if (definitionId && ROOF_RIDGE_PANEL.has(definitionId)) {
      return [{ portId: 'roof-cover', role: 'SUPPORTED_BY', address: anchor }];
    }
    if (definitionId && ROOF_GABLE_FRAME.has(definitionId)) {
      return [{ portId: 'roof-frame', role: 'SUPPORTED_BY', address: anchor }];
    }
    if (definitionId && ROOF_FRAME_DEFINITIONS.has(definitionId)) {
      const span = normalizedRoofSpanBays(spanBays);
      const orientation = roofOrientation(yawOffsetDegrees);
      const frameFeet = orientation === 0
        ? [
            { kind: 'EDGE' as const, level: anchor.level,
              edge: canonicalSurvivalBuildV3Edge(anchor.u, anchor.v, 'NORTH') },
            { kind: 'EDGE' as const, level: anchor.level,
              edge: canonicalSurvivalBuildV3Edge(anchor.u, anchor.v + span - 1, 'SOUTH') },
          ]
        : [
            { kind: 'EDGE' as const, level: anchor.level,
              edge: canonicalSurvivalBuildV3Edge(anchor.u, anchor.v, 'WEST') },
            { kind: 'EDGE' as const, level: anchor.level,
              edge: canonicalSurvivalBuildV3Edge(anchor.u + span - 1, anchor.v, 'EAST') },
          ];
      return [
        { portId: 'roof-frame', role: 'SUPPORTS', address: anchor },
        ...frameFeet.map(
          (address, index): ConnectionDescriptor => ({
            portId: `frame-foot-${index}`,
            role: 'SUPPORTED_BY',
            address,
          }),
        ),
      ];
    }
    if (definitionId && ROOF_PANEL_FRAME.has(definitionId)) {
      return [
        { portId: 'roof-frame', role: 'SUPPORTED_BY', address: anchor },
        { portId: 'roof-cover', role: 'SUPPORTS', address: anchor },
        ...survivalBuildV3BayEdges(anchor.u, anchor.v, anchor.level).flatMap(
          (address, index): ConnectionDescriptor[] => [
            { portId: `supported-edge-${index}`, role: 'SUPPORTED_BY', address },
            { portId: `support-edge-${index}`, role: 'SUPPORTS', address },
          ],
        ),
      ];
    }
    return [
      { portId: 'bay', role: 'SUPPORTED_BY', address: anchor },
      ...survivalBuildV3BayEdges(anchor.u, anchor.v, anchor.level).flatMap(
        (address, index): ConnectionDescriptor[] => [
          { portId: `supported-edge-${index}`, role: 'SUPPORTED_BY', address },
          // A completed roof bay owns its surface like a floor, but also
          // exposes a structural edge for ridges and the neighbouring bay.
          { portId: `support-edge-${index}`, role: 'SUPPORTS', address },
        ],
      ),
    ];
  }
  return [{ portId: 'primary', role: 'MOUNTS', address: anchor }];
};

const cloneSave = (
  save: Readonly<SurvivalBuildV3SaveData>,
): SurvivalBuildV3SaveData => ({
  version: SURVIVAL_BUILD_V3_SAVE_VERSION,
  sites: save.sites.map((site) => ({ ...site, pieceIds: [...site.pieceIds] })),
  frames: save.frames.map((frame) => ({ ...frame, origin: { ...frame.origin } })),
  pieces: save.pieces.map((piece) => ({
    ...piece,
    anchor: structuredClone(piece.anchor),
    ...(piece.roofMember ? { roofMember: structuredClone(piece.roofMember) } : {}),
    ...(piece.freePose ? { freePose: structuredClone(piece.freePose) } : {}),
    damage: piece.damage && buildDamageProfile(piece.definitionId)
      ? normaliseBuildDamage(buildDamageProfile(piece.definitionId)!,piece.damage) : undefined,
    connections: piece.connections.map((connection) => ({ ...connection })),
    terrainFit: piece.terrainFit
      ? {
          ...piece.terrainFit,
          samples: piece.terrainFit.samples.map((sample) => ({ ...sample })),
        }
      : undefined,
  })),
  joints: save.joints.map((joint) => ({
    ...joint,
    address: structuredClone(joint.address),
    members: joint.members.map((member) => ({ ...member })),
  })),
  nextSiteSerial: save.nextSiteSerial,
  nextFrameSerial: save.nextFrameSerial,
  nextPieceSerial: save.nextPieceSerial,
});

const jointHasSupport = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  address: Readonly<SurvivalBuildV3AnchorAddress>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): boolean => {
  const candidate = query.index?.joint(jointId(siteId, address));
  const joints = candidate ? [candidate] : query.index ? [] : save.joints;
  return joints.some((joint) =>
    joint.id === jointId(siteId, address) &&
    joint.members.some((member) =>
      member.role === 'SUPPORTS' && providerIsSupported(save, member.pieceId, query))
  );
};

const jointHasSupportFromRoles = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  address: Readonly<SurvivalBuildV3AnchorAddress>,
  roles: ReadonlySet<SurvivalBuildV3Role>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): boolean => {
  const candidate = query.index?.joint(jointId(siteId, address));
  const joints = candidate ? [candidate] : query.index ? [] : save.joints;
  return joints.some((joint) =>
    joint.id === jointId(siteId, address) &&
    joint.members.some((member) => {
      if (member.role !== 'SUPPORTS' || query.omittedPieceIds?.has(member.pieceId)) {
        return false;
      }
      const provider = query.index?.piece(member.pieceId) ??
        save.pieces.find((piece) => piece.id === member.pieceId);
      return Boolean(provider && roles.has(provider.role) && providerIsSupported(save, provider.id, query));
    })
  );
};

const pieceAt = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  role: SurvivalBuildV3Role,
  anchor: Readonly<SurvivalBuildV3AnchorAddress>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): SurvivalBuildV3Piece | undefined => {
  const key = survivalBuildV3AnchorKey(anchor);
  const candidates = query.index?.piecesAt(siteId, role, anchor) ?? save.pieces;
  return candidates.find((piece) =>
    piece.siteId === siteId &&
    piece.role === role &&
    pieceIsVisibleToQuery(piece, query) &&
    survivalBuildV3AnchorKey(piece.anchor) === key
  );
};

/**
 * A normal floor placed above a stair flight becomes an authored open bay.
 * Keeping this decision in the authority makes preview, save/load and future
 * multiplayer placement agree on the same geometry without a special UI tool.
 */
export const resolveSurvivalBuildV3AutomaticPlacement = (
  save: Readonly<SurvivalBuildV3SaveData>,
  request: Readonly<SurvivalBuildV3PlacementRequest>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): SurvivalBuildV3PlacementRequest => {
  if (request.freePose) return request;
  if (
    request.anchor.kind === 'BAY' &&
    ROOF_FRAME_DEFINITIONS.has(request.definitionId)
  ) {
    const supported = supportedRoofFrameRequest(save, {
      ...request,
      anchor: request.anchor,
    }, query);
    if (supported) return supported;
    return { ...request, anchor: structuredClone(request.anchor) };
  }
  if (request.anchor.kind === 'BAY') {
    const requestedBay = request.anchor;
    const supportingDefinitionId = ROOF_PANEL_FRAME.get(request.definitionId) ??
      ROOF_RIDGE_PANEL.get(request.definitionId) ??
      ROOF_GABLE_FRAME.get(request.definitionId);
    if (supportingDefinitionId) {
      const supportingPiece = (query.index?.piecesForRole(
        request.siteId,
        'ROOF',
      ) ?? save.pieces).find((piece) =>
        piece.siteId === request.siteId &&
        piece.role === 'ROOF' &&
        piece.definitionId === supportingDefinitionId &&
        pieceIsVisibleToQuery(piece, query) &&
        roofSpanContainsBay(piece, requestedBay)
      );
      if (supportingPiece) {
        return {
          ...request,
          anchor: structuredClone(supportingPiece.anchor),
          yawOffsetDegrees: supportingPiece.yawOffsetDegrees ?? 0,
          spanBays: normalizedRoofSpanBays(supportingPiece.spanBays),
          roofProfile: supportingPiece.roofProfile,
        };
      }
    }
  }
  if (request.definitionId !== 'TIMBER_FLOOR' || request.anchor.kind !== 'BAY') {
    return { ...request, anchor: structuredClone(request.anchor) };
  }
  const floorAnchor = request.anchor;
  const belowAnchor: SurvivalBuildV3AnchorAddress = {
    kind: 'BAY',
    level: floorAnchor.level - 1,
    u: floorAnchor.u,
    v: floorAnchor.v,
    shape: 'SQUARE',
  };
  const stairsBelow = (query.index?.piecesAt(request.siteId, 'FLOOR', belowAnchor) ??
    save.pieces).find((piece) =>
    piece.siteId === request.siteId &&
    piece.definitionId === 'TIMBER_STAIRS' &&
    piece.anchor.kind === 'BAY' &&
    piece.anchor.level + 1 === floorAnchor.level &&
    piece.anchor.u === floorAnchor.u &&
    piece.anchor.v === floorAnchor.v
  );
  return stairsBelow
    ? {
        ...request,
        definitionId: 'TIMBER_FLOOR_STAIR_OPENING',
        anchor: structuredClone(request.anchor),
        yawOffsetDegrees: stairsBelow.yawOffsetDegrees ?? 0,
        mirrored: stairsBelow.mirrored,
      }
    : { ...request, anchor: structuredClone(request.anchor) };
};

const supportedFloorAt = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  u: number,
  v: number,
  level: number,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): boolean => {
  const floor = pieceAt(save, siteId, 'FLOOR', {
    kind: 'BAY', level, u, v, shape: 'SQUARE',
  }, query);
  return Boolean(floor && providerIsSupported(save, floor.id, query));
};

const foundationEdgesAtNode = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  u: number,
  v: number,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): number => (query.index?.piecesForRole(siteId, 'FOUNDATION') ?? save.pieces).filter((piece) => {
  if (piece.definitionId === 'TIMBER_PALISADE') return false;
  if (!pieceIsVisibleToQuery(piece, query)) return false;
  if (piece.siteId !== siteId || piece.role !== 'FOUNDATION' || piece.anchor.kind !== 'EDGE') {
    return false;
  }
  const [start, end] = survivalBuildV3EdgeEndpoints(piece.anchor.edge);
  const edgeU = end.u - start.u;
  const edgeV = end.v - start.v;
  const pointU = u - start.u;
  const pointV = v - start.v;
  const cross = edgeU * pointV - edgeV * pointU;
  const dot = pointU * edgeU + pointV * edgeV;
  const lengthSquared = edgeU * edgeU + edgeV * edgeV;
  return Math.abs(cross) <= 0.0001 && dot >= -0.0001 && dot <= lengthSquared + 0.0001;
}).length;

const isWholeNodeCoordinate = (value: number): boolean =>
  Math.abs(value - Math.round(value)) <= 0.0001;

/** Integer nodes touch four bays. A half-node touches the one or two bays it
 * physically lies inside/on; this prevents a centre post from borrowing a
 * floor diagonally across a canonical module boundary. */
const baysTouchingPrecisionNode = (
  u: number,
  v: number,
): readonly Readonly<{ u: number; v: number }>[] => {
  const wholeU = isWholeNodeCoordinate(u);
  const wholeV = isWholeNodeCoordinate(v);
  if (wholeU && wholeV) return survivalBuildV3BaysTouchingNode(u, v);
  if (!wholeU && !wholeV) return [{ u: Math.floor(u), v: Math.floor(v) }];
  if (!wholeU) {
    return [
      { u: Math.floor(u), v: Math.round(v) - 1 },
      { u: Math.floor(u), v: Math.round(v) },
    ];
  }
  return [
    { u: Math.round(u) - 1, v: Math.floor(v) },
    { u: Math.round(u), v: Math.floor(v) },
  ];
};

const postSupportForFloor = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): number => {
  const floorCentreU = anchor.u + 0.5;
  const floorCentreV = anchor.v + 0.5;
  for (const piece of query.index?.piecesForRole(siteId, 'POST') ?? save.pieces) {
    if (!pieceIsVisibleToQuery(piece, query)) continue;
    if (
      piece.siteId !== siteId || piece.role !== 'POST' ||
      piece.anchor.kind !== 'NODE' || piece.anchor.level + 1 !== anchor.level
    ) continue;
    // A vertical post carries one canonical bay beyond itself in both local
    // axes. A precision-grid post at the centre of a 3x3 room therefore makes
    // all nine floor bays directly safe, while a fourth bay still becomes a
    // genuine cantilever. The Chebyshev footprint is intentional: it follows
    // the square two-metre construction language and stays an O(indexed posts)
    // query rather than recursively borrowing support through the floor field.
    if (
      Math.abs(piece.anchor.u - floorCentreU) <= 1.0001 &&
      Math.abs(piece.anchor.v - floorCentreV) <= 1.0001
    ) {
      if (providerIsSupported(save, piece.id, query)) return 2;
    }
  }
  return 0;
};

const directFloorSupportCount = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): number => Math.min(4, survivalBuildV3BayEdges(anchor.u, anchor.v, anchor.level)
  .filter((edge) => jointHasSupportFromRoles(
    save,
    siteId,
    edge,
    new Set<SurvivalBuildV3Role>(['FOUNDATION', 'WALL', 'POST', 'BEAM']),
    query,
  )).length + postSupportForFloor(save, siteId, anchor, query));

/**
 * A directly safe neighbouring floor can carry one shared edge. This is a
 * deliberately non-recursive transfer: one wall plus one genuinely supported
 * adjacent bay is safe, while a long chain of otherwise unsupported floors
 * cannot magically support itself.
 */
const stableNeighbourFloorSupportCount = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): number => survivalBuildV3BayEdges(anchor.u, anchor.v, anchor.level)
  .filter((edge) => edge.kind === 'EDGE' && survivalBuildV3BaysTouchingEdge(edge.edge).some((bay) => {
    if (bay.u === anchor.u && bay.v === anchor.v) return false;
    const neighbour = pieceAt(save, siteId, 'FLOOR', {
      kind: 'BAY',
      level: anchor.level,
      u: bay.u,
      v: bay.v,
      shape: 'SQUARE',
    }, query);
    return Boolean(
      neighbour && directFloorSupportCount(save, siteId, neighbour.anchor as Extract<
        SurvivalBuildV3AnchorAddress,
        { kind: 'BAY' }
      >, query) >= 2,
    );
  })).length;

const floorSupportCount = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): number => Math.min(
  4,
  directFloorSupportCount(save, siteId, anchor, query) +
    stableNeighbourFloorSupportCount(save, siteId, anchor, query),
);

const wallHasFloor = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'EDGE' }>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): boolean => survivalBuildV3BaysTouchingEdge(anchor.edge).some(
  (bay) => supportedFloorAt(save, siteId, bay.u, bay.v, anchor.level, query),
);

const postHasFloor = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'NODE' }>,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): boolean => baysTouchingPrecisionNode(anchor.u, anchor.v).some(
  (bay) => supportedFloorAt(save, siteId, bay.u, bay.v, anchor.level, query),
);

const oppositeRoofSupports = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  yawOffsetDegrees = 0,
  spanBays = 1,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): number => {
  const span = normalizedRoofSpanBays(spanBays);
  const orientation = roofOrientation(yawOffsetDegrees);
  const [first, second] = orientation === 0
    ? [
        { kind: 'EDGE' as const, level: anchor.level,
          edge: canonicalSurvivalBuildV3Edge(anchor.u, anchor.v, 'NORTH') },
        { kind: 'EDGE' as const, level: anchor.level,
          edge: canonicalSurvivalBuildV3Edge(anchor.u, anchor.v + span - 1, 'SOUTH') },
      ]
    : [
        { kind: 'EDGE' as const, level: anchor.level,
          edge: canonicalSurvivalBuildV3Edge(anchor.u, anchor.v, 'WEST') },
        { kind: 'EDGE' as const, level: anchor.level,
          edge: canonicalSurvivalBuildV3Edge(anchor.u + span - 1, anchor.v, 'EAST') },
      ];
  // A load-bearing wall's own top rail is a valid bearing; a separate wall
  // plate is optional. Existing supported beams remain valid bearings.
  const wallPlateRole = new Set<SurvivalBuildV3Role>(['WALL', 'BEAM']);
  return jointHasSupportFromRoles(save, siteId, first, wallPlateRole, query) &&
    jointHasSupportFromRoles(save, siteId, second, wallPlateRole, query)
    ? 2
    : 0;
};

const oppositeLegacyRoofSupports = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  yawOffsetDegrees = 0,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): number => {
  const [north, east, south, west] = survivalBuildV3BayEdges(
    anchor.u,
    anchor.v,
    anchor.level,
  );
  const roles = new Set<SurvivalBuildV3Role>(['WALL', 'POST', 'BEAM']);
  const supported = roofOrientation(yawOffsetDegrees) === 0
    ? jointHasSupportFromRoles(save, siteId, north!, roles, query) &&
      jointHasSupportFromRoles(save, siteId, south!, roles, query)
    : jointHasSupportFromRoles(save, siteId, east!, roles, query) &&
      jointHasSupportFromRoles(save, siteId, west!, roles, query);
  return supported ? 2 : 0;
};

const supportedRoofFrameRequest = (
  save: Readonly<SurvivalBuildV3SaveData>,
  request: Readonly<SurvivalBuildV3PlacementRequest> & Readonly<{
    anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>;
  }>,
  query: Readonly<SurvivalBuildV3QueryContext>,
): SurvivalBuildV3PlacementRequest | undefined => {
  const requestedYaw = request.yawOffsetDegrees ?? 0;
  const requestedOrientation = roofOrientation(requestedYaw);
  const explicitSpan = request.spanBays === undefined
    ? undefined
    : normalizedRoofSpanBays(request.spanBays);
  const candidates: SurvivalBuildV3PlacementRequest[] = [];
  for (const orientation of [requestedOrientation, 1 - requestedOrientation]) {
    const yawOffsetDegrees = requestedYaw +
      (orientation === requestedOrientation ? 0 : 90);
    const spans = explicitSpan
      ? [explicitSpan]
      : Array.from(
          { length: SURVIVAL_BUILD_V3_MAX_ROOF_SPAN_BAYS },
          (_, index) => index + 1,
        );
    for (const spanBays of spans) {
      for (let offset = 0; offset < spanBays; offset += 1) {
        const anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }> = {
          ...request.anchor,
          u: request.anchor.u - (orientation === 1 ? offset : 0),
          v: request.anchor.v - (orientation === 0 ? offset : 0),
        };
        if (oppositeRoofSupports(
          save,
          request.siteId,
          anchor,
          yawOffsetDegrees,
          spanBays,
          query,
        ) < 2) continue;
        candidates.push({
          ...request,
          anchor,
          yawOffsetDegrees,
          spanBays,
        });
      }
    }
  }
  return candidates.sort((left, right) => {
    const spanDifference = normalizedRoofSpanBays(left.spanBays) -
      normalizedRoofSpanBays(right.spanBays);
    if (spanDifference !== 0) return spanDifference;
    const leftTurn = roofOrientation(left.yawOffsetDegrees) === requestedOrientation ? 0 : 1;
    const rightTurn = roofOrientation(right.yawOffsetDegrees) === requestedOrientation ? 0 : 1;
    return leftTurn - rightTurn;
  })[0];
};

const matchingRoofPieceExists = (
  save: Readonly<SurvivalBuildV3SaveData>,
  siteId: string,
  anchor: Extract<SurvivalBuildV3AnchorAddress, { kind: 'BAY' }>,
  requiredDefinitionId: SurvivalBuildPieceId,
  yawOffsetDegrees = 0,
  spanBays = 1,
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): boolean => {
  const candidates = query.index?.piecesAt(siteId, 'ROOF', anchor) ?? save.pieces;
  return candidates.some((piece) =>
    piece.siteId === siteId &&
    piece.role === 'ROOF' &&
    piece.definitionId === requiredDefinitionId &&
    (piece.roofAssemblyStage ?? 4) >= 4 &&
    roofOrientation(piece.yawOffsetDegrees) === roofOrientation(yawOffsetDegrees) &&
    normalizedRoofSpanBays(piece.spanBays) === normalizedRoofSpanBays(spanBays) &&
    pieceIsVisibleToQuery(piece, query) &&
    survivalBuildV3AnchorKey(piece.anchor) === survivalBuildV3AnchorKey(anchor)
  );
};

const evaluateCanonicalSurvivalBuildV3Placement = (
  save: Readonly<SurvivalBuildV3SaveData>,
  request: Readonly<SurvivalBuildV3PlacementRequest>,
  environment: Readonly<SurvivalBuildV3Environment> = {},
  query: Readonly<SurvivalBuildV3QueryContext> = {},
): SurvivalBuildV3PlacementEvaluation => {
  query = { ...query, environment, supportProof: query.supportProof ?? { visiting: new Set(), supported: new Set() } };
  if (CURVE_DEFINITIONS.has(request.definitionId)) {
    return { status: 'BLOCKED', reason: 'curve-family-not-ready' };
  }
  const definition = survivalBuildV3Definition(request.definitionId);
  if (!definition) return { status: 'BLOCKED', reason: 'unknown-definition' };
  const site = query.index?.site(request.siteId) ??
    save.sites.find((candidate) => candidate.id === request.siteId);
  if (!site) return { status: 'BLOCKED', reason: 'site-not-found', definition };
  const frame = query.index?.frame(site.frameId) ??
    save.frames.find((candidate) => candidate.id === site.frameId);
  if (!frame) return { status: 'BLOCKED', reason: 'frame-not-found', definition };
  if (request.freePose) {
    if (!validBuildV4Pose(request.freePose)) return {status:'BLOCKED',reason:'wrong-anchor-kind',definition,frame};
    const result=evaluateBuildV4Pose({save,definitionId:request.definitionId,pose:request.freePose,
      omitted:query.omittedPieceIds,terrain:environment.sampleTerrainHeight,
      legacyStable:id=>providerIsSupported(save,id,query)});
    return {...result,definition,frame,transform:request.freePose,
      supportHint:result.reason==='occupied'?'Occupied volume':result.status==='BLOCKED'?'Needs a real bearing to ground':'Socket/contact support'};
  }
  if (request.anchor.kind !== definition.anchorKind) {
    return { status: 'BLOCKED', reason: 'wrong-anchor-kind', definition, frame };
  }
  const level = addressLevel(request.anchor);
  if (level !== undefined && (!Number.isInteger(level) || level < 0)) {
    return { status: 'BLOCKED', reason: 'invalid-level', definition, frame };
  }
  if (definition.role === 'FOUNDATION' && level !== 0) {
    return { status: 'BLOCKED', reason: 'invalid-level', definition, frame };
  }
  if (modularRoofKind(request.definitionId)) {
    const member = request.roofMember;
    if (!member || !validRoofMember(member) || MODULAR_ROOF_IDS[member.kind] !== request.definitionId) {
      return { status: 'BLOCKED', reason: 'wrong-anchor-kind', definition, frame };
    }
    const transform = roofMemberTransform(frame, member);
    const key = `${request.siteId}:modular-roof:${roofMemberKey(member)}`;
    const occupied = (query.index?.piecesOccupying(key) ?? save.pieces).some((p) =>
      pieceIsVisibleToQuery(p, query) && pieceOccupancyKey(p) === key);
    if (occupied) return { status: 'BLOCKED', reason: 'occupied', definition, frame, transform };
    if(member.rules===2) {
      const pieces=(query.index?.roofCandidates(request.siteId,frame,member) ?? save.pieces.filter(p=>p.siteId===request.siteId))
        .filter(p=>!query.omittedPieceIds?.has(p.id));
      const buildLimit = !query.omittedPieceIds?.size ? roofFrameBuildLimit(member, pieces) : undefined;
      if (buildLimit) return { status:'BLOCKED', reason:'unsupported', supportHint:buildLimit, definition, frame, transform };
      const cache=query.roofStableCache??new Map<string,boolean>();
      const evaluation=evaluateRoofFrame(frame,member,pieces,(parent)=>{
        if(query.roofVisited?.has(parent.id)||(query.roofVisited?.size??0)>64)return false;
        if(cache.get(parent.id))return true;
        const supported=evaluateSurvivalBuildV3Placement(save,{...parent},environment,{
          ...query,roofStableCache:cache,
          omittedPieceIds:new Set([...(query.omittedPieceIds??[]),parent.id]),
          roofVisited:new Set([...(query.roofVisited??[]),parent.id]),
        }).status==='SUPPORTED';
        if(supported)cache.set(parent.id,true);
        return supported;
      });
      return {status:evaluation.status,reason:evaluation.status==='SUPPORTED'?undefined:'unsupported',
        supportHint:evaluation.message,definition,frame,transform,supportCount:evaluation.supports.length};
    }
    const supported = member.supports.every((id, slot) => {
      if ((query.roofVisited?.size ?? 0) > 64) return false;
      const original = query.index?.piece(id) ?? save.pieces.find((p) => p.id === id);
      const parents=original && !query.omittedPieceIds?.has(id) ? [original]
        :query.index ? (['WALL','BEAM','ROOF'] as const).flatMap((role)=>query.index!.piecesForRole(request.siteId,role)) : save.pieces;
      return parents.some((support)=>{
        if(support.siteId!==request.siteId || query.omittedPieceIds?.has(support.id) || query.roofVisited?.has(support.id) ||
          !roofSupportedAtSocket(frame,member,slot,support)) return false;
        return evaluateSurvivalBuildV3Placement(save, { ...support }, environment, {
          ...query, omittedPieceIds: new Set([...(query.omittedPieceIds ?? []), support.id]),
          roofVisited: new Set([...(query.roofVisited ?? []), support.id]),
        }).status === 'SUPPORTED';
      });
    });
    return { status: supported ? 'SUPPORTED' : 'BLOCKED', reason: supported ? undefined : 'unsupported',
      definition, frame, transform, supportCount: supported ? member.supports.length : 0 };
  }
  const requestedOccupancy = occupancyKey(
    request.siteId,
    pieceOccupancyLane(definition, request.definitionId, request.mirrored),
    request.anchor,
  );
  const occupancyCandidates = query.index?.piecesOccupying(requestedOccupancy) ?? save.pieces;
  const ordinaryOccupancyBlocked = occupancyCandidates.some((piece) =>
    pieceIsVisibleToQuery(piece, query) && pieceOccupancyKey(piece) === requestedOccupancy
  );
  const spannedRoofOccupancyBlocked = request.anchor.kind === 'BAY' &&
    SPANNED_ROOF_DEFINITIONS.has(request.definitionId) &&
    !ROOF_GABLE_FRAME.has(request.definitionId) && (() => {
      const requestedKeys = new Set(roofSpanBayKeys(
        request.anchor,
        request.yawOffsetDegrees,
        request.spanBays,
      ));
      const candidates = query.index?.piecesForRole(request.siteId, 'ROOF') ?? save.pieces;
      return candidates.some((piece) => {
        if (
          !pieceIsVisibleToQuery(piece, query) ||
          piece.siteId !== request.siteId ||
          piece.role !== 'ROOF' ||
          piece.anchor.kind !== 'BAY'
        ) return false;
        const existing = survivalBuildV3Definition(piece.definitionId);
        if (existing?.occupancyLane !== definition.occupancyLane) return false;
        return roofSpanBayKeys(piece.anchor, piece.yawOffsetDegrees, piece.spanBays)
          .some((key) => requestedKeys.has(key));
      });
    })();
  if (ordinaryOccupancyBlocked || spannedRoofOccupancyBlocked) {
    return { status: 'BLOCKED', reason: 'occupied', definition, frame };
  }

  const baseTransform = survivalBuildV3AnchorWorldTransform(
    frame,
    request.anchor,
    definition.role,
  );
  let transform = {
    ...baseTransform,
    yawDegrees: request.anchor.kind === 'BAY'
      ? baseTransform.yawDegrees + Math.round((request.yawOffsetDegrees ?? 0) / 90) * 90
      : baseTransform.yawDegrees,
  };
  if (
    request.anchor.kind === 'BAY' &&
    SPANNED_ROOF_DEFINITIONS.has(request.definitionId)
  ) {
    const span = normalizedRoofSpanBays(request.spanBays);
    const orientation = roofOrientation(request.yawOffsetDegrees);
    const localOffset = (span - 1) * frame.moduleMetres * 0.5;
    const frameYaw = frame.yawDegrees * Math.PI / 180;
    const localX = orientation === 1 ? localOffset : 0;
    const localZ = orientation === 0 ? localOffset : 0;
    transform = {
      ...transform,
      x: transform.x + localX * Math.cos(frameYaw) + localZ * Math.sin(frameYaw),
      z: transform.z - localX * Math.sin(frameYaw) + localZ * Math.cos(frameYaw),
    };
  }
  if (
    request.anchor.kind === 'BAY' &&
    ROOF_GABLE_FRAME.has(request.definitionId)
  ) {
    // A gable occupies the vertical station at a roof bay boundary, not the
    // centre of the cover bay. Mirroring selects the opposite boundary and
    // remains part of the occupancy key, so a one-bay roof can own both ends.
    const endOffset = (request.mirrored ? 1 : -1) * frame.moduleMetres * 0.5;
    const yawRadians = transform.yawDegrees * Math.PI / 180;
    transform = {
      ...transform,
      x: transform.x + endOffset * Math.cos(yawRadians),
      z: transform.z - endOffset * Math.sin(yawRadians),
    };
  }
  if (definition.role === 'FOUNDATION') {
    const terrainFit = environment.sampleTerrainHeight
      ? evaluateSurvivalBuildV3FoundationTerrainFit(
          frame,
          request.anchor,
          environment.sampleTerrainHeight,
        )
      : undefined;
    return terrainFit?.status === 'BLOCKED'
      ? {
          status: 'BLOCKED',
          reason: 'terrain-too-steep',
          definition,
          frame,
          transform,
          supportCount: 0,
          terrainFit,
        }
      : {
          status: 'SUPPORTED',
          definition,
          frame,
          transform,
          supportCount: 1,
          terrainFit,
        };
  }
  if (definition.role === 'FLOOR' && request.anchor.kind === 'BAY') {
    const supportCount = floorSupportCount(save, request.siteId, request.anchor, query);
    if (supportCount >= 2) {
      return { status: 'SUPPORTED', definition, frame, transform, supportCount };
    }
    if (supportCount === 1) {
      // A stair flight is a braced structural run from its supported foot to
      // the next storey, not a flat occupied cantilever. Treating it like a
      // one-edge floor made the whole visible stair wobble under the actor.
      if (definition.definitionId === 'TIMBER_STAIRS') {
        return { status: 'SUPPORTED', definition, frame, transform, supportCount };
      }
      return { status: 'CANTILEVER', definition, frame, transform, supportCount };
    }
    return { status: 'BLOCKED', reason: 'unsupported', definition, frame, transform, supportCount };
  }
  if (definition.role === 'WALL' && request.anchor.kind === 'EDGE') {
    const supported = jointHasSupport(save, request.siteId, request.anchor, query) ||
      wallHasFloor(save, request.siteId, request.anchor, query);
    return supported
      ? { status: 'SUPPORTED', definition, frame, transform, supportCount: 1 }
      : { status: 'BLOCKED', reason: 'unsupported', definition, frame, transform, supportCount: 0 };
  }
  if (definition.role === 'POST' && request.anchor.kind === 'NODE') {
    const supportCount = request.anchor.level === 0
      ? foundationEdgesAtNode(save, request.siteId, request.anchor.u, request.anchor.v, query)
      : (jointHasSupport(save, request.siteId, request.anchor, query) ? 1 : 0);
    const supported = supportCount > 0 || postHasFloor(save, request.siteId, request.anchor, query);
    return supported
      ? { status: 'SUPPORTED', definition, frame, transform, supportCount: Math.max(1, supportCount) }
      : { status: 'BLOCKED', reason: 'unsupported', definition, frame, transform, supportCount: 0 };
  }
  if (definition.role === 'BEAM' && request.anchor.kind === 'EDGE') {
    if (definition.definitionId === 'TIMBER_ROOF_RIDGE') {
      const supportCount = jointHasSupport(save, request.siteId, request.anchor, query) ? 1 : 0;
      return supportCount > 0
        ? { status: 'SUPPORTED', definition, frame, transform, supportCount }
        : { status: 'BLOCKED', reason: 'unsupported', definition, frame, transform, supportCount };
    }
    const endpoints = edgeNodeAddresses(request.anchor);
    const supportCount = endpoints.filter((node) =>
      jointHasSupport(save, request.siteId, node, query)
    ).length;
    return supportCount >= 2
      ? { status: 'SUPPORTED', definition, frame, transform, supportCount }
      : { status: 'BLOCKED', reason: 'unsupported', definition, frame, transform, supportCount };
  }
  if (definition.role === 'ROOF' && request.anchor.kind === 'BAY') {
    const requiredFrame = ROOF_PANEL_FRAME.get(definition.definitionId) ??
      ROOF_GABLE_FRAME.get(definition.definitionId);
    if (requiredFrame) {
      const supported = matchingRoofPieceExists(
        save,
        request.siteId,
        request.anchor,
        requiredFrame,
        request.yawOffsetDegrees,
        request.spanBays,
        query,
      );
      return supported
        ? { status: 'SUPPORTED', definition, frame, transform, supportCount: 2 }
        : { status: 'BLOCKED', reason: 'unsupported', definition, frame, transform, supportCount: 0 };
    }
    const requiredPanel = ROOF_RIDGE_PANEL.get(definition.definitionId);
    if (requiredPanel) {
      const supported = matchingRoofPieceExists(
        save,
        request.siteId,
        request.anchor,
        requiredPanel,
        request.yawOffsetDegrees,
        request.spanBays,
        query,
      );
      const roofGeometry = survivalBuildV3RoofGeometry(
        definition.definitionId,
        request.spanBays,
        frame.moduleMetres,
        request.roofProfile,
      );
      const highEdge = roofGeometry?.profile === 'SHED' ? -roofGeometry.structuralHalfSpanMetres : 0;
      const roofYaw = transform.yawDegrees * Math.PI / 180;
      const ridgeTransform = {
        ...transform,
        x: transform.x + highEdge * Math.sin(roofYaw),
        z: transform.z + highEdge * Math.cos(roofYaw),
        y: transform.y + (roofGeometry?.ridgeYMetres ?? 0),
      };
      return supported
        ? { status: 'SUPPORTED', definition, frame, transform: ridgeTransform, supportCount: 1 }
        : {
            status: 'BLOCKED', reason: 'unsupported', definition, frame,
            transform: ridgeTransform, supportCount: 0,
          };
    }
    const supportCount = ROOF_FRAME_DEFINITIONS.has(definition.definitionId)
      ? oppositeRoofSupports(
          save,
          request.siteId,
          request.anchor,
          request.yawOffsetDegrees,
          request.spanBays,
          query,
        )
      : oppositeLegacyRoofSupports(
          save,
          request.siteId,
          request.anchor,
          request.yawOffsetDegrees,
          query,
        );
    return supportCount >= 2
      ? { status: 'SUPPORTED', definition, frame, transform, supportCount }
      : { status: 'BLOCKED', reason: 'unsupported', definition, frame, transform, supportCount };
  }
  return { status: 'SUPPORTED', definition, frame, transform, supportCount: 1 };
};

const resolveNearestBay = (
  frame: Readonly<SurvivalBuildV3Frame>,
  localX: number,
  localZ: number,
): Readonly<{ u: number; v: number }> => ({
  u: Math.floor(localX / frame.moduleMetres),
  v: Math.floor(localZ / frame.moduleMetres),
});

const resolveNearestNode = (
  frame: Readonly<SurvivalBuildV3Frame>,
  localX: number,
  localZ: number,
  divisions = 1,
): Readonly<{ u: number; v: number }> => ({
  u: Math.round(localX / frame.moduleMetres * divisions) / divisions,
  v: Math.round(localZ / frame.moduleMetres * divisions) / divisions,
});

const resolveNearestEdge = (
  frame: Readonly<SurvivalBuildV3Frame>,
  localX: number,
  localZ: number,
): Readonly<{
  edge: SurvivalBuildV3CanonicalEdge;
  sector: 'NORTH' | 'EAST' | 'SOUTH' | 'WEST';
}> => {
  const scaledX = localX / frame.moduleMetres;
  const scaledZ = localZ / frame.moduleMetres;
  const u = Math.floor(scaledX);
  const v = Math.floor(scaledZ);
  const fractionX = scaledX - u;
  const fractionZ = scaledZ - v;
  const candidates = [
    { distance: fractionZ, sector: 'NORTH' as const },
    { distance: 1 - fractionX, sector: 'EAST' as const },
    { distance: 1 - fractionZ, sector: 'SOUTH' as const },
    { distance: fractionX, sector: 'WEST' as const },
  ].sort((left, right) => left.distance - right.distance ||
    ['NORTH', 'EAST', 'SOUTH', 'WEST'].indexOf(left.sector) -
    ['NORTH', 'EAST', 'SOUTH', 'WEST'].indexOf(right.sector));
  const sector = candidates[0]!.sector;
  return {
    edge: canonicalSurvivalBuildV3Edge(u, v, sector),
    sector,
  };
};

const resolveNearestDiagonalEdge = (
  frame: Readonly<SurvivalBuildV3Frame>,
  localX: number,
  localZ: number,
): Readonly<{
  edge: SurvivalBuildV3CanonicalEdge;
  sector: 'NORTH' | 'EAST' | 'SOUTH' | 'WEST';
}> => {
  const scaledX = localX / frame.moduleMetres;
  const scaledZ = localZ / frame.moduleMetres;
  const u = Math.floor(scaledX);
  const v = Math.floor(scaledZ);
  const fractionX = scaledX - u;
  const fractionZ = scaledZ - v;
  const descendingDistance = Math.abs(fractionZ - fractionX);
  const ascendingDistance = Math.abs(fractionZ - (1 - fractionX));
  return descendingDistance <= ascendingDistance
    ? {
        edge: {
          kind: 'DIAGONAL',
          u,
          v,
          diagonal: 'NORTH_WEST_TO_SOUTH_EAST',
        },
        sector: fractionZ <= fractionX ? 'NORTH' : 'SOUTH',
      }
    : {
        edge: {
          kind: 'DIAGONAL',
          u,
          v,
          diagonal: 'SOUTH_WEST_TO_NORTH_EAST',
        },
        sector: fractionZ <= 1 - fractionX ? 'NORTH' : 'SOUTH',
      };
};

export const resolveSurvivalBuildV3OutgoingEdge = (
  frame: Readonly<SurvivalBuildV3Frame>,
  node: Readonly<{ u: number; v: number; level: number }>,
  pointerWorld: Readonly<{ x: number; y: number; z: number }>,
): Readonly<{
  anchor: SurvivalBuildV3AnchorAddress;
  sector: 'NORTH' | 'EAST' | 'SOUTH' | 'WEST';
}> => {
  const pointer = survivalBuildV3WorldToLocal(frame, pointerWorld);
  const nodeX = node.u * frame.moduleMetres;
  const nodeZ = node.v * frame.moduleMetres;
  const deltaX = pointer.x - nodeX;
  const deltaZ = pointer.z - nodeZ;
  let sector: 'NORTH' | 'EAST' | 'SOUTH' | 'WEST';
  if (Math.abs(deltaX) >= Math.abs(deltaZ)) sector = deltaX >= 0 ? 'EAST' : 'WEST';
  else sector = deltaZ >= 0 ? 'SOUTH' : 'NORTH';
  const edge = sector === 'EAST'
    ? canonicalSurvivalBuildV3Edge(node.u, node.v, 'NORTH')
    : sector === 'WEST'
      ? canonicalSurvivalBuildV3Edge(node.u - 1, node.v, 'NORTH')
      : sector === 'SOUTH'
        ? canonicalSurvivalBuildV3Edge(node.u, node.v, 'WEST')
        : canonicalSurvivalBuildV3Edge(node.u, node.v - 1, 'WEST');
  return {
    anchor: { kind: 'EDGE', level: node.level, edge },
    sector,
  };
};

export const resolveSurvivalBuildV3Intent = (options: Readonly<{
  frame: SurvivalBuildV3Frame;
  definitionId: SurvivalBuildPieceId;
  pointerWorld: Readonly<{ x: number; y: number; z: number }>;
  level: number;
  hostAnchor?: SurvivalBuildV3AnchorAddress;
  /** Two creates half-module NODE addresses. It is currently reserved for
   * upright posts so canonical wall/floor/roof topology remains unchanged. */
  nodeGridDivisions?: 1 | 2;
  /** Previous canonical choice on this same site/definition. It is retained
   * briefly across a boundary so tiny mouse motion cannot flicker the ghost. */
  previousIntent?: SurvivalBuildV3IntentResolution;
  hysteresisMetres?: number;
}>): SurvivalBuildV3IntentResolution | undefined => {
  const definition = survivalBuildV3Definition(options.definitionId);
  if (!definition) return undefined;
  const local = survivalBuildV3WorldToLocal(options.frame, options.pointerWorld);
  let anchor: SurvivalBuildV3AnchorAddress;
  let cursorSector: SurvivalBuildV3IntentResolution['cursorSector'];
  if (
    options.hostAnchor?.kind === 'NODE' &&
    (definition.role === 'FOUNDATION' || definition.role === 'BEAM')
  ) {
    const outgoing = resolveSurvivalBuildV3OutgoingEdge(
      options.frame,
      options.hostAnchor,
      options.pointerWorld,
    );
    anchor = outgoing.anchor;
    cursorSector = outgoing.sector;
  } else if (definition.anchorKind === 'NODE') {
    const node = resolveNearestNode(
      options.frame,
      local.x,
      local.z,
      options.nodeGridDivisions ?? 1,
    );
    anchor = { kind: 'NODE', level: options.level, ...node };
  } else if (definition.anchorKind === 'BAY') {
    const bay = resolveNearestBay(options.frame, local.x, local.z);
    anchor = { kind: 'BAY', level: options.level, ...bay, shape: 'SQUARE' };
  } else if (definition.anchorKind === 'EDGE') {
    const resolved = options.definitionId === 'LOG_WALL_45'
      ? resolveNearestDiagonalEdge(options.frame, local.x, local.z)
      : resolveNearestEdge(options.frame, local.x, local.z);
    anchor = { kind: 'EDGE', level: options.level, edge: resolved.edge };
    cursorSector = resolved.sector;
  } else {
    return undefined;
  }
  const previous = options.previousIntent;
  if (previous && anchorLevelMatches(previous.anchor, anchor)) {
    const previousDistance = distanceToAnchorInFrame(
      options.frame,
      previous.anchor,
      local.x,
      local.z,
    );
    const freshDistance = distanceToAnchorInFrame(options.frame, anchor, local.x, local.z);
    if (previousDistance <= freshDistance + (options.hysteresisMetres ?? 0.16)) {
      anchor = structuredClone(previous.anchor);
      cursorSector = previous.cursorSector;
    }
  }
  const transform = survivalBuildV3AnchorWorldTransform(options.frame, anchor, definition.role);
  return {
    anchor,
    transform,
    cursorSector,
    intentionKey: `${survivalBuildV3AnchorKey(anchor)}:${cursorSector ?? 'NONE'}`,
  };
};

/** Canonical rules stay first. A newly socket-placed prop can nevertheless
 * rescue an existing grid beam/floor through a real bearing contact. */
const freeContactStates = new WeakMap<object, boolean>();
export const evaluateSurvivalBuildV3Placement = (
  save:Readonly<SurvivalBuildV3SaveData>,request:Readonly<SurvivalBuildV3PlacementRequest>,
  environment?:Readonly<SurvivalBuildV3Environment>,query:Readonly<SurvivalBuildV3QueryContext>={},
):SurvivalBuildV3PlacementEvaluation=>{
  const result=evaluateCanonicalSurvivalBuildV3Placement(save,request,environment,query);
  if(request.freePose||request.roofMember||!V4_FREE_PIECES.has(request.definitionId)||result.status==='SUPPORTED'||
    result.reason&&result.reason!=='unsupported'||!result.frame||!result.definition)return result;
  let hasFree = freeContactStates.get(save);
  if (hasFree === undefined) { hasFree = save.pieces.some(p => p.freePose); freeContactStates.set(save, hasFree); }
  if (!hasFree) return result;
  const pose=result.transform ?? survivalBuildV3AnchorWorldTransform(result.frame,request.anchor,result.definition.role);
  const body=buildContactBody('$candidate',request.definitionId,pose),index=buildV4ContactIndex(save);
  if(!index.near(body).some(p=>index.records.get(p.id)?.freePose&&!query.omittedPieceIds?.has(p.id)))return result;
  const contact=evaluateBuildV4Pose({save,definitionId:request.definitionId,pose:{...pose,version:1},
    omitted:query.omittedPieceIds,terrain:environment?.sampleTerrainHeight,
    legacyStable:id=>providerIsSupported(save,id,query)});
  return contact.status==='SUPPORTED'?{...result,status:'SUPPORTED',reason:undefined,supportHint:'Supported by physical bearing'}:result;
};

export class SurvivalBuildV3Authority {
  private state: SurvivalBuildV3SaveData;
  private index: SurvivalBuildV3StateIndex;
  /** Topology mutations invalidate this cache and rebuild the read index. */
  private readonly supportStatusCache = new Map<
    string,
    SurvivalBuildV3PlacementEvaluation['status']
  >();
  private topologyIndexRebuilds = 0;
  private supportEvaluations = 0;
  private supportCacheHits = 0;

  public constructor(
    save: Readonly<SurvivalBuildV3SaveData> = emptySurvivalBuildV3Save(),
    private readonly environment: Readonly<SurvivalBuildV3Environment> = {},
  ) {
    this.state = cloneSave(save);
    this.index = new SurvivalBuildV3StateIndex(this.state, pieceOccupancyKey);
    this.topologyIndexRebuilds = 1;
  }

  public snapshot(): SurvivalBuildV3SaveData {
    return cloneSave(this.state);
  }

  /** Identity-only invalidation token: no save clone in pointer queries. */
  public topologyToken(): object { return this.state; }

  /** Immutable, shared contact index for derived runtime graphs. */
  public contactIndex(): ReturnType<typeof buildV4ContactIndex> { return buildV4ContactIndex(this.state); }

  /** Immutable topology view for derived graphs; save/undo still use snapshot. */
  public allPieces(): readonly SurvivalBuildV3Piece[] { return this.state.pieces; }

  public impact(pieceId:string,point:{x:number;y:number;z:number},power:number,eventId:string):readonly number[]|undefined {
    return this.impactBatch([{pieceId,point,power,eventId}]).get(pieceId);
  }

  public impactBatch(impacts:readonly {pieceId:string;point:{x:number;y:number;z:number};power:number;eventId:string}[]):ReadonlyMap<string,readonly number[]> {
    const changed=new Map<string,SurvivalBuildV3Piece>(),broken=new Map<string,readonly number[]>();
    for(const hit of impacts) {
      const piece=changed.get(hit.pieceId)??this.index.piece(hit.pieceId),profile=piece&&buildDamageProfile(piece.definitionId);
      if(!piece||!profile)continue;
      const result=applyBuildDamage(profile,piece.damage,hit.point,hit.power,hit.eventId);if(!result.changed)continue;
      changed.set(piece.id,{...piece,damage:result.state,buildState:'DAMAGED',revision:piece.revision+1});
      broken.set(piece.id,[...(broken.get(piece.id)??[]),...result.broken]);
    }
    if(changed.size){this.state={...this.state,pieces:this.state.pieces.map(p=>changed.get(p.id)??p)};this.refreshTopologyIndex();}
    return broken;
  }

  public repairDamage(pieceId:string):boolean {
    const piece=this.index.piece(pieceId),profile=piece&&buildDamageProfile(piece.definitionId);
    if(!piece?.damage||!profile)return false;
    const damage=repairBuildDamage(profile,piece.damage);
    this.state={...this.state,pieces:this.state.pieces.map(p=>p.id===pieceId?
      {...p,damage,buildState:damage?'DAMAGED':'FINISHED',revision:p.revision+1}:p)};
    this.refreshTopologyIndex();return true;
  }

  public restore(save: Readonly<SurvivalBuildV3SaveData>): void {
    this.state = cloneSave(save);
    this.refreshTopologyIndex();
  }

  public piece(pieceId: string): SurvivalBuildV3Piece | undefined {
    const piece = this.index.piece(pieceId);
    return piece ? structuredClone(piece) : undefined;
  }

  public advanceRoofAssembly(pieceId: string): boolean {
    const piece = this.index.piece(pieceId);
    if (!piece || !ROOF_FRAME_DEFINITIONS.has(piece.definitionId) ||
      (piece.roofAssemblyStage ?? 4) >= 4 || this.supportStatus(pieceId) === 'BLOCKED') return false;
    const roofAssemblyStage = Math.min(4, (piece.roofAssemblyStage ?? 4) + 1);
    this.state = { ...this.state, pieces: this.state.pieces.map((entry) => entry.id === pieceId
      ? { ...entry, roofAssemblyStage, buildState: roofAssemblyStage === 4 ? 'FINISHED' as const : 'FRAME_PLACED' as const,
        revision: entry.revision + 1 } : entry) };
    this.refreshTopologyIndex();
    return true;
  }

  /** Read-only indexed view for presentation systems. Callers must never
   * mutate these canonical records; snapshots remain the save/undo boundary. */
  public piecesForSiteRole(
    siteId: string,
    role: SurvivalBuildV3Role,
  ): readonly Readonly<SurvivalBuildV3Piece>[] {
    return this.index.piecesForRole(siteId, role);
  }

  public diagnostics(): SurvivalBuildV3AuthorityDiagnostics {
    return {
      indexedPieces: this.index.pieceCount,
      indexedJoints: this.index.jointCount,
      topologyIndexRebuilds: this.topologyIndexRebuilds,
      supportEvaluations: this.supportEvaluations,
      supportCacheHits: this.supportCacheHits,
      querySaveClones: 0,
    };
  }

  private refreshTopologyIndex(): void {
    this.index = new SurvivalBuildV3StateIndex(this.state, pieceOccupancyKey);
    this.topologyIndexRebuilds += 1;
    this.supportStatusCache.clear();
  }

  /** Terrain edits can change foundation support without changing topology. */
  public invalidateTerrainSupport(): void {
    this.supportStatusCache.clear();
  }

  /**
   * Re-evaluates an already placed piece without letting its own occupancy
   * block the query. Runtime load/collapse logic uses the same authority rules
   * as placement, so a later wall or beam can turn a cantilever into a safe
   * floor without storing a stale support flag on the presentation object.
   */
  public supportStatus(
    pieceId: string,
  ): SurvivalBuildV3PlacementEvaluation['status'] | undefined {
    const cached = this.supportStatusCache.get(pieceId);
    if (cached) {
      this.supportCacheHits += 1;
      return cached;
    }
    const piece = this.index.piece(pieceId);
    if (!piece) return undefined;
    const damageProfile=buildDamageProfile(piece.definitionId);
    if(damageProfile&&!buildDamageHasBearing(damageProfile,piece.damage))return 'BLOCKED';
    this.supportEvaluations += 1;
    const status = evaluateSurvivalBuildV3Placement(this.state, {
      siteId: piece.siteId,
      definitionId: piece.definitionId,
      anchor: structuredClone(piece.anchor),
      mirrored: piece.mirrored,
      paintId: piece.paintId,
      yawOffsetDegrees: piece.yawOffsetDegrees,
      spanBays: piece.spanBays,
      roofMember: piece.roofMember,
      freePose: piece.freePose,
      roofProfile: piece.roofProfile,
    }, this.environment, {
      index: this.index,
      omittedPieceIds: new Set([pieceId]),
    }).status;
    this.supportStatusCache.set(pieceId, status);
    return status;
  }

  public dependentPieceIds(pieceId: string): readonly string[] {
    const contactIndex=buildV4ContactIndex(this.state),body=contactIndex.bodies.get(pieceId);
    const freeSource=Boolean(contactIndex.records.get(pieceId)?.freePose);
    const freeNeighbours=body?contactIndex.near(body).filter(p=>p.id!==pieceId&&
      (freeSource||contactIndex.records.get(p.id)?.freePose)).map(p=>p.id):[];
    const supportingJointIds = new Set(
      this.index.jointsForPiece(pieceId)
        .filter((joint) => joint.members.some((member) =>
          member.pieceId === pieceId && member.role === 'SUPPORTS'))
        .map((joint) => joint.id),
    );
    const directDependentIds = [...new Set([...supportingJointIds]
      .flatMap((id) => this.index.joint(id) ? [this.index.joint(id)!] : [])
      .flatMap((joint) => joint.members)
      .filter((member) =>
        member.pieceId !== pieceId && member.role === 'SUPPORTED_BY')
      .map((member) => member.pieceId).concat(this.index.roofDependents(pieceId),freeNeighbours))];

    // Sharing a support joint is not the same as depending on this exact
    // piece. Neighbouring floors, for example, expose both sides of their
    // common edge. Re-evaluate each direct consumer after removing the
    // candidate support; only a piece that genuinely becomes unsupported may
    // block demolition.
    return directDependentIds.filter((dependentId) => {
      const dependent = this.index.piece(dependentId);
      if (!dependent) return false;
      const omitted = new Set([pieceId, dependentId]);
      this.supportEvaluations += 1;
      const evaluation = evaluateSurvivalBuildV3Placement(this.state, {
        siteId: dependent.siteId,
        definitionId: dependent.definitionId,
        anchor: structuredClone(dependent.anchor),
        mirrored: dependent.mirrored,
        paintId: dependent.paintId,
        yawOffsetDegrees: dependent.yawOffsetDegrees,
        spanBays: dependent.spanBays,
        roofMember: dependent.roofMember,
        freePose: dependent.freePose,
        roofProfile: dependent.roofProfile,
      }, this.environment, { index: this.index, omittedPieceIds: omitted });
      return evaluation.status === 'BLOCKED' || Boolean(dependent.roofMember?.rules===2 && evaluation.status !== 'SUPPORTED');
    });
  }

  /**
   * Returns every currently safe piece that would lose its authored support
   * if `pieceId` disappeared. Unlike `dependentPieceIds`, this also includes
   * floors which become a legal-but-dangerous cantilever. Presentation uses
   * this preview to give the player a short, reversible warning window before
   * a demolition propagates into a collapse.
   */
  public destabilizedPieceIdsAfterRemoval(pieceId: string): readonly string[] {
    if (!this.index.piece(pieceId)) return [];
    return this.state.pieces.flatMap((piece) => {
      if (piece.id === pieceId || this.supportStatus(piece.id) !== 'SUPPORTED') return [];
      this.supportEvaluations += 1;
      const next = evaluateSurvivalBuildV3Placement(this.state, {
        siteId: piece.siteId,
        definitionId: piece.definitionId,
        anchor: piece.anchor,
        mirrored: piece.mirrored,
        paintId: piece.paintId,
        yawOffsetDegrees: piece.yawOffsetDegrees,
        spanBays: piece.spanBays,
        roofMember: piece.roofMember,
        freePose: piece.freePose,
        roofProfile: piece.roofProfile,
      }, this.environment, {
        index: this.index,
        omittedPieceIds: new Set([pieceId, piece.id]),
      }).status;
      return next !== undefined && next !== 'SUPPORTED' ? [piece.id] : [];
    });
  }

  public remove(pieceId: string, force = false): boolean {
    const piece = this.index.piece(pieceId);
    if (!piece) return false;
    if (!force && this.dependentPieceIds(pieceId).length > 0) return false;
    const joints = this.state.joints.flatMap((joint): SurvivalBuildV3Joint[] => {
      const members = joint.members.filter((member) => member.pieceId !== pieceId);
      return members.length > 0 ? [{ ...joint, members }] : [];
    });
    const sites = this.state.sites.map((site) => site.id === piece.siteId
      ? {
          ...site,
          pieceIds: site.pieceIds.filter((id) => id !== pieceId),
          topologyRevision: site.topologyRevision + 1,
        }
      : site);
    this.state = {
      ...this.state,
      sites,
      joints,
      pieces: this.state.pieces.filter((candidate) => candidate.id !== pieceId),
    };
    const frame=this.frameForSite(piece.siteId);
    if(frame) {
      const sitePieces=this.state.pieces.filter((p)=>p.siteId===piece.siteId);
      const repaired=repairModularRoofSupports(frame,sitePieces);
      if(repaired!==sitePieces) {
        const byId=new Map(repaired.map((p)=>[p.id,p]));
        this.state={...this.state,pieces:this.state.pieces.map((p)=>byId.get(p.id)??p)};
      }
    }
    this.refreshTopologyIndex();
    return true;
  }

  public createSite(options: Readonly<{
    kind?: SurvivalBuildV3SiteKind;
    x: number;
    y: number;
    z: number;
    yawDegrees: number;
    excavationSiteId?: string;
  }>): SurvivalBuildV3Site {
    const siteId = `tlw-build-site:${this.state.nextSiteSerial}`;
    const frameId = `tlw-build-frame:${this.state.nextFrameSerial}`;
    const frame = createSurvivalBuildV3Frame({
      id: frameId,
      x: options.x,
      y: options.y,
      z: options.z,
      yawDegrees: options.yawDegrees,
    });
    const site: SurvivalBuildV3Site = {
      id: siteId,
      frameId,
      kind: options.kind ?? 'SURFACE',
      excavationSiteId: options.excavationSiteId,
      pieceIds: [],
      topologyRevision: 1,
    };
    this.state = {
      ...this.state,
      frames: [...this.state.frames, frame],
      sites: [...this.state.sites, site],
      nextSiteSerial: this.state.nextSiteSerial + 1,
      nextFrameSerial: this.state.nextFrameSerial + 1,
    };
    this.refreshTopologyIndex();
    return site;
  }

  public frameForSite(siteId: string): SurvivalBuildV3Frame | undefined {
    const site = this.index.site(siteId);
    return site
      ? this.index.frame(site.frameId)
      : undefined;
  }

  public evaluate(
    request: Readonly<SurvivalBuildV3PlacementRequest>,
  ): SurvivalBuildV3PlacementEvaluation {
    const resolved = resolveSurvivalBuildV3AutomaticPlacement(
      this.state,
      request,
      { index: this.index },
    );
    return evaluateSurvivalBuildV3Placement(
      this.state,
      resolved,
      this.environment,
      { index: this.index },
    );
  }

  public resolveAutomaticPlacement(
    request: Readonly<SurvivalBuildV3PlacementRequest>,
  ): SurvivalBuildV3PlacementRequest {
    return resolveSurvivalBuildV3AutomaticPlacement(
      this.state,
      request,
      { index: this.index },
    );
  }

  /** Placement replacement view without allocating a staged authority/save. */
  public evaluateReplacement(
    replacedPieceId: string,
    request: Readonly<SurvivalBuildV3PlacementRequest>,
  ): SurvivalBuildV3PlacementEvaluation {
    const resolved = resolveSurvivalBuildV3AutomaticPlacement(
      this.state,
      request,
      { index: this.index },
    );
    return evaluateSurvivalBuildV3Placement(
      this.state,
      resolved,
      this.environment,
      { index: this.index, omittedPieceIds: new Set([replacedPieceId]) },
    );
  }

  public place(
    request: Readonly<SurvivalBuildV3PlacementRequest>,
  ): SurvivalBuildV3PlacementResult {
    const resolvedRequest = resolveSurvivalBuildV3AutomaticPlacement(
      this.state,
      request,
      { index: this.index },
    );
    const evaluation = evaluateSurvivalBuildV3Placement(
      this.state,
      resolvedRequest,
      this.environment,
      { index: this.index },
    );
    if (evaluation.status === 'BLOCKED' || !evaluation.definition) {
      return {
        ok: false,
        reason: evaluation.reason ?? 'unsupported',
        evaluation,
      };
    }
    const pieceId = `tlw-build-piece:${this.state.nextPieceSerial}`;
    const descriptors = resolvedRequest.freePose ? [] : connectionDescriptors(
      evaluation.definition.role,
      resolvedRequest.anchor,
      resolvedRequest.definitionId,
      resolvedRequest.yawOffsetDegrees,
      resolvedRequest.spanBays,
    );
    const connections: SurvivalBuildV3Connection[] = descriptors.map((descriptor) => ({
      jointId: jointId(resolvedRequest.siteId, descriptor.address),
      portId: descriptor.portId,
      role: descriptor.role,
    }));
    const roofAssemblyStage = resolvedRequest.roofAssemblyStage === undefined ? undefined
      : Math.max(1, Math.min(4, Math.round(resolvedRequest.roofAssemblyStage) || 1));
    const piece: SurvivalBuildV3Piece = {
      id: pieceId,
      siteId: resolvedRequest.siteId,
      definitionId: resolvedRequest.definitionId,
      role: evaluation.definition.role,
      anchor: structuredClone(resolvedRequest.anchor),
      mirrored: resolvedRequest.mirrored,
      paintId: resolvedRequest.paintId,
      yawOffsetDegrees: resolvedRequest.yawOffsetDegrees,
      spanBays: resolvedRequest.spanBays,
      roofProfile: resolvedRequest.roofProfile,
      roofAssemblyStage,
      ...(resolvedRequest.roofMember ? { roofMember: structuredClone(resolvedRequest.roofMember) } : {}),
      ...(resolvedRequest.freePose ? { freePose: structuredClone(resolvedRequest.freePose) } : {}),
      terrainFit: evaluation.terrainFit,
      buildState: evaluation.terrainFit?.status === 'NEEDS_SITE_PREPARATION'
        ? 'SITE_PREPARATION'
        : roofAssemblyStage === 4 ? 'FINISHED' : roofAssemblyStage !== undefined ? 'FRAME_PLACED' : 'PLANNED',
      connections,
      revision: 1,
    };
    const joints = [...this.state.joints];
    // Some pieces intentionally expose more than one semantic port at the
    // same canonical address (for example a floor can both receive and pass
    // support at an edge). The topology index describes the committed state,
    // so remember joints created during this placement locally as well.
    const addedJointPositions = new Map<string, number>();
    const touchedJointPositions = new Map<string, number>();
    for (const descriptor of descriptors) {
      const id = jointId(resolvedRequest.siteId, descriptor.address);
      const member: SurvivalBuildV3JointMember = {
        pieceId,
        portId: descriptor.portId,
        role: descriptor.role,
      };
      const index = this.index.jointPosition(id) ?? addedJointPositions.get(id) ?? -1;
      if (index >= 0) {
        const current = joints[index]!;
        joints[index] = { ...current, members: [...current.members, member] };
      } else {
        addedJointPositions.set(id, joints.length);
        joints.push({
          id,
          siteId: resolvedRequest.siteId,
          address: structuredClone(descriptor.address),
          capacityClass: capacityClass(descriptor.address),
          members: [member],
        });
      }
      touchedJointPositions.set(id, index >= 0 ? index : joints.length - 1);
    }
    const sites = this.state.sites.map((site) => site.id === resolvedRequest.siteId
      ? {
          ...site,
          pieceIds: [...site.pieceIds, pieceId],
          topologyRevision: site.topologyRevision + 1,
        }
      : site
    );
    let pieces = [...this.state.pieces, piece];
    if (piece.definitionId === 'TIMBER_STAIRS' && piece.anchor.kind === 'BAY') {
      const stairsAnchor = piece.anchor;
      pieces = pieces.map((existing) =>
        existing.id !== piece.id &&
        existing.siteId === piece.siteId &&
        existing.definitionId === 'TIMBER_FLOOR' &&
        existing.anchor.kind === 'BAY' &&
        existing.anchor.level === stairsAnchor.level + 1 &&
        existing.anchor.u === stairsAnchor.u &&
        existing.anchor.v === stairsAnchor.v
          ? {
              ...existing,
              definitionId: 'TIMBER_FLOOR_STAIR_OPENING',
              yawOffsetDegrees: piece.yawOffsetDegrees ?? 0,
              revision: existing.revision + 1,
            }
          : existing,
      );
    }
    const sitePieces=pieces.filter((p)=>p.siteId===piece.siteId);
    const repaired=repairModularRoofSupports(evaluation.frame!,sitePieces);
    const repairedParents=repaired!==sitePieces;
    if(repairedParents) {
      const byId=new Map(repaired.map((p)=>[p.id,p]));
      pieces=pieces.map((p)=>byId.get(p.id)??p);
    }
    this.state = {
      ...this.state,
      sites,
      pieces,
      joints,
      nextPieceSerial: this.state.nextPieceSerial + 1,
    };
    if (piece.definitionId === 'TIMBER_STAIRS' || repairedParents) {
      // Stairs can rewrite an existing floor into an opening, so this uncommon
      // replacement path still takes the conservative complete rebuild.
      this.refreshTopologyIndex();
    } else {
      const site = sites.find((candidate) => candidate.id === piece.siteId);
      if (site) this.index.replaceSite(site);
      this.index.addPiece(piece, pieceOccupancyKey(piece));
      for (const [id, position] of touchedJointPositions) {
        const joint = joints[position];
        if (joint?.id === id) this.index.upsertJoint(joint, position);
      }
      this.supportStatusCache.clear();
    }
    return { ok: true, piece, evaluation };
  }
}
