import type { Vector3 } from 'three';
import type { FollowCameraTarget } from './FollowCameraSystem';
import { clamp } from '../utils/math';

export const CHARACTER_SHOULDER_CAMERA = {
  minimumBoom: 0.5,
  nearOffset: 0.38,
  fallbackShoulderHeight: 1.5,
  explore: { boom: 4.65, offset: 0.52, anchorHeight: 1.24 },
  tool: { boom: 2.85, offset: 0.72, anchorHeight: 0.92 },
} as const;

/** Far framing keeps the existing pitched boom. Near zoom blends into a
 * physical shoulder pose: pitch turns the view, not a boom above the head.
 * All outputs are reused; the spring arm still resolves the resulting pose. */
export function writeCharacterShoulderPose(
  target: Readonly<FollowCameraTarget>,
  direction: Readonly<Vector3>,
  right: Readonly<Vector3>,
  boom: number,
  profile: Readonly<{ boom: number; offset: number; anchorHeight: number }>,
  side: number,
  anchor: Vector3,
  position: Vector3,
): void {
  const progress = 1 - clamp(
    (boom - CHARACTER_SHOULDER_CAMERA.minimumBoom) /
      (profile.boom - CHARACTER_SHOULDER_CAMERA.minimumBoom),
    0, 1,
  );
  // Zero slope at both endpoints avoids a velocity kink when zooming from
  // the original far rig into the anatomical shoulder rig.
  const near = progress * progress * (3 - 2 * progress);
  const focusY = target.position.y ?? 0;
  const farY = focusY + profile.anchorHeight;
  // `position.y` is a composition target, not necessarily the actor's feet.
  const shoulderY = target.shoulderY ?? focusY + CHARACTER_SHOULDER_CAMERA.fallbackShoulderHeight;
  anchor.set(target.position.x, farY + (shoulderY - farY) * near, target.position.z);
  const offset = (profile.offset + (CHARACTER_SHOULDER_CAMERA.nearOffset - profile.offset) * near) * side;
  const pitchedBoom = boom * (1 - near);
  const horizontalBoom = boom * near;
  position.set(
    anchor.x - direction.x * pitchedBoom - right.z * horizontalBoom + right.x * offset,
    anchor.y - direction.y * pitchedBoom,
    anchor.z - direction.z * pitchedBoom + right.x * horizontalBoom + right.z * offset,
  );
}
