import {
  playerId,
  sessionEpoch,
  sessionId,
  type SessionId,
} from '../../netcode/core/NetworkPrimitives';
import {
  createIcewayCompatibilityDescriptor,
  evaluateSessionCompatibility,
  ICEWAY_DEFAULT_DEFINITION_SET_ID,
  ICEWAY_DEFAULT_WORLD_DATASET_HASH,
  ICEWAY_DEFAULT_WORLD_DATASET_ID,
  ICEWAY_WEBSOCKET_CAPABILITIES,
  validateSessionBootstrapDescriptorPayload,
  type SessionBootstrapDescriptorPayload,
} from '../../netcode/protocol/SessionHandshake';
import { WebSocketClientTransport } from '../../netcode/transport/WebSocketClientTransport';
import type { SessionTransportEndpoint } from '../../netcode/transport/SessionTransport';
import { ICEWAY_BUILD_ID } from '../../core/RuntimeBuildFlags';
import {
  MultiplayerSessionClient,
  type SessionResumeCredentials,
} from './MultiplayerSessionClient';
import {
  createCompatibilityRejectionNotice,
  type CompatibilityRejectionNoticePayload,
} from '../../netcode/protocol/DeploymentPolicy';

const ROOM_ID_PATTERN = /^[A-Za-z0-9_-]{8,64}$/;
const MAXIMUM_BOOTSTRAP_BYTES = 64 * 1024;
const CLIENT_INSTANCE_STORAGE_KEY = 'iceway-multiplayer-client-v1';
const RESUME_STORAGE_PREFIX = 'iceway-multiplayer-resume-v1:';

export type BrowserMultiplayerBootstrapFailure =
  | 'INCOMPLETE_CONFIGURATION'
  | 'INVALID_SERVER_URL'
  | 'MIXED_CONTENT'
  | 'INVALID_ROOM_ID'
  | 'INVALID_DISPLAY_NAME'
  | 'DESCRIPTOR_REQUEST_FAILED'
  | 'INVALID_SERVER_DESCRIPTOR'
  | 'INCOMPATIBLE_SERVER';

export class BrowserMultiplayerBootstrapError extends Error {
  public constructor(
    public readonly code: BrowserMultiplayerBootstrapFailure,
    message: string,
    public readonly recoveryNotice?: CompatibilityRejectionNoticePayload,
  ) {
    super(message);
    this.name = 'BrowserMultiplayerBootstrapError';
  }
}

export interface BrowserMultiplayerLaunchConfig {
  serverHttpUrl: string;
  webSocketUrl: string;
  roomId: string;
  sessionId: SessionId;
  displayName: string;
}

export interface BrowserMultiplayerSessionHandle {
  config: BrowserMultiplayerLaunchConfig;
  descriptor: SessionBootstrapDescriptorPayload;
  client: MultiplayerSessionClient;
  stop(): void;
}

export const createBrowserMultiplayerInviteUrl = (
  config: Readonly<BrowserMultiplayerLaunchConfig>,
  pageHref: string,
): string => {
  const invite = new URL(pageHref);
  invite.searchParams.set('mpServer', config.serverHttpUrl);
  invite.searchParams.set('mpRoom', config.roomId);
  invite.searchParams.delete('mpName');
  invite.hash = '';
  return invite.toString();
};

export type BrowserSessionLifecycleState =
  | 'FOREGROUND'
  | 'BACKGROUND'
  | 'OFFLINE';

export interface BrowserSessionLifecycle {
  currentState(): BrowserSessionLifecycleState;
  subscribe(
    listener: (state: BrowserSessionLifecycleState, reason: string) => void,
  ): () => void;
}

export interface BrowserMultiplayerBootstrapDependencies {
  fetch?: typeof globalThis.fetch;
  storage?: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;
  randomId?: () => string;
  requestTimeoutMs?: number;
  transportFactory?: (webSocketUrl: string) => SessionTransportEndpoint;
  lifecycle?: BrowserSessionLifecycle;
}

const boundedTrimmed = (
  value: string | null | undefined,
  maximum: number,
): string | undefined => {
  const trimmed = value?.trim();
  return trimmed && trimmed.length <= maximum ? trimmed : undefined;
};

const normalizedServerUrl = (
  raw: string,
  pageUrl: URL,
): URL => {
  let server: URL;
  try {
    server = new URL(raw, pageUrl);
  } catch {
    throw new BrowserMultiplayerBootstrapError(
      'INVALID_SERVER_URL',
      'Multiplayer server URL is invalid.',
    );
  }
  if (
    !['http:', 'https:'].includes(server.protocol) ||
    server.username ||
    server.password ||
    server.search ||
    server.hash
  ) {
    throw new BrowserMultiplayerBootstrapError(
      'INVALID_SERVER_URL',
      'Multiplayer server must be a credential-free HTTP(S) base URL.',
    );
  }
  if (pageUrl.protocol === 'https:' && server.protocol !== 'https:') {
    throw new BrowserMultiplayerBootstrapError(
      'MIXED_CONTENT',
      'HTTPS clients require an HTTPS/WSS multiplayer server.',
    );
  }
  server.pathname = server.pathname.replace(/\/+$/, '');
  return server;
};

export const parseBrowserMultiplayerLaunchConfig = (
  href: string,
): BrowserMultiplayerLaunchConfig | undefined => {
  const pageUrl = new URL(href);
  const serverValue = boundedTrimmed(
    pageUrl.searchParams.get('mpServer'),
    512,
  );
  const roomValue = boundedTrimmed(
    pageUrl.searchParams.get('mpRoom'),
    64,
  );
  if (!serverValue && !roomValue) return undefined;
  if (!serverValue || !roomValue) {
    throw new BrowserMultiplayerBootstrapError(
      'INCOMPLETE_CONFIGURATION',
      'Both mpServer and mpRoom are required for multiplayer.',
    );
  }
  if (!ROOM_ID_PATTERN.test(roomValue)) {
    throw new BrowserMultiplayerBootstrapError(
      'INVALID_ROOM_ID',
      'Multiplayer room ID is invalid.',
    );
  }
  const displayName = boundedTrimmed(
    pageUrl.searchParams.get('mpName') ?? 'Penguin',
    48,
  );
  if (!displayName) {
    throw new BrowserMultiplayerBootstrapError(
      'INVALID_DISPLAY_NAME',
      'Multiplayer display name is invalid.',
    );
  }
  const server = normalizedServerUrl(serverValue, pageUrl);
  const webSocket = new URL(server.toString());
  webSocket.protocol = server.protocol === 'https:' ? 'wss:' : 'ws:';
  webSocket.pathname = `${server.pathname}/rooms/${encodeURIComponent(roomValue)}`
    .replace(/^\/\//, '/');
  return {
    serverHttpUrl: server.toString().replace(/\/$/, ''),
    webSocketUrl: webSocket.toString(),
    roomId: roomValue,
    sessionId: sessionId(`session:room:${roomValue}`),
    displayName,
  };
};

export const createBrowserCompatibilityDescriptor = () =>
  createIcewayCompatibilityDescriptor({
    buildId: ICEWAY_BUILD_ID,
    worldDatasetId:
      import.meta.env.VITE_ICEWAY_WORLD_DATASET_ID?.trim() ||
      ICEWAY_DEFAULT_WORLD_DATASET_ID,
    worldDatasetHash:
      import.meta.env.VITE_ICEWAY_WORLD_DATASET_HASH?.trim() ||
      ICEWAY_DEFAULT_WORLD_DATASET_HASH,
    definitionSetIds: [
      import.meta.env.VITE_ICEWAY_DEFINITION_SET_ID?.trim() ||
        ICEWAY_DEFAULT_DEFINITION_SET_ID,
    ],
    capabilities: ICEWAY_WEBSOCKET_CAPABILITIES,
  });

const fetchBootstrapDescriptor = async (
  serverHttpUrl: string,
  fetcher: typeof globalThis.fetch,
  timeoutMs: number,
): Promise<SessionBootstrapDescriptorPayload> => {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  let response: Response;
  try {
    response = await fetcher(`${serverHttpUrl}/session-descriptor`, {
      method: 'GET',
      headers: { Accept: 'application/json' },
      signal: controller.signal,
    });
  } catch (error) {
    throw new BrowserMultiplayerBootstrapError(
      'DESCRIPTOR_REQUEST_FAILED',
      error instanceof Error
        ? `Multiplayer descriptor request failed: ${error.message}`
        : 'Multiplayer descriptor request failed.',
    );
  } finally {
    clearTimeout(timeout);
  }
  if (!response.ok) {
    throw new BrowserMultiplayerBootstrapError(
      'DESCRIPTOR_REQUEST_FAILED',
      `Multiplayer descriptor request returned HTTP ${response.status}.`,
    );
  }
  const declaredLength = Number(response.headers.get('content-length'));
  if (Number.isFinite(declaredLength) && declaredLength > MAXIMUM_BOOTSTRAP_BYTES) {
    throw new BrowserMultiplayerBootstrapError(
      'INVALID_SERVER_DESCRIPTOR',
      'Multiplayer descriptor exceeds the size limit.',
    );
  }
  const body = await response.text();
  if (new TextEncoder().encode(body).byteLength > MAXIMUM_BOOTSTRAP_BYTES) {
    throw new BrowserMultiplayerBootstrapError(
      'INVALID_SERVER_DESCRIPTOR',
      'Multiplayer descriptor exceeds the size limit.',
    );
  }
  let decoded: unknown;
  try {
    decoded = JSON.parse(body);
  } catch {
    decoded = undefined;
  }
  const descriptor = validateSessionBootstrapDescriptorPayload(decoded);
  if (!descriptor) {
    throw new BrowserMultiplayerBootstrapError(
      'INVALID_SERVER_DESCRIPTOR',
      'Multiplayer server returned an invalid compatibility descriptor.',
    );
  }
  return descriptor;
};

const resumeStorageKey = (
  config: Readonly<BrowserMultiplayerLaunchConfig>,
): string =>
  `${RESUME_STORAGE_PREFIX}${encodeURIComponent(
    `${config.serverHttpUrl}|${config.roomId}`,
  )}`;

const loadResumeCredentials = (
  storage: BrowserMultiplayerBootstrapDependencies['storage'],
  key: string,
  expectedSessionId: SessionId,
): SessionResumeCredentials | undefined => {
  if (!storage) return undefined;
  try {
    const raw = storage.getItem(key);
    if (!raw || raw.length > 1_024) return undefined;
    const decoded = JSON.parse(raw) as Record<string, unknown>;
    if (
      decoded.sessionId !== expectedSessionId ||
      typeof decoded.playerId !== 'string' ||
      !decoded.playerId ||
      decoded.playerId.length > 160 ||
      typeof decoded.resumeToken !== 'string' ||
      !decoded.resumeToken ||
      decoded.resumeToken.length > 256 ||
      (decoded.sessionEpoch !== undefined &&
        (typeof decoded.sessionEpoch !== 'number' ||
          !Number.isSafeInteger(decoded.sessionEpoch) ||
          decoded.sessionEpoch < 1))
    ) {
      storage.removeItem(key);
      return undefined;
    }
    return {
      sessionId: expectedSessionId,
      playerId: playerId(decoded.playerId),
      resumeToken: decoded.resumeToken,
      ...(decoded.sessionEpoch === undefined
        ? {}
        : { sessionEpoch: sessionEpoch(decoded.sessionEpoch as number) }),
    };
  } catch {
    try {
      storage.removeItem(key);
    } catch {
      // Storage may be unavailable in privacy modes; reconnect still works
      // within the lifetime of the current client instance.
    }
    return undefined;
  }
};

const clientInstanceId = (
  storage: BrowserMultiplayerBootstrapDependencies['storage'],
  randomId: () => string,
): string => {
  try {
    const existing = storage?.getItem(CLIENT_INSTANCE_STORAGE_KEY)?.trim();
    if (existing && existing.length <= 160) return existing;
    const created = `browser:${randomId()}`.slice(0, 160);
    storage?.setItem(CLIENT_INSTANCE_STORAGE_KEY, created);
    return created;
  } catch {
    return `browser:${randomId()}`.slice(0, 160);
  }
};

const browserStorage = (): BrowserMultiplayerBootstrapDependencies['storage'] => {
  try {
    return globalThis.localStorage;
  } catch {
    // Accessing the localStorage property itself may throw in hardened privacy
    // modes. The session remains usable; only cross-reload resume is disabled.
    return undefined;
  }
};

const browserSessionLifecycle = (): BrowserSessionLifecycle => ({
  currentState: () => {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
      return 'OFFLINE';
    }
    return typeof document !== 'undefined' && document.hidden
      ? 'BACKGROUND'
      : 'FOREGROUND';
  },
  subscribe: (listener) => {
    if (typeof document === 'undefined' || typeof window === 'undefined') {
      return () => undefined;
    }
    const visibility = () => listener(
      document.hidden ? 'BACKGROUND' : 'FOREGROUND',
      document.hidden ? 'Document hidden.' : 'Document visible.',
    );
    const pageHide = () => listener('BACKGROUND', 'Page hidden or frozen.');
    const pageShow = () => listener('FOREGROUND', 'Page restored.');
    const offline = () => listener('OFFLINE', 'Browser went offline.');
    const online = () => listener('FOREGROUND', 'Browser returned online.');
    document.addEventListener('visibilitychange', visibility);
    window.addEventListener('pagehide', pageHide);
    window.addEventListener('pageshow', pageShow);
    window.addEventListener('offline', offline);
    window.addEventListener('online', online);
    return () => {
      document.removeEventListener('visibilitychange', visibility);
      window.removeEventListener('pagehide', pageHide);
      window.removeEventListener('pageshow', pageShow);
      window.removeEventListener('offline', offline);
      window.removeEventListener('online', online);
    };
  },
});

export const startBrowserMultiplayerSession = async (
  config: Readonly<BrowserMultiplayerLaunchConfig>,
  dependencies: Readonly<BrowserMultiplayerBootstrapDependencies> = {},
): Promise<BrowserMultiplayerSessionHandle> => {
  const fetcher = dependencies.fetch ?? globalThis.fetch.bind(globalThis);
  const storage = dependencies.storage ?? browserStorage();
  const randomId = dependencies.randomId ?? (() => crypto.randomUUID());
  const descriptor = await fetchBootstrapDescriptor(
    config.serverHttpUrl,
    fetcher,
    dependencies.requestTimeoutMs ?? 5_000,
  );
  const clientCompatibility = createBrowserCompatibilityDescriptor();
  const compatibility = evaluateSessionCompatibility(clientCompatibility, {
    descriptor: descriptor.compatibility,
    requiredCapabilities: descriptor.requiredCapabilities,
    requireExactBuild: descriptor.requireExactBuild,
    deploymentPolicy: descriptor.deploymentPolicy,
  });
  if (!compatibility.accepted) {
    const notice = createCompatibilityRejectionNotice(
      compatibility.reason,
      descriptor.compatibility.buildId,
      descriptor.deploymentPolicy,
    );
    throw new BrowserMultiplayerBootstrapError(
      'INCOMPATIBLE_SERVER',
      notice.message,
      notice,
    );
  }

  const storageKey = resumeStorageKey(config);
  const resumeCredentials = loadResumeCredentials(
    storage,
    storageKey,
    config.sessionId,
  );
  const client = new MultiplayerSessionClient({
    sessionId: config.sessionId,
    displayName: config.displayName,
    clientInstanceId: clientInstanceId(storage, randomId),
    compatibility: clientCompatibility,
    resumeCredentials,
    transportFactory: () =>
      dependencies.transportFactory?.(config.webSocketUrl) ??
      new WebSocketClientTransport(config.webSocketUrl),
  });
  const unsubscribe = client.onState((state) => {
    if (state.phase === 'JOINED') {
      const credentials = client.exportResumeCredentials();
      if (credentials) {
        try {
          storage?.setItem(storageKey, JSON.stringify(credentials));
        } catch {
          // A denied storage write does not prevent the active session.
        }
      }
    } else if (state.phase === 'REJECTED' && resumeCredentials) {
      try {
        storage?.removeItem(storageKey);
      } catch {
        // Ignore privacy-mode storage failures.
      }
    }
  });
  const lifecycle = dependencies.lifecycle ?? browserSessionLifecycle();
  const unsubscribeLifecycle = lifecycle.subscribe((state, reason) => {
    if (state === 'FOREGROUND') client.resumeFromSuspension();
    else client.suspend(reason);
  });
  client.start();
  if (lifecycle.currentState() !== 'FOREGROUND') {
    client.suspend('Session started while browser was backgrounded or offline.');
  }
  return {
    config: { ...config },
    descriptor,
    client,
    stop: () => {
      unsubscribeLifecycle();
      unsubscribe();
      client.stop();
    },
  };
};
