export interface SessionContinuityPolicyPayload {
  readonly version: 1;
  readonly kind: 'SESSION_CONTINUITY_POLICY';
  readonly authorityModel: 'SERVER_AUTHORITATIVE';
  readonly deploymentModes: readonly ['LOCAL_PRIVATE_HOST', 'DEDICATED_SERVER'];
  readonly continuationMode: 'CHECKPOINT_RESUME';
  readonly peerHostElection: false;
  readonly sessionEpochTransition: true;
}

/**
 * Product decision for the first supported multiplayer release: continuity
 * comes from a dedicated authority or checkpoint resume, never peer election.
 */
export const ICEWAY_SESSION_CONTINUITY_POLICY:
Readonly<SessionContinuityPolicyPayload> = Object.freeze({
  version: 1,
  kind: 'SESSION_CONTINUITY_POLICY',
  authorityModel: 'SERVER_AUTHORITATIVE',
  deploymentModes: Object.freeze([
    'LOCAL_PRIVATE_HOST',
    'DEDICATED_SERVER',
  ] as const),
  continuationMode: 'CHECKPOINT_RESUME',
  peerHostElection: false,
  sessionEpochTransition: true,
});

export const validateSessionContinuityPolicyPayload = (
  input: unknown,
): SessionContinuityPolicyPayload | undefined => {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return undefined;
  const value = input as Record<string, unknown>;
  if (
    value.version !== 1 ||
    value.kind !== 'SESSION_CONTINUITY_POLICY' ||
    value.authorityModel !== 'SERVER_AUTHORITATIVE' ||
    value.continuationMode !== 'CHECKPOINT_RESUME' ||
    value.peerHostElection !== false ||
    value.sessionEpochTransition !== true ||
    !Array.isArray(value.deploymentModes) ||
    value.deploymentModes.length !== 2 ||
    value.deploymentModes[0] !== 'LOCAL_PRIVATE_HOST' ||
    value.deploymentModes[1] !== 'DEDICATED_SERVER'
  ) return undefined;
  return {
    version: 1,
    kind: 'SESSION_CONTINUITY_POLICY',
    authorityModel: 'SERVER_AUTHORITATIVE',
    deploymentModes: ['LOCAL_PRIVATE_HOST', 'DEDICATED_SERVER'],
    continuationMode: 'CHECKPOINT_RESUME',
    peerHostElection: false,
    sessionEpochTransition: true,
  };
};
