import {
  BoxGeometry,
  BufferGeometry,
  CylinderGeometry,
  Float32BufferAttribute,
  Group,
  Mesh,
  MeshStandardMaterial,
  Points,
  PointsMaterial,
  type Scene,
} from 'three';

export interface PushSnowThrowerView {
  readonly x: number;
  readonly z: number;
  readonly heading: number;
  readonly chuteSide: -1 | 1;
  readonly augerActive: boolean;
}

interface ThrowerParticle {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
}

const PARTICLE_COUNT = 36;

/** Compact one-draw plume and a readable low-poly push snow thrower. */
export class PushSnowThrowerPresenter {
  private readonly root = new Group();
  private readonly chutePivot = new Group();
  private readonly augerMaterial = new MeshStandardMaterial({
    color: 0xd96130,
    roughness: 0.58,
    metalness: 0.14,
    emissive: 0x5c1708,
  });
  private readonly darkMaterial = new MeshStandardMaterial({
    color: 0x273235,
    roughness: 0.77,
    metalness: 0.18,
  });
  private readonly metalMaterial = new MeshStandardMaterial({
    color: 0x8faaa9,
    roughness: 0.52,
    metalness: 0.35,
  });
  private readonly geometries = [
    new BoxGeometry(1, 1, 1),
    new CylinderGeometry(0.5, 0.5, 1, 10),
  ];
  private readonly plumeGeometry = new BufferGeometry();
  private readonly plumePositions = new Float32Array(PARTICLE_COUNT * 3);
  private readonly plumeMaterial = new PointsMaterial({
    color: 0xf2fbff,
    size: 0.22,
    transparent: true,
    opacity: 0.86,
    depthWrite: false,
    sizeAttenuation: true,
  });
  private readonly plume: Points;
  private readonly particles: ThrowerParticle[] = Array.from(
    { length: PARTICLE_COUNT },
    () => ({ x: 0, y: -100, z: 0, vx: 0, vy: 0, vz: 0, life: 0 }),
  );
  private particleCursor = 0;
  private view: PushSnowThrowerView = {
    x: 0,
    z: 0,
    heading: 0,
    chuteSide: 1,
    augerActive: false,
  };

  public constructor(
    scene: Scene,
    private readonly sampleSurfaceHeight: (x: number, z: number) => number,
  ) {
    this.root.name = 'North Star push snow thrower';
    const body = new Mesh(this.geometries[0]!, this.augerMaterial);
    body.position.set(0, 0.43, 0.2);
    body.scale.set(0.9, 0.52, 0.62);
    const intake = new Mesh(this.geometries[1]!, this.augerMaterial);
    intake.rotation.z = Math.PI / 2;
    intake.position.set(0, 0.32, 0.55);
    intake.scale.set(0.38, 0.98, 0.38);
    const engine = new Mesh(this.geometries[0]!, this.darkMaterial);
    engine.position.set(0, 0.74, 0.05);
    engine.scale.set(0.48, 0.38, 0.48);
    const chute = new Mesh(this.geometries[1]!, this.metalMaterial);
    chute.position.y = 0.5;
    chute.scale.set(0.2, 0.72, 0.2);
    const chuteMouth = new Mesh(this.geometries[0]!, this.metalMaterial);
    chuteMouth.position.set(0, 0.86, 0.17);
    chuteMouth.scale.set(0.32, 0.22, 0.48);
    this.chutePivot.position.set(0, 0.62, 0.17);
    this.chutePivot.add(chute, chuteMouth);
    for (const side of [-1, 1]) {
      const wheel = new Mesh(this.geometries[1]!, this.darkMaterial);
      wheel.rotation.z = Math.PI / 2;
      wheel.position.set(side * 0.53, 0.35, -0.03);
      wheel.scale.set(0.34, 0.18, 0.34);
      this.root.add(wheel);
      const handle = new Mesh(this.geometries[1]!, this.darkMaterial);
      handle.rotation.z = side * -0.17;
      handle.rotation.x = -0.55;
      handle.position.set(side * 0.37, 1.18, -0.52);
      handle.scale.set(0.045, 1.18, 0.045);
      this.root.add(handle);
    }
    this.root.add(body, intake, engine, this.chutePivot);
    this.root.traverse((object) => {
      if (!(object instanceof Mesh)) return;
      object.castShadow = true;
      object.receiveShadow = true;
    });
    this.plumeGeometry.setAttribute(
      'position',
      new Float32BufferAttribute(this.plumePositions, 3),
    );
    this.plume = new Points(this.plumeGeometry, this.plumeMaterial);
    this.plume.name = 'Push snow thrower chute plume';
    this.plume.frustumCulled = false;
    scene.add(this.root, this.plume);
    this.setVisible(false);
  }

  public setVisible(visible: boolean): void {
    this.root.visible = visible;
    this.plume.visible = visible;
  }

  public update(view: Readonly<PushSnowThrowerView>, deltaSeconds: number): void {
    this.view = { ...view };
    this.root.position.set(
      view.x,
      this.sampleSurfaceHeight(view.x, view.z) + 0.03,
      view.z,
    );
    this.root.rotation.y = view.heading;
    this.chutePivot.rotation.y = view.chuteSide * Math.PI * 0.48;
    this.augerMaterial.emissiveIntensity = view.augerActive ? 0.25 : 0.03;
    this.updatePlume(Math.max(0, Math.min(deltaSeconds, 0.05)));
  }

  public emitSnow(snowMass: number): void {
    if (snowMass <= 0.00001) return;
    const count = Math.max(2, Math.min(9, Math.ceil(snowMass * 360)));
    const forwardX = Math.sin(this.view.heading);
    const forwardZ = Math.cos(this.view.heading);
    const rightX = Math.cos(this.view.heading);
    const rightZ = -Math.sin(this.view.heading);
    for (let index = 0; index < count; index += 1) {
      const particle = this.particles[this.particleCursor]!;
      this.particleCursor = (this.particleCursor + 1) % this.particles.length;
      const variation = ((index * 0.61803398875) % 1) - 0.5;
      particle.x = this.view.x + forwardX * 0.18;
      particle.z = this.view.z + forwardZ * 0.18;
      particle.y = this.sampleSurfaceHeight(this.view.x, this.view.z) + 1.18;
      particle.vx = rightX * this.view.chuteSide * (2.35 + variation * 0.55) +
        forwardX * (0.64 + variation * 0.24);
      particle.vz = rightZ * this.view.chuteSide * (2.35 + variation * 0.55) +
        forwardZ * (0.64 + variation * 0.24);
      particle.vy = 1.18 + Math.abs(variation) * 0.42;
      particle.life = 0.78 + (variation + 0.5) * 0.18;
    }
  }

  public dispose(): void {
    this.root.removeFromParent();
    this.plume.removeFromParent();
    this.geometries.forEach((geometry) => geometry.dispose());
    this.plumeGeometry.dispose();
    this.augerMaterial.dispose();
    this.darkMaterial.dispose();
    this.metalMaterial.dispose();
    this.plumeMaterial.dispose();
  }

  private updatePlume(deltaSeconds: number): void {
    for (let index = 0; index < this.particles.length; index += 1) {
      const particle = this.particles[index]!;
      if (particle.life > 0) {
        particle.life -= deltaSeconds;
        particle.x += particle.vx * deltaSeconds;
        particle.y += particle.vy * deltaSeconds;
        particle.z += particle.vz * deltaSeconds;
        particle.vy -= 6.2 * deltaSeconds;
        const floor = this.sampleSurfaceHeight(particle.x, particle.z) + 0.05;
        if (particle.y <= floor) particle.life = 0;
      }
      const offset = index * 3;
      this.plumePositions[offset] = particle.x;
      this.plumePositions[offset + 1] = particle.life > 0 ? particle.y : -100;
      this.plumePositions[offset + 2] = particle.z;
    }
    const position = this.plumeGeometry.getAttribute('position');
    position.needsUpdate = true;
  }
}
