import type { SurvivalBuildPieceId } from '../SurvivalBuildingCatalog';

/** Five tools, not nine apparently unrelated timbers. Variants retain their
 * saved IDs and explicit load roles; selecting a tool never changes old parts. */
export const SURVIVAL_ROOF_TOOLS = [
  { primary:'SIMPLE_ROOF_SLOPE_26', name:'Roof tile', variants:[
    ['SIMPLE_ROOF_SLOPE_26','Shallow · 2 m run / 1 m rise'], ['SIMPLE_ROOF_SLOPE_45','Steep · 2 m run / 2 m rise'],
    ['SIMPLE_ROOF_INNER_26','Inner corner · shallow'], ['SIMPLE_ROOF_INNER_45','Inner corner · steep'],
    ['SIMPLE_ROOF_OUTER_26','Outer corner · shallow'], ['SIMPLE_ROOF_OUTER_45','Outer corner · steep'],
  ] },
  { primary:'SIMPLE_ROOF_RIDGE_26', name:'Finish', variants:[
    ['SIMPLE_ROOF_RIDGE_26','Ridge cap · shallow'], ['SIMPLE_ROOF_RIDGE_45','Ridge cap · steep'],
    ['SIMPLE_ROOF_GABLE_26','Gable half · shallow'], ['SIMPLE_ROOF_GABLE_45','Gable half · steep'],
  ] },
  { primary: 'ROOF_CROSS_BEAM', name: 'Beam', variants: [
    ['ROOF_CROSS_BEAM', 'Tie · across supporting walls'],
    ['ROOF_SPINE_BEAM', 'Centre · along tie beams'],
    ['ROOF_RIDGE_BEAM', 'Ridge · across upright tops'],
  ] },
  { primary: 'ROOF_RIDGE_POST', name: 'Upright', variants: [
    ['ROOF_RIDGE_POST', 'Ridge upright · from a tie'],
    ['ROOF_SUPPORT_POST', 'Bearing upright · floor to beam'],
    ['ROOF_BRACE', 'Infill strut · tie to rafter'],
  ] },
  { primary: 'ROOF_RAFTER', name: 'Rafter', variants: [['ROOF_RAFTER', 'Length Q/E · pitch Shift+R']] },
  { primary: 'ROOF_BATTEN', name: 'Batten', variants: [['ROOF_BATTEN', 'Across rafters · 2 m or G 1 m']] },
  { primary: 'ROOF_COVER', name: 'Cover', variants: [['ROOF_COVER', 'Roof boards · clipped to the slope'], ['ROOF_GABLE', 'Gable infill · close the roof ends']] },
] as const satisfies readonly { primary: SurvivalBuildPieceId; name:string; variants:readonly (readonly [SurvivalBuildPieceId,string])[] }[];

export const survivalRoofTool = (id: SurvivalBuildPieceId) =>
  SURVIVAL_ROOF_TOOLS.find(tool => tool.variants.some(([variant]) => variant === id));

/** The palette describes shapes, not load roles. Persist the resolved role so
 * existing saves and support rules stay explicit; never ask the player to pick it. */
export const contextualRoofDefinitions = (id: SurvivalBuildPieceId): readonly SurvivalBuildPieceId[] =>
  survivalRoofTool(id)?.variants.map(([variant]) => variant) ?? [id];
