import { survivalBuildDefinition, type SurvivalBuildPieceDefinition } from '../SurvivalBuildingCatalog';
import type { SurvivalPlacedBuildPiece } from './SurvivalConstructionState';
import { isTriangleBuildFloor, triangleBuildFloorContains } from './SurvivalBuildV4Catalog';
import { type Ray, Vector3 } from 'three';
import type { SurvivalBuildSurfaceHit } from '../SurvivalBuildPlacementV2';

export interface SurvivalFurnitureSurface {
  readonly y: number;
  readonly pieceIds: readonly string[];
}

export function furnitureSupportHeight(piece: Readonly<SurvivalPlacedBuildPiece>): number | undefined {
  const d=survivalBuildDefinition(piece.definitionId);
  if(d.placementSurfaceY !== undefined) return piece.y+d.placementSurfaceY;
  if (['TIMBER_FLOOR_EQUILATERAL','TIMBER_FLOOR','TIMBER_FLOOR_STAIR_OPENING','STONE_FLOOR','TIMBER_FLOOR_TRIANGLE','STONE_FLOOR_TRIANGLE',
    'LOG_FOUNDATION','STONE_FOUNDATION','LOG_POST','LOG_BEAM','LOG_WALL_STRAIGHT','LOG_HALF_WALL','STONE_WALL',
    'STORAGE_CHEST_SMALL','CAMP_BEDROLL'].includes(piece.definitionId)) return piece.y+d.height;
  return undefined;
}

/** Logical flat support surfaces bridge cosmetic plank seams, but never real
 * stair/triangle/damage openings. No expanded selection boxes are involved. */
export function intersectFurnitureSupport(
  ray: Readonly<Ray>, pieces: readonly SurvivalPlacedBuildPiece[], maximumDistance: number,
  solidAt?: (piece: SurvivalPlacedBuildPiece, u: number, v: number) => boolean,
  underside = false,
): (SurvivalBuildSurfaceHit & { distance: number }) | undefined {
  if (underside ? ray.direction.y <= .00001 : ray.direction.y >= -.00001) return undefined;
  let best: (SurvivalBuildSurfaceHit & { distance: number }) | undefined;
  const point = new Vector3();
  for (const piece of pieces) {
    const supportY = furnitureSupportHeight(piece);
    if (supportY === undefined) continue;
    if (underside && !['TIMBER_FLOOR_EQUILATERAL','TIMBER_FLOOR','TIMBER_FLOOR_STAIR_OPENING','STONE_FLOOR',
      'TIMBER_FLOOR_TRIANGLE','STONE_FLOOR_TRIANGLE','LOG_BEAM','TIMBER_SHELF'].includes(piece.definitionId)) continue;
    const y = underside ? piece.y : supportY;
    const distance = (y - ray.origin.y) / ray.direction.y;
    if (distance < 0 || distance > maximumDistance || (best && distance >= best.distance)) continue;
    ray.at(distance, point);
    if (!findSurvivalFurnitureSurface([piece], {halfWidth:0,halfDepth:0},
      {x:point.x,z:point.z,yawDegrees:0},supportY-.001,supportY+.001,solidAt)) continue;
    best = {pieceId:piece.id,x:point.x,y,z:point.z,normalX:0,normalY:underside?-1:1,normalZ:0,distance};
  }
  return best;
}

/** Nine footprint samples, allowing furniture across coplanar floor seams.
 * Stairs, openings and pitched roofs are not flat furniture supports. */
export function findSurvivalFurnitureSurface(
  pieces: readonly SurvivalPlacedBuildPiece[],
  footprint: Pick<SurvivalBuildPieceDefinition, 'halfWidth' | 'halfDepth'>,
  placement: { x: number; z: number; yawDegrees: number; id?: string },
  minimumY: number,
  maximumY: number,
  solidAt?:(piece:SurvivalPlacedBuildPiece,u:number,v:number)=>boolean,
): SurvivalFurnitureSurface | undefined {
  const floors = pieces.filter(p => p.id !== placement.id && furnitureSupportHeight(p) !== undefined)
    .map(p => ({ p, d: survivalBuildDefinition(p.definitionId), y: furnitureSupportHeight(p)! }))
    .filter(p => p.y >= minimumY && p.y <= maximumY).sort((a, b) => b.y - a.y);
  const yaw = placement.yawDegrees * Math.PI / 180;
  const points = [-1, 0, 1].flatMap(u => [-1, 0, 1].map(v => ({
    x: placement.x + Math.cos(yaw) * u * footprint.halfWidth + Math.sin(yaw) * v * footprint.halfDepth,
    z: placement.z - Math.sin(yaw) * u * footprint.halfWidth + Math.cos(yaw) * v * footprint.halfDepth,
  })));
  for (const height of new Set(floors.map(f => f.y))) {
    const supports = new Set<string>();
    const covered = points.every(point => {
      const floor = floors.find(({ p, d, y }) => {
        if (Math.abs(y - height) > .04) return false;
        const a = -p.yawDegrees * Math.PI / 180, dx = point.x - p.x, dz = point.z - p.z;
        const u = Math.cos(a) * dx + Math.sin(a) * dz;
        const v = -Math.sin(a) * dx + Math.cos(a) * dz;
        if (Math.abs(u) > d.halfWidth + .025 || Math.abs(v) > d.halfDepth + .025) return false;
        if(isTriangleBuildFloor(p.definitionId)&&!triangleBuildFloorContains(u,v,.025,p.definitionId))return false;
        if(solidAt&&!solidAt(p,u,v))return false;
        return p.definitionId !== 'TIMBER_FLOOR_STAIR_OPENING' ||
          !(Math.abs(u) < .65 && v > -.65 && v < .84);
      });
      if (floor) supports.add(floor.p.id);
      return Boolean(floor);
    });
    if (covered) return { y: height, pieceIds: [...supports] };
  }
  return undefined;
}
