export const borealisBuildingFrontVector = (
  front: BorealisTownBuildingLot['front'],
): Readonly<{ x: number; z: number }> => {
  switch (front) {
    case 'NORTH': return { x: 0, z: -1 };
    case 'SOUTH': return { x: 0, z: 1 };
    case 'EAST': return { x: 1, z: 0 };
    case 'WEST': return { x: -1, z: 0 };
  }
};

export const borealisBuildingEntrancePosition = (
  building: Readonly<BorealisTownBuildingLot>,
  clearanceMetres = 1.25,
): Readonly<{ x: number; z: number; heading: number }> => {
  const front = borealisBuildingFrontVector(building.front);
  const facadeHalfExtent = Math.abs(front.x) > 0
    ? building.width * 0.5
    : building.depth * 0.5;
  return {
    x: building.x + front.x * (facadeHalfExtent + clearanceMetres),
    z: building.z + front.z * (facadeHalfExtent + clearanceMetres),
    heading: Math.atan2(-front.x, -front.z),
  };
};

