export interface WinterWorldRoute {
  readonly id: string;
  readonly width: number;
  /** Maximum reduction in the untouched snow baseline at the route centre. */
  readonly snowDepression: number;
  readonly points: readonly Readonly<{ x: number; z: number }>[];
}

export interface WinterWorldRouteSaveData {
  readonly version: 1;
  readonly routes: readonly WinterWorldRoute[];
}

export const WINTER_WORLD_ROUTES: readonly WinterWorldRoute[] = [
  {
    id: 'old-raven-road',
    width: 0.92,
    snowDepression: 0.085,
    points: [
      { x: -826, z: -226 },
      { x: -837, z: -216 },
      { x: -847, z: -202 },
      { x: -857, z: -184 },
      { x: -850, z: -167 },
      { x: -837, z: -154 },
    ],
  },
  {
    id: 'creek-keepers-way',
    width: 0.76,
    snowDepression: 0.07,
    points: [
      { x: -826, z: -226 },
      { x: -813, z: -217 },
      { x: -800, z: -207 },
      // Authored bridge centre. Keeping route geometry independent from the
      // biome module lets the biome use this same route mask to clear trees.
      { x: -787.655, z: -199 },
      { x: -781, z: -185 },
      { x: -771, z: -170 },
    ],
  },
];

const cloneRoute = (route: Readonly<WinterWorldRoute>): WinterWorldRoute => ({
  id: route.id,
  width: route.width,
  snowDepression: route.snowDepression,
  points: route.points.map((point) => ({ x: point.x, z: point.z })),
});

const normalizeRoutes = (
  routes: readonly Readonly<WinterWorldRoute>[],
): WinterWorldRoute[] => {
  const usedIds = new Set<string>();
  return routes.flatMap((route, routeIndex) => {
    const points = route.points
      .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.z))
      .slice(0, 512)
      .map((point) => ({
        x: Math.max(-1_000_000, Math.min(1_000_000, point.x)),
        z: Math.max(-1_000_000, Math.min(1_000_000, point.z)),
      }));
    if (points.length < 2) return [];
    const stem = String(route.id || `winter-route-${routeIndex + 1}`)
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9-]+/g, '-')
      .replace(/^-+|-+$/g, '') || `winter-route-${routeIndex + 1}`;
    let id = stem;
    let suffix = 2;
    while (usedIds.has(id)) id = `${stem}-${suffix++}`;
    usedIds.add(id);
    return [{
      id,
      width: Math.max(0.35, Math.min(32, Number(route.width) || 1)),
      snowDepression: Math.max(
        0,
        Math.min(0.8, Number(route.snowDepression) || 0),
      ),
      points,
    }];
  });
};

let activeRoutes: WinterWorldRoute[] = WINTER_WORLD_ROUTES.map(cloneRoute);
const routeListeners = new Set<() => void>();

interface RouteBounds {
  readonly route: WinterWorldRoute;
  readonly minX: number;
  readonly maxX: number;
  readonly minZ: number;
  readonly maxZ: number;
}

const ROUTE_FEATHER = 0.34;

const createRouteBounds = (
  routes: readonly WinterWorldRoute[],
): readonly RouteBounds[] => routes.map((route) => {
  const xs = route.points.map((point) => point.x);
  const zs = route.points.map((point) => point.z);
  const margin = route.width * 0.5 + ROUTE_FEATHER;
  return {
    route,
    minX: Math.min(...xs) - margin,
    maxX: Math.max(...xs) + margin,
    minZ: Math.min(...zs) - margin,
    maxZ: Math.max(...zs) + margin,
  };
});

let routeBounds: readonly RouteBounds[] = createRouteBounds(activeRoutes);

/** Current authored route layer. Callers receive clones so edits stay atomic. */
export const listWinterWorldRoutes = (): readonly WinterWorldRoute[] =>
  activeRoutes.map(cloneRoute);

export const exportWinterWorldRoutes = (): WinterWorldRouteSaveData => ({
  version: 1,
  routes: listWinterWorldRoutes(),
});

export const replaceWinterWorldRoutes = (
  routes: readonly Readonly<WinterWorldRoute>[],
  notifyListeners = true,
): boolean => {
  const normalized = normalizeRoutes(routes);
  // An explicit empty layer is valid for a new World Builder draft. Invalid
  // individual routes are still discarded by normalizeRoutes.
  if (routes.length > 0 && normalized.length === 0) return false;
  activeRoutes = normalized;
  routeBounds = createRouteBounds(activeRoutes);
  if (notifyListeners) {
    for (const listener of routeListeners) listener();
  }
  return true;
};

export const importWinterWorldRoutes = (
  saved?: Readonly<WinterWorldRouteSaveData>,
): boolean => replaceWinterWorldRoutes(
  saved?.version === 1 && Array.isArray(saved.routes)
    ? saved.routes
    : WINTER_WORLD_ROUTES,
);

export const addWinterWorldRouteListener = (listener: () => void): (() => void) => {
  routeListeners.add(listener);
  return () => routeListeners.delete(listener);
};

export const winterWorldRouteBounds = (
  padding = 0,
): Readonly<{ minX: number; maxX: number; minZ: number; maxZ: number }> =>
  routeBounds.length === 0
    ? { minX: -padding, maxX: padding, minZ: -padding, maxZ: padding }
    : {
        minX: Math.min(...routeBounds.map((bounds) => bounds.minX)) - padding,
        maxX: Math.max(...routeBounds.map((bounds) => bounds.maxX)) + padding,
        minZ: Math.min(...routeBounds.map((bounds) => bounds.minZ)) - padding,
        maxZ: Math.max(...routeBounds.map((bounds) => bounds.maxZ)) + padding,
      };

const distanceToSegment = (
  x: number,
  z: number,
  from: Readonly<{ x: number; z: number }>,
  to: Readonly<{ x: number; z: number }>,
): number => {
  const deltaX = to.x - from.x;
  const deltaZ = to.z - from.z;
  const lengthSquared = deltaX * deltaX + deltaZ * deltaZ;
  if (lengthSquared <= 0.000001) return Math.hypot(x - from.x, z - from.z);
  const t = Math.max(0, Math.min(1,
    ((x - from.x) * deltaX + (z - from.z) * deltaZ) / lengthSquared,
  ));
  return Math.hypot(
    x - (from.x + deltaX * t),
    z - (from.z + deltaZ * t),
  );
};

/**
 * Returns the deterministic compaction/depression made by an old route.
 *
 * The route is intentionally not a visible snow decal. Its centre is only a
 * little lower than untouched snow and the shoulders feather into the field,
 * so fresh snowfall and player deformation remain the visible authority.
 */
export const winterRouteSnowDepressionAt = (x: number, z: number): number => {
  let depression = 0;
  for (const bounds of routeBounds) {
    if (
      x < bounds.minX || x > bounds.maxX ||
      z < bounds.minZ || z > bounds.maxZ
    ) continue;
    const { route } = bounds;
    let distance = Number.POSITIVE_INFINITY;
    for (let index = 0; index < route.points.length - 1; index += 1) {
      distance = Math.min(distance, distanceToSegment(
        x,
        z,
        route.points[index]!,
        route.points[index + 1]!,
      ));
    }
    const innerRadius = route.width * 0.34;
    const outerRadius = route.width * 0.5 + ROUTE_FEATHER;
    if (distance >= outerRadius) continue;
    const normalized = Math.max(0, Math.min(1,
      (outerRadius - distance) / Math.max(0.001, outerRadius - innerRadius),
    ));
    const feather = normalized * normalized * (3 - 2 * normalized);
    depression = Math.max(depression, route.snowDepression * feather);
  }
  return depression;
};

/** True inside the physical route corridor plus optional prop clearance. */
export const isWinterWorldRouteAt = (
  x: number,
  z: number,
  padding = 0,
): boolean => {
  for (const bounds of routeBounds) {
    if (
      x < bounds.minX - padding || x > bounds.maxX + padding ||
      z < bounds.minZ - padding || z > bounds.maxZ + padding
    ) continue;
    const { route } = bounds;
    for (let index = 0; index < route.points.length - 1; index += 1) {
      if (distanceToSegment(
        x,
        z,
        route.points[index]!,
        route.points[index + 1]!,
      ) <= route.width * 0.5 + padding) return true;
    }
  }
  return false;
};
