import { clamp, smoothstep } from '../utils/math';

export const ICE_LIFECYCLE_TUNING = Object.freeze({
  disturbanceGraceSeconds: 180,
  graceRampSeconds: 120,
  surfaceSkimDelaySeconds: 600,
  surfaceSkimRampSeconds: 300,
  thermalMemoryMinimum: 0.02,
  mechanicalSolidOpenness: 0.72,
  thermalSolidOpenness: 0.4,
});

export interface ThermalRefreezeInput {
  openness: number;
  channelMemory: number;
  disturbanceAgeSeconds: number;
  edgeSupport: number;
  environmentMultiplier: number;
  baseRatePerSecond: number;
  deltaSeconds: number;
  spatialVariation?: number;
}

export interface ThermalRefreezeResult {
  amount: number;
  graceProgress: number;
  edgeGrowth: number;
  skimProgress: number;
}

export interface IceLifecyclePresentation {
  filmCoverage: number;
  visualThickness: number;
  channelMemory: number;
}

export interface VesselDisturbanceInput {
  disturbanceAgeSeconds: number;
  channelMemory: number;
  openness: number;
  impactSpeed: number;
  compression: number;
  localWeight: number;
}

export const isThermalRefreezeCell = (
  channelMemory: number,
): boolean =>
  channelMemory >= ICE_LIFECYCLE_TUNING.thermalMemoryMinimum;

export const isThermallyCoherentIce = (
  openness: number,
  channelMemory: number,
): boolean =>
  openness <
  (
    isThermalRefreezeCell(channelMemory)
      ? ICE_LIFECYCLE_TUNING.thermalSolidOpenness
      : ICE_LIFECYCLE_TUNING.mechanicalSolidOpenness
  );

export const isFormingChannelIce = (
  openness: number,
  channelMemory: number,
): boolean =>
  isThermalRefreezeCell(channelMemory) &&
  !isThermallyCoherentIce(openness, channelMemory);

export const calculateRouteNavigabilityOpenness = (
  openness: number,
  channelMemory: number,
): number => {
  const physicalOpenness = clamp(openness, 0, 1);
  if (!isFormingChannelIce(physicalOpenness, channelMemory)) {
    return physicalOpenness;
  }
  return Math.max(
    physicalOpenness,
    ICE_LIFECYCLE_TUNING.mechanicalSolidOpenness,
  );
};

export const calculateRouteRefreezePressure = (
  openness: number,
  channelMemory: number,
): number => {
  if (
    !isThermalRefreezeCell(channelMemory) ||
    isFormingChannelIce(openness, channelMemory)
  ) {
    return 0;
  }
  return Math.sqrt(
    clamp(channelMemory, 0, 1) *
      (1 - clamp(openness, 0, 1)),
  );
};

export const calculateEdgeSupport = (
  openness: number,
  neighborOpenness: ArrayLike<number>,
): number => {
  if (neighborOpenness.length === 0) return 0;
  let support = 0;
  let totalWeight = 0;
  for (let index = 0; index < neighborOpenness.length; index += 1) {
    const weight = index < 4 ? 1 : Math.SQRT1_2;
    const neighborCoverage =
      1 - clamp(neighborOpenness[index] ?? 1, 0, 1);
    const stableCoverage = smoothstep(
      0.22,
      0.76,
      neighborCoverage,
    );
    const inwardBias = smoothstep(
      0.02,
      0.52,
      openness - (neighborOpenness[index] ?? 1),
    );
    support += stableCoverage * (0.45 + inwardBias * 0.55) * weight;
    totalWeight += weight;
  }
  return clamp(support / Math.max(0.0001, totalWeight), 0, 1);
};

export const calculateThermalRefreeze = (
  input: Readonly<ThermalRefreezeInput>,
): ThermalRefreezeResult => {
  if (
    !isThermalRefreezeCell(input.channelMemory) ||
    input.deltaSeconds <= 0 ||
    input.baseRatePerSecond <= 0
  ) {
    return {
      amount: 0,
      graceProgress: 0,
      edgeGrowth: 0,
      skimProgress: 0,
    };
  }

  const graceProgress = smoothstep(
    ICE_LIFECYCLE_TUNING.disturbanceGraceSeconds,
    ICE_LIFECYCLE_TUNING.disturbanceGraceSeconds +
      ICE_LIFECYCLE_TUNING.graceRampSeconds,
    input.disturbanceAgeSeconds,
  );
  const skimProgress = smoothstep(
    ICE_LIFECYCLE_TUNING.surfaceSkimDelaySeconds,
    ICE_LIFECYCLE_TUNING.surfaceSkimDelaySeconds +
      ICE_LIFECYCLE_TUNING.surfaceSkimRampSeconds,
    input.disturbanceAgeSeconds,
  );
  const edgeSupport = clamp(input.edgeSupport, 0, 1);
  const edgeGrowth =
    edgeSupport * (0.58 + edgeSupport * 1.72);
  const centreGrowth =
    0.012 +
    skimProgress * (0.46 - edgeSupport * 0.12);
  const variation =
    1 + clamp(input.spatialVariation ?? 0, -1, 1) * 0.08;
  const opennessResponse =
    0.58 + clamp(input.openness, 0, 1) * 0.42;
  const amount =
    input.baseRatePerSecond *
    Math.max(0, input.environmentMultiplier) *
    graceProgress *
    (edgeGrowth + centreGrowth) *
    variation *
    opennessResponse *
    input.deltaSeconds;

  return {
    amount: Math.max(0, amount),
    graceProgress,
    edgeGrowth,
    skimProgress,
  };
};

export const getVisualThicknessBand = (
  thickness: number,
): number => {
  const value = clamp(thickness, 0, 1);
  if (value < 0.58) return 0;
  if (value < 0.76) return 1;
  return 2;
};

export const calculateLifecyclePresentation = (
  openness: number,
  channelMemory: number,
  disturbanceAgeSeconds: number,
  visualThickness: number,
): IceLifecyclePresentation => {
  if (!isThermalRefreezeCell(channelMemory)) {
    return {
      filmCoverage: 0,
      visualThickness: clamp(visualThickness, 0, 1),
      channelMemory: 0,
    };
  }
  const graceProgress = smoothstep(
    ICE_LIFECYCLE_TUNING.disturbanceGraceSeconds,
    ICE_LIFECYCLE_TUNING.disturbanceGraceSeconds +
      ICE_LIFECYCLE_TUNING.graceRampSeconds,
    disturbanceAgeSeconds,
  );
  const closure =
    1 -
    smoothstep(
      ICE_LIFECYCLE_TUNING.thermalSolidOpenness,
      0.97,
      clamp(openness, 0, 1),
    );
  return {
    filmCoverage: clamp(closure * graceProgress, 0, 1),
    visualThickness: clamp(visualThickness, 0, 1),
    channelMemory: clamp(channelMemory, 0, 1),
  };
};

export const calculateDisturbanceAgeAfterPassage = (
  input: Readonly<VesselDisturbanceInput>,
): number => {
  const age = Math.max(0, input.disturbanceAgeSeconds);
  if (
    !isThermalRefreezeCell(input.channelMemory) ||
    input.openness <= ICE_LIFECYCLE_TUNING.thermalSolidOpenness
  ) {
    return age;
  }
  const disturbance = clamp(
    (
      Math.max(0, input.impactSpeed) * 0.48 +
      Math.max(0, input.compression) * 0.9
    ) * clamp(input.localWeight, 0, 1),
    0,
    1,
  );
  return age * (1 - disturbance * 0.9);
};

export const measureContiguousChannelWidth = (
  openness: readonly number[],
  cellSize: number,
  minimumOpenness = 0.64,
): number => {
  let longestRun = 0;
  let currentRun = 0;
  for (const value of openness) {
    if (value >= minimumOpenness) {
      currentRun += 1;
      longestRun = Math.max(longestRun, currentRun);
    } else {
      currentRun = 0;
    }
  }
  return longestRun * Math.max(0, cellSize);
};
