import { Ray, Vector3 } from 'three';

export interface CombatPoint { readonly x: number; readonly y: number; readonly z: number }
/** Feet-anchored upright capsule. Independent of mesh, animation and camera.
 * The same contract serves the human, husks and future weapon sweeps. */
export interface CombatBody extends CombatPoint {
  readonly id: string;
  readonly team: 'PLAYER' | 'HOSTILE';
  readonly radius: number;
  readonly height: number;
}
export const HUMAN_HITBOX = { radius: .28, height: 1.7 } as const;
export const HUSK_HITBOX = { radius: .32, height: 1.9 } as const;

export function sphereHitsBody(point: CombatPoint, radius: number, body: CombatBody): boolean {
  const y = Math.max(body.y + body.radius, Math.min(body.y + body.height - body.radius, point.y));
  return (point.x - body.x) ** 2 + (point.y - y) ** 2 + (point.z - body.z) ** 2 <= (radius + body.radius) ** 2;
}

/** Exact first intersection, including end caps and origins inside the body.
 * Ray directions must be normalized (Three.js Ray contract). */
export function rayBodyDistance(ray: Readonly<Ray>, body: CombatBody): number | undefined {
  if (sphereHitsBody(ray.origin, 0, body)) return 0;
  const ox = ray.origin.x - body.x, oz = ray.origin.z - body.z;
  const dx = ray.direction.x, dy = ray.direction.y, dz = ray.direction.z;
  const bottom = body.y + body.radius, top = body.y + body.height - body.radius;
  let best = Infinity;
  const a = dx * dx + dz * dz, b = ox * dx + oz * dz;
  const discriminant = b * b - a * (ox * ox + oz * oz - body.radius ** 2);
  if (a > 1e-12 && discriminant >= 0) {
    for (const t of [(-b - Math.sqrt(discriminant)) / a, (-b + Math.sqrt(discriminant)) / a]) {
      const y = ray.origin.y + t * dy;
      if (t >= 0 && y >= bottom && y <= top) best = Math.min(best, t);
    }
  }
  for (const cy of [bottom, top]) {
    const oy = ray.origin.y - cy;
    const dot = ox * dx + oy * dy + oz * dz;
    const d = dot * dot - (ox * ox + oy * oy + oz * oz - body.radius ** 2);
    if (d < 0) continue;
    for (const t of [-dot - Math.sqrt(d), -dot + Math.sqrt(d)]) {
      const y = ray.origin.y + t * dy;
      if (t >= 0 && (cy === bottom ? y <= bottom : y >= top)) best = Math.min(best, t);
    }
  }
  return Number.isFinite(best) ? best : undefined;
}

export function nearestCombatHit(ray: Readonly<Ray>, bodies: readonly CombatBody[],
  attacker: CombatBody, reach: number, blocked: (from: CombatPoint, to: CombatPoint) => boolean) {
  let nearest: { body: CombatBody; point: Vector3; distance: number } | undefined;
  const origin = { x: attacker.x, y: attacker.y + attacker.height * .6, z: attacker.z };
  for (const body of bodies) {
    if (body.id === attacker.id || body.team === attacker.team) continue;
    const distance = rayBodyDistance(ray, body);
    if (distance === undefined || (nearest && distance >= nearest.distance)) continue;
    const point = ray.at(distance, new Vector3());
    if (Math.hypot(point.x - origin.x, point.y - origin.y, point.z - origin.z) > reach) continue;
    if (blocked(ray.origin, point) || blocked(origin, point)) continue;
    nearest = { body, point, distance };
  }
  return nearest;
}

/** Future sword/axe arc segments can sweep a small sphere without tunnelling. */
export function sweepHitsBody(from: CombatPoint, to: CombatPoint, radius: number, body: CombatBody): boolean {
  const expanded = { ...body, radius: body.radius + radius, y: body.y - radius, height: body.height + radius * 2 };
  const delta = new Vector3(to.x - from.x, to.y - from.y, to.z - from.z);
  const length = delta.length();
  if (length < 1e-9) return sphereHitsBody(from, radius, body);
  const distance = rayBodyDistance(new Ray(new Vector3(from.x, from.y, from.z), delta.divideScalar(length)), expanded);
  return distance !== undefined && distance <= length;
}
