import type { SettlementBuildingSystem } from './SettlementBuildingSystem';
import type {
  SettlementGoodAmount,
  SettlementTrainDefinition,
  SettlementTrainSaveData,
  SettlementTrainStatus,
  SettlementTrainView,
} from './SettlementTypes';
import type { SettlementWarehouse } from './SettlementWarehouse';

interface MutableTrainState {
  status: SettlementTrainStatus;
  contributions: Array<{ goodId: string; quantity: number }>;
  dispatchedAt?: number;
  returnStartedAt?: number;
  arrivesAt?: number;
  stationmasterArrived: boolean;
  completedTrips: number;
  revision: number;
}

const statuses = new Set<SettlementTrainStatus>([
  'UNAVAILABLE',
  'AT_STATION',
  'LOADING',
  'TRAVELLING',
  'RETURNING',
]);

/**
 * Timestamped near/far train loop. Only the short station corridor needs a
 * physical train; the journey itself is deterministic world state.
 */
export class SettlementTrainSystem {
  private readonly state: MutableTrainState = {
    status: 'UNAVAILABLE',
    contributions: [],
    stationmasterArrived: false,
    completedTrips: 0,
    revision: 0,
  };

  public constructor(
    private readonly definition: Readonly<SettlementTrainDefinition>,
    private readonly buildings: SettlementBuildingSystem,
    private readonly warehouse: SettlementWarehouse,
    saved?: Readonly<SettlementTrainSaveData>,
  ) {
    this.importState(saved);
  }

  public remainingManifestGoods(): readonly SettlementGoodAmount[] {
    return this.definition.manifestGoods.flatMap((required) => {
      const contributed = this.state.contributions.find(
        (entry) => entry.goodId === required.goodId,
      )?.quantity ?? 0;
      const quantity = Math.max(0, required.quantity - contributed);
      return quantity > 0 ? [{ goodId: required.goodId, quantity }] : [];
    });
  }

  public contribute(goodId: string, requestedQuantity: number): number {
    if (
      (this.state.status !== 'AT_STATION' && this.state.status !== 'LOADING') ||
      !Number.isSafeInteger(requestedQuantity) ||
      requestedQuantity <= 0
    ) return 0;
    const capacity = this.remainingManifestGoods().find(
      (entry) => entry.goodId === goodId,
    )?.quantity ?? 0;
    const quantity = Math.min(
      capacity,
      requestedQuantity,
      this.warehouse.getQuantity(goodId),
    );
    if (quantity <= 0 || !this.warehouse.apply([{ goodId, quantity }], -1)) {
      return 0;
    }
    const existing = this.state.contributions.find(
      (entry) => entry.goodId === goodId,
    );
    if (existing) existing.quantity += quantity;
    else this.state.contributions.push({ goodId, quantity });
    this.state.contributions.sort((left, right) =>
      left.goodId.localeCompare(right.goodId));
    this.state.status = 'LOADING';
    this.state.revision += 1;
    return quantity;
  }

  public dispatch(simulationTime: number): boolean {
    if (
      (this.state.status !== 'AT_STATION' && this.state.status !== 'LOADING') ||
      this.remainingManifestGoods().length > 0
    ) return false;
    const now = Math.max(0, simulationTime);
    this.state.status = 'TRAVELLING';
    this.state.dispatchedAt = now;
    this.state.returnStartedAt = now + this.definition.outboundDurationSeconds;
    this.state.arrivesAt = this.state.returnStartedAt +
      this.definition.returnDurationSeconds;
    this.state.revision += 1;
    return true;
  }

  public update(simulationTime: number): boolean {
    let changed = false;
    if (
      this.state.status === 'UNAVAILABLE' &&
      this.buildings.getView(this.definition.stationBuildingId)?.workState ===
        'COMPLETE'
    ) {
      this.state.status = 'AT_STATION';
      this.state.revision += 1;
      changed = true;
    }
    if (
      this.state.status === 'TRAVELLING' &&
      simulationTime >= (this.state.returnStartedAt ?? Number.POSITIVE_INFINITY)
    ) {
      this.state.status = 'RETURNING';
      this.state.revision += 1;
      changed = true;
    }
    if (
      this.state.status === 'RETURNING' &&
      simulationTime >= (this.state.arrivesAt ?? Number.POSITIVE_INFINITY) &&
      this.warehouse.canApply(this.definition.returnGoods, 1) &&
      this.warehouse.apply(this.definition.returnGoods, 1)
    ) {
      this.state.status = 'AT_STATION';
      this.state.contributions = [];
      delete this.state.dispatchedAt;
      delete this.state.returnStartedAt;
      delete this.state.arrivesAt;
      this.state.completedTrips += 1;
      this.state.stationmasterArrived = true;
      this.state.revision += 1;
      changed = true;
    }
    return changed;
  }

  public snapshot(simulationTime: number): SettlementTrainView {
    let normalizedJourneyProgress = 0;
    if (
      this.state.dispatchedAt !== undefined &&
      this.state.arrivesAt !== undefined &&
      this.state.arrivesAt > this.state.dispatchedAt
    ) {
      normalizedJourneyProgress = Math.max(0, Math.min(1,
        (simulationTime - this.state.dispatchedAt) /
          (this.state.arrivesAt - this.state.dispatchedAt)));
    }
    return {
      trainId: this.definition.id,
      displayName: this.definition.displayName,
      manifestId: this.definition.manifestId,
      manifestDisplayName: this.definition.manifestDisplayName,
      status: this.state.status,
      contributions: this.state.contributions.map((entry) => ({ ...entry })),
      remainingManifestGoods: this.remainingManifestGoods(),
      returnGoods: this.definition.returnGoods.map((entry) => ({ ...entry })),
      ...(this.state.dispatchedAt === undefined
        ? {}
        : { dispatchedAt: this.state.dispatchedAt }),
      ...(this.state.returnStartedAt === undefined
        ? {}
        : { returnStartedAt: this.state.returnStartedAt }),
      ...(this.state.arrivesAt === undefined
        ? {}
        : { arrivesAt: this.state.arrivesAt }),
      normalizedJourneyProgress,
      stationmasterArrived: this.state.stationmasterArrived,
      completedTrips: this.state.completedTrips,
      revision: this.state.revision,
    };
  }

  public exportState(): SettlementTrainSaveData {
    return {
      version: 1,
      status: this.state.status,
      contributions: this.state.contributions.map((entry) => ({ ...entry })),
      ...(this.state.dispatchedAt === undefined
        ? {}
        : { dispatchedAt: this.state.dispatchedAt }),
      ...(this.state.returnStartedAt === undefined
        ? {}
        : { returnStartedAt: this.state.returnStartedAt }),
      ...(this.state.arrivesAt === undefined
        ? {}
        : { arrivesAt: this.state.arrivesAt }),
      stationmasterArrived: this.state.stationmasterArrived,
      completedTrips: this.state.completedTrips,
      revision: this.state.revision,
    };
  }

  private importState(saved?: Readonly<SettlementTrainSaveData>): void {
    if (!saved || saved.version !== 1 || !statuses.has(saved.status)) return;
    this.state.status = saved.status;
    this.state.contributions = this.definition.manifestGoods.flatMap((required) => {
      const quantity = saved.contributions?.find(
        (entry) => entry.goodId === required.goodId,
      )?.quantity;
      return Number.isSafeInteger(quantity) && quantity! > 0
        ? [{ goodId: required.goodId, quantity: Math.min(required.quantity, quantity!) }]
        : [];
    });
    this.state.stationmasterArrived = saved.stationmasterArrived === true;
    this.state.completedTrips = Number.isSafeInteger(saved.completedTrips) &&
      saved.completedTrips >= 0 ? saved.completedTrips : 0;
    this.state.revision = Number.isSafeInteger(saved.revision) &&
      saved.revision >= 0 ? saved.revision : 0;
    if (
      (saved.status === 'TRAVELLING' || saved.status === 'RETURNING') &&
      Number.isFinite(saved.dispatchedAt) &&
      Number.isFinite(saved.returnStartedAt) &&
      Number.isFinite(saved.arrivesAt) &&
      saved.dispatchedAt! <= saved.returnStartedAt! &&
      saved.returnStartedAt! <= saved.arrivesAt!
    ) {
      this.state.dispatchedAt = Math.max(0, saved.dispatchedAt!);
      this.state.returnStartedAt = saved.returnStartedAt!;
      this.state.arrivesAt = saved.arrivesAt!;
    } else if (saved.status === 'TRAVELLING' || saved.status === 'RETURNING') {
      this.state.status = 'AT_STATION';
      this.state.contributions = [];
    }
  }
}
