export const WORLD_REPLICATION_FORMAT_VERSION = 4;

export type WorldInterestSubscriptionSource =
  | 'MAP'
  | 'QUEST'
  | 'INCIDENT'
  | 'RADIO'
  | 'EXPLICIT_OBSERVATION';

export type SharedWeatherKind =
  | 'clear'
  | 'overcast'
  | 'light-snow'
  | 'fog'
  | 'strong-wind'
  | 'snowstorm';

export interface SharedWorldEnvironmentState {
  readonly revision: number;
  readonly worldTimeSeconds: number;
  readonly timeScale: number;
  readonly sessionPaused: boolean;
  readonly weather: Readonly<{
    kind: SharedWeatherKind;
    windMultiplier: number;
    fogDensity: number;
    snowIntensity: number;
    refreezeMultiplier: number;
  }>;
  readonly forecast: readonly Readonly<{
    startsAtWorldTimeSeconds: number;
    kind: SharedWeatherKind;
    snowIntensity: number;
  }>[];
  readonly activeForecastStartedAtWorldTimeSeconds?: number;
}

/** Explicit ownership policy for data which must not accidentally become shared. */
export interface SharedWorldScopePolicy {
  readonly questProgress: 'SHARED';
  readonly questContributors: 'ATTRIBUTED_PER_EVENT';
  readonly logicalRadioBroadcasts: 'SHARED';
  readonly radioReceiverTuning: 'PERSONAL';
  readonly radioMuteAndReadState: 'PERSONAL';
  readonly localMenuPausesWorld: false;
  readonly localCinematicsPauseWorld: false;
  readonly cutsceneInputLock: 'PERSONAL';
  readonly dialogueDefault: 'PERSONAL';
  readonly dialogueSharedSceneOptIn: true;
  readonly mapDiscoveries: 'SHARED';
  readonly personalMapNotes: 'PERSONAL';
}

export interface SharedWorldDevUnlockState {
  readonly enabled: boolean;
  readonly allVehicles: boolean;
  readonly allTools: boolean;
  readonly creditGrantAmount: number;
  readonly revision: number;
}

/**
 * Position-free NPC state used outside the observer's simulation bubble.
 * ETA is an absolute authority-world time, so it does not churn every tick.
 */
export interface ReplicatedNpcTravelSummary {
  readonly npcId: string;
  readonly displayName: string;
  readonly status: TravelAgentState['status'];
  readonly tripSequence: number;
  readonly stateChangedAt: number;
  readonly currentLocationId?: string;
  readonly currentSegmentId?: string;
  readonly destinationLocationId?: string;
  readonly tripId?: string;
  readonly estimatedArrivalAtWorldTimeSeconds?: number;
  readonly incidentId?: string;
}

export interface ReplicatedPersonalRadioState {
  readonly revision: number;
  readonly tuning: RadioTuningSnapshot;
  readonly messages: readonly RadioMessage[];
  readonly unreadCount: number;
  readonly mutedCategories: readonly RadioCategory[];
  readonly acknowledgementPolicy: 'PERSONAL';
}

export interface ReplicatedWorldInterestSubscription {
  readonly source: WorldInterestSubscriptionSource;
  readonly sourceId: string;
  readonly chunks: readonly WorldChunkAddress[];
  readonly entityIds: readonly NetworkEntityId[];
  readonly npcIds: readonly string[];
}

export type ReplicatedMapMarkerSourceKind =
  | 'PLAYER'
  | 'ENTITY'
  | 'NPC'
  | 'PORT'
  | 'POI'
  | 'INCIDENT';

/**
 * A marker is a view of a real domain object. `(sourceKind, sourceId)` is its
 * identity; deliberately there is no independent marker ID namespace.
 */
export interface ReplicatedMapMarker {
  readonly sourceKind: ReplicatedMapMarkerSourceKind;
  readonly sourceId: string;
  readonly displayName: string;
  readonly worldPosition: GlobalPosition;
  readonly revision: number;
  readonly visibility:
    | 'SELF'
    | 'TEAMMATE'
    | 'SUBSCRIBED'
    | 'DISCOVERED'
    | 'INCIDENT';
  /** Current entity used to position a player marker, not a marker identity. */
  readonly sourceEntityId?: NetworkEntityId;
  readonly state?: string;
}

export interface ReplicatedMapSubscriptionState {
  readonly revision: number;
  readonly open: boolean;
  readonly worldPartitionId: string;
  readonly requestedMapChunks: readonly WorldChunkAddress[];
  /** The exact authority interest records also consumed by world streaming. */
  readonly activeSubscriptions: readonly ReplicatedWorldInterestSubscription[];
  readonly markers: readonly ReplicatedMapMarker[];
}

export type CooperativeVehicleMode =
  | 'NO_PERMISSION'
  | 'WAITING_FOR_WEATHER'
  | 'WAITING_FOR_VEHICLE'
  | 'WORKING'
  | 'RETURNING'
  | 'YIELDING'
  | 'PARKED';

export interface ReplicatedCooperativeVehicleState {
  readonly policyId: string;
  readonly npcId: string;
  readonly npcEntityId: NetworkEntityId;
  readonly vehicleEntityId: NetworkEntityId;
  readonly routeId: string;
  readonly revision: number;
  readonly permissionGranted: boolean;
  readonly workRequired: boolean;
  readonly mode: CooperativeVehicleMode;
  readonly reason: string;
  readonly controlLeaseRevision: number;
  readonly updatedAtTick: ServerTick;
  readonly reservedForPlayerId?: PlayerId;
}

export interface SharedWorldCompactSnapshot {
  /** Monotonic revision of this one client's projected replication stream. */
  readonly revision: number;
  /** Canonical room-world revision represented by this projection. */
  readonly authorityRevision: number;
  readonly simulationTime: number;
  readonly eventCursor: number;
  readonly routes: readonly RouteState[];
  readonly ports: readonly PortState[];
  readonly portClearances: readonly PortClearanceState[];
  readonly missions: readonly MissionRuntimeState[];
  readonly settlement: SettlementSnapshot;
  readonly outcomes: readonly WorldOutcomeRuntimeState[];
  readonly merchantShips: readonly MerchantShipRuntimeState[];
  readonly economy: Readonly<{
    money: number;
    upgrades: UpgradeInventorySaveData;
    playerShipCapabilities?: ComputedShipCapabilities;
  }>;
  readonly serviceViews: Readonly<{
    radioTowerRepairs: readonly RadioTowerRepairView[];
    lighthouseRestorations: readonly LighthouseRestorationView[];
    portPresentations: readonly PortPresentationState[];
  }>;
  readonly radio: Readonly<{
    /** One canonical set; reception and presentation are evaluated per player. */
    logicalBroadcasts: readonly LogicalRadioBroadcast[];
    receiver: ReplicatedPersonalRadioState;
  }>;
  readonly dialogue: ReplicatedDialogueState;
  readonly map: Readonly<{
    discoveredPortIds: readonly string[];
    discoveredPoiIds: readonly string[];
    teammatePositionPolicy: 'SUBSCRIPTION_WHEN_MAP_OPEN';
    subscription: ReplicatedMapSubscriptionState;
  }>;
  readonly emergence: Readonly<{
    roads: readonly RoadConditionState[];
    /** Position-free state for all NPCs, including those currently nearby. */
    travel: readonly ReplicatedNpcTravelSummary[];
    npcs: readonly NpcRuntimeState[];
    services: readonly ServiceRuntimeState[];
    incidents: readonly WorldIncidentState[];
    storyQuests: readonly StoryQuestRuntimeState[];
    /** Low-frequency policy/lease state; vehicle pose stays in entity snapshots. */
    cooperativeVehicles: readonly ReplicatedCooperativeVehicleState[];
    /** Exact pose state only for NPCs in this observer's near bubble. */
    npcPresentation: readonly NpcPresentationState[];
  }>;
  readonly environment: SharedWorldEnvironmentState;
  readonly scopePolicy: SharedWorldScopePolicy;
  readonly devUnlocks: SharedWorldDevUnlockState;
}

export interface ReplicatedWorldDomainEvent {
  readonly cursor: number;
  readonly serverTick: ServerTick;
  readonly contributorPlayerIds: readonly PlayerId[];
  readonly event: WorldDomainEvent;
}

export interface WorldStateBaselinePayload {
  readonly version: 1;
  readonly kind: 'WORLD_STATE_BASELINE';
  readonly formatVersion: number;
  readonly worldDatasetHash: string;
  readonly serverTick: ServerTick;
  readonly snapshot: SharedWorldCompactSnapshot;
}

export interface WorldStateDeltaPayload {
  readonly version: 1;
  readonly kind: 'WORLD_STATE_DELTA';
  readonly baseRevision: number;
  readonly revision: number;
  readonly serverTick: ServerTick;
  /** V1 replaces one compact DTO atomically; later formats may field-diff it. */
  readonly snapshot: SharedWorldCompactSnapshot;
}

export interface WorldDomainEventBatchPayload {
  readonly version: 1;
  readonly kind: 'WORLD_DOMAIN_EVENT_BATCH';
  readonly firstCursor: number;
  readonly lastCursor: number;
  readonly serverTick: ServerTick;
  readonly events: readonly ReplicatedWorldDomainEvent[];
}

export interface WorldEventResyncRequestPayload {
  readonly version: 1;
  readonly kind: 'WORLD_EVENT_RESYNC_REQUEST';
  readonly afterCursor: number;
  readonly observedRevision: number;
  readonly scope: 'EVENTS' | 'FULL';
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const isNonNegativeInteger = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

const isBoundedString = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' && value.length > 0 && value.length <= maximum;

const INTEREST_SOURCES = new Set<WorldInterestSubscriptionSource>([
  'MAP',
  'QUEST',
  'INCIDENT',
  'RADIO',
  'EXPLICIT_OBSERVATION',
]);
const MAP_MARKER_SOURCES = new Set<ReplicatedMapMarkerSourceKind>([
  'PLAYER',
  'ENTITY',
  'NPC',
  'PORT',
  'POI',
  'INCIDENT',
]);
const MAP_MARKER_VISIBILITIES = new Set<ReplicatedMapMarker['visibility']>([
  'SELF',
  'TEAMMATE',
  'SUBSCRIBED',
  'DISCOVERED',
  'INCIDENT',
]);
const DIALOGUE_SCOPES = new Set<DialogueScope>([
  'PERSONAL',
  'PARTY_SHARED',
  'WORLD_SHARED',
]);
const COOPERATIVE_VEHICLE_MODES = new Set<CooperativeVehicleMode>([
  'NO_PERMISSION',
  'WAITING_FOR_WEATHER',
  'WAITING_FOR_VEHICLE',
  'WORKING',
  'RETURNING',
  'YIELDING',
  'PARKED',
]);

const isCooperativeVehicleState = (
  input: unknown,
): input is ReplicatedCooperativeVehicleState =>
  isRecord(input) &&
  isBoundedString(input.policyId, 160) &&
  isBoundedString(input.npcId, 160) &&
  isBoundedString(input.npcEntityId, 160) &&
  isBoundedString(input.vehicleEntityId, 160) &&
  isBoundedString(input.routeId, 160) &&
  isNonNegativeInteger(input.revision) &&
  typeof input.permissionGranted === 'boolean' &&
  typeof input.workRequired === 'boolean' &&
  typeof input.mode === 'string' &&
  COOPERATIVE_VEHICLE_MODES.has(input.mode as CooperativeVehicleMode) &&
  isBoundedString(input.reason, 160) &&
  isNonNegativeInteger(input.controlLeaseRevision) &&
  isNonNegativeInteger(input.updatedAtTick) &&
  (input.reservedForPlayerId === undefined ||
    isBoundedString(input.reservedForPlayerId, 160)) &&
  (input.permissionGranted ||
    input.mode === 'NO_PERMISSION' ||
    input.mode === 'RETURNING' ||
    input.mode === 'YIELDING');

const isChunk = (input: unknown): input is WorldChunkAddress =>
  isRecord(input) &&
  typeof input.x === 'number' &&
  typeof input.z === 'number' &&
  Number.isInteger(input.x) &&
  Number.isInteger(input.z) &&
  input.x >= ICEAWAY_TARGET_WORLD_PARTITION.minimumChunk.x &&
  input.z >= ICEAWAY_TARGET_WORLD_PARTITION.minimumChunk.z &&
  input.x < ICEAWAY_TARGET_WORLD_PARTITION.minimumChunk.x +
    ICEAWAY_TARGET_WORLD_PARTITION.chunkColumns &&
  input.z < ICEAWAY_TARGET_WORLD_PARTITION.minimumChunk.z +
    ICEAWAY_TARGET_WORLD_PARTITION.chunkRows;

const isStringArray = (
  input: unknown,
  maximum: number,
): input is string[] => Array.isArray(input) &&
  input.length <= maximum &&
  input.every((value) => isBoundedString(value, 160));

const isInterestSubscription = (
  input: unknown,
): input is ReplicatedWorldInterestSubscription => {
  if (
    !isRecord(input) ||
    typeof input.source !== 'string' ||
    !INTEREST_SOURCES.has(input.source as WorldInterestSubscriptionSource) ||
    !isBoundedString(input.sourceId, 160) ||
    !Array.isArray(input.chunks) ||
    input.chunks.length > 128 ||
    !input.chunks.every(isChunk) ||
    !isStringArray(input.entityIds, 128) ||
    !isStringArray(input.npcIds, 128)
  ) return false;
  return true;
};

const isMapMarker = (input: unknown): input is ReplicatedMapMarker => {
  if (
    !isRecord(input) ||
    typeof input.sourceKind !== 'string' ||
    !MAP_MARKER_SOURCES.has(input.sourceKind as ReplicatedMapMarkerSourceKind) ||
    !isBoundedString(input.sourceId, 160) ||
    !isBoundedString(input.displayName, 160) ||
    !isRecord(input.worldPosition) ||
    !isGlobalPositionInPartition(
      ICEAWAY_TARGET_WORLD_PARTITION,
      input.worldPosition as unknown as GlobalPosition,
    ) ||
    !isNonNegativeInteger(input.revision) ||
    typeof input.visibility !== 'string' ||
    !MAP_MARKER_VISIBILITIES.has(
      input.visibility as ReplicatedMapMarker['visibility'],
    ) ||
    (input.sourceEntityId !== undefined &&
      !isBoundedString(input.sourceEntityId, 160)) ||
    (input.state !== undefined && !isBoundedString(input.state, 160))
  ) return false;
  return true;
};

const isMapState = (input: unknown): input is SharedWorldCompactSnapshot['map'] => {
  if (
    !isRecord(input) ||
    !isStringArray(input.discoveredPortIds, 2_048) ||
    !isStringArray(input.discoveredPoiIds, 2_048) ||
    input.teammatePositionPolicy !== 'SUBSCRIPTION_WHEN_MAP_OPEN' ||
    !isRecord(input.subscription)
  ) return false;
  const subscription = input.subscription;
  if (
    !isNonNegativeInteger(subscription.revision) ||
    typeof subscription.open !== 'boolean' ||
    subscription.worldPartitionId !== ICEAWAY_TARGET_WORLD_PARTITION.id ||
    !Array.isArray(subscription.requestedMapChunks) ||
    subscription.requestedMapChunks.length > 64 ||
    !subscription.requestedMapChunks.every(isChunk) ||
    !Array.isArray(subscription.activeSubscriptions) ||
    subscription.activeSubscriptions.length > 128 ||
    !subscription.activeSubscriptions.every(isInterestSubscription) ||
    !Array.isArray(subscription.markers) ||
    subscription.markers.length > 512 ||
    !subscription.markers.every(isMapMarker)
  ) return false;
  const identities = new Set<string>();
  for (const marker of subscription.markers as ReplicatedMapMarker[]) {
    const identity = `${marker.sourceKind}:${marker.sourceId}`;
    if (identities.has(identity)) return false;
    identities.add(identity);
  }
  return true;
};

const isDialogueState = (input: unknown): input is ReplicatedDialogueState => {
  if (
    !isRecord(input) ||
    !isNonNegativeInteger(input.revision) ||
    !Array.isArray(input.conversations) ||
    input.conversations.length > 512 ||
    !Array.isArray(input.notices) ||
    input.notices.length > 512 ||
    !isRecord(input.inputPolicy) ||
    input.inputPolicy.localDialogueLocksMovement !== false ||
    input.inputPolicy.localDialoguePausesAuthority !== false
  ) return false;
  for (const conversation of input.conversations) {
    if (
      !isRecord(conversation) ||
      !isBoundedString(conversation.instanceId, 384) ||
      !isBoundedString(conversation.conversationId, 160) ||
      typeof conversation.scope !== 'string' ||
      !DIALOGUE_SCOPES.has(conversation.scope as DialogueScope) ||
      !['ACTIVE', 'COMPLETED'].includes(String(conversation.status)) ||
      !isNonNegativeInteger(conversation.revision) ||
      !isStringArray(conversation.participants, 4) ||
      (conversation.lastChoiceId !== undefined &&
        !isBoundedString(conversation.lastChoiceId, 160)) ||
      (conversation.lastActorPlayerId !== undefined &&
        !isBoundedString(conversation.lastActorPlayerId, 160))
    ) return false;
    if (conversation.currentNode !== undefined) {
      const node = conversation.currentNode;
      if (
        !isRecord(node) ||
        !isBoundedString(node.nodeId, 160) ||
        !isBoundedString(node.speakerId, 160) ||
        !isBoundedString(node.speakerName, 160) ||
        !isBoundedString(node.text, 4_000) ||
        !Array.isArray(node.choices) ||
        node.choices.length > 32 ||
        node.choices.some((choice) =>
          !isRecord(choice) ||
          !isBoundedString(choice.choiceId, 160) ||
          !isBoundedString(choice.text, 1_000))
      ) return false;
    }
  }
  for (const notice of input.notices) {
    if (
      !isRecord(notice) ||
      !isBoundedString(notice.noticeId, 384) ||
      !['NPC', 'SYSTEM'].includes(String(notice.channel)) ||
      typeof notice.scope !== 'string' ||
      !DIALOGUE_SCOPES.has(notice.scope as DialogueScope) ||
      !isBoundedString(notice.title, 160) ||
      !isBoundedString(notice.body, 1_000) ||
      typeof notice.createdAtWorldTimeSeconds !== 'number' ||
      !Number.isFinite(notice.createdAtWorldTimeSeconds) ||
      notice.createdAtWorldTimeSeconds < 0 ||
      typeof notice.acknowledged !== 'boolean' ||
      (notice.sourceEventId !== undefined &&
        !isBoundedString(notice.sourceEventId, 384))
    ) return false;
  }
  return true;
};

const isCompactSnapshot = (
  input: unknown,
): input is SharedWorldCompactSnapshot => {
  if (
    !isRecord(input) ||
    !isNonNegativeInteger(input.revision) ||
    !isNonNegativeInteger(input.authorityRevision) ||
    !isNonNegativeInteger(input.eventCursor) ||
    typeof input.simulationTime !== 'number' ||
    !Number.isFinite(input.simulationTime) ||
    input.simulationTime < 0 ||
    !Array.isArray(input.routes) ||
    !Array.isArray(input.ports) ||
    !Array.isArray(input.portClearances) ||
    !Array.isArray(input.missions) ||
    !isRecord(input.settlement) ||
    !Array.isArray(input.outcomes) ||
    !Array.isArray(input.merchantShips) ||
    !isRecord(input.economy) ||
    !isRecord(input.serviceViews) ||
    !isRecord(input.radio) ||
    !Array.isArray(input.radio.logicalBroadcasts) ||
    !isRecord(input.radio.receiver) ||
    !Array.isArray(input.radio.receiver.messages) ||
    !Array.isArray(input.radio.receiver.mutedCategories) ||
    !isDialogueState(input.dialogue) ||
    !isMapState(input.map) ||
    !isRecord(input.emergence) ||
    !Array.isArray(input.emergence.roads) ||
    !Array.isArray(input.emergence.travel) ||
    !Array.isArray(input.emergence.npcs) ||
    !Array.isArray(input.emergence.services) ||
    !Array.isArray(input.emergence.incidents) ||
    !Array.isArray(input.emergence.storyQuests) ||
    !Array.isArray(input.emergence.cooperativeVehicles) ||
    input.emergence.cooperativeVehicles.length > 32 ||
    !input.emergence.cooperativeVehicles.every(isCooperativeVehicleState) ||
    !Array.isArray(input.emergence.npcPresentation) ||
    !isRecord(input.environment) ||
    !isRecord(input.scopePolicy) ||
    !isRecord(input.devUnlocks)
  ) return false;
  return isJsonValue(input);
};

export const validateWorldStateBaselinePayload = (
  input: unknown,
): WorldStateBaselinePayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'WORLD_STATE_BASELINE' ||
    input.formatVersion !== WORLD_REPLICATION_FORMAT_VERSION ||
    !isBoundedString(input.worldDatasetHash, 256) ||
    !isNonNegativeInteger(input.serverTick) ||
    !isCompactSnapshot(input.snapshot)
  ) return undefined;
  return {
    version: 1,
    kind: 'WORLD_STATE_BASELINE',
    formatVersion: WORLD_REPLICATION_FORMAT_VERSION,
    worldDatasetHash: input.worldDatasetHash,
    serverTick: serverTick(input.serverTick),
    snapshot: input.snapshot,
  };
};

export const validateWorldStateDeltaPayload = (
  input: unknown,
): WorldStateDeltaPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'WORLD_STATE_DELTA' ||
    !isNonNegativeInteger(input.baseRevision) ||
    !isNonNegativeInteger(input.revision) ||
    input.revision <= input.baseRevision ||
    !isNonNegativeInteger(input.serverTick) ||
    !isCompactSnapshot(input.snapshot) ||
    input.snapshot.revision !== input.revision
  ) return undefined;
  return {
    version: 1,
    kind: 'WORLD_STATE_DELTA',
    baseRevision: input.baseRevision,
    revision: input.revision,
    serverTick: serverTick(input.serverTick),
    snapshot: input.snapshot,
  };
};

const isReplicatedEvent = (
  input: unknown,
): input is ReplicatedWorldDomainEvent => {
  if (
    !isRecord(input) ||
    !isNonNegativeInteger(input.cursor) ||
    input.cursor < 1 ||
    !isNonNegativeInteger(input.serverTick) ||
    !Array.isArray(input.contributorPlayerIds) ||
    input.contributorPlayerIds.length > 4 ||
    !input.contributorPlayerIds.every((id) => isBoundedString(id, 160)) ||
    !isRecord(input.event) ||
    !isBoundedString(input.event.type, 96) ||
    !isBoundedString(input.event.eventId, 160) ||
    typeof input.event.occurredAt !== 'number' ||
    !Number.isFinite(input.event.occurredAt) ||
    input.event.occurredAt < 0 ||
    !isJsonValue(input.event)
  ) return false;
  return true;
};

export const validateWorldDomainEventBatchPayload = (
  input: unknown,
): WorldDomainEventBatchPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'WORLD_DOMAIN_EVENT_BATCH' ||
    !isNonNegativeInteger(input.firstCursor) ||
    !isNonNegativeInteger(input.lastCursor) ||
    !isNonNegativeInteger(input.serverTick) ||
    !Array.isArray(input.events) ||
    input.events.length < 1 ||
    input.events.length > 128 ||
    !input.events.every(isReplicatedEvent)
  ) return undefined;
  const events = input.events as ReplicatedWorldDomainEvent[];
  if (
    input.firstCursor !== events[0]!.cursor ||
    input.lastCursor !== events[events.length - 1]!.cursor ||
    events.some((event, index) =>
      index > 0 && event.cursor !== events[index - 1]!.cursor + 1)
  ) return undefined;
  return {
    version: 1,
    kind: 'WORLD_DOMAIN_EVENT_BATCH',
    firstCursor: input.firstCursor,
    lastCursor: input.lastCursor,
    serverTick: serverTick(input.serverTick),
    events: events.map((record) => ({
      ...record,
      serverTick: serverTick(record.serverTick),
      contributorPlayerIds: record.contributorPlayerIds.map(playerId),
    })),
  };
};

export const validateWorldEventResyncRequestPayload = (
  input: unknown,
): WorldEventResyncRequestPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    input.kind !== 'WORLD_EVENT_RESYNC_REQUEST' ||
    !isNonNegativeInteger(input.afterCursor) ||
    !isNonNegativeInteger(input.observedRevision) ||
    (input.scope !== 'EVENTS' && input.scope !== 'FULL')
  ) return undefined;
  return {
    version: 1,
    kind: 'WORLD_EVENT_RESYNC_REQUEST',
    afterCursor: input.afterCursor,
    observedRevision: input.observedRevision,
    scope: input.scope,
  };
};
