import { clamp, smoothstep } from '../utils/math';

export interface WorldCloudFieldInput {
  readonly timeSeconds: number;
  readonly x: number;
  readonly z: number;
  readonly directionX: number;
  readonly directionZ: number;
  readonly cloudCover: number;
}

export interface WorldCloudFieldSample {
  /** Zero is open sky and one is the darkest part of a cloud bank. */
  readonly shadow: number;
  /** Direct-light transmission retained beneath the cloud bank. */
  readonly transmission: number;
  /**
   * Local precipitation-bearing cloud mass. Weather intensity still decides
   * whether anything can fall; this only prevents snow under a clear gap.
   */
  readonly precipitation: number;
}

export interface LocalPrecipitationMassState {
  readonly active: boolean;
  readonly clearSeconds: number;
  readonly gate: number;
}

export const INITIAL_LOCAL_PRECIPITATION_MASS_STATE:
Readonly<LocalPrecipitationMassState> = Object.freeze({
  active: false,
  clearSeconds: 0,
  gate: 0,
});

/**
 * Keeps a player inside one precipitation mass until its trailing cloud edge
 * has genuinely passed. The asymmetric thresholds reject tiny analytic-field
 * ripples, while the slow optical release lets already-visible flakes finish
 * falling instead of blinking out together.
 */
export const advanceLocalPrecipitationMass = (
  previous: Readonly<LocalPrecipitationMassState>,
  cloudMass: number,
  deltaSeconds: number,
): LocalPrecipitationMassState => {
  const sample = clamp(cloudMass, 0, 1);
  const delta = clamp(deltaSeconds, 0, 0.1);
  let active = previous.active;
  let clearSeconds = previous.clearSeconds;
  if (active) {
    clearSeconds = sample < 0.055 ? clearSeconds + delta : 0;
    // A falling flake lives for several seconds and a real precipitation
    // shaft is hundreds of metres wide. Requiring a sustained clear gap
    // prevents small field-edge errors from producing two-second snow/no-snow
    // pulses while still letting a genuinely departed bank end cleanly.
    if (clearSeconds >= 18) active = false;
  } else if (sample >= 0.16) {
    active = true;
    clearSeconds = 0;
  }
  const target = active
    ? sample < 0.055
      ? previous.gate
      : Math.max(0.14, smoothstep(0.025, 0.78, sample))
    : 0;
  const response = target > previous.gate ? 0.82 : 0.1;
  const blend = 1 - Math.exp(-response * delta);
  return {
    active,
    clearSeconds,
    gate: previous.gate + (target - previous.gate) * blend,
  };
};

/**
 * Cheap analytic cloud deck shared by ground shaders and the local sun.
 * Multi-kilometre wavelengths make cloud and precipitation fronts travel
 * across the landscape as weather, rather than flickering like a local noise
 * texture. At the normal 5.4 m/s advection rate a snow-bearing lobe takes
 * roughly five to ten minutes to cross one fixed world point.
 */
export const sampleWorldCloudField = (
  input: Readonly<WorldCloudFieldInput>,
): WorldCloudFieldSample => {
  const cover = clamp(input.cloudCover, 0, 1);
  if (cover <= 0.015) {
    return { shadow: 0, transmission: 1, precipitation: 0 };
  }
  const directionLength = Math.max(
    0.0001,
    Math.hypot(input.directionX, input.directionZ),
  );
  const directionX = input.directionX / directionLength;
  const directionZ = input.directionZ / directionLength;
  const crossX = -directionZ;
  const crossZ = directionX;
  const along = input.x * directionX + input.z * directionZ;
  const across = input.x * crossX + input.z * crossZ;
  const time = Math.max(0, input.timeSeconds);
  const warpedAlong = along - time * 5.4 +
    Math.sin(across * 0.00122 + time * 0.00042) * 310;
  const broad = 0.5 + 0.5 * Math.sin(warpedAlong * 0.00116 + 0.7);
  const crossBank = 0.5 + 0.5 * Math.sin(
    across * 0.00172 - time * 0.00074 +
      Math.sin(warpedAlong * 0.00068) * 0.72,
  );
  const detail = 0.5 + 0.5 * Math.sin(
    warpedAlong * 0.00335 + across * 0.0021 - time * 0.0032 + 2.1,
  );
  const field = broad * 0.64 + crossBank * 0.25 + detail * 0.11;
  const threshold = 0.8 - cover * 0.42;
  const brokenShadow = smoothstep(threshold - 0.1, threshold + 0.09, field);
  const overcastFloor = smoothstep(0.76, 0.98, cover) * 0.64;
  const shadow = clamp(
    Math.max(overcastFloor, brokenShadow * smoothstep(0.08, 0.38, cover)),
    0,
    1,
  );
  // Precipitation intentionally does not inherit the overcast floor. A sky
  // can be grey without snowing; flakes belong only to the broad, visibly
  // dense mass that is crossing the player. Fine cloud detail affects the
  // edge visually but cannot chop a several-minute event into tiny bursts.
  const precipitationMass = broad * 0.84 + crossBank * 0.16;
  const strength = 0.16 + cover * 0.34;
  return {
    shadow,
    transmission: clamp(1 - shadow * strength, 0.48, 1),
    precipitation: smoothstep(0.43, 0.67, precipitationMass) *
      smoothstep(0.64, 0.84, cover),
  };
};

/** GLSL twin used by snow and macro terrain without a shadow-map pass. */
export const WORLD_CLOUD_FIELD_GLSL = `
float icewayWorldCloudShadow(
  vec2 icewayWorldXZ,
  float icewayTime,
  vec2 icewayWindDirection,
  float icewayCloudCover
) {
  float icewayCover = clamp(icewayCloudCover, 0.0, 1.0);
  if (icewayCover <= 0.015) return 0.0;
  vec2 icewayDirection = normalize(
    icewayWindDirection + vec2(0.00001, 0.0)
  );
  vec2 icewayCross = vec2(-icewayDirection.y, icewayDirection.x);
  float icewayAlong = dot(icewayWorldXZ, icewayDirection);
  float icewayAcross = dot(icewayWorldXZ, icewayCross);
  float icewayWarpedAlong = icewayAlong - icewayTime * 5.4 +
    sin(icewayAcross * 0.00122 + icewayTime * 0.00042) * 310.0;
  float icewayBroad = 0.5 + 0.5 * sin(icewayWarpedAlong * 0.00116 + 0.7);
  float icewayCrossBank = 0.5 + 0.5 * sin(
    icewayAcross * 0.00172 - icewayTime * 0.00074 +
      sin(icewayWarpedAlong * 0.00068) * 0.72
  );
  float icewayDetail = 0.5 + 0.5 * sin(
    icewayWarpedAlong * 0.00335 + icewayAcross * 0.0021 -
      icewayTime * 0.0032 + 2.1
  );
  float icewayField = icewayBroad * 0.64 +
    icewayCrossBank * 0.25 + icewayDetail * 0.11;
  float icewayThreshold = 0.8 - icewayCover * 0.42;
  float icewayBrokenShadow = smoothstep(
    icewayThreshold - 0.1,
    icewayThreshold + 0.09,
    icewayField
  );
  float icewayOvercastFloor = smoothstep(0.76, 0.98, icewayCover) * 0.64;
  return clamp(max(
    icewayOvercastFloor,
    icewayBrokenShadow * smoothstep(0.08, 0.38, icewayCover)
  ), 0.0, 1.0);
}

float icewayWorldCloudPrecipitation(
  vec2 icewayWorldXZ,
  float icewayTime,
  vec2 icewayWindDirection,
  float icewayCloudCover
) {
  float icewayCover = clamp(icewayCloudCover, 0.0, 1.0);
  if (icewayCover <= 0.015) return 0.0;
  vec2 icewayDirection = normalize(
    icewayWindDirection + vec2(0.00001, 0.0)
  );
  vec2 icewayCross = vec2(-icewayDirection.y, icewayDirection.x);
  float icewayAlong = dot(icewayWorldXZ, icewayDirection);
  float icewayAcross = dot(icewayWorldXZ, icewayCross);
  float icewayWarpedAlong = icewayAlong - icewayTime * 5.4 +
    sin(icewayAcross * 0.00122 + icewayTime * 0.00042) * 310.0;
  float icewayBroad = 0.5 + 0.5 * sin(
    icewayWarpedAlong * 0.00116 + 0.7
  );
  float icewayCrossBank = 0.5 + 0.5 * sin(
    icewayAcross * 0.00172 - icewayTime * 0.00074 +
      sin(icewayWarpedAlong * 0.00068) * 0.72
  );
  float icewayMass = icewayBroad * 0.84 + icewayCrossBank * 0.16;
  return smoothstep(0.43, 0.67, icewayMass) *
    smoothstep(0.64, 0.84, icewayCover);
}
`;
