import { HEART_SANCTUARY } from './SanctuaryWorld';
import { SanctuaryNavigation, type SanctuaryObstacle } from './SanctuaryNavigation';
import { HUSK_HITBOX, sphereHitsBody, type CombatBody, type CombatPoint } from '../combat/CombatHitboxes';

export type SanctuaryPhase = 'UNDISCOVERED' | 'PREPARE' | 'APPROACH' | 'DEFEND' | 'REST' | 'WOUNDED' | 'RESTORED';
export interface SanctuaryHusk {
  id: string; x: number; z: number; health: number; heading: number;
  age: number; attack: number; speed: number; gait: number; death: number;
  mode: 'WALK' | 'RUN' | 'BREACH' | 'DRAIN' | 'STAGGER' | 'FALL' | 'WINDUP' | 'RECOVER';
  hitRunes: string[];
}
export interface SanctuarySave {
  version: 1; phase: SanctuaryPhase; wave: number; vitality: number;
  seconds: number; spawnTimer: number; spawned: number; nextId: number;
  suppliesTaken: boolean; husks: SanctuaryHusk[]; damage: Record<string, number>;
}
export interface SanctuaryRuneField {
  id: string; kind: 'FIRE_LINE' | 'WARD' | 'BURST' | 'STRIKE' | 'SLOW';
  x: number; z: number; radius: number;
  y?: number;
}
export interface SanctuaryStep {
  obstacles: readonly SanctuaryObstacle[];
  runes: readonly SanctuaryRuneField[];
  canWalk: (x: number, z: number) => boolean;
  collapse: (id: string) => void;
  breach?: (id:string,attacker:{x:number;z:number})=>boolean;
  track: (ax: number, az: number, bx: number, bz: number, heading: number) => void;
  player?: CombatBody;
  groundY?: (x: number, z: number) => number;
  blocked?: (from: CombatPoint, to: CombatPoint) => boolean;
  hurtPlayer?: (damage: number) => void;
}
const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, Number.isFinite(v) ? v : a));
const WAVES = [4, 7, 10];

/** Real elapsed play time only. Calendar fast-forward, unloaded scenes and
 * wall-clock time cannot secretly spawn a raid or destroy the player's home. */
export class SanctuaryModel {
  readonly navigation = new SanctuaryNavigation();
  readonly state: SanctuarySave;
  readonly messages: string[] = [];
  private accumulator = 0;
  private navTimer = 0;
  private trackOrigins = new Map<string, { x: number; z: number }>();
  private playerInvulnerability = 0;

  constructor(saved?: SanctuarySave) {
    const phases: SanctuaryPhase[] = ['UNDISCOVERED', 'PREPARE', 'APPROACH', 'DEFEND', 'REST', 'WOUNDED', 'RESTORED'];
    this.state = {
      version: 1, phase: saved && phases.includes(saved.phase) ? saved.phase : 'UNDISCOVERED',
      wave: clamp(Math.floor(saved?.wave ?? 0), 0, 3), vitality: clamp(saved?.vitality ?? 1, .05, 1),
      seconds: clamp(saved?.seconds ?? 0, 0, 10000), spawnTimer: clamp(saved?.spawnTimer ?? 0, 0, 20),
      spawned: clamp(saved?.spawned ?? 0, 0, 10), nextId: Math.max(1, saved?.nextId ?? 1),
      suppliesTaken: saved?.suppliesTaken === true,
      damage: Object.fromEntries(Object.entries(saved?.damage ?? {}).slice(0, 500).map(([id, d]) => [id, clamp(d, 0, 1)])),
      husks: (saved?.husks ?? []).slice(0, 12).filter(h => Number.isFinite(h.x) && Number.isFinite(h.z)).map(h => ({
        ...h, health: clamp(h.health, 0, 3), attack: clamp(h.attack, 0, 3),
        speed: 0, age: clamp(h.age, 0, 10000), death: clamp(h.death, 0, 3),
        hitRunes: (h.hitRunes ?? []).slice(-32),
      })),
    };
  }

  discover(): boolean {
    if (this.state.phase !== 'UNDISCOVERED') return false;
    this.state.phase = 'PREPARE';
    this.messages.push('The Heart still breathes. Prepare the pass; touch the Heart when you are ready.');
    return true;
  }

  begin(): boolean {
    if (!['PREPARE', 'REST'].includes(this.state.phase) || this.state.wave >= 3) return false;
    this.state.wave++;
    this.state.phase = 'APPROACH'; this.state.seconds = 0;
    this.state.spawned = 0; this.state.spawnTimer = 0;
    this.messages.push('A pulse answers from the dark beyond the pass. Reach your defences.');
    return true;
  }

  restore(): boolean {
    if (this.state.phase !== 'WOUNDED') return false;
    this.state.phase = this.state.wave <= 1 ? 'PREPARE' : 'REST';
    this.state.wave = Math.max(0, this.state.wave - 1);
    this.state.vitality = .75; this.state.seconds = 0;
    return true;
  }

  hit(id: string, damage = .8): boolean {
    const h = this.state.husks.find(h => h.id === id && h.health > 0);
    if (!h) return false;
    h.health = Math.max(0, h.health - damage);
    h.mode = h.health ? 'STAGGER' : 'FALL'; h.attack = .65;
    return true;
  }

  update(dt: number, nearby: boolean, env: SanctuaryStep): void {
    if (!nearby || !['APPROACH', 'DEFEND'].includes(this.state.phase)) return;
    this.accumulator += clamp(dt, 0, .25);
    // Fixed 20 Hz gameplay; presenter interpolates at the display frame rate.
    while (this.accumulator >= .05) { this.accumulator -= .05; this.step(.05, env); }
  }

  private step(dt: number, env: SanctuaryStep): void {
    const s = this.state;
    if (!['APPROACH', 'DEFEND'].includes(s.phase)) return;
    s.seconds += dt;
    this.playerInvulnerability = Math.max(0, this.playerInvulnerability - dt);
    this.navTimer -= dt;
    if (this.navTimer <= 0) { this.navTimer = .65; this.navigation.rebuild(env.obstacles); }
    if (s.phase === 'APPROACH') {
      if (s.seconds < 28) return;
      s.phase = 'DEFEND'; s.seconds = 0;
      this.messages.push('The soulless have entered the pass. Fire Gate burns; Ash Burst breaks their hold.');
    }
    s.spawnTimer -= dt;
    const count = WAVES[s.wave - 1] ?? 4;
    if (s.spawned < count && s.spawnTimer <= 0) {
      const lane = ((s.spawned * 7 + s.wave * 3) % 13) - 6;
      s.husks.push({ id: `husk-${s.nextId++}`, x: HEART_SANCTUARY.x + lane,
        z: HEART_SANCTUARY.z + 72, heading: Math.PI, health: s.wave === 3 ? 2.4 : 1.8,
        age: 0, attack: 0, speed: 0, gait: 0, death: 0, mode: 'WALK', hitRunes: [] });
      s.spawned++; s.spawnTimer = s.wave === 1 ? 8 : s.wave === 2 ? 6 : 4.5;
    }
    for (const h of s.husks) {
      h.age += dt; h.attack = Math.max(0, h.attack - dt); h.speed = 0;
      if (h.health <= 0) { h.death += dt; h.mode = 'FALL'; continue; }
      const body: CombatBody = { id: h.id, team: 'HOSTILE', x: h.x, z: h.z,
        y: env.groundY?.(h.x, h.z) ?? 0, ...HUSK_HITBOX };
      let slow = 1, ward = false;
      for (const r of env.runes) {
        if (Math.hypot(h.x - r.x, h.z - r.z) > r.radius + body.radius) continue;
        const origin = { x: r.x, y: (r.y ?? body.y) + .65, z: r.z };
        // Fields have a real vertical band; no hits through a floor above.
        if (body.y > origin.y + 1.4 || body.y + body.height < origin.y - .65 ||
          !sphereHitsBody(origin, r.radius, body) ||
          env.blocked?.(origin, {x: h.x, y: body.y + .9, z: h.z})) continue;
        if (r.kind === 'SLOW') slow = .3;
        if (r.kind === 'WARD') { ward = true; h.health -= dt * .14; }
        if (r.kind === 'FIRE_LINE') h.health -= dt * .62;
        if ((r.kind === 'BURST' || r.kind === 'STRIKE') && !h.hitRunes.includes(r.id)) {
          h.hitRunes.push(r.id); h.hitRunes = h.hitRunes.slice(-32);
          this.hit(h.id, r.kind === 'BURST' ? 1.3 : 2);
        }
      }
      if (h.health <= 0) { h.health = 0; h.mode = 'FALL'; continue; }
      if (h.mode === 'STAGGER' && h.attack > 0) continue;
      if (ward) { h.mode = 'STAGGER'; continue; }
      const player = env.player;
      const hand = { x: h.x + Math.sin(h.heading) * .68,
        y: body.y + 1.05, z: h.z + Math.cos(h.heading) * .68 };
      const canStrike = player && sphereHitsBody(hand, .5, player) &&
        !env.blocked?.({x: h.x, y: body.y + 1.05, z: h.z}, {x: player.x, y: player.y + 1, z: player.z});
      if (h.mode === 'WINDUP') {
        if (h.attack > 0) continue;
        if (canStrike && this.playerInvulnerability <= 0) {
          env.hurtPlayer?.(.09); this.playerInvulnerability = .8;
        }
        h.mode = 'RECOVER'; h.attack = 1.05; continue;
      }
      if (h.mode === 'RECOVER' && h.attack > 0) continue;
      if (player && Math.hypot(h.x - player.x, h.z - player.z) < 1.25 &&
        Math.abs(body.y - player.y) < .9) {
        h.heading = Math.atan2(player.x - h.x, player.z - h.z);
        if (!env.blocked?.({x: h.x,y:body.y+1,z:h.z}, {x:player.x,y:player.y+1,z:player.z})) {
          h.mode = 'WINDUP'; h.attack = .5; continue;
        }
      }
      if (Math.hypot(h.x - HEART_SANCTUARY.x, h.z - HEART_SANCTUARY.z) < 3.8) {
        h.mode = 'DRAIN'; s.vitality = Math.max(0, s.vitality - dt * .012); continue;
      }
      const next = this.navigation.next(h.x, h.z);
      if (!next) continue;
      if (next.blocker && env.obstacles.some(o => o.id === next.blocker)) {
        h.mode = 'BREACH';
        if (h.attack <= 0) {
          h.attack = 1.8;
          const damage = (s.damage[next.blocker] ?? 0) + .075;
          const regionDamage=env.breach?.(next.blocker,h)===true;
          s.damage[next.blocker] = regionDamage?Math.min(.99,damage):damage;
          if(regionDamage)this.navTimer=0;
          else if (damage >= 1) { env.collapse(next.blocker); delete s.damage[next.blocker]; this.navTimer = 0; }
        }
        continue;
      }
      const dx = next.x - h.x, dz = next.z - h.z, distance = Math.hypot(dx, dz);
      const running = s.wave >= 2 && h.age > (s.wave === 3 ? 8 : 23);
      const speed = (running ? 2.15 : .85) * slow;
      const travel = Math.min(distance, speed * dt);
      const nx = h.x + dx / Math.max(.001, distance) * travel;
      const nz = h.z + dz / Math.max(.001, distance) * travel;
      if (player && Math.abs(body.y - player.y) < 1.5 && Math.hypot(nx-player.x,nz-player.z) < body.radius+player.radius) continue;
      const crowded = s.husks.some(other => other !== h && other.health > 0 &&
        Math.hypot(nx - other.x, nz - other.z) < .48 && this.navigation.distance[this.navigation.index(other.x, other.z)]! < this.navigation.distance[this.navigation.index(h.x, h.z)]!);
      if (crowded || !env.canWalk(nx, nz)) continue;
      h.x = nx; h.z = nz; h.speed = speed; h.gait += travel * 4;
      if (distance > .01) h.heading = Math.atan2(dx, dz);
      h.mode = running ? 'RUN' : 'WALK';
      const previous = this.trackOrigins.get(h.id);
      if (!previous || Math.hypot(h.x - previous.x, h.z - previous.z) >= .35) {
        if (previous) env.track(previous.x, previous.z, h.x, h.z, h.heading);
        this.trackOrigins.set(h.id, { x: h.x, z: h.z });
      }
    }
    s.husks = s.husks.filter(h => {
      if (h.death < 2.5) return true;
      this.trackOrigins.delete(h.id); return false;
    });
    if (s.vitality <= 0) {
      s.phase = 'WOUNDED'; s.vitality = .05; s.husks = []; this.trackOrigins.clear();
      this.messages.push('The Heart folds its light inward. Your home remains. Bring two logs and one stone to rekindle its ward.');
    } else if (s.spawned >= count && s.husks.length === 0) {
      s.phase = s.wave >= 3 ? 'RESTORED' : 'REST';
      s.vitality = Math.min(1, s.vitality + .25);
      this.messages.push(s.phase === 'RESTORED'
        ? 'The Heart sings again. The sanctuary is at peace; warmth returns to the temple garden.'
        : 'The pass is quiet. Repair, gather and explore. The next pulse waits for your touch.');
    }
  }

  exportState(): SanctuarySave {
    return { ...this.state, damage: { ...this.state.damage }, husks: this.state.husks.map(h => ({ ...h, hitRunes: [...h.hitRunes] })) };
  }
}
