import {
  BufferGeometry,
  CatmullRomCurve3,
  CircleGeometry,
  Color,
  DoubleSide,
  Float32BufferAttribute,
  Group,
  Mesh,
  MeshStandardMaterial,
  ShaderMaterial,
  Vector3,
  type Scene,
} from 'three';
import { clamp, hash2D } from '../utils/math';
import type { TerrainGridCell, TerrainHeightSystem } from './TerrainHeightSystem';
import { WILDERNESS_SURVIVAL_REGION } from '../survival/WildernessBiome';
import { sampleGeneratedWorld } from '../world/generation/GeneratedWorldRuntime';

export interface InlandWaterPoint {
  readonly x: number;
  readonly z: number;
}

export interface InlandWatercourse {
  readonly id: string;
  readonly points: readonly InlandWaterPoint[];
  readonly widthMetres: number;
  readonly depthMetres: number;
  readonly sourceFlow: number;
  readonly waterEnabled: boolean;
}

export interface InlandWaterBody {
  readonly id: string;
  readonly x: number;
  readonly z: number;
  readonly radiusX: number;
  readonly radiusZ: number;
  readonly depthMetres: number;
  readonly waterEnabled: boolean;
}

export interface InlandWaterSaveData {
  readonly version: 1;
  readonly watercourses: readonly InlandWatercourse[];
  readonly waterBodies: readonly InlandWaterBody[];
}

export interface InlandWaterSample {
  readonly water: boolean;
  readonly flowSpeed: number;
  readonly frozenFraction: number;
  readonly depthMetres: number;
}

const pointSegmentDistance = (
  x: number,
  z: number,
  a: Readonly<InlandWaterPoint>,
  b: Readonly<InlandWaterPoint>,
): number => {
  const dx = b.x - a.x;
  const dz = b.z - a.z;
  const lengthSquared = Math.max(0.0001, dx * dx + dz * dz);
  const t = clamp(((x - a.x) * dx + (z - a.z) * dz) / lengthSquared, 0, 1);
  return Math.hypot(x - (a.x + dx * t), z - (a.z + dz * t));
};

/**
 * Sparse authored inland hydrology. It deliberately simulates readable flow
 * rather than fluid dynamics: terrain slope, channel width/depth and source
 * flow determine one deterministic speed, which in turn determines freezing.
 */
export class InlandWaterSystem {
  private readonly root = new Group();
  private readonly waterways = new Map<string, InlandWatercourse>();
  private readonly bodies = new Map<string, InlandWaterBody>();
  private readonly waterMaterial: ShaderMaterial;
  private readonly iceMaterial: MeshStandardMaterial;
  private readonly renderedWaterMaterials = new Set<ShaderMaterial>();
  private readonly renderedIceMaterials = new Set<MeshStandardMaterial>();
  private readonly removeTerrainListener: () => void;
  private readonly listeners = new Set<() => void>();
  private idSequence = 1;
  private temperatureCelsius = -8;
  private worldTime = 0;
  private suppressTerrainRebuild = false;

  public constructor(
    scene: Scene,
    private readonly terrain: TerrainHeightSystem,
    saved?: Readonly<InlandWaterSaveData>,
  ) {
    this.root.name = 'Authored inland water · creek, river, pond and lake';
    scene.add(this.root);
    this.waterMaterial = new ShaderMaterial({
      name: 'Asset-bank material · WATER_COLD',
      uniforms: {
        uTime: { value: 0 },
        uFlowSpeed: { value: 0.2 },
        uDeep: { value: new Color(0x276f82) },
        uShallow: { value: new Color(0x77c6cb) },
      },
      vertexShader: `
        varying vec2 vUv;
        varying float vWave;
        uniform float uTime;
        uniform float uFlowSpeed;
        void main() {
          vUv = uv;
          vec3 p = position;
          vWave = sin((uv.y * 31.0 - uTime * (0.65 + uFlowSpeed * 3.4)) + uv.x * 3.0) * 0.5 + 0.5;
          p.y += (vWave - 0.5) * 0.025;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
        }
      `,
      fragmentShader: `
        varying vec2 vUv;
        varying float vWave;
        uniform vec3 uDeep;
        uniform vec3 uShallow;
        void main() {
          float edge = smoothstep(0.0, 0.24, min(vUv.x, 1.0 - vUv.x));
          vec3 color = mix(uShallow, uDeep, edge * 0.72);
          color += vec3(0.12, 0.18, 0.17) * pow(vWave, 8.0) * 0.38;
          gl_FragColor = vec4(color, 0.82);
        }
      `,
      transparent: true,
      depthWrite: false,
      side: DoubleSide,
    });
    this.iceMaterial = new MeshStandardMaterial({
      name: 'Asset-bank material · ICE_THIN',
      color: 0x9ed8dc,
      roughness: 0.38,
      metalness: 0.03,
      transparent: true,
      opacity: 0.68,
      polygonOffset: true,
      polygonOffsetFactor: -1,
    });
    if (saved) this.importState(saved);
    this.removeTerrainListener = terrain.addListener(() => {
      if (!this.suppressTerrainRebuild) this.rebuild();
    });
  }

  public update(worldTime: number, temperatureCelsius = this.temperatureCelsius): void {
    this.worldTime = worldTime;
    this.temperatureCelsius = clamp(temperatureCelsius, -45, 30);
    this.waterMaterial.uniforms.uTime!.value = worldTime;
    for (const material of this.renderedWaterMaterials) {
      material.uniforms.uTime!.value = worldTime;
    }
    for (const material of this.renderedIceMaterials) {
      const speed = Number(material.userData.icewayFlowSpeed ?? 0.035);
      const frozenFraction = this.freezeForSpeed(speed);
      material.opacity = 0.08 + frozenFraction * 0.76;
      material.visible = frozenFraction > 0.025;
    }
  }

  public addListener(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  public getBounds(padding = 2): Readonly<{
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
  }> | undefined {
    const points = this.listWatercourses().flatMap((item) => item.points)
      .concat(this.listWaterBodies().map((body) => ({ x: body.x, z: body.z })));
    if (points.length === 0) return undefined;
    const maximumRadius = Math.max(
      0,
      ...this.listWatercourses().map((item) => item.widthMetres * 0.5),
      ...this.listWaterBodies().map((body) => Math.max(body.radiusX, body.radiusZ)),
    );
    const margin = maximumRadius + padding;
    return {
      minX: Math.min(...points.map((point) => point.x)) - margin,
      maxX: Math.max(...points.map((point) => point.x)) + margin,
      minZ: Math.min(...points.map((point) => point.z)) - margin,
      maxZ: Math.max(...points.map((point) => point.z)) + margin,
    };
  }

  public addCreek(
    start: Readonly<InlandWaterPoint>,
    end: Readonly<InlandWaterPoint>,
    options: Readonly<{
      widthMetres?: number;
      depthMetres?: number;
      sourceFlow?: number;
      waterEnabled?: boolean;
    }> = {},
  ): string {
    const id = `watercourse-${this.idSequence++}`;
    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const length = Math.max(0.001, Math.hypot(dx, dz));
    const sideX = -dz / length;
    const sideZ = dx / length;
    const seed = Math.round(start.x * 7 + start.z * 11 + end.x * 13 + end.z * 17);
    const points = Array.from({ length: 5 }, (_, index) => {
      const t = index / 4;
      const envelope = Math.sin(t * Math.PI);
      const meander = (hash2D(seed, index, 1129) - 0.5) *
        Math.min(length * 0.13, 5.5) * envelope;
      return {
        x: start.x + dx * t + sideX * meander,
        z: start.z + dz * t + sideZ * meander,
      };
    });
    this.waterways.set(id, {
      id,
      points,
      widthMetres: clamp(options.widthMetres ?? 2.4, 0.5, 24),
      depthMetres: clamp(options.depthMetres ?? 0.55, 0.15, 6),
      sourceFlow: clamp(options.sourceFlow ?? 0.55, 0, 3),
      waterEnabled: options.waterEnabled ?? true,
    });
    this.carveWatercourse(id);
    this.rebuild();
    this.notifyChanged();
    return id;
  }

  public addLake(
    x: number,
    z: number,
    radiusX: number,
    radiusZ = radiusX,
    depthMetres = 0.75,
    waterEnabled = true,
  ): string {
    const id = `waterbody-${this.idSequence++}`;
    const body: InlandWaterBody = {
      id,
      x,
      z,
      radiusX: clamp(radiusX, 1, 80),
      radiusZ: clamp(radiusZ, 1, 80),
      depthMetres: clamp(depthMetres, 0.2, 10),
      waterEnabled,
    };
    this.bodies.set(id, body);
    this.carveWaterBody(id);
    this.rebuild();
    this.notifyChanged();
    return id;
  }

  public widenNearest(x: number, z: number, deltaMetres: number): boolean {
    const nearest = this.nearestWatercourse(x, z);
    if (!nearest || nearest.distance > nearest.item.widthMetres + 4) return false;
    const previousCells = this.collectWatercourseCells(nearest.item);
    const widened: InlandWatercourse = {
      ...nearest.item,
      widthMetres: clamp(nearest.item.widthMetres + deltaMetres, 0.5, 24),
    };
    if (Math.abs(widened.widthMetres - nearest.item.widthMetres) < 0.001) return false;
    this.waterways.set(nearest.item.id, widened);
    if (widened.widthMetres > nearest.item.widthMetres) {
      const nextCells = this.collectWatercourseCells(widened);
      const added = [...nextCells].flatMap(([key, cell]) =>
        previousCells.has(key) ? [] : [cell]);
      // Only the newly exposed banks are cut. Re-running the full channel here
      // would deepen the old creek on every authoring click.
      this.applyChannelCells(
        added,
        Math.min(0.22, widened.depthMetres * 0.34),
      );
    }
    this.rebuild();
    this.notifyChanged();
    return true;
  }

  public removeNearest(x: number, z: number, radius = 5): boolean {
    const creek = this.nearestWatercourse(x, z);
    const lake = [...this.bodies.values()]
      .map((item) => ({
        item,
        distance: Math.max(0, Math.hypot(x - item.x, z - item.z) -
          Math.max(item.radiusX, item.radiusZ)),
      }))
      .sort((a, b) => a.distance - b.distance)[0];
    if (creek && creek.distance <= radius && (!lake || creek.distance <= lake.distance)) {
      this.waterways.delete(creek.item.id);
      this.rebuild();
      this.notifyChanged();
      return true;
    }
    if (lake && lake.distance <= radius) {
      this.bodies.delete(lake.item.id);
      this.rebuild();
      this.notifyChanged();
      return true;
    }
    return false;
  }

  public sample(x: number, z: number): InlandWaterSample {
    for (const body of this.bodies.values()) {
      const normalized = Math.hypot(
        (x - body.x) / body.radiusX,
        (z - body.z) / body.radiusZ,
      );
      if (normalized <= 1) {
        const flowSpeed = 0.035;
        return {
          water: body.waterEnabled,
          flowSpeed,
          frozenFraction: this.freezeForSpeed(flowSpeed),
          depthMetres: body.depthMetres,
        };
      }
    }
    for (const watercourse of this.waterways.values()) {
      for (let index = 1; index < watercourse.points.length; index += 1) {
        const a = watercourse.points[index - 1]!;
        const b = watercourse.points[index]!;
        if (pointSegmentDistance(x, z, a, b) > watercourse.widthMetres * 0.56) continue;
        const flowSpeed = this.segmentFlowSpeed(watercourse, a, b);
        return {
          water: watercourse.waterEnabled,
          flowSpeed,
          frozenFraction: this.freezeForSpeed(flowSpeed),
          depthMetres: watercourse.depthMetres,
        };
      }
    }
    // Macro hydrology is read-only runtime data. The authored survival creek
    // and Borealis coast retain priority, while generated lakes and river
    // catchments become usable as the player explores the larger mainland.
    const protectedWilderness = Math.hypot(
      x - WILDERNESS_SURVIVAL_REGION.centerX,
      z - WILDERNESS_SURVIVAL_REGION.centerZ,
    ) <= WILDERNESS_SURVIVAL_REGION.radius + 24;
    if (x <= -430 && !protectedWilderness) {
      const generated = sampleGeneratedWorld(x, z);
      if (generated.inside && generated.water >= 0.1) {
        const lakeDominant = generated.lake >= generated.river;
        const flowSpeed = lakeDominant
          ? 0.035
          : clamp(0.12 + generated.river * 1.75, 0.12, 2.2);
        return {
          water: true,
          flowSpeed,
          frozenFraction: this.freezeForSpeed(flowSpeed),
          depthMetres: lakeDominant
            ? 0.45 + generated.lake * 1.8
            : 0.28 + generated.river * 0.75,
        };
      }
    }
    return { water: false, flowSpeed: 0, frozenFraction: 0, depthMetres: 0 };
  }

  public suppressesSnowAt(x: number, z: number): boolean {
    const sample = this.sample(x, z);
    return sample.water && sample.frozenFraction < 0.72;
  }

  public listWatercourses(): readonly InlandWatercourse[] {
    return [...this.waterways.values()].map((item) => ({
      ...item,
      points: item.points.map((point) => ({ ...point })),
    }));
  }

  public listWaterBodies(): readonly InlandWaterBody[] {
    return [...this.bodies.values()].map((item) => ({ ...item }));
  }

  public exportState(): InlandWaterSaveData {
    return {
      version: 1,
      watercourses: this.listWatercourses(),
      waterBodies: this.listWaterBodies(),
    };
  }

  public importState(saved: Readonly<InlandWaterSaveData>): boolean {
    if (saved.version !== 1) return false;
    this.waterways.clear();
    this.bodies.clear();
    for (const candidate of saved.watercourses ?? []) {
      if (!candidate || candidate.points?.length < 2) continue;
      this.waterways.set(String(candidate.id), {
        id: String(candidate.id),
        points: candidate.points.flatMap((point) =>
          Number.isFinite(point.x) && Number.isFinite(point.z)
            ? [{ x: point.x, z: point.z }]
            : []),
        widthMetres: clamp(candidate.widthMetres, 0.5, 24),
        depthMetres: clamp(candidate.depthMetres, 0.15, 6),
        sourceFlow: clamp(candidate.sourceFlow, 0, 3),
        waterEnabled: Boolean(candidate.waterEnabled),
      });
    }
    for (const candidate of saved.waterBodies ?? []) {
      if (!candidate || !Number.isFinite(candidate.x) || !Number.isFinite(candidate.z)) continue;
      this.bodies.set(String(candidate.id), {
        id: String(candidate.id),
        x: candidate.x,
        z: candidate.z,
        radiusX: clamp(candidate.radiusX, 1, 80),
        radiusZ: clamp(candidate.radiusZ, 1, 80),
        depthMetres: clamp(candidate.depthMetres, 0.2, 10),
        waterEnabled: Boolean(candidate.waterEnabled),
      });
    }
    const ids = [...this.waterways.keys(), ...this.bodies.keys()];
    this.idSequence = Math.max(1, ...ids.map((id) => {
      const value = Number(id.split('-').at(-1));
      return Number.isFinite(value) ? value + 1 : 1;
    }));
    this.rebuild();
    this.notifyChanged();
    return true;
  }

  public dispose(): void {
    this.removeTerrainListener();
    this.listeners.clear();
    this.clearMeshes();
    this.waterMaterial.dispose();
    this.iceMaterial.dispose();
    this.root.removeFromParent();
  }

  private carveWatercourse(id: string): void {
    const watercourse = this.waterways.get(id);
    if (!watercourse) return;
    this.applyChannelCells(
      [...this.collectWatercourseCells(watercourse).values()],
      watercourse.depthMetres,
    );
  }

  private collectWatercourseCells(
    watercourse: Readonly<InlandWatercourse>,
  ): Map<string, TerrainGridCell> {
    const cells = new Map<string, TerrainGridCell>();
    const curve = new CatmullRomCurve3(watercourse.points.map((point) =>
      new Vector3(point.x, 0, point.z)), false, 'centripetal');
    const length = Math.max(1, curve.getLength());
    for (const point of curve.getSpacedPoints(Math.ceil(length))) {
      for (const cell of this.terrain.brushCells(
        point.x,
        point.z,
        watercourse.widthMetres * 0.5,
      )) cells.set(`${cell.gridX},${cell.gridZ}`, cell);
    }
    return cells;
  }

  private applyChannelCells(
    cells: readonly TerrainGridCell[],
    depthMetres: number,
  ): void {
    if (cells.length === 0) return;
    this.suppressTerrainRebuild = true;
    try {
      this.terrain.applyChannelCells(cells, depthMetres);
    } finally {
      this.suppressTerrainRebuild = false;
    }
  }

  private carveWaterBody(id: string): void {
    const body = this.bodies.get(id);
    if (!body) return;
    const cells: TerrainGridCell[] = [];
    const minimumX = this.terrain.worldToCell(body.x - body.radiusX);
    const maximumX = this.terrain.worldToCell(body.x + body.radiusX);
    const minimumZ = this.terrain.worldToCell(body.z - body.radiusZ);
    const maximumZ = this.terrain.worldToCell(body.z + body.radiusZ);
    for (let gridZ = minimumZ; gridZ <= maximumZ; gridZ += 1) {
      for (let gridX = minimumX; gridX <= maximumX; gridX += 1) {
        const x = this.terrain.cellCenterWorld(gridX);
        const z = this.terrain.cellCenterWorld(gridZ);
        if (Math.hypot((x - body.x) / body.radiusX, (z - body.z) / body.radiusZ) <= 1) {
          cells.push({ gridX, gridZ });
        }
      }
    }
    this.applyChannelCells(cells, body.depthMetres);
  }

  private nearestWatercourse(x: number, z: number): {
    item: InlandWatercourse;
    distance: number;
  } | undefined {
    return [...this.waterways.values()]
      .map((item) => ({
        item,
        distance: Math.min(...item.points.slice(1).map((point, index) =>
          pointSegmentDistance(x, z, item.points[index]!, point))),
      }))
      .sort((a, b) => a.distance - b.distance)[0];
  }

  private segmentFlowSpeed(
    watercourse: Readonly<InlandWatercourse>,
    a: Readonly<InlandWaterPoint>,
    b: Readonly<InlandWaterPoint>,
  ): number {
    const distance = Math.max(0.1, Math.hypot(b.x - a.x, b.z - a.z));
    const slope = Math.abs(
      this.terrain.sampleHeight(a.x, a.z) - this.terrain.sampleHeight(b.x, b.z),
    ) / distance;
    return clamp(
      0.04 + watercourse.sourceFlow * 0.38 + slope * 5.2 -
        watercourse.widthMetres * 0.012 + watercourse.depthMetres * 0.055,
      0.02,
      3.5,
    );
  }

  private freezeForSpeed(speed: number): number {
    const cold = clamp(-this.temperatureCelsius / 13, 0, 1);
    return clamp(cold * (1 - speed / 2.35), 0, 1);
  }

  private watercourseFlowSpeed(watercourse: Readonly<InlandWatercourse>): number {
    const speeds = watercourse.points.slice(1).map((point, index) =>
      this.segmentFlowSpeed(watercourse, watercourse.points[index]!, point));
    if (speeds.length === 0) return 0.035;
    return speeds.reduce((sum, speed) => sum + speed, 0) / speeds.length;
  }

  private createWaterMaterial(flowSpeed: number): ShaderMaterial {
    const material = this.waterMaterial.clone();
    material.uniforms = {
      uTime: { value: this.worldTime },
      uFlowSpeed: { value: flowSpeed },
      uDeep: { value: new Color(0x276f82) },
      uShallow: { value: new Color(0x77c6cb) },
    };
    this.renderedWaterMaterials.add(material);
    return material;
  }

  private createIceMaterial(flowSpeed: number): MeshStandardMaterial {
    const material = this.iceMaterial.clone();
    material.userData.icewayFlowSpeed = flowSpeed;
    const frozenFraction = this.freezeForSpeed(flowSpeed);
    material.opacity = 0.08 + frozenFraction * 0.76;
    material.visible = frozenFraction > 0.025;
    this.renderedIceMaterials.add(material);
    return material;
  }

  private rebuild(): void {
    this.clearMeshes();
    for (const watercourse of this.waterways.values()) {
      if (!watercourse.waterEnabled) continue;
      const geometry = this.createWatercourseGeometry(watercourse);
      const flowSpeed = this.watercourseFlowSpeed(watercourse);
      const water = new Mesh(geometry, this.createWaterMaterial(flowSpeed));
      water.name = `Inland flowing water · ${watercourse.id}`;
      water.renderOrder = 3;
      this.root.add(water);
      const ice = new Mesh(geometry, this.createIceMaterial(flowSpeed));
      ice.name = `Inland current-aware ice · ${watercourse.id}`;
      ice.position.y = 0.018;
      ice.renderOrder = 4;
      this.root.add(ice);
    }
    for (const body of this.bodies.values()) {
      if (!body.waterEnabled) continue;
      const y = this.terrain.sampleHeight(body.x, body.z) + 0.035;
      const geometry = new CircleGeometry(1, 48);
      geometry.rotateX(-Math.PI / 2);
      const water = new Mesh(geometry, this.createWaterMaterial(0.035));
      water.name = `Inland pond water · ${body.id}`;
      water.position.set(body.x, y, body.z);
      water.scale.set(body.radiusX, 1, body.radiusZ);
      water.renderOrder = 3;
      this.root.add(water);
      const ice = new Mesh(geometry, this.createIceMaterial(0.035));
      ice.name = `Inland pond ice · ${body.id}`;
      ice.position.set(body.x, y + 0.018, body.z);
      ice.scale.set(body.radiusX, 1, body.radiusZ);
      ice.renderOrder = 4;
      this.root.add(ice);
    }
  }

  private createWatercourseGeometry(
    watercourse: Readonly<InlandWatercourse>,
  ): BufferGeometry {
    const curve = new CatmullRomCurve3(watercourse.points.map((point) =>
      new Vector3(point.x, 0, point.z)), false, 'centripetal');
    const samples = Math.max(8, Math.ceil(curve.getLength() / 0.75));
    const positions: number[] = [];
    const uvs: number[] = [];
    const indices: number[] = [];
    for (let index = 0; index <= samples; index += 1) {
      const t = index / samples;
      const point = curve.getPoint(t);
      const tangent = curve.getTangent(t).normalize();
      const sideX = -tangent.z;
      const sideZ = tangent.x;
      for (const side of [-1, 1]) {
        const x = point.x + sideX * watercourse.widthMetres * 0.5 * side;
        const z = point.z + sideZ * watercourse.widthMetres * 0.5 * side;
        positions.push(x, this.terrain.sampleHeight(x, z) + 0.035, z);
        uvs.push(side < 0 ? 0 : 1, t);
      }
      if (index < samples) {
        const offset = index * 2;
        indices.push(offset, offset + 2, offset + 1, offset + 1, offset + 2, offset + 3);
      }
    }
    const geometry = new BufferGeometry();
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometry.computeBoundingSphere();
    return geometry;
  }

  private clearMeshes(): void {
    for (const child of [...this.root.children]) {
      if (child instanceof Mesh) child.geometry.dispose();
      child.removeFromParent();
    }
    for (const material of this.renderedWaterMaterials) material.dispose();
    for (const material of this.renderedIceMaterials) material.dispose();
    this.renderedWaterMaterials.clear();
    this.renderedIceMaterials.clear();
  }

  private notifyChanged(): void {
    for (const listener of this.listeners) listener();
  }
}
