import type { EmergentWorldRegistry } from '../gameplay/emergence/EmergentWorldRegistry';
import { emergentPolylineLength, sampleEmergentPolyline } from '../gameplay/emergence/EmergentPosition';
import type { RoadSurfaceObservation } from '../gameplay/emergence/EmergentWorldTypes';
import { prototypeGlobalToLocalPosition } from '../world/PrototypeWorldPositionAdapter';
import type { LandSnowSystem } from './LandSnowSystem';

/**
 * Converts detailed physical snow into bounded gameplay observations. The
 * simulation never imports or mutates Three.js snow meshes directly.
 */
export class LandSnowRoadObservationAdapter {
  private lastRevision = Number.NEGATIVE_INFINITY;
  private lastObservedAt = Number.NEGATIVE_INFINITY;
  private cached: RoadSurfaceObservation[] = [];

  public constructor(
    private readonly registry: EmergentWorldRegistry,
    private readonly snow: LandSnowSystem,
    private readonly maximumSamplesPerSegment = 48,
    private readonly maximumStaleSeconds = 10,
  ) {}

  public observe(simulationTime: number): readonly RoadSurfaceObservation[] {
    const revision = this.snow.getMutationRevision();
    if (
      revision === this.lastRevision &&
      simulationTime - this.lastObservedAt < this.maximumStaleSeconds
    ) return this.cached.map((value) => ({
      ...value,
      measuredAt: simulationTime,
      impediments: [...value.impediments],
    }));
    this.lastRevision = revision;
    this.lastObservedAt = simulationTime;
    this.cached = this.registry.definitions.roadSegments.map((segment) => {
      const points = this.registry.getRoadPolyline(segment.id);
      const length = emergentPolylineLength(points);
      const longitudinalSamples = Math.max(2, Math.min(
        this.maximumSamplesPerSegment,
        Math.ceil(length / segment.sampleSpacing) + 1,
      ));
      // Each longitudinal station reports the shallowest continuous lane
      // candidate across the sampled road width. Snow banks at the edge of a
      // freshly plowed track remain physical without falsely blocking the
      // route that runs between them.
      const laneDepths: number[] = [];
      let physicalSampleCount = 0;
      for (let index = 0; index < longitudinalSamples; index += 1) {
        const normalized = longitudinalSamples > 1
          ? index / (longitudinalSamples - 1)
          : 0.5;
        // Junction centres are wider than a road strip and the plow blade is
        // physically ahead of the vehicle. Sampling the exact graph node
        // would require reversing past every turn before a route could open.
        // Ignore only the first/last 1.6 m; the full lane between junctions
        // remains physical and snow-authoritative.
        const endInset = Math.min(0.2, 1.6 / Math.max(0.001, length));
        const progress = endInset + normalized * (1 - endInset * 2);
        const center = prototypeGlobalToLocalPosition(sampleEmergentPolyline(points, progress));
        const before = prototypeGlobalToLocalPosition(sampleEmergentPolyline(points, Math.max(0, progress - 0.01)));
        const after = prototypeGlobalToLocalPosition(sampleEmergentPolyline(points, Math.min(1, progress + 0.01)));
        const heading = Math.atan2(after.x - before.x, after.z - before.z);
        const rightX = Math.cos(heading);
        const rightZ = -Math.sin(heading);
        const crossSection = [-1, -0.5, 0, 0.5, 1]
          .map((factor) => factor * segment.sampleHalfWidth)
          .map((lateral) =>
            this.snow.sampleDepth(
              center.x + rightX * lateral,
              center.z + rightZ * lateral,
            ));
        physicalSampleCount += crossSection.length;
        laneDepths.push(Math.min(...crossSection));
      }
      const averageDepth = laneDepths.reduce((sum, value) => sum + value, 0) / Math.max(1, laneDepths.length);
      const maximumDepth = Math.max(0, ...laneDepths);
      const deepSampleRatio = laneDepths.filter((value) => value >= segment.condition.blockedAverageDepth).length / Math.max(1, laneDepths.length);
      return {
        segmentId: segment.id,
        measuredAt: simulationTime,
        sourceRevision: revision,
        sampleCount: physicalSampleCount,
        averageDepth,
        maximumDepth,
        deepSampleRatio,
        impediments: averageDepth >= segment.condition.degradedAverageDepth ? ['DEEP_SNOW'] : [],
      } satisfies RoadSurfaceObservation;
    });
    return this.cached.map((value) => ({ ...value, impediments: [...value.impediments] }));
  }
}
