export const createResolvedOceanVisualProfile =
  (): ResolvedOceanVisualProfile => ({
    deepColor: new Color(),
    midColor: new Color(),
    shallowColor: new Color(),
    lightColor: new Color(),
    foamColor: new Color(),
    clarityStrength: 0,
    depthContrast: 1,
    waveHighlightStrength: 1,
    currentRibbonStrength: 1,
    edgeFoamStrength: 1,
    windShimmerStrength: 1,
    skyReflectionStrength: 1,
    waterBrightness: 1,
    microNormalStrength: CURRENT_PROFILE.microNormalStrength,
    fresnelStrength: CURRENT_PROFILE.fresnelStrength,
    sunGlintIntensity: CURRENT_PROFILE.sunGlintIntensity,
    moonGlintIntensity: CURRENT_PROFILE.moonGlintIntensity,
    oceanV2Blend: 0,
    oceanV3Blend: 0,
  });

export const resolveOceanVisualProfile = (
  id: VisualProfileId,
  presentation: Readonly<EnvironmentPresentationState>,
  target: ResolvedOceanVisualProfile,
): ResolvedOceanVisualProfile => {
  const profile = VISUAL_PROFILES[id];
  const colors = PROFILE_COLORS[id];
  const daylightRetention =
    1 - presentation.night * 0.68;
  const colorBlend =
    profile.colorBlend * (0.72 + daylightRetention * 0.28);

  target.deepColor
    .copy(presentation.seaDeepColor)
    .lerp(colors.deep, colorBlend);
  target.midColor
    .copy(presentation.seaMidColor)
    .lerp(colors.mid, colorBlend);
  target.shallowColor
    .copy(presentation.seaShallowColor)
    .lerp(colors.shallow, colorBlend);
  target.lightColor
    .copy(presentation.seaLightColor)
    .lerp(colors.light, colorBlend);
  target.foamColor
    .setHex(CURRENT_PROFILE.foamColor)
    .lerp(colors.foam, profile.colorBlend);
  target.clarityStrength = profile.clarityStrength;
  target.depthContrast = profile.depthContrast;
  target.waveHighlightStrength = profile.waveHighlightStrength;
  target.currentRibbonStrength = profile.currentRibbonStrength;
  target.edgeFoamStrength = profile.edgeFoamStrength;
  target.windShimmerStrength = profile.windShimmerStrength;
  target.skyReflectionStrength = profile.skyReflectionStrength;
  target.waterBrightness = profile.waterBrightness;
  target.microNormalStrength = profile.microNormalStrength;
  target.fresnelStrength = profile.fresnelStrength;
  target.sunGlintIntensity = profile.sunGlintIntensity;
  target.moonGlintIntensity = profile.moonGlintIntensity;
  target.oceanV2Blend = profile.oceanV2Blend;
  target.oceanV3Blend = profile.oceanV3Blend;
  return target;
};

export class VisualProfileController {
  private id: VisualProfileId;

  public constructor(
    initial: VisualProfileId = DEFAULT_VISUAL_PROFILE_ID,
  ) {
    this.id = initial;
  }

  public getId(): VisualProfileId {
    return this.id;
  }

  public getProfile(): Readonly<OceanVisualProfile> {
    return VISUAL_PROFILES[this.id];
  }

  public set(id: VisualProfileId): VisualProfileId {
    this.id = id;
    return this.id;
  }

  public cycle(): VisualProfileId {
    const current = PROFILE_ORDER.indexOf(this.id);
    this.id =
      PROFILE_ORDER[(current + 1) % PROFILE_ORDER.length] ??
      DEFAULT_VISUAL_PROFILE_ID;
    return this.id;
  }
}
