import type { Mesh, Object3D, Scene } from 'three';
import type { IsolationFeature, PerformanceIsolation } from './PerformanceIsolation';

/** Scoped writes are restored before gameplay, collisions, selection or saves can run. */
export class IsolationRenderScope {
  private readonly restores: (() => void)[] = [];
  public set<T extends object, K extends keyof T>(object: T, key: K, value: T[K]): void {
    if (object[key] === value) return;
    const previous = object[key];
    this.restores.push(() => { object[key] = previous; }); object[key] = value;
  }
  public restore(): void { for (let i = this.restores.length - 1; i >= 0; i--) this.restores[i]!(); this.restores.length = 0; }
}

/** Stable prefab metadata first; names cover existing pooled presenters without changing their lifecycle. */
export const isolationFeaturesForObject = (object: Object3D): IsolationFeature[] => {
  const name = object.name.toLowerCase();
  const prefab = String(object.userData.worldAssetPrefabId ?? object.userData.assetId ?? '').toLowerCase();
  const text = `${name} ${prefab}`;
  const features = new Set<IsolationFeature>();
  if (/conifer|spruce|pine|deciduous|birch|young-tree|tree shadow|forest_hlod|tree_/.test(text)) features.add('trees');
  if (/rock|boulder/.test(text) && !/drill|blast|tool/.test(text)) features.add('rocks');
  if (/bush|shrub|grass|heather|groundcover|fern|reed|berry|berries|wind-carried|windborne/.test(text)) features.add('vegetation');
  if (/animal|wildlife|fauna|wolf|rabbit|bunny|deer|raven|crow|bear|fox|hare|bird/.test(text) && !/track|impression|home/.test(text)) features.add('animals');
  if (name.startsWith('player-built')) features.add('buildings');
  if (name.startsWith('charred collapsed structure')) features.add('debris');
  if (/terrain top|terrain cliff|distant terrain underlay/.test(name)) features.add('terrain');
  if (/terrain top/.test(name)) features.add('terrainNear');
  if (/distant terrain underlay/.test(name)) features.add('terrainFar');
  if (/terrain cliff/.test(name)) features.add('terrainCliffs');
  if (/generated lakes|generated freezing|water surface|ice surface|hydrology|authored inland water/.test(name) && !name.startsWith('generated macro world')) features.add('water');
  if (name === 'borealis deformable land snow tiles') { features.add('snow'); features.add('snowBase'); }
  if (name === 'snow v5 local hierarchical microdetail') { features.add('snow'); features.add('snowDetail'); }
  if (name === 'persistent winter surface · medium lod') { features.add('snow'); features.add('snowMiddle'); }
  if (name.startsWith('snow v4')) features.add('snow');
  if (/surface snow|mesh-shaped snow|snow shroud|snow-covered town roofs/.test(name)) { features.add('assetSnow'); features.add('snow'); }
  if (/gpu instanced ots snowfall|quarks snowfall batch|snowfall emitter/.test(name)) features.add('snowfall');
  if (/windblown powder|airborne snow crystals|wind streak/.test(name)) features.add('spindrift');
  if (/world-space volumetric cloud|cloud library|cloud mesh library|baked cloud/.test(name)) features.add('clouds');
  if (/snowfall curtain/.test(name)) features.add('curtains');
  if (/spatial fog/.test(name)) features.add('fog');
  if (name === 'physical arctic atmosphere' || name === 'arctic photographic sky backdrop') features.add('atmosphere');
  if (name === 'arctic weather sky layer') features.add('sky');
  if (name === 'solar retinal glare') features.add('glare');
  if (/smoke/.test(name)) features.add('smoke');
  if (/volumetric fire|billboard campfire flames|fire embers/.test(name)) features.add('fire');
  if (/built fire direct light|built fire interior bounce|pooled wilderness campfire light/.test(name)) features.add('fireLights');
  // New presenters may opt in without requiring a naming convention.
  for (const id of object.userData.performanceIsolationFeatures ?? []) features.add(id);
  return [...features];
};

export class ScenePerformanceIsolation {
  private cache = new WeakMap<Object3D, { name: string; prefab: unknown; tags: unknown; features: IsolationFeature[] }>();
  public lastHiddenObjects = 0;
  public apply(scene: Scene, isolation: PerformanceIsolation, scope: IsolationRenderScope): void {
    this.lastHiddenObjects = 0;
    // A/B/A traverses both A and B so classification overhead is comparable.
    if (!isolation.active && !isolation.running) return;
    const visit = (object: Object3D, inheritedTree = false, inheritedSnow = false, inheritedTerrain = false): void => {
      if (!object.visible) return;
      const prefab = object.userData.worldAssetPrefabId ?? object.userData.assetId;
      const tags = object.userData.performanceIsolationFeatures;
      let cached = this.cache.get(object);
      if (!cached || cached.name !== object.name || cached.prefab !== prefab || cached.tags !== tags) {
        cached = { name: object.name, prefab, tags, features: isolationFeaturesForObject(object) }; this.cache.set(object, cached);
      }
      if (cached.features.some(id => !isolation.enabled(id))) { scope.set(object, 'visible', false); this.lastHiddenObjects++; }
      const tree = inheritedTree || cached.features.includes('trees');
      const snow = inheritedSnow || cached.features.includes('assetSnow');
      const terrain = inheritedTerrain || cached.features.includes('terrain');
      if (tree && snow && !isolation.enabled('treeSnow')) { scope.set(object, 'visible', false); this.lastHiddenObjects++; }
      if ((object as Mesh).isMesh) {
        const mesh = object as Mesh;
        // Empty material list suppresses this mesh, NOT its snow children, and
        // does not mutate materials shared by unrelated assets.
        if (tree && !snow && !isolation.enabled('treeModels')) { scope.set(mesh, 'material', []); this.lastHiddenObjects++; }
        if ((tree && !isolation.enabled('treeShadows')) || (terrain && !isolation.enabled('terrainShadowCasting'))) scope.set(mesh, 'castShadow', false);
      }
      const farSnow = object.userData.performanceIsolationUniforms?.snowFar;
      if (farSnow && (!isolation.enabled('snowFar') || !isolation.enabled('snow'))) scope.set(farSnow, 'value', 0);
      // Still classify children in both A/B paths: avoids conflating traversal cost with render cost.
      for (const child of object.children) visit(child, tree, snow, terrain);
    };
    visit(scene);
  }
}
