declare const icewayNetworkBrand: unique symbol;

type BrandedString<TName extends string> = string & {
  readonly [icewayNetworkBrand]: TName;
};

type BrandedNumber<TName extends string> = number & {
  readonly [icewayNetworkBrand]: TName;
};

export type SessionId = BrandedString<'SessionId'>;
export type ConnectionId = BrandedString<'ConnectionId'>;
export type PlayerId = BrandedString<'PlayerId'>;
export type PersistentEntityId = BrandedString<'PersistentEntityId'>;
export type TransientEntityId = BrandedString<'TransientEntityId'>;
export type NetworkEntityId = PersistentEntityId | TransientEntityId;
export type DefinitionId = BrandedString<'DefinitionId'>;
export type ControlSlotId = BrandedString<'ControlSlotId'>;
export type ControlLeaseId = BrandedString<'ControlLeaseId'>;
export type TransactionId = BrandedString<'TransactionId'>;
export type SessionEpoch = BrandedNumber<'SessionEpoch'>;
export type ServerTick = BrandedNumber<'ServerTick'>;
export type CommandSequence = BrandedNumber<'CommandSequence'>;
export type StreamSequence = BrandedNumber<'StreamSequence'>;
export type Revision = BrandedNumber<'Revision'>;

const asNonEmptyId = <TName extends string>(
  value: string,
  label: string,
): BrandedString<TName> => {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new Error(`${label} must be a non-empty string.`);
  }
  if (value.length > 160) {
    throw new Error(`${label} must not exceed 160 characters.`);
  }
  return value as BrandedString<TName>;
};

const asMonotonicNumber = <TName extends string>(
  value: number,
  label: string,
): BrandedNumber<TName> => {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(`${label} must be a non-negative safe integer.`);
  }
  return value as BrandedNumber<TName>;
};

export const sessionId = (value: string): SessionId =>
  asNonEmptyId<'SessionId'>(value, 'SessionId');
export const connectionId = (value: string): ConnectionId =>
  asNonEmptyId<'ConnectionId'>(value, 'ConnectionId');
export const playerId = (value: string): PlayerId =>
  asNonEmptyId<'PlayerId'>(value, 'PlayerId');
export const persistentEntityId = (value: string): PersistentEntityId =>
  asNonEmptyId<'PersistentEntityId'>(value, 'PersistentEntityId');
export const transientEntityId = (value: string): TransientEntityId =>
  asNonEmptyId<'TransientEntityId'>(value, 'TransientEntityId');
export const networkEntityId = (value: string): NetworkEntityId =>
  asNonEmptyId<'PersistentEntityId'>(value, 'NetworkEntityId') as NetworkEntityId;
export const definitionId = (value: string): DefinitionId =>
  asNonEmptyId<'DefinitionId'>(value, 'DefinitionId');
export const controlSlotId = (value: string): ControlSlotId =>
  asNonEmptyId<'ControlSlotId'>(value, 'ControlSlotId');
export const controlLeaseId = (value: string): ControlLeaseId =>
  asNonEmptyId<'ControlLeaseId'>(value, 'ControlLeaseId');
export const transactionId = (value: string): TransactionId =>
  asNonEmptyId<'TransactionId'>(value, 'TransactionId');

export const sessionEpoch = (value: number): SessionEpoch =>
  asMonotonicNumber<'SessionEpoch'>(value, 'SessionEpoch');
export const serverTick = (value: number): ServerTick =>
  asMonotonicNumber<'ServerTick'>(value, 'ServerTick');
export const commandSequence = (value: number): CommandSequence =>
  asMonotonicNumber<'CommandSequence'>(value, 'CommandSequence');
export const streamSequence = (value: number): StreamSequence =>
  asMonotonicNumber<'StreamSequence'>(value, 'StreamSequence');
export const revision = (value: number): Revision =>
  asMonotonicNumber<'Revision'>(value, 'Revision');

export const INITIAL_SESSION_EPOCH = sessionEpoch(1);
export const INITIAL_REVISION = revision(1);
export const ZERO_REVISION = revision(0);
export const ZERO_SERVER_TICK = serverTick(0);

export const nextRevision = (current: Revision): Revision =>
  revision(current + 1);
export const nextServerTick = (current: ServerTick): ServerTick =>
  serverTick(current + 1);

export type JsonPrimitive = string | number | boolean | null;
export type JsonValue =
  | JsonPrimitive
  | readonly JsonValue[]
  | { readonly [key: string]: JsonValue };
export type JsonObject = { readonly [key: string]: JsonValue };

export const isPlainJsonObject = (value: unknown): value is JsonObject => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
};

export const isJsonValue = (value: unknown, depth = 0): value is JsonValue => {
  if (depth > 24) return false;
  if (
    value === null ||
    typeof value === 'string' ||
    typeof value === 'boolean'
  ) {
    return true;
  }
  if (typeof value === 'number') return Number.isFinite(value);
  if (Array.isArray(value)) {
    return value.length <= 4_096 && value.every((item) => isJsonValue(item, depth + 1));
  }
  if (!isPlainJsonObject(value)) return false;
  const entries = Object.entries(value);
  return (
    entries.length <= 1_024 &&
    entries.every(
      ([key, child]) => key.length <= 160 && isJsonValue(child, depth + 1),
    )
  );
};
