import type { SurvivalBuildV3Piece } from './SurvivalBuildV3Model';
import { roofMemberPoints, roofPointDistance } from './SurvivalModularRoof';
import { isSimpleRoof, simpleRoofIsCover } from './SurvivalSimpleRoof';

/** Gameplay capacity in cubic metres of settled snow, not engineering units.
 * Construction topology is immutable for the lifetime of this small graph.
 * Legacy members terminate transfers: old saves never acquire new failures. */
export class SurvivalBuildV4SnowLoads {
  readonly pieces: ReadonlyMap<string, SurvivalBuildV3Piece>;
  readonly capacities = new Map<string, number>();
  readonly areas = new Map<string, number>();
  private readonly parents = new Map<string, readonly string[]>();
  private readonly bearingCounts = new Map<string, number>();
  private readonly order: string[] = [];
  readonly cyclic: boolean;

  constructor(pieces: readonly SurvivalBuildV3Piece[], isSupported: (id: string) => boolean = () => true,
    simpleCapacity:(piece:SurvivalBuildV3Piece)=>number=()=>2.4) {
    const known = new Set(pieces.map(p => p.id));
    this.pieces = new Map(pieces.filter(p => p.roofMember?.loadRules === 1 ||
      (p.freePose&&isSimpleRoof(p.definitionId))).map(p => [p.id, p]));
    const children = new Map<string, number>();
    for (const [id, p] of this.pieces) {
      if(isSimpleRoof(p.definitionId)){
        this.parents.set(id,[]);this.bearingCounts.set(id,0);
        // Basic modules have a bounded local snow reserve. No cyclic tile-to-
        // tile load redistribution; extra physical timbers raise the reserve.
        this.capacities.set(id,Math.max(.1,simpleCapacity(p)));
        if(simpleRoofIsCover(p.definitionId))this.areas.set(id,p.definitionId.includes('RIDGE')?1.2:4);
        continue;
      }
      const m = p.roofMember!, run = roofPointDistance(m.start, m.end);
      const bearings = [...new Set(m.supports)].filter(parent => parent !== id && known.has(parent) && isSupported(parent));
      const parents = bearings.filter(parent => this.pieces.has(parent));
      this.bearingCounts.set(id, bearings.length);
      this.parents.set(id, parents);
      const tied = parents.some(parent => ['CROSS_BEAM', 'SPINE_BEAM'].includes(this.pieces.get(parent)!.roofMember!.kind));
      const braced = parents.some(parent => this.pieces.get(parent)!.roofMember!.kind === 'BRACE');
      const capacity = m.kind === 'RAFTER' ? 2.4 * 4 / Math.max(2, run) * (tied ? 1.8 : 1) * (braced ? 1.3 : 1)
        : m.kind === 'BATTEN' ? 3 * 4 / Math.max(2, run)
        : ['CROSS_BEAM', 'SPINE_BEAM', 'RIDGE_BEAM'].includes(m.kind) ? 20 * 4 / Math.max(2, run)
        : 100;
      this.capacities.set(id, capacity);
      if (m.kind === 'COVER') {
        const points = roofMemberPoints(m);
        // Horizontal catchment area, not the inflated sloping surface area.
        this.areas.set(id, Math.abs(points.reduce((a, p, i) => {
          const q = points[(i + 1) % points.length]!; return a + p.x * q.z - q.x * p.z;
        }, 0)) / 2);
      }
      for (const parent of parents) children.set(parent, (children.get(parent) ?? 0) + 1);
    }
    const ready = [...this.pieces.keys()].filter(id => !children.get(id)).sort();
    while (ready.length) {
      const id = ready.pop()!; this.order.push(id);
      for (const parent of this.parents.get(id) ?? []) {
        const remaining = (children.get(parent) ?? 0) - 1; children.set(parent, remaining);
        if (!remaining) ready.push(parent);
      }
    }
    this.cyclic = this.order.length !== this.pieces.size;
  }

  evaluate(depthMetres: ReadonlyMap<string, number>): ReadonlyMap<string, { load: number; capacity: number; ratio: number }> {
    const loads = new Map<string, number>();
    for (const [id, area] of this.areas) loads.set(id, area * Math.max(0, depthMetres.get(id) ?? 0));
    // Invalid imported cycles never cause a hang or a phantom cascade.
    if (this.cyclic) return new Map();
    for (const id of this.order) {
      const parents = this.parents.get(id) ?? [], load = loads.get(id) ?? 0;
      // Divide across ALL physical bearings, including legacy bearing sinks.
      const count = this.bearingCounts.get(id) ?? 0;
      for (const parent of parents) loads.set(parent, (loads.get(parent) ?? 0) + load / Math.max(1, count));
    }
    return new Map([...this.capacities].map(([id, capacity]) => {
      const load = loads.get(id) ?? 0; return [id, { load, capacity, ratio: load / capacity }];
    }));
  }
}

/** Eight seconds to react at overload, longer near the limit. Repair/melting
 * recovers the warning. No one-frame impulse may collapse a roof. */
export function snowLoadWarningSeconds(previous: number, ratio: number, seconds: number): number {
  const dt = Math.max(0, Math.min(2, seconds));
  return Math.max(0, Math.min(8, previous + (ratio > 1 ? Math.min(1, (ratio - 1) * 2) : -2) * dt));
}
