export interface EmergentDirectorDecision {
  allowed: boolean;
  reason: 'STORY_CRITICAL' | 'WITHIN_BUDGET' | 'INCIDENT_BUDGET_FULL' | 'REPORT_COOLDOWN';
}

interface DirectorSaveData {
  version: 1;
  lastReportAt: number;
  surfacedIncidentIds: string[];
}

export class EmergentWorldDirector {
  private lastReportAt = Number.NEGATIVE_INFINITY;
  private readonly surfacedIncidentIds = new Set<string>();

  public constructor(
    private readonly maximumReportedIncidents: number,
    private readonly minimumReportIntervalSeconds: number,
    saved?: unknown,
  ) {
    this.importState(saved);
  }

  public decide(
    incidentId: string,
    simulationTime: number,
    activeReportedIncidents: number,
    storyCritical = false,
  ): EmergentDirectorDecision {
    if (storyCritical) return { allowed: true, reason: 'STORY_CRITICAL' };
    if (this.surfacedIncidentIds.has(incidentId)) return { allowed: true, reason: 'WITHIN_BUDGET' };
    if (activeReportedIncidents >= this.maximumReportedIncidents) {
      return { allowed: false, reason: 'INCIDENT_BUDGET_FULL' };
    }
    if (simulationTime - this.lastReportAt < this.minimumReportIntervalSeconds) {
      return { allowed: false, reason: 'REPORT_COOLDOWN' };
    }
    return { allowed: true, reason: 'WITHIN_BUDGET' };
  }

  public markSurfaced(incidentId: string, simulationTime: number): void {
    this.surfacedIncidentIds.add(incidentId);
    this.lastReportAt = simulationTime;
  }

  public exportState(): DirectorSaveData {
    return { version: 1, lastReportAt: Number.isFinite(this.lastReportAt) ? this.lastReportAt : -1, surfacedIncidentIds: [...this.surfacedIncidentIds].sort() };
  }

  private importState(saved: unknown): boolean {
    const candidate = saved as Partial<DirectorSaveData> | undefined;
    if (candidate?.version !== 1 || !Array.isArray(candidate.surfacedIncidentIds)) return false;
    this.lastReportAt = Number.isFinite(candidate.lastReportAt) && candidate.lastReportAt! >= 0
      ? candidate.lastReportAt!
      : Number.NEGATIVE_INFINITY;
    candidate.surfacedIncidentIds.filter((id): id is string => typeof id === 'string' && id.length > 0).forEach((id) => this.surfacedIncidentIds.add(id));
    return true;
  }
}

