import { Group, MathUtils, Matrix4 } from 'three';
import type { WorldAssetPlacementSystem } from '../../land/WorldAssetPlacementSystem';

/** Both the visible boards and their snow receivers live under the same hinge. */
export function createSurvivalWindowPresentation(
  root: Group,
  bank: WorldAssetPlacementSystem | undefined,
  prefabId: string,
  initialOpen: boolean,
  initialSnow: number,
) {
  const leaves = ([-1, 1] as const).flatMap((side) => {
    const prefix = `survival-window-leaf-${side < 0 ? 'left' : 'right'}-`;
    const parts = root.children.filter((part) => part.name.startsWith(prefix));
    if (!parts.length) return [];
    const hinge = new Group();
    hinge.name = `${prefix}hinge`;
    hinge.position.set(side * 0.46, 0, -0.23);
    root.add(hinge);
    for (const part of parts) {
      part.position.sub(hinge.position);
      hinge.add(part);
    }
    const snow = bank?.createRuntimeSnowBatch?.(prefabId, 1, { includeRolePrefixes: [prefix] });
    if (snow) {
      snow.setMatrixAt(0, new Matrix4()); snow.setAmountAt(0, initialSnow);
      snow.setCount(1); snow.commit(); snow.root.position.copy(hinge.position).negate();
      snow.root.visible = initialSnow > 0.008;
      hinge.add(snow.root);
    }
    return [{ hinge, snow, side }];
  });
  let opening = initialOpen ? 1 : 0;
  const pose = () => {
    for (const leaf of leaves) leaf.hinge.rotation.y = leaf.side * MathUtils.degToRad(145) * opening;
  };
  pose();
  return {
    update(open: boolean, delta: number) {
      opening += ((open ? 1 : 0) - opening) * (1 - Math.exp(-8 * Math.min(0.1, delta)));
      pose();
    },
    setSnow(amount: number, opacity: number) {
      for (const leaf of leaves) {
        leaf.snow?.setAmountAt(0, amount); leaf.snow?.commit(false);
        if (leaf.snow) leaf.snow.root.visible = amount > 0.008 && opacity > 0.52;
      }
    },
    setVisibleSnow(visible: boolean) { for (const leaf of leaves) if (leaf.snow) leaf.snow.root.visible = visible; },
    dispose() { for (const leaf of leaves) leaf.snow?.dispose(); },
    get opening() { return opening; },
    get receiverCount() { return leaves.filter((leaf) => leaf.snow).length; },
  };
}
