import { clamp, smoothstep } from '../utils/math';

/**
 * Shared ownership policy for the winter surface.
 *
 * The previous renderer let three unrelated surfaces overlap: 25 cm snow,
 * 2 m mainland terrain and an 8 m macro snow-coloured underlay. On curved
 * slopes the coarse triangles could cross the finer surface and appear as
 * bright squares. Fine vertices now morph onto the actual coarser triangles;
 * fragment ownership changes only after their heights match. No dual sinking.
 */
export const WINTER_WORLD_LOD = Object.freeze({
  /** Canonical 25 cm snow is guaranteed throughout this radius. */
  deformableSnowRadiusMetres: 46,
  /**
   * Fine snow must reach the two-metre surface before the nearest possible
   * edge of the square canonical ring (48 m). The old 46–68 m handoff left a
   * sunken strip with no visible owner when looking back down a nearby hill.
   */
  midSnowInnerFadeStartMetres: 36,
  midSnowInnerFadeEndMetres: 46,
  /** Detailed mainland chunks cover at least this much in every direction. */
  detailedTerrainSafeRadiusMetres: 238,
  /** MID vertices converge onto actual macro triangles over this band. */
  macroOwnershipFadeStartMetres: 270,
  macroOwnershipFadeEndMetres: 300,
  /** Mid snow hands the visible surface to the macro field here. */
  midSnowOuterFadeStartMetres: 270,
  midSnowOuterFadeEndMetres: 300,
  /** Bare terrain underlay safety only. Never sink both visible snow owners. */
  hiddenSurfaceSinkMetres: 2.4,
  /** Visible HLOD ecology range. */
  ecologyHorizonMetres: 2_260,
  /** Perspective exploration camera range; haze still owns the visual fade. */
  perspectiveFarMetres: 5_200,
});

export interface WinterSurfaceLodWeights {
  readonly deformable: number;
  readonly mid: number;
  readonly macro: number;
}

/** Continuous height-morph weights; these are NOT alpha/opacity weights. */
export const resolveWinterSurfaceLodWeights = (
  distanceMetres: number,
): WinterSurfaceLodWeights => {
  const distance = Math.max(0, distanceMetres);
  const deformable = 1 - smoothstep(
    WINTER_WORLD_LOD.midSnowInnerFadeStartMetres,
    WINTER_WORLD_LOD.midSnowInnerFadeEndMetres,
    distance,
  );
  const macro = smoothstep(
    WINTER_WORLD_LOD.macroOwnershipFadeStartMetres,
    WINTER_WORLD_LOD.macroOwnershipFadeEndMetres,
    distance,
  );
  const mid = (1 - deformable) * (1 - macro);
  const sum = Math.max(0.0001, deformable + mid + macro);
  return {
    deformable: clamp(deformable / sum, 0, 1),
    mid: clamp(mid / sum, 0, 1),
    macro: clamp(macro / sum, 0, 1),
  };
};
