import {
  ACHIEVEMENT_STAT_IDS,
  type AchievementDefinition,
  type AchievementStatId,
} from './AchievementDefinitions';

export type AchievementStatValues = Record<
  AchievementStatId,
  number
>;

export type AchievementStatUpdate = Partial<
  AchievementStatValues
>;

export interface AchievementUnlock {
  achievementId: string;
  unlockedAt: number;
}

export interface AchievementProgress {
  definition: AchievementDefinition;
  currentValue: number;
  progress: number;
  unlocked: boolean;
  unlockedAt?: number;
}

export interface AchievementSaveData {
  version: 1;
  stats: AchievementStatValues;
  unlocks: AchievementUnlock[];
}

const emptyStats = (): AchievementStatValues => ({
  DISTANCE_TRAVELLED_KM: 0,
  ICE_CELLS_BROKEN: 0,
  FUEL_USED: 0,
  TIME_AT_HELM_SECONDS: 0,
  PORTS_CLEARED: 0,
  ROUTES_OPENED: 0,
  MISSIONS_COMPLETED: 0,
});

const safeValue = (value: unknown): number =>
  typeof value === 'number' && Number.isFinite(value)
    ? Math.max(0, value)
    : 0;

export class AchievementSystem {
  private readonly definitions:
    readonly AchievementDefinition[];
  private readonly definitionIds = new Set<string>();
  private readonly stats = emptyStats();
  private readonly unlocks =
    new Map<string, AchievementUnlock>();

  public constructor(
    definitions: readonly AchievementDefinition[],
    saved?: Readonly<AchievementSaveData>,
  ) {
    this.definitions = definitions.map((definition) => ({
      ...definition,
    }));
    for (const definition of this.definitions) {
      if (
        !definition.id ||
        this.definitionIds.has(definition.id) ||
        !ACHIEVEMENT_STAT_IDS.includes(definition.statId) ||
        !Number.isFinite(definition.threshold) ||
        definition.threshold <= 0
      ) {
        throw new Error(
          `Invalid achievement definition "${definition.id}".`,
        );
      }
      this.definitionIds.add(definition.id);
    }
    if (saved) this.importState(saved);
  }

  public record(
    deltas: Readonly<AchievementStatUpdate>,
    unlockedAt: number,
  ): readonly AchievementUnlock[] {
    for (const statId of ACHIEVEMENT_STAT_IDS) {
      const delta = deltas[statId];
      if (
        delta === undefined ||
        !Number.isFinite(delta) ||
        delta <= 0
      ) {
        continue;
      }
      this.stats[statId] += delta;
    }
    return this.evaluate(unlockedAt);
  }

  public synchronizeMinimums(
    minimums: Readonly<AchievementStatUpdate>,
    unlockedAt: number,
    announce = false,
  ): readonly AchievementUnlock[] {
    for (const statId of ACHIEVEMENT_STAT_IDS) {
      const minimum = minimums[statId];
      if (minimum === undefined || !Number.isFinite(minimum)) {
        continue;
      }
      this.stats[statId] = Math.max(
        this.stats[statId],
        Math.max(0, minimum),
      );
    }
    const unlocks = this.evaluate(unlockedAt);
    return announce ? unlocks : [];
  }

  public getStats(): AchievementStatValues {
    return { ...this.stats };
  }

  public getProgress(): readonly AchievementProgress[] {
    return this.definitions.map((definition) => {
      const currentValue = this.stats[definition.statId];
      const unlock = this.unlocks.get(definition.id);
      return {
        definition: { ...definition },
        currentValue,
        progress: Math.min(
          1,
          currentValue / definition.threshold,
        ),
        unlocked: Boolean(unlock),
        unlockedAt: unlock?.unlockedAt,
      };
    });
  }

  public exportState(): AchievementSaveData {
    return {
      version: 1,
      stats: this.getStats(),
      unlocks: [...this.unlocks.values()].map((unlock) => ({
        ...unlock,
      })),
    };
  }

  public importState(
    saved: Readonly<AchievementSaveData>,
  ): boolean {
    if (
      saved.version !== 1 ||
      !saved.stats ||
      !Array.isArray(saved.unlocks)
    ) {
      return false;
    }
    for (const statId of ACHIEVEMENT_STAT_IDS) {
      this.stats[statId] = safeValue(saved.stats[statId]);
    }
    this.unlocks.clear();
    for (const candidate of saved.unlocks) {
      if (
        !this.definitionIds.has(candidate.achievementId) ||
        !Number.isFinite(candidate.unlockedAt)
      ) {
        continue;
      }
      this.unlocks.set(candidate.achievementId, {
        achievementId: candidate.achievementId,
        unlockedAt: Math.max(0, candidate.unlockedAt),
      });
    }
    this.evaluate(0);
    return true;
  }

  private evaluate(
    unlockedAt: number,
  ): readonly AchievementUnlock[] {
    const newUnlocks: AchievementUnlock[] = [];
    for (const definition of this.definitions) {
      if (
        this.unlocks.has(definition.id) ||
        this.stats[definition.statId] < definition.threshold
      ) {
        continue;
      }
      const unlock = {
        achievementId: definition.id,
        unlockedAt: Math.max(0, unlockedAt),
      };
      this.unlocks.set(definition.id, unlock);
      newUnlocks.push({ ...unlock });
    }
    return newUnlocks;
  }
}

