import type { SurvivalBuildPieceId } from '../SurvivalBuildingCatalog';
import { survivalBuildV3LocalToWorld, type SurvivalBuildV3Frame } from './SurvivalBuildV3Model';

export type RoofPoint = Readonly<{ x: number; y: number; z: number }>;
export type ModularRoofKind = 'CROSS_BEAM' | 'SPINE_BEAM' | 'RIDGE_POST' | 'RAFTER' | 'COVER' |
  'RIDGE_BEAM' | 'SUPPORT_POST' | 'BRACE' | 'BATTEN' | 'GABLE';
export const MODULAR_ROOF_IDS: Readonly<Record<ModularRoofKind, SurvivalBuildPieceId>> = {
  CROSS_BEAM: 'ROOF_CROSS_BEAM', SPINE_BEAM: 'ROOF_SPINE_BEAM',
  RIDGE_POST: 'ROOF_RIDGE_POST', RAFTER: 'ROOF_RAFTER', COVER: 'ROOF_COVER', GABLE: 'ROOF_GABLE',
  RIDGE_BEAM: 'ROOF_RIDGE_BEAM', SUPPORT_POST: 'ROOF_SUPPORT_POST', BRACE: 'ROOF_BRACE', BATTEN: 'ROOF_BATTEN',
};
/** Site-local metres; never camera coordinates. Each timber is a real saved
 * piece. start is the fixed socket, end is the adjustable free end. */
export interface ModularRoofMember {
  /** Missing = the original wall-fitted roof. Never reinterpret old saves. */
  readonly rules?: 2;
  /** V4: physical wall bearings + snow capacity. Absent keeps legacy dry rules. */
  readonly loadRules?: 1;
  readonly kind: ModularRoofKind;
  readonly start: RoofPoint;
  readonly end: RoofPoint;
  readonly supports: readonly string[];
  readonly level: number;
  /** The matching, adjacent rafter for a single continuous sloping cover. */
  readonly farStart?: RoofPoint;
  readonly farEnd?: RoofPoint;
  /** Convex, planar, clipped cover tile. Shared by render/collision/weather. */
  readonly polygon?: readonly RoofPoint[];
  readonly coverSupports?: readonly Readonly<{kind:ModularRoofKind;start:RoofPoint;end:RoofPoint}>[];
}
export const modularRoofKind = (id: SurvivalBuildPieceId): ModularRoofKind | undefined =>
  (Object.keys(MODULAR_ROOF_IDS) as ModularRoofKind[]).find((k) => MODULAR_ROOF_IDS[k] === id);
export const roofPointDistance = (a: RoofPoint, b: RoofPoint) => Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
export const roofLerp = (a: RoofPoint, b: RoofPoint, t: number): RoofPoint => ({
  x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: a.z + (b.z - a.z) * t,
});
export const roofMemberPoints = (m: ModularRoofMember): readonly RoofPoint[] =>
  m.polygon ?? (m.kind === 'COVER' && m.farStart && m.farEnd ? [m.start, m.end, m.farEnd, m.farStart] : [m.start, m.end]);
const roofAxisSign = (v:number):number => Math.abs(v)<.0001?0:Math.sign(v);
export const roofMemberKey = (m: ModularRoofMember): string => `${m.kind}:` +
  (m.kind==='RIDGE_POST'||m.kind==='SUPPORT_POST'||m.kind==='BRACE'?[m.start]:m.kind==='RAFTER'?[m.start,
    {x:m.start.x+roofAxisSign(m.end.x-m.start.x),y:m.start.y,z:m.start.z+roofAxisSign(m.end.z-m.start.z)}]:roofMemberPoints(m))
    .map((p) => [p.x, p.y, p.z].map((v) => Math.round(v * 100)).join(',')).sort().join('/');
export const validRoofMember = (m: ModularRoofMember): boolean =>
  (m.loadRules === undefined || m.loadRules === 1 && m.rules === 2) &&
  Boolean(MODULAR_ROOF_IDS[m.kind]) && Number.isInteger(m.level) && m.level >= 0 &&
  (m.rules === 2 ? m.supports.length <= 64 : m.supports.length === (m.kind === 'RIDGE_POST' ? 1 : 2)) &&
  new Set(m.supports).size === m.supports.length && m.supports.every((id) => typeof id === 'string' && id.length > 0) &&
  roofMemberPoints(m).every((p) => [p.x, p.y, p.z].every(Number.isFinite)) &&
  roofPointDistance(m.start, m.end) >= (m.polygon ? .01 : .24) && roofPointDistance(m.start, m.end) <= 10 &&
  (m.rules === 2 && (m.kind === 'COVER' || m.kind === 'GABLE') ? Boolean(m.polygon && m.polygon.length>=3 && m.polygon.length<=8) : m.kind !== 'COVER' || Boolean(m.farStart && m.farEnd &&
    roofPointDistance(m.start, m.farStart) <= 2.05 && roofPointDistance(m.end, m.farEnd) <= 2.05));
export const roofMemberTransform = (frame: SurvivalBuildV3Frame, m: ModularRoofMember) => {
  const points = roofMemberPoints(m);
  const centre = points.reduce((p, q) => ({ x: p.x + q.x / points.length, y: 0, z: p.z + q.z / points.length }), {x:0,y:0,z:0});
  const base = { ...centre, y: Math.min(...points.map((p) => p.y)) - 0.08 };
  return { ...survivalBuildV3LocalToWorld(frame, base), yawDegrees: frame.yawDegrees };
};
export const roofMemberBounds = (m: ModularRoofMember) => {
  const p = roofMemberPoints(m);
  return { halfWidth: (Math.max(...p.map((q) => q.x)) - Math.min(...p.map((q) => q.x))) / 2 + 0.1,
    halfDepth: (Math.max(...p.map((q) => q.z)) - Math.min(...p.map((q) => q.z))) / 2 + 0.1,
    height: Math.max(...p.map((q) => q.y)) - Math.min(...p.map((q) => q.y)) + 0.16 };
};
/** Cover planes and their snow, shelter, smoke and walking height all use the
 * same slope. V1 accepts parallel rafters, so no twisted/CAD surface needed. */
export const roofCoverHeightAt = (m: ModularRoofMember, localX: number, localZ: number): number => {
  if(m.polygon && m.polygon.length>=3) {
    const [a,b,c]=m.polygon as readonly [RoofPoint,RoofPoint,RoofPoint,...RoofPoint[]];
    const ux=b.x-a.x,uy=b.y-a.y,uz=b.z-a.z,vx=c.x-a.x,vy=c.y-a.y,vz=c.z-a.z;
    const ny=uz*vx-ux*vz;
    if(Math.abs(ny)>.00001) return a.y-((uy*vz-uz*vy)*(localX-a.x)+(ux*vy-uy*vx)*(localZ-a.z))/ny;
  }
  const dx = m.end.x - m.start.x, dz = m.end.z - m.start.z;
  const t = Math.max(0, Math.min(1, ((localX - m.start.x) * dx + (localZ - m.start.z) * dz) / Math.max(.001, dx*dx + dz*dz)));
  return m.start.y + (m.end.y - m.start.y) * t;
};

export const roofCoverContains = (m: ModularRoofMember,x:number,z:number,padding=0):boolean => {
  const points=roofMemberPoints(m); let sign=0;
  for(let i=0;i<points.length;i++) {
    const a=points[i]!,b=points[(i+1)%points.length]!;
    const cross=(b.x-a.x)*(z-a.z)-(b.z-a.z)*(x-a.x);
    if(Math.abs(cross)<=padding*Math.hypot(b.x-a.x,b.z-a.z)+.00001) continue;
    if(sign && Math.sign(cross)!==sign) return false; sign=Math.sign(cross);
  }
  return true;
};
