import type { SaveData } from '../data/types';

export interface AsyncSaveRecord { savedAt: number; data: SaveData }
const DATABASE = 'iceway-progress-v1';
const STORE = 'checkpoints';

/** One atomic checkpoint. IDB owns serialization and durability; no JSON
 * construction or synchronous multi-megabyte localStorage write per autosave. */
export async function accessAsyncSave(record?: AsyncSaveRecord): Promise<AsyncSaveRecord | undefined> {
  if (typeof indexedDB === 'undefined') throw new Error('IndexedDB unavailable');
  const database = await new Promise<IDBDatabase>((resolve, reject) => {
    const request = indexedDB.open(DATABASE, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE);
    request.onerror = () => reject(request.error);
    request.onblocked = () => reject(new Error('Save database upgrade blocked'));
    request.onsuccess = () => resolve(request.result);
  });
  try {
    return await new Promise<AsyncSaveRecord | undefined>((resolve, reject) => {
      const transaction = database.transaction(STORE, record ? 'readwrite' : 'readonly');
      const store = transaction.objectStore(STORE);
      // IDB transactions serialize writes. Refuse an older queued checkpoint
      // even when two callers completed their async database opens out of order.
      const request = store.get('latest'); let result: AsyncSaveRecord | undefined;
      request.onsuccess = () => {
        result = request.result as AsyncSaveRecord | undefined;
        if (record && (!result || record.savedAt >= result.savedAt)) { store.put(record, 'latest'); result = record; }
      };
      transaction.oncomplete = () => resolve(result);
      transaction.onerror = () => reject(transaction.error);
      transaction.onabort = () => reject(transaction.error ?? new Error('Save transaction aborted'));
    });
  } finally { database.close(); }
}
