import type { ConstructionSurfaceId } from './ConstructionBlueprint';

export interface ConstructionSurfaceDefinition {
  id: ConstructionSurfaceId;
  label: string;
  description: string;
  roughness: number;
  metalness: number;
}

export const CONSTRUCTION_SURFACES: readonly ConstructionSurfaceDefinition[] = [
  {
    id: 'painted-steel',
    label: 'Painted steel',
    description: 'Durable marine paint over structural steel.',
    roughness: 0.48,
    metalness: 0.52,
  },
  {
    id: 'galvanized-steel',
    label: 'Galvanized steel',
    description: 'Hard utilitarian metal for frames, roofs and machinery.',
    roughness: 0.42,
    metalness: 0.76,
  },
  {
    id: 'weathered-timber',
    label: 'Weathered timber',
    description: 'Rough wood for fishing huts, piers and warm interiors.',
    roughness: 0.92,
    metalness: 0,
  },
  {
    id: 'marine-plywood',
    label: 'Marine plywood',
    description: 'Smooth sealed wood for lightweight cabins and fittings.',
    roughness: 0.7,
    metalness: 0,
  },
  {
    id: 'industrial-concrete',
    label: 'Industrial concrete',
    description: 'Heavy matte foundation finish for harbor facilities.',
    roughness: 1,
    metalness: 0,
  },
  {
    id: 'rubber',
    label: 'Black rubber',
    description: 'Soft low-gloss finish for fenders and seals.',
    roughness: 0.96,
    metalness: 0,
  },
] as const;

const surfacesById = new Map(
  CONSTRUCTION_SURFACES.map((surface) => [surface.id, surface]),
);

export const getConstructionSurface = (
  id: ConstructionSurfaceId,
): ConstructionSurfaceDefinition =>
  surfacesById.get(id) ?? CONSTRUCTION_SURFACES[0]!;

