import { clamp } from '../../utils/math';
import type { PortGameplayDefinition } from '../definitions/GameplayTypes';
import type { WorldContributionEvent } from '../events/WorldContributionEvent';

export type PortClearanceStatus =
  | 'FROZEN'
  | 'CLEARING'
  | 'CLEARED';

export interface PortClearanceObservation {
  portId: string;
  eligibleCells: number;
  openCells: number;
  openRatio: number;
  connectedToDock: boolean;
  connectedToExterior: boolean;
}

export interface PortClearanceState {
  portId: string;
  status: PortClearanceStatus;
  eligibleCells: number;
  openCells: number;
  openRatio: number;
  connectedToDock: boolean;
  connectedToExterior: boolean;
  clearedAt?: number;
}

export interface PortClearanceSaveData {
  version: 1;
  ports: PortClearanceState[];
}

export interface PortClearanceUpdateResult {
  clearedPortIds: string[];
  contributionEvents: WorldContributionEvent[];
}

const initialState = (portId: string): PortClearanceState => ({
  portId,
  status: 'FROZEN',
  eligibleCells: 0,
  openCells: 0,
  openRatio: 0,
  connectedToDock: false,
  connectedToExterior: false,
});

const copyState = (
  state: Readonly<PortClearanceState>,
): PortClearanceState => ({ ...state });

export const portClearanceCompletionProgress = (
  state: Readonly<PortClearanceState>,
  definition: Readonly<PortGameplayDefinition>,
): number => {
  if (state.status === 'CLEARED') return 1;

  const coverage = clamp(
    state.openRatio /
      Math.max(0.01, definition.iceAccess.requiredOpenRatio),
    0,
    1,
  );
  const connectionSatisfied =
    !definition.iceAccess.requireDockConnection ||
    (
      state.connectedToDock &&
      state.connectedToExterior
    );

  // Reserve 100% for the authoritative cleared state. When the
  // required dock connection is missing, keep a little more room
  // below completion so the HUD still communicates unfinished access.
  return Math.min(connectionSatisfied ? 0.994 : 0.984, coverage);
};

export class PortClearanceSystem {
  private readonly definitions = new Map<
    string,
    PortGameplayDefinition
  >();
  private readonly states = new Map<
    string,
    PortClearanceState
  >();

  public constructor(
    definitions: readonly PortGameplayDefinition[],
    saved?: Readonly<PortClearanceSaveData>,
    grandfatheredClearedPortIds: readonly string[] = [],
  ) {
    for (const definition of definitions) {
      this.definitions.set(definition.id, definition);
      this.states.set(definition.id, initialState(definition.id));
    }
    if (saved) this.importState(saved);
    for (const portId of grandfatheredClearedPortIds) {
      this.markCleared(portId, 0);
    }
  }

  public getState(
    portId: string,
  ): PortClearanceState | undefined {
    const state = this.states.get(portId);
    return state ? copyState(state) : undefined;
  }

  public getStates(): readonly PortClearanceState[] {
    return [...this.states.values()].map(copyState);
  }

  public getClearedPortIds(): readonly string[] {
    return [...this.states.values()].flatMap((state) =>
      state.status === 'CLEARED' ? [state.portId] : [],
    );
  }

  public isCleared(portId: string): boolean {
    return this.states.get(portId)?.status === 'CLEARED';
  }

  public getCompletionProgress(portId: string): number {
    const state = this.states.get(portId);
    const definition = this.definitions.get(portId);
    if (!state || !definition) return 0;
    return portClearanceCompletionProgress(state, definition);
  }

  public reset(): void {
    for (const portId of this.states.keys()) {
      this.states.set(portId, initialState(portId));
    }
  }

  public update(
    simulationTime: number,
    observations: readonly PortClearanceObservation[],
  ): PortClearanceUpdateResult {
    const byPort = new Map(
      observations.map((observation) => [
        observation.portId,
        observation,
      ]),
    );
    const clearedPortIds: string[] = [];
    const contributionEvents: WorldContributionEvent[] = [];

    for (const [portId, definition] of this.definitions) {
      const observation = byPort.get(portId);
      const state = this.states.get(portId)!;
      if (state.status === 'CLEARED') {
        if (observation) {
          state.eligibleCells = Math.max(
            0,
            Math.floor(observation.eligibleCells),
          );
        }
        state.openCells = state.eligibleCells;
        state.openRatio = 1;
        state.connectedToDock = true;
        state.connectedToExterior = true;
        continue;
      }
      if (observation) {
        state.eligibleCells = Math.max(
          0,
          Math.floor(observation.eligibleCells),
        );
        state.openCells = clamp(
          Math.floor(observation.openCells),
          0,
          state.eligibleCells,
        );
        state.openRatio = clamp(observation.openRatio, 0, 1);
        state.connectedToDock =
          observation.connectedToDock === true;
        state.connectedToExterior =
          observation.connectedToExterior === true;
      }
      const connectionSatisfied =
        !definition.iceAccess.requireDockConnection ||
        (
          state.connectedToDock &&
          state.connectedToExterior
        );
      if (
        state.eligibleCells > 0 &&
        state.openRatio >=
          definition.iceAccess.requiredOpenRatio &&
        connectionSatisfied
      ) {
        this.markCleared(portId, simulationTime);
        clearedPortIds.push(portId);
        contributionEvents.push({
          type: 'PORT_CLEARED',
          eventId:
            `port:${portId}:cleared:` +
            `${Math.round(simulationTime * 1000)}`,
          occurredAt: Math.max(0, simulationTime),
          portId,
        });
      } else {
        state.status =
          state.openRatio >= 0.04 ||
          state.connectedToDock ||
          state.connectedToExterior
            ? 'CLEARING'
            : 'FROZEN';
      }
    }
    return { clearedPortIds, contributionEvents };
  }

  public exportState(): PortClearanceSaveData {
    return {
      version: 1,
      ports: [...this.getStates()],
    };
  }

  public importState(
    saved: Readonly<PortClearanceSaveData>,
  ): boolean {
    if (saved.version !== 1 || !Array.isArray(saved.ports)) {
      return false;
    }
    for (const candidate of saved.ports) {
      const state = this.states.get(candidate.portId);
      if (
        !state ||
        !['FROZEN', 'CLEARING', 'CLEARED'].includes(
          candidate.status,
        )
      ) {
        continue;
      }
      state.status = candidate.status;
      state.eligibleCells = Math.max(
        0,
        Math.floor(candidate.eligibleCells || 0),
      );
      state.openCells = clamp(
        Math.floor(candidate.openCells || 0),
        0,
        state.eligibleCells,
      );
      state.openRatio = clamp(candidate.openRatio || 0, 0, 1);
      state.connectedToDock =
        candidate.connectedToDock === true;
      state.connectedToExterior =
        candidate.connectedToExterior === true;
      state.clearedAt =
        candidate.status === 'CLEARED'
          ? Math.max(0, candidate.clearedAt || 0)
          : undefined;
    }
    return true;
  }

  private markCleared(
    portId: string,
    simulationTime: number,
  ): boolean {
    const state = this.states.get(portId);
    if (!state || state.status === 'CLEARED') return false;
    state.status = 'CLEARED';
    state.openRatio = 1;
    state.openCells = state.eligibleCells;
    state.connectedToDock = true;
    state.connectedToExterior = true;
    state.clearedAt = Math.max(0, simulationTime);
    return true;
  }
}
