import {
  DepthTexture,
  DepthStencilFormat,
  UnsignedInt248Type,
  LinearFilter,
  RGBAFormat,
  ShaderMaterial,
  UnsignedByteType,
  Vector2,
  WebGLRenderTarget,
  type Camera,
  type Scene,
  type WebGLRenderer,
} from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { damp } from '../utils/math';
import type { RenderDiagnostics } from '../performance/RenderDiagnostics';
import type { PerformanceIsolation } from '../performance/PerformanceIsolation';
import type { IsolationRenderScope } from '../performance/ScenePerformanceIsolation';
import { CelestialDepthMaskPass, type CelestialDepthMaskSource } from './CelestialDepthMaskPass';
import { IndoorLightShaftPass, type IndoorLightShaftState } from './IndoorLightShaftPass';

export type SphericalWorldContext =
  | 'sea'
  | 'harbor'
  | 'construction';

export type AtmosphereGroundingQuality = 'LOW' | 'MEDIUM' | 'HIGH' | 'ULTRA';

export interface AtmosphereGroundingState {
  readonly daylight: number;
  readonly night: number;
  readonly warmth: number;
  readonly snowIntensity: number;
  readonly fog: number;
}

interface AtmosphereGroundingProfile {
  readonly grade: number;
  readonly bloom: number;
  readonly bloomRadius: number;
  readonly bloomResolutionScale: number;
}

const ATMOSPHERE_GROUNDING_PROFILES: Readonly<
  Record<AtmosphereGroundingQuality, AtmosphereGroundingProfile>
> = Object.freeze({
  LOW: { grade: 0, bloom: 0, bloomRadius: 0, bloomResolutionScale: 0.35 },
  MEDIUM: { grade: 0.62, bloom: 0, bloomRadius: 0, bloomResolutionScale: 0.35 },
  HIGH: { grade: 0.88, bloom: 0.105, bloomRadius: 0.16, bloomResolutionScale: 0.42 },
  ULTRA: { grade: 1, bloom: 0.15, bloomRadius: 0.2, bloomResolutionScale: 0.55 },
});

export const SPHERICAL_WORLD_STRENGTH = Object.freeze({
  sea: 0.14,
  harbor: 0.3,
  construction: 0,
} satisfies Record<SphericalWorldContext, number>);

/** The post-process scene target must preserve the character outline mask. */
export const SPHERICAL_WORLD_RENDER_TARGET_STENCIL_ENABLED = true;

const SPHERICAL_WORLD_SHADER = {
  uniforms: {
    tDiffuse: { value: null },
    uStrength: { value: 0 },
    uAspect: { value: 1 },
    uFocus: { value: new Vector2() },
  },
  vertexShader: `
    varying vec2 vUv;

    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform float uStrength;
    uniform float uAspect;
    uniform vec2 uFocus;
    varying vec2 vUv;

    void main() {
      vec2 point = vUv * 2.0 - 1.0;
      vec2 localPoint = point - uFocus;
      vec2 sphericalPoint = vec2(
        localPoint.x * uAspect,
        localPoint.y
      );
      float sphereRadius = 1.08;
      float normalizedRadius = min(
        length(sphericalPoint) / sphereRadius,
        0.97
      );
      float radiusSquared = normalizedRadius * normalizedRadius;

      // Lower distant screen regions around the focal point instead of
      // magnifying the centre. The sphere sagitta gives this projection an
      // actual round profile rather than an arbitrary lens distortion.
      float sphereSagitta =
        1.0 - sqrt(max(0.0, 1.0 - radiusSquared));
      float domeDrop = uStrength * sphereSagitta * 0.95;
      vec2 samplePoint = vec2(point.x, point.y + domeDrop);
      vec2 sampleUv = samplePoint * 0.5 + 0.5;
      vec4 sceneColor = texture2D(tDiffuse, sampleUv);

      // A very small cool falloff helps the corners recede without drawing a
      // visible vignette over the arctic palette.
      float edgeFalloff =
        smoothstep(0.48, 1.0, radiusSquared) * uStrength * 0.12;
      sceneColor.rgb = mix(
        sceneColor.rgb,
        sceneColor.rgb * 0.965 + vec3(0.012, 0.022, 0.026),
        edgeFalloff
      );
      gl_FragColor = sceneColor;
    }
  `,
};

const ATMOSPHERE_GROUNDING_SHADER = {
  uniforms: {
    tDiffuse: { value: null },
    uStrength: { value: 0 },
    uDaylight: { value: 1 },
    uNight: { value: 0 },
    uWarmth: { value: 0 },
    uSnow: { value: 0 },
    uFog: { value: 0 },
    uTime: { value: 0 },
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform float uStrength;
    uniform float uDaylight;
    uniform float uNight;
    uniform float uWarmth;
    uniform float uSnow;
    uniform float uFog;
    uniform float uTime;
    varying vec2 vUv;

    float groundingHash(vec2 point) {
      return fract(sin(dot(point, vec2(12.9898, 78.233))) * 43758.5453);
    }

    void main() {
      vec4 source = texture2D(tDiffuse, vUv);
      vec3 color = source.rgb;
      float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
      float saturation = 1.0 + uStrength * (
        0.045 + uWarmth * 0.035 - uFog * 0.045
      );
      color = mix(vec3(luminance), color, saturation);
      float contrast = 1.0 + uStrength * mix(0.038, 0.018, uFog);
      color = (color - 0.5) * contrast + 0.5;

      float shadowWeight = 1.0 - smoothstep(0.16, 0.56, luminance);
      float highlightWeight = smoothstep(0.56, 1.0, luminance);
      color *= mix(
        vec3(1.0),
        vec3(0.91, 0.965, 1.045),
        shadowWeight * uNight * 0.1 * uStrength
      );
      color *= mix(
        vec3(1.0),
        vec3(1.035, 1.005, 0.955),
        highlightWeight * uWarmth * 0.075 * uStrength
      );

      // Fine grain only breaks digital colour plateaus in fog and sky; it is
      // deliberately too weak to read as a film filter.
      float grain = groundingHash(
        floor(gl_FragCoord.xy * 0.5) + floor(uTime * 18.0)
      ) - 0.5;
      color += grain * (0.0014 + uFog * 0.0008) * uStrength;
      vec2 centred = vUv * 2.0 - 1.0;
      float vignette = smoothstep(0.52, 1.38, dot(centred, centred));
      float grounding = 0.012 + uSnow * 0.012 + uNight * 0.008;
      color *= 1.0 - vignette * grounding * uStrength;
      gl_FragColor = vec4(max(color, vec3(0.0)), source.a);
    }
  `,
};

/**
 * Presentation-only spherical lens for evaluating a rounder world language.
 * The scene, physics, raycasts, construction grid and persistence remain flat.
 */
export class SphericalWorldOverlay {
  private readonly renderer: WebGLRenderer;
  private readonly scene: Scene;
  private camera: Camera;
  private composer?: EffectComposer;
  private sphericalPass?: ShaderPass;
  private bloomPass?: UnrealBloomPass;
  private atmospherePass?: ShaderPass;
  private width = 1;
  private height = 1;
  private enabled = false;
  private context: SphericalWorldContext = 'sea';
  private currentStrength = 0;
  private readonly focus = new Vector2();
  private atmosphereQuality: AtmosphereGroundingQuality = 'LOW';
  private atmosphereTime = 0;
  private celestialDepthSource?: CelestialDepthMaskSource;
  private celestialDepthPass?: CelestialDepthMaskPass;
  private indoorShaftPass?: IndoorLightShaftPass;
  private indoorShaftEnabled=false;
  private indoorShaftSource?:()=>IndoorLightShaftState|undefined;
  private readonly diagnostic = { bypass: false };

  public applyPerformanceIsolation(isolation: PerformanceIsolation, scope: IsolationRenderScope): void {
    scope.set(this.diagnostic, 'bypass', !isolation.enabled('postprocessing'));
    if (this.atmospherePass && !isolation.enabled('grade')) scope.set(this.atmospherePass, 'enabled', false);
    if (this.bloomPass && !isolation.enabled('bloom')) scope.set(this.bloomPass, 'enabled', false);
  }

  public setCelestialDepthSource(source: CelestialDepthMaskSource | undefined): void {
    if (source === this.celestialDepthSource) return;
    this.celestialDepthSource=source;
    this.releaseComposer();
    if(source || this.atmosphereQuality!=='LOW' || this.enabled)this.ensureComposer();
  }

  public setIndoorShaftSource(source:()=>IndoorLightShaftState|undefined):void{this.indoorShaftSource=source;}
  public setIndoorShaftEnabled(enabled:boolean):void{
    this.indoorShaftEnabled=enabled;
    if(enabled&&(!this.indoorShaftPass||!this.composer?.passes.includes(this.indoorShaftPass))){this.releaseComposer();this.ensureComposer();}
    if(!enabled&&this.indoorShaftPass)this.indoorShaftPass.enabled=false;
  }
  public isIndoorShaftEnabled():boolean{return this.indoorShaftEnabled;}
  public prewarmIndoorShafts():void {
    this.indoorShaftPass??=new IndoorLightShaftPass();this.indoorShaftPass.prewarm(this.renderer);
  }

  public constructor(
    renderer: WebGLRenderer,
    scene: Scene,
    camera: Camera,
  ) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
  }

  public dispose(): void {
    this.releaseComposer();
    this.indoorShaftPass?.dispose();this.indoorShaftPass=undefined;
  }

  public setSize(width: number, height: number): void {
    this.width = Math.max(1, width);
    this.height = Math.max(1, height);
    if (!this.composer) return;
    this.composer.setPixelRatio(this.renderer.getPixelRatio());
    this.composer.setSize(this.width, this.height);
    this.updateBloomResolution();
    this.updateAspect();
  }

  public setAtmosphereQuality(quality: AtmosphereGroundingQuality): void {
    if (this.atmosphereQuality === quality) return;
    this.atmosphereQuality = quality;
    if (quality !== 'LOW') this.ensureComposer();
    this.applyAtmosphereProfile();
    if (!this.indoorShaftEnabled && !this.celestialDepthSource && !this.enabled && quality === 'LOW' && this.currentStrength <= 0.0005) {
      this.releaseComposer();
    }
  }

  public getAtmosphereQuality(): AtmosphereGroundingQuality {
    return this.atmosphereQuality;
  }

  public setAtmosphereState(state: Readonly<AtmosphereGroundingState>): void {
    if (!this.atmospherePass) return;
    const uniforms = this.atmospherePass.uniforms;
    uniforms.uDaylight!.value = Math.max(0, Math.min(1, state.daylight));
    uniforms.uNight!.value = Math.max(0, Math.min(1, state.night));
    uniforms.uWarmth!.value = Math.max(0, Math.min(1, state.warmth));
    uniforms.uSnow!.value = Math.max(0, Math.min(1, state.snowIntensity));
    uniforms.uFog!.value = Math.max(0, Math.min(1, state.fog));
  }

  /** Keeps the optional post-process aligned with the current gameplay camera. */
  public setCamera(camera: Camera): void {
    if (this.camera === camera) return;
    this.camera = camera;
    const renderPass = this.composer?.passes.find(
      (pass): pass is RenderPass => pass instanceof RenderPass,
    );
    if (renderPass) renderPass.camera = camera;
  }

  public setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (enabled) this.ensureComposer();
  }

  public toggle(): boolean {
    this.setEnabled(!this.enabled);
    return this.enabled;
  }

  public isEnabled(): boolean {
    return this.enabled;
  }

  public setContext(context: SphericalWorldContext): void {
    this.context = context;
  }

  public getContext(): SphericalWorldContext {
    return this.context;
  }

  public setFocus(x: number, y: number): void {
    this.focus.set(x, y);
    if (!this.sphericalPass) return;
    const focus = this.sphericalPass.uniforms.uFocus;
    if (focus) (focus.value as Vector2).copy(this.focus);
  }

  public update(deltaSeconds: number): void {
    this.atmosphereTime += Math.max(0, Math.min(0.1, deltaSeconds));
    const target = this.enabled
      ? SPHERICAL_WORLD_STRENGTH[this.context]
      : 0;
    this.currentStrength = damp(
      this.currentStrength,
      target,
      this.enabled ? 5.2 : 7.5,
      deltaSeconds,
    );
    if (this.sphericalPass) {
      const strength = this.sphericalPass.uniforms.uStrength;
      if (strength) strength.value = this.currentStrength;
      this.sphericalPass.enabled = this.currentStrength > 0.0005;
    }
    if (this.atmospherePass?.uniforms.uTime) {
      this.atmospherePass.uniforms.uTime.value = this.atmosphereTime;
    }
    if (
      !this.indoorShaftEnabled && !this.celestialDepthSource && !this.enabled && this.currentStrength <= 0.0005 &&
      this.atmosphereQuality === 'LOW'
    ) {
      this.currentStrength = 0;
      this.releaseComposer();
    }
  }

  /**
   * Converts a pointer position from the curved output back into the flat
   * scene projection. This keeps world interaction aligned with the visual
   * dome while the simulation remains planar.
   */
  public mapScreenNdcToSceneNdc(
    x: number,
    y: number,
    target: Vector2,
  ): Vector2 {
    if (this.currentStrength <= 0.0005) return target.set(x, y);
    const aspect = this.width / this.height;
    const localX = x - this.focus.x;
    const localY = y - this.focus.y;
    const normalizedRadius = Math.min(
      0.97,
      Math.hypot(localX * aspect, localY) / 1.08,
    );
    const radiusSquared = normalizedRadius * normalizedRadius;
    const sphereSagitta =
      1 - Math.sqrt(Math.max(0, 1 - radiusSquared));
    const domeDrop = this.currentStrength * sphereSagitta * 0.95;
    return target.set(x, y + domeDrop);
  }

  /** Inverse used by world-space HUD markers after flat-scene projection. */
  public mapSceneNdcToScreenNdc(
    x: number,
    y: number,
    target: Vector2,
  ): Vector2 {
    if (this.currentStrength <= 0.0005) return target.set(x, y);
    const aspect = this.width / this.height;
    let screenY = y;
    // The dome mapping only offsets Y. A short fixed-point solve is stable
    // throughout the deliberately subtle presentation-strength range.
    for (let iteration = 0; iteration < 5; iteration += 1) {
      const localX = x - this.focus.x;
      const localY = screenY - this.focus.y;
      const normalizedRadius = Math.min(
        0.97,
        Math.hypot(localX * aspect, localY) / 1.08,
      );
      const sphereSagitta =
        1 - Math.sqrt(Math.max(0, 1 - normalizedRadius * normalizedRadius));
      screenY = y - this.currentStrength * sphereSagitta * 0.95;
    }
    return target.set(x, screenY);
  }

  public render(deltaSeconds: number, diagnostics?: RenderDiagnostics): void {
    this.indoorShaftPass?.prepare(this.camera,this.indoorShaftEnabled?this.indoorShaftSource?.():undefined,this.indoorShaftEnabled);
    if (!this.composer || this.diagnostic.bypass) {
      if (diagnostics) diagnostics.measure('scene', () => this.renderer.render(this.scene, this.camera));
      else this.renderer.render(this.scene, this.camera);
      return;
    }
    if (diagnostics?.capture.active) diagnostics.instrumentPasses(this.composer.passes,
      this.composer.passes.map((pass, index) => pass === this.celestialDepthPass ? 'celestial-depth-mask' :
        pass === this.indoorShaftPass ? 'indoor-light-shafts' : pass === this.sphericalPass ? 'spherical-warp' : pass === this.bloomPass ? 'bloom' :
        pass === this.atmospherePass ? 'atmosphere-grade' : index === 0 ? 'scene' : 'output'));
    this.composer.render(deltaSeconds);
  }

  public getRenderPassCount(): number {
    if (!this.composer) return 1;
    return this.composer.passes.reduce(
      (count, pass) => count + (pass.enabled ? 1 : 0),
      0,
    );
  }

  public getRenderTargetCount(): number {
    if (!this.composer) return 0;
    return 2 + (this.bloomPass?.enabled ? 11 : 0) + (this.celestialDepthPass ? 1 : 0) + (this.indoorShaftPass ? 1 : 0);
  }

  /** compile() must see the same target as RenderPass. Compiling against the
   * canvas instead prepares the wrong tone-mapping / output-color variants. */
  public getSceneRenderTarget(): WebGLRenderTarget | null { return this.composer?.readBuffer ?? null; }

  public applyShaderWarmup(scope: IsolationRenderScope, includeBloom: boolean): void {
    // Reuse existing targets at their current resolution; don't allocate Ultra
    // buffers just to warm a shader on a low-memory device.
    if (this.sphericalPass) scope.set(this.sphericalPass, 'enabled', true);
    if (this.atmospherePass) scope.set(this.atmospherePass, 'enabled', true);
    if (includeBloom && this.bloomPass) scope.set(this.bloomPass, 'enabled', true);
  }

  private ensureComposer(): void {
    if (this.composer) return;
    const renderTarget = new WebGLRenderTarget(1, 1, {
      minFilter: LinearFilter,
      magFilter: LinearFilter,
      format: RGBAFormat,
      type: UnsignedByteType,
      depthBuffer: true,
      stencilBuffer: SPHERICAL_WORLD_RENDER_TARGET_STENCIL_ENABLED,
    });
    renderTarget.texture.name = 'Spherical world overlay scene';
    if(this.celestialDepthSource || this.indoorShaftEnabled) {
      renderTarget.depthTexture=new DepthTexture(1,1,UnsignedInt248Type);
      renderTarget.depthTexture.format=DepthStencilFormat;
    }
    const composer = new EffectComposer(this.renderer, renderTarget);
    composer.addPass(new RenderPass(this.scene, this.camera));
    if(this.celestialDepthSource){
      this.celestialDepthPass=new CelestialDepthMaskPass(this.celestialDepthSource);
      composer.addPass(this.celestialDepthPass);
    }
    if(this.indoorShaftEnabled){
      this.indoorShaftPass??=new IndoorLightShaftPass();composer.addPass(this.indoorShaftPass);
    }
    const sphericalMaterial = new ShaderMaterial(
      SPHERICAL_WORLD_SHADER,
    );
    sphericalMaterial.name = 'Spherical world overlay';
    sphericalMaterial.toneMapped = false;
    const sphericalPass = new ShaderPass(sphericalMaterial);
    sphericalPass.enabled = this.currentStrength > 0.0005;
    composer.addPass(sphericalPass);
    const bloomPass = new UnrealBloomPass(
      new Vector2(1, 1),
      0,
      0,
      0.94,
    );
    bloomPass.enabled = false;
    composer.addPass(bloomPass);
    const atmosphereMaterial = new ShaderMaterial(
      ATMOSPHERE_GROUNDING_SHADER,
    );
    atmosphereMaterial.name = 'The Long Winter atmosphere grounding grade';
    atmosphereMaterial.toneMapped = false;
    const atmospherePass = new ShaderPass(atmosphereMaterial);
    atmospherePass.enabled = false;
    composer.addPass(atmospherePass);
    composer.addPass(new OutputPass());
    this.composer = composer;
    this.sphericalPass = sphericalPass;
    this.bloomPass = bloomPass;
    this.atmospherePass = atmospherePass;
    const focus = sphericalPass.uniforms.uFocus;
    if (focus) (focus.value as Vector2).copy(this.focus);
    composer.setPixelRatio(this.renderer.getPixelRatio());
    composer.setSize(this.width, this.height);
    this.applyAtmosphereProfile();
    this.updateBloomResolution();
    this.updateAspect();
  }

  private updateAspect(): void {
    if (!this.sphericalPass) return;
    const aspect = this.sphericalPass.uniforms.uAspect;
    if (aspect) aspect.value = this.width / this.height;
  }

  private applyAtmosphereProfile(): void {
    const profile = ATMOSPHERE_GROUNDING_PROFILES[this.atmosphereQuality];
    if (this.atmospherePass) {
      this.atmospherePass.enabled = profile.grade > 0;
      this.atmospherePass.uniforms.uStrength!.value = profile.grade;
    }
    if (this.bloomPass) {
      this.bloomPass.enabled = profile.bloom > 0;
      this.bloomPass.strength = profile.bloom;
      this.bloomPass.radius = profile.bloomRadius;
      this.bloomPass.threshold = 0.94;
    }
    this.updateBloomResolution();
  }

  private updateBloomResolution(): void {
    if (!this.bloomPass) return;
    const profile = ATMOSPHERE_GROUNDING_PROFILES[this.atmosphereQuality];
    const pixelRatio = this.renderer.getPixelRatio();
    this.bloomPass.setSize(
      Math.max(
        1,
        Math.floor(this.width * pixelRatio * profile.bloomResolutionScale),
      ),
      Math.max(
        1,
        Math.floor(this.height * pixelRatio * profile.bloomResolutionScale),
      ),
    );
  }

  private releaseComposer(): void {
    if(this.indoorShaftPass)this.indoorShaftPass.enabled=false;
    this.celestialDepthPass?.dispose();
    this.celestialDepthPass=undefined;
    this.composer?.dispose();
    this.sphericalPass?.material.dispose();
    this.atmospherePass?.material.dispose();
    this.bloomPass?.dispose();
    this.composer = undefined;
    this.sphericalPass = undefined;
    this.bloomPass = undefined;
    this.atmospherePass = undefined;
  }
}
