import { Color, Group, Mesh, MeshStandardMaterial, Object3D, PointLight, Ray, ShaderMaterial, Vector3, type Scene } from 'three';
import type { TerrainHeightSystem } from '../../land/TerrainHeightSystem';
import type { LandSnowSystem } from '../../land/LandSnowSystem';
import type { WorldAssetPlacementSystem } from '../../land/WorldAssetPlacementSystem';
import type { WildernessSurvivalSimulation, WildernessInteractionView, WildernessActionResult, WildernessStepContext } from '../WildernessSurvivalSimulation';
import type { WildernessRuneSystem } from '../WildernessRuneSystem';
import type { SurvivalConstructionSystem } from '../SurvivalConstructionSystem';
import type { LocalWorldInfluence } from '../LocalWorldInfluenceRegistry';
import { SanctuaryModel, type SanctuarySave } from './SanctuaryModel';
import { type SanctuaryObstacle } from './SanctuaryNavigation';
import { HEART_SANCTUARY, inSanctuary } from './SanctuaryWorld';
import { HUMAN_HITBOX, HUSK_HITBOX, nearestCombatHit, type CombatBody, type CombatPoint } from '../combat/CombatHitboxes';
import { CombatHitboxDebug } from '../combat/CombatHitboxDebug';

const heartMaterial = (layer: number) => new ShaderMaterial({
  transparent: layer > 0, depthWrite: layer === 0,
  uniforms: { uTime: { value: 0 }, uVitality: { value: 1 }, uLayer: { value: layer } },
  vertexShader: `
    varying vec3 vP; varying vec3 vN; varying vec3 vW;
    void main() {
      vP=position; vN=normalize(mat3(modelMatrix)*normal);
      vec4 world=modelMatrix*vec4(position,1.); vW=world.xyz;
      gl_Position=projectionMatrix*viewMatrix*world;
    }`,
  fragmentShader: `
    uniform float uTime; uniform float uVitality; uniform float uLayer;
    varying vec3 vP; varying vec3 vN; varying vec3 vW;
    void main() {
      float t=uTime*.24;
      float flow=sin(vP.y*5.+t+sin(vP.x*4.-t*.7)+sin(vP.z*5.+t*.5));
      float vein=pow(.5+.5*sin(vP.y*15.+flow*3.+t),12.);
      float face=pow(1.-abs(dot(normalize(vN),normalize(cameraPosition-vW))),2.3);
      float hue=.5+.5*sin(flow*1.8+vP.y*2.2+t*.3+uLayer*1.4);
      vec3 teal=vec3(.025,.56,.32), amethyst=vec3(.35,.025,.65), amber=vec3(.85,.20,.018);
      vec3 color=mix(teal,amethyst,smoothstep(.2,.75,hue));
      color=mix(color,amber,pow(.5+.5*sin(vP.y*3.-t*.4+flow),5.)*.8);
      float breath=.94+.06*sin(uTime*.9);
      color*=mix(.25,1.,uVitality)*breath;
      color+=mix(color,vec3(.65,.9,.74),.25)*vein*.9+color*face*.45;
      float alpha=uLayer<.5?1.:.07+face*.27+vein*.12;
      gl_FragColor=vec4(color*(uLayer<.5?1.25:1.),alpha);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }`,
});

interface HuskVisual {
  root: Group; material: MeshStandardMaterial;
  parts: { mesh: Object3D; home: Vector3; rotation: number; role: string }[];
  id?: string;
}

/** Feature-island presentation/controller. V3 owns buildings; canonical snow
 * owns tracks; the existing rune authority owns costs, drawings and lifetimes. */
export class SanctuarySystem {
  readonly model: SanctuaryModel;
  readonly root = new Group();
  readonly light = new PointLight(0x72e7cf, 0, 25, 2);
  private readonly coreMaterial = heartMaterial(0);
  private readonly veilMaterial = heartMaterial(1);
  private readonly breachMaterial = new ShaderMaterial({
    transparent: true, depthWrite: false,
    uniforms: { uTime: { value: 0 }, uAmount: { value: 0 } },
    vertexShader: `varying vec3 vP; varying vec3 vN; varying vec3 vW;
      void main(){vP=position;vN=normalize(mat3(modelMatrix)*normal);vec4 w=modelMatrix*vec4(position,1.);vW=w.xyz;gl_Position=projectionMatrix*viewMatrix*w;}`,
    fragmentShader: `uniform float uTime; uniform float uAmount; varying vec3 vP; varying vec3 vN; varying vec3 vW;
      void main(){float f=abs(dot(normalize(vN),normalize(cameraPosition-vW)));
      float curl=.5+.5*sin(vP.y*8.+sin(vP.x*7.+uTime*.3)+sin(vP.z*6.-uTime*.2));
      gl_FragColor=vec4(mix(vec3(.018,.012,.028),vec3(.08,.025,.11),curl*.3),pow(f,1.5)*uAmount*.88);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
      }`,
  });
  private readonly breaches: Group[] = [];
  private readonly heartParts: { mesh: Mesh; home: Vector3; rotation: Vector3 }[] = [];
  private readonly heartTeal = new Color(0x8df5d6);
  private readonly heartViolet = new Color(0xc99bea);
  private readonly husks: HuskVisual[] = [];
  private readonly ray = new Ray();
  private hasRay = false;
  private active = false;
  private time = 0;
  private attackCooldown = 0;
  private obstacleTimer = 0;
  private obstacles: SanctuaryObstacle[] = [];
  private readonly unsubscribe: () => void;
  private lastX = 0;
  private lastZ = 0;
  private lastY = 0;
  private readonly hitboxDebug = typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('combatHitboxes') === '1'
    ? new CombatHitboxDebug() : undefined;
  private lastNear = false;
  public updateMs = 0;
  public tracksWritten = 0;

  constructor(scene: Scene, private readonly terrain: TerrainHeightSystem,
    private readonly bank: WorldAssetPlacementSystem | undefined,
    private readonly simulation: WildernessSurvivalSimulation,
    private readonly construction: SurvivalConstructionSystem,
    private readonly runes: WildernessRuneSystem, saved?: SanctuarySave) {
    this.model = new SanctuaryModel(saved);
    this.root.name = 'The Long Winter · Heart temple sanctuary';
    this.light.castShadow = false;
    scene.add(this.root);
    if (this.hitboxDebug) scene.add(this.hitboxDebug.root);
    this.rebuildAssets();
    this.unsubscribe = bank?.addVisualListener(() => this.rebuildAssets()) ?? (() => {});
    this.setActive(false);
  }

  private rebuildAssets(): void {
    this.root.clear(); this.heartParts.length = 0; this.breaches.length = 0;
    for (const v of this.husks) v.material.dispose();
    this.husks.length = 0;
    const { x, z } = HEART_SANCTUARY;
    for (const side of [-1, 1]) {
      const cliff = this.bank?.createRuntimeInstance('TLW_SANCTUARY_CLIFF_FACE_01');
      if (!cliff) continue;
      cliff.position.set(x + side * 15, HEART_SANCTUARY.groundY, z + 31);
      cliff.rotation.y = side < 0 ? 0 : Math.PI;
      this.root.add(cliff);
    }
    for (const offset of [-6, 0, 6]) {
      const breach = this.bank?.createRuntimeInstance('TLW_SHADOW_BREACH_01');
      if (!breach) continue;
      breach.position.set(x + offset, this.terrain.sampleHeight(x + offset, z + 72), z + 72);
      breach.traverse(obj => { if (obj instanceof Mesh) {
        obj.material = this.breachMaterial; obj.castShadow = false; obj.onBeforeRender = () => {};
      } });
      this.breaches.push(breach); this.root.add(breach);
    }
    const temple = this.bank?.createRuntimeInstance(HEART_SANCTUARY.templePrefab);
    if (temple) { temple.position.set(x, this.terrain.sampleHeight(x, z), z); this.root.add(temple); }
    const heart = this.bank?.createRuntimeInstance(HEART_SANCTUARY.heartPrefab);
    if (heart) {
      heart.position.set(x, this.terrain.sampleHeight(x, z), z);
      heart.traverse(obj => {
        if (!(obj instanceof Mesh) || !obj.name.startsWith('heart-')) return;
        obj.material = obj.name === 'heart-core' ? this.coreMaterial : this.veilMaterial;
        obj.castShadow = false; obj.onBeforeRender = () => {};
        this.heartParts.push({ mesh: obj, home: obj.position.clone(),
          rotation: new Vector3(obj.rotation.x, obj.rotation.y, obj.rotation.z) });
      });
      this.root.add(heart);
    }
    this.light.position.set(x, this.terrain.sampleHeight(x, z) + 3.8, z);
    this.root.add(this.light);
    // Pre-create a bounded actor pool. No geometry or material allocation on spawn.
    for (let i = 0; i < 12; i++) {
      const root = this.bank?.createRuntimeInstance(HEART_SANCTUARY.shellPrefab);
      if (!root) continue;
      const material = new MeshStandardMaterial({ color: 0x29232f, roughness: .96,
        emissive: 0x240f32, emissiveIntensity: .12, transparent: true, opacity: 0 });
      const parts: HuskVisual['parts'] = [];
      root.traverse(obj => {
        if (!(obj instanceof Mesh)) return;
        if (obj.name !== 'husk-eye') { obj.material = material; obj.onBeforeRender = () => {}; }
        parts.push({ mesh: obj, home: obj.position.clone(), rotation: obj.rotation.x, role: obj.name });
      });
      root.visible = false; this.root.add(root);
      this.husks.push({ root, material, parts });
    }
  }

  setActive(active: boolean): void {
    this.active = active; this.root.visible = active;
    if (this.hitboxDebug) this.hitboxDebug.root.visible = active;
    if (!active) { this.light.intensity = 0; this.construction.setSanctuaryEconomy(false); this.runes.setSanctuaryEconomy(false); }
  }

  setRay(ray: Readonly<Ray>): void { this.ray.copy(ray); this.hasRay = true; }
  clearRay(): void { this.hasRay = false; }

  public combatBodies(): CombatBody[] {
    return this.model.state.husks.filter(h => h.health > 0).map(h => ({ id: h.id, team: 'HOSTILE',
      x: h.x, y: this.terrain.sampleHeight(h.x, h.z), z: h.z, ...HUSK_HITBOX }));
  }

  public playerBody(): CombatBody {
    return { id: 'player', team: 'PLAYER', x: this.lastX, y: this.lastY, z: this.lastZ, ...HUMAN_HITBOX };
  }

  public combatBlocked = (a: CombatPoint, b: CombatPoint): boolean => {
    if (this.construction.combatSegmentBlocked(a, b)) return true;
    const length = Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z);
    for (let distance = .3; distance < length - .1; distance += .45) {
      const t = distance / length, x = a.x + (b.x - a.x) * t, z = a.z + (b.z - a.z) * t;
      if (this.terrain.sampleHeight(x, z) > a.y + (b.y - a.y) * t + .03) return true;
    }
    return false;
  };

  public spellTarget(ray: Readonly<Ray>): Vector3 | undefined {
    if (!this.active) return undefined;
    const hit = nearestCombatHit(ray, this.combatBodies(), this.playerBody(), 16, this.combatBlocked);
    return hit ? new Vector3(hit.body.x, hit.body.y, hit.body.z) : undefined;
  }
  hasInteraction(): boolean { return Boolean(this.interaction(this.lastX, this.lastZ)); }

  canWalkAt(x: number, z: number, radius: number, footY?: number): boolean {
    if (!this.active) return true;
    for (const body of this.combatBodies()) {
      if (footY !== undefined && (footY > body.y + body.height || footY + HUMAN_HITBOX.height < body.y)) continue;
      if (Math.hypot(x-body.x,z-body.z) < radius+body.radius) return false;
    }
    const u = x - HEART_SANCTUARY.x, v = z - HEART_SANCTUARY.z;
    if (Math.abs(u) > 9 || Math.abs(v) > 14) return true;
    const ground = this.terrain.sampleHeight(x, z);
    if ((footY ?? ground) > ground + 7.7) return true;
    if (Math.hypot(u, v) < 1.35 + radius) return false;
    for (const cx of [-6, 6]) for (const cz of [-4, 3, 10]) {
      if (Math.hypot(u - cx, v - cz) < .68 + radius) return false;
    }
    return true;
  }

  interaction(x: number, z: number): WildernessInteractionView | undefined {
    if (!this.active || !inSanctuary(x, z)) return undefined;
    if (this.hasRay) {
      for (const obstacle of this.obstacles) {
        if (!(this.model.state.damage[obstacle.id]! > 0) || Math.hypot(x - obstacle.x, z - obstacle.z) > 3.5) continue;
        const point = new Vector3(obstacle.x, this.terrain.sampleHeight(obstacle.x, obstacle.z) + .9, obstacle.z);
        if (this.ray.direction.dot(point.clone().sub(this.ray.origin)) <= 0 || this.ray.distanceToPoint(point) > 1.1) continue;
        return { label: 'REPAIR DEFENCE · 1 BRANCH', enabled: this.simulation.inventory.branches >= 1,
          kind: 'WAIT', targetId: `heart-repair:${obstacle.id}`, x: obstacle.x, z: obstacle.z };
      }
      const hit = nearestCombatHit(this.ray, this.combatBodies(), this.playerBody(), 2.9, this.combatBlocked);
      if (hit) {
        const h = hit.body;
        return { label: 'STRIKE THE HUSK · AXE', enabled: this.attackCooldown <= 0,
          kind: 'DEFEND', targetId: h.id, x: h.x, z: h.z, requiredTool: 'STONE_AXE' };
      }
    }
    if (Math.hypot(x - HEART_SANCTUARY.x, z - HEART_SANCTUARY.z) > 5.5) return undefined;
    const phase = this.model.state.phase;
    const label = phase === 'PREPARE' || phase === 'UNDISCOVERED' ? 'AWAKEN THE FIRST PULSE · BEGIN DEFENCE'
      : phase === 'REST' ? 'CALL THE NEXT PULSE · WHEN YOU ARE READY'
      : phase === 'WOUNDED' ? 'REKINDLE THE WARD · 2 LOGS + 1 STONE'
      : phase === 'RESTORED' ? 'THE HEART IS SAFE · REST AND EXPLORE' : 'THE HEART NEEDS YOUR DEFENCE';
    return { label, enabled: ['PREPARE', 'REST', 'WOUNDED'].includes(phase),
      kind: 'WAIT', targetId: 'world-heart', x: HEART_SANCTUARY.x, z: HEART_SANCTUARY.z };
  }

  perform(interaction: WildernessInteractionView): WildernessActionResult {
    const target = interaction.targetId ?? '';
    if (!interaction.enabled) return { accepted: false, message: interaction.label };
    if (target.startsWith('heart-repair:')) {
      const id = target.slice('heart-repair:'.length);
      if (this.simulation.inventory.branches < 1 || !(this.model.state.damage[id]! > 0)) return { accepted: false, message: 'This defence needs no repair.' };
      this.simulation.inventory.branches--;
      this.model.state.damage[id] = Math.max(0, this.model.state.damage[id]! - .4);
      this.construction.showSanctuaryDamage(this.model.state.damage, this.time);
      return { accepted: true, message: 'The bindings hold again. · −1 branch' };
    }
    if (target.startsWith('husk-')) {
      if (this.attackCooldown > 0 || this.simulation.toolCondition.stoneAxe <= 0) return { accepted: false, message: 'Ready your axe.' };
      // Revalidate at impact: cached prompts cannot hit a dead, moved or now
      // occluded body. A future sword can feed the shared swept-volume query.
      const hit = this.hasRay && nearestCombatHit(this.ray, this.combatBodies(), this.playerBody(), 2.9, this.combatBlocked);
      if (!hit || hit.body.id !== target) return { accepted: false, message: 'The husk is beyond your strike.' };
      this.attackCooldown = .7;
      const accepted = this.model.hit(target);
      if (accepted) this.simulation.toolCondition.stoneAxe = Math.max(0, this.simulation.toolCondition.stoneAxe - .008);
      return { accepted, message: accepted ? 'The empty shell recoils.' : 'The husk is beyond reach.' };
    }
    if (target === 'world-heart' && this.model.state.phase === 'WOUNDED') {
      if (this.simulation.inventory.logs < 2 || this.simulation.inventory.stone < 1) return { accepted: false, message: 'Bring two logs and one stone to rebuild the ward.' };
      this.simulation.inventory.logs -= 2; this.simulation.inventory.stone--;
      this.model.restore();
      return { accepted: true, message: 'A small pulse returns. Prepare and try again.' };
    }
    const accepted = target === 'world-heart' && this.model.begin();
    return { accepted, message: accepted ? 'The Heart calls. You have time to reach the pass.' : interaction.label };
  }

  update(dt: number, context: Readonly<WildernessStepContext>, snow: LandSnowSystem): void {
    if (!this.active) return;
    const start = performance.now();
    this.time += Math.min(.1, Math.max(0, dt)); this.attackCooldown = Math.max(0, this.attackCooldown - dt);
    this.lastX = context.playerX; this.lastZ = context.playerZ;
    this.lastY = (context.playerY ?? this.terrain.sampleHeight(this.lastX, this.lastZ)) +
      (context.playerVerticalOffset ?? 0);
    this.lastNear = inSanctuary(this.lastX, this.lastZ, 145);
    const distance = Math.hypot(context.playerX - HEART_SANCTUARY.x, context.playerZ - HEART_SANCTUARY.z);
    if (distance < 24 && this.model.discover()) {
      for (const id of ['FIRE_GATE', 'ASH_BURST', 'FROST_BIND', 'LIGHT_STRIKE'] as const) this.runes.discoverRune(id);
      this.runes.selectRune('FIRE_GATE'); this.runes.close();
    }
    if (this.model.state.phase !== 'UNDISCOVERED' && !this.model.state.suppliesTaken) {
      this.model.state.suppliesTaken = true;
      const stock = this.simulation.inventory;
      stock.logs += 24; stock.branches += 36; stock.fiber += 20; stock.tinder += 24; stock.stone += 12; stock.stoneChips += 16; stock.flint += 8;
      this.model.messages.push('Temple stores recovered: timber, bindings and rune offerings. B: build · Q: runes · F: interact.');
    }
    const finiteStock = inSanctuary(this.lastX, this.lastZ) && this.model.state.phase !== 'UNDISCOVERED';
    this.construction.setSanctuaryEconomy(finiteStock);
    this.runes.setSanctuaryEconomy(finiteStock);
    this.obstacleTimer -= dt;
    if (this.lastNear && this.obstacleTimer <= 0) {
      this.obstacleTimer = .5;
      this.obstacles = this.construction.sanctuaryObstacles(HEART_SANCTUARY.x, HEART_SANCTUARY.z + 30, 65);
      const current = new Set(this.obstacles.map(o => o.id));
      for (const id of Object.keys(this.model.state.damage)) if (!current.has(id)) delete this.model.state.damage[id];
    }
    this.model.update(dt, this.lastNear, {
      obstacles: this.obstacles, runes: this.runes.sanctuaryFields(),
      player: this.playerBody(), groundY: (x, z) => this.terrain.sampleHeight(x, z),
      blocked: this.combatBlocked,
      hurtPlayer: damage => {
        // Keep survival's current non-lethal playtest floor; death/respawn is
        // not silently introduced as a side effect of adding hitboxes.
        this.simulation.condition.health = Math.max(.08, this.simulation.condition.health - damage);
        this.model.messages.push('The husk strikes. Step away or interrupt it with a spell.');
      },
      canWalk: (x, z) => this.construction.canWalkAt(x, z, .28, this.terrain.sampleHeight(x, z)),
      breach: (id,attacker) => this.construction.breachBuildPiece(id,attacker),
      collapse: id => { this.construction.collapseFromSanctuary(id); this.obstacles = this.obstacles.filter(o => o.id !== id); this.obstacleTimer = 0; },
      track: (ax, az, bx, bz, heading) => {
        if (!snow.isTileActiveAt(bx, bz)) return;
        snow.compactTracks(ax, az, bx, bz, heading,
          { halfWidth: .12, radius: .105, compression: .95, edgeSoftness: .09 });
        this.tracksWritten++;
      },
    });
    this.construction.showSanctuaryDamage(this.model.state.damage, this.time);
    this.present(dt, distance);
    this.hitboxDebug?.update(this.playerBody(), this.combatBodies());
    this.updateMs = performance.now() - start;
  }

  private present(dt: number, distance: number): void {
    const vitality = this.model.state.vitality;
    this.root.visible = this.active && distance < 520;
    for (const material of [this.coreMaterial, this.veilMaterial]) {
      material.uniforms.uTime!.value = this.time;
      material.uniforms.uVitality!.value = vitality;
    }
    const s = this.model.state;
    const opening = s.phase === 'APPROACH' ? Math.min(1, s.seconds / 14) : s.phase === 'DEFEND' ? 1 : 0;
    const amount = this.breachMaterial.uniforms.uAmount!;
    amount.value += (opening - amount.value) * (1 - Math.exp(-dt * .8));
    this.breachMaterial.uniforms.uTime!.value = this.time;
    for (const breach of this.breaches) breach.visible = amount.value > .002;
    this.light.intensity = distance < 85 ? (32 + Math.sin(this.time * .9) * 2.5) * vitality : 0;
    this.light.color.copy(this.heartTeal).lerp(this.heartViolet, .35 + .2 * Math.sin(this.time * .08));
    for (let i = 0; i < this.heartParts.length; i++) {
      const part = this.heartParts[i]!;
      part.mesh.position.y = part.home.y + Math.sin(this.time * .8 + i * .8) * (part.mesh.name === 'heart-shard' ? .18 : .035);
      if (part.mesh.name === 'heart-orbit') part.mesh.rotation.z = part.rotation.z + this.time * .04 * (i % 2 ? 1 : -1);
    }
    const activeIds = new Set(this.model.state.husks.map(h => h.id));
    for (const visual of this.husks) {
      if (visual.id && !activeIds.has(visual.id)) { visual.id = undefined; visual.root.visible = false; }
    }
    for (const h of this.model.state.husks) {
      let v = this.husks.find(v => v.id === h.id);
      if (!v) {
        v = this.husks.find(v => !v.id);
        if (!v) continue;
        v.id = h.id; v.root.position.set(h.x, this.terrain.sampleHeight(h.x, h.z), h.z);
        v.root.rotation.set(0, h.heading, 0);
      }
      v.root.visible = distance < 170;
      const blend = 1 - Math.exp(-dt * 18);
      v.root.position.x += (h.x - v.root.position.x) * blend;
      v.root.position.z += (h.z - v.root.position.z) * blend;
      v.root.position.y += (this.terrain.sampleHeight(h.x, h.z) - v.root.position.y) * blend;
      const turn = Math.atan2(Math.sin(h.heading - v.root.rotation.y), Math.cos(h.heading - v.root.rotation.y));
      v.root.rotation.y += turn * (1 - Math.exp(-dt * 7));
      v.root.rotation.x = h.health <= 0 ? Math.min(1.45, h.death * 1.3) : h.mode === 'DRAIN' ? .16 : 0;
      v.material.opacity = Math.min(1, h.age / 2) * Math.max(0, 1 - h.death / 2.5);
      v.material.emissiveIntensity = h.mode === 'STAGGER' ? .8 : .12;
      for (const part of v.parts) {
        const sign = part.role.endsWith('-1') ? -1 : 1;
        const stride = h.speed > 0 ? Math.sin(h.gait) * .24 * sign : 0;
        if (part.role.startsWith('husk-leg') || part.role.startsWith('husk-foot')) part.mesh.position.z = part.home.z + stride;
        if (part.role.startsWith('husk-arm')) part.mesh.rotation.x = part.rotation - stride +
          (h.mode === 'WINDUP' ? -1.1 * (1 - h.attack / .5) : h.mode === 'RECOVER' ? -.75 * h.attack / 1.05 :
            h.mode === 'BREACH' ? -.65 * Math.max(0, Math.sin(h.attack * 5)) : h.mode === 'DRAIN' ? -.6 : 0);
      }
    }
  }

  influences(): LocalWorldInfluence[] {
    if (!this.active || this.model.state.phase === 'UNDISCOVERED' || !this.lastNear) return [];
    const { x, z } = HEART_SANCTUARY;
    return [{ id: 'world-heart-warmth', ownerId: 'world-heart', revision: this.model.state.wave * 100 + Math.round(this.model.state.vitality * 20),
      kind: 'THERMAL_SOURCE', bounds: { minX: x - 10, maxX: x + 10, minZ: z - 10, maxZ: z + 10 },
      x, z, y: this.terrain.sampleHeight(x, z) + 1, radiantRadius: this.model.state.phase === 'RESTORED' ? 10 : 5,
      convectiveRadius: 5, heatOutput: this.model.state.vitality * .8, fuelLimited: false }];
  }

  activity(): { title: string; detail: string; progress: number } {
    const s = this.model.state, distance = Math.round(Math.hypot(this.lastX - HEART_SANCTUARY.x, this.lastZ - HEART_SANCTUARY.z));
    if (s.phase === 'UNDISCOVERED') return { title: 'A heartbeat beneath the cliffs',
      detail: `Find the old temple beyond camp · ${distance} m. M: map · playtest travel is in the backpack.`, progress: 0 };
    const titles = { PREPARE: 'Shelter the World Heart', APPROACH: 'The dark is approaching', DEFEND: 'Hold the temple pass',
      REST: 'A moment of peace', WOUNDED: 'The ward has faltered', RESTORED: 'The Heart sings again' };
    const details = { PREPARE: 'B: build timber palisades at the 16 m pass. Q: choose spell · left click: cast. Touch the Heart with F when ready.',
      APPROACH: `Pulse ${s.wave}/3 · reach the pass · ${Math.max(0, Math.ceil(28 - s.seconds))} s.`,
      DEFEND: `Pulse ${s.wave}/3 · ${s.husks.filter(h => h.health > 0).length} approaching · Q: runes · F: repair a damaged defence.`,
      REST: 'Repair with branches, gather supplies and explore. F at the Heart starts the next pulse; there is no timer.',
      WOUNDED: 'Your buildings remain. Bring 2 logs + 1 stone to the Heart, then prepare another defence.',
      RESTORED: 'The sanctuary is quiet. Warmth returns to its garden. Your next journey can begin here.' };
    return { title: titles[s.phase], detail: this.lastNear ? details[s.phase] : 'The encounter waits while you are away. Return to the temple when ready.', progress: s.vitality };
  }

  drainMessages(): string[] { return this.model.messages.splice(0); }
  warmupMaterials(): readonly (ShaderMaterial | MeshStandardMaterial)[] {
    return [this.coreMaterial, this.veilMaterial, this.breachMaterial, ...this.husks.slice(0, 1).map(h => h.material)];
  }
  exportState(): SanctuarySave { return this.model.exportState(); }
  dispose(): void {
    this.hitboxDebug?.dispose();
    this.unsubscribe(); this.root.removeFromParent(); this.light.dispose();
    this.coreMaterial.dispose(); this.veilMaterial.dispose(); this.breachMaterial.dispose();
    for (const h of this.husks) h.material.dispose();
  }
}
