import {
  BufferGeometry,
  Float32BufferAttribute,
  Group,
  Mesh,
  MeshStandardMaterial,
  Vector2,
  type IUniform,
  type Scene,
} from 'three';
import { isBorealisLand } from './BorealisLand';
import type {
  LandSnowMutationBounds,
  LandSnowSystem,
} from './LandSnowSystem';
import {
  SnowDistantSurfaceMaterialController,
  type SnowSurfaceLighting,
} from './SnowSurfaceMaterial';
import type {
  TerrainEditBounds,
  TerrainHeightSystem,
} from './TerrainHeightSystem';
import { WINTER_WORLD_LOD } from '../world/WinterWorldLodPolicy';
import { winterSnowCoverage } from '../world/WinterSurfaceGeometry';
import { WinterSurfaceReadiness } from '../world/WinterSurfaceReadiness';

const TILE_METRES = 64;
const GRID_METRES = 2;
const SEGMENTS = TILE_METRES / GRID_METRES;
const SAMPLES = SEGMENTS + 1;
// Keep a complete medium snow owner past the nearby hills visible from OTS.
// 11×11 low-density tiles are still much cheaper than extending the 25 cm
// deformable simulation and move the hard streaming edge beyond the fade.
const RADIUS_TILES = 5;
const MAXIMUM_CACHE_TILES = 180;
const MAXIMUM_REBUILDS_PER_UPDATE = 2;
const REBUILD_SOFT_BUDGET_MS = 1.5;
const MAXIMUM_ROWS_PER_UPDATE = 16;

interface MidSnowTile {
  readonly key: string;
  readonly tileX: number;
  readonly tileZ: number;
  readonly mesh: Mesh<BufferGeometry, MeshStandardMaterial>;
  geometry: BufferGeometry;
  revision: number;
  ready: boolean;
  terrainDirty: boolean;
  spare?: BufferGeometry;
  pending?: { minColumn: number; maxColumn: number; minRow: number; maxRow: number };
  job?: { geometry: BufferGeometry; rows: Set<number>; minColumn: number; maxColumn: number; terrain: boolean };
}

export interface LandSnowMidLodStats {
  readonly activeTiles: number;
  readonly cachedTiles: number;
  readonly dirtyTiles: number;
  readonly vertices: number;
  readonly rebuiltTiles: number;
}

const tileKey = (x: number, z: number): string => `${x},${z}`;

const intersects = (
  tileX: number,
  tileZ: number,
  bounds: Readonly<LandSnowMutationBounds | TerrainEditBounds>,
): boolean => {
  const minX = tileX * TILE_METRES;
  const minZ = tileZ * TILE_METRES;
  return minX <= bounds.maxX &&
    minX + TILE_METRES >= bounds.minX &&
    minZ <= bounds.maxZ &&
    minZ + TILE_METRES >= bounds.minZ;
};

/**
 * Persistent two-metre presentation between canonical 25 cm snow and the
 * generated-world macro surface.
 *
 * It never owns simulation. Heights are resampled from LandSnowSystem, which
 * means ploughed paths and accumulated banks survive streaming at a cheap
 * resolution. A shader sinks this surface under the exact near snow and under
 * the conservative macro surface; no two renderers fight for the same pixel.
 */
export class LandSnowMidLodSystem {
  readonly readiness = new WinterSurfaceReadiness();
  private readonly root = new Group();
  private readonly active = new Map<string, MidSnowTile>();
  private readonly cache = new Map<string, MidSnowTile>();
  private readonly dirty = new Set<string>();
  private readonly viewer = { value: new Vector2() } satisfies IUniform<Vector2>;
  private readonly authoringMode = { value: 0 } satisfies IUniform<number>;
  private readonly material = new MeshStandardMaterial({
    name: 'Persistent winter surface · 2 m LOD',
    color: 0xe7eef2,
    vertexColors: true,
    roughness: 0.985,
    metalness: 0,
    polygonOffset: true,
    polygonOffsetFactor: -0.1,
    polygonOffsetUnits: -0.2,
  });
  private readonly surfaceMaterial: SnowDistantSurfaceMaterialController;
  private readonly removeSnowListener: () => void;
  private readonly removeTerrainListener: () => void;
  private centerTileX?: number;
  private centerTileZ?: number;
  private revision = 0;
  private rebuiltTiles = 0;
  private farSurfaceHeight?: (x: number, z: number) => number | undefined;

  public constructor(
    scene: Scene,
    private readonly snow: LandSnowSystem,
    private readonly terrain: TerrainHeightSystem,
  ) {
    this.root.name = 'Persistent winter surface · medium LOD';
    scene.add(this.root);

    const previousCompile = this.material.onBeforeCompile;
    this.material.onBeforeCompile = (shader, renderer) => {
      previousCompile.call(this.material, shader, renderer);
      shader.uniforms.uWinterMidViewer = this.viewer;
      shader.uniforms.uWinterMidAuthoringMode = this.authoringMode;
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          `#include <common>
uniform vec2 uWinterMidViewer;
attribute float aWinterFarHeight;
varying vec2 vWinterMidXZ;
uniform float uWinterMidAuthoringMode;`,
        )
        .replace(
          '#include <begin_vertex>',
          `#include <begin_vertex>
float winterMidDistance = distance(position.xz, uWinterMidViewer);
vWinterMidXZ = position.xz;
float winterMidMorph = smoothstep(
  ${WINTER_WORLD_LOD.midSnowOuterFadeStartMetres.toFixed(1)},
  ${WINTER_WORLD_LOD.midSnowOuterFadeEndMetres.toFixed(1)},
  winterMidDistance
);
transformed.y = mix(transformed.y, aWinterFarHeight, winterMidMorph);`,
        );
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', '#include <common>\nuniform vec2 uWinterMidViewer;\nvarying vec2 vWinterMidXZ;')
        .replace('#include <clipping_planes_fragment>', `#include <clipping_planes_fragment>
float winterMidRadialDistance = distance(vWinterMidXZ, uWinterMidViewer);
if (winterMidRadialDistance < ${WINTER_WORLD_LOD.midSnowInnerFadeEndMetres.toFixed(1)} ||
    winterMidRadialDistance >= ${WINTER_WORLD_LOD.midSnowOuterFadeEndMetres.toFixed(1)}) discard;`);
    };
    this.material.customProgramCacheKey = () => 'winter-mid-shared-height-v2';
    this.surfaceMaterial = new SnowDistantSurfaceMaterialController(this.material);
    this.removeSnowListener = snow.addMutationListener((bounds) =>
      this.invalidate(bounds),
    );
    this.removeTerrainListener = terrain.addListener((bounds) =>
      this.invalidate(bounds, true),
    );
  }

  public setVisible(visible: boolean): void {
    this.root.visible = visible;
  }

  public setFarSurfaceSampler(sample: (x: number, z: number) => number | undefined): void {
    this.farSurfaceHeight = sample;
    for (const tile of this.active.values()) { tile.terrainDirty = true; this.dirty.add(tile.key); }
    for (const tile of this.cache.values()) { tile.revision = -1; tile.terrainDirty = true; }
  }

  public setAuthoringPresentation(active: boolean): void {
    this.authoringMode.value = active ? 1 : 0;
    this.surfaceMaterial.setAuthoringMode(active);
  }

  /**
   * Re-samples the complete visible presentation after an atomic workspace or
   * canonical-snow swap. Normal gameplay edits stay time-sliced; a workspace
   * boundary must not show the previous map's 64 m tiles for even one frame.
   */
  public refreshAll(): void {
    this.revision += 1;
    for (const tile of this.active.values()) {
      // Never leave the previous workspace's surface visible while a new
      // world is sampled. The macro snow remains the presentation fallback.
      tile.ready = false;
      tile.terrainDirty = true;
      tile.job?.geometry.dispose(); tile.job = undefined; tile.pending = undefined;
      tile.mesh.visible = false;
      this.dirty.add(tile.key);
    }
    for (const tile of this.cache.values()) { tile.geometry.dispose(); tile.spare?.dispose(); }
    this.cache.clear();
    this.readiness.update(this.centerTileX ?? 0, this.centerTileZ ?? 0, this.active.values());
  }

  public setSurfaceLighting(lighting: Readonly<SnowSurfaceLighting>): void {
    this.surfaceMaterial.update(lighting);
  }

  public updateCenter(x: number, z: number): void {
    this.viewer.value.set(x, z);
    const centerTileX = Math.floor(x / TILE_METRES);
    const centerTileZ = Math.floor(z / TILE_METRES);
    if (
      centerTileX !== this.centerTileX ||
      centerTileZ !== this.centerTileZ
    ) {
      this.centerTileX = centerTileX;
      this.centerTileZ = centerTileZ;
      this.stream(centerTileX, centerTileZ);
    }
    this.rebuildDirty(x, z);
    this.readiness.update(centerTileX, centerTileZ, this.active.values());
  }

  public getStats(): LandSnowMidLodStats {
    return {
      activeTiles: this.active.size,
      cachedTiles: this.cache.size,
      dirtyTiles: this.dirty.size,
      vertices: this.active.size * SAMPLES * SAMPLES,
      rebuiltTiles: this.rebuiltTiles,
    };
  }

  public writePerformanceTrace(target: {
    midSnowTiles?: number;
    midSnowCachedTiles?: number;
    midSnowDirtyTiles?: number;
    midSnowVertices?: number;
    midSnowRebuiltTiles?: number;
  }): void {
    const stats = this.getStats();
    target.midSnowTiles = stats.activeTiles;
    target.midSnowCachedTiles = stats.cachedTiles;
    target.midSnowDirtyTiles = stats.dirtyTiles;
    target.midSnowVertices = stats.vertices;
    target.midSnowRebuiltTiles = stats.rebuiltTiles;
  }

  public dispose(): void {
    this.removeSnowListener();
    this.removeTerrainListener();
    for (const tile of [...this.active.values(), ...this.cache.values()]) {
      tile.geometry.dispose(); tile.job?.geometry.dispose(); tile.spare?.dispose();
    }
    this.active.clear();
    this.cache.clear();
    this.dirty.clear();
    this.material.dispose();
    this.readiness.dispose();
    this.root.removeFromParent();
  }

  private stream(centerTileX: number, centerTileZ: number): void {
    const requested = new Set<string>();
    for (let dz = -RADIUS_TILES; dz <= RADIUS_TILES; dz += 1) {
      for (let dx = -RADIUS_TILES; dx <= RADIUS_TILES; dx += 1) {
        const tileX = centerTileX + dx;
        const tileZ = centerTileZ + dz;
        if (!this.tileTouchesLand(tileX, tileZ)) continue;
        const key = tileKey(tileX, tileZ);
        requested.add(key);
        if (this.active.has(key)) continue;
        let tile = this.cache.get(key);
        if (tile) {
          this.cache.delete(key);
        } else {
          tile = this.createTile(tileX, tileZ);
          this.dirty.add(key);
        }
        this.active.set(key, tile);
        this.root.add(tile.mesh);
        tile.mesh.visible = tile.ready;
        if (!tile.ready || tile.revision < this.revision) this.dirty.add(key);
      }
    }
    for (const [key, tile] of this.active) {
      if (requested.has(key)) continue;
      this.active.delete(key);
      this.dirty.delete(key);
      if (tile.job) { tile.job.geometry.dispose(); tile.job = undefined; tile.terrainDirty = true; tile.revision = -1; }
      tile.mesh.removeFromParent();
      this.cache.delete(key);
      this.cache.set(key, tile);
    }
    while (this.cache.size > MAXIMUM_CACHE_TILES) {
      const oldest = this.cache.entries().next().value as
        | [string, MidSnowTile]
        | undefined;
      if (!oldest) break;
      this.cache.delete(oldest[0]);
      oldest[1].geometry.dispose();
      oldest[1].spare?.dispose();
    }
  }

  private invalidate(
    bounds: Readonly<LandSnowMutationBounds | TerrainEditBounds>,
    terrain = false,
  ): void {
    this.revision += 1;
    for (const tile of this.active.values()) {
      if (!intersects(tile.tileX, tile.tileZ, bounds)) continue;
      this.dirty.add(tile.key);
      tile.terrainDirty ||= terrain;
      const baseX = tile.tileX * TILE_METRES, baseZ = tile.tileZ * TILE_METRES;
      const range = {
        minColumn: Math.max(0, Math.floor((bounds.minX - baseX) / GRID_METRES) - 1),
        maxColumn: Math.min(SEGMENTS, Math.ceil((bounds.maxX - baseX) / GRID_METRES) + 1),
        minRow: Math.max(0, Math.floor((bounds.minZ - baseZ) / GRID_METRES) - 1),
        maxRow: Math.min(SEGMENTS, Math.ceil((bounds.maxZ - baseZ) / GRID_METRES) + 1),
      };
      const p = tile.pending;
      tile.pending = p ? { minColumn: Math.min(p.minColumn, range.minColumn), maxColumn: Math.max(p.maxColumn, range.maxColumn),
        minRow: Math.min(p.minRow, range.minRow), maxRow: Math.max(p.maxRow, range.maxRow) } : range;
    }
    for (const tile of this.cache.values()) {
      if (intersects(tile.tileX, tile.tileZ, bounds)) { tile.revision = -1; tile.terrainDirty ||= terrain; }
    }
  }

  private rebuildDirty(focusX: number, focusZ: number): void {
    if (this.dirty.size === 0) return;
    const candidates = [...this.dirty]
      .map((key) => this.active.get(key))
      .filter((tile): tile is MidSnowTile => tile !== undefined)
      .sort((left, right) => {
        const leftX = (left.tileX + 0.5) * TILE_METRES - focusX;
        const leftZ = (left.tileZ + 0.5) * TILE_METRES - focusZ;
        const rightX = (right.tileX + 0.5) * TILE_METRES - focusX;
        const rightZ = (right.tileZ + 0.5) * TILE_METRES - focusZ;
        return leftX * leftX + leftZ * leftZ -
          (rightX * rightX + rightZ * rightZ);
      });
    const startedAt = performance.now();
    let rows = 0;
    for (
      let index = 0;
      index < Math.min(MAXIMUM_REBUILDS_PER_UPDATE, candidates.length);
      index += 1
    ) {
      // Make progress on the nearest tile, then stop at the row/time limit.
      // Keep its previous complete mesh visible until the private job finishes.
      if (rows > 0 && performance.now() - startedAt >= REBUILD_SOFT_BUDGET_MS) break;
      const tile = candidates[index]!;
      do {
        rows++;
        if (this.writeTilePositions(tile)) { this.dirty.delete(tile.key); break; }
      } while (rows < MAXIMUM_ROWS_PER_UPDATE && performance.now() - startedAt < REBUILD_SOFT_BUDGET_MS);
      if (rows >= MAXIMUM_ROWS_PER_UPDATE) break;
    }
  }

  private createTile(tileX: number, tileZ: number): MidSnowTile {
    const geometry = new BufferGeometry();
    const positions = new Float32Array(SAMPLES * SAMPLES * 3);
    const indices: number[] = [];
    for (let row = 0; row < SEGMENTS; row += 1) {
      for (let column = 0; column < SEGMENTS; column += 1) {
        const a = row * SAMPLES + column;
        const b = a + 1;
        const c = a + SAMPLES;
        const d = c + 1;
        indices.push(a, c, b, b, c, d);
      }
    }
    geometry.setAttribute('position', new Float32BufferAttribute(positions, 3));
    geometry.setAttribute('aWinterFarHeight', new Float32BufferAttribute(new Float32Array(SAMPLES * SAMPLES), 1));
    geometry.setAttribute('aSnowCoverage', new Float32BufferAttribute(new Float32Array(SAMPLES * SAMPLES), 1));
    geometry.setAttribute('color', new Float32BufferAttribute(new Float32Array(SAMPLES * SAMPLES * 3), 3));
    geometry.setIndex(indices);
    const mesh = new Mesh(geometry, this.material);
    mesh.name = `Persistent winter surface ${tileX},${tileZ}`;
    mesh.receiveShadow = true;
    mesh.frustumCulled = true;
    const tile: MidSnowTile = {
      key: tileKey(tileX, tileZ),
      tileX,
      tileZ,
      mesh,
      geometry,
      revision: this.revision,
      ready: false,
      terrainDirty: true,
    };
    return tile;
  }

  /** One bounded row into a private buffer. Never expose a half-written tile.
   * Weather/heat edits reuse the unchanged far-terrain height and touch only
   * intersecting rows; terrain edits also refresh the static channels. */
  private writeTilePositions(tile: MidSnowTile): boolean {
    if (!tile.job) {
      const full = !tile.ready || tile.terrainDirty || !tile.pending;
      const range = full ? { minColumn: 0, maxColumn: SEGMENTS, minRow: 0, maxRow: SEGMENTS } : tile.pending!;
      const staging = tile.spare ?? tile.geometry.clone(); tile.spare = undefined;
      for (const name of ['position', 'aWinterFarHeight', 'aSnowCoverage', 'color']) {
        staging.getAttribute(name).array.set(tile.geometry.getAttribute(name).array);
      }
      tile.job = { geometry: staging, rows: new Set(), minColumn: range.minColumn, maxColumn: range.maxColumn,
        terrain: tile.terrainDirty || !tile.ready };
      for (let row = range.minRow; row <= range.maxRow; row++) tile.job.rows.add(row);
      tile.terrainDirty = false; tile.pending = undefined;
    }
    const job = tile.job;
    if (tile.pending || tile.terrainDirty) {
      const p = tile.terrainDirty ? { minColumn: 0, maxColumn: SEGMENTS, minRow: 0, maxRow: SEGMENTS } : tile.pending!;
      job.minColumn = Math.min(job.minColumn, p.minColumn); job.maxColumn = Math.max(job.maxColumn, p.maxColumn);
      for (let row = p.minRow; row <= p.maxRow; row++) job.rows.add(row);
      job.terrain ||= tile.terrainDirty; tile.terrainDirty = false; tile.pending = undefined;
    }
    const positions = job.geometry.getAttribute('position');
    const farHeight = job.geometry.getAttribute('aWinterFarHeight');
    const coverage = job.geometry.getAttribute('aSnowCoverage');
    const colors = job.geometry.getAttribute('color');
    const baseX = tile.tileX * TILE_METRES;
    const baseZ = tile.tileZ * TILE_METRES;
    const row = job.rows.values().next().value!;
      for (let column = job.minColumn; column <= job.maxColumn; column += 1) {
        const index = row * SAMPLES + column;
        const x = baseX + column * GRID_METRES;
        const z = baseZ + row * GRID_METRES;
        const height = this.snow.sampleSurfaceHeight(x, z);
        positions.setXYZ(index, x, height, z);
        if (job.terrain) farHeight.setX(index, this.farSurfaceHeight?.(x, z) ?? height);
        const cover = winterSnowCoverage(this.snow.sampleDepth(x, z));
        coverage.setX(index, cover);
        const surface = this.terrain.sampleMaterial(x, z);
        const ground = surface === 'ROCK' ? [.34,.38,.36] : surface === 'DIRT' ? [.35,.27,.2] :
          surface === 'ROAD' ? [.19,.205,.21] : surface === 'SIDEWALK' ? [.45,.48,.49] : [.22,.29,.27];
        colors.setXYZ(index,
          cover + (1-cover)*ground[0]!/this.material.color.r,
          cover + (1-cover)*ground[1]!/this.material.color.g,
          cover + (1-cover)*ground[2]!/this.material.color.b);
      }
    job.rows.delete(row);
    if (job.rows.size > 0) return false;
    // Commit the complete buffer in one frame; keep the old geometry until now.
    const old = tile.geometry;
    tile.geometry = job.geometry; tile.mesh.geometry = job.geometry; tile.job = undefined; tile.spare = old;
    positions.needsUpdate = true;
    farHeight.needsUpdate = true;
    coverage.needsUpdate = true;
    colors.needsUpdate = true;
    tile.geometry.computeVertexNormals();
    tile.geometry.computeBoundingSphere();
    tile.revision = this.revision;
    tile.ready = true;
    tile.mesh.visible = true;
    this.rebuiltTiles += 1;
    return true;
  }

  private tileTouchesLand(tileX: number, tileZ: number): boolean {
    if (this.terrain.getBaseProfile() === 'FLAT') return true;
    const baseX = tileX * TILE_METRES;
    const baseZ = tileZ * TILE_METRES;
    for (let row = 0; row <= 4; row += 1) {
      for (let column = 0; column <= 4; column += 1) {
        if (isBorealisLand(
          baseX + column * TILE_METRES / 4,
          baseZ + row * TILE_METRES / 4,
        )) return true;
      }
    }
    return false;
  }
}
