export enum IceCellOwner {
  OpenWater = 0,
  StaticPack = 1,
  DetachedFloe = 2,
  CoarseIce = 3,
}

export type IceCellOwnerName =
  | 'open-water'
  | 'static-pack'
  | 'detached-floe'
  | 'coarse-ice';

export const ICE_CELL_OWNER_NAMES: Readonly<Record<IceCellOwner, IceCellOwnerName>> = {
  [IceCellOwner.OpenWater]: 'open-water',
  [IceCellOwner.StaticPack]: 'static-pack',
  [IceCellOwner.DetachedFloe]: 'detached-floe',
  [IceCellOwner.CoarseIce]: 'coarse-ice',
};

// Fragments are pooled presentation effects and never own authoritative grid data.
export type IcePresentationOwner = IceCellOwnerName | 'visual-fragment';

export enum IceDirtyFlag {
  None = 0,
  Geometry = 1 << 0,
  Openness = 1 << 1,
  Snow = 1 << 2,
  Movement = 1 << 3,
  Appearance = 1 << 4,
  All =
    Geometry |
    Openness |
    Snow |
    Movement |
    Appearance,
}

export interface IceOwnershipStats {
  openWater: number;
  staticPack: number;
  detachedFloe: number;
  coarseIce: number;
}

export interface IceOwnershipDiagnostics {
  invalidOwnerCells: number;
  staticCellsWithLocalMotion: number;
  detachedCellsWithLocalMotion: number;
  detachedCellsWithoutFloe: number;
}

export interface IceRevisionStats {
  topology: number;
  geometry: number;
  openness: number;
  snow: number;
  movement: number;
  dirtyCells: number;
  dirtyChunks: number;
  fullVisualUpdates: number;
  partialVisualUpdates: number;
}

export const ICE_DIRTY_CHUNK_SIZE = 16;
export const ICE_OPEN_WATER_OPENNESS = 0.94;
export const MAX_DETACHED_FLOE_CELLS = 220;
