import { type PlayerId, playerId } from '../core/NetworkPrimitives';
import type {
  ConnectionId,
  NetworkEntityId,
  ServerTick,
  SessionEpoch,
  SessionId,
} from '../core/NetworkPrimitives';
import {
  ICEWAY_PROTOCOL_VERSION,
  type ProtocolVersion,
} from './ProtocolEnvelope';
import {
  validateSessionContinuityPolicyPayload,
  type SessionContinuityPolicyPayload,
} from './SessionContinuity';
import {
  validateSessionDeploymentPolicyPayload,
  type CompatibilityRejectionNoticePayload,
  type SessionDeploymentPolicyPayload,
} from './DeploymentPolicy';

export type SessionCapability =
  | 'JSON_PROTOCOL_V1'
  | 'LOOPBACK_TRANSPORT'
  | 'WEBSOCKET_TRANSPORT'
  | 'COMMAND_FRAMES_V1'
  | 'SERVICE_LANES_V1'
  | 'CONTROL_LEASES_V1'
  | 'ENTITY_SNAPSHOTS_V1'
  | 'SNOW_SPARSE_DELTAS_V1'
  | 'ICE_SPARSE_DELTAS_V1'
  | 'WORLD_STATE_EVENTS_V1'
  | 'CONSTRUCTION_BLUEPRINTS_V1'
  | 'PORTABLE_INVENTORY_V1'
  | 'INFRASTRUCTURE_RUNTIME_V1'
  | 'STAGED_BASELINES_V1'
  | 'AUTHORITY_EPOCH_TRANSITION_V1';

const SESSION_CAPABILITIES = new Set<SessionCapability>([
  'JSON_PROTOCOL_V1',
  'LOOPBACK_TRANSPORT',
  'WEBSOCKET_TRANSPORT',
  'COMMAND_FRAMES_V1',
  'SERVICE_LANES_V1',
  'CONTROL_LEASES_V1',
  'ENTITY_SNAPSHOTS_V1',
  'SNOW_SPARSE_DELTAS_V1',
  'ICE_SPARSE_DELTAS_V1',
  'WORLD_STATE_EVENTS_V1',
  'CONSTRUCTION_BLUEPRINTS_V1',
  'PORTABLE_INVENTORY_V1',
  'INFRASTRUCTURE_RUNTIME_V1',
  'STAGED_BASELINES_V1',
  'AUTHORITY_EPOCH_TRANSITION_V1',
]);

export const ICEWAY_WEBSOCKET_CAPABILITIES = Object.freeze([
  'JSON_PROTOCOL_V1',
  'WEBSOCKET_TRANSPORT',
  'COMMAND_FRAMES_V1',
  'SERVICE_LANES_V1',
  'CONTROL_LEASES_V1',
  'ENTITY_SNAPSHOTS_V1',
  'SNOW_SPARSE_DELTAS_V1',
  'ICE_SPARSE_DELTAS_V1',
  'WORLD_STATE_EVENTS_V1',
  'CONSTRUCTION_BLUEPRINTS_V1',
  'PORTABLE_INVENTORY_V1',
  'INFRASTRUCTURE_RUNTIME_V1',
  'STAGED_BASELINES_V1',
  'AUTHORITY_EPOCH_TRANSITION_V1',
] as const satisfies readonly SessionCapability[]);

export const ICEWAY_DEFAULT_WORLD_DATASET_ID = 'iceaway-world-v1';
export const ICEWAY_DEFAULT_WORLD_DATASET_HASH = 'iceway-world-dev-v1';
export const ICEWAY_DEFAULT_DEFINITION_SET_ID = 'iceway-definitions-v1';

export interface SessionCompatibilityDescriptor {
  protocolVersion: ProtocolVersion;
  buildId: string;
  worldDatasetId: string;
  worldDatasetHash: string;
  definitionSetIds: readonly string[];
  checkpointVersion: number;
  capabilities: readonly SessionCapability[];
}

export interface ClientHelloPayload {
  version: 1;
  clientInstanceId: string;
  requestedPlayerId?: PlayerId;
  resumeToken?: string;
  displayName: string;
  compatibility: SessionCompatibilityDescriptor;
}

export interface ServerHelloPayload {
  version: 1;
  accepted: boolean;
  authorityBuildId: string;
  compatibility: SessionCompatibilityDescriptor;
  negotiatedCapabilities: readonly SessionCapability[];
  rejection?: SessionCompatibilityRejection;
  rejectionNotice?: CompatibilityRejectionNoticePayload;
}

export interface JoinAcceptedPayload {
  version: 1;
  sessionId: SessionId;
  sessionEpoch: SessionEpoch;
  serverTick: ServerTick;
  playerId: PlayerId;
  connectionId: ConnectionId;
  resumeToken: string;
  characterEntityId?: NetworkEntityId;
  stateHashes: Readonly<{
    players: string;
    entities: string;
    leases: string;
    ingress: string;
    combined: string;
  }>;
  chatHistory: readonly SessionChatMessagePayload[];
}

export interface SessionChatMessagePayload {
  version: 1;
  messageId: string;
  playerId: PlayerId;
  displayName: string;
  serverTick: ServerTick;
  text: string;
}

export type SessionCompatibilityRejection =
  | 'PROTOCOL_MAJOR_MISMATCH'
  | 'CLIENT_PROTOCOL_TOO_OLD'
  | 'CLIENT_PROTOCOL_TOO_NEW'
  | 'BUILD_MISMATCH'
  | 'WORLD_DATASET_MISMATCH'
  | 'DEFINITION_SET_MISMATCH'
  | 'CHECKPOINT_VERSION_MISMATCH'
  | 'MISSING_REQUIRED_CAPABILITY';

export interface SessionCompatibilityPolicy {
  descriptor: SessionCompatibilityDescriptor;
  requiredCapabilities: readonly SessionCapability[];
  requireExactBuild: boolean;
  deploymentPolicy?: SessionDeploymentPolicyPayload;
}

export interface SessionBootstrapDescriptorPayload {
  version: 1;
  compatibility: SessionCompatibilityDescriptor;
  requiredCapabilities: readonly SessionCapability[];
  requireExactBuild: boolean;
  roomCapacity: number;
  continuityPolicy: SessionContinuityPolicyPayload;
  deploymentPolicy: SessionDeploymentPolicyPayload;
}

export interface IcewayCompatibilityDescriptorOptions {
  buildId: string;
  worldDatasetId?: string;
  worldDatasetHash?: string;
  definitionSetIds?: readonly string[];
  checkpointVersion?: number;
  capabilities?: readonly SessionCapability[];
}

export const createIcewayCompatibilityDescriptor = (
  options: Readonly<IcewayCompatibilityDescriptorOptions>,
): SessionCompatibilityDescriptor => ({
  protocolVersion: { ...ICEWAY_PROTOCOL_VERSION },
  buildId: options.buildId,
  worldDatasetId:
    options.worldDatasetId ?? ICEWAY_DEFAULT_WORLD_DATASET_ID,
  worldDatasetHash:
    options.worldDatasetHash ?? ICEWAY_DEFAULT_WORLD_DATASET_HASH,
  definitionSetIds: [
    ...(options.definitionSetIds ?? [ICEWAY_DEFAULT_DEFINITION_SET_ID]),
  ],
  checkpointVersion: options.checkpointVersion ?? 1,
  capabilities: [
    ...(options.capabilities ?? ICEWAY_WEBSOCKET_CAPABILITIES),
  ],
});

export type SessionCompatibilityResult =
  | {
      accepted: true;
      negotiatedCapabilities: readonly SessionCapability[];
    }
  | { accepted: false; reason: SessionCompatibilityRejection };

export type SessionDescriptorValidationResult =
  | { ok: true; value: SessionCompatibilityDescriptor }
  | { ok: false; reason: string };

export type ClientHelloValidationResult =
  | { ok: true; value: ClientHelloPayload }
  | { ok: false; reason: string };

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const isBoundedString = (value: unknown, maximum: number): value is string =>
  typeof value === 'string' &&
  value.trim().length > 0 &&
  value.length <= maximum;

export const validateSessionCompatibilityDescriptor = (
  input: unknown,
): SessionDescriptorValidationResult => {
  if (!isRecord(input) || !isRecord(input.protocolVersion)) {
    return { ok: false, reason: 'INVALID_DESCRIPTOR' };
  }
  const major = input.protocolVersion.major;
  const minor = input.protocolVersion.minor;
  if (
    typeof major !== 'number' ||
    typeof minor !== 'number' ||
    !Number.isSafeInteger(major) ||
    !Number.isSafeInteger(minor) ||
    major < 0 ||
    minor < 0
  ) {
    return { ok: false, reason: 'INVALID_PROTOCOL_VERSION' };
  }
  if (
    !isBoundedString(input.buildId, 160) ||
    !isBoundedString(input.worldDatasetId, 160) ||
    !isBoundedString(input.worldDatasetHash, 256)
  ) {
    return { ok: false, reason: 'INVALID_BUILD_OR_WORLD_IDENTITY' };
  }
  if (
    !Array.isArray(input.definitionSetIds) ||
    input.definitionSetIds.length > 128 ||
    !input.definitionSetIds.every((value) => isBoundedString(value, 160))
  ) {
    return { ok: false, reason: 'INVALID_DEFINITION_SETS' };
  }
  if (
    typeof input.checkpointVersion !== 'number' ||
    !Number.isSafeInteger(input.checkpointVersion) ||
    input.checkpointVersion < 0
  ) {
    return { ok: false, reason: 'INVALID_CHECKPOINT_VERSION' };
  }
  if (
    !Array.isArray(input.capabilities) ||
    input.capabilities.length > SESSION_CAPABILITIES.size ||
    !input.capabilities.every(
      (value) =>
        typeof value === 'string' &&
        SESSION_CAPABILITIES.has(value as SessionCapability),
    )
  ) {
    return { ok: false, reason: 'INVALID_CAPABILITIES' };
  }
  return {
    ok: true,
    value: {
      protocolVersion: { major, minor },
      buildId: input.buildId,
      worldDatasetId: input.worldDatasetId,
      worldDatasetHash: input.worldDatasetHash,
      definitionSetIds: normalizedSet(input.definitionSetIds as string[]),
      checkpointVersion: input.checkpointVersion,
      capabilities: normalizedSet(
        input.capabilities as SessionCapability[],
      ) as SessionCapability[],
    },
  };
};

export const validateSessionBootstrapDescriptorPayload = (
  input: unknown,
): SessionBootstrapDescriptorPayload | undefined => {
  if (
    !isRecord(input) ||
    input.version !== 1 ||
    !Array.isArray(input.requiredCapabilities) ||
    input.requiredCapabilities.length > SESSION_CAPABILITIES.size ||
    !input.requiredCapabilities.every(
      (value) =>
        typeof value === 'string' &&
        SESSION_CAPABILITIES.has(value as SessionCapability),
    ) ||
    typeof input.requireExactBuild !== 'boolean' ||
    typeof input.roomCapacity !== 'number' ||
    !Number.isSafeInteger(input.roomCapacity) ||
    input.roomCapacity < 1 ||
    input.roomCapacity > 16
  ) {
    return undefined;
  }
  const compatibility = validateSessionCompatibilityDescriptor(
    input.compatibility,
  );
  if (!compatibility.ok) return undefined;
  const continuityPolicy = validateSessionContinuityPolicyPayload(
    input.continuityPolicy,
  );
  if (!continuityPolicy) return undefined;
  const deploymentPolicy = validateSessionDeploymentPolicyPayload(
    input.deploymentPolicy,
  );
  if (!deploymentPolicy) return undefined;
  const available = new Set(compatibility.value.capabilities);
  const requiredCapabilities = normalizedSet(
    input.requiredCapabilities as SessionCapability[],
  ) as SessionCapability[];
  if (requiredCapabilities.some((capability) => !available.has(capability))) {
    return undefined;
  }
  return {
    version: 1,
    compatibility: compatibility.value,
    requiredCapabilities,
    requireExactBuild: input.requireExactBuild,
    roomCapacity: input.roomCapacity,
    continuityPolicy,
    deploymentPolicy,
  };
};

export const validateClientHelloPayload = (
  input: unknown,
): ClientHelloValidationResult => {
  if (!isRecord(input) || input.version !== 1) {
    return { ok: false, reason: 'INVALID_HELLO_VERSION' };
  }
  if (
    !isBoundedString(input.clientInstanceId, 160) ||
    !isBoundedString(input.displayName, 48) ||
    (input.requestedPlayerId !== undefined &&
      !isBoundedString(input.requestedPlayerId, 160)) ||
    (input.resumeToken !== undefined &&
      !isBoundedString(input.resumeToken, 256))
  ) {
    return { ok: false, reason: 'INVALID_CLIENT_IDENTITY' };
  }
  const compatibility = validateSessionCompatibilityDescriptor(
    input.compatibility,
  );
  if (!compatibility.ok) return compatibility;
  return {
    ok: true,
    value: {
      version: 1,
      clientInstanceId: input.clientInstanceId,
      requestedPlayerId:
        input.requestedPlayerId === undefined
          ? undefined
          : playerId(input.requestedPlayerId),
      resumeToken:
        input.resumeToken === undefined ? undefined : input.resumeToken,
      displayName: input.displayName.trim(),
      compatibility: compatibility.value,
    },
  };
};

const normalizedSet = (values: readonly string[]): readonly string[] =>
  [...new Set(values)].sort();

const equalSets = (a: readonly string[], b: readonly string[]): boolean => {
  const left = normalizedSet(a);
  const right = normalizedSet(b);
  return (
    left.length === right.length &&
    left.every((value, index) => value === right[index])
  );
};

export const evaluateSessionCompatibility = (
  client: Readonly<SessionCompatibilityDescriptor>,
  policy: Readonly<SessionCompatibilityPolicy>,
): SessionCompatibilityResult => {
  const authority = policy.descriptor;
  if (client.protocolVersion.major !== authority.protocolVersion.major) {
    return { accepted: false, reason: 'PROTOCOL_MAJOR_MISMATCH' };
  }
  if (
    policy.deploymentPolicy &&
    client.protocolVersion.major ===
      policy.deploymentPolicy.minimumClientProtocol.major &&
    client.protocolVersion.minor <
      policy.deploymentPolicy.minimumClientProtocol.minor
  ) {
    return { accepted: false, reason: 'CLIENT_PROTOCOL_TOO_OLD' };
  }
  if (client.protocolVersion.minor > authority.protocolVersion.minor) {
    return { accepted: false, reason: 'CLIENT_PROTOCOL_TOO_NEW' };
  }
  if (policy.requireExactBuild && client.buildId !== authority.buildId) {
    return { accepted: false, reason: 'BUILD_MISMATCH' };
  }
  if (
    !policy.requireExactBuild &&
    policy.deploymentPolicy &&
    policy.deploymentPolicy.acceptedClientBuildIds.length > 0 &&
    !policy.deploymentPolicy.acceptedClientBuildIds.includes(client.buildId)
  ) {
    return { accepted: false, reason: 'BUILD_MISMATCH' };
  }
  if (
    client.worldDatasetId !== authority.worldDatasetId ||
    client.worldDatasetHash !== authority.worldDatasetHash
  ) {
    return { accepted: false, reason: 'WORLD_DATASET_MISMATCH' };
  }
  if (!equalSets(client.definitionSetIds, authority.definitionSetIds)) {
    return { accepted: false, reason: 'DEFINITION_SET_MISMATCH' };
  }
  if (client.checkpointVersion !== authority.checkpointVersion) {
    return { accepted: false, reason: 'CHECKPOINT_VERSION_MISMATCH' };
  }
  const clientCapabilities = new Set(client.capabilities);
  if (
    policy.requiredCapabilities.some(
      (capability) => !clientCapabilities.has(capability),
    )
  ) {
    return { accepted: false, reason: 'MISSING_REQUIRED_CAPABILITY' };
  }
  const authorityCapabilities = new Set(authority.capabilities);
  return {
    accepted: true,
    negotiatedCapabilities: normalizedSet(
      client.capabilities.filter((capability) => authorityCapabilities.has(capability)),
    ) as SessionCapability[],
  };
};
