import { clamp, damp, smoothstep } from '../utils/math';

export type OceanPreviewMode = 'auto' | 'calm' | 'normal' | 'rough';
export type OceanTimeScale = 0.25 | 1 | 4;

export interface OceanConditionState {
  mode: OceanPreviewMode;
  frozen: boolean;
  timeScale: OceanTimeScale;
  motionTime: number;
  waveScale: number;
  swellStrength: number;
  directionOffset: number;
  weatherWaveMultiplier: number;
  weatherWindMultiplier: number;
  updates: number;
}

export interface OceanConditionSystemSaveData {
  version: 1;
  state: OceanConditionState;
  accumulator: number;
}

const CONDITION_STEP = 0.25;
const PREVIEW_MODES: readonly OceanPreviewMode[] = [
  'auto',
  'calm',
  'normal',
  'rough',
];
const TIME_SCALES: readonly OceanTimeScale[] = [0.25, 1, 4];

const cycleValue = <T>(
  values: readonly T[],
  current: T,
): T => {
  const index = values.indexOf(current);
  return values[(index + 1) % values.length] ?? values[0]!;
};

const swellEnvelopeAt = (time: number): number => {
  const cycleLength = 92;
  const cycle = Math.floor(time / cycleLength);
  const phase = (time - cycle * cycleLength) / cycleLength;
  const center = 0.42 + Math.sin(cycle * 2.71 + 0.8) * 0.08;
  const halfWidth = 0.18 + Math.sin(cycle * 1.37 + 2.1) * 0.025;
  const rise = smoothstep(
    center - halfWidth,
    center - halfWidth * 0.35,
    phase,
  );
  const fall =
    1 -
    smoothstep(
      center + halfWidth * 0.3,
      center + halfWidth,
      phase,
    );
  return clamp(rise * fall, 0, 1);
};

const targetsAt = (
  mode: OceanPreviewMode,
  time: number,
  weatherWaveMultiplier: number,
): Pick<OceanConditionState, 'waveScale' | 'swellStrength' | 'directionOffset'> => {
  const envelope = swellEnvelopeAt(time);
  const automaticWave =
    0.82 +
    Math.sin(time * 0.017 + 0.4) * 0.12 +
    Math.sin(time * 0.0061 - 1.2) * 0.08;
  const waveScale =
    mode === 'calm'
      ? 0.42
      : mode === 'normal'
        ? 0.82
        : mode === 'rough'
          ? 1.3
          : automaticWave;
  const swellStrength =
    mode === 'calm'
      ? envelope * 0.12
      : mode === 'normal'
        ? 0.08 + envelope * 0.42
        : mode === 'rough'
          ? 0.38 + envelope * 0.58
          : 0.05 + envelope * 0.68;
  const directionRange =
    mode === 'calm' ? 0.08 : mode === 'rough' ? 0.28 : 0.18;

  return {
    waveScale: waveScale * weatherWaveMultiplier,
    swellStrength:
      swellStrength * (0.88 + weatherWaveMultiplier * 0.12),
    directionOffset:
      Math.sin(time * 0.0083 + 0.7) * directionRange +
      Math.sin(time * 0.0027 - 1.4) * directionRange * 0.42,
  };
};

export class OceanConditionSystem {
  private readonly state: OceanConditionState = {
    mode: 'auto',
    frozen: false,
    timeScale: 1,
    motionTime: 0,
    waveScale: 0.82,
    swellStrength: 0.05,
    directionOffset: 0,
    weatherWaveMultiplier: 1,
    weatherWindMultiplier: 1,
    updates: 0,
  };
  private accumulator = 0;

  public update(deltaSeconds: number, masterTimeScale = 1): void {
    if (this.state.frozen) return;
    const delta = clamp(deltaSeconds, 0, 0.1) * clamp(
      masterTimeScale,
      1,
      64,
    );
    this.state.motionTime += delta * this.state.timeScale;
    this.accumulator += delta;

    while (this.accumulator >= CONDITION_STEP) {
      const targets = targetsAt(
        this.state.mode,
        this.state.motionTime,
        this.state.weatherWaveMultiplier,
      );
      this.state.waveScale = damp(
        this.state.waveScale,
        targets.waveScale,
        0.62,
        CONDITION_STEP,
      );
      this.state.swellStrength = damp(
        this.state.swellStrength,
        targets.swellStrength,
        0.48,
        CONDITION_STEP,
      );
      this.state.directionOffset = damp(
        this.state.directionOffset,
        targets.directionOffset,
        0.18,
        CONDITION_STEP,
      );
      this.state.updates += 1;
      this.accumulator -= CONDITION_STEP;
    }
  }

  public getState(): Readonly<OceanConditionState> {
    return this.state;
  }

  public exportState(): OceanConditionSystemSaveData {
    return {
      version: 1,
      state: { ...this.state },
      accumulator: this.accumulator,
    };
  }

  public importState(saved: unknown): boolean {
    if (!saved || typeof saved !== 'object') return false;
    const candidate = saved as Partial<OceanConditionSystemSaveData>;
    const state =
      candidate.state as Partial<OceanConditionState> | undefined;
    if (
      candidate.version !== 1 ||
      !state ||
      !PREVIEW_MODES.includes(state.mode as OceanPreviewMode) ||
      !TIME_SCALES.includes(state.timeScale as OceanTimeScale)
    ) {
      return false;
    }
    const numericState = [
      state.motionTime,
      state.waveScale,
      state.swellStrength,
      state.directionOffset,
      state.weatherWaveMultiplier,
      state.weatherWindMultiplier,
      state.updates,
      candidate.accumulator,
    ];
    if (!numericState.every((value) => Number.isFinite(value))) {
      return false;
    }

    Object.assign(this.state, {
      mode: state.mode,
      frozen: state.frozen === true,
      timeScale: state.timeScale,
      motionTime: Math.max(0, state.motionTime ?? 0),
      waveScale: clamp(state.waveScale ?? 0.82, 0.2, 2),
      swellStrength: clamp(state.swellStrength ?? 0.05, 0, 1.4),
      directionOffset: clamp(
        state.directionOffset ?? 0,
        -Math.PI,
        Math.PI,
      ),
      weatherWaveMultiplier: clamp(
        state.weatherWaveMultiplier ?? 1,
        0.7,
        1.5,
      ),
      weatherWindMultiplier: clamp(
        state.weatherWindMultiplier ?? 1,
        0.5,
        1.7,
      ),
      updates: Math.max(0, Math.floor(state.updates ?? 0)),
    });
    this.accumulator = clamp(
      candidate.accumulator ?? 0,
      0,
      CONDITION_STEP,
    );
    return true;
  }

  public setWeatherInfluence(
    waveMultiplier: number,
    windMultiplier: number,
  ): void {
    this.state.weatherWaveMultiplier = clamp(
      waveMultiplier,
      0.7,
      1.5,
    );
    this.state.weatherWindMultiplier = clamp(
      windMultiplier,
      0.5,
      1.7,
    );
  }

  public cyclePreviewMode(): OceanPreviewMode {
    this.state.mode = cycleValue(PREVIEW_MODES, this.state.mode);
    return this.state.mode;
  }

  public toggleFrozen(): boolean {
    this.state.frozen = !this.state.frozen;
    return this.state.frozen;
  }

  public cycleTimeScale(): OceanTimeScale {
    this.state.timeScale = cycleValue(TIME_SCALES, this.state.timeScale);
    return this.state.timeScale;
  }

  public setTimeScale(timeScale: OceanTimeScale): void {
    this.state.timeScale = timeScale;
  }
}
