import type {
  WorldChunkAddress,
  WorldPartitionDefinition,
} from './WorldPartitionTypes';
import {
  isChunkInWorldPartition,
  isValidWorldPartition,
} from './WorldPartitionTypes';

export interface ChunkLocalPosition {
  xMetres: number;
  yMetres: number;
  zMetres: number;
}

export interface GlobalPosition {
  chunk: WorldChunkAddress;
  local: ChunkLocalPosition;
}

export interface AbsoluteWorldPosition {
  xMetres: number;
  yMetres: number;
  zMetres: number;
}

export const cloneGlobalPosition = (
  position: Readonly<GlobalPosition>,
): GlobalPosition => ({
  chunk: { ...position.chunk },
  local: { ...position.local },
});

export const normalizeGlobalPosition = (
  partition: Readonly<WorldPartitionDefinition>,
  position: Readonly<GlobalPosition>,
): GlobalPosition => {
  if (!isValidWorldPartition(partition)) {
    throw new Error(
      `Invalid world partition "${partition.id}"`,
    );
  }
  const size = partition.chunkSizeMetres;
  const chunkOffsetX = Math.floor(
    position.local.xMetres / size,
  );
  const chunkOffsetZ = Math.floor(
    position.local.zMetres / size,
  );
  return {
    chunk: {
      x: position.chunk.x + chunkOffsetX,
      z: position.chunk.z + chunkOffsetZ,
    },
    local: {
      xMetres:
        position.local.xMetres - chunkOffsetX * size,
      yMetres: position.local.yMetres,
      zMetres:
        position.local.zMetres - chunkOffsetZ * size,
    },
  };
};

export const globalPositionFromAbsoluteMetres = (
  partition: Readonly<WorldPartitionDefinition>,
  position: Readonly<AbsoluteWorldPosition>,
): GlobalPosition =>
  normalizeGlobalPosition(partition, {
    chunk: { x: 0, z: 0 },
    local: { ...position },
  });

export const globalPositionToAbsoluteMetres = (
  partition: Readonly<WorldPartitionDefinition>,
  position: Readonly<GlobalPosition>,
): AbsoluteWorldPosition => {
  const normalized = normalizeGlobalPosition(
    partition,
    position,
  );
  return {
    xMetres:
      normalized.chunk.x * partition.chunkSizeMetres +
      normalized.local.xMetres,
    yMetres: normalized.local.yMetres,
    zMetres:
      normalized.chunk.z * partition.chunkSizeMetres +
      normalized.local.zMetres,
  };
};

export const globalPositionDistanceMetres = (
  partition: Readonly<WorldPartitionDefinition>,
  left: Readonly<GlobalPosition>,
  right: Readonly<GlobalPosition>,
): number => {
  const a = globalPositionToAbsoluteMetres(partition, left);
  const b = globalPositionToAbsoluteMetres(partition, right);
  return Math.hypot(
    b.xMetres - a.xMetres,
    b.yMetres - a.yMetres,
    b.zMetres - a.zMetres,
  );
};

export const isFiniteGlobalPosition = (
  position: Readonly<GlobalPosition>,
): boolean =>
  Number.isInteger(position.chunk.x) &&
  Number.isInteger(position.chunk.z) &&
  Number.isFinite(position.local.xMetres) &&
  Number.isFinite(position.local.yMetres) &&
  Number.isFinite(position.local.zMetres);

export const isNormalizedGlobalPosition = (
  partition: Readonly<WorldPartitionDefinition>,
  position: Readonly<GlobalPosition>,
): boolean =>
  isFiniteGlobalPosition(position) &&
  position.local.xMetres >= 0 &&
  position.local.xMetres < partition.chunkSizeMetres &&
  position.local.zMetres >= 0 &&
  position.local.zMetres < partition.chunkSizeMetres;

export const isGlobalPositionInPartition = (
  partition: Readonly<WorldPartitionDefinition>,
  position: Readonly<GlobalPosition>,
): boolean =>
  isNormalizedGlobalPosition(partition, position) &&
  isChunkInWorldPartition(partition, position.chunk);

