import {
  SURVIVAL_BUILDING_CATALOG,
  type SurvivalBuildPieceId,
} from './SurvivalBuildingCatalog';
import type {
  SurvivalConstructionMode,
  SurvivalConstructionView,
} from './SurvivalConstructionSystem';
import {
  wildernessRuneDefinition,
  type WildernessRuneId,
} from './WildernessRuneCatalog';
import type { WildernessRuneView } from './WildernessRuneSystem';
import { SURVIVAL_ROOF_TOOLS, survivalRoofTool } from './build-v3/SurvivalRoofPalette';

// Build V3 deliberately exposes the canonical straight/45° Yarrgone family.
// The old 15°/30° props remain loadable for save migration, but their freeform
// sockets do not belong in the authoritative structural palette.
const WORLD_BUILD_V3_CATALOG = SURVIVAL_BUILDING_CATALOG.filter((piece) =>
  piece.id !== 'LOG_WALL_CURVE_15' &&
  piece.id !== 'LOG_WALL_CURVE_30' &&
  !piece.automaticVariantOf);

type WildernessBuildCategoryId = 'STRUCTURE' | 'ROOF' | 'OPENINGS' | 'CAMP' | 'ANCIENT';

const WILDERNESS_BUILD_CATEGORIES: readonly Readonly<{
  id: WildernessBuildCategoryId;
  name: string;
  icon: string;
  pieceIds: readonly SurvivalBuildPieceId[];
}>[] = [
  {
    id: 'STRUCTURE', name: 'Structure', icon: '⌂',
    pieceIds: [
      'TIMBER_PALISADE', 'LOG_FOUNDATION', 'LOG_POST', 'LOG_BEAM', 'LOG_WALL_STRAIGHT',
      'LOG_WALL_45', 'TIMBER_FLOOR', 'TIMBER_FLOOR_TRIANGLE', 'TIMBER_FLOOR_EQUILATERAL',
      'EARTH_BERM_WALL', 'DUGOUT_ROOF',
    ],
  },
  { id: 'ROOF', name: 'Roof', icon: '⌃', pieceIds: SURVIVAL_ROOF_TOOLS.map(tool => tool.primary) },
  {
    id: 'OPENINGS', name: 'Openings', icon: '⊔',
    pieceIds: [
      'DOOR_FRAME', 'LOG_WALL_WINDOW', 'TIMBER_STAIRS',
      'LOG_HALF_WALL',
    ],
  },
  {
    id: 'CAMP', name: 'Camp', icon: '✷',
    pieceIds: [
      'CAMP_BEDROLL', 'CAMP_COOK_RACK', 'CAMP_FIREWOOD_RACK',
      'OUTDOOR_BRAZIER', 'WALL_TORCH_HEMP', 'WALL_TORCH_TAR', 'WALL_TORCH_HOLDER',
      'COAL_BRAZIER', 'HANGING_COAL_BRAZIER', 'OIL_LAMP_TABLE', 'OIL_LAMP_STANDING', 'OIL_LAMP_HANGING',
      'STONE_FIREPLACE', 'FIREPLACE_COOKING_INSERT',
      'CHIMNEY_STRAIGHT', 'CHIMNEY_CAP', 'STORAGE_CHEST_SMALL', 'TIMBER_TABLE', 'TIMBER_CHAIR', 'TIMBER_SHELF',
      'WARM_GARDEN_BED',
    ],
  },
  {
    id: 'ANCIENT', name: 'Ancient', icon: '✧',
    pieceIds: [
      'RUNE_FOCUS_STONE', 'STONE_FOUNDATION', 'STONE_WALL', 'STONE_ARCH',
      'STONE_FLOOR', 'STONE_FLOOR_TRIANGLE', 'STONE_ROOF',
    ],
  },
] as const;

const buildCategory = (id: WildernessBuildCategoryId) =>
  WILDERNESS_BUILD_CATEGORIES.find((category) => category.id === id) ??
  WILDERNESS_BUILD_CATEGORIES[0]!;

const categoryForBuildPiece = (
  id: SurvivalBuildPieceId,
): WildernessBuildCategoryId | undefined => WILDERNESS_BUILD_CATEGORIES.find(
  (category) => category.pieceIds.includes(survivalRoofTool(id)?.primary ?? id),
)?.id;

const categoryPieces = (id: WildernessBuildCategoryId) => buildCategory(id).pieceIds
  .map((pieceId) => WORLD_BUILD_V3_CATALOG.find((piece) => piece.id === pieceId))
  .filter((piece) => piece !== undefined);

const BUILD_HUD_LAYOUT_STORAGE_KEY = 'tlw-build-hud-layout-v1';
const BUILD_HUD_SCALE_MIN = 0.72;
const BUILD_HUD_SCALE_MAX = 1.38;
const SURVIVAL_HUD_LAYOUT_STORAGE_KEY = 'tlw-survival-hud-layout-v1';
const HUD_VIEWPORT_MARGIN = 8;
const SURVIVAL_HUD_ISLANDS = [
  ['objective', '.wilderness-survival-objective'],
  ['vitals', '.wilderness-survival-vitals'],
  ['pack', '.wilderness-survival-pack'],
  ['tools', '.wilderness-survival-tools'],
  ['context', '.wilderness-survival-context'],
  ['jump', '.wilderness-survival-jump'],
  ['world-craft-launchers', '.wilderness-world-craft-launchers'],
  ['performance', '#drive-performance-summary'],
] as const;

interface BuildHudLayout {
  readonly scale: number;
  readonly x?: number;
  readonly y?: number;
}

interface SurvivalHudIslandLayout {
  x: number;
  y: number;
  scale: number;
}

export class WildernessWorldCraftHUD {
  private readonly element: HTMLElement;
  private readonly buildPanel: HTMLElement;
  private readonly runePanel: HTMLElement;
  private readonly buildStatus: HTMLElement;
  private readonly buildHandName: HTMLElement;
  private readonly buildHandHint: HTMLElement;
  private readonly hammerCursor: HTMLElement;
  private signature = '';
  private buildCatalogExpanded = true;
  private buildToolsExpanded = true;
  private activeBuildCategory: WildernessBuildCategoryId = 'STRUCTURE';
  private buildMode: SurvivalConstructionMode = 'INACTIVE';
  private selectedBuildPiece?: SurvivalBuildPieceId;
  private runeWheelRotation = 0;
  private runeWheelAccumulator = 0;
  private runeWheelWasOpen = false;
  private runeWheelIds: readonly WildernessRuneId[] = [];
  private runeWheelSelected: WildernessRuneId = 'FIRE_GATE';
  private buildHudScale = 1;
  private buildHudPosition?: { x: number; y: number };
  private buildHudDrag?: Readonly<{
    pointerId: number;
    offsetX: number;
    offsetY: number;
  }>;
  private survivalHudLayoutEditing = false;
  private survivalHudLayouts: Record<string, SurvivalHudIslandLayout> = {};
  private readonly survivalHudVisibilityObserver?: MutationObserver;
  private survivalHudDrag?: Readonly<{
    pointerId: number;
    key: string;
    startClientX: number;
    startClientY: number;
    startX: number;
    startY: number;
  }>;

  public constructor(
    root: HTMLElement,
    actions: Readonly<{
      onToggleBuild: () => void;
      onToggleRunes: () => void;
      onSelectBuildPiece: (id: SurvivalBuildPieceId) => void;
      onSetBuildMode: (mode: SurvivalConstructionMode) => void;
      onRotate: (fine: boolean) => void;
      onCyclePaint: () => void;
      onCycleLevel: (direction: -1 | 1) => void;
      onBuildVisibility?: (group: 'ROOF' | 'UPPER' | 'RESET') => void;
      onToggleMirror: () => void;
      onTogglePrecisionGrid: () => void;
      onTogglePlacementStyle?: () => void;
      onCycleRoofProfile?: () => void;
      onUndo: () => void;
      onRedo: () => void;
      onConfirm: () => void;
      onSelectRune: (id: WildernessRuneId) => void;
      onCancel: () => void;
    }>,
  ) {
    this.element = document.createElement('section');
    this.element.className = 'wilderness-world-craft-hud is-hidden';
    this.element.innerHTML = `
      <nav class="wilderness-world-craft-launchers" aria-label="World crafting">
        <button data-world-craft="build"><kbd>B</kbd><span>BUILD</span><small>IN WORLD</small></button>
        <button data-world-craft="runes"><kbd>Q</kbd><span>RUNES</span><small>QUICK WHEEL</small></button>
      </nav>
      <section class="wilderness-world-craft-panel is-hidden" data-world-craft-panel="build">
        <header data-world-build-drag-handle title="Drag to move the build workbench">
          <span><strong>BUILD</strong></span>
          <span class="wilderness-build-window-controls">
            <button data-world-craft="catalog" title="Show or hide building parts" aria-label="Show or hide building parts">▦</button>
            <button data-world-craft="scale-down" title="Make build HUD smaller" aria-label="Make build HUD smaller">A−</button>
            <button data-world-craft="scale-up" title="Make build HUD larger" aria-label="Make build HUD larger">A+</button>
            <button data-world-craft="reset-layout" title="Reset build HUD position and size" aria-label="Reset build HUD layout">⌂</button>
            <button data-world-craft="layout-hud" title="Arrange all survival HUD islands" aria-label="Arrange survival HUD">HUD</button>
            <button data-world-craft="cancel" title="Close build mode" aria-label="Close build mode">×</button>
          </span>
        </header>
        <nav class="wilderness-build-categories" aria-label="Build categories">
          ${WILDERNESS_BUILD_CATEGORIES.map((category) => `
            <button data-world-build-category="${category.id}" title="${category.name}">
              <i>${category.icon}</i><span>${category.name}</span>
            </button>
          `).join('')}
        </nav>
        <section class="wilderness-build-hand" aria-label="Selected build part">
          <span class="wilderness-build-hand-copy">
            <small>IN HAND</small>
            <strong data-world-build-hand>EMPTY HAND</strong>
            <em data-world-build-hand-hint>Select a part below</em>
          </span>
          <p data-world-craft-status="build"></p>
        </section>
        <nav class="wilderness-world-craft-pieces" aria-label="Building parts">
          ${WILDERNESS_BUILD_CATEGORIES.map((category) => `
            <section class="wilderness-world-craft-family" data-build-category-pieces="${category.id}">
              <h3>${category.name}</h3>
              <div>
                ${categoryPieces(category.id).map((piece, index) => `
                  <button data-world-build-piece="${piece.id}" title="${piece.description}">
                    ${index < 9 ? `<kbd>${index + 1}</kbd>` : ''}
                    <i>${piece.icon}</i><span>${survivalRoofTool(piece.id)?.name ?? piece.name}</span>
                  </button>
                `).join('')}
              </div>
            </section>
          `).join('')}
        </nav>
        <aside class="wilderness-build-tools" aria-label="Build tools">
          <button class="wilderness-build-tools-toggle" data-world-craft="tools" title="Show or hide build tools" aria-label="Show or hide build tools">⚒</button>
          <div class="wilderness-build-tools-body">
            <div class="wilderness-build-toolrail" role="toolbar" aria-label="Edit tools">
              <button data-world-build-mode="HAND" title="Empty hand (X)"><i>✋</i><span>Hand</span><kbd>X</kbd></button>
              <button data-world-build-mode="REMOVE" title="Demolition hammer (H)"><i>⚒</i><span>Remove</span><kbd>H</kbd></button>
              <button data-world-build-mode="PAINT" title="Finish brush (P)"><i>◩</i><span>Paint</span><kbd>P</kbd></button>
              <button data-world-build-mode="PICK" title="Copy part (V)"><i>⌁</i><span>Copy</span><kbd>V</kbd></button>
            </div>
            <div class="wilderness-build-adjustment-group" aria-label="Transform tools">
              <button data-world-craft="rotate" title="Rotate 90° (R)"><b>↻</b><small>90°</small></button>
              <button data-world-craft="rotate-fine" title="Rotate 15° (Shift + R)"><b>15°</b><small>FINE</small></button>
              <button data-world-craft="mirror" title="Mirror"><b>⇄</b><small>MIRROR</small></button>
              <button data-world-craft="paint" title="Next finish"><b>◈</b><small>FINISH</small></button>
              <button data-world-craft="precision-grid" title="Local alignment grid on/off (G)"><b>▦</b><small>GRID G</small></button>
              <button data-world-craft="placement-style" title="Grid painting or Build V4 free/socket placement"><b>⌖</b><small>GRID</small></button>
              <button data-world-craft="roof-profile" title="New roof profile: gable, shed or mansard"><b>⌂</b><small>GABLE</small></button>
            </div>
            <div class="wilderness-build-adjustment-group wilderness-build-storey" aria-label="Storey">
              <button data-world-craft="level-down" title="Previous storey"><b>−</b></button>
              <strong data-world-build-level>1</strong>
              <button data-world-craft="level-up" title="Next storey"><b>+</b></button>
            </div>
            <div class="wilderness-build-adjustment-group" aria-label="History">
              <button data-world-craft="undo" title="Undo"><b>↶</b></button>
              <button data-world-craft="redo" title="Redo"><b>↷</b></button>
            </div>
            <div class="wilderness-build-adjustment-group" aria-label="Build visibility">
              <button data-build-visibility="ROOF" title="Roof cover: solid → ghost → hidden"><b>⌂</b><small>COVER</small></button>
              <button data-build-visibility="UPPER" title="Storeys above the selected level: solid → ghost → hidden"><b>▤</b><small>ABOVE</small></button>
              <button data-build-visibility="RESET" title="Restore all building visibility"><b>◉</b><small>RESET</small></button>
            </div>
          </div>
        </aside>
      </section>
      <span class="wilderness-build-hammer-cursor is-hidden" aria-hidden="true">🔨</span>
      <section class="wilderness-rune-wheel is-hidden" data-world-craft-panel="runes" aria-label="Rune quick select">
        <div class="wilderness-rune-wheel-scroll-zone" aria-hidden="true"></div>
        <div class="wilderness-rune-wheel-slots" data-rune-wheel-slots></div>
        <button class="wilderness-rune-wheel-centre" data-world-craft="runes">
          <kbd>Q</kbd><span>RUNES</span><small>SCROLL · ROTATE</small>
        </button>
      </section>
    `;
    root.appendChild(this.element);
    this.buildPanel = this.require('[data-world-craft-panel="build"]');
    this.runePanel = this.require('[data-world-craft-panel="runes"]');
    this.buildStatus = this.require('[data-world-craft-status="build"]');
    this.buildHandName = this.require('[data-world-build-hand]');
    this.buildHandHint = this.require('[data-world-build-hand-hint]');
    this.hammerCursor = this.require('.wilderness-build-hammer-cursor');
    this.restoreBuildHudLayout();
    this.restoreSurvivalHudLayouts();
    if (typeof MutationObserver !== 'undefined') {
      this.survivalHudVisibilityObserver = new MutationObserver((records) => {
        for (const record of records) {
          const island = record.target as HTMLElement;
          const key = island.dataset.tlwHudLayoutKey;
          if (!key || !this.survivalHudLayouts[key]) continue;
          requestAnimationFrame(() => this.applySurvivalHudIslandLayout(key));
        }
      });
      for (const [key] of SURVIVAL_HUD_ISLANDS) {
        const island = this.findSurvivalHudIsland(key);
        if (island) this.survivalHudVisibilityObserver.observe(island, {
          attributes: true,
          attributeFilter: ['class'],
        });
      }
    }
    this.require('[data-world-build-drag-handle]')
      .addEventListener('pointerdown', this.onBuildHudDragStart);
    document.addEventListener('pointermove', this.onDocumentPointerMove);
    document.addEventListener('pointerdown', this.onDocumentPointerDown);
    document.addEventListener('pointerup', this.onDocumentPointerUp);
    document.addEventListener('wheel', this.onDocumentLayoutWheel, { passive: false });
    document.addEventListener('click', this.onDocumentLayoutClick, true);
    document.addEventListener('dblclick', this.onDocumentLayoutDoubleClick, true);
    window.addEventListener('resize', this.onWindowResize);
    this.runePanel.addEventListener('wheel', (event) => {
      event.preventDefault();
      this.runeWheelAccumulator += event.deltaY;
      if (Math.abs(this.runeWheelAccumulator) < 24) return;
      this.runeWheelRotation += this.runeWheelAccumulator > 0 ? 1 : -1;
      this.runeWheelAccumulator = 0;
      this.renderRuneWheel();
    }, { passive: false });
    this.element.addEventListener('click', (event) => {
      const target = event.target as HTMLElement;
      const action = target.closest<HTMLElement>('[data-world-craft]')?.dataset.worldCraft;
      const piece = target.closest<HTMLElement>('[data-world-build-piece]')
        ?.dataset.worldBuildPiece as SurvivalBuildPieceId | undefined;
      const mode = target.closest<HTMLElement>('[data-world-build-mode]')
        ?.dataset.worldBuildMode as SurvivalConstructionMode | undefined;
      const category = target.closest<HTMLElement>('[data-world-build-category]')
        ?.dataset.worldBuildCategory as WildernessBuildCategoryId | undefined;
      const rune = target.closest<HTMLElement>('[data-world-rune]')
        ?.dataset.worldRune as WildernessRuneId | undefined;
      if (category) this.setActiveBuildCategory(category);
      if (piece) {
        if (this.buildMode === 'PLACE' && this.selectedBuildPiece === piece) {
          actions.onSetBuildMode('HAND');
        } else {
          actions.onSelectBuildPiece(piece);
        }
        // The narrow left library deliberately remains available while the
        // bottom quickbar changes hand. PARTS is the explicit hide/show action.
      }
      if (mode) {
        actions.onSetBuildMode(
          mode !== 'HAND' && this.buildMode === mode ? 'HAND' : mode,
        );
      }
      if (rune) actions.onSelectRune(rune);
      const visibility = target.closest<HTMLElement>('[data-build-visibility]')?.dataset.buildVisibility as 'ROOF' | 'UPPER' | 'RESET' | undefined;
      if (visibility) actions.onBuildVisibility?.(visibility);
      if (action === 'build') {
        this.buildCatalogExpanded = true;
        actions.onToggleBuild();
      }
      if (action === 'catalog') {
        this.buildCatalogExpanded = !this.buildCatalogExpanded;
        this.syncBuildCatalogClass();
      }
      if (action === 'tools') {
        this.buildToolsExpanded = !this.buildToolsExpanded;
        this.syncBuildCatalogClass();
      }
      if (action === 'runes') actions.onToggleRunes();
      if (action === 'rotate') actions.onRotate(false);
      if (action === 'rotate-fine') actions.onRotate(true);
      if (action === 'paint') actions.onCyclePaint();
      if (action === 'level-down') actions.onCycleLevel(-1);
      if (action === 'level-up') actions.onCycleLevel(1);
      if (action === 'mirror') actions.onToggleMirror();
      if (action === 'precision-grid') actions.onTogglePrecisionGrid();
      if (action === 'placement-style') actions.onTogglePlacementStyle?.();
      if (action === 'roof-profile') actions.onCycleRoofProfile?.();
      if (action === 'undo') actions.onUndo();
      if (action === 'redo') actions.onRedo();
      if (action === 'confirm') actions.onConfirm();
      if (action === 'cancel') actions.onCancel();
      if (action === 'scale-down') this.scaleBuildHud(-0.1);
      if (action === 'scale-up') this.scaleBuildHud(0.1);
      if (action === 'reset-layout') this.resetBuildHudLayout();
      if (action === 'layout-hud') this.setSurvivalHudLayoutEditing(
        !this.survivalHudLayoutEditing,
      );
    });
  }

  public setVisible(visible: boolean): void {
    this.element.classList.toggle('is-hidden', !visible);
    if (!visible) this.setSurvivalHudLayoutEditing(false);
    if (visible) requestAnimationFrame(() => this.clampAllHudLayouts());
  }

  /** Number keys always address the visible category, not a hidden fixed bar. */
  public quickBuildDefinitionId(slotIndex: number): SurvivalBuildPieceId | undefined {
    return buildCategory(this.activeBuildCategory).pieceIds[slotIndex];
  }

  public update(
    build: Readonly<SurvivalConstructionView>,
    runes: Readonly<WildernessRuneView>,
  ): void {
    const buildOpen = build.mode !== 'INACTIVE';
    const buildWasOpen = this.buildMode !== 'INACTIVE';
    const runeOpen = runes.paletteOpen;
    if (runeOpen && !this.runeWheelWasOpen) {
      const ringLength = Math.max(10, runes.availableRuneIds.length);
      const selectedIndex = runes.availableRuneIds.indexOf(runes.selectedRuneId);
      this.runeWheelRotation = selectedIndex >= 0
        ? (ringLength - selectedIndex) % ringLength
        : 0;
      this.runeWheelAccumulator = 0;
    }
    this.runeWheelWasOpen = runeOpen;
    this.runeWheelIds = runes.availableRuneIds;
    this.runeWheelSelected = runes.selectedRuneId;
    this.buildPanel.classList.toggle('is-hidden', !buildOpen);
    this.buildMode = build.mode;
    if (!buildOpen && buildWasOpen) this.setSurvivalHudLayoutEditing(false);
    if (buildOpen && !buildWasOpen && this.buildHudPosition) {
      requestAnimationFrame(() => this.onWindowResize());
    }
    this.selectedBuildPiece = build.selectedDefinitionId;
    const selectedCategory = categoryForBuildPiece(build.selectedDefinitionId);
    if (selectedCategory && buildOpen && !buildWasOpen) {
      this.activeBuildCategory = selectedCategory;
    }
    if (build.mode !== 'REMOVE') this.hammerCursor.classList.add('is-hidden');
    this.syncBuildCatalogClass();
    this.runePanel.classList.toggle('is-hidden', !runeOpen);
    this.element.classList.toggle('is-open', buildOpen || runeOpen);
    this.element.querySelector('[data-world-craft="build"]')?.classList.toggle('is-selected', buildOpen);
    this.element.querySelectorAll('[data-world-craft="runes"]')
      .forEach((button) => button.classList.toggle('is-selected', runeOpen || runes.tracing || Boolean(runes.spellArmed)));
    const nextSignature = [
      build.mode,
      build.selectedDefinitionId,
      build.selectedPaintId,
      build.gridMetres,
      build.valid,
      build.status,
      build.pieceCount,
      build.mirrored,
      build.precisionGrid,
      build.freePlacementDepth?.toFixed(2),
      build.structuralLevel,
      build.roofVisibility, build.upperVisibility,
      build.canUndo,
      build.canRedo,
      build.roofSpanBays,
      build.roofSpanMode,
      build.roofProfile,
      build.roofPitchDegrees, build.placementStyle,
      build.unlockedPieceIds.join(','),
      runes.paletteOpen,
      runes.tracing,
      runes.selectedRuneId,
      runes.status,
      runes.activeRunes,
      runes.availableRuneIds.join(','),
    ].join('|');
    if (nextSignature === this.signature) return;
    this.signature = nextSignature;
    const toolName = build.mode === 'HAND'
      ? 'EMPTY HAND'
      : build.mode === 'REMOVE'
        ? 'DEMOLITION HAMMER'
        : build.mode === 'PAINT'
          ? 'FINISH BRUSH'
          : build.mode === 'PICK'
            ? 'COPY TOOL'
            : build.selectedPieceName.toUpperCase();
    this.buildHandName.textContent = toolName;
    const roofTool = survivalRoofTool(build.selectedDefinitionId);
    this.buildHandHint.textContent = build.mode === 'PLACE'
      ? build.freePlacementDepth!==undefined
        ? `Surface · wheel depth offset · Alt+wheel zoom · G grid`
      : build.selectedDefinitionId.startsWith('ROOF_') && !['ROOF_COVER','ROOF_GABLE','ROOF_BATTEN','ROOF_BRACE'].includes(build.selectedDefinitionId)
        ? 'Q/E length/height · R direction · Shift+R pitch · G half-grid'
      : build.selectedDefinitionId.startsWith('ROOF_')
        ? 'Aim at real timber sockets · click to place · G half-grid'
      : build.canAdjustRoofSpan
        ? `${build.roofProfile} · ${build.roofSpanMetres} m · Shift + wheel width · click frames to assemble`
      : build.placementStyle === 'SOCKET'
        ? `Storey ${build.structuralLevel + 1} · sockets · R rotate · G grid`
        : `${build.costLabel} · click-drag to paint`
      : build.mode === 'REMOVE'
        ? 'Click one highlighted part to reclaim it'
        : build.mode === 'PAINT'
          ? `${build.selectedPaintId.replaceAll('_', ' ')} · hold and sweep`
          : build.mode === 'PICK'
            ? 'Click an existing part to copy it'
            : 'Aim + X reclaims one part · select a part below';
    this.buildStatus.innerHTML = `<small class="${build.valid ? '' : 'is-warning'}">${build.status}</small><span>${build.pieceCount}</span>`;
    const level = this.element.querySelector<HTMLElement>('[data-world-build-level]');
    if (level) level.textContent = String(build.structuralLevel + 1);
    for (const [group, state] of [['ROOF',build.roofVisibility],['UPPER',build.upperVisibility]] as const) {
      const button = this.element.querySelector<HTMLButtonElement>(`[data-build-visibility="${group}"]`);
      if (button) {
        button.style.color = state === 'HIDDEN' ? '#8b8c89' : state === 'GHOST' ? '#82bce0' : '#7fc9a6';
        button.title = `${group === 'ROOF' ? 'Roof cover' : 'Upper storeys'}: ${state ?? 'SOLID'} → click to change`;
        button.setAttribute('aria-label', `${group === 'ROOF' ? 'Roof cover' : 'Upper storeys'}: ${state ?? 'SOLID'}. Click to cycle visibility.`);
      }
    }
    this.renderRuneWheel();
    this.element.querySelectorAll<HTMLButtonElement>('[data-world-build-piece]').forEach((button) => {
      const id = button.dataset.worldBuildPiece as SurvivalBuildPieceId;
      button.classList.toggle(
        'is-selected',
        build.mode === 'PLACE' && id === (roofTool?.primary ?? build.selectedDefinitionId),
      );
      button.disabled = !build.unlockedPieceIds.includes(id);
      button.title = button.disabled
        ? 'Study the buried laboratory to learn ancient stonework.'
        : button.title;
    });
    this.element.querySelectorAll<HTMLElement>('[data-world-build-mode]').forEach((button) =>
      button.classList.toggle('is-selected', button.dataset.worldBuildMode === build.mode));
    this.element.querySelector('[data-world-craft="mirror"]')?.classList.toggle('is-selected', build.mirrored);
    this.element.querySelector('[data-world-craft="precision-grid"]')?.classList.toggle(
      'is-selected',
      build.precisionGrid,
    );
    const roofProfile = this.element.querySelector<HTMLElement>('[data-world-craft="roof-profile"]');
    const placementStyle=this.element.querySelector<HTMLElement>('[data-world-craft="placement-style"]');
    if(placementStyle){placementStyle.querySelector('small')!.textContent=build.placementStyle??'GRID';
      placementStyle.setAttribute('aria-pressed',String(build.placementStyle==='SOCKET'));}
    if (roofProfile) {
      roofProfile.hidden = !build.canAdjustRoofSpan && build.selectedDefinitionId!=='ROOF_RAFTER';
      roofProfile.title=build.selectedDefinitionId==='ROOF_RAFTER'?'Change rafter pitch · Shift+R':'New roof profile';
      roofProfile.querySelector('small')!.textContent = build.selectedDefinitionId==='ROOF_RAFTER'?`${build.roofPitchDegrees??30}°`:build.roofProfile ?? 'GABLE';
    }
    const undo = this.element.querySelector<HTMLButtonElement>('[data-world-craft="undo"]');
    const redo = this.element.querySelector<HTMLButtonElement>('[data-world-craft="redo"]');
    if (undo) undo.disabled = !build.canUndo;
    if (redo) redo.disabled = !build.canRedo;
  }

  public dispose(): void {
    document.removeEventListener('pointermove', this.onDocumentPointerMove);
    document.removeEventListener('pointerdown', this.onDocumentPointerDown);
    document.removeEventListener('pointerup', this.onDocumentPointerUp);
    document.removeEventListener('wheel', this.onDocumentLayoutWheel);
    document.removeEventListener('click', this.onDocumentLayoutClick, true);
    document.removeEventListener('dblclick', this.onDocumentLayoutDoubleClick, true);
    window.removeEventListener('resize', this.onWindowResize);
    this.survivalHudVisibilityObserver?.disconnect();
    document.body.classList.remove('tlw-hud-layout-edit');
    this.element.remove();
  }

  private readonly onDocumentPointerMove = (event: PointerEvent): void => {
    if (this.survivalHudDrag?.pointerId === event.pointerId) {
      const layout = this.survivalHudLayouts[this.survivalHudDrag.key] ?? {
        x: 0, y: 0, scale: 1,
      };
      layout.x = this.survivalHudDrag.startX +
        event.clientX - this.survivalHudDrag.startClientX;
      layout.y = this.survivalHudDrag.startY +
        event.clientY - this.survivalHudDrag.startClientY;
      this.survivalHudLayouts[this.survivalHudDrag.key] = layout;
      this.applySurvivalHudIslandLayout(this.survivalHudDrag.key);
      return;
    }
    if (this.buildHudDrag?.pointerId === event.pointerId) {
      this.moveBuildHud(
        event.clientX - this.buildHudDrag.offsetX,
        event.clientY - this.buildHudDrag.offsetY,
      );
      return;
    }
    const overWorld = event.target instanceof HTMLCanvasElement;
    const visible = this.buildMode === 'REMOVE' && overWorld;
    this.hammerCursor.classList.toggle('is-hidden', !visible);
    if (!visible) return;
    this.hammerCursor.style.left = `${event.clientX}px`;
    this.hammerCursor.style.top = `${event.clientY}px`;
  };

  private readonly onDocumentPointerDown = (event: PointerEvent): void => {
    if (this.survivalHudLayoutEditing && event.button === 0) {
      const island = (event.target as HTMLElement).closest<HTMLElement>(
        '[data-tlw-hud-layout-key]',
      );
      const key = island?.dataset.tlwHudLayoutKey;
      if (island && key) {
        event.preventDefault();
        event.stopPropagation();
        const layout = this.survivalHudLayouts[key] ?? { x: 0, y: 0, scale: 1 };
        this.survivalHudLayouts[key] = layout;
        this.survivalHudDrag = {
          pointerId: event.pointerId,
          key,
          startClientX: event.clientX,
          startClientY: event.clientY,
          startX: layout.x,
          startY: layout.y,
        };
        island.classList.add('is-hud-layout-dragging');
        return;
      }
    }
    if (
      this.buildMode !== 'REMOVE' ||
      event.button !== 0 ||
      !(event.target instanceof HTMLCanvasElement)
    ) return;
    this.hammerCursor.classList.remove('is-striking');
    void this.hammerCursor.offsetWidth;
    this.hammerCursor.classList.add('is-striking');
  };

  private readonly onDocumentPointerUp = (event: PointerEvent): void => {
    if (this.survivalHudDrag?.pointerId === event.pointerId) {
      this.findSurvivalHudIsland(this.survivalHudDrag.key)
        ?.classList.remove('is-hud-layout-dragging');
      this.survivalHudDrag = undefined;
      this.persistSurvivalHudLayouts();
      return;
    }
    if (this.buildHudDrag?.pointerId !== event.pointerId) return;
    this.buildHudDrag = undefined;
    this.buildPanel.classList.remove('is-dragging');
    this.persistBuildHudLayout();
  };

  private readonly onBuildHudDragStart = (event: PointerEvent): void => {
    if (
      event.button !== 0 ||
      (event.target as HTMLElement).closest('button')
    ) return;
    event.preventDefault();
    const bounds = this.buildPanel.getBoundingClientRect();
    this.buildHudPosition = { x: bounds.left, y: bounds.top };
    this.applyBuildHudLayout();
    this.buildHudDrag = {
      pointerId: event.pointerId,
      offsetX: event.clientX - bounds.left,
      offsetY: event.clientY - bounds.top,
    };
    this.buildPanel.classList.add('is-dragging');
  };

  private readonly onWindowResize = (): void => {
    requestAnimationFrame(() => this.clampAllHudLayouts());
  };

  private readonly onDocumentLayoutWheel = (event: WheelEvent): void => {
    if (!this.survivalHudLayoutEditing) return;
    const island = (event.target as HTMLElement).closest<HTMLElement>(
      '[data-tlw-hud-layout-key]',
    );
    const key = island?.dataset.tlwHudLayoutKey;
    if (!island || !key) return;
    event.preventDefault();
    event.stopPropagation();
    const layout = this.survivalHudLayouts[key] ?? { x: 0, y: 0, scale: 1 };
    layout.scale = Math.min(1.6, Math.max(0.65,
      layout.scale + (event.deltaY < 0 ? 0.08 : -0.08)));
    this.survivalHudLayouts[key] = layout;
    this.applySurvivalHudIslandLayout(key);
    this.persistSurvivalHudLayouts();
  };

  private readonly onDocumentLayoutClick = (event: MouseEvent): void => {
    if (!this.survivalHudLayoutEditing) return;
    if (!(event.target as HTMLElement).closest('[data-tlw-hud-layout-key]')) return;
    event.preventDefault();
    event.stopImmediatePropagation();
  };

  private readonly onDocumentLayoutDoubleClick = (event: MouseEvent): void => {
    if (!this.survivalHudLayoutEditing) return;
    const island = (event.target as HTMLElement).closest<HTMLElement>(
      '[data-tlw-hud-layout-key]',
    );
    const key = island?.dataset.tlwHudLayoutKey;
    if (!island || !key) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    delete this.survivalHudLayouts[key];
    this.applySurvivalHudIslandLayout(key);
    this.persistSurvivalHudLayouts();
  };

  private require<T extends Element = HTMLElement>(selector: string): T {
    const element = this.element.querySelector<T>(selector);
    if (!element) throw new Error(`Missing world crafting HUD element: ${selector}`);
    return element;
  }

  private syncBuildCatalogClass(): void {
    this.buildPanel.classList.toggle('is-catalog-expanded', this.buildCatalogExpanded);
    this.buildPanel.classList.toggle('is-compact', !this.buildCatalogExpanded);
    this.buildPanel.classList.toggle('is-tools-expanded', this.buildToolsExpanded);
    this.buildPanel.classList.toggle('is-tools-compact', !this.buildToolsExpanded);
    this.buildPanel.querySelector('[data-world-craft="catalog"]')
      ?.classList.toggle('is-selected', this.buildCatalogExpanded);
    this.buildPanel.querySelector('[data-world-craft="tools"]')
      ?.classList.toggle('is-selected', this.buildToolsExpanded);
    this.buildPanel.querySelectorAll<HTMLElement>('[data-world-build-category]')
      .forEach((button) => button.classList.toggle(
        'is-selected',
        button.dataset.worldBuildCategory === this.activeBuildCategory,
      ));
    this.buildPanel.querySelectorAll<HTMLElement>('[data-build-category-pieces]')
      .forEach((section) => section.classList.toggle(
        'is-active',
        section.dataset.buildCategoryPieces === this.activeBuildCategory,
      ));
  }

  private setActiveBuildCategory(category: WildernessBuildCategoryId): void {
    this.activeBuildCategory = category;
    this.buildCatalogExpanded = true;
    this.syncBuildCatalogClass();
  }

  private restoreBuildHudLayout(): void {
    try {
      const stored = localStorage.getItem(BUILD_HUD_LAYOUT_STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored) as Partial<BuildHudLayout>;
        if (Number.isFinite(parsed.scale)) {
          this.buildHudScale = Math.min(
            BUILD_HUD_SCALE_MAX,
            Math.max(BUILD_HUD_SCALE_MIN, Number(parsed.scale)),
          );
        }
        if (Number.isFinite(parsed.x) && Number.isFinite(parsed.y)) {
          this.buildHudPosition = { x: Number(parsed.x), y: Number(parsed.y) };
        }
      }
    } catch {
      // Layout preferences are optional; private storage policies must never
      // stop the world-building HUD from opening.
    }
    this.applyBuildHudLayout();
    if (this.buildHudPosition) {
      requestAnimationFrame(() => this.clampAllHudLayouts());
    }
  }

  private persistBuildHudLayout(): void {
    try {
      localStorage.setItem(BUILD_HUD_LAYOUT_STORAGE_KEY, JSON.stringify({
        scale: this.buildHudScale,
        ...this.buildHudPosition,
      } satisfies BuildHudLayout));
    } catch {
      // A non-persistent layout remains fully usable for the current session.
    }
  }

  private applyBuildHudLayout(): void {
    this.buildPanel.style.setProperty('--build-hud-scale', this.buildHudScale.toFixed(2));
    this.buildPanel.classList.toggle('is-user-positioned', Boolean(this.buildHudPosition));
    if (this.buildHudPosition) {
      this.buildPanel.style.left = `${this.buildHudPosition.x}px`;
      this.buildPanel.style.top = `${this.buildHudPosition.y}px`;
      this.buildPanel.style.bottom = 'auto';
    } else {
      this.buildPanel.style.removeProperty('left');
      this.buildPanel.style.removeProperty('top');
      this.buildPanel.style.removeProperty('bottom');
    }
  }

  private moveBuildHud(x: number, y: number, persist = true): void {
    const margin = HUD_VIEWPORT_MARGIN;
    let bounds = this.buildPanel.getBoundingClientRect();
    const availableWidth = Math.max(1, window.innerWidth - margin * 2);
    const availableHeight = Math.max(1, window.innerHeight - margin * 2);
    const fit = Math.min(
      1,
      availableWidth / Math.max(1, bounds.width),
      availableHeight / Math.max(1, bounds.height),
    );
    if (fit < 1) {
      // Responsive CSS normally keeps this panel inside the screen. Retain a
      // final emergency fit for restored desktop layouts opened in a much
      // smaller window, where position clamping alone cannot expose both
      // opposite edges.
      this.buildHudScale = Math.max(0.35, this.buildHudScale * fit);
      this.applyBuildHudLayout();
      bounds = this.buildPanel.getBoundingClientRect();
    }
    const maxX = Math.max(margin, window.innerWidth - margin - bounds.width);
    const maxY = Math.max(margin, window.innerHeight - margin - bounds.height);
    this.buildHudPosition = {
      x: Math.min(maxX, Math.max(margin, x)),
      y: Math.min(maxY, Math.max(margin, y)),
    };
    this.applyBuildHudLayout();
    if (persist) this.persistBuildHudLayout();
  }

  private scaleBuildHud(delta: number): void {
    if (!this.buildHudPosition) {
      const bounds = this.buildPanel.getBoundingClientRect();
      this.buildHudPosition = { x: bounds.left, y: bounds.top };
    }
    this.buildHudScale = Math.min(
      BUILD_HUD_SCALE_MAX,
      Math.max(BUILD_HUD_SCALE_MIN, this.buildHudScale + delta),
    );
    this.applyBuildHudLayout();
    this.moveBuildHud(this.buildHudPosition.x, this.buildHudPosition.y);
  }

  private resetBuildHudLayout(): void {
    this.buildHudScale = 1;
    this.buildHudPosition = undefined;
    this.applyBuildHudLayout();
    this.persistBuildHudLayout();
  }

  private restoreSurvivalHudLayouts(): void {
    try {
      const stored = localStorage.getItem(SURVIVAL_HUD_LAYOUT_STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored) as Record<string, Partial<SurvivalHudIslandLayout>>;
        for (const [key, value] of Object.entries(parsed)) {
          if (
            Number.isFinite(value.x) &&
            Number.isFinite(value.y) &&
            Number.isFinite(value.scale)
          ) {
            this.survivalHudLayouts[key] = {
              x: Number(value.x),
              y: Number(value.y),
              scale: Math.min(1.6, Math.max(0.65, Number(value.scale))),
            };
          }
        }
      }
    } catch {
      this.survivalHudLayouts = {};
    }
    for (const [key, selector] of SURVIVAL_HUD_ISLANDS) {
      const island = document.querySelector<HTMLElement>(selector);
      if (!island) continue;
      island.dataset.tlwHudLayoutKey = key;
      this.applySurvivalHudIslandLayout(key);
    }
    requestAnimationFrame(() => this.clampAllSurvivalHudLayouts());
  }

  private persistSurvivalHudLayouts(): void {
    try {
      localStorage.setItem(
        SURVIVAL_HUD_LAYOUT_STORAGE_KEY,
        JSON.stringify(this.survivalHudLayouts),
      );
    } catch {
      // Per-session layout still works when storage is unavailable.
    }
  }

  private findSurvivalHudIsland(key: string): HTMLElement | undefined {
    const entry = SURVIVAL_HUD_ISLANDS.find(([candidate]) => candidate === key);
    return entry
      ? document.querySelector<HTMLElement>(entry[1]) ?? undefined
      : undefined;
  }

  private applySurvivalHudIslandLayout(key: string): void {
    const island = this.findSurvivalHudIsland(key);
    if (!island) return;
    const layout = this.survivalHudLayouts[key];
    if (!layout) {
      island.style.removeProperty('translate');
      island.style.removeProperty('scale');
      return;
    }
    island.style.translate = `${layout.x.toFixed(1)}px ${layout.y.toFixed(1)}px`;
    island.style.scale = layout.scale.toFixed(2);
    this.clampSurvivalHudIslandLayout(key, island, layout);
  }

  private clampAllHudLayouts(): void {
    if (this.buildHudPosition) {
      const bounds = this.buildPanel.getBoundingClientRect();
      if (bounds.width > 0 && bounds.height > 0) {
        this.moveBuildHud(this.buildHudPosition.x, this.buildHudPosition.y, false);
      }
    }
    this.clampAllSurvivalHudLayouts();
    if (this.buildHudPosition) this.persistBuildHudLayout();
    this.persistSurvivalHudLayouts();
  }

  private clampAllSurvivalHudLayouts(): void {
    for (const key of Object.keys(this.survivalHudLayouts)) {
      this.applySurvivalHudIslandLayout(key);
    }
  }

  /**
   * Layout offsets are stored relative to each island's responsive CSS home.
   * Correcting the rendered rectangle keeps that model intact across desktop,
   * fullscreen and mobile viewport changes.
   */
  private clampSurvivalHudIslandLayout(
    key: string,
    island: HTMLElement,
    layout: SurvivalHudIslandLayout,
  ): void {
    let bounds = island.getBoundingClientRect();
    if (bounds.width <= 0 || bounds.height <= 0) return;
    const style = window.getComputedStyle(island);
    // Sliding drawers such as the closed backpack deliberately live just
    // outside the viewport. Preserve their saved offset while hidden; their
    // class observer clamps it as soon as the drawer becomes visible again.
    if (
      style.display === 'none' || style.visibility === 'hidden' ||
      Number.parseFloat(style.opacity || '1') < 0.05
    ) return;

    const availableWidth = Math.max(1, window.innerWidth - HUD_VIEWPORT_MARGIN * 2);
    const availableHeight = Math.max(1, window.innerHeight - HUD_VIEWPORT_MARGIN * 2);
    const fit = Math.min(
      1,
      availableWidth / bounds.width,
      availableHeight / bounds.height,
    );
    if (fit < 1) {
      // The normal editor range remains 0.65-1.6. A smaller emergency scale is
      // allowed only when the viewport physically cannot contain the island.
      layout.scale = Math.max(0.35, layout.scale * fit);
      island.style.scale = layout.scale.toFixed(2);
      bounds = island.getBoundingClientRect();
    }

    let correctionX = 0;
    let correctionY = 0;
    if (bounds.left < HUD_VIEWPORT_MARGIN) {
      correctionX = HUD_VIEWPORT_MARGIN - bounds.left;
    } else if (bounds.right > window.innerWidth - HUD_VIEWPORT_MARGIN) {
      correctionX = window.innerWidth - HUD_VIEWPORT_MARGIN - bounds.right;
    }
    if (bounds.top < HUD_VIEWPORT_MARGIN) {
      correctionY = HUD_VIEWPORT_MARGIN - bounds.top;
    } else if (bounds.bottom > window.innerHeight - HUD_VIEWPORT_MARGIN) {
      correctionY = window.innerHeight - HUD_VIEWPORT_MARGIN - bounds.bottom;
    }
    if (Math.abs(correctionX) < 0.05 && Math.abs(correctionY) < 0.05) return;

    layout.x += correctionX;
    layout.y += correctionY;
    this.survivalHudLayouts[key] = layout;
    island.style.translate = `${layout.x.toFixed(1)}px ${layout.y.toFixed(1)}px`;
  }

  private setSurvivalHudLayoutEditing(editing: boolean): void {
    this.survivalHudLayoutEditing = editing;
    document.body.classList.toggle('tlw-hud-layout-edit', editing);
    this.element.querySelector('[data-world-craft="layout-hud"]')
      ?.classList.toggle('is-selected', editing);
    if (!editing && this.survivalHudDrag) {
      this.findSurvivalHudIsland(this.survivalHudDrag.key)
        ?.classList.remove('is-hud-layout-dragging');
      this.survivalHudDrag = undefined;
      this.persistSurvivalHudLayouts();
    }
  }

  private renderRuneWheel(): void {
    const host = this.element.querySelector<HTMLElement>('[data-rune-wheel-slots]');
    if (!host) return;
    const slotCount = 10;
    const ringLength = Math.max(slotCount, this.runeWheelIds.length);
    const rotation = ((this.runeWheelRotation % ringLength) + ringLength) % ringLength;
    host.innerHTML = Array.from({ length: slotCount }, (_, slot) => {
      const angle = -Math.PI * 0.5 + slot / slotCount * Math.PI * 2;
      const sourceIndex = (slot - rotation + ringLength) % ringLength;
      const runeId = this.runeWheelIds[sourceIndex];
      const style = `--rune-x:${(Math.cos(angle) * 10.1).toFixed(3)}rem;--rune-y:${(Math.sin(angle) * 10.1).toFixed(3)}rem;--rune-mobile-x:${(Math.cos(angle) * 7.05).toFixed(3)}rem;--rune-mobile-y:${(Math.sin(angle) * 7.05).toFixed(3)}rem;--rune-slot:${slot}`;
      if (!runeId) {
        return `<span class="wilderness-rune-wheel-empty" style="${style}" aria-hidden="true"><i></i></span>`;
      }
      const rune = wildernessRuneDefinition(runeId);
      const selected = rune.id === this.runeWheelSelected ? ' is-selected' : '';
      return `
        <button data-world-rune="${rune.id}" class="wilderness-rune-wheel-choice${selected}" style="${style};--rune-color:#${rune.color.toString(16).padStart(6, '0')}" title="${rune.description}">
          <i>${rune.icon}</i><span>${rune.name}</span>
        </button>`;
    }).join('');
  }
}
