import type { DialogueConversationDefinition } from '../gameplay/dialogue/DialogueTypes';
import type { StoryQuestDefinition } from '../gameplay/emergence/EmergentWorldTypes';
import { createDefaultContentAuthoringDocument } from './ContentAuthoringDefaults';
import { ContentAuthoringStore } from './ContentAuthoringStore';
import type {
  AssetAuthoringRecord,
  AuthoringScenarioDefinition,
  ContentAuthoringDomain,
  IcewayContentAuthoringDocument,
  SurfaceMaterialAuthoringDefinition,
} from './ContentAuthoringTypes';
import { validateContentAuthoringDocument } from './ContentAuthoringValidator';

type AuthoringItem =
  | StoryQuestDefinition
  | DialogueConversationDefinition
  | SurfaceMaterialAuthoringDefinition
  | AuthoringScenarioDefinition
  | AssetAuthoringRecord;

export interface ContentAuthoringWorkbenchOptions {
  readonly onOpenChanged?: (open: boolean) => void;
  readonly onToast?: (message: string) => void;
}

const escapeHtml = (value: string): string => value
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;');

const itemId = (item: AuthoringItem): string => item.id;
const itemName = (item: AuthoringItem): string =>
  'displayName' in item ? item.displayName : item.id;

/**
 * Dev-only data workbench. Runtime registries remain immutable; saved drafts
 * are explicit authoring input for review/import instead of silently changing
 * a running shared world underneath another tester.
 */
export class ContentAuthoringWorkbench {
  private readonly element = document.createElement('section');
  private readonly store = new ContentAuthoringStore();
  private document: IcewayContentAuthoringDocument;
  private domain: ContentAuthoringDomain = 'QUESTS';
  private selectedId?: string;
  private open = false;
  private dirty = false;

  public constructor(
    host: HTMLElement,
    private readonly options: ContentAuthoringWorkbenchOptions = {},
  ) {
    const latest = this.store.loadVersions()[0];
    this.document = latest?.document ?? createDefaultContentAuthoringDocument();
    this.selectedId = this.items()[0]?.id;
    this.element.className = 'content-authoring-workbench is-hidden';
    this.element.setAttribute('aria-label', 'ICEWAY content authoring workbench');
    this.element.innerHTML = `
      <header>
        <div><small>ICEWAY DEV AUTHORING</small><strong>CONTENT WORKBENCH</strong></div>
        <nav>
          <button data-authoring-action="validate">VALIDATE</button>
          <button data-authoring-action="save-version">SAVE VERSION</button>
          <button data-authoring-action="export">EXPORT</button>
          <button data-authoring-action="import">IMPORT</button>
          <button data-authoring-action="close" aria-label="Close content workbench">×</button>
        </nav>
      </header>
      <nav class="content-authoring-tabs">
        <button data-authoring-domain="QUESTS">QUESTS</button>
        <button data-authoring-domain="DIALOGUES">DIALOGUE</button>
        <button data-authoring-domain="MATERIALS">MATERIALS</button>
        <button data-authoring-domain="SCENARIOS">SCENARIOS</button>
        <button data-authoring-domain="ASSETS">ASSETS</button>
      </nav>
      <main>
        <aside data-authoring-list></aside>
        <article>
          <div class="content-authoring-preview" data-authoring-preview></div>
          <label>
            <span>EDITABLE JSON</span>
            <textarea data-authoring-json spellcheck="false"></textarea>
          </label>
          <footer>
            <button data-authoring-action="apply-item">APPLY TO DRAFT</button>
            <small>Runtime stays unchanged until the authored document is reviewed and imported.</small>
          </footer>
        </article>
        <aside class="content-authoring-validation" data-authoring-validation></aside>
      </main>
      <input type="file" accept="application/json,.json" data-authoring-import hidden />
    `;
    host.append(this.element);
    this.element.addEventListener('click', this.onClick);
    this.element.querySelector<HTMLTextAreaElement>('[data-authoring-json]')
      ?.addEventListener('input', () => {
        this.dirty = true;
        this.syncHeader();
      });
    this.element.querySelector<HTMLInputElement>('[data-authoring-import]')
      ?.addEventListener('change', this.onImportChanged);
    this.render();
  }

  public isOpen(): boolean {
    return this.open;
  }

  public setOpen(open: boolean): void {
    if (this.open === open) return;
    this.open = open;
    this.element.classList.toggle('is-hidden', !open);
    this.element.setAttribute('aria-hidden', String(!open));
    this.options.onOpenChanged?.(open);
    if (open) this.render();
  }

  public toggle(): boolean {
    this.setOpen(!this.open);
    return this.open;
  }

  public dispose(): void {
    this.element.removeEventListener('click', this.onClick);
    this.element.querySelector<HTMLInputElement>('[data-authoring-import]')
      ?.removeEventListener('change', this.onImportChanged);
    this.element.remove();
  }

  private items(): readonly AuthoringItem[] {
    if (this.domain === 'QUESTS') return this.document.quests;
    if (this.domain === 'DIALOGUES') return this.document.dialogues;
    if (this.domain === 'MATERIALS') return this.document.materials;
    if (this.domain === 'SCENARIOS') return this.document.scenarios;
    return this.document.assets;
  }

  private selected(): AuthoringItem | undefined {
    return this.items().find((item) => item.id === this.selectedId);
  }

  private render(): void {
    if (!this.items().some((item) => item.id === this.selectedId)) {
      this.selectedId = this.items()[0]?.id;
    }
    this.syncHeader();
    for (const button of this.element.querySelectorAll<HTMLElement>('[data-authoring-domain]')) {
      button.classList.toggle('is-active', button.dataset.authoringDomain === this.domain);
    }
    const list = this.element.querySelector<HTMLElement>('[data-authoring-list]')!;
    list.replaceChildren(...this.items().map((item) => {
      const button = document.createElement('button');
      button.dataset.authoringItem = item.id;
      button.classList.toggle('is-active', item.id === this.selectedId);
      button.innerHTML = `<strong>${escapeHtml(itemName(item))}</strong><small>${escapeHtml(item.id)}</small>`;
      return button;
    }));
    const selected = this.selected();
    const textarea = this.element.querySelector<HTMLTextAreaElement>('[data-authoring-json]')!;
    textarea.value = selected ? JSON.stringify(selected, null, 2) : '';
    this.renderPreview(selected);
    this.renderValidation();
  }

  private syncHeader(): void {
    const title = this.element.querySelector('header strong');
    if (title) title.textContent = this.dirty
      ? 'CONTENT WORKBENCH · UNSAVED DRAFT'
      : 'CONTENT WORKBENCH';
  }

  private renderPreview(item: AuthoringItem | undefined): void {
    const preview = this.element.querySelector<HTMLElement>('[data-authoring-preview]')!;
    if (!item) {
      preview.textContent = 'No authored item selected.';
      return;
    }
    if (this.domain === 'QUESTS') {
      const quest = item as StoryQuestDefinition;
      preview.innerHTML = `<h2>${escapeHtml(quest.displayName)}</h2><p>${escapeHtml(quest.description ?? 'No description')}</p><div class="content-authoring-node-chain">${quest.stages.map((stage, index) => `<span><b>${index + 1}</b>${escapeHtml(stage.displayName)}<small>${escapeHtml(stage.hudGuidance ?? 'No HUD guidance')}</small></span>`).join('<i>→</i>')}</div>`;
      return;
    }
    if (this.domain === 'DIALOGUES') {
      const conversation = item as DialogueConversationDefinition;
      preview.innerHTML = `<h2>${escapeHtml(conversation.id)}</h2><p>${conversation.nodes.length} nodes · ${escapeHtml(conversation.scope)}</p><div class="content-authoring-dialogue-nodes">${conversation.nodes.map((node) => `<span><b>${escapeHtml(node.speakerName)}</b>${escapeHtml(node.text)}<small>${node.choices.length} choice(s)</small></span>`).join('')}</div>`;
      return;
    }
    if (this.domain === 'MATERIALS') {
      const material = item as SurfaceMaterialAuthoringDefinition;
      preview.innerHTML = `<h2>${escapeHtml(material.displayName)}</h2><div class="content-authoring-material" style="--authoring-material:${escapeHtml(material.baseColor)}"><i></i><span>ROUGH ${material.roughness.toFixed(2)}<br>SNOW ${material.snowAffinity.toFixed(2)}<br>HEAT ${material.thermalOutput.toFixed(2)}<br>WIND ${material.windResponse.toFixed(2)}</span></div>`;
      return;
    }
    if (this.domain === 'SCENARIOS') {
      const scenario = item as AuthoringScenarioDefinition;
      preview.innerHTML = `<h2>${escapeHtml(scenario.displayName)}</h2><p>SPAWN · ${escapeHtml(scenario.spawnLocationId)}<br>${escapeHtml(scenario.weather)} · ${escapeHtml(scenario.dayPhase)}</p>`;
      return;
    }
    const asset = item as AssetAuthoringRecord;
    preview.innerHTML = `<h2>${escapeHtml(asset.displayName)}</h2><p>${escapeHtml(asset.category)} · ${escapeHtml(asset.budgetClass)}</p><code>${escapeHtml(asset.suggestedModelUrl)}</code><div class="content-authoring-tags">${asset.tags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join('')}</div>`;
  }

  private renderValidation(): void {
    const host = this.element.querySelector<HTMLElement>('[data-authoring-validation]')!;
    const issues = validateContentAuthoringDocument(this.document);
    const relevant = issues.filter((issue) =>
      issue.domain === this.domain || issue.domain === 'DOCUMENT');
    const errors = issues.filter((issue) => issue.severity === 'ERROR').length;
    const warnings = issues.filter((issue) => issue.severity === 'WARNING').length;
    host.innerHTML = `<header><strong>VALIDATION</strong><small>${errors} errors · ${warnings} warnings</small></header>${relevant.length === 0 ? '<p class="is-valid">No issues in this domain.</p>' : relevant.slice(0, 80).map((issue) => `<p class="is-${issue.severity.toLowerCase()}"><b>${escapeHtml(issue.path)}</b>${escapeHtml(issue.message)}</p>`).join('')}`;
  }

  private applySelectedJson(): void {
    const current = this.selected();
    const textarea = this.element.querySelector<HTMLTextAreaElement>('[data-authoring-json]')!;
    if (!current) return;
    let parsed: AuthoringItem;
    try {
      parsed = JSON.parse(textarea.value) as AuthoringItem;
    } catch {
      this.options.onToast?.('Authoring JSON is not valid. Draft was not changed.');
      return;
    }
    if (!parsed || typeof parsed.id !== 'string' || parsed.id !== current.id) {
      this.options.onToast?.('Keep the stable item ID unchanged while editing a draft.');
      return;
    }
    const replace = <T extends AuthoringItem>(items: readonly T[]): readonly T[] =>
      items.map((item) => item.id === current.id ? parsed as T : item);
    this.document = {
      ...this.document,
      quests: this.domain === 'QUESTS' ? replace(this.document.quests) : this.document.quests,
      dialogues: this.domain === 'DIALOGUES' ? replace(this.document.dialogues) : this.document.dialogues,
      materials: this.domain === 'MATERIALS' ? replace(this.document.materials) : this.document.materials,
      scenarios: this.domain === 'SCENARIOS' ? replace(this.document.scenarios) : this.document.scenarios,
      assets: this.domain === 'ASSETS' ? replace(this.document.assets) : this.document.assets,
    };
    this.dirty = true;
    this.options.onToast?.('Item applied to the local authoring draft.');
    this.render();
  }

  private saveVersion(): void {
    const issues = validateContentAuthoringDocument(this.document);
    if (issues.some((issue) => issue.severity === 'ERROR')) {
      this.options.onToast?.('Fix authoring errors before saving a named version.');
      this.renderValidation();
      return;
    }
    const record = this.store.saveVersion(
      this.document,
      `Borealis content ${new Date().toLocaleString()}`,
    );
    this.dirty = false;
    this.syncHeader();
    this.options.onToast?.(`Saved authoring version ${record.name}.`);
  }

  private download(): void {
    const blob = new Blob([JSON.stringify(this.document, null, 2)], {
      type: 'application/json',
    });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `iceway-content-authoring-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
    document.body.append(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 0);
  }

  private onClick = (event: MouseEvent): void => {
    const target = event.target as HTMLElement;
    const domain = target.closest<HTMLElement>('[data-authoring-domain]')
      ?.dataset.authoringDomain as ContentAuthoringDomain | undefined;
    if (domain) {
      this.domain = domain;
      this.selectedId = this.items()[0]?.id;
      this.render();
      return;
    }
    const selectedId = target.closest<HTMLElement>('[data-authoring-item]')
      ?.dataset.authoringItem;
    if (selectedId) {
      this.selectedId = selectedId;
      this.render();
      return;
    }
    const action = target.closest<HTMLElement>('[data-authoring-action]')
      ?.dataset.authoringAction;
    if (action === 'close') this.setOpen(false);
    else if (action === 'validate') {
      this.renderValidation();
      const issues = validateContentAuthoringDocument(this.document);
      this.options.onToast?.(`Authoring validation: ${issues.length} finding(s).`);
    } else if (action === 'apply-item') this.applySelectedJson();
    else if (action === 'save-version') this.saveVersion();
    else if (action === 'export') this.download();
    else if (action === 'import') {
      this.element.querySelector<HTMLInputElement>('[data-authoring-import]')?.click();
    }
  };

  private onImportChanged = (event: Event): void => {
    const input = event.currentTarget as HTMLInputElement;
    const file = input.files?.[0];
    input.value = '';
    if (!file) return;
    void file.text().then((text) => {
      const parsed = this.store.parseDocument(text);
      if (!parsed) {
        this.options.onToast?.('The selected file is not an ICEWAY authoring document.');
        return;
      }
      this.document = parsed;
      this.dirty = true;
      this.selectedId = this.items()[0]?.id;
      this.options.onToast?.('Authoring document imported as an unsaved draft.');
      this.render();
    });
  };
}
