import { survivalBuildFootprintsOverlap } from '../SurvivalBuildPlacementV2';

export interface SurvivalPlacementVolume {
  x: number; y: number; z: number; yawDegrees: number;
  halfWidth: number; halfDepth: number; height: number;
  segment?: Readonly<{ start:Readonly<{x:number;y:number;z:number}>; end:Readonly<{x:number;y:number;z:number}>; radius:number }>;
}
export interface SurvivalPlacementObstacle extends SurvivalPlacementVolume {
  cylinder?: boolean;
}

/** A thin rotated wall/beam is not a large exclusion circle. Height matters:
 * a floor above a shrub is legal, placing that floor through its trunk isn't. */
export const survivalPlacementHitsObstacle = (
  placement: Readonly<SurvivalPlacementVolume>, obstacle: Readonly<SurvivalPlacementObstacle>,
): boolean => {
  if (Math.min(placement.y + placement.height, obstacle.y + obstacle.height) -
    Math.max(placement.y, obstacle.y) <= 0.025) return false;
  if (placement.segment) {
    const { start, end, radius } = placement.segment;
    const yaw = obstacle.yawDegrees * Math.PI / 180;
    const local = (p: typeof start) => ({ x:(p.x-obstacle.x)*Math.cos(yaw)-(p.z-obstacle.z)*Math.sin(yaw),
      y:p.y-obstacle.y-obstacle.height/2, z:(p.x-obstacle.x)*Math.sin(yaw)+(p.z-obstacle.z)*Math.cos(yaw) });
    const a=local(start), b=local(end);
    let lo=0, hi=1;
    for (const [origin, delta, half] of [[a.y,b.y-a.y,obstacle.height/2+radius],
      ...(!obstacle.cylinder ? [[a.x,b.x-a.x,obstacle.halfWidth+radius],[a.z,b.z-a.z,obstacle.halfDepth+radius]] : [])]) {
      if (Math.abs(delta!)<1e-8) { if (Math.abs(origin!)>half!) return false; }
      else { const p=(-half!-origin!)/delta!, q=(half!-origin!)/delta!; lo=Math.max(lo,Math.min(p,q)); hi=Math.min(hi,Math.max(p,q)); }
      if(lo>hi)return false;
    }
    if (!obstacle.cylinder) return true;
    const dx=b.x-a.x,dz=b.z-a.z;
    const t=Math.max(lo,Math.min(hi,-(a.x*dx+a.z*dz)/Math.max(1e-8,dx*dx+dz*dz)));
    return Math.hypot(a.x+t*dx,a.z+t*dz)<Math.max(obstacle.halfWidth,obstacle.halfDepth)+radius;
  }
  const dx = obstacle.x - placement.x, dz = obstacle.z - placement.z;
  const reach = Math.hypot(placement.halfWidth, placement.halfDepth) +
    Math.hypot(obstacle.halfWidth, obstacle.halfDepth);
  if (Math.abs(dx) > reach || Math.abs(dz) > reach) return false;
  if (!obstacle.cylinder) return survivalBuildFootprintsOverlap(placement, obstacle, 0.015);
  const yaw = placement.yawDegrees * Math.PI / 180;
  const x = dx * Math.cos(yaw) - dz * Math.sin(yaw);
  const z = dx * Math.sin(yaw) + dz * Math.cos(yaw);
  return Math.hypot(Math.max(0, Math.abs(x) - placement.halfWidth),
    Math.max(0, Math.abs(z) - placement.halfDepth)) < Math.max(obstacle.halfWidth, obstacle.halfDepth) - 0.015;
};
