export interface WorldChunkAddress {
  x: number;
  z: number;
}

export interface WorldPartitionDefinition {
  id: string;
  chunkSizeMetres: number;
  minimumChunk: WorldChunkAddress;
  chunkColumns: number;
  chunkRows: number;
}

export const ICEAWAY_TARGET_WORLD_PARTITION: Readonly<WorldPartitionDefinition> =
  Object.freeze({
    id: 'iceaway-world-v1',
    chunkSizeMetres: 128,
    minimumChunk: Object.freeze({ x: 0, z: 0 }),
    chunkColumns: 24,
    chunkRows: 32,
  });

export const worldPartitionChunkCount = (
  partition: Readonly<WorldPartitionDefinition>,
): number =>
  Math.max(0, partition.chunkColumns) *
  Math.max(0, partition.chunkRows);

export const worldPartitionWidthMetres = (
  partition: Readonly<WorldPartitionDefinition>,
): number =>
  partition.chunkSizeMetres * partition.chunkColumns;

export const worldPartitionHeightMetres = (
  partition: Readonly<WorldPartitionDefinition>,
): number =>
  partition.chunkSizeMetres * partition.chunkRows;

export const isValidWorldPartition = (
  partition: Readonly<WorldPartitionDefinition>,
): boolean =>
  partition.id.trim().length > 0 &&
  Number.isFinite(partition.chunkSizeMetres) &&
  partition.chunkSizeMetres > 0 &&
  Number.isInteger(partition.minimumChunk.x) &&
  Number.isInteger(partition.minimumChunk.z) &&
  Number.isInteger(partition.chunkColumns) &&
  partition.chunkColumns > 0 &&
  Number.isInteger(partition.chunkRows) &&
  partition.chunkRows > 0;

export const isChunkInWorldPartition = (
  partition: Readonly<WorldPartitionDefinition>,
  chunk: Readonly<WorldChunkAddress>,
): boolean =>
  Number.isInteger(chunk.x) &&
  Number.isInteger(chunk.z) &&
  chunk.x >= partition.minimumChunk.x &&
  chunk.z >= partition.minimumChunk.z &&
  chunk.x <
    partition.minimumChunk.x + partition.chunkColumns &&
  chunk.z <
    partition.minimumChunk.z + partition.chunkRows;

