/** Visual exhaust clusters only. Sources indoors must feed uncapped room
 * mass before presentation pooling. Grouping never changes heat or fuel. */
export interface SmokeClusterMember {
  readonly key: string; readonly x: number; readonly y: number | undefined; readonly z: number;
  readonly heat: number; readonly emissionScale: number;
  readonly spreadX?: number; readonly spreadZ?: number;
}

export const groupOutdoorStructureSmoke = <T extends SmokeClusterMember>(
  sources: readonly T[], canMerge: (source: T) => boolean,
): (T & SmokeClusterMember)[] => {
  const result: (T & SmokeClusterMember)[] = [];
  const cells = new Map<string, T[]>();
  for (const source of sources) {
    if (!canMerge(source)) { result.push(source); continue; }
    // Stable world addresses: no camera/player-relative regrouping, no giant
    // single plume stretching across an entire connected burning house.
    const key = `${Math.floor(source.x / 4)}:${Math.floor((source.y ?? 0) / 3)}:${Math.floor(source.z / 4)}`;
    const members = cells.get(key) ?? []; members.push(source); cells.set(key, members);
  }
  for (const [key, members] of cells) {
    if (members.length === 1) { result.push(members[0]!); continue; }
    const weight = members.reduce((sum, source) => sum + source.emissionScale, 0);
    const centre = (axis: 'x' | 'y' | 'z') => members.reduce((sum, source) =>
      sum + (source[axis] ?? 0) * source.emissionScale, 0) / Math.max(weight, 0.001);
    const x = centre('x'); const z = centre('z');
    result.push({ ...members[0]!, key: `outdoor-smoke:${key}`, x, y: centre('y'), z,
      heat: members.reduce((sum, source) => sum + source.heat * source.emissionScale, 0) / Math.max(weight, 0.001),
      emissionScale: 4 * (1 - Math.exp(-weight / 4)),
      spreadX: Math.min(2.2, Math.max(...members.map((m) => Math.abs(m.x - x) + (m.spreadX ?? 0)))),
      spreadZ: Math.min(2.2, Math.max(...members.map((m) => Math.abs(m.z - z) + (m.spreadZ ?? 0)))),
    });
  }
  return result;
};
