import { BoxGeometry, Color, DynamicDrawUsage, Group, InstancedMesh, Matrix4, Mesh, MeshStandardMaterial,
  Quaternion, Vector3, type Object3D } from 'three';
import type { BuildDamageCell, BuildDamageProfile, BuildDamageState } from './SurvivalBuildDamage';

const chipLimit=128;
interface Fractured { hidden:Map<Object3D,boolean>; mesh:InstancedMesh; state:BuildDamageState }
interface Chip { x:number;y:number;z:number;vx:number;vy:number;vz:number;ground:number;age:number;size:number;angle:number }

/** Authored-region impostors only for damaged pieces; intact asset-bank meshes
 * stay untouched. One draw per fractured piece, one shared transient chip draw.
 * No per-impact CSG, mutual debris collisions or unbounded physics bodies. */
export class SurvivalBuildDamagePresentation {
  private readonly geometry=new BoxGeometry(1,1,1);
  private readonly fractured=new WeakMap<Object3D,Fractured>();
  readonly chips:InstancedMesh;
  private readonly particles:Array<Chip|undefined>=Array(chipLimit);
  private cursor=0;
  private readonly matrix=new Matrix4();
  private readonly position=new Vector3();
  private readonly scale=new Vector3();
  private readonly quaternion=new Quaternion();
  private readonly axis=new Vector3(.4,.8,.3).normalize();
  private readonly color=new Color();
  constructor() {
    this.chips=new InstancedMesh(this.geometry,new MeshStandardMaterial({color:0x86613d,roughness:1}),chipLimit);
    this.chips.name='Build impact chips · bounded 128';this.chips.instanceMatrix.setUsage(DynamicDrawUsage);
    this.chips.count=chipLimit;this.chips.visible=false;this.chips.frustumCulled=false;
    for(let i=0;i<chipLimit;i++)this.chips.setMatrixAt(i,new Matrix4().makeScale(0,0,0));
  }
  sync(root:Object3D,profile:BuildDamageProfile,state:BuildDamageState|undefined):void {
    const old=this.fractured.get(root);
    if(!state) {
      if(old){for(const [child,visible]of old.hidden){child.visible=visible;delete child.userData.survivalDamageHidden;}old.mesh.removeFromParent();
        (old.mesh.material as MeshStandardMaterial).dispose();this.fractured.delete(root);}
      delete root.userData.survivalDamageActive;return;
    }
    root.userData.survivalDamageActive=true;
    if(old?.state===state){for(const child of old.hidden.keys())child.visible=false;return;}
    let record=old;
    if(!record) {
      let source:MeshStandardMaterial|undefined;
      root.traverse(o=>{if(!source&&o instanceof Mesh&&o.material instanceof MeshStandardMaterial)source=o.material;});
      const material=source?.clone()??new MeshStandardMaterial({color:0x87674d,roughness:1});
      material.userData.survivalBuildOwnedMaterial=true;
      const mesh=new InstancedMesh(this.geometry,material,profile.cells.length);
      mesh.name=`${profile.prefabId}:damage-regions-v1`;mesh.castShadow=true;mesh.receiveShadow=true;mesh.frustumCulled=false;
      const hidden=new Map(root.children.map(child=>[child,child.visible]));
      for(const child of hidden.keys()){child.visible=false;child.userData.survivalDamageHidden=true;}
      root.add(mesh);record={mesh,hidden,state};this.fractured.set(root,record);
    }
    record.state=state;
    for(const c of profile.cells) {
      const alive=(state.health[c.id]??255)>0;
      this.matrix.makeScale(alive?c.width-.006:0,alive?c.height-.004:0,alive?c.depth-.004:0);
      this.matrix.setPosition(c.x,c.y,c.z);record.mesh.setMatrixAt(c.id,this.matrix);
      this.color.setScalar(.45+.55*(state.health[c.id]??255)/255);
      record.mesh.setColorAt(c.id,this.color);
    }
    record.mesh.instanceMatrix.needsUpdate=true;if(record.mesh.instanceColor)record.mesh.instanceColor.needsUpdate=true;
  }
  emit(cell:BuildDamageCell,pose:{x:number;y:number;z:number;yawDegrees:number},ground:number):void {
    const a=pose.yawDegrees*Math.PI/180;
    for(let i=0;i<4;i++) {
      const index=this.cursor++%chipLimit,angle=(index*2.399963)% (Math.PI*2);
      this.particles[index]={x:pose.x+cell.x*Math.cos(a)+cell.z*Math.sin(a),y:pose.y+cell.y,z:pose.z-cell.x*Math.sin(a)+cell.z*Math.cos(a),
        vx:Math.cos(angle)*1.3,vy:1.2+i*.25,vz:Math.sin(angle)*1.3,ground,age:0,
        size:Math.min(.22,cell.width*.28),angle};
    }
  }
  update(seconds:number):void {
    const dt=Math.max(0,Math.min(.05,seconds));let visible=0;
    for(let i=0;i<chipLimit;i++) {
      const p=this.particles[i];if(!p)continue;p.age+=dt;
      if(p.age>=7){this.particles[i]=undefined;this.chips.setMatrixAt(i,this.matrix.makeScale(0,0,0));continue;}
      if(p.y>p.ground+p.size/2){p.vy-=9.8*dt;p.x+=p.vx*dt;p.y=Math.max(p.ground+p.size/2,p.y+p.vy*dt);p.z+=p.vz*dt;p.angle+=dt*4;}
      const size=p.size*Math.min(1,7-p.age);this.position.set(p.x,p.y,p.z);this.scale.set(size,size*.7,size*1.5);
      this.quaternion.setFromAxisAngle(this.axis,p.angle);this.matrix.compose(this.position,this.quaternion,this.scale);
      this.chips.setMatrixAt(i,this.matrix);visible++;
    }
    this.chips.visible=visible>0;if(visible)this.chips.instanceMatrix.needsUpdate=true;
  }
  get activeChips():number{return this.particles.filter(Boolean).length;}
  clear():void{this.particles.fill(undefined);this.chips.visible=false;for(let i=0;i<chipLimit;i++)this.chips.setMatrixAt(i,this.matrix.makeScale(0,0,0));}
  dispose():void{this.chips.removeFromParent();this.geometry.dispose();(this.chips.material as MeshStandardMaterial).dispose();}
}
